window.NCE.booksData[3] = {"id":3,"key":"NCE3","units":[{"id":"b3-u01","book":3,"unit":1,"key":"01","lessonFrom":1,"lessonTo":1,"title":"A Puma at Large","titleZh":"豹子出逃","question":"Where must the puma have come from?","sentences":[{"en":"Pumas are large, cat-like animals which are found in America.","zh":"美洲狮是一种体形似猫的大动物，产于美洲。","t":14.48},{"en":"When reports came into London Zoo that a wild puma had been spotted forty-five miles south of London,","zh":"当伦敦动物园接到报告，说在伦敦南面45英里处发现一头野生美洲狮时，","t":19.17},{"en":"they were not taken seriously.","zh":"他们并没有认真对待。","t":26.27},{"en":"However, as the evidence began to accumulate,","zh":"然而，随着证据的增多，","t":29.15},{"en":"experts from the Zoo felt obliged to investigate,","zh":"动物园的专家们感到有必要进行一番调查，","t":33.21},{"en":"for the descriptions given by people who claimed to have seen the puma were extraordinarily similar.","zh":"因为凡是声称见过美洲狮的人们所描述的情况竟然惊人地相似。","t":37.15},{"en":"The hunt for the puma began in a small village where a woman picking blackberries saw 'a large cat'only five yards away from her.","zh":"搜捕美洲狮的行动是从一个小村庄开始的，在那里，一位采摘黑莓的妇女看见“一只大猫”离她只有五码远。","t":43.86},{"en":"It immediately ran away when she saw it,","zh":"她一看到它，它就立刻跑开了，","t":53.61},{"en":"and experts confirmed that a puma will not attack a human being unless it is cornered.","zh":"专家证实，美洲狮除非被逼入绝境，否则是不会伤人的。","t":56.49},{"en":"The search proved difficult,","zh":"搜寻工作很困难，","t":62.94},{"en":"for the puma was often observed at one place in the morning and at another place twenty miles away in the evening.","zh":"因为常常是早晨在一个地方发现美洲狮，晚上却在20英里以外的另一个地方发现它。","t":65.2},{"en":"Wherever it went, it left behind it a trail of dead deer and small animals like rabbits.","zh":"无论它走到哪里，身后都留下了死鹿及死兔子之类小动物的痕迹。","t":72.58},{"en":"Paw prints were seen in a number of places and puma fur was found clinging to bushes.","zh":"在许多地方都发现了美洲狮的爪印，灌木丛中也发现了美洲狮的毛。","t":79.38},{"en":"Several people complained of 'cat-like noises' at night and a businessman on a fishing trip saw the puma up a tree.","zh":"有几个人抱怨说夜里听到了“像猫叫一样的声音”，一位商人在钓鱼时也看见那只美洲狮爬到了一棵树上。","t":85.39},{"en":"The experts were now fully convinced that the animal was a puma,","zh":"专家们现在完全相信那只动物就是美洲狮，","t":94.26},{"en":"but where had it come from?","zh":"可是它是从哪里来的呢？","t":98.72},{"en":"As no pumas had been reported missing from any zoo in the country,","zh":"由于全国任何一家动物园都没有报道说美洲狮失踪，","t":101.27},{"en":"this one must have been in the possession of a private collector and somehow managed to escape.","zh":"那么这只美洲狮一定是某个私人收藏者喂养的，且不知怎么设法逃脱了。","t":105.55},{"en":"The hunt went on for several weeks,","zh":"搜捕进行了数周，","t":112.16},{"en":"but the puma was not caught.","zh":"但那只美洲狮仍未捕获。","t":114.18},{"en":"It is disturbing to think that a dangerous wild animal is still at large in the quiet countryside.","zh":"想到在这宁静的乡村里，一只危险的野生动物仍然逍遥在外，真令人不安。","t":117.42}],"vocab":[{"word":"puma","phonetic":"/ˈpjuːmə/","meanings":[{"pos":"noun","meaning":"美洲狮","usage":"一种原产于美洲的大型猫科动物，可数名词"}]},{"word":"spot","phonetic":"/spɒt/","meanings":[{"pos":"verb","meaning":"发现；认出","usage":"尤指偶然看到不易察觉的事物，常用搭配：spot sb/sth doing sth"},{"pos":"noun","meaning":"地点；斑点","usage":"表示具体的位置或物体上的点状痕迹"}]},{"word":"accumulate","phonetic":"/əˈkjuːmjəleɪt/","meanings":[{"pos":"verb","meaning":"积累；积聚","usage":"可作及物动词表示“积累某物”，也可作不及物动词表示“逐渐增多”"}]},{"word":"oblige","phonetic":"/əˈblaɪdʒ/","meanings":[{"pos":"verb","meaning":"迫使；使感到必须做","usage":"常用被动结构：be/feel obliged to do sth 表示“觉得有义务做某事”"}]},{"word":"extraordinarily","phonetic":"/ɪkˈstrɔːdnrəli/","meanings":[{"pos":"adverb","meaning":"极其；非常地","usage":"用于修饰形容词或副词，加强程度"}]},{"word":"hunt","phonetic":"/hʌnt/","meanings":[{"pos":"noun","meaning":"搜寻；捕猎","usage":"常用搭配：hunt for sb/sth 表示“搜寻某人/某物”"},{"pos":"verb","meaning":"打猎；搜寻","usage":"可作及物或不及物动词"}]},{"word":"confirm","phonetic":"/kənˈfɜːm/","meanings":[{"pos":"verb","meaning":"证实；确认","usage":"后可接名词、that从句或wh-从句，表示确认某件事的真实性"}]},{"word":"corner","phonetic":"/ˈkɔːnə(r)/","meanings":[{"pos":"verb","meaning":"使走投无路；逼入绝境","usage":"常用被动语态be cornered表示“被逼入绝境”"},{"pos":"noun","meaning":"角落；拐角","usage":"指空间的角落或道路的拐角处"}]},{"word":"trail","phonetic":"/treɪl/","meanings":[{"pos":"noun","meaning":"痕迹；踪迹","usage":"指人或动物经过时留下的一系列痕迹，常用搭配：a trail of sth"}]},{"word":"cling","phonetic":"/klɪŋ/","meanings":[{"pos":"verb","meaning":"紧贴；附着","usage":"不及物动词，过去式和过去分词为clung，常用搭配：cling to sth"}]},{"word":"convince","phonetic":"/kənˈvɪns/","meanings":[{"pos":"verb","meaning":"使确信；使信服","usage":"常用结构：convince sb of sth / convince sb that 从句，被动结构be convinced that表示“坚信…”"}]},{"word":"possession","phonetic":"/pəˈzeʃn/","meanings":[{"pos":"noun","meaning":"拥有；所有物","usage":"常用搭配：in the possession of sb 表示“为某人所有”，in possession of 表示“某人拥有某物”"}]},{"word":"disturbing","phonetic":"/dɪˈstɜːbɪŋ/","meanings":[{"pos":"adjective","meaning":"令人不安的；引起恐慌的","usage":"用于修饰事物，区别于disturbed（感到不安的，修饰人）"}]}],"phrases":[{"phrase":"at large","usage":"表示（危险的人或动物）在逃、逍遥法外；也可表示“总的来说”","examples":[{"en":"The escaped prisoner is still at large.","zh":"逃犯仍然在逃。"},{"en":"People at large are against the new policy.","zh":"总的来说人们反对这项新政策。"}]},{"phrase":"take sth seriously","usage":"认真对待某事，重视某事，否定形式为not take sth seriously","examples":[{"en":"You should take your parents' advice seriously.","zh":"你应该认真对待父母的建议。"},{"en":"His threat was not taken seriously at first.","zh":"一开始没人把他的威胁当回事。"}]},{"phrase":"feel obliged to do sth","usage":"觉得有义务做某事，被迫做某事，强调主观上的责任感","examples":[{"en":"I felt obliged to help him when he was in trouble.","zh":"他遇到困难时我觉得有义务帮他。"},{"en":"The company felt obliged to apologize for the mistake.","zh":"公司觉得有必要为这个错误道歉。"}]},{"phrase":"leave behind","usage":"留下；遗留，宾语可放在leave和behind之间，也可放在behind之后","examples":[{"en":"The thief left behind a wallet at the scene of the crime.","zh":"小偷在犯罪现场留下了一个钱包。"},{"en":"Don't leave your belongings behind when you get off the bus.","zh":"下车时别落下你的随身物品。"}]},{"phrase":"complain of","usage":"抱怨；诉说（病痛、不适等），后接名词或动名词","examples":[{"en":"Many residents complain of the noise from the construction site.","zh":"很多居民抱怨工地的噪音。"},{"en":"The patient complained of having a headache for three days.","zh":"病人诉说自己已经头疼三天了。"}]},{"phrase":"in the possession of","usage":"为某人所有，主语是被拥有的事物，注意和in possession of（主语是拥有者）区分","examples":[{"en":"The rare painting is now in the possession of a private collector.","zh":"这幅罕见的画作现在为一位私人收藏家所有。"},{"en":"The company is in possession of three advanced production lines.","zh":"这家公司拥有三条先进的生产线。"}]},{"phrase":"go on","usage":"持续；继续，此处表示事件持续发生，后可接一段时间","examples":[{"en":"The meeting went on for more than three hours.","zh":"会议持续了三个多小时。"},{"en":"The rain has been going on since this morning.","zh":"雨从今天早上就一直下个不停。"}]}],"grammar":[{"title":"情态动词表推测（对过去的肯定推测）","definition":"用来表示对过去已经发生的事情的确定性推断，说话人对推测的内容有较高的把握","structure":"must have done / must have been doing","usage":"仅用于肯定句中，否定推测用can't have done，疑问推测用can have done","examples":[{"en":"This one must have been in the possession of a private collector and somehow managed to escape.","zh":"这只美洲狮肯定是某个私人收藏家的，不知怎么逃出来了。"},{"en":"The ground is wet. It must have rained last night.","zh":"地面是湿的，昨晚肯定下雨了。"},{"en":"He knew everything about the plan. He must have attended the meeting yesterday.","zh":"他对这个计划了如指掌，他昨天肯定参加了会议。"}]},{"title":"同位语从句","definition":"在复合句中用作同位语的从句，用于解释说明前面名词的具体内容","structure":"抽象名词（news, fact, report, idea, thought等）+ that + 完整陈述语序的从句","usage":"that在同位语从句中不充当任何成分，仅起连接作用，无实际含义，一般不可省略","examples":[{"en":"When reports came into London Zoo that a wild puma had been spotted forty-five miles south of London, they were not taken seriously.","zh":"当伦敦动物园接到报告说，在伦敦以南45英里处发现了一只野生美洲狮时，这些报告并没有受到重视。"},{"en":"The news that our team won the game excited all of us.","zh":"我们队赢了比赛的消息让我们所有人都很兴奋。"},{"en":"There is no doubt that he is the right person for the job.","zh":"毫无疑问他是这份工作的合适人选。"}]},{"title":"让步/原因状语从句的省略","definition":"当状语从句的主语和主句主语一致，且从句谓语含有be动词时，可以省略从句的主语和be动词","structure":"连词（when, while, if, though等）+ 现在分词/过去分词/介词短语/形容词","usage":"现在分词表示和主语是主动关系，过去分词表示和主语是被动关系","examples":[{"en":"The hunt for the puma began in a small village where a woman picking blackberries saw 'a large cat' only five yards away from her.","zh":"搜寻美洲狮的工作是从一个小村庄开始的，那里有一位采黑莓的妇女看见“一只大猫”离她只有五码远。（此处picking blackberries是定语从句who was picking blackberries的省略）"},{"en":"When crossing the street, you should look both sides.","zh":"过马路的时候你应该两边都看看。（省略了you are）"},{"en":"If given more time, I will finish the task better.","zh":"如果给我更多时间，我会把任务完成得更好。（省略了I am）"}]}],"patterns":[{"pattern":"It is + 形容词 + to think that...","explanation":"","original":{"en":"It is disturbing to think that a dangerous wild animal is still at large in the quiet countryside.","zh":"想到在宁静的乡村里有一头危险的野兽仍然在逃，就令人不安。"},"examples":[{"en":"It is exciting to think that we will go to the beach for vacation next week.","zh":"想到我们下周要去海边度假，就很令人兴奋。"},{"en":"It is disappointing to think that he failed the exam again after studying so hard.","zh":"想到他这么努力学习还是考试不及格，就很令人失望。"}]},{"pattern":"However, as sth began to accumulate, sb felt obliged to do sth, for...","explanation":"","original":{"en":"However, as the evidence began to accumulate, experts from the Zoo felt obliged to investigate, for the descriptions given by people who claimed to have seen the puma were extraordinarily similar.","zh":"然而，随着证据越来越多，动物园的专家们感到有必要进行调查，因为凡是声称见到过美洲狮的人们所描述的情况出奇地相似。"},"examples":[{"en":"However, as the complaints from customers began to accumulate, the company felt obliged to recall the product, for the design flaw had caused several safety accidents.","zh":"然而，随着消费者的投诉越来越多，公司感到有必要召回产品，因为这个设计缺陷已经造成了多起安全事故。"},{"en":"However, as the waste in the river began to accumulate, the local residents felt obliged to report to the environmental department, for the water had become too dirty to use.","zh":"然而，随着河里的垃圾越积越多，当地居民觉得有必要向环保部门举报，因为水已经脏得没法用了。"}]},{"pattern":"The search/problem proved + 形容词, for...","explanation":"","original":{"en":"The search proved difficult, for the puma was often observed at one place in the morning and at another place twenty miles away in the evening.","zh":"搜寻工作很困难，因为常常是早晨在甲地发现那只美洲狮，晚上却在20英里外的乙地出现。"},"examples":[{"en":"The project proved challenging, for we lacked the professional technology and enough funding.","zh":"这个项目很有挑战性，因为我们缺少专业技术和足够的资金。"},{"en":"The final exam proved easy, for all the questions were from the exercises we had done before.","zh":"期末考试很简单，因为所有题目都来自我们之前做过的练习。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“紧贴；附着” 对应的单词是？","hint":"verb · /klɪŋ/","options":["underestimate","overbalance","cling","surgeon"],"answer":2,"explain":"cling · /klɪŋ/ · verb · 紧贴；附着。不及物动词，过去式和过去分词为clung，常用搭配：cling to sth","source":{"kind":"vocab","word":"cling"},"id":"b3-u01-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：证实；确认","hint":"/kənˈfɜːm/ · verb","answer":"confirm","placeholder":"输入英文单词","explain":"confirm · /kənˈfɜːm/ · verb · 证实；确认。后可接名词、that从句或wh-从句，表示确认某件事的真实性","source":{"kind":"vocab","word":"confirm"},"id":"b3-u01-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The rare painting is now _____ a private collector.","hint":"这幅罕见的画作现在为一位私人收藏家所有。","answer":"in the possession of","placeholder":"输入缺失的短语","explain":"in the possession of：为某人所有，主语是被拥有的事物，注意和in possession of（主语是拥有者）区分（这幅罕见的画作现在为一位私人收藏家所有。）","source":{"kind":"phrase","phrase":"in the possession of"},"id":"b3-u01-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ reports came into London Zoo that a wild puma had been spotted forty-five miles south of London,","hint":"当伦敦动物园接到报告，说在伦敦南面45英里处发现一头野生美洲狮时，","answer":"When","placeholder":"输入缺失的单词","explain":"When reports came into London Zoo that a wild puma had been spotted forty-five miles south of London, — 当伦敦动物园接到报告，说在伦敦南面45英里处发现一头野生美洲狮时，","source":{"kind":"sentence","en":"When reports came into London Zoo that a wild puma had been spotted forty-five miles south of London,"},"id":"b3-u01-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“在复合句中用作同位语的从句，用于解释说明前面名词的具体内容” 描述的是哪个语法点？","hint":"抽象名词（news, fact, report, idea, thought等）+ that + 完整陈述语序的从句","options":["同位语从句","介词+关系代词引导的定语从句","并列结构中的省略","百分数表达在描述数据中的应用"],"answer":0,"explain":"同位语从句：抽象名词（news, fact, report, idea, thought等）+ that + 完整陈述语序的从句：that在同位语从句中不充当任何成分，仅起连接作用，无实际含义，一般不可省略","source":{"kind":"grammar","title":"同位语从句"},"id":"b3-u01-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAs no pumas had been reported missing from any zoo in the country,","hint":"","options":["由于全国任何一家动物园都没有报道说美洲狮失踪，","果不其然，拉斯特斯那天晚上7点准时回来了。","记者们不停地要求采访，所以不得不雇佣律师在新闻发布会上担任这个家庭的发言人。","我应该能看到山谷里的农场和小屋，"],"answer":0,"explain":"As no pumas had been reported missing from any zoo in the country, — 由于全国任何一家动物园都没有报道说美洲狮失踪，","source":{"kind":"sentence","en":"As no pumas had been reported missing from any zoo in the country,"},"id":"b3-u01-q06"}]},{"id":"b3-u02","book":3,"unit":2,"key":"02","lessonFrom":2,"lessonTo":2,"title":"Thirteen Equals One","titleZh":"十三等于一","question":"Was the vicar pleased that the clock was striking? Why?","sentences":[{"en":"Our vicar is always raising money for one cause or another,","zh":"我们的牧师总是为这样或那样的缘故筹款，","t":16.63},{"en":"but he has never managed to get enough money to have the church clock repaired.","zh":"但他从未筹集到足够的钱来修理教堂的时钟。","t":20.87},{"en":"The big clock which used to strike the hours day and night was damaged many years ago and has been silent ever since.","zh":"那座日夜报时的大钟多年前损坏了，从那以后就一直沉默不语。","t":26.49},{"en":"One night, however, our vicar woke up with a start: the clock was striking the hours!","zh":"然而，一天晚上，我们的牧师突然惊醒：钟正在报时！","t":36.38},{"en":"Looking at his watch, he saw that it was one o'clock,","zh":"他看了看表，发现是一点钟，","t":43.48},{"en":"but the bell struck thirteen times before it stopped.","zh":"但钟声响了十三次才停下来。","t":47.38},{"en":"Armed with a torch, the vicar went up into the clock tower to see what was going on.","zh":"牧师拿着手电筒，爬上钟楼，想看看发生了什么事。","t":51.91},{"en":"In the torchlight, he caught sight of a figure whom he immediately recognized as Bill Wilkins, our local grocer.","zh":"在手电筒的光束中，他看到一个人影，他立刻认出那是比尔·威尔金斯，我们当地的杂货商。","t":58.03},{"en":"'Whatever are you doing up here Bill?' asked the vicar in surprise.","zh":"“比尔，你在这上面做什么？”牧师惊讶地问道。","t":66.24},{"en":"'I'm trying to repair the bell, ' answered Bill.","zh":"“我正在努力修理钟，”比尔回答道。","t":71.57},{"en":"'I've been coming up here night after night for weeks now.","zh":"“我来这里已经好几个星期了，夜复一夜。","t":75.23},{"en":"You see, I was hoping to give you a surprise.'","zh":"你看，我本来希望能给你一个惊喜。”","t":78.64},{"en":"'You certainly did give me a surprise!' said the vicar.","zh":"“你确实给了我一个惊喜！”牧师说。","t":82.4},{"en":"'You've probably woken up everyone in the village as well.","zh":"“你可能也把村里所有人都吵醒了。","t":85.82},{"en":"Still, I'm glad the bell is working again.'","zh":"不过，我很高兴钟又响了。”","t":89.51},{"en":"'That's the trouble, vicar, 'answered Bill. 'It's working all right,","zh":"“问题就在这儿，牧师，”比尔回答道。“它确实在响，","t":93.01},{"en":"but I'm afraid that at one o'clock it will strike thirteen times and there's nothing I can do about it.'","zh":"但我担心一点钟的时候它会响十三次，我对此束手无策。”","t":98.07},{"en":"'We'll get used to that, Bill, 'said the vicar.","zh":"“我们会习惯的，比尔，”牧师说。","t":105.01},{"en":"'Thirteen is not as good as one, but it's better than nothing.","zh":"“十三次不如一次好，但总比没有好。","t":108.05},{"en":"Now let's go downstairs and have a cup of tea.'","zh":"现在我们下去喝杯茶吧。”","t":112.95}],"vocab":[{"word":"equal","phonetic":"/ˈiːkwəl/","meanings":[{"pos":"verb","meaning":"等于；等同于","usage":"表示数量、价值等方面的对等，主语和宾语通常为同等性质的事物"},{"pos":"adjective","meaning":"相等的；平等的","usage":"描述事物在大小、数量、权利等方面一致的状态"}]},{"word":"vicar","phonetic":"/ˈvɪkə(r)/","meanings":[{"pos":"noun","meaning":"教区牧师，教区神父","usage":"指英国国教中负责一个教区的神职人员"}]},{"word":"strike","phonetic":"/straɪk/","meanings":[{"pos":"verb","meaning":"（钟）敲，报时","usage":"用于描述时钟整点敲响报时的动作"},{"pos":"verb","meaning":"撞击；打击","usage":"表示用力击打某物的动作"},{"pos":"verb","meaning":"罢工","usage":"指劳动者为争取权益集体停止工作"}]},{"word":"cause","phonetic":"/kɔːz/","meanings":[{"pos":"noun","meaning":"事业；（公益）活动","usage":"指人们支持并为之努力的目标或社会运动"},{"pos":"noun","meaning":"原因，起因","usage":"表示导致某个结果的缘由"}]},{"word":"damage","phonetic":"/ˈdæmɪdʒ/","meanings":[{"pos":"verb","meaning":"损坏，破坏","usage":"指对物品、设施等造成损害，使其功能或外观受损"},{"pos":"noun","meaning":"损坏，损失","usage":"表示被损害的状态或造成的损失"}]},{"word":"silent","phonetic":"/ˈsaɪlənt/","meanings":[{"pos":"adjective","meaning":"无声的，沉默的","usage":"可描述物体不发出声音，也可描述人不说话的状态"}]},{"word":"start","phonetic":"/stɑːt/","meanings":[{"pos":"noun","meaning":"惊醒，惊跳","usage":"指因惊讶、害怕等突然产生的身体抖动反应，常与with a start搭配"},{"pos":"verb","meaning":"开始；启动","usage":"表示某个动作或事件的开端"}]},{"word":"torch","phonetic":"/tɔːtʃ/","meanings":[{"pos":"noun","meaning":"手电筒；火把","usage":"英式英语中常用指手电筒，美式英语对应flashlight"}]},{"word":"tower","phonetic":"/ˈtaʊə(r)/","meanings":[{"pos":"noun","meaning":"塔；塔楼","usage":"指高耸的建筑结构，如钟楼、灯塔等"}]},{"word":"grocer","phonetic":"/ˈɡrəʊsə(r)/","meanings":[{"pos":"noun","meaning":"食品杂货商","usage":"指经营食品、日常用品等杂货的店铺老板或店员"}]},{"word":"repair","phonetic":"/rɪˈpeə(r)/","meanings":[{"pos":"verb","meaning":"修理，修复","usage":"指对损坏的物品、设备进行修理使其恢复正常功能"},{"pos":"noun","meaning":"修理，修补","usage":"表示修理的行为或过程"}]},{"word":"surprise","phonetic":"/səˈpraɪz/","meanings":[{"pos":"noun","meaning":"惊喜，惊讶","usage":"指意想不到的事或意外的情绪"},{"pos":"verb","meaning":"使惊讶，使意外","usage":"表示某事让人感到出乎意料"}]},{"word":"recognize","phonetic":"/ˈrekəɡnaɪz/","meanings":[{"pos":"verb","meaning":"认出，识别","usage":"指认出曾经见过或知道的人或事物"}]}],"phrases":[{"phrase":"raise money","usage":"意为“筹钱，募集资金”，宾语后可接for引出筹款的目的对象","examples":[{"en":"We are raising money for the children in poor areas.","zh":"我们正在为贫困地区的儿童筹款。"},{"en":"The organization raised over 1 million yuan for disaster relief last year.","zh":"该组织去年为救灾募集了超过100万元资金。"}]},{"phrase":"used to do","usage":"表示过去常常做某事（现在已经不做了），暗指过去和现在的对比","examples":[{"en":"I used to swim every week when I was a student.","zh":"我上学的时候常常每周都去游泳。"},{"en":"This park used to be a wasteland ten years ago.","zh":"这个公园十年前曾是一片荒地。"}]},{"phrase":"day and night","usage":"意为“日日夜夜，昼夜不停”，在句中作时间状语，描述动作持续的状态","examples":[{"en":"The nurses took care of the patient day and night until he recovered.","zh":"护士们日夜照顾这位病人，直到他康复。"},{"en":"The construction site works day and night to finish the project on time.","zh":"工地昼夜施工，以按时完成项目。"}]},{"phrase":"wake up with a start","usage":"意为“猛然惊醒，突然惊醒”，强调惊醒的突发性","examples":[{"en":"I woke up with a start when the thunder struck last night.","zh":"昨晚打雷的时候我猛然惊醒了。"},{"en":"She woke up with a start, realizing she was late for the meeting.","zh":"她猛地惊醒，意识到自己开会要迟到了。"}]},{"phrase":"armed with","usage":"意为“装备有，携带”，属于过去分词短语作状语，说明主语的状态","examples":[{"en":"Armed with a map and a compass, the hikers set off into the mountain.","zh":"背着地图和指南针，徒步旅行者们出发进山了。"},{"en":"Armed with all the evidence, he was confident he would win the case.","zh":"掌握了所有证据，他有信心赢得这场官司。"}]},{"phrase":"catch sight of","usage":"意为“看见，瞥见”，强调偶然看到的动作","examples":[{"en":"I caught sight of an old friend in the crowd when I was shopping yesterday.","zh":"我昨天购物的时候在人群里瞥见了一位老朋友。"},{"en":"The little girl caught sight of a cat running through the garden.","zh":"小女孩看见一只猫从花园里跑过。"}]},{"phrase":"night after night","usage":"意为“一夜又一夜，连续很多夜晚”，强调动作的重复性和持续性","examples":[{"en":"He came to the studio night after night to practice his speech for the contest.","zh":"他连续很多个晚上来到演播室练习比赛的演讲。"},{"en":"Night after night, the mother sat by the sick child's bed.","zh":"一夜又一夜，这位母亲守在生病的孩子床边。"}]},{"phrase":"get used to","usage":"意为“习惯于”，to是介词，后面接名词、代词或动名词","examples":[{"en":"It took me a month to get used to the life in the new city.","zh":"我花了一个月才习惯新城市的生活。"},{"en":"My grandparents have got used to living in the countryside.","zh":"我的祖父母已经习惯了在农村生活。"}]}],"grammar":[{"title":"现在进行时表感情色彩","definition":"现在进行时与always, constantly, continually等频率副词连用时，不表示正在进行的动作，而是表达说话者的某种感情，如赞赏、抱怨、厌烦等","structure":"主语 + be + always/constantly + doing sth","usage":"用于突出说话人对某个重复发生的动作的主观态度","examples":[{"en":"Our vicar is always raising money for one cause or another.","zh":"我们教区的牧师总是在为各种各样的事业筹钱。"},{"en":"He is always helping others when they are in trouble.","zh":"别人有困难的时候他总是出手帮忙，真热心。"},{"en":"My deskmate is always talking in class, which annoys the teacher a lot.","zh":"我的同桌总在课上说话，这让老师很生气。"}]},{"title":"现在完成进行时","definition":"表示动作从过去某一时间开始，一直持续到现在，并且可能还会继续下去，强调动作的持续性和重复性","structure":"主语 + have/has + been + doing sth","usage":"常和表示一段时间的状语连用，如for weeks, since last year, these days等","examples":[{"en":"I've been coming up here night after night for weeks now.","zh":"我一连好几个星期每天晚上都到这儿来。"},{"en":"I have been learning English for more than ten years.","zh":"我学英语已经有十多年了。"},{"en":"It has been raining for three days. When will it stop?","zh":"雨已经下了三天了，什么时候才会停啊？"}]},{"title":"非限定性定语从句","definition":"对先行词进行补充说明，去掉之后不影响主句的完整意思，和主句之间常用逗号隔开","structure":"先行词 + which/who/whom/whose + 从句","usage":"用于提供额外的信息，修饰整个主句或者主句中的某个名词","examples":[{"en":"The big clock which used to strike the hours day and night was damaged many years ago.","zh":"那座过去昼夜都报时的大钟很多年前就被损坏了。"},{"en":"The book, which I bought last week, is very popular among young people.","zh":"那本书我上周买的，在年轻人中非常受欢迎。"},{"en":"Mr. Smith, who used to work in our company, has moved to Shanghai.","zh":"史密斯先生过去在我们公司工作，他已经搬去上海了。"}]}],"patterns":[{"pattern":"主语 + have never managed to do sth","explanation":"","original":{"en":"He has never managed to get enough money to have the church clock repaired.","zh":"他一直没能筹到足够的钱来修理教堂的钟。"},"examples":[{"en":"I have never managed to finish reading this novel though I have tried many times.","zh":"尽管我试了很多次，还是没能读完这本小说。"},{"en":"The little boy has never managed to ride a bike without his father's help.","zh":"没有爸爸的帮忙，这个小男孩一直学不会骑自行车。"}]},{"pattern":"..., however, + 句子","explanation":"","original":{"en":"One night, however, our vicar woke up with a start: the clock was striking the hours!","zh":"然而有一天晚上，牧师突然惊醒：钟竟然在报时！"},"examples":[{"en":"Everyone thought the team would lose the game. They won, however, in the last minute.","zh":"所有人都觉得这支队伍会输掉比赛，然而他们在最后一分钟赢了。"},{"en":"The task is very difficult. I am confident, however, that we can complete it on time.","zh":"这项任务非常艰巨，不过我有信心我们能按时完成。"}]},{"pattern":"主语 + be afraid that + 从句","explanation":"","original":{"en":"I'm afraid that at one o'clock it will strike thirteen times and there's nothing I can do about it.","zh":"恐怕到一点钟的时候它还是会敲13下，我实在没办法解决这个问题。"},"examples":[{"en":"I'm afraid that I can't come to your birthday party this weekend because I have an exam.","zh":"恐怕我这周末没法参加你的生日派对了，因为我有一场考试。"},{"en":"She is afraid that her parents will be worried if she goes home too late.","zh":"她担心如果回家太晚的话父母会担心。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“教区牧师，教区神父” 对应的单词是？","hint":"noun · /ˈvɪkə(r)/","options":["dismantle","vicar","procession","performance"],"answer":1,"explain":"vicar · /ˈvɪkə(r)/ · noun · 教区牧师，教区神父。指英国国教中负责一个教区的神职人员","source":{"kind":"vocab","word":"vicar"},"id":"b3-u02-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：事业；（公益）活动","hint":"/kɔːz/ · noun","answer":"cause","placeholder":"输入英文单词","explain":"cause · /kɔːz/ · noun · 事业；（公益）活动。指人们支持并为之努力的目标或社会运动","source":{"kind":"vocab","word":"cause"},"id":"b3-u02-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The nurses took care of the patient _____ until he recovered.","hint":"护士们日夜照顾这位病人，直到他康复。","answer":"day and night","placeholder":"输入缺失的短语","explain":"day and night：意为“日日夜夜，昼夜不停”，在句中作时间状语，描述动作持续的状态（护士们日夜照顾这位病人，直到他康复。）","source":{"kind":"phrase","phrase":"day and night"},"id":"b3-u02-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：but he has never managed to get _____ money to have the church clock repaired.","hint":"但他从未筹集到足够的钱来修理教堂的时钟。","answer":"enough","placeholder":"输入缺失的单词","explain":"but he has never managed to get enough money to have the church clock repaired. — 但他从未筹集到足够的钱来修理教堂的时钟。","source":{"kind":"sentence","en":"but he has never managed to get enough money to have the church clock repaired."},"id":"b3-u02-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“现在进行时与always, constantly, continually等频率副词连用时，不表示正在进行的动作，而是表达说话者的某种感情，如赞赏、抱怨、厌烦等” 描述的是哪个语法点？","hint":"主语 + be + always/constantly + doing sth","options":["现在进行时表感情色彩","Though / Although + 从句（让步状语从句）","What引导的特殊疑问句","被动语态 (Passive Voice)"],"answer":0,"explain":"现在进行时表感情色彩：主语 + be + always/constantly + doing sth：用于突出说话人对某个重复发生的动作的主观态度","source":{"kind":"grammar","title":"现在进行时表感情色彩"},"id":"b3-u02-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\n'That's the trouble, vicar, 'answered Bill. 'It's working all right,","hint":"","options":["但他再次不幸。","“问题就在这儿，牧师，”比尔回答道。“它确实在响，","五天后，当一艘过往的油轮救起他们时，两人都真诚地感到遗憾，因为他们不得不离开。","他们无视社会习俗，却没意识到自己在做任何非凡的事情。"],"answer":1,"explain":"'That's the trouble, vicar, 'answered Bill. 'It's working all right, — “问题就在这儿，牧师，”比尔回答道。“它确实在响，","source":{"kind":"sentence","en":"'That's the trouble, vicar, 'answered Bill. 'It's working all right,"},"id":"b3-u02-q06"}]},{"id":"b3-u03","book":3,"unit":3,"key":"03","lessonFrom":3,"lessonTo":3,"title":"An Unknown Goddess","titleZh":"一个不知名的女神","question":"How did the archaeologists know that the statue was a goddess?","sentences":[{"en":"Some time ago, an interesting discovery was made by archaeologists on the Aegean island of Kea.","zh":"不久前，考古学家在爱琴海的凯阿岛上有一项有趣的发现。","t":16.23},{"en":"An American team explored a temple which stands in an ancient city on the promontory of Ayia Irini.","zh":"一个美国小组考察了在阿伊亚伊里尼海角的一座古城中的一座神庙。","t":24.33},{"en":"The city at one time must have been prosperous, for it enjoyed a high level of civilization.","zh":"这座城市曾一度繁荣，因为它享有高度的文明。","t":32.71},{"en":"Houses -- often three storeys high -- were built of stone.","zh":"房屋——通常有三层楼高——是用石头建造的。","t":38.98},{"en":"They had large rooms with beautifully decorated walls.","zh":"它们有大房间，墙壁装饰精美。","t":44.07},{"en":"The city was even equipped with a drainage system, for a great many clay pipes were found beneath the narrow streets.","zh":"这座城市甚至配备了排水系统，因为在狭窄的街道下发现了大量的陶土管道。","t":48.39},{"en":"The temple which the archaeologists explored was used as a place of worship from the fifteenth century B.C. until Roman times.","zh":"考古学家考察的神庙从公元前15世纪一直到罗马时代都被用作礼拜场所。","t":57.46},{"en":"In the most sacred room of the temple, clay fragments of fifteen statues were found.","zh":"在神庙最神圣的房间里，发现了15尊雕像的陶土碎片。","t":67.15},{"en":"Each of these represented a goddess and had, at one time, been painted.","zh":"每一尊都代表一位女神，并且曾被涂上颜色。","t":74.21},{"en":"The body of one statue was found among remains dating from the 15th century B.C.","zh":"一尊雕像的身体是在可追溯到公元前15世纪的遗迹中发现的。","t":80.18},{"en":"Its missing head happened to be among remains of the fifth century B.C.","zh":"它缺失的头部碰巧在公元前5世纪的遗迹中。","t":87.02},{"en":"This head must have been found in Classical times and carefully preserved.","zh":"这个头部一定是在古典时期被发现并精心保存下来的。","t":92.8},{"en":"It was very old and precious even then.","zh":"即使在当时，它也非常古老而珍贵。","t":97.84},{"en":"When the archaeologists reconstructed the fragments, they were amazed to find that the goddess turned out to be a very modern-looking woman.","zh":"当考古学家重组这些碎片时，他们惊讶地发现这位女神竟然是一个看起来非常现代的女人。","t":101.87},{"en":"She stood three feet high and her hands rested on her hips.","zh":"她身高三英尺，双手叉腰。","t":111.07},{"en":"She was wearing a full-length skirt which swept the ground.","zh":"她穿着一件拖地的长裙。","t":115.76},{"en":"Despite her great age, she was very graceful indeed, but, so far, the archaeologists have been unable to discover her identity.","zh":"尽管她年代久远，但确实非常优雅，不过到目前为止，考古学家们还未能发现她的身份。","t":119.95}],"vocab":[{"word":"goddess","phonetic":"/ˈɡɒdes/","meanings":[{"pos":"noun","meaning":"女神；受崇敬的女性","usage":"对应阳性形式为god，可指神话中的女神，也可用于赞美极具魅力的女性"}]},{"word":"archaeologist","phonetic":"/ˌɑːkiˈɒlədʒɪst/","meanings":[{"pos":"noun","meaning":"考古学家","usage":"指从事考古研究、挖掘古代遗迹的专业人员，相关学科为archaeology（考古学）"}]},{"word":"Aegean","phonetic":"/iːˈdʒiːən/","meanings":[{"pos":"adjective","meaning":"爱琴海的","usage":"专有形容词，常与sea搭配构成the Aegean Sea（爱琴海），指地中海东部的海域"}]},{"word":"promontory","phonetic":"/ˈprɒməntri/","meanings":[{"pos":"noun","meaning":"海角，岬","usage":"指深入海洋或湖泊的狭长高地，地理场景常用术语"}]},{"word":"prosperous","phonetic":"/ˈprɒspərəs/","meanings":[{"pos":"adjective","meaning":"繁荣的，兴旺的","usage":"可用来描述城市、国家、经济或者人的事业发展良好，名词形式为prosperity"}]},{"word":"civilization","phonetic":"/ˌsɪvəlaɪˈzeɪʃn/","meanings":[{"pos":"noun","meaning":"文明；文明社会","usage":"指人类社会发展到较高阶段的状态，也可指特定的文明体系，如ancient civilization（古代文明）"}]},{"word":"storey","phonetic":"/ˈstɔːri/","meanings":[{"pos":"noun","meaning":"楼层","usage":"英式拼写，美式拼写为story，用于描述建筑的层数，如a three-storey house（一栋三层的房子）"}]},{"word":"drainage","phonetic":"/ˈdreɪnɪdʒ/","meanings":[{"pos":"noun","meaning":"排水；排水系统","usage":"可指排水的动作，也可指整套排水设施，如drainage system（排水系统）"}]},{"word":"clay","phonetic":"/kleɪ/","meanings":[{"pos":"noun","meaning":"黏土，陶土","usage":"可塑的泥土材料，常用于制作陶器、砖块等，如clay pot（陶罐）"}]},{"word":"worship","phonetic":"/ˈwɜːʃɪp/","meanings":[{"pos":"noun","meaning":"崇拜，敬奉；礼拜","usage":"指对神、宗教人物的敬拜，也可指对某人/物的极度崇拜，place of worship即宗教礼拜场所"},{"pos":"verb","meaning":"崇拜，敬奉","usage":"后可直接接崇拜的对象，如worship the gods"}]},{"word":"sacred","phonetic":"/ˈseɪkrɪd/","meanings":[{"pos":"adjective","meaning":"神圣的，宗教的；受崇敬的","usage":"常用来描述与宗教相关、被认为不可侵犯的事物，如sacred place（圣地）"}]},{"word":"fragment","phonetic":"/ˈfræɡmənt/","meanings":[{"pos":"noun","meaning":"碎片，片段","usage":"指物体破碎后的小块，或者信息、文艺作品的片段，如clay fragment（陶片）"}]},{"word":"reconstruct","phonetic":"/ˌriːkənˈstrʌkt/","meanings":[{"pos":"verb","meaning":"修复，重建；重构","usage":"可指修复破损的物体，也可指根据线索还原事件过程，前缀re-表示“重新”"}]},{"word":"graceful","phonetic":"/ˈɡreɪsfl/","meanings":[{"pos":"adjective","meaning":"优雅的，优美的","usage":"可形容人的姿态、动作优美，也可形容事物的形式雅致，名词形式为grace"}]},{"word":"identity","phonetic":"/aɪˈdentəti/","meanings":[{"pos":"noun","meaning":"身份；特征","usage":"用于表明某人/物是谁、是什么的信息，如identity card（身份证）"}]}],"phrases":[{"phrase":"at one time","usage":"用于描述过去某个时期曾经发生的情况，相当于“曾经，一度”，常与过去时态搭配","examples":[{"en":"The city at one time must have been prosperous, for it enjoyed a high level of civilization.","zh":"这座古城肯定一度很繁荣，因为它曾享有高度的文明。"},{"en":"At one time, I lived in the countryside, so I know a lot about farm work.","zh":"我曾经在农村住过，所以我很了解农活。"}]},{"phrase":"be equipped with","usage":"表示“配备有，装备有”，主语通常为地点、机构、设备等，后接配备的具体物品","examples":[{"en":"The city was even equipped with a drainage system, for a great many clay pipes were found beneath the narrow streets.","zh":"这座城市甚至还敷设了排水系统，因为在狭窄的街道底下发现了许许多多陶土制作的排水管道。"},{"en":"The new gym is equipped with all the latest fitness equipment.","zh":"这个新健身房配备了所有最新的健身器材。"}]},{"phrase":"date from","usage":"表示“追溯到，始于（某个时期）”，主语通常为古物、遗迹、传统等，无被动形式，常用一般现在时","examples":[{"en":"The body of one statue was found among remains dating from the 15th century B.C.","zh":"其中一尊雕像的躯体是在公元前15世纪的历史文物中发现的。"},{"en":"This tradition dates from the Tang Dynasty and is still kept in many villages.","zh":"这个传统可以追溯到唐朝，现在很多村庄仍然保留着。"}]},{"phrase":"happen to do","usage":"表示“碰巧做某事，偶然发生”，强调事情的偶然性，无被动语态","examples":[{"en":"Its missing head happened to be among remains of the fifth century B.C.","zh":"它那失踪的头像恰巧在公元前5世纪的遗迹里。"},{"en":"I happened to meet my primary school teacher when I was shopping yesterday.","zh":"我昨天逛街的时候碰巧遇到了我的小学老师。"}]},{"phrase":"turn out to be","usage":"表示“结果是，原来是，最终被发现是”，强调结果与预期可能不同，后可接名词、形容词","examples":[{"en":"They were amazed to find that the goddess turned out to be a very modern-looking woman.","zh":"他们惊奇地发现，那位女神原来竟是一位相貌十分摩登的女郎。"},{"en":"The job turned out to be much harder than I thought at first.","zh":"这份工作结果比我一开始想的要难得多。"}]},{"phrase":"rest on","usage":"表示“搁在，靠在；依赖，基于”，此处取“放置在某个支撑物上”的含义","examples":[{"en":"She stood three feet high and her hands rested on her hips.","zh":"她身高3英尺，双手叉腰。"},{"en":"After walking for two hours, he rested his shoulders on the wall and took a deep breath.","zh":"走了两个小时的路，他把肩膀靠在墙上，深吸了一口气。"}]},{"phrase":"so far","usage":"表示“到目前为止，迄今为止”，常与现在完成时连用，说明截止到现在的状态","examples":[{"en":"So far, the archaeologists have been unable to discover her identity.","zh":"到目前为止，考古学家们还不能确定她的身份。"},{"en":"So far, we have received more than 100 applications for the position.","zh":"到目前为止，我们已经收到了100多份这个岗位的申请。"}]},{"phrase":"be used as","usage":"表示“被用作，充当”，主语为被使用的事物，后接功能、用途类名词","examples":[{"en":"The temple which the archaeologists explored was used as a place of worship from the fifteenth century B.C. until Roman times.","zh":"考古工作者考察的这座庙宇从公元前15世纪直到罗马时代一直是祭祀祈祷的场所。"},{"en":"The small room was used as a temporary storage room during the renovation.","zh":"装修期间，这个小房间被用作临时储藏室。"}]}],"grammar":[{"title":"情态动词表推测（must have done）","definition":"用于对过去已经发生的事情进行肯定的推测，说话人对推测的内容有较大把握，通常是基于已知证据做出的判断","structure":"must + have + 动词过去分词","usage":"只用在肯定句中，否定推测用can't have done，疑问推测用can have done，常用来对过去的情况进行合理推断","examples":[{"en":"The city at one time must have been prosperous, for it enjoyed a high level of civilization.","zh":"这座古城肯定一度很繁荣，因为它曾享有高度的文明。"},{"en":"This head must have been found in Classical times and carefully preserved.","zh":"这个头像肯定在古希腊罗马时期就被发现了，并且得到了精心的保存。"},{"en":"He didn't come to the meeting yesterday. He must have forgotten about it.","zh":"他昨天没来开会，肯定是把这件事忘了。"}]},{"title":"定语从句","definition":"在句子中作定语，修饰名词或代词的从句，被修饰的词叫先行词，引导定语从句的词叫关系词（which, who, that, where等）","structure":"先行词 + 关系词 + 定语从句","usage":"当先行词是事物时，常用关系代词which/that引导，关系词在从句中可作主语或宾语；作宾语时关系词可以省略","examples":[{"en":"An American team explored a temple which stands in an ancient city on the promontory of Ayia Irini.","zh":"一个美国考古队考察了位于阿伊亚·依里尼海角的一座古城中的庙宇。"},{"en":"The temple which the archaeologists explored was used as a place of worship.","zh":"考古工作者考察的这座庙宇被用作祭祀祈祷的场所。"},{"en":"The book that I bought last week is very interesting.","zh":"我上周买的那本书非常有意思。"}]},{"title":"现在完成时的被动语态","definition":"表示动作从过去持续到现在，且主语是动作的承受者，强调对现在造成的影响","structure":"have/has + been + 动词过去分词","usage":"当主语是动作的承受者，且时间涉及从过去到现在的范畴（常和so far, up to now, since等连用）时使用","examples":[{"en":"So far, the archaeologists have been unable to discover her identity.","zh":"到目前为止，考古学家们还不能确定她的身份。"},{"en":"The old building has been repaired three times since 2010.","zh":"这座老建筑自2010年以来已经被修缮了三次。"},{"en":"The problem has not been solved yet, so we need to hold another meeting.","zh":"这个问题还没有被解决，所以我们需要再开一次会。"}]}],"patterns":[{"pattern":"Some time ago, an interesting discovery was made by... on...","explanation":"","original":{"en":"Some time ago, an interesting discovery was made by archaeologists on the Aegean island of Kea.","zh":"不久之前，考古学家在爱琴海的基亚岛上有了一项有趣的发现。"},"examples":[{"en":"Some time ago, a surprising discovery was made by astronomers on a planet outside the solar system.","zh":"不久之前，天文学家在太阳系外的一颗行星上有了一项惊人的发现。"},{"en":"Some time ago, an important discovery was made by biologists in the tropical rainforest.","zh":"不久之前，生物学家在热带雨林里有了一项重要的发现。"}]},{"pattern":"... must have been..., for...","explanation":"","original":{"en":"The city at one time must have been prosperous, for it enjoyed a high level of civilization.","zh":"这座古城肯定一度很繁荣，因为它曾享有高度的文明。"},"examples":[{"en":"The man must have been a soldier before, for he walks in a very straight posture.","zh":"这个男人以前肯定当过兵，因为他走路的姿势非常挺拔。"},{"en":"The concert must have been very wonderful, for all the audience stood up and applauded for ten minutes.","zh":"那场音乐会肯定非常精彩，因为所有观众都站起来鼓掌了十分钟。"}]},{"pattern":"When..., sb. were amazed to find that...","explanation":"","original":{"en":"When the archaeologists reconstructed the fragments, they were amazed to find that the goddess turned out to be a very modern-looking woman.","zh":"当考古学家们把这些碎片拼接起来的时候，他们惊奇地发现，那位女神原来竟是一位相貌十分摩登的女郎。"},"examples":[{"en":"When I opened the old box that my grandma left, I was amazed to find that there were many photos of my childhood inside.","zh":"当我打开奶奶留下的旧盒子时，我惊奇地发现里面有很多我童年的照片。"},{"en":"When the police checked the surveillance video, they were amazed to find that the thief was actually a teenager under 14.","zh":"当警方查看监控录像时，他们惊讶地发现小偷居然是一个不满14岁的少年。"}]},{"pattern":"Despite..., ... indeed, but, so far, ... have been unable to...","explanation":"","original":{"en":"Despite her great age, she was very graceful indeed, but, so far, the archaeologists have been unable to discover her identity.","zh":"尽管年代久远，她仍然风姿绰约，但是到目前为止，考古学家们还不能确定她的身份。"},"examples":[{"en":"Despite the difficult conditions, the rescue work is progressing smoothly indeed, but, so far, the rescuers have been unable to reach the trapped people.","zh":"尽管条件艰苦，救援工作确实进展顺利，但是到目前为止，救援人员还无法到达被困人员所在的位置。"},{"en":"Despite many experiments, the new drug is effective in treating the disease indeed, but, so far, the researchers have been unable to confirm its long-term safety.","zh":"尽管经过了多次实验，这种新药确实对治疗这种疾病有效，但是到目前为止，研究人员还无法确认它的长期安全性。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“崇拜，敬奉；礼拜” 对应的单词是？","hint":"noun · /ˈwɜːʃɪp/","options":["joke","clump","worship","piece together"],"answer":2,"explain":"worship · /ˈwɜːʃɪp/ · noun · 崇拜，敬奉；礼拜。指对神、宗教人物的敬拜，也可指对某人/物的极度崇拜，place of worship即宗教礼拜场所","source":{"kind":"vocab","word":"worship"},"id":"b3-u03-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：神圣的，宗教的；受崇敬的","hint":"/ˈseɪkrɪd/ · adjective","answer":"sacred","placeholder":"输入英文单词","explain":"sacred · /ˈseɪkrɪd/ · adjective · 神圣的，宗教的；受崇敬的。常用来描述与宗教相关、被认为不可侵犯的事物，如sacred place（圣地）","source":{"kind":"vocab","word":"sacred"},"id":"b3-u03-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, I lived in the countryside, so I know a lot about farm work.","hint":"我曾经在农村住过，所以我很了解农活。","answer":"at one time","placeholder":"输入缺失的短语","explain":"at one time：用于描述过去某个时期曾经发生的情况，相当于“曾经，一度”，常与过去时态搭配（我曾经在农村住过，所以我很了解农活。）","source":{"kind":"phrase","phrase":"at one time"},"id":"b3-u03-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：She stood three _____ high and her hands rested on her hips.","hint":"她身高三英尺，双手叉腰。","answer":"feet","placeholder":"输入缺失的单词","explain":"She stood three feet high and her hands rested on her hips. — 她身高三英尺，双手叉腰。","source":{"kind":"sentence","en":"She stood three feet high and her hands rested on her hips."},"id":"b3-u03-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于对过去已经发生的事情进行肯定的推测，说话人对推测的内容有较大把握，通常是基于已知证据做出的判断” 描述的是哪个语法点？","hint":"must + have + 动词过去分词","options":["过去完成进行时","情态动词表推测（must have done）","结果状语从句 (Consecutive Clause)","宾语从句（Object Clause）"],"answer":1,"explain":"情态动词表推测（must have done）：must + have + 动词过去分词：只用在肯定句中，否定推测用can't have done，疑问推测用can have done，常用来对过去的情况进行合理推断","source":{"kind":"grammar","title":"情态动词表推测（must have done）"},"id":"b3-u03-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe body of one statue was found among remains dating from the 15th century B.C.","hint":"","options":["一尊雕像的身体是在可追溯到公元前15世纪的遗迹中发现的。","还有其他好处。","他很快就要在办公室工作了。","我的大部分朋友都住在城里，然而他们一提到乡村就手舞足蹈。"],"answer":0,"explain":"The body of one statue was found among remains dating from the 15th century B.C. — 一尊雕像的身体是在可追溯到公元前15世纪的遗迹中发现的。","source":{"kind":"sentence","en":"The body of one statue was found among remains dating from the 15th century B.C."},"id":"b3-u03-q06"}]},{"id":"b3-u04","book":3,"unit":4,"key":"04","lessonFrom":4,"lessonTo":4,"title":"The Double Life of Alfred Bloggs","titleZh":"阿尔弗雷德·布洛格斯的双重生活","question":"Why did Alf want a white-collar job?","sentences":[{"en":"These days, people who do manual work often receive far more money than people who work in offices.","zh":"如今，从事体力劳动的人挣的钱，常常比办公室工作人员挣的钱多得多。","t":16.83},{"en":"People who work in offices are frequently referred to as 'white-collar workers' for the simple reason that they usually wear a collar and tie to go to work.","zh":"办公室工作人员通常被称为“白领工人”，原因很简单，他们上班时通常穿带领带的衬衫。","t":24.76},{"en":"Such is human nature, that a great many people are often willing to sacrifice higher pay for the privilege of becoming white-collar workers.","zh":"人性如此，许多人常常愿意牺牲较高的工资，以换取成为白领工人的殊荣。","t":36.74},{"en":"This can give rise to curious situations, as it did in the case of Alfred Bloggs who worked as a dustman for the Ellesmere Corporation.","zh":"这可能导致一些奇怪的情况，就像阿尔弗雷德·布洛格斯的情况一样，他曾是埃尔斯米尔公司的一名清洁工。","t":48.19},{"en":"When he got married, Alf was too embarrassed to say anything to his wife about his job.","zh":"结婚时，阿尔弗太不好意思告诉妻子他的工作了。","t":60.78},{"en":"He simply told her that he worked for the Corporation.","zh":"他只告诉她他在公司上班。","t":67.63},{"en":"Every morning, he left home dressed in a smart black suit.","zh":"每天早上，他都穿着一套漂亮的黑色西装出门。","t":71.57},{"en":"He then changed into overalls and spent the next eight hours as a dustman.","zh":"然后他换上工作服，接下来的八个小时都当清洁工。","t":76.45},{"en":"Before returning home at night, he took a shower and changed back into his suit.","zh":"晚上回家前，他洗了个澡，又换回了他的西装。","t":82.9},{"en":"Alf did this for over two years and his fellow dustmen kept his secret.","zh":"阿尔弗这样做了两年多，他的清洁工同事们都替他保密。","t":89.02},{"en":"Alf's wife has never discovered that she married a dustman and she never will, for Alf has just found another job.","zh":"阿尔弗的妻子从未发现她嫁给了一个清洁工，而且她永远也不会发现了，因为阿尔弗刚刚找到了另一份工作。","t":95.66},{"en":"He will soon be working in an office.","zh":"他很快就要在办公室工作了。","t":104.47},{"en":"He will be earning only half as much as he used to, but he feels that his rise in status is well worth the loss of money.","zh":"他挣的钱将只有以前的一半，但他觉得地位的提升，很值得损失这点钱。","t":107.61},{"en":"From now on, he will wear a suit all day and others will call him 'Mr.Bloggs', not 'Alf'.","zh":"从现在起，他将一整天都穿西装，别人会称呼他“布洛格斯先生”，而不是“阿尔弗”。","t":117.05}],"vocab":[{"word":"manual","phonetic":"/ˈmænjuəl/","meanings":[{"pos":"adjective","meaning":"体力的；手工的","usage":"通常修饰工作、劳动等需要体力完成的活动"}]},{"word":"white-collar","phonetic":"/ˌwaɪt ˈkɒlə(r)/","meanings":[{"pos":"adjective","meaning":"白领的；办公室工作的","usage":"用于描述从事非体力办公室工作的人群或相关属性"}]},{"word":"sacrifice","phonetic":"/ˈsækrɪfaɪs/","meanings":[{"pos":"verb","meaning":"牺牲；舍弃","usage":"常用搭配sacrifice sth for sth，表为了某物舍弃另一物"}]},{"word":"privilege","phonetic":"/ˈprɪvəlɪdʒ/","meanings":[{"pos":"noun","meaning":"特权；特殊待遇","usage":"可指社会地位带来的特殊优待，也可表荣幸做某事"}]},{"word":"curious","phonetic":"/ˈkjʊəriəs/","meanings":[{"pos":"adjective","meaning":"奇特的；奇怪的","usage":"除表好奇的，还可修饰事物表示不寻常、值得注意的"}]},{"word":"dustman","phonetic":"/ˈdʌstmən/","meanings":[{"pos":"noun","meaning":"清洁工；垃圾清运工","usage":"英式英语表述，对应美式英语garbage man"}]},{"word":"embarrassed","phonetic":"/ɪmˈbærəst/","meanings":[{"pos":"adjective","meaning":"尴尬的；难堪的","usage":"用来描述人因处境尴尬、害羞的状态，修饰事物用embarrassing"}]},{"word":"overalls","phonetic":"/ˈəʊvərɔːlz/","meanings":[{"pos":"noun","meaning":"工装裤；工作罩衣","usage":"常用复数形式，指工作时穿的防护性服装"}]},{"word":"fellow","phonetic":"/ˈfeləʊ/","meanings":[{"pos":"adjective","meaning":"同类的；同伴的","usage":"放在名词前，指和自己有相同身份、处境的人"}]},{"word":"status","phonetic":"/ˈsteɪtəs/","meanings":[{"pos":"noun","meaning":"地位；身份","usage":"指个人在社会、组织中的层级地位，不可数名词"}]}],"phrases":[{"phrase":"refer to sb as","usage":"将某人称作、把某人称为，用来表达对某人的称谓","examples":[{"en":"People who work in offices are frequently referred to as 'white-collar workers'.","zh":"在办公室工作的人常常被称作“白领工人”。"},{"en":"He is often referred to as the best basketball player of his generation.","zh":"他常被称为他那一代人中最好的篮球运动员。"}]},{"phrase":"give rise to","usage":"引起；导致；使发生，后接表示结果类的名词","examples":[{"en":"This can give rise to curious situations.","zh":"这就可能引起一些奇怪的现象。"},{"en":"Poor communication may give rise to misunderstandings between team members.","zh":"沟通不畅可能会导致团队成员之间产生误会。"}]},{"phrase":"in the case of","usage":"就……而言；在……的情况下，用来引出具体的例子或情况","examples":[{"en":"As it did in the case of Alfred Bloggs who worked as a dustman.","zh":"在阿尔弗雷德·布洛格斯的情况中就是如此，他是埃尔斯米尔公司的清洁工。"},{"en":"The new policy is quite flexible, especially in the case of small businesses.","zh":"这项新政策很灵活，对小企业来说尤其如此。"}]},{"phrase":"too ... to ...","usage":"太……而不能……，用来表达否定含义，说明程度过高导致无法做某事","examples":[{"en":"Alf was too embarrassed to say anything to his wife about his job.","zh":"阿尔弗太尴尬了，以至于没法和妻子说自己工作的事。"},{"en":"The little boy was too short to reach the book on the top shelf.","zh":"这个小男孩太矮了，够不到顶层架子上的书。"}]},{"phrase":"be well worth","usage":"非常值得……，后面接名词或动名词，表付出的代价是值得的","examples":[{"en":"He feels that his rise in status is well worth the loss of money.","zh":"他觉得地位提升了，损失这点钱是非常值得的。"},{"en":"The view from the mountain top is well worth the two-hour climb.","zh":"爬两个小时的山来看山顶的景色是非常值得的。"}]}],"grammar":[{"title":"定语从句 (Attributive Clause)","definition":"在复合句中修饰名词或代词的从句，用来对先行词进行修饰限定","structure":"先行词 + 关系代词/关系副词 + 从句剩余部分","usage":"用来补充说明先行词的特征、属性等，常用关系代词who指代人，which指代物，that既可指人或物","examples":[{"en":"People who do manual work often receive far more money than people who work in offices.","zh":"从事体力劳动的人通常比坐办公室的人收入高得多。"},{"en":"The book that you lent me last week is very interesting.","zh":"你上周借给我的那本书非常有意思。"}]},{"title":"将来进行时 (Future Continuous Tense)","definition":"表示将来某个时间正在进行的动作，或者将来某段时间内持续进行的动作","structure":"will be + 动词的现在分词（doing）","usage":"用来表达对将来动作的客观描述，比一般将来时更强调动作在未来的持续性、进行状态","examples":[{"en":"He will soon be working in an office.","zh":"他不久就要在办公室工作了。"},{"en":"This time tomorrow, I will be flying to Paris.","zh":"明天这个时候，我正飞往巴黎。"}]},{"title":"such引导的倒装句","definition":"为了强调表语部分，将such置于句首，句子需要部分倒装，用来加强语气","structure":"Such + be + 主语 + that引导的结果状语从句","usage":"用来突出强调某事物的性质、特点，后接that从句说明该特点带来的结果","examples":[{"en":"Such is human nature, that a great many people are often willing to sacrifice higher pay for the privilege of becoming white-collar workers.","zh":"很多人常常愿意牺牲更高的薪水来换取成为白领的优待，这就是人之常情。"},{"en":"Such is the power of music that it can make people forget their sadness.","zh":"这就是音乐的力量，它能让人们忘记悲伤。"}]}],"patterns":[{"pattern":"A receive far more money than B","explanation":"","original":{"en":"These days, people who do manual work often receive far more money than people who work in offices.","zh":"如今，从事体力劳动的人通常比坐办公室的人收入高得多。"},"examples":[{"en":"Nowadays, skilled technicians often receive far more money than ordinary office clerks.","zh":"如今，技术娴熟的技工通常比普通办公室职员收入高得多。"},{"en":"In many cities, people who work in the catering industry often receive far more money than new graduates.","zh":"在很多城市，从事餐饮行业的人通常比刚毕业的学生收入高得多。"}]},{"pattern":"A be willing to sacrifice A for the privilege of B","explanation":"","original":{"en":"A great many people are often willing to sacrifice higher pay for the privilege of becoming white-collar workers.","zh":"很多人常常愿意牺牲更高的薪水来换取成为白领的优待。"},"examples":[{"en":"Many young people are willing to sacrifice their free time for the privilege of studying at a top university.","zh":"很多年轻人愿意牺牲自己的空闲时间来换取在顶尖大学学习的机会。"},{"en":"He was willing to sacrifice a stable job for the privilege of starting his own business.","zh":"他愿意牺牲一份稳定的工作来换取自己创业的机会。"}]},{"pattern":"A do this for + 时间段, and B keep the secret","explanation":"","original":{"en":"Alf did this for over two years and his fellow dustmen kept his secret.","zh":"阿尔弗这样做了两年多，他的清洁工同事们都替他保守秘密。"},"examples":[{"en":"She hid her illness from her family for three months and her close friends kept her secret.","zh":"她向家人隐瞒了自己的病情三个月，她的密友们都替她保守秘密。"},{"en":"He prepared a surprise birthday party for his wife for a week and all their common friends kept the secret.","zh":"他为妻子准备惊喜生日派对准备了一周，他们的共同好友都替他保守秘密。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“白领的；办公室工作的” 对应的单词是？","hint":"adjective · /ˌwaɪt ˈkɒlə(r)/","options":["verify","white-collar","mania","confusion"],"answer":1,"explain":"white-collar · /ˌwaɪt ˈkɒlə(r)/ · adjective · 白领的；办公室工作的。用于描述从事非体力办公室工作的人群或相关属性","source":{"kind":"vocab","word":"white-collar"},"id":"b3-u04-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：同类的；同伴的","hint":"/ˈfeləʊ/ · adjective","answer":"fellow","placeholder":"输入英文单词","explain":"fellow · /ˈfeləʊ/ · adjective · 同类的；同伴的。放在名词前，指和自己有相同身份、处境的人","source":{"kind":"vocab","word":"fellow"},"id":"b3-u04-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Poor communication may _____ misunderstandings between team members.","hint":"沟通不畅可能会导致团队成员之间产生误会。","answer":"give rise to","placeholder":"输入缺失的短语","explain":"give rise to：引起；导致；使发生，后接表示结果类的名词（沟通不畅可能会导致团队成员之间产生误会。）","source":{"kind":"phrase","phrase":"give rise to"},"id":"b3-u04-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：He then changed _____ overalls and spent the next eight hours as a dustman.","hint":"然后他换上工作服，接下来的八个小时都当清洁工。","answer":"into","placeholder":"输入缺失的单词","explain":"He then changed into overalls and spent the next eight hours as a dustman. — 然后他换上工作服，接下来的八个小时都当清洁工。","source":{"kind":"sentence","en":"He then changed into overalls and spent the next eight hours as a dustman."},"id":"b3-u04-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示将来某个时间正在进行的动作，或者将来某段时间内持续进行的动作” 描述的是哪个语法点？","hint":"will be + 动词的现在分词（doing）","options":["Not only...but (also) 引起的倒装句","否定副词置于句首的倒装句","虚拟条件句的倒装","将来进行时 (Future Continuous Tense)"],"answer":3,"explain":"将来进行时 (Future Continuous Tense)：will be + 动词的现在分词（doing）：用来表达对将来动作的客观描述，比一般将来时更强调动作在未来的持续性、进行状态","source":{"kind":"grammar","title":"将来进行时 (Future Continuous Tense)"},"id":"b3-u04-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nHe simply told her that he worked for the Corporation.","hint":"","options":["由于人太多，狗必须被关在一个特殊的围栏里。","乞丐几乎是出卖他们自身以博得过路人的同情。","下面这个“病态幽默”的例子能让你自己评判。","他只告诉她他在公司上班。"],"answer":3,"explain":"He simply told her that he worked for the Corporation. — 他只告诉她他在公司上班。","source":{"kind":"sentence","en":"He simply told her that he worked for the Corporation."},"id":"b3-u04-q06"}]},{"id":"b3-u05","book":3,"unit":5,"key":"05","lessonFrom":5,"lessonTo":5,"title":"The Facts","titleZh":"事实真相","question":"What was the consequence of the editor's insistence on facts and statistics?","sentences":[{"en":"Editors of newspapers and magazines often go to extremes to provide their readers with unimportant facts and statistics.","zh":"报纸杂志的编辑们常常不厌其烦地向读者提供一些无关紧要的事实和统计数字。","t":16.65},{"en":"Last year a journalist had been instructed by a well-known magazine to write an article on the president's palace in a new African republic.","zh":"去年，一家有名的杂志派一名记者去撰写一篇有关一个非洲新共和国总统府的稿件。","t":25.01},{"en":"When the article arrived, the editor read the first sentence and then refused to publish it.","zh":"稿件寄来后，编辑看了第一句话就拒绝发表。","t":35.09},{"en":"The article began:'Hundreds of steps lead to the high wall which surrounds the president's palace.'","zh":"文章的开头是这样的：“几百级台阶通向总统府四周的高墙。”","t":42.43},{"en":"The editor at once sent the journalist a fax instructing him to find out the exact number of steps and the height of the wall.","zh":"编辑立即给记者发了一份传真，指示他查明台阶的确切数字和围墙的高度。","t":50.24},{"en":"The journalist immediately set out to obtain these important facts, but he took a long time to send them.","zh":"记者立即动身去搜集这些重要的事实，但过了很久才把材料寄来。","t":61.28},{"en":"Meanwhile, the editor was getting impatient, for the magazine would soon go to press.","zh":"与此同时，编辑等得不耐烦了，因为杂志很快就要付印。","t":68.66},{"en":"He sent the journalist two more faxes, but received no reply.","zh":"他又给记者发了两份传真，但没有任何回音。","t":74.24},{"en":"He sent yet another fax informing the journalist that if he did not reply soon he would be fired.","zh":"他又发了一份传真，通知记者说如果再不迅速回复，他就将被解雇。","t":79.44},{"en":"When the journalist again failed to reply, the editor reluctantly published the article as it had originally been written.","zh":"记者还是没有回复，编辑只好不情愿地按原样发表了那篇文章。","t":86.81},{"en":"A week later, the editor at last received a fax from the journalist.","zh":"一周后，编辑终于接到了记者的一份传真。","t":95.61},{"en":"Not only had the poor man been arrested, but he had been sent to prison as well.","zh":"那可怜的记者不仅被捕了，而且还被送进了监狱。","t":100.98},{"en":"However, he had at last been allowed to send a fax in which he informed the editor that he had been arrested","zh":"然而，他最终获准发了一份传真，在传真中他告诉编辑，他被捕了，","t":107.19},{"en":"while counting the 1,084 steps leading to the 15th foot wall which surrounded the president's palace.","zh":"因为他正在数通向总统府的1084级台阶和围绕总统府15英尺高的围墙。","t":115.99}],"vocab":[{"word":"editor","phonetic":"/ˈedɪtə(r)/","meanings":[{"pos":"noun","meaning":"编辑","usage":"指报刊、杂志、书籍等内容的审核、整理人员"}]},{"word":"journalist","phonetic":"/ˈdʒɜːnəlɪst/","meanings":[{"pos":"noun","meaning":"记者","usage":"指从事新闻采访、报道工作的人员"}]},{"word":"instruct","phonetic":"/ɪnˈstrʌkt/","meanings":[{"pos":"verb","meaning":"指示；命令；吩咐","usage":"正式用法，指上级给下级明确指示做某事，常用结构instruct sb to do sth"}]},{"word":"publish","phonetic":"/ˈpʌblɪʃ/","meanings":[{"pos":"verb","meaning":"出版；发表；刊登","usage":"可指书籍、报刊、文章等的正式发布"}]},{"word":"impatient","phonetic":"/ɪmˈpeɪʃnt/","meanings":[{"pos":"adjective","meaning":"不耐烦的；急躁的","usage":"前缀im-表否定，对应反义词patient，常用搭配be impatient with sb/at sth"}]},{"word":"reluctantly","phonetic":"/rɪˈlʌktəntli/","meanings":[{"pos":"adverb","meaning":"不情愿地；勉强地","usage":"用来修饰动作，表示做某事时很不情愿"}]},{"word":"originally","phonetic":"/əˈrɪdʒənəli/","meanings":[{"pos":"adverb","meaning":"最初；原先","usage":"用来描述事物最开始的状态"}]},{"word":"arrest","phonetic":"/əˈrest/","meanings":[{"pos":"verb","meaning":"逮捕；拘留","usage":"常用被动语态be arrested表示“被逮捕”"}]},{"word":"consequence","phonetic":"/ˈkɒnsɪkwəns/","meanings":[{"pos":"noun","meaning":"结果；后果","usage":"常指某个行为或事件带来的直接结果，常用搭配as a consequence"}]},{"word":"statistics","phonetic":"/stəˈtɪstɪks/","meanings":[{"pos":"noun","meaning":"统计数据；统计资料","usage":"通常以复数形式出现，指具体的统计数字"}]}],"phrases":[{"phrase":"go to extremes","usage":"表示“走极端；做过头”，描述人在做某事时过于偏激，超出合理范围","examples":[{"en":"Some parents go to extremes to send their children to the best schools.","zh":"有些家长为了把孩子送到最好的学校做得太过极端。"}]},{"phrase":"set out to do sth","usage":"表示“着手做某事；开始努力做某事”，强调带着明确目标开始行动","examples":[{"en":"He set out to finish the report within three days.","zh":"他着手准备在三天内完成这份报告。"}]},{"phrase":"go to press","usage":"固定搭配，表示“（报刊、杂志）付印；即将出版”","examples":[{"en":"The weekly magazine will go to press tomorrow, so we have to submit the article today.","zh":"这本周刊明天就要付印了，所以我们今天必须提交文章。"}]},{"phrase":"not only...but...as well","usage":"表示“不仅……而且……”，用于连接两个并列的成分，强调后者","examples":[{"en":"Not only did she win the first prize, but she got a scholarship as well.","zh":"她不仅获得了一等奖，还拿到了奖学金。"}]},{"phrase":"lead to","usage":"此处表示“通向；通往”，此外也可表示“导致；引起”某个结果","examples":[{"en":"This path leads to the small village at the foot of the mountain.","zh":"这条小路通向山脚下的小村庄。"},{"en":"Lack of exercise can lead to many health problems.","zh":"缺乏锻炼会导致很多健康问题。"}]}],"grammar":[{"title":"过去完成时的被动语态","definition":"表示在过去某个动作之前已经完成的被动动作，即“过去的过去”发生的被动行为","structure":"had been + 动词过去分词","usage":"当句子中动作的承受者作为主语，且动作发生在过去另一个动作之前时使用","examples":[{"en":"Last year a journalist had been instructed by a well-known magazine to write an article.","zh":"去年，一位记者受一家知名杂志委托写一篇文章。"},{"en":"All the tickets had been sold out when we arrived at the cinema.","zh":"我们到电影院的时候，所有票都已经卖光了。"}]},{"title":"not only位于句首的部分倒装结构","definition":"当not only放在句首连接两个分句时，第一个分句需要进行部分倒装，将助动词/情态动词/be动词提到主语之前，第二个分句保持正常语序","structure":"Not only + 助动词/情态动词/be动词 + 主语 + 谓语 + 其他, but + 正常语序的分句","usage":"用于加强语气，突出“不仅……而且……”的递进关系","examples":[{"en":"Not only had the poor man been arrested, but he had been sent to prison as well.","zh":"这个可怜的人不仅被逮捕了，还被送进了监狱。"},{"en":"Not only does he speak English fluently, but he also knows French.","zh":"他不仅英语说得流利，还懂法语。"}]}],"patterns":[{"pattern":"sb be instructed to do sth","explanation":"","original":{"en":"Last year a journalist had been instructed by a well-known magazine to write an article on the president's palace.","zh":"去年，一位记者受一家知名杂志委托，写一篇关于某个非洲新共和国总统府的文章。"},"examples":[{"en":"The new intern was instructed by the manager to collect customer feedback.","zh":"新来的实习生被经理要求收集客户反馈。"},{"en":"All the team members were instructed to arrive at the office before 8 a.m. tomorrow.","zh":"所有团队成员都被要求明天早上8点前到达办公室。"}]},{"pattern":"sb sent sb sth informing sb that...","explanation":"","original":{"en":"He sent yet another fax informing the journalist that if he did not reply soon he would be fired.","zh":"他又发了一份传真，通知记者如果他再不尽快回复就会被解雇。"},"examples":[{"en":"The teacher sent all parents a message informing them that the parent-teacher meeting would be held next Friday.","zh":"老师给所有家长发了一条消息，通知他们下周五将召开家长会。"},{"en":"The travel agency sent us an email informing us that our flight had been delayed for two hours.","zh":"旅行社给我们发了一封邮件，通知我们的航班延误了两个小时。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“最初；原先” 对应的单词是？","hint":"adverb · /əˈrɪdʒənəli/","options":["delicacy","boxer","luscious","originally"],"answer":3,"explain":"originally · /əˈrɪdʒənəli/ · adverb · 最初；原先。用来描述事物最开始的状态","source":{"kind":"vocab","word":"originally"},"id":"b3-u05-q01"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The weekly magazine will _____ tomorrow, so we have to submit the article today.","hint":"这本周刊明天就要付印了，所以我们今天必须提交文章。","answer":"go to press","placeholder":"输入缺失的短语","explain":"go to press：固定搭配，表示“（报刊、杂志）付印；即将出版”（这本周刊明天就要付印了，所以我们今天必须提交文章。）","source":{"kind":"phrase","phrase":"go to press"},"id":"b3-u05-q02"},{"type":"cloze","kind":"text","prompt":"补全句子：The editor at once sent the journalist a fax instructing him to _____ out the exact number of steps and the height of the wall.","hint":"编辑立即给记者发了一份传真，指示他查明台阶的确切数字和围墙的高度。","answer":"find","placeholder":"输入缺失的单词","explain":"The editor at once sent the journalist a fax instructing him to find out the exact number of steps and the height of the wall. — 编辑立即给记者发了一份传真，指示他查明台阶的确切数字和围墙的高度。","source":{"kind":"sentence","en":"The editor at once sent the journalist a fax instructing him to find out the exact number of steps and the height of the wall."},"id":"b3-u05-q03"},{"type":"grammar-choice","kind":"choice","prompt":"“当not only放在句首连接两个分句时，第一个分句需要进行部分倒装，将助动词/情态动词/be动词提到主语之前，第二个分句保持正常语序” 描述的是哪个语法点？","hint":"Not only + 助动词/情态动词/be动词 + 主语 + 谓语 + 其他, but + 正常语序的分句","options":["As引导的时间状语从句","as if引导的虚拟语气","But连接的并列句","not only位于句首的部分倒装结构"],"answer":3,"explain":"not only位于句首的部分倒装结构：Not only + 助动词/情态动词/be动词 + 主语 + 谓语 + 其他, but + 正常语序的分句：用于加强语气，突出“不仅……而且……”的递进关系","source":{"kind":"grammar","title":"not only位于句首的部分倒装结构"},"id":"b3-u05-q04"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nMeanwhile, the editor was getting impatient, for the magazine would soon go to press.","hint":"","options":["与此同时，编辑等得不耐烦了，因为杂志很快就要付印。","指出他兄弟在战争中阵亡了。","英语中有一个生动的说法来描述这种情况。","使用基于地球的望远镜来寻找其他行星上的生命是不可能的。"],"answer":0,"explain":"Meanwhile, the editor was getting impatient, for the magazine would soon go to press. — 与此同时，编辑等得不耐烦了，因为杂志很快就要付印。","source":{"kind":"sentence","en":"Meanwhile, the editor was getting impatient, for the magazine would soon go to press."},"id":"b3-u05-q05"},{"type":"dictation","kind":"text","prompt":"听写：点击播放，写出你听到的句子。","hint":"共 11 个单词","answer":"He sent the journalist two more faxes, but received no reply.","placeholder":"输入完整英文句子","explain":"He sent the journalist two more faxes, but received no reply. — 他又给记者发了两份传真，但没有任何回音。","playText":"He sent the journalist two more faxes, but received no reply.","source":{"kind":"sentence","en":"He sent the journalist two more faxes, but received no reply."},"id":"b3-u05-q06"}]},{"id":"b3-u06","book":3,"unit":6,"key":"06","lessonFrom":6,"lessonTo":6,"title":"Smash and Grab","titleZh":"砸橱窗抢劫","question":"How did Mr. Taylor try to stop the thieves?","sentences":[{"en":"The expensive shops in a famous arcade near Piccadilly were just opening.","zh":"靠近皮卡迪利大街的著名拱形建筑里的那些高档商店刚刚开门。","t":13.91},{"en":"At this time of the morning, the arcade was almost empty.","zh":"在早晨这个时候，拱形建筑里几乎空无一人。","t":19.86},{"en":"Mr. Taylor, the owner of a jewellery shop was admiring a new window display.","zh":"珠宝店店主泰勒先生正在欣赏新布置的橱窗。","t":24.53},{"en":"Two of his assistants had been working busily since 8 o'clock and had only just finished.","zh":"他的两名助手从8点钟就开始忙碌，刚刚才把橱窗布置好。","t":30.92},{"en":"Diamond necklaces and rings had been beautifully arranged on a background of black velvet.","zh":"钻石项链和戒指精美地摆放在黑色丝绒的衬托下。","t":38.1},{"en":"After gazing at the display for several minutes, Mr. Taylor went back into his shop.","zh":"泰勒先生凝视橱窗几分钟之后，便回到了店里。","t":45.36},{"en":"The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade.","zh":"正在这时，突然一辆开着车灯、鸣着喇叭的汽车，咆哮着冲进了拱形建筑，打破了寂静。","t":52.13},{"en":"It came to a stop outside the jeweller's.","zh":"它在珠宝店门口停了下来。","t":61.86},{"en":"One man stayed at the wheel while two others with black stockings over their faces jumped out and smashed the window of the shop with iron bars.","zh":"一个人留在驾驶座上，另外两个人则蒙着黑色丝袜跳下车，用铁棍砸碎了商店的橱窗。","t":65.68},{"en":"While this was going on, Mr. Taylor was upstairs.","zh":"就在这当儿，泰勒先生正在楼上。","t":76.82},{"en":"He and his staff began throwing furniture out of the window.","zh":"他和店员开始把家具往窗外扔。","t":81.36},{"en":"Chairs and tables went flying into the arcade.","zh":"椅子和桌子飞进了拱形建筑。","t":86.25},{"en":"One of the thieves was struck by a heavy statue,","zh":"其中一个窃贼被一尊沉重的塑像砸中，","t":90.59},{"en":"but he was too busy helping himself to diamonds to notice any pain.","zh":"但他只顾忙着抢钻石，根本没注意到疼痛。","t":94.21},{"en":"The raid was all over in three minutes, for the men scrambled back into the car and it moved off at a fantastic speed.","zh":"抢劫在3分钟之内便结束了，因为劫匪们又争先恐后地跳上汽车，汽车以惊人的速度开走了。","t":100.36},{"en":"Just as it was leaving,","zh":"就在汽车开走的时候，","t":110.19},{"en":"Mr.Taylor rushed out and ran after it throwing ashtrays and vases,","zh":"泰勒先生冲了出来，一边追赶汽车，一边扔烟灰缸和花瓶，","t":112.38},{"en":"but it was impossible to stop the thieves.","zh":"但根本无法阻止窃贼。","t":117.86},{"en":"They had got away with thousands of pounds worth of diamonds.","zh":"他们已带着价值数千英镑的钻石逃走了。","t":120.99}],"vocab":[{"word":"smash-and-grab","phonetic":"/ˌsmæʃ ən ˈɡræb/","meanings":[{"pos":"noun","meaning":"砸橱窗抢劫（指砸碎商店橱窗盗窃商品的行为）","usage":"复合名词，常用来描述针对商铺的快速抢劫行为"}]},{"word":"arcade","phonetic":"/ɑːˈkeɪd/","meanings":[{"pos":"noun","meaning":"拱廊；（两侧设有商店的）拱廊街道","usage":"指有拱顶的通道，两侧通常开设商铺"}]},{"word":"jewellery","phonetic":"/ˈdʒuːəlri/","meanings":[{"pos":"noun","meaning":"珠宝；首饰","usage":"不可数名词，统指各类珠宝首饰，美式英语常写作jewelry"}]},{"word":"admire","phonetic":"/ədˈmaɪə(r)/","meanings":[{"pos":"verb","meaning":"欣赏；赞赏；仰慕","usage":"后面可接名词或代词作宾语，常用搭配admire sb./sth."}]},{"word":"arrange","phonetic":"/əˈreɪndʒ/","meanings":[{"pos":"verb","meaning":"排列；布置；安排","usage":"可表示整理物品，也可表示安排活动、行程等"}]},{"word":"velvet","phonetic":"/ˈvelvɪt/","meanings":[{"pos":"noun","meaning":"天鹅绒；丝绒","usage":"不可数名词，指质地柔软的丝绒面料"}]},{"word":"gaze","phonetic":"/ɡeɪz/","meanings":[{"pos":"verb","meaning":"凝视；注视","usage":"强调长时间目不转睛地看，常用搭配gaze at sth./sb."}]},{"word":"blare","phonetic":"/bleə(r)/","meanings":[{"pos":"verb","meaning":"（喇叭、音乐等）发出响亮而刺耳的声音","usage":"常用来描述噪音大的声响，主语多为horn、speaker等"}]},{"word":"roar","phonetic":"/rɔː(r)/","meanings":[{"pos":"verb","meaning":"（车辆）呼啸而行；（猛兽）吼叫","usage":"可表示车辆高速行驶发出的轰鸣声，也可表示动物的咆哮"}]},{"word":"smash","phonetic":"/smæʃ/","meanings":[{"pos":"verb","meaning":"打碎；猛烈撞击","usage":"指用猛力将物体砸碎，常用搭配smash sth. with sth."}]},{"word":"raid","phonetic":"/reɪd/","meanings":[{"pos":"noun","meaning":"抢劫；突袭；搜查","usage":"可指劫匪的抢劫行动，也可指警方的突击搜查"}]},{"word":"scramble","phonetic":"/ˈskræmbl/","meanings":[{"pos":"verb","meaning":"迅速爬行；仓促行动","usage":"强调动作匆忙、慌乱，常用搭配scramble into/out of sth."}]},{"word":"fantastic","phonetic":"/fænˈtæstɪk/","meanings":[{"pos":"adjective","meaning":"极好的；难以置信的；极大的","usage":"可形容速度、数量等非常惊人，也可表达对事物的夸赞"}]},{"word":"ashtray","phonetic":"/ˈæʃtreɪ/","meanings":[{"pos":"noun","meaning":"烟灰缸","usage":"可数名词，由ash（烟灰）和tray（托盘）复合构成"}]},{"word":"statue","phonetic":"/ˈstætʃuː/","meanings":[{"pos":"noun","meaning":"雕像；塑像","usage":"指人物或动物的雕塑作品"}]}],"phrases":[{"phrase":"come to a stop","usage":"表示车辆、机器等逐渐停下，强调停止的过程，比stop更具画面感","examples":[{"en":"The bus came to a stop just in time to avoid hitting the child.","zh":"公交车及时停了下来，避免撞到那个孩子。"},{"en":"The engine sputtered and finally came to a stop.","zh":"引擎噼啪响了几声，最终停了下来。"}]},{"phrase":"help oneself to","usage":"指擅自取用、偷窃，也可礼貌邀请别人随意取用食物、物品等","examples":[{"en":"The intruder helped himself to all the cash in the safe.","zh":"闯入者偷走了保险箱里所有的现金。"},{"en":"Please help yourself to some drinks if you are thirsty.","zh":"如果你渴了请随便喝点饮料。"}]},{"phrase":"at a fantastic speed","usage":"形容速度极快，相当于at an extremely high speed","examples":[{"en":"The sports car drove past at a fantastic speed.","zh":"跑车以极快的速度开了过去。"},{"en":"The project is progressing at a fantastic speed.","zh":"这个项目正以惊人的速度推进。"}]},{"phrase":"get away with","usage":"表示偷了某物后成功逃脱，也可表示做了坏事却没有受到惩罚","examples":[{"en":"The burglars got away with jewellery worth over £100,000.","zh":"窃贼偷走了价值10万多英镑的珠宝，逃之夭夭。"},{"en":"Don't think you can get away with lying to me.","zh":"别以为你对我撒谎能蒙混过关。"}]},{"phrase":"with its headlights on","usage":"with的独立主格结构，用来描述伴随状态，结构为with + 宾语 + 宾补（形容词/副词/介词短语等）","examples":[{"en":"He stood in the rain, with his clothes completely wet.","zh":"他站在雨里，衣服全湿了。"},{"en":"She left the office, with the lights still on.","zh":"她离开了办公室，灯还亮着。"}]},{"phrase":"worth of","usage":"表示“价值……的东西”，结构为“金额/时间 + worth of + 名词”","examples":[{"en":"The storm caused thousands of pounds worth of damage.","zh":"风暴造成了价值数千英镑的损失。"},{"en":"I bought two weeks' worth of food before the holiday.","zh":"放假前我买了够吃两周的食物。"}]},{"phrase":"stay at the wheel","usage":"表示留在驾驶座上开车，wheel此处指代汽车的方向盘","examples":[{"en":"You stay at the wheel while I go into the shop to buy some water.","zh":"我去商店买水的时候你留在车里开车。"},{"en":"He stayed at the wheel for 6 hours before stopping to rest.","zh":"他连续开了6小时车才停下来休息。"}]}],"grammar":[{"title":"过去完成进行时","definition":"表示过去某个时间之前一直持续进行的动作，强调动作的持续性和连贯性，动作可能刚结束，也可能还在进行","structure":"had been + 动词现在分词（doing）","usage":"常和since+时间点、for+时间段等时间状语连用，描述在过去某个动作发生前已经持续了一段时间的动作","examples":[{"en":"Two of his assistants had been working busily since 8 o'clock and had only just finished.","zh":"他的两个助手从8点就一直在忙，刚刚才做完。"},{"en":"I had been waiting for the bus for half an hour when it finally arrived.","zh":"我已经等了半小时公交车，它才终于来。"},{"en":"He had been studying English for three years before he went abroad.","zh":"他出国前已经学了三年英语。"}]},{"title":"while引导的时间状语从句（过去进行时搭配）","definition":"while表示“当……的时候”，引导时间状语从句时，通常强调主从句的动作在过去同一时间段同时发生","structure":"While + 从句（过去进行时）, 主句（过去进行时/一般过去时）","usage":"从句的动作通常是延续性的，主从句动作同时发生时，延续性动作用过去进行时，短暂性动作用一般过去时","examples":[{"en":"While this was going on, Mr. Taylor was upstairs.","zh":"当这一切发生的时候，泰勒先生在楼上。"},{"en":"While I was cooking dinner, my husband was watching TV.","zh":"我做晚饭的时候，我丈夫在看电视。"},{"en":"While we were walking in the park, it began to rain.","zh":"我们在公园散步的时候，开始下雨了。"}]}],"patterns":[{"pattern":"The silence was suddenly broken when + 事件","explanation":"","original":{"en":"The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade.","zh":"宁静突然被打破，一辆大轿车亮着前灯，响着喇叭，呼啸着冲进了拱廊街。"},"examples":[{"en":"The silence was suddenly broken when a fire alarm went off in the building.","zh":"大楼里的火警突然响起，打破了宁静。"},{"en":"The silence was suddenly broken when a child started crying loudly in the library.","zh":"一个孩子在图书馆里大声哭了起来，宁静突然被打破。"}]},{"pattern":"Just as + 某事正在发生, 主语 + 动作","explanation":"","original":{"en":"Just as it was leaving, Mr.Taylor rushed out and ran after it throwing ashtrays and vases.","zh":"就在轿车离开的时候，泰勒先生冲了出来，跟在后面追赶，一边扔烟灰缸和花瓶。"},"examples":[{"en":"Just as the train was leaving, she arrived at the station out of breath.","zh":"就在火车要开的时候，她气喘吁吁地赶到了车站。"},{"en":"Just as I was taking a photo of the sunset, my phone died.","zh":"就在我要拍日落的时候，我的手机没电了。"}]},{"pattern":"..., for + 解释原因的句子","explanation":"","original":{"en":"The raid was all over in three minutes, for the men scrambled back into the car and it moved off at a fantastic speed.","zh":"抢劫行动总共只用了3分钟，因为那些人争先恐后地爬回车里，然后以极快的速度开走了。"},"examples":[{"en":"We decided to cancel the picnic, for the weather forecast said it would rain heavily.","zh":"我们决定取消野餐，因为天气预报说会下大雨。"},{"en":"He didn't attend the meeting, for he had caught a bad cold the day before.","zh":"他没有参加会议，因为前一天他得了重感冒。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“打碎；猛烈撞击” 对应的单词是？","hint":"verb · /smæʃ/","options":["safekeeping","sway","user-friendly","smash"],"answer":3,"explain":"smash · /smæʃ/ · verb · 打碎；猛烈撞击。指用猛力将物体砸碎，常用搭配smash sth. with sth.","source":{"kind":"vocab","word":"smash"},"id":"b3-u06-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：天鹅绒；丝绒","hint":"/ˈvelvɪt/ · noun","answer":"velvet","placeholder":"输入英文单词","explain":"velvet · /ˈvelvɪt/ · noun · 天鹅绒；丝绒。不可数名词，指质地柔软的丝绒面料","source":{"kind":"vocab","word":"velvet"},"id":"b3-u06-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The storm caused thousands of pounds _____ damage.","hint":"风暴造成了价值数千英镑的损失。","answer":"worth of","placeholder":"输入缺失的短语","explain":"worth of：表示“价值……的东西”，结构为“金额/时间 + worth of + 名词”（风暴造成了价值数千英镑的损失。）","source":{"kind":"phrase","phrase":"worth of"},"id":"b3-u06-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The expensive shops in a famous arcade near _____ were just opening.","hint":"靠近皮卡迪利大街的著名拱形建筑里的那些高档商店刚刚开门。","answer":"Piccadilly","placeholder":"输入缺失的单词","explain":"The expensive shops in a famous arcade near Piccadilly were just opening. — 靠近皮卡迪利大街的著名拱形建筑里的那些高档商店刚刚开门。","source":{"kind":"sentence","en":"The expensive shops in a famous arcade near Piccadilly were just opening."},"id":"b3-u06-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“while表示“当……的时候”，引导时间状语从句时，通常强调主从句的动作在过去同一时间段同时发生” 描述的是哪个语法点？","hint":"While + 从句（过去进行时）, 主句（过去进行时/一般过去时）","options":["while引导的时间状语从句（过去进行时搭配）","would rather ... than ... 结构","As引导的时间状语从句","used to 的用法"],"answer":0,"explain":"while引导的时间状语从句（过去进行时搭配）：While + 从句（过去进行时）, 主句（过去进行时/一般过去时）：从句的动作通常是延续性的，主从句动作同时发生时，延续性动作用过去进行时，短暂性动作用一般过去时","source":{"kind":"grammar","title":"while引导的时间状语从句（过去进行时搭配）"},"id":"b3-u06-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nChairs and tables went flying into the arcade.","hint":"","options":["但消防员最终通过在墙上凿开一个大洞，成功地解救了他。","他走进牢房，把信递给了贵族。","因为常常是早晨在一个地方发现美洲狮，晚上却在20英里以外的另一个地方发现它。","椅子和桌子飞进了拱形建筑。"],"answer":3,"explain":"Chairs and tables went flying into the arcade. — 椅子和桌子飞进了拱形建筑。","source":{"kind":"sentence","en":"Chairs and tables went flying into the arcade."},"id":"b3-u06-q06"}]},{"id":"b3-u07","book":3,"unit":7,"key":"07","lessonFrom":7,"lessonTo":7,"title":"Mutilated Ladies","titleZh":"残损的钞票","question":"Why did Jane cook John's wallet?","sentences":[{"en":"Has it ever happened to you?","zh":"你有过这种经历吗？","t":12.78},{"en":"Have you ever put your trousers in the washing machine and then remembered there was a large bank note in your back pocket?","zh":"你是否曾经把裤子放进洗衣机里，然后才想起你的后裤袋里有一张大额钞票？","t":15.17},{"en":"When you rescued your trousers, did you find the note was whiter than white?","zh":"当你把裤子拿出来时，是否发现那张钞票比雪还白？","t":23.29},{"en":"People who live in Britain needn't despair when they make mistakes like this (and a lot of people do)!","zh":"在英国居住的人们犯了这种错误不必绝望（而且很多人都会犯这种错误）！","t":29.1},{"en":"Fortunately for them, the Bank of England has a team called Mutilated Ladies","zh":"对他们来说幸运的是，英格兰银行有一个名为“残钞处理小组”的团队，","t":36.62},{"en":"which deals with claims from people who fed their money to a machine or to their dog.","zh":"处理那些把钱喂给机器或喂给狗的人提出的索赔。","t":42.32},{"en":"Dogs, it seems, love to chew up money!","zh":"看来狗很喜欢嚼钱！","t":48.62},{"en":"A recent case concerns Jane Butlin whose fiance, John, runs a successful furniture business.","zh":"最近有一件事是关于简·巴特林，她的未婚夫约翰经营着一家成功的家具公司。","t":52.94},{"en":"John had a very good day and put his wallet containing ￡3, 000 into the microwave oven for safekeeping.","zh":"约翰那天生意很好，就把装有3000英镑的钱包放进了微波炉里，以求安全。","t":61.06},{"en":"Then he and Jane went horse-riding.","zh":"然后他和简去骑马了。","t":69.99},{"en":"When they got home, Jane cooked their dinner in the microwave oven and without realizing it, cooked her fiance's wallet as well.","zh":"他们到家后，简在微波炉里做了晚餐，并且在不知不觉中，也把她未婚夫的钱包给煮了。","t":72.63},{"en":"Imagine their dismay when they found a beautifully-cooked wallet and notes turned to ash!","zh":"想象一下当他们发现一个“烹调精美”的钱包和变成灰烬的钞票时，他们的沮丧！","t":82.99},{"en":"John went to see his bank manager who sent the remains of wallet and the money","zh":"约翰去见了银行经理，经理把钱包和钱的残余部分","t":91.09},{"en":"to the special department of the Bank of England in Newcastle: the Mutilated Ladies!","zh":"送到了英格兰银行在纽卡斯尔的特别部门：残钞处理小组！","t":96.68},{"en":"They examined the remains and John got all his money back.","zh":"他们检查了残余物，约翰拿回了他所有的钱。","t":102.82},{"en":"'So long as there's something to identify, we will give people their money back,' said a spokeswoman for the Bank.","zh":"“只要有可识别的部分，我们就会把钱还给人们，”银行的一位女发言人说。","t":108.33},{"en":"'Last year, we paid ￡1.5 million on 21,000 claims.'","zh":"“去年，我们为21000份索赔支付了150万英镑。”","t":116.56}],"vocab":[{"word":"mutilate","phonetic":"/ˈmjuːtɪleɪt/","meanings":[{"pos":"verb","meaning":"使残缺不全；毁损","usage":"常指严重损坏物体的外观或完整性，也可指使身体致残"}]},{"word":"despair","phonetic":"/dɪˈspeə(r)/","meanings":[{"pos":"verb","meaning":"绝望；失去希望","usage":"常用结构：despair of (doing) sth 对做某事不抱希望"},{"pos":"noun","meaning":"绝望","usage":"不可数名词，常用搭配：in despair 陷入绝望"}]},{"word":"claim","phonetic":"/kleɪm/","meanings":[{"pos":"noun","meaning":"索赔；要求","usage":"常用搭配：make a claim for sth 就某物提出索赔"},{"pos":"verb","meaning":"索要；声称","usage":"后可接名词或that从句"}]},{"word":"fiance","phonetic":"/fiˈɒnseɪ/","meanings":[{"pos":"noun","meaning":"未婚夫","usage":"指已订婚的男性，对应的女性形式为fiancee"}]},{"word":"safekeeping","phonetic":"/ˌseɪfˈkiːpɪŋ/","meanings":[{"pos":"noun","meaning":"妥善保管，保存","usage":"不可数名词，常用搭配：for safekeeping 以妥善保管"}]},{"word":"dismay","phonetic":"/dɪsˈmeɪ/","meanings":[{"pos":"noun","meaning":"诧异；惊愕；失望","usage":"不可数名词，常用搭配：to one's dismay 令某人惊愕的是"}]},{"word":"ash","phonetic":"/æʃ/","meanings":[{"pos":"noun","meaning":"灰烬；废墟","usage":"表示“灰烬”时常用复数形式ashes，不可数名词"}]},{"word":"identify","phonetic":"/aɪˈdentɪfaɪ/","meanings":[{"pos":"verb","meaning":"识别，辨认出","usage":"后可直接接宾语，也可用于identify A as B 结构，指认出A是B"}]},{"word":"spokeswoman","phonetic":"/ˈspəʊkswʊmən/","meanings":[{"pos":"noun","meaning":"女发言人，女代言人","usage":"对应的男性形式为spokesman，复数形式为spokeswomen"}]},{"word":"concern","phonetic":"/kənˈsɜːn/","meanings":[{"pos":"verb","meaning":"涉及；关于","usage":"主语通常为事件、故事等，表示内容和某人/事相关"},{"pos":"verb","meaning":"使担忧","usage":"常用结构：be concerned about 担忧..."}]}],"phrases":[{"phrase":"deal with","usage":"表示“处理，应付”，后接问题、事件、人等作宾语","examples":[{"en":"The team deals with all kinds of customer complaints every day.","zh":"这个团队每天处理各种各样的客户投诉。"},{"en":"He is good at dealing with difficult situations.","zh":"他擅长应对困难局面。"}]},{"phrase":"turn to ash","usage":"表示“变成灰烬”，属于turn to sth的固定搭配，指转化为某种形态","examples":[{"en":"The old books turned to ash in the big fire.","zh":"那些旧书在大火中化成了灰烬。"},{"en":"All his hopes turned to ash when he heard the bad news.","zh":"听到这个坏消息时，他所有的希望都破灭了。"}]},{"phrase":"so long as","usage":"连词短语，引导条件状语从句，意为“只要”，相当于as long as","examples":[{"en":"So long as you work hard, you will pass the exam.","zh":"只要你努力学习，你就会通过考试。"},{"en":"We can go out so long as it doesn't rain.","zh":"只要不下雨，我们就可以出门。"}]},{"phrase":"for safekeeping","usage":"固定搭配，表示“为了妥善保管”，在句中作目的状语","examples":[{"en":"He gave his important documents to his lawyer for safekeeping.","zh":"他把自己的重要文件交给律师妥善保管。"},{"en":"I put the diamond necklace in the bank for safekeeping.","zh":"我把钻石项链放在银行妥善保存。"}]},{"phrase":"it seems (that)","usage":"常用表达，表示“似乎，看起来”，用于描述不确定的情况或主观推测","examples":[{"en":"It seems that no one knows what happened last night.","zh":"似乎没有人知道昨晚发生了什么。"},{"en":"It seems he is not interested in the plan at all.","zh":"看起来他对这个计划一点都不感兴趣。"}]}],"grammar":[{"title":"定语从句","definition":"在复合句中修饰名词或代词的从句，起到定语的作用，被修饰的词叫先行词，关系词连接先行词和从句","structure":"先行词 + 关系代词/关系副词 + 从句","usage":"当先行词是人时，常用who/that引导；先行词是物时，常用which/that引导；表示所属关系时用whose引导","examples":[{"en":"People who live in Britain needn't despair when they make mistakes like this.","zh":"犯了这类错误的英国人完全不必绝望。"},{"en":"A recent case concerns Jane Butlin whose fiance, John, runs a successful furniture business.","zh":"最近的一个案例与简·巴特林有关，她的未婚夫约翰经营着一家生意兴隆的家具店。"}]},{"title":"现在完成时的一般疑问句","definition":"用于询问到目前为止是否发生过某件事，常和ever等词搭配使用，强调经历","structure":"Have/Has + 主语 + ever + 动词过去分词 + 其他?","usage":"常用于询问对方是否有过某种经历，肯定回答用Yes, 主语+have/has，否定回答用No, 主语+haven't/hasn't","examples":[{"en":"Have you ever put your trousers in the washing machine and then remembered there was a large bank note in your back pocket?","zh":"你有没有过把裤子放进洗衣机，然后才想起后兜里还有一张大额钞票的经历？"},{"en":"Has she ever travelled abroad alone?","zh":"她有没有过独自出国旅行的经历？"}]}],"patterns":[{"pattern":"Have you ever done sth and then done sth else?","explanation":"","original":{"en":"Have you ever put your trousers in the washing machine and then remembered there was a large bank note in your back pocket?","zh":"你有没有过把裤子放进洗衣机，然后才想起后兜里还有一张大额钞票的经历？"},"examples":[{"en":"Have you ever fallen asleep in class and then woken up to find the teacher standing next to you?","zh":"你有没有过在课堂上睡着，醒来时发现老师就站在你旁边的经历？"},{"en":"Have you ever ordered a lot of food and then found you couldn't finish it?","zh":"你有没有过点了很多食物，结果发现自己吃不完的经历？"}]},{"pattern":"Sb needn't despair when...","explanation":"","original":{"en":"People who live in Britain needn't despair when they make mistakes like this.","zh":"犯了这类错误的英国人完全不必绝望。"},"examples":[{"en":"You needn't despair when you meet difficulties in learning English.","zh":"你在学习英语时遇到困难不必绝望。"},{"en":"We needn't despair when the experiment fails the first time.","zh":"第一次实验失败的时候我们不必绝望。"}]},{"pattern":"So long as..., sb will do sth.","explanation":"","original":{"en":"So long as there's something to identify, we will give people their money back.","zh":"只要还有可以识别的东西，我们就会把钱还给当事人。"},"examples":[{"en":"So long as you keep trying, you will achieve your goal sooner or later.","zh":"只要你不断尝试，你迟早会实现目标的。"},{"en":"So long as we finish the work before Friday, we can have a three-day holiday.","zh":"只要我们在周五前完成工作，我们就可以放三天假。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“涉及；关于” 对应的单词是？","hint":"verb · /kənˈsɜːn/","options":["gesticulate","concern","grievance","scramble"],"answer":1,"explain":"concern · /kənˈsɜːn/ · verb · 涉及；关于。主语通常为事件、故事等，表示内容和某人/事相关","source":{"kind":"vocab","word":"concern"},"id":"b3-u07-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：女发言人，女代言人","hint":"/ˈspəʊkswʊmən/ · noun","answer":"spokeswoman","placeholder":"输入英文单词","explain":"spokeswoman · /ˈspəʊkswʊmən/ · noun · 女发言人，女代言人。对应的男性形式为spokesman，复数形式为spokeswomen","source":{"kind":"vocab","word":"spokeswoman"},"id":"b3-u07-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：I put the diamond necklace in the bank _____.","hint":"我把钻石项链放在银行妥善保存。","answer":"for safekeeping","placeholder":"输入缺失的短语","explain":"for safekeeping：固定搭配，表示“为了妥善保管”，在句中作目的状语（我把钻石项链放在银行妥善保存。）","source":{"kind":"phrase","phrase":"for safekeeping"},"id":"b3-u07-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Imagine their dismay when they found a _____ wallet and notes turned to ash!","hint":"想象一下当他们发现一个“烹调精美”的钱包和变成灰烬的钞票时，他们的沮丧！","answer":"beautifully-cooked","placeholder":"输入缺失的单词","explain":"Imagine their dismay when they found a beautifully-cooked wallet and notes turned to ash! — 想象一下当他们发现一个“烹调精美”的钱包和变成灰烬的钞票时，他们的沮丧！","source":{"kind":"sentence","en":"Imagine their dismay when they found a beautifully-cooked wallet and notes turned to ash!"},"id":"b3-u07-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于询问到目前为止是否发生过某件事，常和ever等词搭配使用，强调经历” 描述的是哪个语法点？","hint":"Have/Has + 主语 + ever + 动词过去分词 + 其他?","options":["现在完成时的一般疑问句","either...or...并列连词结构","虚拟语气在条件状语从句中的用法（与过去事实相反）","定冠词the的特指用法 (Definite Article 'the' for Specific Reference)"],"answer":0,"explain":"现在完成时的一般疑问句：Have/Has + 主语 + ever + 动词过去分词 + 其他?：常用于询问对方是否有过某种经历，肯定回答用Yes, 主语+have/has，否定回答用No, 主语+haven't/hasn't","source":{"kind":"grammar","title":"现在完成时的一般疑问句"},"id":"b3-u07-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThen he and Jane went horse-riding.","hint":"","options":["这些平台延伸到海面以下100多英尺的深度。","然后他和简去骑马了。","一个糟糕的冬天，我们看着河水悄悄漫上了低洼的草地。","由当时一家名为微软的小公司开发。"],"answer":1,"explain":"Then he and Jane went horse-riding. — 然后他和简去骑马了。","source":{"kind":"sentence","en":"Then he and Jane went horse-riding."},"id":"b3-u07-q06"}]},{"id":"b3-u08","book":3,"unit":8,"key":"08","lessonFrom":8,"lessonTo":8,"title":"A Famous Monastery","titleZh":"一座著名的修道院","question":"What are the St.Bernard dogs used for?","sentences":[{"en":"The Great St.Bernard Pass connects Switzerland to Italy.","zh":"大圣伯纳山口连接着瑞士和意大利。","t":15.03},{"en":"At 2,473 metres, it is the highest mountain pass in Europe.","zh":"它海拔2473米，是欧洲最高的山口。","t":20.49},{"en":"The famous monastery of St.Bernard,","zh":"著名的圣伯纳修道院，","t":28.15},{"en":"which was founded in the eleventh century, lies about a mile away.","zh":"建立于11世纪，距此约一英里。","t":31.71},{"en":"For hundreds of years, St.Bernard dogs have saved the lives of travellers crossing the dangerous Pass.","zh":"数百年来，圣伯纳狗一直在拯救穿越这个危险山口的旅行者的生命。","t":36.95},{"en":"These friendly dogs, which were first brought from Asia,","zh":"这些友善的狗，最初从亚洲引进，","t":44.64},{"en":"were used as watchdogs even in Roman times.","zh":"甚至在罗马时代就被用作看门狗。","t":49.2},{"en":"Now that a tunnel has been built through the mountains, the Pass is less dangerous,","zh":"如今，随着一条穿山隧道的建成，这个山口不再那么危险了，","t":53.39},{"en":"but each year, the dogs are still sent out into the snow whenever a traveller is in difficulty.","zh":"但是每年，只要有旅行者遇到困难，这些狗仍然会被派出去在雪地里搜救。","t":58.92},{"en":"Despite the new tunnel,","zh":"尽管有了新隧道，","t":66.32},{"en":"there are still a few people who rashly attempt to cross the Pass on foot.","zh":"仍然有一些人冒险徒步穿越山口。","t":67.93},{"en":"During the summer months, the monastery is very busy,","zh":"在夏季，修道院非常繁忙，","t":74.69},{"en":"for it is visited by thousands of people who cross the Pass in cars.","zh":"因为成千上万驾车穿越山口的人会来这里参观。","t":78.3},{"en":"As there are so many people about, the dogs have to be kept in a special enclosure.","zh":"由于人太多，狗必须被关在一个特殊的围栏里。","t":84.01},{"en":"In winter, however, life at the monastery is quite different.","zh":"然而，在冬天，修道院的生活则截然不同。","t":90.32},{"en":"The temperature drops to -30 degrees,","zh":"气温降至零下30度，","t":95.72},{"en":"and very few people attempt to cross the Pass.","zh":"很少有人尝试穿越山口。","t":98.73},{"en":"The monks prefer winter to summer for they have more privacy.","zh":"僧侣们更喜欢冬天而不是夏天，因为他们有更多的隐私。","t":102.74},{"en":"The dogs have greater freedom, too,","zh":"狗也有更大的自由，","t":107.68},{"en":"for they are allowed to wander outside their enclosure.","zh":"因为它们被允许在围栏外自由漫步。","t":110.39},{"en":"The only regular visitors to the monastery in winter are parties of skiers who go there at Christmas and Easter.","zh":"冬季修道院唯一的常客是圣诞节和复活节前往那里的滑雪者们。","t":113.92},{"en":"These young people,","zh":"这些年轻人，","t":122.36},{"en":"who love the peace of the mountains,","zh":"热爱山间的宁静，","t":124.34},{"en":"always receive a warm welcome at St.Bernard's monastery.","zh":"总能在圣伯纳修道院受到热烈的欢迎。","t":126.56}],"vocab":[{"word":"monastery","phonetic":"/ˈmɒnəstri/","meanings":[{"pos":"noun","meaning":"修道院；寺院","usage":"指修道士、僧侣居住和进行宗教活动的场所"}]},{"word":"pass","phonetic":"/pɑːs/","meanings":[{"pos":"noun","meaning":"山口；关隘","usage":"指山脉中可供通行的狭窄通道"},{"pos":"verb","meaning":"通过；经过","usage":"表示从一个地方移动到另一个地方的动作"}]},{"word":"connect","phonetic":"/kəˈnekt/","meanings":[{"pos":"verb","meaning":"连接；相连","usage":"常用搭配connect A to/with B，表示把A和B连接起来"}]},{"word":"found","phonetic":"/faʊnd/","meanings":[{"pos":"verb","meaning":"创建；建立","usage":"为及物动词，通常表示创立组织、机构等，过去式和过去分词为founded"}]},{"word":"traveller","phonetic":"/ˈtrævələ(r)/","meanings":[{"pos":"noun","meaning":"旅行者；游客","usage":"指长途旅行的人，美式拼写为traveler"}]},{"word":"watchdog","phonetic":"/ˈwɒtʃdɒɡ/","meanings":[{"pos":"noun","meaning":"看门狗；监察人","usage":"既可以指看门的犬只，也可比喻监督公共事务的个人或组织"}]},{"word":"tunnel","phonetic":"/ˈtʌnl/","meanings":[{"pos":"noun","meaning":"隧道；地道","usage":"指在山体、地下或海底开凿的通道"}]},{"word":"rashly","phonetic":"/ˈræʃli/","meanings":[{"pos":"adverb","meaning":"轻率地；鲁莽地","usage":"用来修饰动词，表示做事情没有经过慎重考虑"}]},{"word":"attempt","phonetic":"/əˈtempt/","meanings":[{"pos":"verb","meaning":"尝试；试图","usage":"常用搭配attempt to do sth，表示努力做有难度的事"},{"pos":"noun","meaning":"尝试；企图","usage":"常用搭配make an attempt to do sth"}]},{"word":"enclosure","phonetic":"/ɪnˈkləʊʒə(r)/","meanings":[{"pos":"noun","meaning":"围场；圈地","usage":"指用栅栏、围墙等围起来的区域"}]},{"word":"temperature","phonetic":"/ˈtemprətʃə(r)/","meanings":[{"pos":"noun","meaning":"温度；气温","usage":"表示天气或物体的冷热程度，常用搭配take one's temperature指量体温"}]},{"word":"monk","phonetic":"/mʌŋk/","meanings":[{"pos":"noun","meaning":"修道士；僧侣","usage":"指男性修行者，对应女性修行者为nun（修女）"}]},{"word":"privacy","phonetic":"/ˈprɪvəsi/","meanings":[{"pos":"noun","meaning":"隐私；独处","usage":"表示不受他人打扰的私人空间或状态"}]},{"word":"wander","phonetic":"/ˈwɒndə(r)/","meanings":[{"pos":"verb","meaning":"漫步；闲逛","usage":"表示没有固定方向地随意行走"}]},{"word":"skier","phonetic":"/ˈskiːə(r)/","meanings":[{"pos":"noun","meaning":"滑雪者","usage":"指进行滑雪运动的人，动词形式为ski"}]}],"phrases":[{"phrase":"now that","usage":"引导原因状语从句，意为“既然；由于”，表示已知的事实或新出现的情况","examples":[{"en":"Now that a tunnel has been built through the mountains, the Pass is less dangerous.","zh":"由于已经修建了一条穿山隧道，山口现在不那么危险了。"},{"en":"Now that you have finished your homework, you can watch TV for a while.","zh":"既然你已经做完了作业，你可以看一会儿电视。"}]},{"phrase":"send out","usage":"动词短语，意为“派出；发出”，可接人或物作宾语","examples":[{"en":"The dogs are still sent out into the snow whenever a traveller is in difficulty.","zh":"每当有旅行者遇到困难时，这些狗仍然会被派到雪地里去。"},{"en":"The rescue team sent out three groups to search for the missing climber.","zh":"救援队派出了三个小组搜寻失踪的登山者。"}]},{"phrase":"in difficulty","usage":"介词短语，意为“处于困境中”，在句中可作表语或后置定语","examples":[{"en":"We should give a hand to those who are in difficulty.","zh":"我们应该帮助那些身处困境的人。"}]},{"phrase":"despite","usage":"介词，意为“尽管；虽然”，后接名词、代词或动名词，引导让步关系","examples":[{"en":"Despite the new tunnel, there are still a few people who rashly attempt to cross the Pass on foot.","zh":"尽管有了新隧道，仍然有少数人鲁莽地试图步行穿越山口。"},{"en":"Despite the bad weather, we still held the sports meeting as planned.","zh":"尽管天气不好，我们仍然按计划举办了运动会。"}]},{"phrase":"attempt to do sth","usage":"动词搭配，意为“试图做某事；尝试做某事”，常指做有难度或风险的事","examples":[{"en":"Very few people attempt to cross the Pass in winter.","zh":"冬天很少有人试图穿越山口。"},{"en":"He attempted to climb the mountain alone, but failed due to the storm.","zh":"他试图独自攀登那座山，但因为暴风雨失败了。"}]},{"phrase":"prefer A to B","usage":"动词搭配，意为“比起B更喜欢A”，用于表达两者间的偏好","examples":[{"en":"The monks prefer winter to summer for they have more privacy.","zh":"修道士们喜欢冬天胜过夏天，因为他们有更多的独处时间。"},{"en":"I prefer coffee to tea when I need to stay up late working.","zh":"我需要熬夜工作的时候，比起茶更喜欢喝咖啡。"}]},{"phrase":"be allowed to do sth","usage":"被动语态搭配，意为“被允许做某事”，表示得到许可做某件事","examples":[{"en":"The dogs are allowed to wander outside their enclosure in winter.","zh":"冬天狗被允许在围场外面闲逛。"},{"en":"Students are not allowed to use mobile phones in class in most schools.","zh":"大多数学校不允许学生在课堂上使用手机。"}]},{"phrase":"receive a warm welcome","usage":"固定搭配，意为“受到热烈欢迎”","examples":[{"en":"These young people always receive a warm welcome at St.Bernard's monastery.","zh":"这些年轻人在圣伯纳德修道院总是受到热烈欢迎。"},{"en":"The foreign visitors received a warm welcome when they arrived at the university.","zh":"外国访客抵达这所大学时受到了热烈欢迎。"}]}],"grammar":[{"title":"非限制性定语从句","definition":"对先行词进行补充说明，去掉之后不影响主句意思的完整性，和主句之间通常用逗号隔开","structure":"主句 + , + which/who/whom/whose + 从句","usage":"which指代物，who指代人，在从句中作主语或宾语，不能用that引导","examples":[{"en":"The famous monastery of St.Bernard, which was founded in the eleventh century, lies about a mile away.","zh":"著名的圣伯纳德修道院建于11世纪，位于（离山口）约一英里远的地方。"},{"en":"These friendly dogs, which were first brought from Asia, were used as watchdogs even in Roman times.","zh":"这些友善的狗最初是从亚洲引进的，甚至在罗马时期就被用作看门狗。"},{"en":"My elder sister, who works in Shanghai, will come back home next week.","zh":"我姐姐在上海工作，她下周会回家。"}]},{"title":"原因状语从句引导词for的用法","definition":"for是并列连词，用来补充说明前一句内容的原因，语气比because弱，不能放在句首","structure":"主句 + for + 原因分句","usage":"通常用于书面语，对前面的事实进行解释说明，前后两个分句是并列关系","examples":[{"en":"During the summer months, the monastery is very busy, for it is visited by thousands of people who cross the Pass in cars.","zh":"夏天的几个月里，修道院十分忙碌，因为有成千上万开车穿越山口的人来这里参观。"},{"en":"The dogs have greater freedom, too, for they are allowed to wander outside their enclosure.","zh":"狗也有更多的自由，因为它们被允许在围场外面闲逛。"},{"en":"He stayed up late last night, for he had to finish his report before the deadline.","zh":"他昨晚熬夜了，因为他得在截止日期前完成报告。"}]}],"patterns":[{"pattern":"At + 具体高度/年龄/价格, it is + 最高级 + 范围","explanation":"","original":{"en":"At 2,473 metres, it is the highest mountain pass in Europe.","zh":"它海拔2473米，是欧洲最高的山口。"},"examples":[{"en":"At 8,848 metres, Mount Qomolangma is the highest mountain in the world.","zh":"珠穆朗玛峰海拔8848米，是世界上最高的山峰。"},{"en":"At 14 years old, he is the youngest player in the national football team.","zh":"他14岁，是国家足球队里最年轻的球员。"}]},{"pattern":"For + 时间段, sth/sb have done sth","explanation":"","original":{"en":"For hundreds of years, St.Bernard dogs have saved the lives of travellers crossing the dangerous Pass.","zh":"数百年来，圣伯纳德狗拯救了穿越危险山口的旅行者的生命。"},"examples":[{"en":"For thousands of years, Chinese people have created splendid traditional culture.","zh":"数千年来，中国人民创造了灿烂的传统文化。"},{"en":"For nearly 10 years, this little library has provided free books for children in the village.","zh":"近十年来，这个小图书馆一直为村里的孩子提供免费书籍。"}]},{"pattern":"In winter/In summer, however, life + 地点 + is quite different.","explanation":"","original":{"en":"In winter, however, life at the monastery is quite different.","zh":"然而到了冬天，修道院的生活就完全不同了。"},"examples":[{"en":"In summer, however, life in this small coastal town is quite different.","zh":"然而到了夏天，这个海滨小镇的生活就完全不同了。"},{"en":"On weekends, however, life in the office building is quite different.","zh":"然而到了周末，这座办公楼里的生活就完全不同了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“尝试；试图” 对应的单词是？","hint":"verb · /əˈtempt/","options":["offer","vessel","uncrumpled","attempt"],"answer":3,"explain":"attempt · /əˈtempt/ · verb · 尝试；试图。常用搭配attempt to do sth，表示努力做有难度的事","source":{"kind":"vocab","word":"attempt"},"id":"b3-u08-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：看门狗；监察人","hint":"/ˈwɒtʃdɒɡ/ · noun","answer":"watchdog","placeholder":"输入英文单词","explain":"watchdog · /ˈwɒtʃdɒɡ/ · noun · 看门狗；监察人。既可以指看门的犬只，也可比喻监督公共事务的个人或组织","source":{"kind":"vocab","word":"watchdog"},"id":"b3-u08-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：We should give a hand to those who are _____.","hint":"我们应该帮助那些身处困境的人。","answer":"in difficulty","placeholder":"输入缺失的短语","explain":"in difficulty：介词短语，意为“处于困境中”，在句中可作表语或后置定语（我们应该帮助那些身处困境的人。）","source":{"kind":"phrase","phrase":"in difficulty"},"id":"b3-u08-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：At 2,473 metres, it is the highest mountain _____ in Europe.","hint":"它海拔2473米，是欧洲最高的山口。","answer":"pass","placeholder":"输入缺失的单词","explain":"At 2,473 metres, it is the highest mountain pass in Europe. — 它海拔2473米，是欧洲最高的山口。","source":{"kind":"sentence","en":"At 2,473 metres, it is the highest mountain pass in Europe."},"id":"b3-u08-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“对先行词进行补充说明，去掉之后不影响主句意思的完整性，和主句之间通常用逗号隔开” 描述的是哪个语法点？","hint":"主句 + , + which/who/whom/whose + 从句","options":["非限制性定语从句","形式主语it (Formal Subject It)","过去分词短语作状语","否定副词开头的倒装句 (Inversion with Negative Adverbs)"],"answer":0,"explain":"非限制性定语从句：主句 + , + which/who/whom/whose + 从句：which指代物，who指代人，在从句中作主语或宾语，不能用that引导","source":{"kind":"grammar","title":"非限制性定语从句"},"id":"b3-u08-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe Great St.Bernard Pass connects Switzerland to Italy.","hint":"","options":["某个地方，在深草丛中埋着一台生锈的割草机，我曾承诺有一天会把它修好。","尽管他们盛赞宁静生活的种种好处，","大圣伯纳山口连接着瑞士和意大利。","我费尽心思整理好的所有东西很快就乱七八糟了。"],"answer":2,"explain":"The Great St.Bernard Pass connects Switzerland to Italy. — 大圣伯纳山口连接着瑞士和意大利。","source":{"kind":"sentence","en":"The Great St.Bernard Pass connects Switzerland to Italy."},"id":"b3-u08-q06"}]},{"id":"b3-u09","book":3,"unit":9,"key":"09","lessonFrom":9,"lessonTo":9,"title":"Flying Cats","titleZh":"会飞的猫","question":"How do cats try to protect themselves when falling from great heights?","sentences":[{"en":"Cats never fail to fascinate human beings.","zh":"猫总是能吸引人类。","t":17.34},{"en":"They can be friendly and affectionate towards humans, but they lead mysterious lives of their own as well.","zh":"它们可以对人类友好和亲热，但它们也有自己的神秘生活。","t":21.77},{"en":"They never become submissive like dogs and horses.","zh":"它们从不像狗和马那样变得顺从。","t":29.47},{"en":"As a result, humans have learned to respect feline independence.","zh":"结果，人类学会了尊重猫的独立性。","t":33.63},{"en":"Most cats remain suspicious of humans all their lives.","zh":"大多数猫一生都对人类保持警惕。","t":39.36},{"en":"One of the things that fascinates us most about cats is the popular belief that they have nine lives.","zh":"关于猫最吸引我们的一点是，人们普遍认为它们有九条命。","t":43.91},{"en":"Apparently, there is a good deal of truth in this idea.","zh":"显然，这种说法有相当多的真实性。","t":51.86},{"en":"A cat's ability to survive falls is based on fact.","zh":"猫从高处跌落后幸存的能力是有事实依据的。","t":57.69},{"en":"Recently the New York Animal Medical Centre made a study of 132 cats over a period of five months.","zh":"最近，纽约动物医疗中心对132只猫进行了为期五个月的研究。","t":63.18},{"en":"All these cats had one experience in common: they had fallen off high buildings,","zh":"所有这些猫都有一个共同的经历：它们都从高楼上跌落过，","t":73},{"en":"yet only eight of them died from shock or injuries.","zh":"然而只有八只死于休克或受伤。","t":77.88},{"en":"Of course, New York is the ideal place for such an interesting study, because there is no shortage of tall buildings.","zh":"当然，纽约是进行这项有趣研究的理想地点，因为那里不缺少高楼大厦。","t":84.07},{"en":"There are plenty of high-rise windowsills to fall from!","zh":"有很多高层窗台可供跌落！","t":93.79},{"en":"One cat, Sabrina, fell 32 storeys, yet only suffered from a broken tooth.","zh":"一只名叫萨布丽娜的猫从32层楼高的地方摔下，却只受了牙齿折断的伤。","t":98.48},{"en":"'Cats behave like well-trained paratroopers,' a doctor said.","zh":"“猫的行为就像训练有素的伞兵，”一位医生说。","t":106.89},{"en":"It seems that the further cats fall, the less they are likely to injure themselves.","zh":"猫似乎跌落得越远，受伤的可能性就越小。","t":112.15},{"en":"In a long drop, they reach speeds of 60 miles an hour and more.","zh":"在长距离跌落中，它们的速度可达每小时60英里甚至更高。","t":119.16},{"en":"At high speeds, falling cats have time to relax.","zh":"在高速跌落时，猫有时间放松。","t":125.01},{"en":"They stretch out their legs like flying squirrels.","zh":"它们像飞鼠一样伸展四肢。","t":129.23},{"en":"This increases their air-resistance and reduces the shock of impact when they hit the ground.","zh":"这增加了它们的空气阻力，并减少了它们撞击地面时的冲击。","t":133.69}],"vocab":[{"word":"fascinate","phonetic":"/ˈfæsɪneɪt/","meanings":[{"pos":"verb","meaning":"深深吸引；迷住","usage":"主语可以是人或事物，常用搭配：sth fascinates sb 某物吸引某人；be fascinated by/with 被……吸引"}]},{"word":"affectionate","phonetic":"/əˈfekʃənət/","meanings":[{"pos":"adjective","meaning":"充满爱的；亲切的","usage":"常用于描述人或动物的态度，常用搭配：be affectionate towards sb 对某人亲切友爱"}]},{"word":"mysterious","phonetic":"/mɪˈstɪəriəs/","meanings":[{"pos":"adjective","meaning":"神秘的；难以解释的","usage":"可修饰人、事物或现象，用来描述不为人知的特性"}]},{"word":"submissive","phonetic":"/səbˈmɪsɪv/","meanings":[{"pos":"adjective","meaning":"顺从的；服从的","usage":"常用来描述人或动物愿意服从他人指令的状态，搭配：be submissive to sb 对某人顺从"}]},{"word":"feline","phonetic":"/ˈfiːlaɪn/","meanings":[{"pos":"adjective","meaning":"猫科的；猫似的","usage":"多用于正式语境修饰和猫相关的特性，也可作名词表示“猫科动物”"}]},{"word":"independence","phonetic":"/ˌɪndɪˈpendəns/","meanings":[{"pos":"noun","meaning":"独立；自主","usage":"不可数名词，常见搭配：gain independence 获得独立；respect one's independence 尊重某人的独立性"}]},{"word":"suspicious","phonetic":"/səˈspɪʃəs/","meanings":[{"pos":"adjective","meaning":"怀疑的；可疑的","usage":"常用搭配：be suspicious of sb/sth 对某人/某物心存怀疑"}]},{"word":"apparently","phonetic":"/əˈpærəntli/","meanings":[{"pos":"adverb","meaning":"显然；看来","usage":"多用于句首或句中，说明根据现有情况得出的明显结论"}]},{"word":"survive","phonetic":"/səˈvaɪv/","meanings":[{"pos":"verb","meaning":"幸存；活下来","usage":"可作及物动词直接接宾语（survive sth 从某事故中幸存），也可作不及物动词"}]},{"word":"ideal","phonetic":"/aɪˈdiːəl/","meanings":[{"pos":"adjective","meaning":"理想的；完美的","usage":"常用搭配：be ideal for sth/sb 对某事/某人来说是理想的"}]},{"word":"shortage","phonetic":"/ˈʃɔːtɪdʒ/","meanings":[{"pos":"noun","meaning":"不足；短缺","usage":"可数/不可数名词，搭配：shortage of sth 某物短缺；no shortage of 不缺少……"}]},{"word":"paratrooper","phonetic":"/ˈpærətruːpə(r)/","meanings":[{"pos":"noun","meaning":"伞兵","usage":"可数名词，指受过跳伞训练的军人"}]},{"word":"resistance","phonetic":"/rɪˈzɪstəns/","meanings":[{"pos":"noun","meaning":"抵抗力；阻力","usage":"不可数名词，常用搭配：air resistance 空气阻力；resistance to sth 对……的抵抗力"}]},{"word":"impact","phonetic":"/ˈɪmpækt/","meanings":[{"pos":"noun","meaning":"冲击力；影响","usage":"表示“冲击力”时为不可数，表“影响”时可数/不可数，搭配：impact of sth 某物的影响；shock of impact 撞击冲击"}]}],"phrases":[{"phrase":"never fail to","usage":"双重否定结构，加强肯定语气，意为“一定会；从未不”，语气比直接用肯定形式更强烈","examples":[{"en":"Cats never fail to fascinate human beings.","zh":"猫总能引起人类的极大兴趣。"},{"en":"She never fails to call her parents every weekend.","zh":"她每个周末一定会给父母打电话。"}]},{"phrase":"be based on","usage":"表示“以……为基础；基于……”，主语通常为理论、故事、结论等抽象事物","examples":[{"en":"A cat's ability to survive falls is based on fact.","zh":"猫在坠落中存活的能力是有事实依据的。"},{"en":"The movie is based on a real historical event.","zh":"这部电影是基于真实历史事件改编的。"}]},{"phrase":"have sth in common","usage":"表示“有共同之处”，可接介词with表示“和某人/某物有共同点”","examples":[{"en":"All these cats had one experience in common: they had fallen off high buildings.","zh":"所有这些猫都有一个共同的经历：它们都曾从高楼上掉下来过。"},{"en":"The two sisters have nothing in common in terms of hobbies.","zh":"这两姐妹在爱好方面没有任何共同点。"}]},{"phrase":"die from","usage":"表示“死于（外部原因，如事故、伤害等）”，区别于die of（多用于死于内部疾病、情感等）","examples":[{"en":"Only eight of them died from shock or injuries.","zh":"它们中只有8只死于休克或受伤。"},{"en":"Many people in the accident died from serious burns.","zh":"事故中的很多人死于严重烧伤。"}]},{"phrase":"no shortage of","usage":"表示“不缺少；充足的”，后接可数名词复数或不可数名词","examples":[{"en":"There is no shortage of tall buildings in New York.","zh":"纽约不缺高楼大厦。"},{"en":"There is no shortage of talented young people in this industry.","zh":"这个行业里不缺有天赋的年轻人。"}]},{"phrase":"suffer from","usage":"表示“遭受；患有（疾病、伤痛等）”，后接具体的病痛、困难等名词","examples":[{"en":"Sabrina fell 32 storeys, yet only suffered from a broken tooth.","zh":"萨布丽娜从32层楼掉下来，却只断了一颗牙。"},{"en":"Many office workers suffer from back pain these days.","zh":"现在很多上班族都有背痛的问题。"}]},{"phrase":"stretch out","usage":"表示“伸展；伸开（肢体）”，可接宾语也可单独使用","examples":[{"en":"They stretch out their legs like flying squirrels.","zh":"它们把腿伸展开，就像飞鼠一样。"},{"en":"He stretched out on the sofa and fell asleep soon.","zh":"他在沙发上舒展身体，很快就睡着了。"}]}],"grammar":[{"title":"the + 比较级, the + 比较级 结构","definition":"表示“越……，就越……”，用于描述两个变化过程的相关性","structure":"The + 形容词/副词比较级 + 句子，the + 形容词/副词比较级 + 句子","usage":"第一个句子相当于条件状语，第二个句子是结果，语序通常为陈述语序，口语中可省略和主句相同的成分","examples":[{"en":"It seems that the further cats fall, the less they are likely to injure themselves.","zh":"看起来猫坠落的距离越远，它们受伤的可能性就越小。"},{"en":"The harder you work, the more progress you will make.","zh":"你越努力，取得的进步就越大。"}]},{"title":"It seems that 主语从句结构","definition":"用于表达不确定的判断或看起来的情况，意为“似乎；看起来好像”","structure":"It seems that + 完整的陈述句","usage":"it为形式主语，真正的主语是that引导的从句，可与sb/sth seems to do 结构互相转换","examples":[{"en":"It seems that there is a good deal of truth in this idea.","zh":"这种说法似乎有不少道理。"},{"en":"It seems that he has already known the news.","zh":"他好像已经知道这个消息了。"}]}],"patterns":[{"pattern":"... never fail to ...","explanation":"","original":{"en":"Cats never fail to fascinate human beings.","zh":"猫总能引起人类的极大兴趣。"},"examples":[{"en":"Traditional Chinese festivals never fail to remind people of their family.","zh":"中国传统节日总能让人们想起自己的家人。"},{"en":"This movie never fails to make me cry every time I watch it.","zh":"我每次看这部电影都会被弄哭。"}]},{"pattern":"One of the things that fascinates us most about ... is the popular belief that ...","explanation":"","original":{"en":"One of the things that fascinates us most about cats is the popular belief that they have nine lives.","zh":"关于猫，最让我们着迷的一点是人们普遍认为它们有九条命。"},"examples":[{"en":"One of the things that fascinates us most about pandas is the popular belief that they are always gentle and cute.","zh":"关于熊猫，最让我们着迷的一点是人们普遍认为它们总是温顺可爱的。"},{"en":"One of the things that attracts visitors most about this city is the popular belief that it is a paradise for food lovers.","zh":"关于这座城市，最吸引游客的一点是大家普遍认为它是美食爱好者的天堂。"}]},{"pattern":"... make a study of ... over a period of ...","explanation":"","original":{"en":"Recently the New York Animal Medical Centre made a study of 132 cats over a period of five months.","zh":"最近纽约动物医疗中心对132只猫进行了为期五个月的研究。"},"examples":[{"en":"The research team made a study of 500 primary school students over a period of two years.","zh":"该研究团队对500名小学生进行了为期两年的研究。"},{"en":"The company made a study of consumers' habits over a period of six months.","zh":"该公司对消费者的习惯进行了为期六个月的研究。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“幸存；活下来” 对应的单词是？","hint":"verb · /səˈvaɪv/","options":["float","consequence","editor","survive"],"answer":3,"explain":"survive · /səˈvaɪv/ · verb · 幸存；活下来。可作及物动词直接接宾语（survive sth 从某事故中幸存），也可作不及物动词","source":{"kind":"vocab","word":"survive"},"id":"b3-u09-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：冲击力；影响","hint":"/ˈɪmpækt/ · noun","answer":"impact","placeholder":"输入英文单词","explain":"impact · /ˈɪmpækt/ · noun · 冲击力；影响。表示“冲击力”时为不可数，表“影响”时可数/不可数，搭配：impact of sth 某物的影响；shock of impact 撞击冲击","source":{"kind":"vocab","word":"impact"},"id":"b3-u09-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Cats _____ fascinate human beings.","hint":"猫总能引起人类的极大兴趣。","answer":"never fail to","placeholder":"输入缺失的短语","explain":"never fail to：双重否定结构，加强肯定语气，意为“一定会；从未不”，语气比直接用肯定形式更强烈（猫总能引起人类的极大兴趣。）","source":{"kind":"phrase","phrase":"never fail to"},"id":"b3-u09-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：In a long drop, they reach speeds of 60 miles an hour and _____","hint":"在长距离跌落中，它们的速度可达每小时60英里甚至更高。","answer":"more","placeholder":"输入缺失的单词","explain":"In a long drop, they reach speeds of 60 miles an hour and more. — 在长距离跌落中，它们的速度可达每小时60英里甚至更高。","source":{"kind":"sentence","en":"In a long drop, they reach speeds of 60 miles an hour and more."},"id":"b3-u09-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示“越……，就越……”，用于描述两个变化过程的相关性” 描述的是哪个语法点？","hint":"The + 形容词/副词比较级 + 句子，the + 形容词/副词比较级 + 句子","options":["nor/neither...nor 的倒装用法","While 引导的让步状语从句","should have done 结构","the + 比较级, the + 比较级 结构"],"answer":3,"explain":"the + 比较级, the + 比较级 结构：The + 形容词/副词比较级 + 句子，the + 形容词/副词比较级 + 句子：第一个句子相当于条件状语，第二个句子是结果，语序通常为陈述语序，口语中可省略和主句相同的成分","source":{"kind":"grammar","title":"the + 比较级, the + 比较级 结构"},"id":"b3-u09-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nCats never fail to fascinate human beings.","hint":"","options":["猫总是能吸引人类。","他们检查了各个房间，小心翼翼地不碰任何东西，","他原以为店员会目瞪口呆地看着他。","尽管她年代久远，但确实非常优雅，不过到目前为止，考古学家们还未能发现她的身份。"],"answer":0,"explain":"Cats never fail to fascinate human beings. — 猫总是能吸引人类。","source":{"kind":"sentence","en":"Cats never fail to fascinate human beings."},"id":"b3-u09-q06"}]},{"id":"b3-u10","book":3,"unit":10,"key":"10","lessonFrom":10,"lessonTo":10,"title":"The Loss of the Titanic","titleZh":"泰坦尼克号的沉没","question":"What would have happened if only two of the 16 water-tight compartments had been flooded?","sentences":[{"en":"The great ship, Titanic sailed for New York from Southampton on April 10th, 1912.","zh":"1912年4月10日，巨轮“泰坦尼克号”从南安普顿启程驶往纽约。","t":19.25},{"en":"She was carrying 1,316 passengers and a crew of 891.","zh":"船上载有1316名乘客和891名船员。","t":27.22},{"en":"Even by modern standards, the 46,000 ton Titanic was a colossal ship.","zh":"即使按现代标准来看，46000吨的泰坦尼克号也是一艘巨轮。","t":35.33},{"en":"At that time, however, she was not only the largest ship that had ever been built, but was regarded as unsinkable, for she had sixteen water-tight compartments.","zh":"然而，在那个时代，她不仅是当时建造过的最大的船只，而且被认为是永不沉没的，因为她有十六个水密舱室。","t":42.72},{"en":"Even if two of these were flooded, she would still be able to float.","zh":"即使其中两个舱室被水淹没，她仍然能够漂浮。","t":55.71},{"en":"The tragic sinking of this great liner will always be remembered, for she went down on her first voyage with heavy loss of life.","zh":"这艘巨型邮轮的悲剧性沉没将永远被铭记，因为她在首次航行中就沉没了，造成了大量人员伤亡。","t":60.83},{"en":"Four days after setting out, while the Titanic was sailing across the icy waters of the North Atlantic,","zh":"启程四天后，当泰坦尼克号航行在北大西洋冰冷的海域时，","t":71.82},{"en":"a huge iceberg was suddenly spotted by a lookout.","zh":"一名瞭望员突然发现了一座巨大的冰山。","t":79.22},{"en":"After the alarm had been given, the great ship turned sharply to avoid a direct collision.","zh":"警报发出后，这艘巨轮急剧转向，以避免直接碰撞。","t":83.88},{"en":"The Titanic turned just in time, narrowly missing the immense wall of ice which rose over 100 feet out of the water beside her.","zh":"泰坦尼克号及时转向，险些错过了她旁边那堵高出水面100多英尺的巨大冰墙。","t":91.18},{"en":"Suddenly, there was a slight trembling sound from below,","zh":"突然，从下方传来一阵轻微的颤抖声，","t":102.6},{"en":"and the captain went down to see what had happened.","zh":"船长下去查看发生了什么。","t":107.57},{"en":"The noise had been so faint that no one thought that the ship had been damaged.","zh":"声音如此微弱，以至于没有人认为船只受到了损坏。","t":111.73},{"en":"Below, the captain realized to his horror that the Titanic was sinking rapidly,","zh":"在下方，船长惊恐地意识到泰坦尼克号正在迅速下沉，","t":117.36},{"en":"for five of her sixteen watertight compartments had already been flooded!","zh":"因为她16个水密舱室中的5个已经进水了！","t":123.98},{"en":"The order to abandon ship was given and hundreds of people plunged into the icy water.","zh":"弃船命令下达，数百人跳入冰冷的水中。","t":130},{"en":"As there were not enough life-boats for everybody, 1,500 lives were lost.","zh":"由于救生艇不足，有1500人丧生。","t":137.23}],"vocab":[{"word":"colossal","phonetic":"/kəˈlɒsl/","meanings":[{"pos":"adjective","meaning":"巨大的，庞大的","usage":"通常用来形容体积、规模、程度等异常巨大的事物，语义比large、big强烈"}]},{"word":"watertight","phonetic":"/ˈwɔːtətaɪt/","meanings":[{"pos":"adjective","meaning":"不漏水的，水密的","usage":"多用来形容容器、隔间等结构不会进水，也可引申指计划、论点等无懈可击的"}]},{"word":"compartment","phonetic":"/kəmˈpɑːtmənt/","meanings":[{"pos":"noun","meaning":"隔间，舱","usage":"指交通工具、容器等内部被分隔出的独立空间，也可指火车的包厢"}]},{"word":"float","phonetic":"/fləʊt/","meanings":[{"pos":"verb","meaning":"漂浮，浮动","usage":"指物体在液体表面漂浮不沉，也可指在空气中悬浮"}]},{"word":"tragic","phonetic":"/ˈtrædʒɪk/","meanings":[{"pos":"adjective","meaning":"悲惨的，悲剧的","usage":"用来形容事件、结局等令人悲痛、造成不幸的"}]},{"word":"liner","phonetic":"/ˈlaɪnə(r)/","meanings":[{"pos":"noun","meaning":"大型客轮，班轮","usage":"指定期航行的大型客运轮船，也可指眼线笔等化妆品"}]},{"word":"voyage","phonetic":"/ˈvɔɪɪdʒ/","meanings":[{"pos":"noun","meaning":"航行，航海，航天旅行","usage":"侧重指长途的海上或太空旅行，区别于短途的trip"}]},{"word":"icy","phonetic":"/ˈaɪsi/","meanings":[{"pos":"adjective","meaning":"冰冷的，冰封的","usage":"可以形容温度极低，也可形容表面覆盖着冰的"}]},{"word":"lookout","phonetic":"/ˈlʊkaʊt/","meanings":[{"pos":"noun","meaning":"瞭望员，守望者","usage":"指负责观察警戒的人员，也可指瞭望台"}]},{"word":"collision","phonetic":"/kəˈlɪʒn/","meanings":[{"pos":"noun","meaning":"碰撞，相撞","usage":"指交通工具等的相撞，也可引申指观点、利益的冲突"}]},{"word":"narrowly","phonetic":"/ˈnærəʊli/","meanings":[{"pos":"adverb","meaning":"勉强地，险些","usage":"常用来修饰miss、escape等词，表示差一点就发生不好的事"}]},{"word":"immense","phonetic":"/ɪˈmens/","meanings":[{"pos":"adjective","meaning":"巨大的，广大的","usage":"强调体积、数量、程度等大到难以测量"}]},{"word":"trembling","phonetic":"/ˈtremblɪŋ/","meanings":[{"pos":"noun","meaning":"颤抖，震动","usage":"指物体或人的轻微抖动，也可作形容词表示颤抖的"}]},{"word":"faint","phonetic":"/feɪnt/","meanings":[{"pos":"adjective","meaning":"微弱的，模糊的","usage":"可以形容声音、光线、气味等不清晰、强度低，也可指人快要昏厥的"}]},{"word":"plunge","phonetic":"/plʌndʒ/","meanings":[{"pos":"verb","meaning":"猛跳，纵身投入","usage":"指快速、猛地跳入某处，也可表示价格、数量骤降"}]}],"phrases":[{"phrase":"sail for","usage":"表示船只、水手等启航前往某地，后接目的地","examples":[{"en":"The ship will sail for Sydney next week.","zh":"这艘船将于下周启航前往悉尼。"}]},{"phrase":"by ... standards","usage":"表示“按照……的标准”，用来引出判断事物的参考依据","examples":[{"en":"By today's standards, this old phone is almost useless.","zh":"按照如今的标准，这部旧手机几乎没什么用了。"}]},{"phrase":"be regarded as","usage":"被动结构，表示“被认为是，被看作”，用来表达人们对某事物的普遍看法","examples":[{"en":"He is regarded as one of the best writers of his generation.","zh":"他被认为是他那一代人中最优秀的作家之一。"}]},{"phrase":"even if","usage":"引导让步状语从句，意为“即使，纵然”，用来引出假设的让步条件","examples":[{"en":"Even if it rains tomorrow, we will still hold the sports meeting.","zh":"即使明天下雨，我们还是会举办运动会。"}]},{"phrase":"go down","usage":"此处意为“（船）沉没”，还可表示下降、下跌、被记下等含义","examples":[{"en":"The small boat went down in the storm last night.","zh":"那艘小船在昨晚的暴风雨中沉没了。"}]},{"phrase":"set out","usage":"意为“出发，启程”，侧重开始一段长途旅行，也可表示着手做某事","examples":[{"en":"They set out before dawn to climb the mountain.","zh":"他们在黎明前就出发去爬山了。"}]},{"phrase":"in time","usage":"表示“及时”，指在约定或所需的时间之前完成动作，区别于on time（准时）","examples":[{"en":"The doctor arrived in time to save the injured man.","zh":"医生及时赶到，救下了受伤的男子。"}]},{"phrase":"to one's horror","usage":"插入语，意为“令某人惊恐的是”，用来表达某人得知某事时的恐惧情绪","examples":[{"en":"To his horror, he found his wallet missing at the airport.","zh":"令他惊恐的是，他在机场发现自己的钱包不见了。"}]},{"phrase":"abandon ship","usage":"固定表达，意为“弃船”，指船只遇险时船上人员撤离船只的命令或行为","examples":[{"en":"When the fire spread out of control, the captain gave the order to abandon ship.","zh":"当火势失去控制时，船长下达了弃船的命令。"}]}],"grammar":[{"title":"虚拟语气在条件状语从句中的用法（与过去事实相反）","definition":"用来表示与过去已经发生的事实相反的假设，假设的情况不可能真实发生，表达遗憾、推测等语气","structure":"If + 主语 + had + 过去分词, 主语 + would/could/should/might + have + 过去分词","usage":"从句描述过去并未发生的假设条件，主句描述该假设条件下会发生的与现实不同的结果","examples":[{"en":"What would have happened if only two of the 16 watertight compartments had been flooded?","zh":"如果16个水密舱中只有两个进水，会发生什么情况呢？"},{"en":"If you had studied harder last term, you would have passed the final exam.","zh":"如果你上学期更努力学习，你就会通过期末考试了。"}]},{"title":"过去完成时的被动语态","definition":"表示在过去某个动作之前已经被完成的动作，强调被动关系和动作发生的“过去的过去”的时间属性","structure":"主语 + had been + 过去分词 + 其他","usage":"常出现在有明显过去时间参照的语境中，用来描述更早发生的被动动作","examples":[{"en":"After the alarm had been given, the great ship turned sharply to avoid a direct collision.","zh":"警报发出后，巨轮猛地转向以避免正面碰撞。"},{"en":"All the tickets had been sold out when we arrived at the cinema.","zh":"我们到达电影院时，所有的票已经被卖光了。"}]},{"title":"so...that...引导的结果状语从句","definition":"用来表示“如此……以至于……”，so后接形容词或副词，that引导从句说明主句动作带来的结果","structure":"主语 + 谓语 + so + 形容词/副词 + that + 结果状语从句","usage":"用来强调程度，说明前面描述的性质或状态达到了某种程度，进而产生了从句中的结果","examples":[{"en":"The noise had been so faint that no one thought that the ship had been damaged.","zh":"声音太微弱了，以至于没人认为船已经受损。"},{"en":"The book was so interesting that I stayed up all night reading it.","zh":"这本书太有趣了，以至于我熬了一整夜读它。"}]}],"patterns":[{"pattern":"At that time, however, ... was not only the ... that had ever been ..., but was regarded as ..., for ...","explanation":"","original":{"en":"At that time, however, she was not only the largest ship that had ever been built, but was regarded as unsinkable, for she had sixteen watertight compartments.","zh":"然而，在当时，它不仅是有史以来建造的最大的轮船，还被认为是不会沉没的，因为它有16个水密舱。"},"examples":[{"en":"At that time, however, the building was not only the tallest skyscraper that had ever been designed in the city, but was regarded as a symbol of modern architecture, for it adopted many new environmental technologies.","zh":"然而，在当时，这座建筑不仅是这座城市有史以来设计的最高的摩天大楼，还被看作是现代建筑的象征，因为它采用了许多新的环保技术。"}]},{"pattern":"The ... will always be remembered, for ...","explanation":"","original":{"en":"The tragic sinking of this great liner will always be remembered, for she went down on her first voyage with heavy loss of life.","zh":"这艘巨轮的悲剧沉没将永远被铭记，因为它在首航时就沉没了，造成了惨重的生命损失。"},"examples":[{"en":"The success of this historic mission will always be remembered, for it marked the first time humans landed on the moon.","zh":"这一历史性任务的成功将永远被铭记，因为它标志着人类首次登上月球。"}]},{"pattern":"As there were not enough ... for everybody, ...","explanation":"","original":{"en":"As there were not enough life-boats for everybody, 1,500 lives were lost.","zh":"由于没有足够的救生艇容纳所有人，1500人丧生了。"},"examples":[{"en":"As there were not enough tickets for everybody, many fans had to watch the match on the screen outside the stadium.","zh":"由于没有足够的票卖给所有人，很多粉丝只能在场馆外的屏幕上观看比赛。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“微弱的，模糊的” 对应的单词是？","hint":"adjective · /feɪnt/","options":["charge","faint","submerge","exclusive"],"answer":1,"explain":"faint · /feɪnt/ · adjective · 微弱的，模糊的。可以形容声音、光线、气味等不清晰、强度低，也可指人快要昏厥的","source":{"kind":"vocab","word":"faint"},"id":"b3-u10-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：巨大的，广大的","hint":"/ɪˈmens/ · adjective","answer":"immense","placeholder":"输入英文单词","explain":"immense · /ɪˈmens/ · adjective · 巨大的，广大的。强调体积、数量、程度等大到难以测量","source":{"kind":"vocab","word":"immense"},"id":"b3-u10-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ it rains tomorrow, we will still hold the sports meeting.","hint":"即使明天下雨，我们还是会举办运动会。","answer":"even if","placeholder":"输入缺失的短语","explain":"even if：引导让步状语从句，意为“即使，纵然”，用来引出假设的让步条件（即使明天下雨，我们还是会举办运动会。）","source":{"kind":"phrase","phrase":"even if"},"id":"b3-u10-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ if two of these were flooded, she would still be able to float.","hint":"即使其中两个舱室被水淹没，她仍然能够漂浮。","answer":"Even","placeholder":"输入缺失的单词","explain":"Even if two of these were flooded, she would still be able to float. — 即使其中两个舱室被水淹没，她仍然能够漂浮。","source":{"kind":"sentence","en":"Even if two of these were flooded, she would still be able to float."},"id":"b3-u10-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在过去某个动作之前已经被完成的动作，强调被动关系和动作发生的“过去的过去”的时间属性” 描述的是哪个语法点？","hint":"主语 + had been + 过去分词 + 其他","options":["Though / Although + 从句（让步状语从句）","过去完成时的被动语态","more than + n./adj. (不仅仅；超出)","虚拟语气 (Subjunctive Mood) - 与过去事实相反"],"answer":1,"explain":"过去完成时的被动语态：主语 + had been + 过去分词 + 其他：常出现在有明显过去时间参照的语境中，用来描述更早发生的被动动作","source":{"kind":"grammar","title":"过去完成时的被动语态"},"id":"b3-u10-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nFour days after setting out, while the Titanic was sailing across the icy waters of the North Atlantic,","hint":"","options":["门多萨在14岁时参加一场拳击比赛后迅速成名。","启程四天后，当泰坦尼克号航行在北大西洋冰冷的海域时，","第二个向我走来的人是卖高档钢笔和手表的。","意识到这些陷阱，今年我试图把我的决心藏在心里。"],"answer":1,"explain":"Four days after setting out, while the Titanic was sailing across the icy waters of the North Atlantic, — 启程四天后，当泰坦尼克号航行在北大西洋冰冷的海域时，","source":{"kind":"sentence","en":"Four days after setting out, while the Titanic was sailing across the icy waters of the North Atlantic,"},"id":"b3-u10-q06"}]},{"id":"b3-u11","book":3,"unit":11,"key":"11","lessonFrom":11,"lessonTo":11,"title":"Not Guilty","titleZh":"无罪","question":"What was the Customs Officer looking for?","sentences":[{"en":"Customs Officers are quite tolerant these days, but they can still stop you when you are going through the Green Channel and have nothing to declare.","zh":"如今海关官员相当宽容，但当你走绿色通道并且没有东西要申报时，他们仍然可以拦住你。","t":13.22},{"en":"Even really honest people are often made to feel guilty.","zh":"即使是非常诚实的人也常常会感到内疚。","t":23},{"en":"The hardened professional smuggler, on the other hand, is never troubled by such feelings,","zh":"另一方面，那些老练的职业走私犯从不会被这种感觉所困扰，","t":27.47},{"en":"even if he has five hundred gold watches hidden in his suitcase.","zh":"即使他的手提箱里藏着五百块金表。","t":33.67},{"en":"When I returned from abroad recently, a particularly officious young Customs Officer","zh":"最近我从国外回来时，一位特别爱管闲事的年轻海关官员","t":38.97},{"en":"clearly regarded me as a smuggler.","zh":"显然把我当成了走私犯。","t":44.92},{"en":"'Have you anything to declare?' he asked, looking me in the eye.","zh":"“你有什么要申报的吗？”他直视着我的眼睛问道。","t":48.39},{"en":"'No,' I answered confidently.","zh":"“没有，”我自信地回答道。","t":54.07},{"en":"'Would you mind unlocking this suitcase please? '","zh":"“请您打开这个手提箱好吗？”","t":57.61},{"en":"'Not at all,' I answered.","zh":"“当然可以，”我回答道。","t":61.55},{"en":"The Officer went through the case with great care.","zh":"那个官员非常仔细地检查了箱子。","t":63.97},{"en":"All the things I had packed so carefully were soon in a dreadful mess.","zh":"我费尽心思整理好的所有东西很快就乱七八糟了。","t":67.71},{"en":"I felt sure I would never be able to close the case again.","zh":"我确信我再也无法把箱子合上了。","t":73.57},{"en":"Suddenly, I saw the Officer's face light up.","zh":"突然，我看到那个官员的脸上露出了喜色。","t":78.27},{"en":"He had spotted a tiny bottle at the bottom of my case","zh":"他发现了一个小瓶子在我的箱子底部","t":82.34},{"en":"and he pounced on it with delight.","zh":"他欣喜若狂地扑了上去。","t":86.25},{"en":"'Perfume, eh?' he asked sarcastically.","zh":"“香水，嗯？”他挖苦地问道。","t":89.35},{"en":"'You should have declared that.","zh":"“你应该申报那个。","t":94.68},{"en":"Perfume is not exempt from import duty. '","zh":"香水不免除进口关税。”","t":96.66},{"en":"'But it isn't perfume,' I said. 'It's hair gel.'","zh":"“但它不是香水，”我说，“它是发胶。”","t":101.38},{"en":"Then I added with a smile,","zh":"然后我笑着补充道，","t":106.96},{"en":"'It's a strange mixture I make myself.","zh":"“这是我自己调制的一种奇怪的混合物。”","t":109.55},{"en":"As I expected, he did not believe me.","zh":"如我所料，他没有相信我。","t":113.36},{"en":"'Try it!' I said encouragingly.","zh":"“尝尝看！”我鼓励地说。","t":117.25},{"en":"The Officer unscrewed the cap and put the bottle to his nostrils.","zh":"那个官员拧开瓶盖，把瓶子凑到鼻孔前。","t":120.96},{"en":"He was greeted by an unpleasant smell which convinced him that I was telling the truth.","zh":"一股难闻的气味扑鼻而来，这让他相信我说的是实话。","t":125.46},{"en":"A few minutes later, I was able to hurry away with precious chalk marks on my baggage.","zh":"几分钟后，我带着行李上珍贵的粉笔标记，匆匆离开了。","t":131.96}],"vocab":[{"word":"guilty","phonetic":"/ˈɡɪlti/","meanings":[{"pos":"adjective","meaning":"内疚的；有罪的","usage":"既可以指人犯了罪，也可以指人因为做错事而感到愧疚"}]},{"word":"tolerant","phonetic":"/ˈtɒlərənt/","meanings":[{"pos":"adjective","meaning":"宽容的，容忍的","usage":"常搭配介词towards/of，表示对某事物/某人宽容"}]},{"word":"declare","phonetic":"/dɪˈkleə(r)/","meanings":[{"pos":"verb","meaning":"申报（纳税品）；宣布，声明","usage":"海关场景中特指申报需缴税的物品，也可用于正式宣布决定、消息等"}]},{"word":"hardened","phonetic":"/ˈhɑːdnd/","meanings":[{"pos":"adjective","meaning":"老练的；有经验的； hardened的动词harden意为变硬","usage":"常修饰有多年不良经历、已经习以为常的人，如hardened criminal（惯犯）"}]},{"word":"smuggler","phonetic":"/ˈsmʌɡlə(r)/","meanings":[{"pos":"noun","meaning":"走私者，偷运者","usage":"对应动词smuggle，意为走私、偷运"}]},{"word":"officious","phonetic":"/əˈfɪʃəs/","meanings":[{"pos":"adjective","meaning":"爱指手画脚的，好管闲事的","usage":"多含贬义，形容人过度行使权力、多管闲事"}]},{"word":"confidently","phonetic":"/ˈkɒnfɪdəntli/","meanings":[{"pos":"adverb","meaning":"自信地，有信心地","usage":"修饰动词，表示做某事时的状态很自信，对应形容词confident"}]},{"word":"dreadful","phonetic":"/ˈdredfl/","meanings":[{"pos":"adjective","meaning":"糟透的，可怕的","usage":"口语中常用来形容事物质量差、情况很糟糕"}]},{"word":"pounce","phonetic":"/paʊns/","meanings":[{"pos":"verb","meaning":"猛扑，突然抓住","usage":"常搭配介词on/upon，指突然抓住机会或者扑向某物/某人"}]},{"word":"sarcastically","phonetic":"/sɑːˈkæstɪkli/","meanings":[{"pos":"adverb","meaning":"讽刺地，挖苦地","usage":"修饰说话的语气，对应形容词sarcastic"}]},{"word":"exempt","phonetic":"/ɪɡˈzempt/","meanings":[{"pos":"adjective","meaning":"被豁免的，被免除的","usage":"常搭配介词from，表示免除某项义务、税费等"}]},{"word":"duty","phonetic":"/ˈdjuːti/","meanings":[{"pos":"noun","meaning":"税；责任，义务","usage":"海关场景中特指进口/出口关税，常见搭配import duty（进口税）"}]},{"word":"gel","phonetic":"/dʒel/","meanings":[{"pos":"noun","meaning":"凝胶，胶冻","usage":"这里hair gel指发胶，也可作动词表示胶凝、成型"}]},{"word":"unscrew","phonetic":"/ˌʌnˈskruː/","meanings":[{"pos":"verb","meaning":"拧开，旋开","usage":"前缀un-表示反义，对应动词screw（拧紧）"}]},{"word":"nostril","phonetic":"/ˈnɒstrəl/","meanings":[{"pos":"noun","meaning":"鼻孔","usage":"通常用复数形式nostrils表示两个鼻孔"}]}],"phrases":[{"phrase":"Green Channel","usage":"海关场景专有名词，指无需申报物品的旅客通行的“绿色通道”","examples":[{"en":"If you have nothing to declare, you can take the Green Channel.","zh":"如果你没有需要申报的物品，你可以走绿色通道。"}]},{"phrase":"look sb in the eye","usage":"表示直视某人的眼睛，通常用于坦诚、问心无愧的场景","examples":[{"en":"He lied to me and couldn't look me in the eye when he spoke.","zh":"他对我撒了谎，说话的时候不敢直视我的眼睛。"}]},{"phrase":"go through","usage":"此处含义是“仔细检查”，还有“经历、度过”的含义","examples":[{"en":"The police went through all the evidence to find the truth.","zh":"警方仔细检查了所有证据来找出真相。"}]},{"phrase":"in a dreadful mess","usage":"形容东西乱作一团，或者情况非常糟糕","examples":[{"en":"After the party, the whole house was in a dreadful mess.","zh":"派对结束后，整栋房子乱得一塌糊涂。"}]},{"phrase":"light up","usage":"此处指“（脸上）流露出喜悦、兴奋的神情”，还有“点亮、开灯”的含义","examples":[{"en":"Her face lit up when she received the admission letter.","zh":"收到录取通知书的时候，她脸上露出了喜色。"}]},{"phrase":"pounce on","usage":"指猛抓住某物，或者突然指出别人的错误、抓住机会","examples":[{"en":"The reporter pounced on the politician's slip of the tongue.","zh":"记者立刻抓住了政客的口误进行追问。"}]},{"phrase":"exempt from","usage":"表示免除某责任、义务或费用","examples":[{"en":"Students are exempt from the entrance fee for the museum.","zh":"学生可以免除这家博物馆的门票费用。"}]},{"phrase":"import duty","usage":"专有名词，指进口商品需要缴纳的进口税","examples":[{"en":"You have to pay import duty on luxury goods brought from abroad.","zh":"你从国外带回的奢侈品需要缴纳进口税。"}]}],"grammar":[{"title":"should have done 结构","definition":"表示“本应该做某事（实际上没做）”，属于虚拟语气的一种，常用来表达责备、后悔、建议等语气","structure":"should + have + 动词过去分词","usage":"用于谈论过去本该发生却没有发生的情况，否定形式为should not have done，表“本不该做某事却做了”","examples":[{"en":"You should have declared that.","zh":"你本应该申报那个（物品）的。"},{"en":"You should have told me the news earlier.","zh":"你本应该早点告诉我这个消息的。"},{"en":"We shouldn't have spent so much money on unnecessary things.","zh":"我们本不该在不必要的东西上花这么多钱的。"}]},{"title":"过去分词作定语","definition":"过去分词可以放在名词前面或后面作定语，表被动或者完成的含义","structure":"及物动词过去分词 + 名词 / 名词 + 过去分词（短语）","usage":"单个过去分词一般放在被修饰名词前，过去分词短语作定语则放在被修饰名词后，相当于一个被动语态的定语从句","examples":[{"en":"even if he has five hundred gold watches hidden in his suitcase.","zh":"即便他的手提箱里藏着500块金表。"},{"en":"The book written by my favorite author sold very well.","zh":"我最喜欢的作家写的那本书销量非常好。"},{"en":"We need to fix the broken window before it rains.","zh":"下雨前我们得把那扇碎了的窗户修好。"}]}],"patterns":[{"pattern":"..., on the other hand, ...","explanation":"","original":{"en":"The hardened professional smuggler, on the other hand, is never troubled by such feelings.","zh":"而另一方面，老练的职业走私犯却从来不会被这种情绪困扰。"},"examples":[{"en":"Many people enjoy living in big cities. Small towns, on the other hand, are more suitable for people who love quiet life.","zh":"很多人喜欢在大城市生活，而另一方面，小城镇更适合喜爱安静生活的人。"},{"en":"Online learning is very convenient. Traditional classroom education, on the other hand, allows better interaction between teachers and students.","zh":"线上学习非常方便，而另一方面，传统课堂教育能让师生有更好的互动。"}]},{"pattern":"Would you mind doing sth please?","explanation":"","original":{"en":"Would you mind unlocking this suitcase please?","zh":"麻烦你打开这个手提箱好吗？"},"examples":[{"en":"Would you mind passing me the salt on the table please?","zh":"麻烦你把桌子上的盐递给我好吗？"},{"en":"Would you mind turning down the radio a little? I'm doing my homework.","zh":"麻烦你把收音机音量调小一点可以吗？我正在做作业。"}]},{"pattern":"sb was greeted by...","explanation":"","original":{"en":"He was greeted by an unpleasant smell which convinced him that I was telling the truth.","zh":"一股难闻的气味扑面而来，让他相信我说的是实话。"},"examples":[{"en":"When I opened the door of the bakery, I was greeted by the warm smell of fresh bread.","zh":"我打开面包店的门时，扑面而来的是新鲜面包温暖的香气。"},{"en":"The visitors were greeted by the beautiful song of birds as they walked into the forest.","zh":"游客们走进森林时，耳边首先传来了鸟儿动听的歌声。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“凝胶，胶冻” 对应的单词是？","hint":"noun · /dʒel/","options":["peculiar","illogical","gel","antique"],"answer":2,"explain":"gel · /dʒel/ · noun · 凝胶，胶冻。这里hair gel指发胶，也可作动词表示胶凝、成型","source":{"kind":"vocab","word":"gel"},"id":"b3-u11-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：申报（纳税品）；宣布，声明","hint":"/dɪˈkleə(r)/ · verb","answer":"declare","placeholder":"输入英文单词","explain":"declare · /dɪˈkleə(r)/ · verb · 申报（纳税品）；宣布，声明。海关场景中特指申报需缴税的物品，也可用于正式宣布决定、消息等","source":{"kind":"vocab","word":"declare"},"id":"b3-u11-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Students are _____ the entrance fee for the museum.","hint":"学生可以免除这家博物馆的门票费用。","answer":"exempt from","placeholder":"输入缺失的短语","explain":"exempt from：表示免除某责任、义务或费用（学生可以免除这家博物馆的门票费用。）","source":{"kind":"phrase","phrase":"exempt from"},"id":"b3-u11-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：I felt sure I would never be able to close the _____ again.","hint":"我确信我再也无法把箱子合上了。","answer":"case","placeholder":"输入缺失的单词","explain":"I felt sure I would never be able to close the case again. — 我确信我再也无法把箱子合上了。","source":{"kind":"sentence","en":"I felt sure I would never be able to close the case again."},"id":"b3-u11-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“过去分词可以放在名词前面或后面作定语，表被动或者完成的含义” 描述的是哪个语法点？","hint":"及物动词过去分词 + 名词 / 名词 + 过去分词（短语）","options":["no matter what引导的让步状语从句","过去分词作定语","过去进行时 (Past Continuous Tense)","Not only...but (also) 引起的倒装句"],"answer":1,"explain":"过去分词作定语：及物动词过去分词 + 名词 / 名词 + 过去分词（短语）：单个过去分词一般放在被修饰名词前，过去分词短语作定语则放在被修饰名词后，相当于一个被动语态的定语从句","source":{"kind":"grammar","title":"过去分词作定语"},"id":"b3-u11-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThen I added with a smile,","hint":"","options":["手机上的大声对话侵扰我们的思绪，或者打断我们与朋友安静聊天的乐趣。","然后我笑着补充道，","我们在河边迎接季节，春天给最小的女孩戴上花冠，","披着黑色披肩的老妇人从门道里窥视着我们。"],"answer":1,"explain":"Then I added with a smile, — 然后我笑着补充道，","source":{"kind":"sentence","en":"Then I added with a smile,"},"id":"b3-u11-q06"}]},{"id":"b3-u12","book":3,"unit":12,"key":"12","lessonFrom":12,"lessonTo":12,"title":"Life on a Desert Island","titleZh":"荒岛生活","question":"What was exceptional about the two men's stay on the desert island?","sentences":[{"en":"Most of us have formed an unrealistic picture of life on a desert island.","zh":"我们大多数人对荒岛生活形成了一种不切实际的想象。","t":16.24},{"en":"We sometimes imagine a desert island to be a sort of paradise where the sun always shines.","zh":"我们有时把荒岛想象成一个阳光普照的天堂。","t":22.19},{"en":"Life there is simple and good.","zh":"那里的生活简单而美好。","t":29.85},{"en":"Ripe fruit falls from the trees and you never have to work.","zh":"成熟的果实从树上掉下来，你根本不用劳动。","t":32.44},{"en":"The other side of the picture is quite the opposite.","zh":"而另一方面的情况却恰恰相反。","t":37.52},{"en":"Life on a desert island is wretched.","zh":"荒岛上的生活是悲惨的。","t":41.16},{"en":"You either starve to death or live like Robinson Crusoe, waiting for a boat which never comes.","zh":"你不是饿死，就是像鲁滨逊漂流记一样，苦等一艘永不来临的船。","t":43.94},{"en":"Perhaps there is an element of truth in both these pictures, but few of us have had the opportunity to find out.","zh":"也许这两种景象都有点真实性，但我们很少有人有机会去证实。","t":52.49},{"en":"Two men who recently spent five days on a coral island wished they had stayed there longer.","zh":"最近，有两个人在一个珊瑚岛上待了五天，他们真希望能在那里待得更久。","t":60.81},{"en":"They were taking a badly damaged boat from the Virgin Islands to Miami to have it repaired.","zh":"他们正驾驶一艘严重受损的船从维尔京群岛前往迈阿密修理。","t":69.25},{"en":"During the journey, their boat began to sink.","zh":"旅途中，他们的船开始下沉。","t":75.85},{"en":"They quickly loaded a small rubber dinghy with food, matches, and cans of beer and rowed for a few miles across the Caribbean until they arrived at a tiny coral island.","zh":"他们迅速将食物、火柴和几罐啤酒装上一艘小橡皮艇，划行了几英里穿过加勒比海，直到抵达一个微小的珊瑚岛。","t":80.15},{"en":"There were hardly any trees on the island and there was no water, but this did not prove to be a problem.","zh":"岛上几乎没有树木，也没有水，但这并没有成为一个问题。","t":93.63},{"en":"The men collected rainwater in the rubber dinghy.","zh":"两人用橡皮艇收集雨水。","t":101.52},{"en":"As they had brought a spear gun with them, they had plenty to eat.","zh":"由于他们带了一支鱼枪，所以食物很充足。","t":105.28},{"en":"They caught lobster and fish every day, and as one of them put it 'ate like kings'.","zh":"他们每天都捕捞龙虾和鱼，正如其中一人所说，他们“吃得像国王一样”。","t":109.56},{"en":"When a passing tanker rescued them five days later, both men were genuinely sorry that they had to leave.","zh":"五天后，当一艘过往的油轮救起他们时，两人都真诚地感到遗憾，因为他们不得不离开。","t":117.2}],"vocab":[{"word":"desert","phonetic":"/ˈdezət/","meanings":[{"pos":"adjective","meaning":"无人居住的；荒凉的","usage":"修饰表示地点的名词，指地方荒无人烟"},{"pos":"noun","meaning":"沙漠；荒漠","usage":"指干旱少雨、植被稀少的大面积荒漠地区"}]},{"word":"exceptional","phonetic":"/ɪkˈsepʃənl/","meanings":[{"pos":"adjective","meaning":"异常的；例外的；杰出的","usage":"用来描述人或事物不同于普通情况，含褒义时表示非常优秀"}]},{"word":"unrealistic","phonetic":"/ˌʌnrɪəˈlɪstɪk/","meanings":[{"pos":"adjective","meaning":"不切实际的；不现实的","usage":"通常用来描述想法、期望等不符合客观实际"}]},{"word":"paradise","phonetic":"/ˈpærədaɪs/","meanings":[{"pos":"noun","meaning":"天堂；乐园","usage":"可指宗教中的天堂，也可指令人愉悦的完美地方或状态"}]},{"word":"wretched","phonetic":"/ˈretʃɪd/","meanings":[{"pos":"adjective","meaning":"悲惨的；可怜的；恶劣的","usage":"用来描述人的处境痛苦，或事物质量差、令人不满"}]},{"word":"starve","phonetic":"/stɑːv/","meanings":[{"pos":"verb","meaning":"挨饿；饿死","usage":"不及物动词，可搭配to death表示饿死；口语中也可表示很饿"}]},{"word":"element","phonetic":"/ˈelɪmənt/","meanings":[{"pos":"noun","meaning":"少量；部分；元素；要素","usage":"an element of 为常用搭配，表示“一点点，些许”"}]},{"word":"coral","phonetic":"/ˈkɒrəl/","meanings":[{"pos":"noun","meaning":"珊瑚","usage":"不可数名词，也可作定语修饰名词，如coral island（珊瑚岛）"}]},{"word":"load","phonetic":"/ləʊd/","meanings":[{"pos":"verb","meaning":"装载；装满","usage":"常用搭配load sth with sth，表示“给某物装上某物”"},{"pos":"noun","meaning":"负载；工作量","usage":"可表示车辆、船只的装载量，也可指人的工作负担"}]},{"word":"dinghy","phonetic":"/ˈdɪŋi/","meanings":[{"pos":"noun","meaning":"小划艇；橡皮艇","usage":"指小型的敞篷船只，通常用桨或者马达驱动"}]},{"word":"spear","phonetic":"/spɪə(r)/","meanings":[{"pos":"noun","meaning":"矛；梭镖","usage":"可作定语构成复合词，如spear gun（捕鱼用的鱼枪）"}]},{"word":"lobster","phonetic":"/ˈlɒbstə(r)/","meanings":[{"pos":"noun","meaning":"龙虾","usage":"可作可数名词指龙虾个体，也可作不可数名词指龙虾肉"}]},{"word":"tanker","phonetic":"/ˈtæŋkə(r)/","meanings":[{"pos":"noun","meaning":"油轮；罐车","usage":"指运输石油、天然气等液体的大型船只或车辆"}]},{"word":"genuinely","phonetic":"/ˈdʒenjuɪnli/","meanings":[{"pos":"adverb","meaning":"真诚地；由衷地","usage":"用来修饰情感、态度，表示发自内心、没有虚假"}]}],"phrases":[{"phrase":"form a picture of","usage":"表示对某事物形成某种想象或印象","examples":[{"en":"It's hard to form a clear picture of life on other planets.","zh":"很难对其他星球上的生活形成清晰的想象。"}]},{"phrase":"a sort of","usage":"用来表示不确定的描述，意为“某种，可以说是”，弱化语气","examples":[{"en":"The small café by the lake is a sort of paradise for book lovers.","zh":"湖边的那家小咖啡馆可以说是读书爱好者的乐园。"}]},{"phrase":"starve to death","usage":"固定搭配，表示饿死，强调极端饥饿的后果","examples":[{"en":"Many animals would starve to death in winter if they don't store enough food.","zh":"如果没有储存足够的食物，很多动物会在冬天饿死。"}]},{"phrase":"an element of","usage":"表示“一点点，些许”，说明某事物中含有少量的某种特质","examples":[{"en":"There is always an element of risk when you travel alone.","zh":"独自旅行的时候总会有一点点风险。"}]},{"phrase":"load...with...","usage":"表示“给……装上……”，主语通常是人，宾语是装载的载体和货物","examples":[{"en":"They loaded the truck with fresh vegetables before dawn.","zh":"他们在黎明前给卡车装上了新鲜蔬菜。"}]},{"phrase":"hardly any","usage":"表示“几乎没有”，相当于very few或very little，否定含义","examples":[{"en":"There is hardly any coffee left in the pot, so I need to make more.","zh":"壶里几乎没有咖啡了，我得再煮点。"}]},{"phrase":"eat like kings","usage":"非正式表达，意思是吃得非常好，享用美食","examples":[{"en":"During the Spring Festival, we eat like kings with all kinds of delicious food.","zh":"春节期间我们吃得非常好，有各种各样的美食。"}]}],"grammar":[{"title":"wish引导的虚拟语气","definition":"wish后面接宾语从句时，常使用虚拟语气，表示与事实相反或不太可能实现的愿望。如果是对过去情况的虚拟，从句谓语用过去完成时（had done）。","structure":"主语 + wish + 从句主语 + had + 过去分词","usage":"用来表达对过去已经发生的事情感到遗憾，希望事情是另一种情况","examples":[{"en":"Two men who recently spent five days on a coral island wished they had stayed there longer.","zh":"最近在一座珊瑚岛上待了5天的两名男子真希望他们能在那儿待更久。"},{"en":"I wish I had taken your advice when I was choosing my major.","zh":"我真希望我选专业的时候听了你的建议。"}]},{"title":"either...or...并列连词结构","definition":"either...or...是表示选择关系的并列连词，用来连接两个对等的成分，表示“要么……要么……；或者……或者……”，二者选其一。","structure":"either + 成分A + or + 成分B","usage":"连接的成分可以是主语、谓语、宾语、表语等，连接主语时，谓语动词遵循“就近原则”，和or后面的主语保持一致","examples":[{"en":"You either starve to death or live like Robinson Crusoe, waiting for a boat which never comes.","zh":"你要么饿死，要么像鲁滨孙·克鲁索那样生活，永远等着一艘永远不会来的船。"},{"en":"You can either come with us to the park or stay at home to read books.","zh":"你要么和我们一起去公园，要么待在家里看书。"}]},{"title":"as引导的方式状语从句","definition":"as可以引导方式状语从句，表示“正如，如同，按照”，用来说明动作的方式或者某人所说的内容。","structure":"as + 主语 + 谓语 + 其他成分","usage":"常用来引用别人的话，或者说明某个动作是按照什么方式进行的","examples":[{"en":"As one of them put it 'ate like kings'.","zh":"正如他们其中一个人说的那样，“吃得像国王一样好”。"},{"en":"As the old saying goes, 'Practice makes perfect'.","zh":"正如老话说的那样：“熟能生巧”。"}]}],"patterns":[{"pattern":"Most of us have formed an unrealistic picture of + 名词/名词短语.","explanation":"","original":{"en":"Most of us have formed an unrealistic picture of life on a desert island.","zh":"我们大多数人对荒岛生活都抱有不切实际的想象。"},"examples":[{"en":"Most of us have formed an unrealistic picture of the life of celebrities.","zh":"我们大多数人对名人的生活都抱有不切实际的想象。"},{"en":"Many children have formed a romantic picture of studying abroad.","zh":"很多孩子对留学的生活都抱有浪漫的想象。"}]},{"pattern":"The other side of the picture is quite the opposite.","explanation":"","original":{"en":"The other side of the picture is quite the opposite.","zh":"而另一种想象则完全相反。"},"examples":[{"en":"People always think being a teacher is easy, but the other side of the picture is quite the opposite.","zh":"人们总觉得当老师很轻松，但实际情况恰恰相反。"},{"en":"Advertisements make the product seem perfect, but the other side of the picture is quite the opposite.","zh":"广告把这个产品说得很完美，但实际情况完全相反。"}]},{"pattern":"When + 时间状语从句, 主语 + be genuinely sorry that + 从句.","explanation":"","original":{"en":"When a passing tanker rescued them five days later, both men were genuinely sorry that they had to leave.","zh":"5天后一艘路过的油轮救了他们，两人都由衷地感到遗憾，不得不离开那里。"},"examples":[{"en":"When the winter vacation came to an end, I was genuinely sorry that I had to go back to school.","zh":"寒假结束的时候，我由衷地感到遗憾，不得不回学校了。"},{"en":"When the party was over, all the guests were genuinely sorry that they had to say goodbye.","zh":"派对结束的时候，所有客人都由衷地不舍，不得不互相道别。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“悲惨的；可怜的；恶劣的” 对应的单词是？","hint":"adjective · /ˈretʃɪd/","options":["reminder","apologize","wretched","astride"],"answer":2,"explain":"wretched · /ˈretʃɪd/ · adjective · 悲惨的；可怜的；恶劣的。用来描述人的处境痛苦，或事物质量差、令人不满","source":{"kind":"vocab","word":"wretched"},"id":"b3-u12-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：天堂；乐园","hint":"/ˈpærədaɪs/ · noun","answer":"paradise","placeholder":"输入英文单词","explain":"paradise · /ˈpærədaɪs/ · noun · 天堂；乐园。可指宗教中的天堂，也可指令人愉悦的完美地方或状态","source":{"kind":"vocab","word":"paradise"},"id":"b3-u12-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Many animals would _____ in winter if they don't store enough food.","hint":"如果没有储存足够的食物，很多动物会在冬天饿死。","answer":"starve to death","placeholder":"输入缺失的短语","explain":"starve to death：固定搭配，表示饿死，强调极端饥饿的后果（如果没有储存足够的食物，很多动物会在冬天饿死。）","source":{"kind":"phrase","phrase":"starve to death"},"id":"b3-u12-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The men collected rainwater in the rubber _____","hint":"两人用橡皮艇收集雨水。","answer":"dinghy","placeholder":"输入缺失的单词","explain":"The men collected rainwater in the rubber dinghy. — 两人用橡皮艇收集雨水。","source":{"kind":"sentence","en":"The men collected rainwater in the rubber dinghy."},"id":"b3-u12-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“either...or...是表示选择关系的并列连词，用来连接两个对等的成分，表示“要么……要么……；或者……或者……”，二者选其一。” 描述的是哪个语法点？","hint":"either + 成分A + or + 成分B","options":["either...or...并列连词结构","too...to... 结构","not only位于句首的部分倒装结构","While 引导的让步状语从句"],"answer":0,"explain":"either...or...并列连词结构：either + 成分A + or + 成分B：连接的成分可以是主语、谓语、宾语、表语等，连接主语时，谓语动词遵循“就近原则”，和or后面的主语保持一致","source":{"kind":"grammar","title":"either...or...并列连词结构"},"id":"b3-u12-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe men collected rainwater in the rubber dinghy.","hint":"","options":["他们将能够，可以说，看到和听到我们的行动。","两人用橡皮艇收集雨水。","门多萨后来又在拳击台上与汉弗莱斯相遇，但他第二次输了。","历史学家长期以来一直对刻在墙壁、骨头和猛犸象牙上的点、线和符号感到困惑。"],"answer":1,"explain":"The men collected rainwater in the rubber dinghy. — 两人用橡皮艇收集雨水。","source":{"kind":"sentence","en":"The men collected rainwater in the rubber dinghy."},"id":"b3-u12-q06"}]},{"id":"b3-u13","book":3,"unit":13,"key":"13","lessonFrom":13,"lessonTo":13,"title":"It's Only Me","titleZh":"“是我呀”","question":"What did the man expect to find under the stairs?","sentences":[{"en":"After her husband had gone to work, Mrs. Richards sent her children to school and went upstairs to her bedroom.","zh":"丈夫去上班后，理查兹夫人把孩子们送去学校，然后上楼到卧室。","t":16.42},{"en":"She was too excited to do any housework that morning, for in the evening she would be going to a fancy-dress party with her husband.","zh":"那个上午她兴奋得顾不上做家务，因为晚上她要和丈夫一起去参加一个化装舞会。","t":24.96},{"en":"She intended to dress up as a ghost and as she had made her costume the night before, she was impatient to try it on.","zh":"她打算打扮成一个鬼魂。由于头天晚上她已做好了化装服，所以她迫不及待地想试穿一下。","t":34.89},{"en":"Though the costume consisted only of a sheet, it was very effective.","zh":"尽管化装服只是一块床单，但效果却非常好。","t":44.23},{"en":"After putting it on, Mrs. Richards went downstairs.","zh":"穿上衣服后，理查兹夫人下了楼。","t":49.62},{"en":"She wanted to find out whether it would be comfortable to wear.","zh":"她想看看穿上是否舒服。","t":53.93},{"en":"Just as Mrs. Richards was entering the dining-room, there was a knock on the front door.","zh":"理查兹夫人刚走进饭厅，前门就传来了敲门声。","t":58.27},{"en":"She knew that it must be the baker.","zh":"她知道肯定是面包师。","t":64.84},{"en":"She had told him to come straight in if ever she failed to open the door and to leave the bread on the kitchen table.","zh":"她曾告诉他，如果她没有开门，他就直接进来，把面包放在厨房的桌子上。","t":67.48},{"en":"Not wanting to frighten the poor man, Mrs. Richards quickly hid in the small storeroom under the stairs.","zh":"理查兹夫人不想吓着那个可怜的人，便迅速躲到了楼梯下的小储藏室里。","t":74.42},{"en":"She heard the front door open and heavy footsteps in the hall.","zh":"她听到前门打开了，走廊里传来沉重的脚步声。","t":82.13},{"en":"Suddenly the door of the storeroom was opened and a man entered.","zh":"突然，储藏室的门开了，一个男人走了进来。","t":87.05},{"en":"Mrs. Richards realized that it must be the man from the Electricity Board who had come to read the metre.","zh":"理查兹夫人意识到这一定是电力公司的抄表员。","t":91.48},{"en":"She tried to explain the situation, saying","zh":"她试图解释情况，说道：","t":98.78},{"en":"'It's only me', but it was too late.","zh":"“是我呀”，但为时已晚。","t":102.15},{"en":"The man let out a cry and jumped back several paces.","zh":"那个男人大叫一声，后退了几步。","t":106.49},{"en":"When Mrs. Richards walked towards him, he fled, slamming the door behind him.","zh":"当理查兹夫人走向他时，他逃走了，并在身后砰地关上了门。","t":111.82}],"vocab":[{"word":"fancy-dress","phonetic":"/ˈfænsi dres/","meanings":[{"pos":"noun (uncountable)","meaning":"化装服，奇装异服","usage":"指用于化装舞会等场合的特殊服饰"}]},{"word":"costume","phonetic":"/ˈkɒstjuːm/","meanings":[{"pos":"noun","meaning":"戏装，（化装舞会的）服饰","usage":"可指演出、化装活动等的特定服装，也可指某个时期或地区的传统服饰"}]},{"word":"impatient","phonetic":"/ɪmˈpeɪʃnt/","meanings":[{"pos":"adjective","meaning":"不耐烦的，渴望的","usage":"常见搭配：be impatient to do sth. 迫不及待做某事；be impatient with sb./sth. 对某人/事不耐烦"}]},{"word":"sheet","phonetic":"/ʃiːt/","meanings":[{"pos":"noun","meaning":"床单；（一）张/片","usage":"除了指床上用品，还可表示薄的片状物，如a sheet of paper一张纸"}]},{"word":"effective","phonetic":"/ɪˈfektɪv/","meanings":[{"pos":"adjective","meaning":"有效的，有效果的","usage":"强调能够产生预期的效果，区别于efficient（高效的，侧重效率）"}]},{"word":"comfortable","phonetic":"/ˈkʌmfətəbl/","meanings":[{"pos":"adjective","meaning":"舒适的，舒服的","usage":"可形容衣物、家具等让人感觉舒服，也可形容人感觉自在"}]},{"word":"baker","phonetic":"/ˈbeɪkə(r)/","meanings":[{"pos":"noun","meaning":"面包师，面包店老板","usage":"由动词bake（烘焙）加表示人的后缀-er构成"}]},{"word":"frighten","phonetic":"/ˈfraɪtn/","meanings":[{"pos":"verb","meaning":"使惊吓，吓唬","usage":"常见搭配：frighten sb. 吓到某人；frighten sb. into doing sth. 威胁某人做某事"}]},{"word":"storeroom","phonetic":"/ˈstɔːruːm/","meanings":[{"pos":"noun","meaning":"储藏室，库房","usage":"复合名词，由store（储藏）和room（房间）构成"}]},{"word":"electricity","phonetic":"/ɪˌlekˈtrɪsəti/","meanings":[{"pos":"noun (uncountable)","meaning":"电，电力","usage":"表示电力、电流的不可数名词，相关形容词为electric（电的）"}]},{"word":"metre","phonetic":"/ˈmiːtə(r)/","meanings":[{"pos":"noun","meaning":"计量器，仪表；米","usage":"文中指电表，也可作为长度单位“米”，美式拼写为meter"}]},{"word":"flee","phonetic":"/fliː/","meanings":[{"pos":"verb","meaning":"逃走，逃离","usage":"过去式和过去分词为fled，强调因害怕、危险而快速逃离"}]},{"word":"slam","phonetic":"/slæm/","meanings":[{"pos":"verb","meaning":"砰地关上，猛摔","usage":"可作及物或不及物动词，强调关门等动作的力度大、声音响"}]}],"phrases":[{"phrase":"dress up as","usage":"表示“装扮成，打扮成”，用于化装、角色扮演等场景","examples":[{"en":"She intended to dress up as a ghost for the party.","zh":"她打算在派对上装扮成鬼魂。"},{"en":"Children love dressing up as cartoon characters on Halloween.","zh":"孩子们喜欢在万圣节装扮成卡通人物。"}]},{"phrase":"try on","usage":"表示“试穿（衣物、配饰等）”，是动副短语，宾语为代词时要放在短语中间","examples":[{"en":"She was impatient to try the new costume on.","zh":"她迫不及待要试穿那件新的化装服。"},{"en":"You should try the shoes on before buying them.","zh":"你买鞋之前应该先试穿一下。"}]},{"phrase":"consist of","usage":"表示“由……组成，由……构成”，不用于被动语态和进行时态","examples":[{"en":"The costume consisted only of a sheet, but it was very effective.","zh":"这件化装服只用了一张床单做成，但效果非常好。"},{"en":"The research team consists of three scientists and two engineers.","zh":"这个研究团队由三名科学家和两名工程师组成。"}]},{"phrase":"find out","usage":"表示“查明，弄清楚”，侧重通过努力、调查等获知事实真相","examples":[{"en":"She wanted to find out whether the costume was comfortable to wear.","zh":"她想弄清楚这件化装服穿起来是否舒服。"},{"en":"Please find out when the train leaves.","zh":"请查一下火车什么时候开。"}]},{"phrase":"let out a cry","usage":"表示“大叫一声，发出一声叫喊”，let out可表示发出（声音、光等）","examples":[{"en":"The man let out a cry and jumped back several paces when he saw the 'ghost'.","zh":"那个男人看到“鬼魂”的时候大叫一声，往后跳了好几步。"},{"en":"She let out a cry of surprise when she saw the birthday gift.","zh":"她看到生日礼物的时候发出了一声惊喜的叫喊。"}]}],"grammar":[{"title":"过去完成时","definition":"表示在过去某个动作或时间之前已经完成的动作，强调“过去的过去”","structure":"had + 动词过去分词","usage":"常与after, before, by the time等引导的时间状语连用，说明两个过去动作的先后顺序","examples":[{"en":"After her husband had gone to work, Mrs. Richards sent her children to school.","zh":"丈夫上班之后，理查兹太太把孩子们送去了学校。"},{"en":"She had made her costume the night before, so she was eager to try it on.","zh":"她前一天晚上就做好了化装服，所以迫不及待想要试穿。"}]},{"title":"too...to... 结构","definition":"表示“太……以至于不能……”，是一种表达否定含义的结构","structure":"too + 形容词/副词 + to do sth.","usage":"当主语是不定式的逻辑宾语时，不定式用主动形式表被动含义","examples":[{"en":"She was too excited to do any housework that morning.","zh":"那天早上她太兴奋了，什么家务都做不进去。"},{"en":"The box is too heavy for the little boy to carry.","zh":"这个箱子太重了，小男孩搬不动。"}]},{"title":"现在分词作原因状语","definition":"现在分词短语可以在句中作状语，说明主句动作发生的原因，相当于原因状语从句","structure":"（Not +）现在分词短语, 主句","usage":"现在分词的逻辑主语要和主句主语保持一致，表否定时not放在现在分词前面","examples":[{"en":"Not wanting to frighten the poor man, Mrs. Richards quickly hid under the stairs.","zh":"因为不想吓到这个可怜的人，理查兹太太迅速躲到了楼梯底下。"},{"en":"Feeling tired, he stopped working to have a rest.","zh":"因为感觉很累，他停下工作休息了一会儿。"}]}],"patterns":[{"pattern":"主语 + be too + 形容词 + to do sth.","explanation":"","original":{"en":"She was too excited to do any housework that morning.","zh":"那天早上她太兴奋了，什么家务都做不进去。"},"examples":[{"en":"He was too nervous to say a word in front of the audience.","zh":"他太紧张了，在观众面前一句话都说不出来。"},{"en":"The coffee is too hot to drink right now.","zh":"咖啡太烫了，现在没法喝。"}]},{"pattern":"主语 + intend to do sth.","explanation":"","original":{"en":"She intended to dress up as a ghost for the fancy-dress party.","zh":"她打算在化装舞会上装扮成鬼魂。"},"examples":[{"en":"I intend to travel to Japan with my family this summer holiday.","zh":"我打算今年暑假和家人一起去日本旅行。"},{"en":"The company intends to set up a new branch in Guangzhou next year.","zh":"这家公司打算明年在广州开一家新的分公司。"}]},{"pattern":"Just as + 从句, 主句","explanation":"","original":{"en":"Just as Mrs. Richards was entering the dining-room, there was a knock on the front door.","zh":"就在理查兹太太走进餐厅的时候，前门传来了敲门声。"},"examples":[{"en":"Just as I was leaving the house, it started to rain heavily.","zh":"就在我出门的时候，开始下大雨了。"},{"en":"Just as he finished his speech, the audience broke into warm applause.","zh":"就在他结束演讲的时候，观众爆发出了热烈的掌声。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“床单；（一）张/片” 对应的单词是？","hint":"noun · /ʃiːt/","options":["sheet","stray","fresco","luscious"],"answer":0,"explain":"sheet · /ʃiːt/ · noun · 床单；（一）张/片。除了指床上用品，还可表示薄的片状物，如a sheet of paper一张纸","source":{"kind":"vocab","word":"sheet"},"id":"b3-u13-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：面包师，面包店老板","hint":"/ˈbeɪkə(r)/ · noun","answer":"baker","placeholder":"输入英文单词","explain":"baker · /ˈbeɪkə(r)/ · noun · 面包师，面包店老板。由动词bake（烘焙）加表示人的后缀-er构成","source":{"kind":"vocab","word":"baker"},"id":"b3-u13-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：She intended to _____ a ghost for the party.","hint":"她打算在派对上装扮成鬼魂。","answer":"dress up as","placeholder":"输入缺失的短语","explain":"dress up as：表示“装扮成，打扮成”，用于化装、角色扮演等场景（她打算在派对上装扮成鬼魂。）","source":{"kind":"phrase","phrase":"dress up as"},"id":"b3-u13-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Not wanting to frighten the _____ man, Mrs. Richards quickly hid in the small storeroom under the stairs.","hint":"理查兹夫人不想吓着那个可怜的人，便迅速躲到了楼梯下的小储藏室里。","answer":"poor","placeholder":"输入缺失的单词","explain":"Not wanting to frighten the poor man, Mrs. Richards quickly hid in the small storeroom under the stairs. — 理查兹夫人不想吓着那个可怜的人，便迅速躲到了楼梯下的小储藏室里。","source":{"kind":"sentence","en":"Not wanting to frighten the poor man, Mrs. Richards quickly hid in the small storeroom under the stairs."},"id":"b3-u13-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“现在分词短语可以在句中作状语，说明主句动作发生的原因，相当于原因状语从句” 描述的是哪个语法点？","hint":"（Not +）现在分词短语, 主句","options":["过去进行时 (Past Continuous Tense)","the + 比较级, the + 比较级 结构","定语从句的分隔现象","现在分词作原因状语"],"answer":3,"explain":"现在分词作原因状语：（Not +）现在分词短语, 主句：现在分词的逻辑主语要和主句主语保持一致，表否定时not放在现在分词前面","source":{"kind":"grammar","title":"现在分词作原因状语"},"id":"b3-u13-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe man let out a cry and jumped back several paces.","hint":"","options":["一些女人会认为她们的丈夫总会把事情弄好。","在最后一幕中，一个狱卒总是会带着一封信上台，然后递给囚犯。","那个男人大叫一声，后退了几步。","我告诉她，要么我买一台新割草机，要么就让草长着。"],"answer":2,"explain":"The man let out a cry and jumped back several paces. — 那个男人大叫一声，后退了几步。","source":{"kind":"sentence","en":"The man let out a cry and jumped back several paces."},"id":"b3-u13-q06"}]},{"id":"b3-u14","book":3,"unit":14,"key":"14","lessonFrom":14,"lessonTo":14,"title":"A Noble Gangster","titleZh":"一位“高尚的”歹徒","question":"How did Hawkwood make money in times of peace?","sentences":[{"en":"There was a time when the owners of shops and businesses in Chicago had to pay large sums of money to gangsters in return for 'protection'.","zh":"过去，芝加哥的店主和商人们不得不向歹徒支付大笔金钱，以换取“保护”。","t":15.2},{"en":"If the money was not paid promptly, the gangsters would quickly put a man out of business by destroying his shop.","zh":"如果不及时付款，歹徒就会捣毁店主的店铺，使其很快破产。","t":26.33},{"en":"Obtaining 'protection money' is not a modern crime.","zh":"敲诈“保护费”并非是现代社会的罪行。","t":35.46},{"en":"As long ago as the fourteenth century, an Englishman, Sir John Hawkwood, made the remarkable discovery that people would rather pay large sums of money than have their life work destroyed by gangsters.","zh":"远在14世纪，英国人约翰·霍克伍德爵士就有了惊人的发现，人们情愿支付大笔金钱，也不愿自己的毕生心血毁于歹徒之手。","t":39.67},{"en":"Six hundred years ago, Sir John Hawkwood arrived in Italy with a band of soldiers and settled near Florence.","zh":"600年前，约翰·霍克伍德爵士率领一队士兵抵达意大利，在佛罗伦萨附近定居下来。","t":56.51},{"en":"He soon made a name for himself and came to be known to the Italians as Giovanni Acuto.","zh":"他很快就出了名，意大利人称他为乔瓦尼·阿库托。","t":65.36},{"en":"Whenever the Italian city-states were at war with each other, Hawkwood used to hire his soldiers to princes who were willing to pay the high price he demanded.","zh":"无论意大利城邦之间何时交战，霍克伍德总是将他的士兵雇佣给那些愿意支付他所要求的高价的君主。","t":73.45},{"en":"In times of peace, when business was bad, Hawkwood and his men would march into a city-state, and after burning down a few farms, would offer to go away if protection money was paid to them.","zh":"在和平时期，当生意不好时，霍克伍德和他的手下就会开进一个城邦，烧毁几座农场后，提出如果向他们支付保护费，他们就离开。","t":85.4},{"en":"Hawkwood made large sums of money in this way.","zh":"霍克伍德就是这样赚取了大笔金钱。","t":100.29},{"en":"In spite of this, the Italians regarded him as a sort of hero.","zh":"尽管如此，意大利人还是把他看作一个英雄。","t":104.35},{"en":"When he died at the age of eighty, the Florentines gave him a state funeral and had a picture painted which was dedicated to the memory of 'the most valiant soldier and most notable leader, Signor Giovanni Haukodue'.","zh":"他80岁去世时，佛罗伦萨人为他举行了国葬，并绘制了一幅纪念他的画像，画像上写着：“最英勇的士兵和最杰出的领袖，乔瓦尼·霍克伍德先生”。","t":109.86}],"vocab":[{"word":"gangster","phonetic":"/ˈɡæŋstər/","meanings":[{"pos":"noun","meaning":"歹徒，匪徒，黑帮成员","usage":"指参与有组织犯罪的人，常带有暴力性质"}]},{"word":"protection","phonetic":"/prəˈtekʃn/","meanings":[{"pos":"noun","meaning":"保护，防护；（黑社会索要的）保护费","usage":"既可指普通的保护行为，也可指黑帮名义上提供“保护”实则勒索的费用"}]},{"word":"promptly","phonetic":"/ˈprɒmptli/","meanings":[{"pos":"adverb","meaning":"及时地，迅速地，立即地","usage":"强调动作发生得准时、没有延迟"}]},{"word":"destroy","phonetic":"/dɪˈstrɔɪ/","meanings":[{"pos":"verb","meaning":"破坏，毁坏，摧毁","usage":"指彻底损坏某物，使其无法使用或恢复"}]},{"word":"crime","phonetic":"/kraɪm/","meanings":[{"pos":"noun","meaning":"罪行，犯罪行为","usage":"指违反法律、应受到惩罚的行为"}]},{"word":"remarkable","phonetic":"/rɪˈmɑːkəbl/","meanings":[{"pos":"adjective","meaning":"非凡的，引人注目的，出色的","usage":"用来形容人或事物不同寻常、值得注意"}]},{"word":"settle","phonetic":"/ˈsetl/","meanings":[{"pos":"verb","meaning":"定居，安家；解决","usage":"表示在某地长期居住，也可指处理、解决问题或纠纷"}]},{"word":"valiant","phonetic":"/ˈvæliənt/","meanings":[{"pos":"adjective","meaning":"英勇的，勇敢的，果敢的","usage":"用于形容人在危险或困难情境下表现出的勇气，带有褒义"}]},{"word":"notable","phonetic":"/ˈnəʊtəbl/","meanings":[{"pos":"adjective","meaning":"显著的，著名的，值得注意的","usage":"指人或事物因成就、特点等被广泛知晓"}]},{"word":"dedicate","phonetic":"/ˈdedɪkeɪt/","meanings":[{"pos":"verb","meaning":"把……奉献给；题献（作品等）","usage":"常用搭配dedicate sth to sb/sth，表示将某物用于特定目的或献给某人"}]}],"phrases":[{"phrase":"in return for","usage":"表示“作为对……的回报/交换”，后接名词或动名词，引出交换的对象","examples":[{"en":"I bought him a drink in return for his help.","zh":"我给他买了一杯饮料，作为对他帮助的回报。"},{"en":"The workers get salary in return for their daily work.","zh":"工人们获得薪水，作为日常工作的报酬。"}]},{"phrase":"put sb out of business","usage":"表示“使某人停业，迫使某人破产”，指让企业或商家无法继续经营","examples":[{"en":"The big supermarket put many small shops out of business last year.","zh":"去年这家大型超市迫使很多小商店停业了。"},{"en":"The serious fire almost put the factory out of business.","zh":"那场严重的火灾几乎让这家工厂破产。"}]},{"phrase":"make a name for oneself","usage":"表示“出名，成名”，指通过自身努力获得名声、知名度","examples":[{"en":"She made a name for herself as a talented singer at a young age.","zh":"她年轻时就作为一名有天赋的歌手成名了。"},{"en":"The designer made a name for himself with his unique style.","zh":"这位设计师凭借其独特的风格出了名。"}]},{"phrase":"be at war with","usage":"表示“与……处于交战状态”，主语常为国家、城邦等政权主体","examples":[{"en":"The two countries were at war with each other for three years.","zh":"这两个国家彼此交战了三年。"},{"en":"The kingdom was at war with its neighbor for control of the island.","zh":"这个王国为了争夺岛屿的控制权与邻国交战。"}]},{"phrase":"in spite of","usage":"表示“尽管，不管”，后接名词、代词或动名词，引导让步关系，相当于despite","examples":[{"en":"In spite of the heavy rain, he still went to work on time.","zh":"尽管下着大雨，他还是准时去上班了。"},{"en":"They kept climbing the mountain in spite of the bad weather.","zh":"尽管天气恶劣，他们还是继续登山。"}]},{"phrase":"dedicate to the memory of","usage":"表示“为纪念……”，常用于艺术作品、纪念碑等，表达对逝者的纪念","examples":[{"en":"This book is dedicated to the memory of my grandfather.","zh":"这本书是为了纪念我的祖父而写的。"},{"en":"The monument was dedicated to the memory of the soldiers who died in the war.","zh":"这座纪念碑是为了纪念在战争中牺牲的士兵而建的。"}]}],"grammar":[{"title":"would rather ... than ... 结构","definition":"表达“宁愿做……而不愿做……”的选择偏好，强调在两个选项中更倾向于前者","structure":"主语 + would rather + 动词原形 + than + 动词原形","usage":"用于表示主观上的选择，than前后的动词形式要保持一致，否定形式为would rather not do sth","examples":[{"en":"People would rather pay large sums of money than have their life work destroyed by gangsters.","zh":"人们宁愿支付大笔钱财，也不愿自己毕生的事业被歹徒毁掉。"},{"en":"I would rather stay at home reading than go to the noisy party.","zh":"我宁愿待在家看书，也不愿去那个吵闹的派对。"}]},{"title":"时间状语从句：There was a time when ...","definition":"表示“曾经有一段时间……”，用于描述过去某段时间内经常发生的情况或存在的状态","structure":"There was a time + when引导的定语从句，when在从句中作时间状语","usage":"用来引出过去的特定时期的情况，when引导的从句通常用一般过去时","examples":[{"en":"There was a time when the owners of shops and businesses in Chicago had to pay large sums of money to gangsters in return for 'protection'.","zh":"曾经有一段时间，芝加哥的店主和商人不得不向歹徒支付大笔钱财以换取“保护”。"},{"en":"There was a time when I lived in the countryside and played with my friends every day.","zh":"曾经有一段时间我住在乡下，每天都和朋友们一起玩耍。"}]}],"patterns":[{"pattern":"If + 一般过去时的条件从句, 主语 + would + 动词原形","explanation":"","original":{"en":"If the money was not paid promptly, the gangsters would quickly put a man out of business by destroying his shop.","zh":"如果钱没有及时支付，歹徒们就会捣毁他的店铺，很快让他破产。"},"examples":[{"en":"If I got the ticket, I would go to the concert with you.","zh":"如果我拿到票的话，我就会和你一起去听音乐会。"},{"en":"If he practiced more, he would pass the driving test easily.","zh":"如果他多练习的话，他就能轻松通过驾照考试。"}]},{"pattern":"When + 时间状语从句, 主语 + 主句动作","explanation":"","original":{"en":"When he died at the age of eighty, the Florentines gave him a state funeral and had a picture painted which was dedicated to the memory of 'the most valiant soldier and most notable leader, Signor Giovanni Haukodue'.","zh":"当他80岁去世时，佛罗伦萨人为他举行了国葬，还为他画了一幅画像，以纪念这位“最英勇的战士和最杰出的领袖，乔瓦尼·奥库多先生”。"},"examples":[{"en":"When the old professor retired, the school held a grand party and gave him a medal in honor of his 40 years of teaching.","zh":"当这位老教授退休时，学校举办了一场盛大的聚会，还给他颁发了一枚奖章，以表彰他40年的教学工作。"},{"en":"When the team won the championship, the fans cheered loudly and held a parade through the city to celebrate the victory.","zh":"当这支队伍赢得冠军时，球迷们大声欢呼，还在城市里举行了游行来庆祝胜利。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“非凡的，引人注目的，出色的” 对应的单词是？","hint":"adjective · /rɪˈmɑːkəbl/","options":["snore","share","hunt","remarkable"],"answer":3,"explain":"remarkable · /rɪˈmɑːkəbl/ · adjective · 非凡的，引人注目的，出色的。用来形容人或事物不同寻常、值得注意","source":{"kind":"vocab","word":"remarkable"},"id":"b3-u14-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：及时地，迅速地，立即地","hint":"/ˈprɒmptli/ · adverb","answer":"promptly","placeholder":"输入英文单词","explain":"promptly · /ˈprɒmptli/ · adverb · 及时地，迅速地，立即地。强调动作发生得准时、没有延迟","source":{"kind":"vocab","word":"promptly"},"id":"b3-u14-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The workers get salary _____ their daily work.","hint":"工人们获得薪水，作为日常工作的报酬。","answer":"in return for","placeholder":"输入缺失的短语","explain":"in return for：表示“作为对……的回报/交换”，后接名词或动名词，引出交换的对象（工人们获得薪水，作为日常工作的报酬。）","source":{"kind":"phrase","phrase":"in return for"},"id":"b3-u14-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：As long ago as the fourteenth century, an Englishman, Sir John Hawkwood, made the remarkable discovery that people would rather pay large sums of money than have their life work _____ by gangsters.","hint":"远在14世纪，英国人约翰·霍克伍德爵士就有了惊人的发现，人们情愿支付大笔金钱，也不愿自己的毕生心血毁于歹徒之手。","answer":"destroyed","placeholder":"输入缺失的单词","explain":"As long ago as the fourteenth century, an Englishman, Sir John Hawkwood, made the remarkable discovery that people would rather pay large sums of money than have their life work destroyed by gangsters. — 远在14世纪，英国人约翰·霍克伍德爵士就有了惊人的发现，人们情愿支付大笔金钱，也不愿自己的毕生心血毁于歹徒之手。","source":{"kind":"sentence","en":"As long ago as the fourteenth century, an Englishman, Sir John Hawkwood, made the remarkable discovery that people would rather pay large sums of money than have their life work destroyed by gangsters."},"id":"b3-u14-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表达“宁愿做……而不愿做……”的选择偏好，强调在两个选项中更倾向于前者” 描述的是哪个语法点？","hint":"主语 + would rather + 动词原形 + than + 动词原形","options":["would rather ... than ... 结构","被动语态 (Passive Voice)","动词不定式作表语 (Infinitive as Predicative)","双关语 (Pun)"],"answer":0,"explain":"would rather ... than ... 结构：主语 + would rather + 动词原形 + than + 动词原形：用于表示主观上的选择，than前后的动词形式要保持一致，否定形式为would rather not do sth","source":{"kind":"grammar","title":"would rather ... than ... 结构"},"id":"b3-u14-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nSix hundred years ago, Sir John Hawkwood arrived in Italy with a band of soldiers and settled near Florence.","hint":"","options":["霍克伍德就是这样赚取了大笔金钱。","我们在一个小镇上呆了几天，参观了附近的一些古老的教堂。","船上许多游客已和小贩们讨价还价起来，","600年前，约翰·霍克伍德爵士率领一队士兵抵达意大利，在佛罗伦萨附近定居下来。"],"answer":3,"explain":"Six hundred years ago, Sir John Hawkwood arrived in Italy with a band of soldiers and settled near Florence. — 600年前，约翰·霍克伍德爵士率领一队士兵抵达意大利，在佛罗伦萨附近定居下来。","source":{"kind":"sentence","en":"Six hundred years ago, Sir John Hawkwood arrived in Italy with a band of soldiers and settled near Florence."},"id":"b3-u14-q06"}]},{"id":"b3-u15","book":3,"unit":15,"key":"15","lessonFrom":15,"lessonTo":15,"title":"Fifty Pence Worth of Trouble","titleZh":"五十便士的麻烦","question":"Did George get anything for his fifty pence? What?","sentences":[{"en":"Children always appreciate small gifts of money.","zh":"孩子们总是喜欢收到小额的零用钱。","t":16.65},{"en":"Mum or dad, of course, provides a regular supply of pocket money, but uncles and aunts are always a source of extra income.","zh":"当然，爸爸妈妈会定期地给零花钱，但叔叔阿姨们总是额外的收入来源。","t":20.6},{"en":"With some children, small sums go a long way.","zh":"对有些孩子来说，小数目也能派上大用场。","t":30.99},{"en":"If fifty pence pieces are not exchanged for sweets, they rattle for months inside money boxes.","zh":"如果五十便士没有换成糖果，它们就会在钱箱里叮当响上好几个月。","t":35.17},{"en":"Only very thrifty children manage to fill up a money box.","zh":"只有非常节俭的孩子才能把钱箱装满。","t":43.16},{"en":"For most of them, fifty pence is a small price to pay for a nice big bar of chocolate.","zh":"对于他们中的大多数人来说，五十便士买一大块美味的巧克力是很划算的。","t":48.59},{"en":"My nephew, George, has a money box but it is always empty.","zh":"我的侄子乔治有一个钱箱，但它总是空的。","t":56.95},{"en":"Very few of the fifty pence pieces and pound coins I have given him have found their way there.","zh":"我给他的五十便士硬币和英镑硬币很少有能存到那里的。","t":62.34},{"en":"I gave him fifty pence yesterday and advised him to save it.","zh":"昨天我给了他五十便士，并建议他存起来。","t":70.05},{"en":"Instead, he bought himself fifty pence worth of trouble.","zh":"结果，他却给自己买来了五十便士的麻烦。","t":74.63},{"en":"On his way to the sweet shop, he dropped his fifty pence and it bounced along the pavement and then disappeared down a drain.","zh":"在去糖果店的路上，他把五十便士掉了，它沿着人行道跳动，然后掉进了一个下水道。","t":79.56},{"en":"George took off his jacket,","zh":"乔治脱下他的夹克，","t":89.81},{"en":"rolled up his sleeves and pushed his right arm through the drain cover.","zh":"卷起袖子，把右臂伸进了下水道盖子。","t":92.21},{"en":"He could not find his 50 pence piece anywhere, and what is more, he could not get his arm out.","zh":"他到处都找不到他的五十便士硬币，更糟的是，他抽不出他的胳膊了。","t":97.54},{"en":"A crowd of people gathered round him and a lady rubbed his arm with soap and butter, but George was firmly stuck.","zh":"一群人围在他周围，一位女士用肥皂和黄油擦他的胳膊，但乔治被牢牢地卡住了。","t":105.86},{"en":"The fire brigade was called and two fire fighters freed George using a special type of grease.","zh":"消防队被叫来了，两名消防队员用一种特殊的润滑脂把乔治解救了出来。","t":115.35},{"en":"George was not too upset by his experience because the lady who owns the sweet shop heard about his troubles and rewarded him with a large box of chocolates.","zh":"乔治并没有因为这次经历而太难过，因为糖果店的老板娘听说了他的麻烦，并奖励了他一大盒巧克力。","t":122.73}],"vocab":[{"word":"appreciate","phonetic":"/əˈpriːʃieɪt/","meanings":[{"pos":"verb","meaning":"感激，欣赏；喜欢","usage":"此处表示对小礼物的喜爱和重视，后面可直接接名词作宾语"}]},{"word":"pence","phonetic":"/pens/","meanings":[{"pos":"noun","meaning":"便士（英国货币单位，penny的复数形式）","usage":"是英国辅币单位，100便士等于1英镑"}]},{"word":"thrifty","phonetic":"/ˈθrɪfti/","meanings":[{"pos":"adjective","meaning":"节俭的，节约的","usage":"用于形容人在花钱上很节省，褒义词"}]},{"word":"bounce","phonetic":"/baʊns/","meanings":[{"pos":"verb","meaning":"弹跳，反弹","usage":"指物体碰到硬面后弹回，也可指人蹦跳着走"}]},{"word":"pavement","phonetic":"/ˈpeɪvmənt/","meanings":[{"pos":"noun","meaning":"人行道","usage":"英式英语用词，对应美式英语的sidewalk"}]},{"word":"drain","phonetic":"/dreɪn/","meanings":[{"pos":"noun","meaning":"下水道，排水管","usage":"此处指路边的排水设施，作动词时意为“排空，流干”"}]},{"word":"sleeve","phonetic":"/sliːv/","meanings":[{"pos":"noun","meaning":"袖子","usage":"指衣服的袖子部分，常见搭配roll up sleeves意为“卷起袖子，准备大干”"}]},{"word":"grease","phonetic":"/ɡriːs/","meanings":[{"pos":"noun","meaning":"油脂，润滑剂","usage":"指用作润滑的油脂，也可指烹饪产生的油脂"}]},{"word":"reward","phonetic":"/rɪˈwɔːd/","meanings":[{"pos":"verb","meaning":"奖励，奖赏","usage":"常用搭配reward sb with sth，意为“用某物奖励某人”"}]},{"word":"rattle","phonetic":"/ˈrætl/","meanings":[{"pos":"verb","meaning":"发出咯咯声，咔嗒作响","usage":"此处指硬币在存钱罐里碰撞发出声响"}]},{"word":"extra","phonetic":"/ˈekstrə/","meanings":[{"pos":"adjective","meaning":"额外的，附加的","usage":"用于修饰名词，表示超出常规的部分"}]},{"word":"sum","phonetic":"/sʌm/","meanings":[{"pos":"noun","meaning":"金额，款项；总和","usage":"表示一笔钱时，常用small/large sum来描述金额大小"}]}],"phrases":[{"phrase":"worth of","usage":"表示“价值……的东西”，前面加金额，后面接名词，说明价值对应的物品","examples":[{"en":"I bought ten dollars' worth of snacks for the picnic.","zh":"我买了价值十美元的零食用于野餐。"},{"en":"He gave me two yuan worth of stamps.","zh":"他给了我价值两元的邮票。"}]},{"phrase":"go a long way","usage":"表示（钱、物品等）可以用很长时间，很经花；也可表示“大有帮助”","examples":[{"en":"A little kindness will go a long way when you meet people in trouble.","zh":"当你遇到有困难的人时，一点善意会帮上大忙。"},{"en":"If you are careful, this bottle of milk will go a long way.","zh":"如果你省着点用，这瓶牛奶可以喝很久。"}]},{"phrase":"exchange for","usage":"表示“把……兑换成/换成……”，用于物品或货币的交换","examples":[{"en":"You can exchange your leftover foreign currency for local money at the airport.","zh":"你可以在机场把剩下的外币兑换成当地货币。"},{"en":"He exchanged his old phone for a new one by paying extra money.","zh":"他补了差价，把旧手机换成了新的。"}]},{"phrase":"find one's way to/into","usage":"表示“偶然到达，最终进入”，主语常是物，暗含“不经意间去到某个地方”的含义","examples":[{"en":"Many of the books I bought never found their way to the bookshelf; they just stayed on my desk.","zh":"我买的很多书从来没被放到书架上，就一直摆在我的书桌上。"},{"en":"The lost key finally found its way into my jacket pocket.","zh":"那把丢失的钥匙最后居然在我夹克口袋里找到了。"}]},{"phrase":"roll up sleeves","usage":"字面意思是卷起袖子，常引申为“准备动手干活，准备大干一场”","examples":[{"en":"After finishing the plan, we rolled up our sleeves and started the project.","zh":"完成计划后，我们撸起袖子开始做这个项目。"},{"en":"Roll up your sleeves; we have a lot of dishes to wash today.","zh":"准备干活吧，我们今天有好多盘子要洗。"}]},{"phrase":"what is more","usage":"插入语，意为“而且，更重要的是”，用于补充说明更严重或更重要的情况","examples":[{"en":"It's difficult to finish this task in one day, and what is more, we don't have enough tools.","zh":"一天内完成这个任务很难，而且我们还没有足够的工具。"},{"en":"The hotel is not comfortable, and what is more, it's far from the city center.","zh":"这家酒店住起来不舒服，而且离市中心还很远。"}]}],"grammar":[{"title":"一般现在时表客观事实和普遍规律","definition":"用于描述不受时间限制的客观真理、普遍存在的事实或者经常性的习惯动作","structure":"主语 + 动词原形/动词第三人称单数形式 + 其他","usage":"当描述大众普遍认可的规律、常态情况时，不管上下文其他时态，都用一般现在时","examples":[{"en":"Children always appreciate small gifts of money.","zh":"孩子们总是喜欢得到一些小额零花钱作为礼物。"},{"en":"The earth moves around the sun.","zh":"地球绕着太阳转。"}]},{"title":"because引导的原因状语从句","definition":"用来解释主句动作发生的原因，是最常用的原因状语从句引导词","structure":"主句 + because + 从句，或者Because + 从句, + 主句","usage":"可以用来回答why提出的问题，从句说明直接、明确的原因","examples":[{"en":"George was not too upset by his experience because the lady who owns the sweet shop heard about his troubles and rewarded him with a large box of chocolates.","zh":"乔治对这次经历并没有太难过，因为糖果店的女老板听说了他遇到的麻烦，奖励了他一大盒巧克力。"},{"en":"I stayed at home yesterday because it was raining heavily.","zh":"我昨天待在家里，因为当时雨下得很大。"}]}],"patterns":[{"pattern":"A is a small price to pay for B.","explanation":"","original":{"en":"For most of them, fifty pence is a small price to pay for a nice big bar of chocolate.","zh":"对他们中的大多数人来说，花50便士买一大块好吃的巧克力是很值的。"},"examples":[{"en":"For many students, two hours' study every day is a small price to pay for a good score in the exam.","zh":"对很多学生来说，每天学习两小时，用来换取考试的好成绩是很划算的。"},{"en":"I think getting up early is a small price to pay for the beautiful sunrise on the mountain.","zh":"我觉得为了看山上美丽的日出，早起一点是完全值得的。"}]},{"pattern":"Instead, sb did sth.","explanation":"","original":{"en":"I gave him fifty pence yesterday and advised him to save it. Instead, he bought himself fifty pence worth of trouble.","zh":"我昨天给了他50便士，劝他存起来。可他却用这50便士给自己买了麻烦。"},"examples":[{"en":"My mom told me to finish my homework first. Instead, I played computer games for three hours.","zh":"我妈妈让我先写完作业。我反而玩了三个小时的电脑游戏。"},{"en":"The doctor advised him to stop drinking alcohol. Instead, he drank even more than before.","zh":"医生建议他戒酒。他反而喝得比以前更多了。"}]},{"pattern":"Sb did sth, and what is more, sb could not do sth.","explanation":"","original":{"en":"He could not find his 50 pence piece anywhere, and what is more, he could not get his arm out.","zh":"他到处都找不到那50便士，而且他的胳膊还拔不出来了。"},"examples":[{"en":"He missed the last bus home, and what is more, he forgot to take his house key with him.","zh":"他错过了回家的末班车，而且他还忘带家门钥匙了。"},{"en":"The team lost the important match, and what is more, their best player got injured during the game.","zh":"球队输掉了这场重要的比赛，而且他们最好的球员还在比赛中受了伤。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“额外的，附加的” 对应的单词是？","hint":"adjective · /ˈekstrə/","options":["aristocrat","extra","damage","scanty"],"answer":1,"explain":"extra · /ˈekstrə/ · adjective · 额外的，附加的。用于修饰名词，表示超出常规的部分","source":{"kind":"vocab","word":"extra"},"id":"b3-u15-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：感激，欣赏；喜欢","hint":"/əˈpriːʃieɪt/ · verb","answer":"appreciate","placeholder":"输入英文单词","explain":"appreciate · /əˈpriːʃieɪt/ · verb · 感激，欣赏；喜欢。此处表示对小礼物的喜爱和重视，后面可直接接名词作宾语","source":{"kind":"vocab","word":"appreciate"},"id":"b3-u15-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：If you are careful, this bottle of milk will _____.","hint":"如果你省着点用，这瓶牛奶可以喝很久。","answer":"go a long way","placeholder":"输入缺失的短语","explain":"go a long way：表示（钱、物品等）可以用很长时间，很经花；也可表示“大有帮助”（如果你省着点用，这瓶牛奶可以喝很久。）","source":{"kind":"phrase","phrase":"go a long way"},"id":"b3-u15-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：With some _____ small sums go a long way.","hint":"对有些孩子来说，小数目也能派上大用场。","answer":"children","placeholder":"输入缺失的单词","explain":"With some children, small sums go a long way. — 对有些孩子来说，小数目也能派上大用场。","source":{"kind":"sentence","en":"With some children, small sums go a long way."},"id":"b3-u15-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于描述不受时间限制的客观真理、普遍存在的事实或者经常性的习惯动作” 描述的是哪个语法点？","hint":"主语 + 动词原形/动词第三人称单数形式 + 其他","options":["时间状语从句：There was a time when ...","it作形式主语/形式宾语","because引导的原因状语从句","一般现在时表客观事实和普遍规律"],"answer":3,"explain":"一般现在时表客观事实和普遍规律：主语 + 动词原形/动词第三人称单数形式 + 其他：当描述大众普遍认可的规律、常态情况时，不管上下文其他时态，都用一般现在时","source":{"kind":"grammar","title":"一般现在时表客观事实和普遍规律"},"id":"b3-u15-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nWith some children, small sums go a long way.","hint":"","options":["除了她所有的其他优点，贝茜还是一位烹饪专家。","理查兹夫人刚走进饭厅，前门就传来了敲门声。","没有指纹痕迹，但警督发现了一个脏兮兮的红色包裹，里面装着珠宝，老太太说那不是她的。","对有些孩子来说，小数目也能派上大用场。"],"answer":3,"explain":"With some children, small sums go a long way. — 对有些孩子来说，小数目也能派上大用场。","source":{"kind":"sentence","en":"With some children, small sums go a long way."},"id":"b3-u15-q06"}]},{"id":"b3-u16","book":3,"unit":16,"key":"16","lessonFrom":16,"lessonTo":16,"title":"Mary Had a Little Lamb","titleZh":"玛丽有只小羊羔","question":"Was Dimitri right to apologize to his neighbour? Why not?","sentences":[{"en":"Mary and her husband Dimitri lived in the tiny village of Perachora in southern Greece.","zh":"玛丽和她的丈夫迪米特里住在希腊南部佩拉霍拉的一个小村庄里。","t":15.03},{"en":"One of Mary's prize possessions was a little white lamb which her husband had given her.","zh":"玛丽最珍贵的财产之一是她丈夫送给她的一只白色小羊羔。","t":25.07},{"en":"She kept it tied to a tree in a field during the day and went to fetch it every evening.","zh":"白天她把它拴在田野里的一棵树上，每天傍晚都去把它牵回来。","t":31.82},{"en":"One evening, however the lamb was missing.","zh":"然而，一个晚上，那只羊不见了。","t":39.4},{"en":"The rope had been cut, so it was obvious that the lamb had been stolen.","zh":"绳子被割断了，很明显羊被偷了。","t":43.27},{"en":"When Dimitri came in from the fields, his wife told him what had happened.","zh":"迪米特里从田里回来时，他的妻子把发生的一切告诉了他。","t":49.52},{"en":"Dimitri at once set out to find the thief.","zh":"迪米特里立刻出去寻找小偷。","t":54.17},{"en":"He knew it would not prove difficult in such a small village.","zh":"他知道在这样一个小村庄里，找到小偷不会很难。","t":58.91},{"en":"After telling several of his friends about the theft,","zh":"在把失窃的事告诉他的几个朋友之后，","t":64.21},{"en":"Dimitri found out that his neighbour, Aleko, had suddenly acquired a new lamb.","zh":"迪米特里发现他的邻居阿列科突然多了一只新羊。","t":67.78},{"en":"Dimitri immediately went to Aleko's house and angrily accused him of stealing the lamb.","zh":"迪米特里立刻去了阿列科家，愤怒地指责他偷了羊。","t":75.19},{"en":"He told him he had better return it or he would call the police.","zh":"他告诉阿列科最好把羊还回来，否则他就报警。","t":82.68},{"en":"Aleko denied taking it and led Dimitri into his backyard.","zh":"阿列科否认偷了羊，并把迪米特里领进了他的后院。","t":87.61},{"en":"It was true that he had just bought a lamb he explained, but his lamb was black.","zh":"他解释说，他确实刚买了一只羊，但他的羊是黑色的。","t":93.03},{"en":"Ashamed of having acted so rashly, Dimitri apologized to Aleko for having accused him.","zh":"迪米特里为自己如此鲁莽的行为感到羞愧，他向阿列科为自己的指责道了歉。","t":100.35},{"en":"While they were talking it began to rain and Dimitri stayed in Aleko's house until the rain stopped.","zh":"他们谈话的时候开始下雨了，迪米特里就在阿列科家里待到雨停。","t":108.26},{"en":"When he went outside half an hour later, he was astonished to find that the little black lamb was almost white.","zh":"半小时后，当他出去时，他惊奇地发现那只黑色的小羊几乎是白色的。","t":116.11},{"en":"Its wool, which had been dyed black, had been washed clean by the rain!","zh":"它的羊毛，原来被染成了黑色，被雨水冲洗干净了！","t":125.48}],"vocab":[{"word":"prize","phonetic":"/praɪz/","meanings":[{"pos":"adjective","meaning":"珍贵的，引以为傲的","usage":"用于修饰名词，描述某物是主人非常珍视的"},{"pos":"noun","meaning":"奖品，奖金","usage":"指竞赛、比赛中获得的奖励"}]},{"word":"possession","phonetic":"/pəˈzeʃn/","meanings":[{"pos":"noun","meaning":"所有物，财产","usage":"常用复数形式possessions表示个人全部财物，单数可指某一件所有物"}]},{"word":"tie","phonetic":"/taɪ/","meanings":[{"pos":"verb","meaning":"系，拴，绑","usage":"常用搭配tie sth to sth表示把某物拴在另一物上"},{"pos":"noun","meaning":"领带；纽带，联系","usage":"可指服饰类的领带，也可指人际关系、文化等方面的联系"}]},{"word":"fetch","phonetic":"/fetʃ/","meanings":[{"pos":"verb","meaning":"去取，去拿来","usage":"强调“去某地取某物再返回”的往返动作，区别于bring（拿来）和take（拿走）"}]},{"word":"missing","phonetic":"/ˈmɪsɪŋ/","meanings":[{"pos":"adjective","meaning":"丢失的，失踪的","usage":"可作表语（sth is missing）或定语（missing person），表示物品找不到或人失踪"}]},{"word":"obvious","phonetic":"/ˈɒbviəs/","meanings":[{"pos":"adjective","meaning":"明显的，显而易见的","usage":"常用结构it is obvious that...表示“很明显……”"}]},{"word":"theft","phonetic":"/θeft/","meanings":[{"pos":"noun","meaning":"盗窃，偷盗","usage":"指偷窃的行为或案件，区别于thief（小偷，窃贼）"}]},{"word":"acquire","phonetic":"/əˈkwaɪə(r)/","meanings":[{"pos":"verb","meaning":"获得，得到","usage":"强调通过努力、购买等方式获得某物，也可指习得技能、知识"}]},{"word":"accuse","phonetic":"/əˈkjuːz/","meanings":[{"pos":"verb","meaning":"指责，控告","usage":"常用搭配accuse sb of (doing) sth表示指责/控告某人做了某事"}]},{"word":"deny","phonetic":"/dɪˈnaɪ/","meanings":[{"pos":"verb","meaning":"否认，否定","usage":"后接动词时要用动名词形式，即deny doing sth表示否认做过某事"}]},{"word":"ashamed","phonetic":"/əˈʃeɪmd/","meanings":[{"pos":"adjective","meaning":"羞愧的，惭愧的","usage":"常用搭配be/feel ashamed of (doing) sth表示为（做了）某事感到羞愧"}]},{"word":"rashly","phonetic":"/ˈræʃli/","meanings":[{"pos":"adverb","meaning":"鲁莽地，轻率地","usage":"修饰动词，描述做事没有经过充分考虑、冲动的状态"}]},{"word":"apologize","phonetic":"/əˈpɒlədʒaɪz/","meanings":[{"pos":"verb","meaning":"道歉，谢罪","usage":"常用搭配apologize to sb for (doing) sth表示因（做了）某事向某人道歉"}]},{"word":"astonished","phonetic":"/əˈstɒnɪʃt/","meanings":[{"pos":"adjective","meaning":"吃惊的，惊讶的","usage":"主语通常是人，描述人因意外事件感到非常惊讶的状态"}]},{"word":"dye","phonetic":"/daɪ/","meanings":[{"pos":"verb","meaning":"给……染色","usage":"常用结构dye sth + 颜色，表示把某物染成某种颜色"}]}],"phrases":[{"phrase":"set out to do sth","usage":"表示开始着手做某件有明确目标的事情，强调行动的目的性","examples":[{"en":"Dimitri at once set out to find the thief.","zh":"迪米特里立刻出发去找小偷。"},{"en":"She set out to break the world record in the marathon.","zh":"她立志要打破马拉松的世界纪录。"}]},{"phrase":"accuse sb of doing sth","usage":"用于指责或控告某人做了错事/违法行为，正式和非正式语境都可使用","examples":[{"en":"Dimitri immediately went to Aleko's house and angrily accused him of stealing the lamb.","zh":"迪米特里立刻去了阿列科家，气冲冲地指责他偷了小羊。"},{"en":"The man was accused of driving after drinking alcohol.","zh":"这名男子被指控酒驾。"}]},{"phrase":"had better do sth","usage":"用来提出建议或警告，意为“最好做某事”，语气较强，暗含如果不做会有不好的后果","examples":[{"en":"He told him he had better return it or he would call the police.","zh":"他告诉阿列科最好把羊还回去，否则他就要报警。"},{"en":"You had better take an umbrella with you, for the weather forecast says it will rain this afternoon.","zh":"你最好带把伞，天气预报说今天下午会下雨。"}]},{"phrase":"deny doing sth","usage":"表示否认做过某件事，deny后必须接动名词形式，不能接不定式","examples":[{"en":"Aleko denied taking it and led Dimitri into his backyard.","zh":"阿列科否认拿了羊，还把迪米特里领到了他的后院。"},{"en":"The little boy denied breaking the window of the neighbor's house.","zh":"小男孩否认打碎了邻居家的窗户。"}]},{"phrase":"ashamed of doing sth","usage":"表示为自己做过的某件事感到羞愧、惭愧，主语通常是人","examples":[{"en":"Ashamed of having acted so rashly, Dimitri apologized to Aleko for having accused him.","zh":"迪米特里为自己的鲁莽行为感到不好意思，于是为自己指责了阿列科向他道歉。"},{"en":"He was ashamed of having lied to his parents when he was a child.","zh":"他为自己小时候对父母撒谎感到愧疚。"}]},{"phrase":"it is obvious that","usage":"用于引出很容易就能推断出的事实，it是形式主语，真正的主语是that引导的从句","examples":[{"en":"The rope had been cut, so it was obvious that the lamb had been stolen.","zh":"绳子是被割断的，所以很明显小羊是被偷走的。"},{"en":"It is obvious that he hasn't finished his homework by the look on his face.","zh":"从他的表情就能明显看出来他没写完作业。"}]},{"phrase":"find out","usage":"表示经过调查、询问等过程后查明、弄清某个事实，强调主动探索的过程","examples":[{"en":"After telling several of his friends about the theft, Dimitri found out that his neighbour, Aleko, had suddenly acquired a new lamb.","zh":"迪米特里把丢羊的事告诉了几个朋友之后，发现他的邻居阿列科突然多了一只新的小羊。"},{"en":"The police are trying to find out the truth of the accident.","zh":"警方正在努力查明这起事故的真相。"}]}],"grammar":[{"title":"过去完成时","definition":"表示在过去某个动作或时间点之前就已经完成的动作，即“过去的过去”","structure":"主语 + had + 动词过去分词","usage":"常和before, by, when等引导的过去时间状语连用，也可通过上下文体现动作的先后顺序","examples":[{"en":"One of Mary's prize possessions was a little white lamb which her husband had given her.","zh":"玛丽最珍贵的财产之一是丈夫送给她的一只白色小羊羔。"},{"en":"When I got to the cinema, the film had already started.","zh":"我到电影院的时候，电影已经开始了。"}]},{"title":"过去分词作原因状语","definition":"过去分词（短语）可放在句首作状语，说明主句动作发生的原因，其逻辑主语是主句的主语，二者是被动关系","structure":"过去分词（短语） + 主句","usage":"可替换为原因状语从句，若过去分词的动作发生在主句动作之前，可用having been done的形式","examples":[{"en":"Ashamed of having acted so rashly, Dimitri apologized to Aleko for having accused him.","zh":"迪米特里为自己的鲁莽行为感到不好意思，于是为自己指责了阿列科向他道歉。"},{"en":"Seriously injured in the accident, the driver was sent to the hospital immediately.","zh":"由于在事故中受了重伤，司机立刻被送去了医院。"}]},{"title":"非限制性定语从句","definition":"对先行词进行补充说明，去掉之后不影响主句的意思，和主句之间常用逗号隔开","structure":"主句 + , which/who/whose/whom + 从句","usage":"修饰物时引导词用which，修饰人时可用who/whom/whose，不能用that引导","examples":[{"en":"Its wool, which had been dyed black, had been washed clean by the rain!","zh":"它的毛之前被染成了黑色，现在都被雨水冲干净了！"},{"en":"Our new school library, which was built last year, is open to all students now.","zh":"我们去年新建的学校图书馆现在对所有学生开放。"}]}],"patterns":[{"pattern":"One of sb's prize possessions is/was + 名词 + which引导的定语从句","explanation":"","original":{"en":"One of Mary's prize possessions was a little white lamb which her husband had given her.","zh":"玛丽最珍贵的财产之一是丈夫送给她的一只白色小羊羔。"},"examples":[{"en":"One of my grandmother's prize possessions is a handmade porcelain vase which her mother gave her when she got married.","zh":"我奶奶最珍贵的物品之一是她结婚时她妈妈送给她的一只手工瓷瓶。"},{"en":"One of the athlete's prize possessions is the gold medal which he won in the 2008 Olympic Games.","zh":"这位运动员最珍贵的所有物之一是他在2008年奥运会上获得的金牌。"}]},{"pattern":"It is/was obvious that + 从句","explanation":"","original":{"en":"The rope had been cut, so it was obvious that the lamb had been stolen.","zh":"绳子是被割断的，所以很明显小羊是被偷走的。"},"examples":[{"en":"All the lights in the office are off, so it is obvious that everyone has gone home already.","zh":"办公室的灯全灭了，很明显所有人都已经回家了。"},{"en":"He is wearing a heavy coat and a scarf, so it is obvious that the weather outside is very cold.","zh":"他穿了厚外套还戴了围巾，显然外面天气很冷。"}]},{"pattern":"主语 + be + 形容词 + to find that + 从句","explanation":"","original":{"en":"When he went outside half an hour later, he was astonished to find that the little black lamb was almost white.","zh":"半小时后他出门时，惊讶地发现那只黑色小羊几乎全白了。"},"examples":[{"en":"When I opened my schoolbag this morning, I was surprised to find that my deskmate had put a box of chocolate in it.","zh":"我今天早上打开书包时，惊讶地发现我同桌在里面放了一盒巧克力。"},{"en":"After he finished the whole process of the experiment, he was happy to find that the result was exactly what he had expected.","zh":"完成实验的全部流程后，他开心地发现结果和他预期的完全一致。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“珍贵的，引以为傲的” 对应的单词是？","hint":"adjective · /praɪz/","options":["universal","ware","prize","predict"],"answer":2,"explain":"prize · /praɪz/ · adjective · 珍贵的，引以为傲的。用于修饰名词，描述某物是主人非常珍视的","source":{"kind":"vocab","word":"prize"},"id":"b3-u16-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：道歉，谢罪","hint":"/əˈpɒlədʒaɪz/ · verb","answer":"apologize","placeholder":"输入英文单词","explain":"apologize · /əˈpɒlədʒaɪz/ · verb · 道歉，谢罪。常用搭配apologize to sb for (doing) sth表示因（做了）某事向某人道歉","source":{"kind":"vocab","word":"apologize"},"id":"b3-u16-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The police are trying to _____ the truth of the accident.","hint":"警方正在努力查明这起事故的真相。","answer":"find out","placeholder":"输入缺失的短语","explain":"find out：表示经过调查、询问等过程后查明、弄清某个事实，强调主动探索的过程（警方正在努力查明这起事故的真相。）","source":{"kind":"phrase","phrase":"find out"},"id":"b3-u16-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：He told him he had _____ return it or he would call the police.","hint":"他告诉阿列科最好把羊还回来，否则他就报警。","answer":"better","placeholder":"输入缺失的单词","explain":"He told him he had better return it or he would call the police. — 他告诉阿列科最好把羊还回来，否则他就报警。","source":{"kind":"sentence","en":"He told him he had better return it or he would call the police."},"id":"b3-u16-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“对先行词进行补充说明，去掉之后不影响主句的意思，和主句之间常用逗号隔开” 描述的是哪个语法点？","hint":"主句 + , which/who/whose/whom + 从句","options":["定语从句 (Relative Clause) - 关系副词where引导","现在完成时的一般疑问句","现在分词作伴随/结果状语","非限制性定语从句"],"answer":3,"explain":"非限制性定语从句：主句 + , which/who/whose/whom + 从句：修饰物时引导词用which，修饰人时可用who/whom/whose，不能用that引导","source":{"kind":"grammar","title":"非限制性定语从句"},"id":"b3-u16-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nDimitri found out that his neighbour, Aleko, had suddenly acquired a new lamb.","hint":"","options":["直到去世，理查德·科尔森都是我们镇上最著名的人物之一。","流浪汉可能会向你要钱，但他绝不会让你可怜他。","但他衣衫褴褛，店员拒绝为他服务。","迪米特里发现他的邻居阿列科突然多了一只新羊。"],"answer":3,"explain":"Dimitri found out that his neighbour, Aleko, had suddenly acquired a new lamb. — 迪米特里发现他的邻居阿列科突然多了一只新羊。","source":{"kind":"sentence","en":"Dimitri found out that his neighbour, Aleko, had suddenly acquired a new lamb."},"id":"b3-u16-q06"}]},{"id":"b3-u17","book":3,"unit":17,"key":"17","lessonFrom":17,"lessonTo":17,"title":"The Longest Suspension Bridge in the World","titleZh":"世界上最长的吊桥","question":"How is the bridge supported?","sentences":[{"en":"Verrazano, an Italian about whom little is known, sailed into New York Harbour in 1524 and named it Angouleme.","zh":"韦拉扎诺，一位鲜为人知的意大利人，于1524年航行进入纽约港，并将其命名为昂古莱姆。","t":16.67},{"en":"He described it as 'a very agreeable situation located within two small hills in the midst of which flowed a great river.'","zh":"他将其描述为“一个非常宜人的地方，坐落在两座小山之间，中间流淌着一条大河。”","t":28.43},{"en":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal,","zh":"尽管韦拉扎诺绝不被认为是一位伟大的探险家，但他的名字可能会流芳百世，","t":39.43},{"en":"for on November 21st, 1964, the longest suspension bridge in the world was named after him.","zh":"因为在1964年11月21日，世界上最长的吊桥以他的名字命名。","t":48.07},{"en":"The Verrazano Bridge, which was designed by Othmar Ammann, joins Brooklyn to Staten Island.","zh":"韦拉扎诺大桥由奥斯马·阿曼设计，连接着布鲁克林和史泰登岛。","t":59.32},{"en":"It has a span of 4,260 feet.","zh":"它有一个4260英尺的跨度。","t":67.72},{"en":"The bridge is so long that the shape of the earth had to be taken into account by its designer.","zh":"这座桥非常长，以至于它的设计师不得不将地球的形状考虑在内。","t":72.52},{"en":"Two great towers support four huge cables.","zh":"两座巨大的塔架支撑着四根巨大的缆索。","t":79.92},{"en":"The towers are built on immense underwater platforms made of steel and concrete.","zh":"这些塔架建在由钢和混凝土制成的巨大水下平台上。","t":85.53},{"en":"The platforms extend to a depth of over 100 feet under the sea.","zh":"这些平台延伸到海面以下100多英尺的深度。","t":92.28},{"en":"These alone took sixteen months to build.","zh":"仅仅这些就花了16个月来建造。","t":97.65},{"en":"Above the surface of the water, the towers rise to a height of nearly 700 feet.","zh":"在水面之上，塔架上升到近700英尺的高度。","t":101.48},{"en":"They support the cables from which the bridge has been suspended.","zh":"它们支撑着悬挂大桥的缆索。","t":108.25},{"en":"Each of the four cables contains 26,108 lengths of wire.","zh":"四根缆索中的每一根都含有26108股钢丝。","t":112.62},{"en":"It has been estimated that if the bridge were packed with cars, it would still only be carrying a third of its total capacity.","zh":"据估计，即使桥上挤满了汽车，它也只承载了其总容量的三分之一。","t":119.62},{"en":"However, size and strength are not the only important things about this bridge.","zh":"然而，尺寸和强度并不是这座桥唯一重要的方面。","t":129.73},{"en":"Despite its immensity, it is both simple and elegant,","zh":"尽管它如此巨大，却既简洁又优雅，","t":135.93},{"en":"fulfilling its designer's dream to create 'an enormous object drawn as faintly as possible'.","zh":"实现了设计师创造“一个尽可能轻描淡写地勾勒出的巨大物体”的梦想。","t":141.49}],"vocab":[{"word":"suspension","phonetic":"/səˈspenʃn/","meanings":[{"pos":"noun","meaning":"悬，吊；悬架","usage":"常用搭配suspension bridge表示悬索桥，也可指暂停、中止"}]},{"word":"agreeable","phonetic":"/əˈɡriːəbl/","meanings":[{"pos":"adjective","meaning":"宜人的；令人愉快的","usage":"可修饰地点、天气、氛围等，也可表示“欣然同意的”"}]},{"word":"locate","phonetic":"/ləʊˈkeɪt/","meanings":[{"pos":"verb","meaning":"位于；坐落于；查找位置","usage":"常用被动语态be located in/on/at表示地点位置"}]},{"word":"immortal","phonetic":"/ɪˈmɔːtl/","meanings":[{"pos":"adjective","meaning":"不朽的；流芳百世的","usage":"可形容人、名声、作品等长久被铭记，反义词为mortal"}]},{"word":"span","phonetic":"/spæn/","meanings":[{"pos":"noun","meaning":"跨度；跨距；持续时间","usage":"可表示桥梁的跨度，也可指attention span（注意力持续时间）等"},{"pos":"verb","meaning":"跨越；持续","usage":"后面可接时间或地点范围"}]},{"word":"support","phonetic":"/səˈpɔːt/","meanings":[{"pos":"verb","meaning":"支撑；支持；养活","usage":"可指物理上的承重，也可指情感、观点上的支持"},{"pos":"noun","meaning":"支持；支撑物","usage":"常用搭配in support of表示“支持”"}]},{"word":"immense","phonetic":"/ɪˈmens/","meanings":[{"pos":"adjective","meaning":"巨大的；极大的","usage":"强调尺寸、规模、程度非常大，比large程度更强"}]},{"word":"platform","phonetic":"/ˈplætfɔːm/","meanings":[{"pos":"noun","meaning":"平台；站台；讲台","usage":"可指建筑结构的平台，也可指公共交通的站台、线上平台等"}]},{"word":"concrete","phonetic":"/ˈkɒŋkriːt/","meanings":[{"pos":"noun","meaning":"混凝土","usage":"不可数名词，指建筑材料"},{"pos":"adjective","meaning":"具体的；实在的","usage":"与abstract（抽象的）相对"}]},{"word":"extend","phonetic":"/ɪkˈstend/","meanings":[{"pos":"verb","meaning":"延伸；扩大；延长","usage":"可指空间上的延伸，也可指时间、范围的扩大"}]},{"word":"estimate","phonetic":"/ˈestɪmeɪt/","meanings":[{"pos":"verb","meaning":"估计；估算","usage":"常用结构It is estimated that...表示“据估计”"},{"pos":"noun","meaning":"估计；估算","usage":"常用搭配at a rough estimate表示“据粗略估计”"}]},{"word":"capacity","phonetic":"/kəˈpæsəti/","meanings":[{"pos":"noun","meaning":"容量；承载量；能力","usage":"可指容器、建筑的容纳量，也可指人的能力"}]},{"word":"immensity","phonetic":"/ɪˈmensəti/","meanings":[{"pos":"noun","meaning":"巨大；庞大","usage":"是immense的名词形式，强调规模的宏大"}]},{"word":"elegant","phonetic":"/ˈelɪɡənt/","meanings":[{"pos":"adjective","meaning":"优雅的；雅致的；精巧的","usage":"可形容人的举止、物品的设计、建筑的风格等"}]},{"word":"fulfill","phonetic":"/fʊlˈfɪl/","meanings":[{"pos":"verb","meaning":"实现；履行；满足","usage":"常用搭配fulfill a dream/goal/duty表示实现梦想/达成目标/履行职责"}]}],"phrases":[{"phrase":"by no means","usage":"表示否定含义，意为“绝不，一点也不”，属于副词短语，可放在句首（需倒装）、句中或句末","examples":[{"en":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal.","zh":"虽然韦拉扎诺绝对算不上一个伟大的探险家，但他的名字很可能会流芳百世。"},{"en":"This is by no means the end of the project, we still have a lot of work to do.","zh":"这绝不是项目的终点，我们还有很多工作要做。"}]},{"phrase":"name after","usage":"动词短语，意为“以……命名”，常用被动结构be named after sb","examples":[{"en":"The longest suspension bridge in the world was named after him.","zh":"世界上最长的悬索桥是以他的名字命名的。"},{"en":"The street is named after the famous scientist who made great contributions to the city.","zh":"这条街是以那位为这座城市做出巨大贡献的著名科学家的名字命名的。"}]},{"phrase":"take into account","usage":"动词短语，意为“考虑到，把……考虑在内”，相当于take into consideration，宾语可放在短语中间或account后面","examples":[{"en":"The bridge is so long that the shape of the earth had to be taken into account by its designer.","zh":"这座桥太长了，以至于设计者必须把地球的形状考虑在内。"},{"en":"When planning the trip, we need to take the weather into account.","zh":"计划旅行的时候，我们需要把天气因素考虑在内。"}]},{"phrase":"be packed with","usage":"形容词短语，意为“挤满，塞满”，强调人或物的密度非常大","examples":[{"en":"It has been estimated that if the bridge were packed with cars, it would still only be carrying a third of its total capacity.","zh":"据估计，即使桥上挤满了汽车，它的载重量也仍然只有总承载量的三分之一。"},{"en":"During the Spring Festival, the train station is always packed with passengers going home.","zh":"春节期间，火车站总是挤满了回家的旅客。"}]},{"phrase":"in the midst of","usage":"介词短语，意为“在……之中，在……中间”，可指地理位置的中间，也可指处于某种事件的过程中","examples":[{"en":"He described it as 'a very agreeable situation located within two small hills in the midst of which flowed a great river.'","zh":"他把它描述为“一个非常宜人的地方，坐落在两座小山之间，中间流淌着一条大河。”"},{"en":"The country is in the midst of an economic recovery.","zh":"这个国家正处于经济复苏的过程中。"}]}],"grammar":[{"title":"介词+关系代词引导的定语从句","definition":"当定语从句的谓语动词和先行词之间需要加介词构成搭配时，常将介词提前到关系代词which（指物）或whom（指人）之前，构成“介词+which/whom”的结构引导定语从句","structure":"先行词 + 介词 + which/whom + 定语从句","usage":"介词的选择通常根据先行词的搭配、从句谓语的固定搭配或者句子的语义决定，这种结构多用于正式文体中","examples":[{"en":"Verrazano, an Italian about whom little is known, sailed into New York Harbour in 1524.","zh":"1524年，一位鲜为人知的意大利人韦拉扎诺驶入了纽约港。"},{"en":"They support the cables from which the bridge has been suspended.","zh":"它们支撑着悬吊桥梁的缆索。"},{"en":"The book for which you are looking is on the shelf.","zh":"你正在找的那本书在架子上。"}]},{"title":"与现在事实相反的虚拟条件句","definition":"用来描述与现在实际情况不相符的假设，从句描述假设的条件，主句描述该条件下会产生的结果","structure":"If + 主语 + 动词过去式（be动词一律用were）, 主语 + would/could/might + 动词原形","usage":"用于表达不可能发生或者发生概率极低的假设，突出假设的非真实性","examples":[{"en":"It has been estimated that if the bridge were packed with cars, it would still only be carrying a third of its total capacity.","zh":"据估计，即使桥上挤满了汽车，它的载重量也仍然只有总承载量的三分之一。"},{"en":"If I were you, I would choose to study abroad after graduation.","zh":"如果我是你，我会选择毕业后出国留学。"}]}],"patterns":[{"pattern":"Though sb/sth is by no means considered to be..., sb/sth will..., for...","explanation":"","original":{"en":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal, for on November 21st, 1964, the longest suspension bridge in the world was named after him.","zh":"虽然韦拉扎诺绝对算不上一个伟大的探险家，但他的名字很可能会流芳百世，因为1964年11月21日，世界上最长的悬索桥是以他的名字命名的。"},"examples":[{"en":"Though this small town is by no means considered to be a famous tourist attraction, it will attract more visitors in the future, for its special local customs are gradually known by people.","zh":"虽然这个小镇绝对算不上著名的旅游景点，但它未来会吸引更多游客，因为它独特的当地习俗正逐渐被人们所知。"},{"en":"Though the young writer is by no means considered to be a master of literature, his works will be remembered by many readers, for his stories always touch people's hearts.","zh":"虽然这位年轻作家绝对算不上文学大师，但他的作品会被很多读者记住，因为他的故事总能触动人心。"}]},{"pattern":"sth is so + adj + that...","explanation":"","original":{"en":"The bridge is so long that the shape of the earth had to be taken into account by its designer.","zh":"这座桥太长了，以至于设计者必须把地球的形状考虑在内。"},"examples":[{"en":"The problem is so complicated that we need to spend more time discussing it.","zh":"这个问题太复杂了，以至于我们需要花更多时间来讨论。"},{"en":"The lecture is so interesting that all the students listen to it carefully.","zh":"这个讲座太有趣了，以至于所有学生都在认真听讲。"}]},{"pattern":"Despite its + n, it is both + adj + and + adj, doing sth","explanation":"","original":{"en":"Despite its immensity, it is both simple and elegant, fulfilling its designer's dream to creat 'an enormous object drawn as faintly as possible'.","zh":"尽管它规模宏大，但它既简洁又优雅，实现了设计师“用尽可能淡的线条勾勒出庞然大物”的梦想。"},"examples":[{"en":"Despite its high price, this phone is both functional and portable, meeting most users' needs for work and entertainment.","zh":"尽管它价格很高，这款手机既实用又便携，满足了大多数用户工作和娱乐的需求。"},{"en":"Despite its small size, this device is both efficient and easy to operate, helping people complete daily tasks quickly.","zh":"尽管它体积很小，这个设备既高效又易操作，帮助人们快速完成日常任务。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“位于；坐落于；查找位置” 对应的单词是？","hint":"verb · /ləʊˈkeɪt/","options":["embarrassed","locate","coral","zigzag"],"answer":1,"explain":"locate · /ləʊˈkeɪt/ · verb · 位于；坐落于；查找位置。常用被动语态be located in/on/at表示地点位置","source":{"kind":"vocab","word":"locate"},"id":"b3-u17-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：悬，吊；悬架","hint":"/səˈspenʃn/ · noun","answer":"suspension","placeholder":"输入英文单词","explain":"suspension · /səˈspenʃn/ · noun · 悬，吊；悬架。常用搭配suspension bridge表示悬索桥，也可指暂停、中止","source":{"kind":"vocab","word":"suspension"},"id":"b3-u17-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：This is _____ the end of the project, we still have a lot of work to do.","hint":"这绝不是项目的终点，我们还有很多工作要做。","answer":"by no means","placeholder":"输入缺失的短语","explain":"by no means：表示否定含义，意为“绝不，一点也不”，属于副词短语，可放在句首（需倒装）、句中或句末（这绝不是项目的终点，我们还有很多工作要做。）","source":{"kind":"phrase","phrase":"by no means"},"id":"b3-u17-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Though _____ is by no means considered to be a great explorer, his name will probably remain immortal,","hint":"尽管韦拉扎诺绝不被认为是一位伟大的探险家，但他的名字可能会流芳百世，","answer":"Verrazano","placeholder":"输入缺失的单词","explain":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal, — 尽管韦拉扎诺绝不被认为是一位伟大的探险家，但他的名字可能会流芳百世，","source":{"kind":"sentence","en":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal,"},"id":"b3-u17-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来描述与现在实际情况不相符的假设，从句描述假设的条件，主句描述该条件下会产生的结果” 描述的是哪个语法点？","hint":"If + 主语 + 动词过去式（be动词一律用were）, 主语 + would/could/might + 动词原形","options":["such...that... 结果状语从句","与现在事实相反的虚拟条件句","定冠词the的特指用法 (Definite Article 'the' for Specific Reference)","百分数表达在描述数据中的应用"],"answer":1,"explain":"与现在事实相反的虚拟条件句：If + 主语 + 动词过去式（be动词一律用were）, 主语 + would/could/might + 动词原形：用于表达不可能发生或者发生概率极低的假设，突出假设的非真实性","source":{"kind":"grammar","title":"与现在事实相反的虚拟条件句"},"id":"b3-u17-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nfor on November 21st, 1964, the longest suspension bridge in the world was named after him.","hint":"","options":["杀虫剂和化肥的使用生产廉价谷物和蔬菜。","因为在1964年11月21日，世界上最长的吊桥以他的名字命名。","我告诉她，要么我买一台新割草机，要么就让草长着。","但它们的许多功能已被小型、强大的个人电脑（通常称为PC）所取代。"],"answer":1,"explain":"for on November 21st, 1964, the longest suspension bridge in the world was named after him. — 因为在1964年11月21日，世界上最长的吊桥以他的名字命名。","source":{"kind":"sentence","en":"for on November 21st, 1964, the longest suspension bridge in the world was named after him."},"id":"b3-u17-q06"}]},{"id":"b3-u18","book":3,"unit":18,"key":"18","lessonFrom":18,"lessonTo":18,"title":"Electric Currents in Modern Art","titleZh":"现代艺术中的电流","question":"How might some of the exhibits have been dangerous?","sentences":[{"en":"Modern sculpture rarely surprises us any more.","zh":"现代雕塑已很少令我们感到惊奇了。","t":15.62},{"en":"The idea that modern art can only be seen in museums is mistaken.","zh":"现代艺术只能在博物馆里才能看到这种想法是错误的。","t":19.58},{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture on display in public places.","zh":"即使是对艺术不感兴趣的人，也不会没有注意到在公共场所展出的现代雕塑作品。","t":25.6},{"en":"Strange forms stand in gardens, and outside buildings and shops.","zh":"花园里、大楼和商店门外都矗立着奇形怪状的雕塑。","t":35.42},{"en":"We have got quite used to them.","zh":"我们对它们已习以为常了。","t":40.66},{"en":"Some so-called 'modern' pieces have been on display for nearly eighty years.","zh":"有些所谓的“现代”作品已经展出了将近80年了。","t":43.55},{"en":"In spite of this, some people--including myself--were surprised by a recent exhibition of modern sculpture.","zh":"尽管如此，最近举办的一次现代雕塑展览还是使一些人——包括我本人在内——大吃一惊。","t":49.9},{"en":"The first thing I saw when I entered the art gallery was a notice which said: 'Do not touch the exhibits, some of them are dangerous!'","zh":"我走进美术馆时，首先看到的是一块牌子，上面写着：“展品切勿触摸，有些是危险品！”","t":58.69},{"en":"The objects on display were pieces of moving sculpture.","zh":"展出的作品都是动态雕塑。","t":69.44},{"en":"Oddly shaped forms that are suspended from the ceiling and move in response to a gust of wind are quite familiar to everybody.","zh":"悬挂在天花板上随风摆动的奇形怪状的雕塑，大家是相当熟悉的。","t":74.16},{"en":"These objects, however, were different.","zh":"然而，这些展品却与众不同。","t":84},{"en":"Lined up against the wall, there were long thin wires attached to metal spheres.","zh":"靠墙摆放着的是些系有金属球的长长的细电线。","t":87.91},{"en":"The spheres had been magnetized and attracted or repelled each other all the time.","zh":"金属球都带磁，因此它们总是互相吸引或排斥。","t":94.17},{"en":"In the centre of the hall,","zh":"在展览厅中央，","t":101.01},{"en":"there were a number of tall structures which contained coloured lights.","zh":"有些高高的建筑物模型，里面装着彩灯。","t":102.89},{"en":"These lights flickered continuously like traffic lights which have gone mad.","zh":"这些彩灯不停地闪烁，就像发了疯的红绿灯。","t":107.68},{"en":"Sparks were emitted from small black boxes and red lamps flashed on and off angrily.","zh":"小黑盒子里迸出火花，红色灯泡恼怒地闪着。","t":113.94},{"en":"It was rather like an exhibition of prehistoric electronic equipment.","zh":"这简直是史前电子设备展览。","t":121.2},{"en":"These peculiar forms not only seemed designed to shock people emotionally, but to give them electric shocks as well!","zh":"这些奇特的造型，似乎不仅要给人以情感上的冲击，还要给人以电击！","t":126.94}],"vocab":[{"word":"sculpture","phonetic":"/ˈskʌlptʃə/","meanings":[{"pos":"noun","meaning":"雕塑品，雕像","usage":"指用石头、木头、金属等材料雕刻或塑造的艺术品"}]},{"word":"exhibit","phonetic":"/ɪɡˈzɪbɪt/","meanings":[{"pos":"noun","meaning":"展览品，陈列品","usage":"指在展览中展示的物品"},{"pos":"verb","meaning":"展出，展示","usage":"指公开展示某物"}]},{"word":"magnetize","phonetic":"/ˈmæɡnɪtaɪz/","meanings":[{"pos":"verb","meaning":"使磁化，使生磁性","usage":"指使物体具有磁性或被磁铁吸引"}]},{"word":"attract","phonetic":"/əˈtrækt/","meanings":[{"pos":"verb","meaning":"吸引","usage":"指将某物拉向自己，与repel（排斥）相对"}]},{"word":"repel","phonetic":"/rɪˈpel/","meanings":[{"pos":"verb","meaning":"排斥，击退","usage":"指推开或抵抗某物，与attract相对"}]},{"word":"flicker","phonetic":"/ˈflɪkə/","meanings":[{"pos":"verb","meaning":"闪烁，闪动","usage":"指灯光或火焰不稳定地闪烁"}]},{"word":"spark","phonetic":"/spɑːk/","meanings":[{"pos":"noun","meaning":"火花，火星","usage":"指电火花或小的火焰"},{"pos":"verb","meaning":"发出火花","usage":"指产生小火花"}]},{"word":"prehistoric","phonetic":"/ˌpriːhɪˈstɒrɪk/","meanings":[{"pos":"adjective","meaning":"史前的，原始时代的","usage":"指人类历史记录之前的时期或非常古老的东西"}]},{"word":"suspend","phonetic":"/səˈspend/","meanings":[{"pos":"verb","meaning":"悬挂，吊","usage":"指从上方挂起，通常用绳索或链条"}]},{"word":"gust","phonetic":"/ɡʌst/","meanings":[{"pos":"noun","meaning":"一阵风，阵风","usage":"指突然而强烈的短时风"}]},{"word":"peculiar","phonetic":"/pɪˈkjuːliə/","meanings":[{"pos":"adjective","meaning":"奇怪的，独特的","usage":"指与众不同的、奇怪的或特有的"}]},{"word":"gallery","phonetic":"/ˈɡæləri/","meanings":[{"pos":"noun","meaning":"美术馆，画廊","usage":"指展示艺术品的场所"}]},{"word":"electronic","phonetic":"/ˌelekˈtrɒnɪk/","meanings":[{"pos":"adjective","meaning":"电子的，电子设备的","usage":"指与电子或电子设备相关的"}]},{"word":"electric shock","phonetic":"/ɪˈlektrɪk ʃɒk/","meanings":[{"pos":"noun","meaning":"电击，触电","usage":"指电流通过身体时造成的感觉或伤害"}]},{"word":"mistaken","phonetic":"/mɪˈsteɪkən/","meanings":[{"pos":"adjective","meaning":"错误的，弄错的","usage":"指基于错误判断的或不正确的"}]}],"phrases":[{"phrase":"take no interest in","usage":"表示对某事物不感兴趣，毫不关心","examples":[{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture.","zh":"即使对艺术不感兴趣的人也不可能没注意到公共场所的现代雕塑。"}]},{"phrase":"in response to","usage":"作为对...的反应，响应","examples":[{"en":"The objects move in response to a gust of wind.","zh":"这些物体会随风而动。"}]},{"phrase":"get used to","usage":"习惯于某事","examples":[{"en":"We have got quite used to them.","zh":"我们已经相当习惯它们了。"}]},{"phrase":"on display","usage":"展出中，正在展示","examples":[{"en":"Some so-called 'modern' pieces have been on display for nearly eighty years.","zh":"一些所谓的'现代'作品已经展出将近八十年了。"}]},{"phrase":"line up","usage":"排队，排列成行","examples":[{"en":"Lined up against the wall, there were long thin wires attached to metal spheres.","zh":"靠墙排列着系着金属球的细长电线。"}]},{"phrase":"a number of","usage":"一些，若干","examples":[{"en":"In the centre of the hall, there were a number of tall structures.","zh":"大厅中央有一些高高的结构物。"}]},{"phrase":"rather like","usage":"相当像，有点像","examples":[{"en":"It was rather like an exhibition of prehistoric electronic equipment.","zh":"它非常像一场史前电子设备的展览。"}]},{"phrase":"in spite of","usage":"尽管，虽然","examples":[{"en":"In spite of this, some people were surprised by a recent exhibition.","zh":"尽管如此，一些人仍然对最近的展览感到惊讶。"}]},{"phrase":"be designed to","usage":"目的是，旨在","examples":[{"en":"These peculiar forms not only seemed designed to shock people emotionally.","zh":"这些奇特的形状似乎不仅是为了在情感上震撼人们。"}]},{"phrase":"cannot have failed to notice","usage":"不可能没注意到，表示一定会注意到","examples":[{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture.","zh":"即使对艺术不感兴趣的人也一定会注意到现代雕塑。"}]}],"grammar":[{"title":"现在完成时 (Present Perfect Tense)","definition":"表示过去发生的动作或状态持续到现在，或对现在有影响。常与already, yet, just, ever, never, for, since等时间状语连用。","structure":"主语 + have/has + 过去分词","usage":"用于描述从过去开始持续到现在的情况，或强调过去的经验对现在的影响。","examples":[{"en":"We have got quite used to them.","zh":"我们已经相当习惯它们了。"},{"en":"Some so-called 'modern' pieces have been on display for nearly eighty years.","zh":"一些所谓的'现代'作品已经展出将近八十年了。"},{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture.","zh":"即使对艺术不感兴趣的人也一定会注意到现代雕塑。"}]},{"title":"被动语态 (Passive Voice)","definition":"当句子的主语是动作的承受者时使用被动语态。强调动作的接受者或当动作执行者不重要时使用。","structure":"主语 + be + 过去分词 (+ by + 动作执行者)","usage":"用于强调动作的承受者，或当动作执行者未知、不重要时。","examples":[{"en":"The spheres had been magnetized and attracted or repelled each other.","zh":"这些球已被磁化，彼此相互吸引或排斥。"},{"en":"Some so-called 'modern' pieces have been on display for nearly eighty years.","zh":"一些所谓的'现代'作品已经被展出将近八十年了。"},{"en":"Sparks were emitted from small black boxes.","zh":"火花从小黑盒子里发射出来。"}]},{"title":"情态动词 + have + 过去分词 (Modal + Perfect Infinitive)","definition":"表示对过去发生的事情的推测、评论或可能性。must have done表示肯定推测，can't have done表示否定推测。","structure":"情态动词 + have + 过去分词","usage":"用于表达对过去事件的推测或判断。","examples":[{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture.","zh":"即使对艺术不感兴趣的人，也不可能没注意到现代雕塑的例子。"}]}],"patterns":[{"pattern":"The idea that... is mistaken","explanation":"","original":{"en":"The idea that modern art can only be seen in museums is mistaken.","zh":"认为现代艺术只能在博物馆里看到的观点是错误的。"},"examples":[{"en":"The idea that money can buy happiness is mistaken.","zh":"认为金钱能买来幸福的观点是错误的。"},{"en":"The idea that practice makes perfect is mistaken.","zh":"认为熟能生巧的观点并非总是正确的。"}]},{"pattern":"Some + 名词 + have been + 过去分词 + for + 时间段","explanation":"","original":{"en":"Some so-called 'modern' pieces have been on display for nearly eighty years.","zh":"一些所谓的'现代'作品已经展出将近八十年了。"},"examples":[{"en":"These paintings have been in the collection for over a century.","zh":"这些画作已经被收藏了一个多世纪。"},{"en":"The museum has been open to the public for fifty years.","zh":"这家博物馆已经向公众开放五十年了。"}]},{"pattern":"These + 名词 + were designed to + 动词原形","explanation":"","original":{"en":"These peculiar forms not only seemed designed to shock people emotionally, but to give them electric shocks as well!","zh":"这些奇特的形状似乎不仅是为了在情感上震撼人们，而且也是为了给他们电击！"},"examples":[{"en":"These exercises are designed to improve your speaking skills.","zh":"这些练习旨在提高你的口语能力。"},{"en":"The warning signs were designed to protect visitors from danger.","zh":"这些警告标志是为了保护游客免受危险。"}]},{"pattern":"Even + 主语 + cannot have failed to + 动词原形","explanation":"","original":{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture on display in public places.","zh":"即使对艺术不感兴趣的人，也不可能没注意到公共场所展出的现代雕塑。"},"examples":[{"en":"Even students who hate history cannot have failed to notice this famous painting.","zh":"即使讨厌历史的学生也不可能没注意到这幅名画。"},{"en":"Even tourists who speak no Chinese cannot have failed to see the Great Wall.","zh":"即使不会说中文的游客也一定能看到长城。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“排斥，击退” 对应的单词是？","hint":"verb · /rɪˈpel/","options":["declare","prosperous","repel","enlightened"],"answer":2,"explain":"repel · /rɪˈpel/ · verb · 排斥，击退。指推开或抵抗某物，与attract相对","source":{"kind":"vocab","word":"repel"},"id":"b3-u18-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：错误的，弄错的","hint":"/mɪˈsteɪkən/ · adjective","answer":"mistaken","placeholder":"输入英文单词","explain":"mistaken · /mɪˈsteɪkən/ · adjective · 错误的，弄错的。指基于错误判断的或不正确的","source":{"kind":"vocab","word":"mistaken"},"id":"b3-u18-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Even people who _____ art cannot have failed to notice examples of modern sculpture.","hint":"即使对艺术不感兴趣的人也不可能没注意到公共场所的现代雕塑。","answer":"take no interest in","placeholder":"输入缺失的短语","explain":"take no interest in：表示对某事物不感兴趣，毫不关心（即使对艺术不感兴趣的人也不可能没注意到公共场所的现代雕塑。）","source":{"kind":"phrase","phrase":"take no interest in"},"id":"b3-u18-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Strange forms stand in gardens, and outside buildings and _____","hint":"花园里、大楼和商店门外都矗立着奇形怪状的雕塑。","answer":"shops","placeholder":"输入缺失的单词","explain":"Strange forms stand in gardens, and outside buildings and shops. — 花园里、大楼和商店门外都矗立着奇形怪状的雕塑。","source":{"kind":"sentence","en":"Strange forms stand in gardens, and outside buildings and shops."},"id":"b3-u18-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示过去发生的动作或状态持续到现在，或对现在有影响。常与already, yet, just, ever, never, for, since等时间状语连用。” 描述的是哪个语法点？","hint":"主语 + have/has + 过去分词","options":["现在完成时 (Present Perfect Tense)","so...that...引导的倒装句","Past Simple 与 Past Perfect 的时序区分","虚拟语气 (Subjunctive Mood) - 与过去事实相反"],"answer":0,"explain":"现在完成时 (Present Perfect Tense)：主语 + have/has + 过去分词：用于描述从过去开始持续到现在的情况，或强调过去的经验对现在的影响。","source":{"kind":"grammar","title":"现在完成时 (Present Perfect Tense)"},"id":"b3-u18-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nWe have got quite used to them.","hint":"","options":["我们对它们已习以为常了。","它是由一名大学生烘烤的，他使用了超过1000磅面粉、800磅糖、","它为闲暇时间提供了放松，因为仅仅看着自己的珍藏就是一种乐趣。","巴格里特驳斥了电脑会学会“独立思考”并“统治世界”的观点，这在当时是人们喜欢相信的。"],"answer":0,"explain":"We have got quite used to them. — 我们对它们已习以为常了。","source":{"kind":"sentence","en":"We have got quite used to them."},"id":"b3-u18-q06"}]},{"id":"b3-u19","book":3,"unit":19,"key":"19","lessonFrom":19,"lessonTo":19,"title":"A Very Dear Cat","titleZh":"一只非常名贵的猫","question":"Why was Rastus 'very dear' in more ways than one?","sentences":[{"en":"Kidnappers are rarely interested in animals, but they recently took considerable interest in Mrs. Eleanor Ramsay's cat.","zh":"绑架者极少对动物感兴趣，但他们最近却对埃莉诺·拉姆齐夫人的猫产生了极大兴趣。","t":16.88},{"en":"Mrs. Eleanor Ramsay, a very wealthy old lady, has shared a flat with her cat, Rastus, for a great many years.","zh":"埃莉诺·拉姆齐夫人，一位非常富有的老太太，与她的猫拉斯特斯共同住在一个公寓里已经很多年了。","t":26.36},{"en":"Rastus leads an orderly life.","zh":"拉斯特斯过着有规律的生活。","t":36.36},{"en":"He usually takes a short walk in the evenings and is always home by seven o'clock.","zh":"它通常在傍晚散步一小会儿，总是在7点钟前到家。","t":38.82},{"en":"One evening, however, he failed to arrive.","zh":"然而，一天晚上，它没有回来。","t":45.58},{"en":"Mrs. Ramsay got very worried.","zh":"拉姆齐夫人非常焦急。","t":49.8},{"en":"She looked everywhere for him but could not find him.","zh":"她到处寻找，但没有找到它。","t":52.41},{"en":"Three days after Rastus' disappearance, Mrs. Ramsay received an anonymous letter.","zh":"拉斯特斯失踪3天后，拉姆齐夫人收到一封匿名信。","t":57.2},{"en":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000.","zh":"写信人称拉斯特斯很安全，如果拉姆齐夫人支付1000英镑赎金，它将立即被送回。","t":64.34},{"en":"Mrs.Ramsay was instructed to place the money in a cardboard box and to leave it outside her door.","zh":"拉姆齐夫人被指示将钱放进一个纸箱，并将其放在门外。","t":75.73},{"en":"At first, she decided to go to the police,","zh":"最初，她决定报警，","t":82.62},{"en":"but fearing that she would never see Rastus again--the letter had made that quite clear--she changed her mind.","zh":"但由于担心再也见不到拉斯特斯——信中已把这一点说得一清二楚——她改变了主意。","t":86.66},{"en":"She withdrew ￡1000 from her bank and followed the kidnapper's instructions.","zh":"她从银行取出1000英镑，按照绑架者的指示做了。","t":96.31},{"en":"The next morning, the box had disappeared but Mrs.Ramsay was sure that the kidnapper would keep his word.","zh":"第二天早上，箱子不见了，但拉姆齐夫人确信绑架者会遵守诺言。","t":101.97},{"en":"Sure enough, Rastus arrived punctually at seven o'clock that evening.","zh":"果不其然，拉斯特斯那天晚上7点准时回来了。","t":110.27},{"en":"He looked very well, though he was rather thirsty, for he drank half a bottle of milk.","zh":"它看上去很好，只是有点渴，喝了半瓶牛奶。","t":116.58},{"en":"The police were astounded when Mrs. Ramsay told them what she had done.","zh":"当拉姆齐夫人告诉警察她所做的一切时，警察都惊呆了。","t":124.04},{"en":"She explained that Rastus was very dear to her.","zh":"她解释说拉斯特斯对她来说非常宝贵。","t":129.64},{"en":"Considering the amount she paid, he was dear in more ways than one!","zh":"考虑到她所支付的金额，它在多方面都确实很“名贵”！","t":133.38}],"vocab":[{"word":"kidnapper","phonetic":"/ˈkɪdnæpə/","meanings":[{"pos":"noun","meaning":"绑架者，绑匪","usage":"指参与绑架他人的人，通常为了索要赎金"}]},{"word":"considerable","phonetic":"/kənˈsɪdərəbl/","meanings":[{"pos":"adjective","meaning":"相当大的；相当多的","usage":"强调数量或程度之大，常用于正式语境"}]},{"word":"wealthy","phonetic":"/ˈwelθi/","meanings":[{"pos":"adjective","meaning":"富有的；富裕的","usage":"形容拥有大量财富的人，是rich的正式表达"}]},{"word":"orderly","phonetic":"/ˈɔːrdərli/","meanings":[{"pos":"adjective","meaning":"有秩序的；有规律的","usage":"形容事物有条理、有规则，也可指人守秩序"}]},{"word":"disappearance","phonetic":"/ˌdɪsəˈpɪərəns/","meanings":[{"pos":"noun","meaning":"失踪；消失","usage":"disappear的名词形式，指某人或某物不见的情况"}]},{"word":"anonymous","phonetic":"/əˈnɒnɪməs/","meanings":[{"pos":"adjective","meaning":"匿名的；不具名的","usage":"指不透露身份或姓名的，常用于信件、捐款等"}]},{"word":"ransom","phonetic":"/ˈrænsəm/","meanings":[{"pos":"noun","meaning":"赎金","usage":"绑架案中要求支付的金钱，作为释放人质的条件"}]},{"word":"instruct","phonetic":"/ɪnˈstrʌkt/","meanings":[{"pos":"verb","meaning":"指示；命令；嘱咐","usage":"正式用语，指给出明确的指示或命令"}]},{"word":"withdraw","phonetic":"/wɪðˈdrɔː/","meanings":[{"pos":"verb","meaning":"取（钱）；提取","usage":"指从银行账户中取出资金，也可用作收回承诺等"}]},{"word":"punctually","phonetic":"/ˈpʌŋktʃuəli/","meanings":[{"pos":"adverb","meaning":"准时地；按时地","usage":"准时地，强调时间的精确性，是punctual的副词形式"}]},{"word":"astound","phonetic":"/əˈstaʊnd/","meanings":[{"pos":"verb","meaning":"使震惊；使大吃一惊","usage":"语气比surprise更强，表示极度惊讶"}]},{"word":"cardboard","phonetic":"/ˈkɑːdbɔːrd/","meanings":[{"pos":"noun","meaning":"硬纸板；卡纸","usage":"指用于制作盒子等的厚纸材料"}]},{"word":"flat","phonetic":"/flæt/","meanings":[{"pos":"noun","meaning":"公寓；一套房间","usage":"英式英语，指同一层楼的公寓套房"}]},{"word":"dear","phonetic":"/dɪə/","meanings":[{"pos":"adjective","meaning":"亲爱的；昂贵的","usage":"双重含义：1.表示亲爱的、珍贵的 2.表示价格高的；本课利用这双关"}]},{"word":"share","phonetic":"/ʃeə/","meanings":[{"pos":"verb","meaning":"共用；分享；共享","usage":"指与他人共同使用或拥有某物"}]}],"phrases":[{"phrase":"take interest in","usage":"对...感兴趣；关注...","examples":[{"en":"They recently took considerable interest in Mrs. Ramsay's cat.","zh":"他们最近对拉姆齐夫人的猫非常感兴趣。"}]},{"phrase":"in safe hands","usage":"安全；处于可信赖的人手中","examples":[{"en":"The writer stated that Rastus was in safe hands.","zh":"写信人称拉斯塔斯很安全。"}]},{"phrase":"change one's mind","usage":"改变主意","examples":[{"en":"She changed her mind and decided to pay the ransom.","zh":"她改变了主意，决定支付赎金。"}]},{"phrase":"keep one's word","usage":"遵守诺言；言而有信","examples":[{"en":"Mrs. Ramsay was sure that the kidnapper would keep his word.","zh":"拉姆齐夫人确信绑匪会遵守诺言。"}]},{"phrase":"look everywhere for","usage":"到处寻找","examples":[{"en":"She looked everywhere for him but could not find him.","zh":"她到处找他，但找不到。"}]},{"phrase":"follow one's instructions","usage":"按照某人的指示行事","examples":[{"en":"She withdrew money and followed the kidnapper's instructions.","zh":"她取了钱并按照绑匪的指示行事。"}]},{"phrase":"lead an orderly life","usage":"过着有规律的生活","examples":[{"en":"Rastus leads an orderly life.","zh":"拉斯塔斯过着有规律的生活。"}]},{"phrase":"in more ways than one","usage":"不止一种方式；多方面地","examples":[{"en":"Considering the amount she paid, he was dear in more ways than one!","zh":"考虑到她付出的金额，拉斯塔斯多方面都很珍贵！"}]},{"phrase":"be dear to someone","usage":"对某人来说很珍贵/亲爱的","examples":[{"en":"Rastus was very dear to her.","zh":"拉斯塔斯对她来说非常珍贵。"}]},{"phrase":"make something clear","usage":"把...讲清楚；使...明确","examples":[{"en":"The letter had made that quite clear.","zh":"信里已经把这一点说得清清楚楚。"}]}],"grammar":[{"title":"过去进行时 (Past Continuous Tense)","definition":"表示在过去某一时刻或某一段时间正在进行的动作，常与when、while等连用","structure":"主语 + was/were + 动词-ing","usage":"用于描述过去正在发生的动作背景，或与一般过去时连用表示过去某事发生时有另一动作在进行","examples":[{"en":"One evening, however, he failed to arrive.","zh":"然而，有一天晚上，他没有按时回家。"}]},{"title":"条件状语从句 (Conditional Clause)","definition":"由if引导的条件句，表达假设的情况及其可能的结果","structure":"If + 主语 + 过去式, 主语 + would/could + 动词原形","usage":"用于谈论不太可能发生的假设情况，或与过去事实相反的虚拟语气","examples":[{"en":"She decided to go to the police, but fearing that she would never see Rastus again, she changed her mind.","zh":"她本想去报警，但又担心再也见不到拉斯塔斯了，于是改变了主意。"}]},{"title":"双关语 (Pun)","definition":"利用词语的多义性或同音异义词创造幽默效果的修辞手法","structure":"同一个词在不同语境下有不同含义","usage":"用于创造幽默效果，本课中'dear'既表示'亲爱的'又表示'昂贵的'，形成文字游戏","examples":[{"en":"Rastus was very dear to her. Considering the amount she paid, he was dear in more ways than one!","zh":"拉斯塔斯对她来说非常珍贵。考虑到她付出的金额，他多方面都很值钱！"}]}],"patterns":[{"pattern":"主语 + has shared + 名词 + with + 某人 + for + 时间段","explanation":"","original":{"en":"Mrs. Eleanor Ramsay has shared a flat with her cat for a great many years.","zh":"埃莱娜·拉姆齐夫人和她的猫拉斯塔斯已经共同居住在一套公寓里很多年了。"},"examples":[{"en":"He has shared an office with his brother for five years.","zh":"他和哥哥已经共用一间办公室五年了。"},{"en":"Mary has shared a room with her sister since childhood.","zh":"玛丽从小就和妹妹同住一个房间。"}]},{"pattern":"主语 + was + 形容词, though + 主语 + 动词","explanation":"","original":{"en":"He looked very well, though he was rather thirsty.","zh":"他看起来很健康，虽然相当口渴。"},"examples":[{"en":"She seemed happy, though she was actually quite tired.","zh":"她看起来很开心，虽然实际上很累。"},{"en":"The book was interesting, though it was a bit long.","zh":"这本书很有趣，虽然有点长。"}]},{"pattern":"It is + 时间 + when...","explanation":"","original":{"en":"Sure enough, Rastus arrived punctually at seven o'clock that evening.","zh":"果然，拉斯塔斯那天晚上准时七点回来了。"},"examples":[{"en":"The train arrived exactly at nine o'clock as expected.","zh":"火车正如预期的那样准时九点到达。"},{"en":"He came right on time for the meeting.","zh":"他正好准时来开会。"}]},{"pattern":"主语 + explained that + 从句","explanation":"","original":{"en":"She explained that Rastus was very dear to her.","zh":"她解释说拉斯塔斯对她来说非常珍贵。"},"examples":[{"en":"He explained that the project would take another month.","zh":"他解释这个项目还需要一个月。"},{"en":"The teacher explained that the exam would be next Friday.","zh":"老师解释说考试将在下周五进行。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“相当大的；相当多的” 对应的单词是？","hint":"adjective · /kənˈsɪdərəbl/","options":["snore","pride","Aegean","considerable"],"answer":3,"explain":"considerable · /kənˈsɪdərəbl/ · adjective · 相当大的；相当多的。强调数量或程度之大，常用于正式语境","source":{"kind":"vocab","word":"considerable"},"id":"b3-u19-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：失踪；消失","hint":"/ˌdɪsəˈpɪərəns/ · noun","answer":"disappearance","placeholder":"输入英文单词","explain":"disappearance · /ˌdɪsəˈpɪərəns/ · noun · 失踪；消失。disappear的名词形式，指某人或某物不见的情况","source":{"kind":"vocab","word":"disappearance"},"id":"b3-u19-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Considering the amount she paid, he was dear _____!","hint":"考虑到她付出的金额，拉斯塔斯多方面都很珍贵！","answer":"in more ways than one","placeholder":"输入缺失的短语","explain":"in more ways than one：不止一种方式；多方面地（考虑到她付出的金额，拉斯塔斯多方面都很珍贵！）","source":{"kind":"phrase","phrase":"in more ways than one"},"id":"b3-u19-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The writer _____ that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000.","hint":"写信人称拉斯特斯很安全，如果拉姆齐夫人支付1000英镑赎金，它将立即被送回。","answer":"stated","placeholder":"输入缺失的单词","explain":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000. — 写信人称拉斯特斯很安全，如果拉姆齐夫人支付1000英镑赎金，它将立即被送回。","source":{"kind":"sentence","en":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000."},"id":"b3-u19-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在过去某一时刻或某一段时间正在进行的动作，常与when、while等连用” 描述的是哪个语法点？","hint":"主语 + was/were + 动词-ing","options":["no matter what引导的让步状语从句","动词不定式作表语 (Infinitive as Predicative)","so...that 结果状语从句","过去进行时 (Past Continuous Tense)"],"answer":3,"explain":"过去进行时 (Past Continuous Tense)：主语 + was/were + 动词-ing：用于描述过去正在发生的动作背景，或与一般过去时连用表示过去某事发生时有另一动作在进行","source":{"kind":"grammar","title":"过去进行时 (Past Continuous Tense)"},"id":"b3-u19-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000.","hint":"","options":["同时，他创办了一所非常成功的拳击学院，甚至拜伦勋爵也成了他的学生之一。","我父亲带我出国时我才五岁，那已经是十八年前的事了。","后来我们沿着村里的主要街道走去，一群默默无声的孩子跟在我们后面。","写信人称拉斯特斯很安全，如果拉姆齐夫人支付1000英镑赎金，它将立即被送回。"],"answer":3,"explain":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000. — 写信人称拉斯特斯很安全，如果拉姆齐夫人支付1000英镑赎金，它将立即被送回。","source":{"kind":"sentence","en":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of ￡1,000."},"id":"b3-u19-q06"}]},{"id":"b3-u20","book":3,"unit":20,"key":"20","lessonFrom":20,"lessonTo":20,"title":"Pioneer Pilots","titleZh":"拓荒飞行员","question":"What was the name of the first plane to fly across the English Channel?","sentences":[{"en":"In 1908 Lord Northcliffe offered a prize of ￡1,000 to the first man who would fly across the English Channel.","zh":"1908年，诺思克利夫勋爵悬赏1000英镑，奖给第一位飞越英吉利海峡的人。","t":15.81},{"en":"Over a year passed before the first attempt was made.","zh":"一年多过去了，才有人首次尝试。","t":26.78},{"en":"On July 19th, 1909, in the early morning,","zh":"1909年7月19日清晨，","t":31.28},{"en":"Hubert Latham took off from the French coast in his plane the 'Antoinette IV.'","zh":"休伯特·拉瑟姆驾驶他的“安托瓦内特四号”飞机从法国海岸起飞。","t":36.36},{"en":"He had travelled only seven miles across the Channel when his engine failed and he was forced to land on the sea.","zh":"他飞越海峡仅七英里，发动机就失灵了，被迫降落在海面上。","t":43.14},{"en":"The 'Antoinette' floated on the water until Latham was picked up by a ship.","zh":"“安托瓦内特”号浮在水面，直到拉瑟姆被一艘船救起。","t":52.26},{"en":"Two days later, Louis Bleriot arrived near Calais with a plane called 'No.XI'.","zh":"两天后，路易·布莱里奥带着一架名叫“十一号”的飞机抵达加来附近。","t":59.22},{"en":"Bleriot had been making planes since 1905 and this was his latest model.","zh":"布莱里奥自1905年起就在制造飞机，这是他的最新型号。","t":67.16},{"en":"A week before, he had completed a successful overland flight during which he covered twenty-six miles.","zh":"一周前，他成功完成了一次陆上飞行，飞行距离达二十六英里。","t":74.33},{"en":"Latham, however, did not give up easily.","zh":"然而，拉瑟姆并没有轻易放弃。","t":82.54},{"en":"He, too, arrived near Calais on the same day with a new 'Antoinette'.","zh":"他也在同一天带着一架新的“安托瓦内特”号抵达加来附近。","t":85.76},{"en":"It looked as if there would be an exciting race across the Channel.","zh":"看来将有一场激动人心的跨海峡比赛。","t":92.2},{"en":"Both planes were going to take off on July 25th, but Latham failed to get up early enough.","zh":"两架飞机都准备在7月25日起飞，但拉瑟姆未能足够早地起床。","t":97.19},{"en":"After making a short test flight at 4.15 a.m., Bleriot set off half an hour later.","zh":"在凌晨4点15分进行了一次短程试飞后，布莱里奥在半小时后出发了。","t":105.05},{"en":"His great flight lasted thirty-seven minutes.","zh":"他这次伟大的飞行持续了三十七分钟。","t":113.1},{"en":"When he landed near Dover, the first person to greet him was a local policeman.","zh":"当他在多佛附近着陆时，第一个迎接他的是一位当地警察。","t":116.9},{"en":"Latham made another attempt a week later and got within half a mile of Dover,","zh":"一周后，拉瑟姆又进行了一次尝试，到达了离多佛半英里以内的地方，","t":123.67},{"en":"but he was unlucky again.","zh":"但他再次不幸。","t":129.34},{"en":"His engine failed and he landed on the sea for the second time.","zh":"他的发动机失灵了，他第二次降落在海面上。","t":131.85}],"vocab":[{"word":"pioneer","phonetic":"/ˌpaɪəˈnɪə(r)/","meanings":[{"pos":"noun","meaning":"先驱；先锋；创始人","usage":"指在某个领域最先开展探索或取得成就的人"},{"pos":"verb","meaning":"开创；倡导","usage":"表示率先做某件事或开发某类事物"}]},{"word":"offer","phonetic":"/ˈɒfə(r)/","meanings":[{"pos":"verb","meaning":"主动提供；出价","usage":"后可接名词、双宾语或不定式，常见结构offer sth. to sb. / offer sb. sth."},{"pos":"noun","meaning":"提议；报价","usage":"常用搭配make an offer"}]},{"word":"attempt","phonetic":"/əˈtempt/","meanings":[{"pos":"noun","meaning":"尝试；企图","usage":"常用搭配make an attempt to do sth. / at doing sth."},{"pos":"verb","meaning":"尝试；努力","usage":"后接不定式，attempt to do sth."}]},{"word":"coast","phonetic":"/kəʊst/","meanings":[{"pos":"noun","meaning":"海岸；海滨","usage":"指陆地与海洋交界的狭长地带"}]},{"word":"engine","phonetic":"/ˈendʒɪn/","meanings":[{"pos":"noun","meaning":"发动机；引擎","usage":"指为车辆、飞机等提供动力的装置"}]},{"word":"fail","phonetic":"/feɪl/","meanings":[{"pos":"verb","meaning":"失灵；失效；失败","usage":"可表示机器故障，也可表示做某事未成功，常见结构fail to do sth."}]},{"word":"force","phonetic":"/fɔːs/","meanings":[{"pos":"verb","meaning":"强迫；迫使","usage":"常用被动结构be forced to do sth.，表示不得不做某事"},{"pos":"noun","meaning":"力量；武力","usage":"可指物理力量或军事力量"}]},{"word":"float","phonetic":"/fləʊt/","meanings":[{"pos":"verb","meaning":"漂浮；浮动","usage":"指物体在液体或气体表面停留不沉没"}]},{"word":"latest","phonetic":"/ˈleɪtɪst/","meanings":[{"pos":"adjective","meaning":"最新的；最近的","usage":"是late的最高级形式，修饰名词表示最近出现的事物"}]},{"word":"overland","phonetic":"/ˈəʊvəlænd/","meanings":[{"pos":"adjective","meaning":"陆路的；横跨陆地的","usage":"修饰旅行、飞行等表示经由陆地的"}]},{"word":"complete","phonetic":"/kəmˈpliːt/","meanings":[{"pos":"verb","meaning":"完成；结束","usage":"后接名词或动名词，表示完成某项任务或活动"},{"pos":"adjective","meaning":"完整的；完全的","usage":"修饰名词表示没有缺失部分的"}]},{"word":"cover","phonetic":"/ˈkʌvə(r)/","meanings":[{"pos":"verb","meaning":"行走（一段路程）；覆盖","usage":"后接距离名词，表示行进了某段长度的路程"}]},{"word":"test","phonetic":"/test/","meanings":[{"pos":"noun","meaning":"测试；试验","usage":"常用搭配test flight表示试飞，test exam表示测验"},{"pos":"verb","meaning":"测试；检验","usage":"表示检查事物的功能或人的能力"}]},{"word":"last","phonetic":"/lɑːst/","meanings":[{"pos":"verb","meaning":"持续；延续","usage":"后接表示时间的名词，说明事件持续的时长"}]},{"word":"local","phonetic":"/ˈləʊkl/","meanings":[{"pos":"adjective","meaning":"当地的；本地的","usage":"修饰人或事物表示属于某个特定地区的"}]}],"phrases":[{"phrase":"take off","usage":"表示飞机起飞，也可引申为事业突然成功、脱掉衣物等含义","examples":[{"en":"The plane is scheduled to take off at 9 a.m.","zh":"这架飞机计划上午9点起飞。"},{"en":"After three years of hard work, his career finally took off.","zh":"经过三年的努力，他的事业终于腾飞了。"}]},{"phrase":"pick up","usage":"此处表示接走、营救某人，也可表示捡起、学会（知识/技能）、接收到信号等含义","examples":[{"en":"The lifeboat picked up all the survivors from the sunken ship.","zh":"救生艇救起了沉船上的所有幸存者。"},{"en":"I picked up some Japanese when I was travelling in Tokyo.","zh":"我在东京旅行的时候学会了一些日语。"}]},{"phrase":"give up","usage":"表示放弃、停止做某事，后可接名词或动名词","examples":[{"en":"No matter how difficult it is, you should never give up your dream.","zh":"无论有多难，你都不应该放弃自己的梦想。"},{"en":"My father gave up smoking last year for his health.","zh":"我爸爸为了健康去年戒烟了。"}]},{"phrase":"it looked as if","usage":"用来表示“看起来似乎/好像”，可描述真实情况，也可描述虚拟的假设","examples":[{"en":"It looked as if it was going to rain, so we took an umbrella with us.","zh":"看起来好像要下雨了，所以我们带了一把伞。"},{"en":"He smiled happily, and it looked as if he had won the game.","zh":"他笑得很开心，看起来好像已经赢了比赛。"}]},{"phrase":"set off","usage":"表示出发、动身，也可表示引爆、引发某事","examples":[{"en":"We set off at dawn so that we could get to the mountain top before noon.","zh":"我们黎明就出发，这样就能在中午之前到达山顶。"},{"en":"The news set off a heated discussion among the students.","zh":"这个消息在学生中引发了激烈的讨论。"}]},{"phrase":"be forced to do sth.","usage":"表示“被迫做某事”，强调因外界原因不得不做非主观意愿的事","examples":[{"en":"Because of the heavy snow, the driver was forced to stop the car.","zh":"因为大雪，司机被迫把车停下来。"},{"en":"Many small companies were forced to close during the economic crisis.","zh":"经济危机期间很多小公司被迫倒闭。"}]},{"phrase":"make an attempt","usage":"表示“尝试、试图做某事”，后可接to do或at doing","examples":[{"en":"He made an attempt to pass the driving test, but he failed because of nervousness.","zh":"他尝试通过驾照考试，但因为紧张失败了。"},{"en":"The team made an attempt at climbing the highest mountain in the country.","zh":"这支队伍尝试攀登该国最高的山峰。"}]},{"phrase":"within ... of","usage":"表示“在距离……不到……的范围内”，用来描述距离、时间等的接近程度","examples":[{"en":"The hotel is within 10 minutes' walk of the railway station.","zh":"这家酒店距离火车站步行不到10分钟。"},{"en":"The team was within one point of winning the championship.","zh":"这支队伍差一分就能赢得冠军。"}]}],"grammar":[{"title":"过去完成时","definition":"表示在过去某个时间或动作之前已经发生或完成的动作，即“过去的过去”","structure":"主语 + had + 动词过去分词 + 其他","usage":"常和before, until, when等引导的时间状语从句连用，明确两个过去动作的先后顺序","examples":[{"en":"He had travelled only seven miles across the Channel when his engine failed.","zh":"他刚在海峡上飞了7英里，发动机就出故障了。"},{"en":"Bleriot had been making planes since 1905 and this was his latest model.","zh":"布莱里奥从1905年起就开始制造飞机，这是他最新型号的飞机。"},{"en":"A week before, he had completed a successful overland flight during which he covered twenty-six miles.","zh":"一周之前，他刚刚成功完成了一次26英里的陆上飞行。"}]},{"title":"定语从句中的“介词+which”结构","definition":"当关系代词which在定语从句中作介词的宾语时，可将介词提前到which之前，构成“介词+which”的结构，用来修饰表示事物的先行词","structure":"先行词（事物） + 介词 + which + 从句其他部分","usage":"介词的选择通常根据从句中的动词、形容词与介词的固定搭配，或者先行词与介词的搭配来确定","examples":[{"en":"A week before, he had completed a successful overland flight during which he covered twenty-six miles.","zh":"一周之前，他刚刚成功完成了一次26英里的陆上飞行。（which指代flight，during which = during the flight）"},{"en":"This is the house in which Lu Xun once lived.","zh":"这就是鲁迅曾经住过的房子。（which指代house，in which = in the house）"},{"en":"The book for which you are looking is on the shelf.","zh":"你正在找的那本书在书架上。（which指代book，for which = for the book）"}]},{"title":"时间状语before引导的时间状语从句","definition":"before引导时间状语从句时，表示主句的动作发生在从句动作之前，可翻译为“在……之前”“过了多久才……”","structure":"主句 + before + 从句（一般过去时）","usage":"当主句描述的是一段时间的流逝时，常翻译为“过了……才发生某事”","examples":[{"en":"Over a year passed before the first attempt was made.","zh":"过了一年多人们才进行第一次尝试。"},{"en":"Several months went by before we finished the whole project.","zh":"过了好几个月我们才完成整个项目。"},{"en":"I had waited for two hours before he finally showed up.","zh":"我等了两个小时他才终于出现。"}]}],"patterns":[{"pattern":"时间 + passed before + 事件","explanation":"","original":{"en":"Over a year passed before the first attempt was made.","zh":"过了一年多人们才进行第一次尝试。"},"examples":[{"en":"Three hours passed before the rescue team arrived at the accident site.","zh":"过了三个小时救援队才抵达事故现场。"},{"en":"Many years passed before the old temple was rebuilt and opened to the public.","zh":"过了很多年这座古庙才被重建并对公众开放。"}]},{"pattern":"主语 + had done sth. when + 另一过去动作","explanation":"","original":{"en":"He had travelled only seven miles across the Channel when his engine failed and he was forced to land on the sea.","zh":"他刚在海峡上飞了7英里，发动机就出故障了，他被迫降落在海面上。"},"examples":[{"en":"I had just finished my homework when my friend invited me to play basketball.","zh":"我刚写完作业，我的朋友就邀请我去打篮球。"},{"en":"We had walked only two hundred metres when it started to rain heavily.","zh":"我们刚走了200米，就开始下大雨了。"}]},{"pattern":"It looked as if + 从句","explanation":"","original":{"en":"It looked as if there would be an exciting race across the Channel.","zh":"看起来似乎会有一场激动人心的横跨海峡的比赛。"},"examples":[{"en":"It looked as if we would have to cancel the picnic because of the bad weather.","zh":"看起来我们因为糟糕的天气得取消野餐了。"},{"en":"He looked so pale that it looked as if he was seriously ill.","zh":"他脸色这么苍白，看起来好像病得很重。"}]},{"pattern":"主语 + 动作 + lasted + 时长","explanation":"","original":{"en":"His great flight lasted thirty-seven minutes.","zh":"他这次伟大的飞行持续了37分钟。"},"examples":[{"en":"The opening ceremony of the sports meeting lasted two and a half hours.","zh":"运动会的开幕式持续了两个半小时。"},{"en":"The heavy rain lasted almost the whole day and caused floods in many areas.","zh":"这场大雨持续了几乎一整天，在很多地区引发了洪水。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“先驱；先锋；创始人” 对应的单词是？","hint":"noun · /ˌpaɪəˈnɪə(r)/","options":["soar","pioneer","grocer","stem"],"answer":1,"explain":"pioneer · /ˌpaɪəˈnɪə(r)/ · noun · 先驱；先锋；创始人。指在某个领域最先开展探索或取得成就的人","source":{"kind":"vocab","word":"pioneer"},"id":"b3-u20-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：最新的；最近的","hint":"/ˈleɪtɪst/ · adjective","answer":"latest","placeholder":"输入英文单词","explain":"latest · /ˈleɪtɪst/ · adjective · 最新的；最近的。是late的最高级形式，修饰名词表示最近出现的事物","source":{"kind":"vocab","word":"latest"},"id":"b3-u20-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The plane is scheduled to _____ at 9 a.m.","hint":"这架飞机计划上午9点起飞。","answer":"take off","placeholder":"输入缺失的短语","explain":"take off：表示飞机起飞，也可引申为事业突然成功、脱掉衣物等含义（这架飞机计划上午9点起飞。）","source":{"kind":"phrase","phrase":"take off"},"id":"b3-u20-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：He, too, arrived _____ Calais on the same day with a new 'Antoinette'.","hint":"他也在同一天带着一架新的“安托瓦内特”号抵达加来附近。","answer":"near","placeholder":"输入缺失的单词","explain":"He, too, arrived near Calais on the same day with a new 'Antoinette'. — 他也在同一天带着一架新的“安托瓦内特”号抵达加来附近。","source":{"kind":"sentence","en":"He, too, arrived near Calais on the same day with a new 'Antoinette'."},"id":"b3-u20-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“before引导时间状语从句时，表示主句的动作发生在从句动作之前，可翻译为“在……之前”“过了多久才……”” 描述的是哪个语法点？","hint":"主句 + before + 从句（一般过去时）","options":["as引导的非限制性定语从句","时间状语before引导的时间状语从句","as if引导的虚拟语气","一般过去时 (Simple Past Tense)"],"answer":1,"explain":"时间状语before引导的时间状语从句：主句 + before + 从句（一般过去时）：当主句描述的是一段时间的流逝时，常翻译为“过了……才发生某事”","source":{"kind":"grammar","title":"时间状语before引导的时间状语从句"},"id":"b3-u20-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nLatham, however, did not give up easily.","hint":"","options":["抢劫在3分钟之内便结束了，因为劫匪们又争先恐后地跳上汽车，汽车以惊人的速度开走了。","有些戏剧非常成功，一连上演好几年。","世界上已知最深的洞穴是格勒诺布尔附近的贝杰深洞。","然而，拉瑟姆并没有轻易放弃。"],"answer":3,"explain":"Latham, however, did not give up easily. — 然而，拉瑟姆并没有轻易放弃。","source":{"kind":"sentence","en":"Latham, however, did not give up easily."},"id":"b3-u20-q06"}]},{"id":"b3-u21","book":3,"unit":21,"key":"21","lessonFrom":21,"lessonTo":21,"title":"Daniel Mendoza","titleZh":"丹尼尔·门多萨","question":"How many unsuccessful attempts did Mendoza make before becoming Champion of all England?","sentences":[{"en":"Boxing matches were very popular in England two hundred years ago.","zh":"两百年前，拳击比赛在英格兰非常盛行。","t":18.59},{"en":"In those days, boxers fought with bare fists for prize money.","zh":"在那些日子里，拳击手们赤手空拳地搏斗以争夺奖金。","t":23.52},{"en":"Because of this, they were known as 'prizefighters'.","zh":"正因为如此，他们被称为“职业拳击手”。","t":28.93},{"en":"However, boxing was very crude,","zh":"然而，拳击是非常原始的，","t":33.27},{"en":"for there were no rules and a prizefighter could be seriously injured or even killed during a match.","zh":"因为当时没有规则，职业拳击手在比赛中可能会受重伤，甚至死亡。","t":36.63},{"en":"One of the most colourful figures in boxing history was Daniel Mendoza, who was born in 1764.","zh":"拳击史上最引人注目的人物之一是丹尼尔·门多萨，他出生于1764年。","t":44.94},{"en":"The use of gloves was not introduced until 1860, when the Marquis of Queensberry drew up the first set of rules.","zh":"直到1860年，昆斯伯里侯爵制定了第一套规则后，才引入了手套的使用。","t":53.56},{"en":"Though he was technically a prizefighter,","zh":"尽管从技术上讲他是一名职业拳击手，","t":62.63},{"en":"Mendoza did much to change crude prizefighting into a sport, for he brought science to the game.","zh":"但门多萨为将原始的职业拳击比赛转变为一项运动做了很多工作，因为他将科学带入了这项运动。","t":65.75},{"en":"In his day, Mendoza enjoyed tremendous popularity.","zh":"在他那个时代，门多萨享有巨大的声望。","t":73.71},{"en":"He was adored by rich and poor alike.","zh":"他深受富人和穷人的喜爱。","t":78.41},{"en":"Mendoza rose to fame swiftly after a boxing match when he was only fourteen years old.","zh":"门多萨在14岁时参加一场拳击比赛后迅速成名。","t":81.94},{"en":"This attracted the attention of Richard Humphries who was then the most eminent boxer in England.","zh":"这引起了理查德·汉弗莱斯的注意，他当时是英格兰最杰出的拳击手。","t":88.42},{"en":"He offered to train Mendoza and his young pupil was quick to learn.","zh":"他主动提出训练门多萨，而他的年轻学生也学得很快。","t":95.87},{"en":"In fact, Mendoza soon became so successful that Humphries turned against him.","zh":"事实上，门多萨很快就变得非常成功，以至于汉弗莱斯转而反对他。","t":100.98},{"en":"The two men quarrelled bitterly and it was clear that the argument could only be settled by a fight.","zh":"两人激烈争吵，很明显，争论只能通过一场战斗来解决。","t":108.01},{"en":"A match was held at Stilton, where both men fought for an hour.","zh":"在斯蒂尔顿举行了一场比赛，两人激战了一个小时。","t":116.5},{"en":"The public bet a great deal of money on Mendoza, but he was defeated.","zh":"公众在门多萨身上下了大笔赌注，但他被击败了。","t":121.6},{"en":"Mendoza met Humphries in the ring on a later occasion and he lost for a second time.","zh":"门多萨后来又在拳击台上与汉弗莱斯相遇，但他第二次输了。","t":127.22},{"en":"It was not until his third match in 1790 that he finally beat Humphries and became Champion of England.","zh":"直到1790年的第三场比赛，他才最终击败汉弗莱斯，成为英格兰冠军。","t":133.97},{"en":"Meanwhile, he founded a highly successful Academy and even Lord Byron became one of his pupils.","zh":"同时，他创办了一所非常成功的拳击学院，甚至拜伦勋爵也成了他的学生之一。","t":143.5},{"en":"He earned enormous sums of money and was paid as much as ￡100 for a single appearance.","zh":"他赚取了巨额财富，单次出场费高达100英镑。","t":151.59},{"en":"Despite this, he was so extravagant that he was always in debt.","zh":"尽管如此，他非常奢侈，总是负债累累。","t":159.85},{"en":"After he was defeated by a boxer called Gentleman Jackson, he was quickly forgotten.","zh":"在他被一位名叫“绅士”杰克逊的拳击手击败后，他很快就被遗忘了。","t":165.91},{"en":"He was sent to prison for failing to pay his debts and died in poverty in 1836.","zh":"他因未能偿还债务而被送进监狱，并于1836年贫困潦倒地去世。","t":172.53}],"vocab":[{"word":"prizefighter","phonetic":"/ˈpraɪzfaɪtər/","meanings":[{"pos":"noun","meaning":"以奖金为报酬的拳击手","usage":"用于指当时没有规则、以奖金为目的的拳击比赛选手"}]},{"word":"crude","phonetic":"/kruːd/","meanings":[{"pos":"adjective","meaning":"粗糙的，粗制的","usage":"形容缺乏精细规则或技术的体育项目"}]},{"word":"colourful","phonetic":"/ˈkʌləfʊl/","meanings":[{"pos":"adjective","meaning":"丰富多彩的，引人注目的","usage":"形容人物或事件生动、引人关注"}]},{"word":"gloves","phonetic":"/ɡlʌvz/","meanings":[{"pos":"noun","meaning":"（拳击）手套","usage":"指用于保护拳手的专用手套"}]},{"word":"academy","phonetic":"/əˈkædəmi/","meanings":[{"pos":"noun","meaning":"学院，专科学校","usage":"指专业训练或教学的机构"}]},{"word":"extravagant","phonetic":"/ɪkˈstrævəɡənt/","meanings":[{"pos":"adjective","meaning":"奢侈的，挥霍的","usage":"形容花费无度、经常欠债的行为"}]},{"word":"pupil","phonetic":"/ˈpjuːpɪl/","meanings":[{"pos":"noun","meaning":"学生，门徒","usage":"指接受某位老师或教练指导的人"}]},{"word":"popularity","phonetic":"/ˌpɒpjʊˈlærəti/","meanings":[{"pos":"noun","meaning":"受欢迎度，流行","usage":"指在大众中被喜爱或认可的程度"}]},{"word":"bet","phonetic":"/bet/","meanings":[{"pos":"verb","meaning":"打赌，下注","usage":"指对某事的结果下钱进行赌博"}]},{"word":"defeated","phonetic":"/dɪˈfiːtɪd/","meanings":[{"pos":"verb","meaning":"被击败的","usage":"在比赛或斗争中输掉"}]},{"word":"imprisoned","phonetic":"/ɪmˈprɪzənd/","meanings":[{"pos":"verb","meaning":"被监禁的","usage":"因债务或其他原因被关进监狱"}]},{"word":"poverty","phonetic":"/ˈpɒvəti/","meanings":[{"pos":"noun","meaning":"贫穷，贫困","usage":"指缺乏金钱和基本生活条件的状态"}]},{"word":"champion","phonetic":"/ˈtʃæmpiən/","meanings":[{"pos":"noun","meaning":"冠军","usage":"指在比赛或竞争中最优秀的人"}]},{"word":"boxer","phonetic":"/ˈbɒksər/","meanings":[{"pos":"noun","meaning":"拳击手","usage":"专门从事拳击运动的人"}]},{"word":"renowned","phonetic":"/rɪˈnaʊnd/","meanings":[{"pos":"adjective","meaning":"著名的，声誉高的","usage":"指因某方面成就而被广泛认可"}]}],"phrases":[{"phrase":"bring science to the game","usage":"指把科学的方法或技术引入某项运动，使其更系统化","examples":[{"en":"Mendoza brought science to the game, revolutionising prizefighting.","zh":"门多萨把科学带进拳击，使当时的拳击运动发生了革命性变化。"}]},{"phrase":"enjoy tremendous popularity","usage":"表示某人或某事在大众中极受欢迎","examples":[{"en":"Mendoza enjoyed tremendous popularity among all classes.","zh":"门多萨在各阶层中都极受欢迎。"}]},{"phrase":"be adored by rich and poor alike","usage":"形容受到所有社会阶层人们的喜爱","examples":[{"en":"He was adored by rich and poor alike.","zh":"无论是富人还是穷人，都对他崇拜不已。"}]},{"phrase":"rise to fame swiftly","usage":"指在短时间内迅速成名","examples":[{"en":"Mendoza rose to fame swiftly after a boxing match at fourteen.","zh":"门多萨在十四岁时的一场拳击赛后迅速成名。"}]},{"phrase":"turn against","usage":"表示从友好或支持转为敌对或反对","examples":[{"en":"Humphries turned against him after Mendoza's success.","zh":"在门多萨成功后，汉弗莱斯转向反对他。"}]},{"phrase":"quarrel bitterly","usage":"指激烈、愤怒地争吵","examples":[{"en":"The two men quarrelled bitterly.","zh":"两人激烈争吵。"}]},{"phrase":"settle the argument by a fight","usage":"通过打斗来解决争端","examples":[{"en":"The argument could only be settled by a fight.","zh":"这场争论只能通过一场拳赛来解决。"}]},{"phrase":"bet a great deal of money on","usage":"指在某人或某事上投入大量赌注","examples":[{"en":"The public bet a great deal of money on Mendoza.","zh":"公众在门多萨身上下了大额赌注。"}]},{"phrase":"be paid as much as £100 for a single appearance","usage":"指一次出场费高达一百英镑","examples":[{"en":"He was paid as much as £100 for a single appearance.","zh":"他一次出场就能得到高达一百英镑的报酬。"}]},{"phrase":"be sent to prison for failing to pay his debts","usage":"因未能偿还债务而被监禁","examples":[{"en":"He was sent to prison for failing to pay his debts.","zh":"他因未能偿还债务而被送进监狱。"}]}],"grammar":[{"title":"It was not until ... that ...（强调时间）","definition":"用于强调某事直到特定时间点才发生。结构为“It is/was not until + 时间/事件 + that + 主语 + 动词（过去式）”。","structure":"It is/was not until + 时间/事件 + that + 主语 + 动词过去式","usage":"强调某个迟来的转折点，常用于叙述关键性事件的发生时刻。","examples":[{"en":"It was not until his third match in 1790 that he finally beat Humphries.","zh":"直到1790年的第三场比赛，他才终于击败了汉弗莱斯。"},{"en":"It was not until 1860 that gloves were introduced.","zh":"直到1860年，手套才被引入拳击。"}]},{"title":"Though / Although + 从句（让步状语从句）","definition":"表示“虽然/尽管”，用于引出与主句意思相反或出乎意料的情况。","structure":"Though / Although + 主语 + 动词（一般过去时）, 主句","usage":"用于对比两个事实，突出主句的重要性。","examples":[{"en":"Though he was technically a prizefighter, Mendoza brought science to the sport.","zh":"虽然他在技术上是个奖金拳击手，门多萨却把科学带进了这项运动。"},{"en":"Although boxing was crude, it was extremely popular.","zh":"尽管拳击很粗糙，却极为流行。"}]},{"title":"Past Simple 与 Past Perfect 的时序区分","definition":"Past Simple 用于描述已完成的具体过去动作；Past Perfect 表示在另一过去动作之前已经发生的动作，构成‘过去的过去’。","structure":"Past Simple: 主语 + 动词过去式 / Past Perfect: 主语 + had + 过去分词","usage":"在叙述连续发生的过去事件时，先发生的动作用过去完成时，后发生的动作用一般过去时。","examples":[{"en":"Mendoza rose to fame after he had defeated many opponents.","zh":"门多萨在击败许多对手后才成名。"},{"en":"He founded an academy after he had become champion.","zh":"他在成为冠军后才创办了学院。"}]}],"patterns":[{"pattern":"The use of X was not introduced until Y.","explanation":"","original":{"en":"The use of gloves was not introduced until 1860.","zh":"手套的使用直到1860年才被引入。"},"examples":[{"en":"The use of safety helmets was not introduced until 1990.","zh":"安全头盔的使用直到1990年才被引入。"},{"en":"The practice of wearing seat belts was not introduced until the 1970s.","zh":"佩戴安全带的做法直到20世纪70年代才被引入。"}]},{"pattern":"It was not until ... that ...","explanation":"","original":{"en":"It was not until his third match in 1790 that he finally beat Humphries.","zh":"直到1790年的第三场比赛，他才终于击败了汉弗莱斯。"},"examples":[{"en":"It was not until the 20th century that women gained the right to vote.","zh":"直到20世纪，妇女才获得投票权。"},{"en":"It was not until sunrise that the fog lifted.","zh":"直到日出，雾才散去。"}]},{"pattern":"Though he was ..., ...","explanation":"","original":{"en":"Though he was technically a prizefighter, Mendoza brought science to the sport.","zh":"虽然他在技术上是个奖金拳击手，门多萨却把科学带进了这项运动。"},"examples":[{"en":"Though she was only fifteen, she mastered three languages.","zh":"虽然她只有十五岁，她已经掌握了三门语言。"},{"en":"Though the weather was terrible, the game went on.","zh":"虽然天气很差，比赛仍在进行。"}]},{"pattern":"He was so ... that ...","explanation":"","original":{"en":"He was so extravagant that he was always in debt.","zh":"他太奢侈了，以至于总是负债累累。"},"examples":[{"en":"She was so nervous that she could not speak.","zh":"她紧张得说不出话来。"},{"en":"The problem was so complex that no one could solve it.","zh":"这个问题太复杂，没人能解决。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“学院，专科学校” 对应的单词是？","hint":"noun · /əˈkædəmi/","options":["steer","academy","log book","clump"],"answer":1,"explain":"academy · /əˈkædəmi/ · noun · 学院，专科学校。指专业训练或教学的机构","source":{"kind":"vocab","word":"academy"},"id":"b3-u21-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：贫穷，贫困","hint":"/ˈpɒvəti/ · noun","answer":"poverty","placeholder":"输入英文单词","explain":"poverty · /ˈpɒvəti/ · noun · 贫穷，贫困。指缺乏金钱和基本生活条件的状态","source":{"kind":"vocab","word":"poverty"},"id":"b3-u21-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The public _____ Mendoza.","hint":"公众在门多萨身上下了大额赌注。","answer":"bet a great deal of money on","placeholder":"输入缺失的短语","explain":"bet a great deal of money on：指在某人或某事上投入大量赌注（公众在门多萨身上下了大额赌注。）","source":{"kind":"phrase","phrase":"bet a great deal of money on"},"id":"b3-u21-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：In fact, Mendoza _____ became so successful that Humphries turned against him.","hint":"事实上，门多萨很快就变得非常成功，以至于汉弗莱斯转而反对他。","answer":"soon","placeholder":"输入缺失的单词","explain":"In fact, Mendoza soon became so successful that Humphries turned against him. — 事实上，门多萨很快就变得非常成功，以至于汉弗莱斯转而反对他。","source":{"kind":"sentence","en":"In fact, Mendoza soon became so successful that Humphries turned against him."},"id":"b3-u21-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于强调某事直到特定时间点才发生。结构为“It is/was not until + 时间/事件 + that + 主语 + 动词（过去式）”。” 描述的是哪个语法点？","hint":"It is/was not until + 时间/事件 + that + 主语 + 动词过去式","options":["It was not until ... that ...（强调时间）","名词性从句 (Noun Clauses)","过去进行时 (Past Continuous Tense)","现在进行时表感情色彩"],"answer":0,"explain":"It was not until ... that ...（强调时间）：It is/was not until + 时间/事件 + that + 主语 + 动词过去式：强调某个迟来的转折点，常用于叙述关键性事件的发生时刻。","source":{"kind":"grammar","title":"It was not until ... that ...（强调时间）"},"id":"b3-u21-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe two men quarrelled bitterly and it was clear that the argument could only be settled by a fight.","hint":"","options":["电话铃响了，这预示着一系列意想不到的灾难即将发生。","但我对自己非常满意。我找到了故障的原因。","两人激烈争吵，很明显，争论只能通过一场战斗来解决。","到20世纪末，电脑在人们家中会像电视机一样普及？"],"answer":2,"explain":"The two men quarrelled bitterly and it was clear that the argument could only be settled by a fight. — 两人激烈争吵，很明显，争论只能通过一场战斗来解决。","source":{"kind":"sentence","en":"The two men quarrelled bitterly and it was clear that the argument could only be settled by a fight."},"id":"b3-u21-q06"}]},{"id":"b3-u22","book":3,"unit":22,"key":"22","lessonFrom":22,"lessonTo":22,"title":"By Heart","titleZh":"熟记于心","question":"Which actor read the letter in the end, the aristocrat or the gaoler?","sentences":[{"en":"Some plays are so successful that they run for years on end.","zh":"有些戏剧非常成功，一连上演好几年。","t":17.32},{"en":"In many ways, this is unfortunate for the poor actors who are required to go on repeating the same lines night after night.","zh":"在许多方面，这对可怜的演员来说是不幸的，他们被要求夜复一夜地重复相同的台词。","t":22.41},{"en":"One would expect them to know their parts by heart and never have cause to falter.","zh":"人们会期望他们熟记自己的角色台词，永不结巴。","t":32.97},{"en":"Yet this is not always the case.","zh":"然而，事实并非总是如此。","t":39.12},{"en":"A famous actor in a highly successful play was once cast in the role of an aristocrat who had been imprisoned in the Bastille for twenty years.","zh":"一部非常成功的戏剧中，一位著名演员曾被塑造成一位在巴士底狱被囚禁了二十年的贵族。","t":42.81},{"en":"In the last act, a gaoler would always come on to the stage with a letter which he would hand to the prisoner.","zh":"在最后一幕中，一个狱卒总是会带着一封信上台，然后递给囚犯。","t":54.25},{"en":"Even though the noble was expected to read the letter at each performance, he always insisted that it should be written out in full.","zh":"尽管这位贵族在每次表演中都应该读这封信，但他总是坚持信应该写得清清楚楚。","t":63.38},{"en":"One night, the gaoler decided to play a joke on his colleague to find out if,","zh":"一天晚上，狱卒决定和他的同事开个玩笑，想看看，","t":72.81},{"en":"after so many performances, he had managed to learn the contents of the letter by heart.","zh":"在这么多场演出之后，他是否已经把信的内容熟记于心。","t":78.41},{"en":"The curtain went up on the final act of the play and revealed the aristocrat sitting alone behind bars in his dark cell.","zh":"戏剧的最后一幕拉开了帷幕，露出了贵族独自一人坐在漆黑牢房的铁窗后面。","t":85.45},{"en":"Just then, the gaoler appeared with the precious letter in his hands.","zh":"就在那时，狱卒手里拿着那封珍贵的信出现了。","t":95.16},{"en":"He entered the cell and presented the letter to the aristocrat.","zh":"他走进牢房，把信递给了贵族。","t":100.55},{"en":"But the copy he gave him had not been written out in full as usual.","zh":"但他给他的那份信件并未像往常一样完整写出。","t":105.36},{"en":"It was simply a blank sheet of paper.","zh":"那只是一张白纸。","t":110.5},{"en":"The gaoler looked on eagerly, anxious to see if his fellow actor had at last learnt his lines.","zh":"狱卒焦急地看着，渴望知道他的同事演员是否终于记住了台词。","t":114.14},{"en":"The noble stared at the blank sheet of paper for a few seconds.","zh":"贵族盯着那张白纸看了几秒钟。","t":122.23},{"en":"Then, squinting his eyes, he said: 'The light is dim. Read the letter to me.'","zh":"然后，他眯着眼睛说：“光线太暗了。你把信念给我听吧。”","t":127.45},{"en":"And he promptly handed the sheet of paper to the gaoler.","zh":"他立刻把那张纸递给了狱卒。","t":136.04},{"en":"Finding that he could not remember a word of the letter either,","zh":"狱卒发现自己也记不住信里一个字，","t":140.49},{"en":"the gaoler replied: 'The light is indeed dim, sire. I must get my glasses. '","zh":"他回答说：“陛下，光线确实很暗。我必须去拿我的眼镜。”","t":144.83},{"en":"With this, he hurried off the stage.","zh":"说完，他匆匆忙忙地下了台。","t":152.56},{"en":"Much to the aristocrat's amusement,","zh":"令贵族非常有趣的是，","t":156.38},{"en":"the gaoler returned a few moments later with a pair of glasses and the usual copy of the letter which he proceeded to read to the prisoner.","zh":"狱卒几分钟后带着一副眼镜和往常那封信的副本回来了，然后他开始念给囚犯听。","t":158.83}],"vocab":[{"word":"aristocrat","phonetic":"/ˈærɪstəkræt/","meanings":[{"pos":"noun","meaning":"贵族","usage":"指出身高贵、有贵族头衔的人"}]},{"word":"gaoler","phonetic":"/ˈdʒeɪlə(r)/","meanings":[{"pos":"noun","meaning":"监狱看守","usage":"负责看守囚犯的人，同 jailer"}]},{"word":"prisoner","phonetic":"/ˈprɪznə(r)/","meanings":[{"pos":"noun","meaning":"囚犯；俘虏","usage":"被关押的人，指因犯罪而被拘禁"}]},{"word":"performance","phonetic":"/pəˈfɔːməns/","meanings":[{"pos":"noun","meaning":"表演；演出","usage":"戏剧、音乐等在观众面前的正式演出"}]},{"word":"cast","phonetic":"/kɑːst/","meanings":[{"pos":"verb","meaning":"挑选...扮演角色","usage":"在戏剧或电影中指定演员扮演某个角色"}]},{"word":"insist","phonetic":"/ɪnˈsɪst/","meanings":[{"pos":"verb","meaning":"坚持；坚决要求","usage":"强烈要求某事发生，含有坚持己见之意"}]},{"word":"blank","phonetic":"/blæŋk/","meanings":[{"pos":"adj","meaning":"空白的；无内容的","usage":"没有写字或图案的，指纸张等表面无内容"}]},{"word":"dim","phonetic":"/dɪm/","meanings":[{"pos":"adj","meaning":"昏暗的；暗淡的","usage":"光线不充足，模糊不清"}]},{"word":"squint","phonetic":"/skwɪnt/","meanings":[{"pos":"verb","meaning":"眯着眼睛看","usage":"眼睛微微眯起以看得更清楚或避免强光"}]},{"word":"joke","phonetic":"/dʒəʊk/","meanings":[{"pos":"noun/verb","meaning":"笑话；开玩笑","usage":"用于逗乐的话语或行为"}]},{"word":"cell","phonetic":"/sel/","meanings":[{"pos":"noun","meaning":"牢房；单人房间","usage":"监狱中关押单个囚犯的小房间"}]},{"word":"present","phonetic":"/prɪˈzent/","meanings":[{"pos":"verb","meaning":"递交；呈上","usage":"正式地将某物交给某人"}]},{"word":"promptly","phonetic":"/ˈprɒmptli/","meanings":[{"pos":"adv","meaning":"立刻；迅速地","usage":"表示立即或很快地做某事"}]},{"word":"bars","phonetic":"/bɑːz/","meanings":[{"pos":"noun","meaning":"铁栏杆","usage":"监狱窗户或门上的金属条，用于防止逃跑"}]},{"word":"imprison","phonetic":"/ɪmˈprɪzn/","meanings":[{"pos":"verb","meaning":"监禁；关押","usage":"将某人关在监狱中"}]}],"phrases":[{"phrase":"by heart","usage":"背诵；牢记","examples":[{"en":"Students must learn these poems by heart.","zh":"学生们必须把这些诗背下来。"},{"en":"He knew all the lines by heart.","zh":"他把这些台词都背熟了。"}]},{"phrase":"run for years on end","usage":"连续上演多年","examples":[{"en":"The show has run for years on end.","zh":"这个节目已经连续演出了很多年。"}]},{"phrase":"night after night","usage":"夜复一夜；连续多夜","examples":[{"en":"She practiced the piano night after night.","zh":"她夜复一夜地练习钢琴。"}]},{"phrase":"have cause to do something","usage":"有理由/有原因做某事","examples":[{"en":"You have no cause to complain.","zh":"你没有理由抱怨。"}]},{"phrase":"come on to the stage","usage":"登上舞台；出场","examples":[{"en":"The actress came on to the stage at the second act.","zh":"女演员在第二幕登上舞台。"}]},{"phrase":"play a joke on someone","usage":"捉弄某人；开某人的玩笑","examples":[{"en":"They decided to play a joke on their teacher.","zh":"他们决定捉弄一下老师。"}]},{"phrase":"look on eagerly","usage":"热切地看着","examples":[{"en":"The audience looked on eagerly as the drama unfolded.","zh":"观众热切地看着剧情展开。"}]},{"phrase":"be cast in the role of","usage":"被选中扮演...角色","examples":[{"en":"She was cast in the role of Juliet.","zh":"她被选中扮演朱丽叶的角色。"}]},{"phrase":"hand to","usage":"递给；交给","examples":[{"en":"He handed the letter to the prisoner.","zh":"他把信递给了囚犯。"}]},{"phrase":"hurry off","usage":"匆忙离开","examples":[{"en":"With this, he hurried off the stage.","zh":"说完，他便匆匆离开了舞台。"}]}],"grammar":[{"title":"一般过去时 (Simple Past Tense)","definition":"表示过去发生的动作或存在的状态","structure":"主语 + 动词过去式","usage":"用于叙述过去发生的事情，故事通常采用过去时叙述","examples":[{"en":"The curtain went up on the final act.","zh":"最后一幕的幕布升起了。"},{"en":"The gaoler appeared with the precious letter.","zh":"看守拿着那封珍贵的信出现了。"},{"en":"The noble stared at the blank sheet of paper.","zh":"贵族盯着那张空白的纸看了一会儿。"}]},{"title":"过去进行时 (Past Continuous Tense)","definition":"表示过去某一时刻或时间段正在进行的动作","structure":"主语 + was/were + 动词-ing","usage":"用于描述过去正在发生的事情，常与过去进行时连用","examples":[{"en":"The gaoler was looking on eagerly.","zh":"看守正热切地看着。"},{"en":"The aristocrat was sitting alone behind bars.","zh":"贵族独自坐在铁栏后面。"}]},{"title":"used to 的用法","definition":"表示过去习惯性的动作或状态","structure":"主语 + used to + 动词原形","usage":"表示过去的习惯，与现在形成对比","examples":[{"en":"He always insisted that it should be written out in full.","zh":"他总是坚持要求把信完整地写出来。"},{"en":"The gaoler would always come on to the stage with a letter.","zh":"看守总是拿着信走上舞台。"}]}],"patterns":[{"pattern":"Some plays are so successful that + 主语 + 动词","explanation":"","original":{"en":"Some plays are so successful that they run for years on end.","zh":"有些戏剧如此成功，以至于它们连续上演多年。"},"examples":[{"en":"He is so tired that he can hardly speak.","zh":"他太累了，几乎说不出话来。"},{"en":"The book is so interesting that everyone wants to read it.","zh":"这本书太有趣了，每个人都想看。"}]},{"pattern":"One would expect + 主语 + to do something","explanation":"","original":{"en":"One would expect them to know their parts by heart.","zh":"人们会期望他们把台词背熟。"},"examples":[{"en":"One would expect a professional to do better.","zh":"人们会期望一个专业人士做得更好。"},{"en":"One would expect her to arrive on time.","zh":"人们会期望她准时到达。"}]},{"pattern":"...to find out if + 主语 + 过去式","explanation":"","original":{"en":"The gaoler decided to play a joke on his colleague to find out if he had managed to learn the contents of the letter by heart.","zh":"看守决定捉弄他的同事，想看看他是否已经把信的内容背熟了。"},"examples":[{"en":"She called him to find out if he was coming.","zh":"她打电话给他，想看看他是否要来。"},{"en":"I checked the paper to find out if I had passed.","zh":"我查看成绩单，想知道我是否通过了。"}]},{"pattern":"Much to + 名词 + 动词","explanation":"","original":{"en":"Much to the aristocrat's amusement, the gaoler returned...","zh":"令贵族非常高兴的是，看守回来了..."},"examples":[{"en":"Much to my surprise, he won the competition.","zh":"令我非常惊讶的是，他赢得了比赛。"},{"en":"Much to their disappointment, it rained on the day of the picnic.","zh":"令他们失望的是，野餐那天下雨了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“笑话；开玩笑” 对应的单词是？","hint":"noun/verb · /dʒəʊk/","options":["multimedia","lodge","liner","joke"],"answer":3,"explain":"joke · /dʒəʊk/ · noun/verb · 笑话；开玩笑。用于逗乐的话语或行为","source":{"kind":"vocab","word":"joke"},"id":"b3-u22-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：监禁；关押","hint":"/ɪmˈprɪzn/ · verb","answer":"imprison","placeholder":"输入英文单词","explain":"imprison · /ɪmˈprɪzn/ · verb · 监禁；关押。将某人关在监狱中","source":{"kind":"vocab","word":"imprison"},"id":"b3-u22-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Students must learn these poems _____.","hint":"学生们必须把这些诗背下来。","answer":"by heart","placeholder":"输入缺失的短语","explain":"by heart：背诵；牢记（学生们必须把这些诗背下来。）","source":{"kind":"phrase","phrase":"by heart"},"id":"b3-u22-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Just then, the gaoler appeared with the precious letter in his _____","hint":"就在那时，狱卒手里拿着那封珍贵的信出现了。","answer":"hands","placeholder":"输入缺失的单词","explain":"Just then, the gaoler appeared with the precious letter in his hands. — 就在那时，狱卒手里拿着那封珍贵的信出现了。","source":{"kind":"sentence","en":"Just then, the gaoler appeared with the precious letter in his hands."},"id":"b3-u22-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示过去习惯性的动作或状态” 描述的是哪个语法点？","hint":"主语 + used to + 动词原形","options":["used to 的用法","一般过去时 (Simple Past Tense)","现在分词作原因状语","独立主格结构"],"answer":0,"explain":"used to 的用法：主语 + used to + 动词原形：表示过去的习惯，与现在形成对比","source":{"kind":"grammar","title":"used to 的用法"},"id":"b3-u22-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nOne would expect them to know their parts by heart and never have cause to falter.","hint":"","options":["四周，一堆堆的石灰石闪耀着彩虹般的光芒。","在它们被蒸汽船取代之前，","人们会期望他们熟记自己的角色台词，永不结巴。","哭声确实是从一个烟囱里传出来的，"],"answer":2,"explain":"One would expect them to know their parts by heart and never have cause to falter. — 人们会期望他们熟记自己的角色台词，永不结巴。","source":{"kind":"sentence","en":"One would expect them to know their parts by heart and never have cause to falter."},"id":"b3-u22-q06"}]},{"id":"b3-u23","book":3,"unit":23,"key":"23","lessonFrom":23,"lessonTo":23,"title":"One Man's Meat is Another Man's Poison","titleZh":"各有所爱","question":"What was it about snails that made the writer collect them for his friend on that day in particular?","sentences":[{"en":"People become quite illogical when they try to decide what can be eaten and what cannot be eaten.","zh":"人们在决定什么能吃，什么不能吃的时候，会变得相当不合逻辑。","t":20.29},{"en":"If you lived in the Mediterranean, for instance, you would consider octopus a great delicacy.","zh":"例如，如果你住在地中海地区，你会认为章鱼是人间美味。","t":28.51},{"en":"You would not be able to understand why some people find it repulsive.","zh":"你会不理解为什么有些人觉得它令人厌恶。","t":35.92},{"en":"On the other hand, your stomach would turn at the idea of frying potatoes in animal fat-the normally accepted practice in many northern countries.","zh":"另一方面，一想到用动物脂肪炸土豆——这在许多北方国家是普遍接受的做法——你就会反胃。","t":41.78},{"en":"The sad truth is that most of us have been brought up to eat certain foods and we stick to them all our lives.","zh":"可悲的事实是，我们大多数人从小就被教导吃某些食物，并且我们一生都坚持这些食物。","t":53.91},{"en":"No creature has received more praise and abuse than the common garden snail.","zh":"没有哪种生物比普通的园林蜗牛得到过更多的赞扬和辱骂。","t":63.19},{"en":"Cooked in wine, snails are a great luxury in various parts of the world.","zh":"用酒烹制的蜗牛在世界各地都是一种高级奢侈品。","t":69.56},{"en":"There are countless people who, ever since their early years, have learned to associate snails with food.","zh":"无数人从小就学会将蜗牛与食物联系在一起。","t":75.43},{"en":"My friend, Robert, lives in a country where snails are despised.","zh":"我的朋友罗伯特住在一个厌恶蜗牛的国家。","t":84.2},{"en":"As his flat is in a large town, he has no garden of his own.","zh":"因为他的公寓在一个大城镇里，他没有自己的花园。","t":90.31},{"en":"For years he has been asking me to collect snails from my garden and take them to him.","zh":"多年来他一直让我从我的花园里收集蜗牛带给他。","t":95.31},{"en":"The idea never appealed to me very much, but one day, after a heavy shower,","zh":"这个想法从来没有太吸引我，但有一天，在一场大雨之后，","t":102.46},{"en":"I happened to be walking in my garden when I noticed a huge number of snails taking a stroll on some of my prize plants.","zh":"我碰巧在我的花园里散步，这时我注意到大量的蜗牛在我的几株珍贵植物上爬行。","t":109.17},{"en":"Acting on a sudden impulse, I collected several dozen, put them in a paper bag, and took them to Robert.","zh":"我一时冲动，收集了几十只，把它们放进一个纸袋里，然后带给了罗伯特。","t":118.55},{"en":"Robert was delighted to see me and equally pleased with my little gift.","zh":"罗伯特很高兴见到我，也同样喜欢我的小礼物。","t":127.01},{"en":"I left the bag in the hall and Robert and I went into the living room where we talked for a couple of hours.","zh":"我把袋子留在门厅里，罗伯特和我走进客厅，我们在那里聊了几个小时。","t":133.03},{"en":"I had forgotten all about the snails when Robert suddenly said that I must stay to dinner.","zh":"我已经完全忘记了蜗牛，这时罗伯特突然说我必须留下来吃晚饭。","t":140.56},{"en":"Snails would, of course, be the main dish.","zh":"蜗牛当然是主菜。","t":147.73},{"en":"I did not fancy the idea and I reluctantly followed Robert out of the room.","zh":"我不喜欢这个主意，我只好不情愿地跟着罗伯特离开了房间。","t":151.79},{"en":"To our dismay,","zh":"令我们沮丧的是，","t":157.9},{"en":"we saw that there were snails everywhere:","zh":"我们看到到处都是蜗牛：","t":159.7},{"en":"they had escaped from the paper bag","zh":"它们已经从纸袋里跑了出来","t":162.97},{"en":"and had taken complete possession of the hall! I have never been able to look at a snail since then.","zh":"并且完全占据了门厅！从那时起，我再也无法正眼看蜗牛了。","t":165.4}],"vocab":[{"word":"poison","phonetic":"/ˈpɔɪzən/","meanings":[{"pos":"noun","meaning":"毒药；毒物","usage":"指任何能够伤害或杀死生物的物质"}]},{"word":"illogical","phonetic":"/ɪˈlɒdʒɪkəl/","meanings":[{"pos":"adjective","meaning":"不合逻辑的；没有道理的","usage":"形容人的行为或想法缺乏逻辑性"}]},{"word":"delicacy","phonetic":"/ˈdelɪkəsi/","meanings":[{"pos":"noun","meaning":"美味；佳肴；珍品","usage":"指特别美味或珍贵的食物"}]},{"word":"repulsive","phonetic":"/rɪˈpʌlsɪv/","meanings":[{"pos":"adjective","meaning":"令人厌恶的；令人反感的","usage":"描述让人觉得恶心或排斥的事物"}]},{"word":"octopus","phonetic":"/ˈɒktəpəs/","meanings":[{"pos":"noun","meaning":"章鱼","usage":"一种海洋生物，常被当作食物"}]},{"word":"despise","phonetic":"/dɪˈspaɪz/","meanings":[{"pos":"verb","meaning":"鄙视；看不起；厌恶","usage":"表达对某人或某事的强烈不喜欢或蔑视"}]},{"word":"prize","phonetic":"/praɪz/","meanings":[{"pos":"adjective","meaning":"珍贵的；重要的；获奖的","usage":"形容特别珍贵或被珍视的东西，如prize plants获奖植物"}]},{"word":"stroll","phonetic":"/strəʊl/","meanings":[{"pos":"noun/verb","meaning":"漫步；闲逛；溜达","usage":"指轻松悠闲地散步"}]},{"word":"impulse","phonetic":"/ˈɪmpʌls/","meanings":[{"pos":"noun","meaning":"冲动；一时兴起；刺激","usage":"指突然产生的强烈欲望或想法，如on impulse一时冲动"}]},{"word":"dismay","phonetic":"/dɪsˈmeɪ/","meanings":[{"pos":"noun","meaning":"惊愕；沮丧；灰心","usage":"指因意外或失望而产生的震惊和沮丧感"}]},{"word":"possession","phonetic":"/pəˈzeʃən/","meanings":[{"pos":"noun","meaning":"拥有；占有；财产","usage":"指拥有或控制某物，take possession of表示接管、占领"}]},{"word":"luxury","phonetic":"/ˈlʌkʃəri/","meanings":[{"pos":"noun","meaning":"奢侈；豪华；奢侈品","usage":"指昂贵的享受或物品，a great luxury表示非常奢侈的享受"}]},{"word":"associate","phonetic":"/əˈsəʊʃieɪt/","meanings":[{"pos":"verb","meaning":"联系；联想；交往","usage":"指把不同事物联系在一起，associate A with B把A和B联系起来"}]},{"word":"escape","phonetic":"/ɪˈskeɪp/","meanings":[{"pos":"verb","meaning":"逃跑；逃脱；逃离","usage":"指从某处逃出来，或避免受到伤害"}]},{"word":"reluctantly","phonetic":"/rɪˈlʌktəntli/","meanings":[{"pos":"adverb","meaning":"不情愿地；勉强地","usage":"描述做某事时内心不愿意但又不得不做的状态"}]}],"phrases":[{"phrase":"One man's meat is another man's poison","usage":"谚语，意思是甲之蜜糖，乙之砒霜。指不同的人对同一种事物有不同的喜好或评价","examples":[{"en":"One man's meat is another man's poison - some people love coffee but others find it terrible.","zh":"萝卜青菜各有所爱——有人爱咖啡，有人却觉得它很糟糕。"}]},{"phrase":"stick to","usage":"坚持；坚守；维持原状。指坚持做某事或坚持某种习惯","examples":[{"en":"We stick to our original plan despite the difficulties.","zh":"尽管有困难，我们仍然坚持原计划。"},{"en":"Most people stick to the foods they grew up with.","zh":"大多数人都坚持吃他们从小吃到大的食物。"}]},{"phrase":"appeal to","usage":"吸引；使感兴趣。指某事物引起某人的兴趣或好感","examples":[{"en":"The idea never appealed to me very much.","zh":"这个想法从来没有真正吸引过我。"},{"en":"Does this job appeal to you?","zh":"这份工作吸引你吗？"}]},{"phrase":"on (a sudden) impulse","usage":"凭（一时）冲动。指突然产生的强烈欲望或想法驱使的行动","examples":[{"en":"Acting on a sudden impulse, I collected several dozen snails.","zh":"一时冲动之下，我抓了几十只蜗牛。"},{"en":"She bought the dress on impulse.","zh":"她一时冲动买下了那条裙子。"}]},{"phrase":"take possession of","usage":"拥有；接管；占领。指开始控制或占据某物","examples":[{"en":"The snails had taken complete possession of the hall!","zh":"蜗牛已经完全占领了门厅！"},{"en":"The company took possession of the new building last month.","zh":"公司上个月接管了那栋新楼。"}]},{"phrase":"be delighted to","usage":"高兴做某事；对某事感到高兴。表达对某事的愉悦感受","examples":[{"en":"Robert was delighted to see me and equally pleased with my little gift.","zh":"罗伯特见到我很高兴，对我的小礼物也很满意。"}]},{"phrase":"turn at","usage":"对...感到恶心/反胃。指对某种想法或气味感到厌恶","examples":[{"en":"Your stomach would turn at the idea of frying potatoes in animal fat.","zh":"一想到用动物油炸土豆，你就会感到恶心。"}]},{"phrase":"bring up","usage":"抚养；培养；养大。指在成长过程中被照顾和教育","examples":[{"en":"Most of us have been brought up to eat certain foods.","zh":"我们大多数人在成长过程中都被培养吃某些特定的食物。"}]},{"phrase":"a heavy shower","usage":"一阵大雨；倾盆大雨。指短时间内的大降雨","examples":[{"en":"One day, after a heavy shower, I noticed a huge number of snails.","zh":"有一天，一阵大雨过后，我注意到大量的蜗牛。"}]},{"phrase":"ever since","usage":"自从；从那以后一直。指从过去的某个时间点一直持续到现在","examples":[{"en":"There are countless people who, ever since their early years, have learned to associate snails with food.","zh":"有无数人从童年时代起就学会把蜗牛和食物联系起来。"}]}],"grammar":[{"title":"过去进行时 (Past Continuous Tense)","definition":"过去进行时表示在过去某一时刻或某一段时间正在进行的动作。","structure":"主语 + was/were + 动词-ing","usage":"用于描述在过去某个特定时刻正在发生的动作，或与另一个过去动作形成对比。本课中'I happened to be walking in my garden when I noticed...'描述了作者在大雨中正在花园里散步时看到了蜗牛。","examples":[{"en":"I happened to be walking in my garden when I noticed a huge number of snails.","zh":"我碰巧在花园里散步时注意到大量的蜗牛。"},{"en":"I was reading a book when he called.","zh":"他打电话时我正在看书。"},{"en":"She was cooking dinner at 7 o'clock yesterday evening.","zh":"昨晚七点她正在做晚饭。"}]},{"title":"间接宾语和直接宾语 (Indirect and Direct Objects)","definition":"某些动词可以带两个宾语：间接宾语（通常指人）和直接宾语（通常指物）。间接宾语通常位于直接宾语之前，但如果间接宾语放在后面，需要用介词to或for。","structure":"主语 + 动词 + 间接宾语 + 直接宾语 或 主语 + 动词 + 直接宾语 + to/for + 间接宾语","usage":"本课中'...I collected several dozen, put them in a paper bag, and took them to Robert.'展示了带两个宾语的用法。本课的被动语态结构也涉及宾语转换。","examples":[{"en":"I took them to Robert. (= I took Robert them.)","zh":"我把它们带给了罗伯特。"},{"en":"She bought me a gift. (= She bought a gift for me.)","zh":"她给我买了一份礼物。"},{"en":"Could you pass me the salt?","zh":"你能把盐递给我吗？"}]},{"title":"时间状语从句 (Adverbial Clause of Time)","definition":"时间状语从句用来说明动作发生的时间，由从属连词如when, while, after, before, as soon as等引导。","structure":"主句 + when/while/after/before + 从句","usage":"本课中多次使用时间状语从句，如'...when I noticed...', '...when Robert suddenly said...'等。when表示具体的时间点，while表示时间段。","examples":[{"en":"I was walking in my garden when I noticed a huge number of snails.","zh":"我在花园里散步时，注意到大量的蜗牛。"},{"en":"Robert and I went into the living room where we talked for a couple of hours.","zh":"我和罗伯特走进客厅，在那里谈了两个小时。"},{"en":"I had forgotten all about the snails when Robert suddenly said that I must stay to dinner.","zh":"我已经完全忘了蜗牛这件事，这时罗伯特突然说我必须留下来吃晚饭。"}]}],"patterns":[{"pattern":"No + 名词 + has received more...than...","explanation":"","original":{"en":"No creature has received more praise and abuse than the common garden snail.","zh":"没有任何生物受到的赞扬和批评比得上普通的花园蜗牛。"},"examples":[{"en":"No movie has received more praise and criticism than Titanic.","zh":"没有任何电影受到的赞扬和批评比得上《泰坦尼克号》。"},{"en":"No sport has received more attention than football in this country.","zh":"在这个国家，没有任何运动受到的关注比得上足球。"}]},{"pattern":"There are countless people who...","explanation":"","original":{"en":"There are countless people who, ever since their early years, have learned to associate snails with food.","zh":"有无数人从童年时代起就学会把蜗牛和食物联系起来。"},"examples":[{"en":"There are countless people who have learned to associate tea with relaxation.","zh":"有无数人学会把茶和放松联系起来。"},{"en":"There are countless people who, ever since their college days, have been working in this field.","zh":"有无数人从大学时代起就一直在这个领域工作。"}]},{"pattern":"主语 + happened to be + doing + when...","explanation":"","original":{"en":"I happened to be walking in my garden when I noticed a huge number of snails.","zh":"我碰巧在花园里散步时注意到大量的蜗牛。"},"examples":[{"en":"She happened to be reading a book when the earthquake happened.","zh":"地震发生时她碰巧在看书。"},{"en":"I happened to be cooking dinner when the guests arrived.","zh":"客人到达时我碰巧在做晚饭。"}]},{"pattern":"主语 + be delighted to + 动词原形","explanation":"","original":{"en":"Robert was delighted to see me and equally pleased with my little gift.","zh":"罗伯特见到我很高兴，对我的小礼物也很满意。"},"examples":[{"en":"My mother was delighted to hear the good news.","zh":"我妈妈听到这个好消息很高兴。"},{"en":"The children were delighted to receive the presents.","zh":"孩子们收到礼物很高兴。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“不情愿地；勉强地” 对应的单词是？","hint":"adverb · /rɪˈlʌktəntli/","options":["devise","reluctantly","submerge","manual"],"answer":1,"explain":"reluctantly · /rɪˈlʌktəntli/ · adverb · 不情愿地；勉强地。描述做某事时内心不愿意但又不得不做的状态","source":{"kind":"vocab","word":"reluctantly"},"id":"b3-u23-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：美味；佳肴；珍品","hint":"/ˈdelɪkəsi/ · noun","answer":"delicacy","placeholder":"输入英文单词","explain":"delicacy · /ˈdelɪkəsi/ · noun · 美味；佳肴；珍品。指特别美味或珍贵的食物","source":{"kind":"vocab","word":"delicacy"},"id":"b3-u23-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：One day, after _____, I noticed a huge number of snails.","hint":"有一天，一阵大雨过后，我注意到大量的蜗牛。","answer":"a heavy shower","placeholder":"输入缺失的短语","explain":"a heavy shower：一阵大雨；倾盆大雨。指短时间内的大降雨（有一天，一阵大雨过后，我注意到大量的蜗牛。）","source":{"kind":"phrase","phrase":"a heavy shower"},"id":"b3-u23-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：and had taken complete possession of the hall! I have never been able to look at a snail _____ then.","hint":"并且完全占据了门厅！从那时起，我再也无法正眼看蜗牛了。","answer":"since","placeholder":"输入缺失的单词","explain":"and had taken complete possession of the hall! I have never been able to look at a snail since then. — 并且完全占据了门厅！从那时起，我再也无法正眼看蜗牛了。","source":{"kind":"sentence","en":"and had taken complete possession of the hall! I have never been able to look at a snail since then."},"id":"b3-u23-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于描述在过去某个特定时刻正在发生的动作，或与另一个过去动作形成对比。本课中'I happened to be walking in my garden when I noticed...'描述了作者在大雨中正在花园里散步时看到了蜗牛。” 描述的是哪个语法点？","hint":"主语 + was/were + 动词-ing","options":["过去进行时 (Past Continuous Tense)","过去完成进行时","双关语 (Pun)","定语从句中的“介词+which”结构"],"answer":0,"explain":"过去进行时 (Past Continuous Tense)：主语 + was/were + 动词-ing：用于描述在过去某个特定时刻正在发生的动作，或与另一个过去动作形成对比。本课中'I happened to be walking in my garden when I noticed...'描述了作者在大雨中正在花园里散步时看到了蜗牛。","source":{"kind":"grammar","title":"过去进行时 (Past Continuous Tense)"},"id":"b3-u23-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nI did not fancy the idea and I reluctantly followed Robert out of the room.","hint":"","options":["我不喜欢这个主意，我只好不情愿地跟着罗伯特离开了房间。","房屋——通常有三层楼高——是用石头建造的。","那个官员拧开瓶盖，把瓶子凑到鼻孔前。","船上有一个船夫，睡得很熟。"],"answer":0,"explain":"I did not fancy the idea and I reluctantly followed Robert out of the room. — 我不喜欢这个主意，我只好不情愿地跟着罗伯特离开了房间。","source":{"kind":"sentence","en":"I did not fancy the idea and I reluctantly followed Robert out of the room."},"id":"b3-u23-q06"}]},{"id":"b3-u24","book":3,"unit":24,"key":"24","lessonFrom":24,"lessonTo":24,"title":"A Skeleton in the Cupboard","titleZh":"橱柜里的骷髅","question":"Who was Sebastian?","sentences":[{"en":"We often read in novels how a seemingly respectable person","zh":"我们经常在小说中读到，一个看似体面的人","t":11.87},{"en":"or family has some terrible secret which has been concealed from strangers for years.","zh":"或家庭隐藏着某个可怕的秘密，多年来一直对陌生人保密。","t":17.06},{"en":"The English language possesses a vivid saying to describe this sort of situation.","zh":"英语中有一个生动的说法来描述这种情况。","t":24.73},{"en":"The terrible secret is called 'a skeleton in the cupboard'.","zh":"这个可怕的秘密被称为“橱柜里的骷髅”。","t":30.61},{"en":"At some dramatic moment in the story, the terrible secret becomes known and a reputation is ruined.","zh":"在故事的某个戏剧性时刻，这个可怕的秘密公诸于世，声誉也随之毁掉。","t":35.69},{"en":"The reader's hair stands on end when he reads in the final pages of the novel that the heroine,","zh":"当读者在小说的最后几页读到女主人公——","t":43.08},{"en":"a dear old lady who had always been so kind to everybody, had, in her youth, poisoned every one of her five husbands.","zh":"一位一直对每个人都非常和蔼可亲的老太太，在年轻时毒死了她的五个丈夫时，会毛骨悚然。","t":49.34},{"en":"It is all very well for such things to occur in fiction.","zh":"这种事情发生在小说里是完全可以的。","t":59.79},{"en":"To varying degrees, we all have secrets which we do not want even our closest friends to learn,","zh":"在不同程度上，我们都有一些甚至不想让最亲密的朋友知道的秘密，","t":64.47},{"en":"but few of us have skeletons in the cupboard.","zh":"但我们中很少有人有“橱柜里的骷髅”。","t":71.76},{"en":"The only person I know who has a skeleton in the cupboard is George Carlton, and he is very proud of the fact.","zh":"我认识的唯一一个有“橱柜里的骷髅”的人是乔治·卡尔顿，他对此引以为豪。","t":75.5},{"en":"George studied medicine in his youth.","zh":"乔治年轻时学医。","t":83.87},{"en":"Instead of becoming a doctor, however, he became a successful writer of detective stories.","zh":"然而，他没有成为一名医生，而是成为了一名成功的侦探小说作家。","t":86.67},{"en":"I once spent an uncomfortable weekend which I shall never forget at his house.","zh":"我有一次在他家度过了一个令我永生难忘的不舒服的周末。","t":93.77},{"en":"George showed me to the guestroom which, he said, was rarely used.","zh":"乔治把我带到客房，他说那个房间很少用。","t":99.38},{"en":"He told me to unpack my things and then come down to dinner.","zh":"他让我把行李打开，然后下来吃饭。","t":104.02},{"en":"After I had stacked my shirts and underclothes in two empty drawers, I decided to hang one of the two suits I had brought with me in the cupboard.","zh":"我把衬衫和内衣叠放在两个空抽屉里后，决定把我带来的两套西装中的一套挂在橱柜里。","t":108.33},{"en":"I opened the cupboard door and then stood in front of it petrified.","zh":"我打开橱柜门，然后僵在原地，吓呆了。","t":118.38},{"en":"A skeleton was dangling before my eyes.","zh":"一个骷髅在我眼前晃动。","t":123.32},{"en":"The sudden movement of the door made it sway slightly and it gave me the impression that it was about to leap out at me.","zh":"门的突然移动使它轻轻摇晃，给我一种它要向我扑过来的感觉。","t":127.06},{"en":"Dropping my suit, I dashed downstairs to tell George.","zh":"我扔下西装，冲下楼去告诉乔治。","t":135.32},{"en":"This was worse than 'a terrible secret'; this was a real skeleton!","zh":"这比“可怕的秘密”更糟糕；这是一个真正的骷髅！","t":140.4},{"en":"But George was unsympathetic.","zh":"但乔治无动于衷。","t":145.85},{"en":"'Oh, that,' he said with a smile as if he were talking about an old friend.","zh":"“哦，那个啊，”他微笑着说，好像在谈论一位老朋友。","t":148.42},{"en":"'That's Sebastian. You forget that I was a medical student once upon a time.'","zh":"“那是塞巴斯蒂安。你忘了我以前也是个医学院的学生。”","t":154.56}],"vocab":[{"word":"skeleton","phonetic":"/ˈskelɪtn/","meanings":[{"pos":"noun","meaning":"骨骼；骷髅","usage":"指人或动物的骨骼框架，也可引申为不可告人的秘密"}]},{"word":"respectable","phonetic":"/rɪˈspektəbl/","meanings":[{"pos":"adjective","meaning":"值得尊敬的；体面的","usage":"用来描述人或家庭品行端正、符合社会道德标准"}]},{"word":"conceal","phonetic":"/kənˈsiːl/","meanings":[{"pos":"verb","meaning":"隐藏；隐瞒","usage":"及物动词，宾语可以是具体物品或抽象的信息、情绪等"}]},{"word":"vivid","phonetic":"/ˈvɪvɪd/","meanings":[{"pos":"adjective","meaning":"生动的；逼真的","usage":"常用来修饰描述、表达、记忆等，强调形象清晰鲜明"}]},{"word":"dramatic","phonetic":"/drəˈmætɪk/","meanings":[{"pos":"adjective","meaning":"戏剧性的；激动人心的","usage":"多用于描述事件、场景充满戏剧张力，有突然或惊人的效果"}]},{"word":"reputation","phonetic":"/ˌrepjuˈteɪʃn/","meanings":[{"pos":"noun","meaning":"名声；声誉","usage":"指公众对某人/机构的评价，常见搭配ruin/damage one's reputation"}]},{"word":"heroine","phonetic":"/ˈherəʊɪn/","meanings":[{"pos":"noun","meaning":"女主人公；女英雄","usage":"对应阳性形式hero，指故事、小说中的女主角或杰出女性"}]},{"word":"poison","phonetic":"/ˈpɔɪzn/","meanings":[{"pos":"verb","meaning":"下毒；毒死","usage":"作及物动词时直接接被毒害的对象；也可作名词表示“毒药”"}]},{"word":"fiction","phonetic":"/ˈfɪkʃn/","meanings":[{"pos":"noun","meaning":"小说；虚构的事","usage":"区别于非虚构作品（non-fiction），也可指不真实的事情"}]},{"word":"stack","phonetic":"/stæk/","meanings":[{"pos":"verb","meaning":"堆放；摞起","usage":"指将物品整齐堆叠，也可作名词表示“一堆（物品）”"}]},{"word":"petrified","phonetic":"/ˈpetrɪfaɪd/","meanings":[{"pos":"adjective","meaning":"惊呆的；吓僵的","usage":"形容人因极度恐惧而无法动弹的状态"}]},{"word":"dangle","phonetic":"/ˈdæŋɡl/","meanings":[{"pos":"verb","meaning":"悬挂；晃荡","usage":"指物体悬垂着来回摆动"}]},{"word":"sway","phonetic":"/sweɪ/","meanings":[{"pos":"verb","meaning":"摇晃；摆动","usage":"可指物体缓慢摇摆，也可引申为“影响、说服某人”"}]},{"word":"leap","phonetic":"/liːp/","meanings":[{"pos":"verb","meaning":"跳；跃","usage":"强调动作幅度大且突然，常见搭配leap out at sb"}]},{"word":"unsympathetic","phonetic":"/ˌʌnˌsɪmpəˈθetɪk/","meanings":[{"pos":"adjective","meaning":"无同情心的；冷漠的","usage":"sympathetic的反义词，指对他人的遭遇没有共情"}]}],"phrases":[{"phrase":"a skeleton in the cupboard","usage":"固定习语，指家庭或个人不愿公开的丑事、家丑","examples":[{"en":"After the politician resigned, the public found he had many skeletons in the cupboard.","zh":"这位政客辞职后，公众发现他有很多不可告人的丑事。"}]},{"phrase":"to varying degrees","usage":"表示“在不同程度上”，用于说明事物的程度差异","examples":[{"en":"Students in this class are to varying degrees interested in art.","zh":"这个班的学生对艺术的兴趣程度各不相同。"}]},{"phrase":"be proud of","usage":"表示“为……感到骄傲/得意”，后接名词、代词或动名词","examples":[{"en":"She is very proud of her daughter's performance in the competition.","zh":"她为女儿在比赛中的表现感到非常骄傲。"}]},{"phrase":"once upon a time","usage":"常用于故事开头，表示“从前；曾经”，也可口语中提及过去的经历","examples":[{"en":"Once upon a time, there lived an old fisherman by the sea.","zh":"从前，海边住着一位老渔夫。"}]},{"phrase":"show sb to","usage":"表示“带领某人到（某地）”，常用于接待客人的场景","examples":[{"en":"The waiter showed us to our table near the window.","zh":"服务员把我们领到了靠窗的桌子旁。"}]},{"phrase":"stand on end","usage":"(毛发) 竖立，通常用来形容人非常恐惧、震惊","examples":[{"en":"The horror movie was so scary that it made my hair stand on end.","zh":"这部恐怖电影太吓人了，吓得我汗毛都竖起来了。"}]},{"phrase":"be about to do","usage":"表示“即将做某事；正要做某事”，强调动作马上就要发生","examples":[{"en":"I was about to go out when the phone rang.","zh":"我正要出门，电话响了。"}]},{"phrase":"dash to","usage":"表示“冲向；猛奔到某地”，强调动作的急促","examples":[{"en":"When the bell rang, he dashed to the classroom.","zh":"铃声一响，他就冲向了教室。"}]}],"grammar":[{"title":"定语从句","definition":"在复合句中修饰名词或代词的从句，被修饰的词叫先行词，从句由关系代词或关系副词引导","structure":"先行词 + 关系代词/副词 + 从句其余部分","usage":"用来对先行词进行补充说明，若从句是限定性的则无需逗号分隔，非限定性的需用逗号和主句隔开","examples":[{"en":"The only person I know who has a skeleton in the cupboard is George Carlton.","zh":"我认识的人中唯一有“家丑”的是乔治·卡尔顿。"},{"en":"The old lady who had always been so kind to everybody poisoned her husbands.","zh":"那位一直对所有人都很和善的老妇人毒死了她的丈夫们。"}]},{"title":"as if 引导的方式状语从句","definition":"用来引导表示“好像、似乎”的从句，描述动作的方式，可接真实情况或虚拟情况","structure":"主句 + as if + 从句","usage":"当描述的内容是非真实的、与事实相反的情况时，从句要用虚拟语气；若表示可能真实的情况则用陈述语气","examples":[{"en":"He said with a smile as if he were talking about an old friend.","zh":"他笑着说，好像在谈论一位老朋友似的。"},{"en":"It looks as if it is going to rain soon.","zh":"看起来好像马上就要下雨了。"}]}],"patterns":[{"pattern":"It is all very well for sth to occur...","explanation":"","original":{"en":"It is all very well for such things to occur in fiction.","zh":"这种事发生在小说里是无可厚非的。"},"examples":[{"en":"It is all very well for jokes to appear in comedy shows.","zh":"这种笑话出现在喜剧节目里是无可厚非的。"},{"en":"It is all very well for kids to make small mistakes.","zh":"小孩子犯点小错是很正常的。"}]},{"pattern":"The only person I know who... is...","explanation":"","original":{"en":"The only person I know who has a skeleton in the cupboard is George Carlton.","zh":"我认识的人中唯一有“家丑”的是乔治·卡尔顿。"},"examples":[{"en":"The only person I know who can play the violin well is my deskmate.","zh":"我认识的人里唯一小提琴拉得好的是我的同桌。"},{"en":"The only restaurant I know which serves authentic Sichuan food is near the station.","zh":"我知道的唯一一家做正宗川菜的餐馆在车站附近。"}]},{"pattern":"It gave me the impression that...","explanation":"","original":{"en":"It gave me the impression that it was about to leap out at me.","zh":"它给我的感觉是好像就要扑到我身上来了。"},"examples":[{"en":"His polite words gave me the impression that he was a very well-educated person.","zh":"他礼貌的话语给我的印象是他是个很有教养的人。"},{"en":"The quiet town gave me the impression that time had slowed down here.","zh":"这个安静的小镇给我的感觉是时间在这里都变慢了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“生动的；逼真的” 对应的单词是？","hint":"adjective · /ˈvɪvɪd/","options":["vivid","predecessor","drainage","costume"],"answer":0,"explain":"vivid · /ˈvɪvɪd/ · adjective · 生动的；逼真的。常用来修饰描述、表达、记忆等，强调形象清晰鲜明","source":{"kind":"vocab","word":"vivid"},"id":"b3-u24-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：戏剧性的；激动人心的","hint":"/drəˈmætɪk/ · adjective","answer":"dramatic","placeholder":"输入英文单词","explain":"dramatic · /drəˈmætɪk/ · adjective · 戏剧性的；激动人心的。多用于描述事件、场景充满戏剧张力，有突然或惊人的效果","source":{"kind":"vocab","word":"dramatic"},"id":"b3-u24-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Students in this class are _____ interested in art.","hint":"这个班的学生对艺术的兴趣程度各不相同。","answer":"to varying degrees","placeholder":"输入缺失的短语","explain":"to varying degrees：表示“在不同程度上”，用于说明事物的程度差异（这个班的学生对艺术的兴趣程度各不相同。）","source":{"kind":"phrase","phrase":"to varying degrees"},"id":"b3-u24-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：I once spent an uncomfortable weekend which I shall never forget at his _____","hint":"我有一次在他家度过了一个令我永生难忘的不舒服的周末。","answer":"house","placeholder":"输入缺失的单词","explain":"I once spent an uncomfortable weekend which I shall never forget at his house. — 我有一次在他家度过了一个令我永生难忘的不舒服的周末。","source":{"kind":"sentence","en":"I once spent an uncomfortable weekend which I shall never forget at his house."},"id":"b3-u24-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“在复合句中修饰名词或代词的从句，被修饰的词叫先行词，从句由关系代词或关系副词引导” 描述的是哪个语法点？","hint":"先行词 + 关系代词/副词 + 从句其余部分","options":["Not only...but (also) 引起的倒装句","定语从句","定语从句中的“介词+which”结构","more than + n./adj. (不仅仅；超出)"],"answer":1,"explain":"定语从句：先行词 + 关系代词/副词 + 从句其余部分：用来对先行词进行补充说明，若从句是限定性的则无需逗号分隔，非限定性的需用逗号和主句隔开","source":{"kind":"grammar","title":"定语从句"},"id":"b3-u24-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nI opened the cupboard door and then stood in front of it petrified.","hint":"","options":["下面这个“病态幽默”的例子能让你自己评判。","我打开橱柜门，然后僵在原地，吓呆了。","在20世纪80年代初，电脑巨头IBM生产了世界上第一台个人电脑。","现代雕塑已很少令我们感到惊奇了。"],"answer":1,"explain":"I opened the cupboard door and then stood in front of it petrified. — 我打开橱柜门，然后僵在原地，吓呆了。","source":{"kind":"sentence","en":"I opened the cupboard door and then stood in front of it petrified."},"id":"b3-u24-q06"}]},{"id":"b3-u25","book":3,"unit":25,"key":"25","lessonFrom":25,"lessonTo":25,"title":"The Cutty Sark","titleZh":"卡蒂萨克号","question":"What piece of bad luck prevented the Cutty Sark from winning the race?","sentences":[{"en":"One of the most famous sailing ships of the nineteenth century, the Cutty Sark, can still be seen at Greenwich.","zh":"19世纪最著名的帆船之一，“卡蒂萨克”号至今仍可在格林威治见到。","t":16.14},{"en":"She stands on dry land and is visited by thousands of people each year.","zh":"她停泊在陆地上，每年都有成千上万的人参观。","t":24.39},{"en":"She serves as an impressive reminder of the great ships of the past.","zh":"她作为对过去伟大船只的深刻纪念。","t":30.28},{"en":"Before they were replaced by steamships,","zh":"在它们被蒸汽船取代之前，","t":36.09},{"en":"sailing vessels like the Cutty Sark were used to carry tea from China and wool from Australia.","zh":"像卡蒂萨克号这样的帆船被用来从中国运茶，从澳大利亚运羊毛。","t":39.07},{"en":"The Cutty Sark was one of the fastest sailing ships that has ever been built.","zh":"卡蒂萨克号是建造过的最快的帆船之一。","t":47.25},{"en":"The only other ship to match her was the Thermopylae.","zh":"唯一能与她匹敌的船是“特莫皮莱”号。","t":53.22},{"en":"Both these ships set out from Shanghai on June 18th, 1872 on an exciting race to England.","zh":"这两艘船于1872年6月18日从上海启程，进行一场激动人心的英国竞赛。","t":58.15},{"en":"This race, which went on for exactly four months, was the last of its kind.","zh":"这场持续了整整四个月的比赛是同类比赛中的最后一场。","t":67.82},{"en":"It marked the end of the great tradition of ships with sails and the beginning of a new era.","zh":"它标志着帆船伟大传统的结束和新时代的开始。","t":74.61},{"en":"The first of the two ships to reach Java after the race had begun was the Thermopylae,","zh":"比赛开始后，两艘船中最先抵达爪哇的是“特莫皮莱”号，","t":82.51},{"en":"but on the Indian Ocean, the Cutty Sark took the lead.","zh":"但在印度洋上，“卡蒂萨克”号取得了领先。","t":89.6},{"en":"It seemed certain that she would be the first ship home,","zh":"似乎她肯定会是第一艘抵达的船，","t":93.88},{"en":"but during the race she had a lot of bad luck.","zh":"但在比赛中她遭遇了很多厄运。","t":97.67},{"en":"In August, she was struck by a very heavy storm during which her rudder was torn away.","zh":"八月，她遭遇了一场特大风暴，船舵被刮走了。","t":101.86},{"en":"The Cutty Sark rolled from side to side and it became impossible to steer her.","zh":"卡蒂萨克号左右摇晃，无法掌舵。","t":109.43},{"en":"A temporary rudder was made on board from spare planks and it was fitted with great difficulty.","zh":"船上用备用木板做了一个临时船舵，并费了很大力气才安装好。","t":115.93},{"en":"This greatly reduced the speed of the ship, for there was a danger that if she travelled too quickly,","zh":"这大大降低了船速，因为存在一个危险，如果她航行过快，","t":123.64},{"en":"this rudder would be torn away as well.","zh":"这个船舵也会被刮走。","t":130.86},{"en":"Because of this, the Cutty Sark lost her lead.","zh":"因此，卡蒂萨克号失去了领先地位。","t":134.6},{"en":"After crossing the Equator, the captain called in at a port to have a new rudder fitted,","zh":"越过赤道后，船长在一个港口停靠，安装了一个新船舵，","t":138.74},{"en":"but by now the Thermopylae was over five hundred miles ahead.","zh":"但此时“特莫皮莱”号已经领先五百多英里了。","t":145.65},{"en":"Though the new rudder was fitted at tremendous speed, it was impossible for the Cutty Sark to win.","zh":"尽管新船舵以惊人的速度安装好了，卡蒂萨克号还是不可能赢得比赛。","t":150.98},{"en":"She arrived in England a week after the Thermopylae.","zh":"她在“特莫皮莱”号之后一周抵达英国。","t":159.18},{"en":"Even this was remarkable, considering that she had had so many delays.","zh":"考虑到她有如此多的延误，即使这样也值得称赞。","t":163.39},{"en":"There is no doubt that if she had not lost her rudder she would have won the race easily.","zh":"毫无疑问，如果她没有失去船舵，她会轻易赢得比赛。","t":169.29}],"vocab":[{"word":"sailing","phonetic":"/ˈseɪlɪŋ/","meanings":[{"pos":"noun","meaning":"航海；帆船运动","usage":"指利用风力推动船只行驶的活动或方式"},{"pos":"adj","meaning":"帆船的；航行的","usage":"修饰名词，如sailing ship帆船"}]},{"word":"vessel","phonetic":"/ˈvesl/","meanings":[{"pos":"noun","meaning":"船；舰","usage":"正式用语，指大型船只或容器"}]},{"word":"impressive","phonetic":"/ɪmˈpresɪv/","meanings":[{"pos":"adj","meaning":"令人印象深刻的","usage":"描述给人留下深刻印象的事物"}]},{"word":"reminder","phonetic":"/rɪˈmaɪndə(r)/","meanings":[{"pos":"noun","meaning":"提醒物；提示","usage":"使某人想起某事的事物"}]},{"word":"tradition","phonetic":"/trəˈdɪʃn/","meanings":[{"pos":"noun","meaning":"传统；惯例","usage":"指代代相传的风俗或习惯"}]},{"word":"era","phonetic":"/ˈɪərə/","meanings":[{"pos":"noun","meaning":"时代；纪元","usage":"指历史上具有特征的时期"}]},{"word":"match","phonetic":"/mætʃ/","meanings":[{"pos":"verb","meaning":"比得上；相配","usage":"表示在质量或能力上相当"}]},{"word":"steer","phonetic":"/stɪə(r)/","meanings":[{"pos":"verb","meaning":"驾驶；掌舵","usage":"指控制船只或车辆的方向"}]},{"word":"rudder","phonetic":"/ˈrʌdə(r)/","meanings":[{"pos":"noun","meaning":"舵；船舵","usage":"船上用于控制方向的装置"}]},{"word":"tremendous","phonetic":"/trəˈmendəs/","meanings":[{"pos":"adj","meaning":"巨大的；极大的","usage":"强调规模或程度非常大"}]},{"word":"delay","phonetic":"/dɪˈleɪ/","meanings":[{"pos":"noun/verb","meaning":"延误；耽搁","usage":"指事情被推迟或延误的状态"}]},{"word":"remarkable","phonetic":"/rɪˈmɑːkəbl/","meanings":[{"pos":"adj","meaning":"非凡的；卓越的","usage":"指值得注意的、不寻常的"}]},{"word":"storm","phonetic":"/stɔːm/","meanings":[{"pos":"noun","meaning":"暴风雨；风暴","usage":"指恶劣的天气状况"}]},{"word":"plank","phonetic":"/plæŋk/","meanings":[{"pos":"noun","meaning":"木板；板条","usage":"指长而薄的木料"}]},{"word":"Equator","phonetic":"/ɪˈkweɪtə(r)/","meanings":[{"pos":"noun","meaning":"赤道","usage":"地球南北之间的假想线"}]}],"phrases":[{"phrase":"set out","usage":"出发；启程，指开始一段旅程","examples":[{"en":"Both ships set out from Shanghai on June 18th, 1872.","zh":"两艘船于1872年6月18日从上海出发。"}]},{"phrase":"take the lead","usage":"取得领先地位","examples":[{"en":"On the Indian Ocean, the Cutty Sark took the lead.","zh":"在印度洋上，卡蒂萨克号取得了领先。"}]},{"phrase":"be struck by","usage":"被击中；遭受，指突然遭遇不好的事情","examples":[{"en":"In August, she was struck by a very heavy storm.","zh":"八月，她遭遇了一场猛烈的暴风雨。"}]},{"phrase":"lose one's lead","usage":"失去领先地位","examples":[{"en":"Because of this, the Cutty Sark lost her lead.","zh":"因此，卡蒂萨克号失去了领先地位。"}]},{"phrase":"call in at","usage":"（船等）停靠，指在某个港口停留","examples":[{"en":"The captain called in at a port to have a new rudder fitted.","zh":"船长将船停靠在一个港口，让工人安装新舵。"}]},{"phrase":"roll from side to side","usage":"左右摇晃，形容船只不稳地晃动","examples":[{"en":"The Cutty Sark rolled from side to side and it became impossible to steer her.","zh":"卡蒂萨克号左右摇晃，变得无法操控。"}]},{"phrase":"fit with difficulty","usage":"困难地安装，形容做某事很艰难","examples":[{"en":"A temporary rudder was made and it was fitted with great difficulty.","zh":"一个临时舵被制造出来，但安装得非常困难。"}]},{"phrase":"There is no doubt that...","usage":"毫无疑问...，用于强调确信某事","examples":[{"en":"There is no doubt that if she had not lost her rudder she would have won the race easily.","zh":"毫无疑问，如果她没有失去舵，她会轻松赢得比赛。"}]},{"phrase":"lose one's rudder","usage":"失去舵，船只失去控制","examples":[{"en":"Her rudder was torn away.","zh":"她的舵被撕裂了。"}]},{"phrase":"be replaced by","usage":"被...取代","examples":[{"en":"Before they were replaced by steamships, sailing vessels were used to carry tea.","zh":"在被汽船取代之前，帆船被用来运茶。"}]}],"grammar":[{"title":"过去完成时 (Past Perfect Tense)","definition":"表示在过去某个时间点之前已经完成的动作或状态，常与一般过去时连用","structure":"had + 过去分词","usage":"用于描述发生在过去之前的事件，常用于复合句中","examples":[{"en":"The first of the two ships to reach Java after the race had begun was the Thermopylae.","zh":"比赛开始后，第一艘到达爪哇的船是Thermopylae号。"},{"en":"She had had many delays before arriving in England.","zh":"她在到达英国之前经历了许多延误。"}]},{"title":"虚拟语气 (Subjunctive Mood) - 与过去事实相反","definition":"用来表达与事实相反的假设或不可能发生的情况","structure":"if + 主语 + had + 过去分词, 主语 + would/could/might have + 过去分词","usage":"用于谈论与过去事实相反的假设","examples":[{"en":"If she had not lost her rudder, she would have won the race easily.","zh":"如果她没有失去舵，她本会轻松赢得比赛。"},{"en":"If it had not rained, we would have gone out.","zh":"如果没有下雨，我们本会出去。"}]},{"title":"过去分词作定语 (Past Participle as Adjective)","definition":"过去分词可用作形容词，修饰名词，表示被动或完成的意义","structure":"过去分词 + 名词 或 名词 + 过去分词","usage":"用于简化定语从句，使句子更简洁","examples":[{"en":"The only other ship to match her was the Thermopylae.","zh":"唯一能与她匹敌的另一艘船是Thermopylae号。"},{"en":"She serves as an impressive reminder of the great ships of the past.","zh":"她作为一个令人印象深刻的纪念物，提醒人们过去伟大的船只。"}]}],"patterns":[{"pattern":"It seemed certain that...","explanation":"","original":{"en":"It seemed certain that she would be the first ship home.","zh":"她似乎是第一个到达的船，这似乎是确定的。"},"examples":[{"en":"It seemed certain that he would pass the exam.","zh":"他似乎一定会通过考试。"},{"en":"It seemed certain that our team would win the match.","zh":"我们队似乎一定会赢得比赛。"}]},{"pattern":"There is no doubt that...","explanation":"","original":{"en":"There is no doubt that if she had not lost her rudder she would have won the race easily.","zh":"毫无疑问，如果她没有失去舵，她会轻松赢得比赛。"},"examples":[{"en":"There is no doubt that hard work leads to success.","zh":"毫无疑问，努力工作会带来成功。"},{"en":"There is no doubt that she is the best student in the class.","zh":"毫无疑问，她是班上最好的学生。"}]},{"pattern":"The only other...to do something was...","explanation":"","original":{"en":"The only other ship to match her was the Thermopylae.","zh":"唯一能与她匹敌的另一艘船是Thermopylae号。"},"examples":[{"en":"The only other student to finish the test early was Tom.","zh":"唯一另一个提前完成考试的学生是汤姆。"},{"en":"The only other country to win the championship three times was Brazil.","zh":"唯一另一个三次赢得冠军的国家是巴西。"}]},{"pattern":"Because of this, ...","explanation":"","original":{"en":"Because of this, the Cutty Sark lost her lead.","zh":"因此，卡蒂萨克号失去了领先地位。"},"examples":[{"en":"Because of this, he decided to change his major.","zh":"因此，他决定换专业。"},{"en":"Because of the heavy traffic, we arrived late.","zh":"因为交通拥堵，我们迟到了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“时代；纪元” 对应的单词是？","hint":"noun · /ˈɪərə/","options":["span","mysterious","era","backwater"],"answer":2,"explain":"era · /ˈɪərə/ · noun · 时代；纪元。指历史上具有特征的时期","source":{"kind":"vocab","word":"era"},"id":"b3-u25-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：延误；耽搁","hint":"/dɪˈleɪ/ · noun/verb","answer":"delay","placeholder":"输入英文单词","explain":"delay · /dɪˈleɪ/ · noun/verb · 延误；耽搁。指事情被推迟或延误的状态","source":{"kind":"vocab","word":"delay"},"id":"b3-u25-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Both ships _____ from Shanghai on June 18th, 1872.","hint":"两艘船于1872年6月18日从上海出发。","answer":"set out","placeholder":"输入缺失的短语","explain":"set out：出发；启程，指开始一段旅程（两艘船于1872年6月18日从上海出发。）","source":{"kind":"phrase","phrase":"set out"},"id":"b3-u25-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：She stands on dry land and is visited by thousands of _____ each year.","hint":"她停泊在陆地上，每年都有成千上万的人参观。","answer":"people","placeholder":"输入缺失的单词","explain":"She stands on dry land and is visited by thousands of people each year. — 她停泊在陆地上，每年都有成千上万的人参观。","source":{"kind":"sentence","en":"She stands on dry land and is visited by thousands of people each year."},"id":"b3-u25-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“过去分词可用作形容词，修饰名词，表示被动或完成的意义” 描述的是哪个语法点？","hint":"过去分词 + 名词 或 名词 + 过去分词","options":["并列结构中的省略","条件状语从句 (Conditional Clause)","过去分词作定语 (Past Participle as Adjective)","make it + 形容词 + for sb. to do sth."],"answer":2,"explain":"过去分词作定语 (Past Participle as Adjective)：过去分词 + 名词 或 名词 + 过去分词：用于简化定语从句，使句子更简洁","source":{"kind":"grammar","title":"过去分词作定语 (Past Participle as Adjective)"},"id":"b3-u25-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nbut on the Indian Ocean, the Cutty Sark took the lead.","hint":"","options":["我们向河流倾诉我们所有的秘密。","她扮演了三年完美仆人的角色，直到哈里特姑妈发现了她的“小缺点”。","但在印度洋上，“卡蒂萨克”号取得了领先。","她曾告诉他，如果她没有开门，他就直接进来，把面包放在厨房的桌子上。"],"answer":2,"explain":"but on the Indian Ocean, the Cutty Sark took the lead. — 但在印度洋上，“卡蒂萨克”号取得了领先。","source":{"kind":"sentence","en":"but on the Indian Ocean, the Cutty Sark took the lead."},"id":"b3-u25-q06"}]},{"id":"b3-u26","book":3,"unit":26,"key":"26","lessonFrom":26,"lessonTo":26,"title":"Wanted a Large Biscuit Tin","titleZh":"征集：一个大饼干盒","question":"Who won the prize for the biggest biscuit?","sentences":[{"en":"No one can avoid being influenced by advertisements.","zh":"没人能避免受到广告的影响。","t":15.29},{"en":"Much as we may pride ourselves on our good taste,","zh":"尽管我们可能为自己的好品味而自豪，","t":19.62},{"en":"we are no longer free to choose the things we want,","zh":"但我们不再能自由选择我们想要的东西，","t":23.32},{"en":"for advertising exerts a subtle influence on us.","zh":"因为广告对我们施加着微妙的影响。","t":26.61},{"en":"In their efforts to persuade us to buy this or that product,","zh":"为了说服我们购买这种或那种产品，","t":30.96},{"en":"advertisers have made a close study of human nature and have classified all our little weaknesses.","zh":"广告商们已经深入研究了人性，并对我们所有的小缺点进行了分类。","t":35.11},{"en":"Advertisers discovered years ago that all of us love to get something for nothing.","zh":"广告商多年前就发现，我们所有人都喜欢不劳而获。","t":43.15},{"en":"An advertisement which begins with the magic word FREE can rarely go wrong.","zh":"以“免费”这个神奇词语开头的广告很少会出错。","t":48.96},{"en":"These days, advertisers not only offer free samples,","zh":"如今，广告商不仅提供免费样品，","t":55.87},{"en":"but free cars, free houses, and free trips round the world as well.","zh":"还提供免费汽车、免费房屋，以及免费环球旅行。","t":59.82},{"en":"They devise hundreds of competitions which will enable us to win huge sums of money.","zh":"他们设计了数百种竞赛，使我们能够赢得巨额奖金。","t":66.8},{"en":"Radio and television have made it possible for advertisers to capture the attention of millions of people in this way.","zh":"无线电和电视使广告商能够通过这种方式吸引数百万人的注意力。","t":72.73},{"en":"During a radio programme, a company of biscuit manufacturers once asked listeners to bake biscuits and send them to their factory.","zh":"在一个广播节目中，一家饼干制造商曾要求听众烘烤饼干并寄到他们的工厂。","t":81.12},{"en":"They offered to pay $10 a pound for the biggest biscuit baked by a listener.","zh":"他们提出为听众烘烤的最大饼干支付每磅10美元。","t":91.29},{"en":"The response to this competition was tremendous.","zh":"这项竞赛的反响非常热烈。","t":97.09},{"en":"Before long, biscuits of all shapes and sizes began arriving at the factory.","zh":"不久，各种形状和大小的饼干开始运抵工厂。","t":100.86},{"en":"One lady brought a biscuit on a wheelbarrow. It weighed nearly 500 pounds.","zh":"一位女士用独轮手推车运来一块饼干。它重近500磅。","t":107.05},{"en":"A little later, a man came along with a biscuit which occupied the whole boot of his car.","zh":"稍后，一位男士带来一块饼干，它占满了他的汽车后备箱。","t":113.41},{"en":"All the biscuits that were sent were carefully weighed.","zh":"所有送来的饼干都被仔细称重。","t":120.71},{"en":"The largest was 713 pounds. It seemed certain that this would win the prize.","zh":"最大的一块重713磅。这似乎肯定会赢得奖品。","t":124.3},{"en":"But just before the competition closed,","zh":"但就在竞赛结束前，","t":132.33},{"en":"a lorry arrived at the factory with a truly colossal biscuit which weighed 2,400 pounds.","zh":"一辆卡车运载着一块重达2400磅的巨型饼干抵达工厂。","t":135.63},{"en":"It had been baked by a college student who had used over 1,000 pounds of flour, 800 pounds of sugar,","zh":"它是由一名大学生烘烤的，他使用了超过1000磅面粉、800磅糖、","t":144.44},{"en":"200 pounds of fat, and 400 pounds of various other ingredients.","zh":"200磅脂肪和400磅其他各种配料。","t":152.59},{"en":"It was so heavy that a crane had to be used to remove it from the lorry.","zh":"它太重了，不得不动用起重机将其从卡车上卸下。","t":158.26},{"en":"The manufacturers had to pay more money than they had anticipated, for they bought the biscuit from the student for $24, 000.","zh":"制造商不得不支付超出他们预期的金额，因为他们以24000美元从这名学生手中买下了这块饼干。","t":163.97}],"vocab":[{"word":"avoid","phonetic":"/əˈvɔɪd/","meanings":[{"pos":"verb","meaning":"避免；避开","usage":"后接名词、代词或动名词作宾语，不可接不定式"}]},{"word":"influence","phonetic":"/ˈɪnfluəns/","meanings":[{"pos":"noun","meaning":"影响；作用","usage":"常与介词on/upon搭配，表示对……的影响"},{"pos":"verb","meaning":"影响；左右","usage":"及物动词，直接接宾语"}]},{"word":"pride","phonetic":"/praɪd/","meanings":[{"pos":"verb","meaning":"为……感到骄傲","usage":"固定搭配pride oneself on/upon sth./doing sth."},{"pos":"noun","meaning":"骄傲；自豪","usage":"不可数名词，可与take pride in搭配"}]},{"word":"taste","phonetic":"/teɪst/","meanings":[{"pos":"noun","meaning":"品味；审美","usage":"表示抽象品味时为不可数名词，表口味时可作可数名词"},{"pos":"verb","meaning":"品尝；尝起来","usage":"作系动词时后接形容词作表语"}]},{"word":"exert","phonetic":"/ɪɡˈzɜːt/","meanings":[{"pos":"verb","meaning":"施加（影响、压力等）","usage":"常与influence, pressure, effort等名词搭配"}]},{"word":"subtle","phonetic":"/ˈsʌtl/","meanings":[{"pos":"adjective","meaning":"微妙的；不易察觉的","usage":"多用来形容变化、影响、差别等抽象事物"}]},{"word":"persuade","phonetic":"/pəˈsweɪd/","meanings":[{"pos":"verb","meaning":"说服；劝说","usage":"常用搭配persuade sb. to do sth. 或persuade sb. into doing sth."}]},{"word":"classify","phonetic":"/ˈklæsɪfaɪ/","meanings":[{"pos":"verb","meaning":"分类；归类","usage":"常与介词into搭配，表示将……分为……"}]},{"word":"devise","phonetic":"/dɪˈvaɪz/","meanings":[{"pos":"verb","meaning":"设计；策划","usage":"及物动词，宾语多为计划、方案、装置等"}]},{"word":"capture","phonetic":"/ˈkæptʃə(r)/","meanings":[{"pos":"verb","meaning":"吸引；捕获","usage":"capture one's attention为固定搭配，表示吸引某人的注意"}]},{"word":"tremendous","phonetic":"/trəˈmendəs/","meanings":[{"pos":"adjective","meaning":"巨大的；极大的","usage":"可用来形容数量、程度、反应等，非正式语境中也可表示“极好的”"}]},{"word":"occupy","phonetic":"/ˈɒkjupaɪ/","meanings":[{"pos":"verb","meaning":"占据；占用","usage":"可指占据空间、时间，也可表示占领、担任职位"}]},{"word":"colossal","phonetic":"/kəˈlɒsl/","meanings":[{"pos":"adjective","meaning":"巨大的；庞大的","usage":"语气比big, large强，强调规模异常大"}]},{"word":"ingredient","phonetic":"/ɪnˈɡriːdiənt/","meanings":[{"pos":"noun","meaning":"原料；成分","usage":"可数名词，多指食品的成分，也可引申为要素、因素"}]},{"word":"anticipate","phonetic":"/ænˈtɪsɪpeɪt/","meanings":[{"pos":"verb","meaning":"预料；预期","usage":"后可接名词、动名词或that从句作宾语"}]}],"phrases":[{"phrase":"get something for nothing","usage":"表示免费获得某物、不劳而获，口语和书面语中都常用","examples":[{"en":"There is no such thing as getting something for nothing in the world.","zh":"世界上没有不劳而获的好事。"},{"en":"Many people are attracted by the idea of getting something for nothing.","zh":"很多人都被免费得东西的想法吸引。"}]},{"phrase":"exert an influence on","usage":"表示对……施加影响，可在influence前加形容词修饰影响的性质","examples":[{"en":"Parents exert a great influence on their children's character development.","zh":"父母对孩子的性格发展有很大影响。"},{"en":"Social media exerts a subtle influence on people's values.","zh":"社交媒体对人们的价值观有着微妙的影响。"}]},{"phrase":"pride oneself on","usage":"为……感到自豪、得意，主语通常是人","examples":[{"en":"He prides himself on his ability to speak four languages fluently.","zh":"他为自己能流利说四种语言而自豪。"},{"en":"The restaurant prides itself on using only fresh local ingredients.","zh":"这家餐厅以只使用新鲜本地食材为荣。"}]},{"phrase":"enable sb. to do sth.","usage":"使某人能够做某事，是正式表达，常用于说明某事物的作用","examples":[{"en":"The new policy enables low-income families to afford better housing.","zh":"新政策让低收入家庭能够负担得起更好的住房。"},{"en":"The Internet enables people to communicate with others around the world easily.","zh":"互联网让人们可以轻松和世界各地的人交流。"}]},{"phrase":"capture the attention of","usage":"吸引……的注意力，同义表达还有draw/attract one's attention","examples":[{"en":"The bright color of the poster captured the attention of passers-by.","zh":"海报鲜艳的颜色吸引了路人的注意。"},{"en":"His speech at the conference captured the attention of all the attendees.","zh":"他在会议上的发言吸引了所有参会者的注意。"}]},{"phrase":"the response to","usage":"对……的反应、回应，response后接介词to","examples":[{"en":"The response to the new product launch was beyond our expectation.","zh":"新产品发布后的反响超出了我们的预期。"},{"en":"There has been a positive response to the government's new environmental policy.","zh":"公众对政府新的环保政策反应积极。"}]},{"phrase":"before long","usage":"不久之后，相当于soon，可放在句首或句末","examples":[{"en":"Before long, he got used to the new school life and made many friends.","zh":"不久之后他就适应了新的学校生活，还交了很多朋友。"},{"en":"The project is progressing well, and before long we will see the results.","zh":"项目进展顺利，很快我们就能看到成果了。"}]},{"phrase":"of all shapes and sizes","usage":"各种形状和大小的，用来形容事物种类多样","examples":[{"en":"The store sells bags of all shapes and sizes to meet different customers' needs.","zh":"这家店卖各种形状和尺寸的包，满足不同顾客的需求。"},{"en":"On the beach, there are shells of all shapes and sizes scattered everywhere.","zh":"沙滩上散落着各种形状和大小的贝壳。"}]}],"grammar":[{"title":"as引导的让步状语从句","definition":"as引导让步状语从句时，需要将表语、状语或动词原形提前到句首，形成倒装结构，含义相当于although/though","structure":"形容词/副词/名词/动词原形 + as + 主语 + 谓语，主句","usage":"用于正式语境中表达“尽管、虽然”的含义，若提前的是单数可数名词，前面要省略冠词","examples":[{"en":"Much as we may pride ourselves on our good taste, we are no longer free to choose the things we want.","zh":"尽管我们可能对自己的品味很是得意，但我们已经不能自主选择想买的东西了。"},{"en":"Young as he is, he has already won several international awards in the field of physics.","zh":"尽管他很年轻，他已经在物理领域获得了数个国际奖项。"},{"en":"Try as she might, she could not open the locked door without the key.","zh":"无论她怎么努力，没有钥匙她都打不开那扇锁着的门。"}]},{"title":"动名词的被动语态","definition":"当动名词的逻辑主语是动名词动作的承受者时，动名词需要用被动形式，即being + 过去分词","structure":"动词（后接动名词） + being done","usage":"常用于avoid, enjoy, mind, remember, forget等后接动名词作宾语的动词之后","examples":[{"en":"No one can avoid being influenced by advertisements.","zh":"没有人能避免受到广告的影响。"},{"en":"He was very upset about being criticized by the teacher in front of the whole class.","zh":"他因为在全班面前被老师批评而非常难过。"},{"en":"Many young people dream of being admitted to their ideal universities.","zh":"很多年轻人都梦想被自己理想的大学录取。"}]},{"title":"make it + 形容词 + for sb. to do sth.","definition":"该结构中it是形式宾语，真正的宾语是后面的不定式短语，形容词作宾语补足语，用来补充说明做某事的性质","structure":"make + it + 形容词/名词 + (for sb.) + 不定式短语","usage":"当不定式作宾语且后面有宾语补足语时，需要用it作形式宾语，将真正的宾语后置，保持句子结构平衡","examples":[{"en":"Radio and television have made it possible for advertisers to capture the attention of millions of people in this way.","zh":"广播和电视使得广告商能够用这种方式吸引数百万人的注意。"},{"en":"Smartphones make it convenient for people to shop, study and work anywhere.","zh":"智能手机让人们可以随时随地很方便地购物、学习和工作。"},{"en":"The frequent public transport makes it easy for citizens to travel around the city.","zh":"便捷的公共交通让市民在城市里出行很容易。"}]}],"patterns":[{"pattern":"Much as we may ..., we ... for ...","explanation":"","original":{"en":"Much as we may pride ourselves on our good taste, we are no longer free to choose the things we want, for advertising exerts a subtle influence on us.","zh":"尽管我们可能对自己的品味很是得意，但我们已经不能自主选择想买的东西了，因为广告在我们身上施加着微妙的影响。"},"examples":[{"en":"Much as we may value our independence, we often need help from others, for no one can solve all problems alone.","zh":"尽管我们可能很看重自己的独立性，但我们时常需要他人的帮助，因为没有人能独自解决所有问题。"},{"en":"Much as we may enjoy staying up late, we should form the habit of sleeping early, for regular rest is essential to our health.","zh":"尽管我们可能很享受熬夜，但我们应该养成早睡的习惯，因为规律的休息对我们的健康至关重要。"}]},{"pattern":"It was so + 形容词 + that ...","explanation":"","original":{"en":"It was so heavy that a crane had to be used to remove it from the lorry.","zh":"它实在太重了，以至于得用起重机才能把它从卡车上卸下来。"},"examples":[{"en":"The novel was so interesting that I stayed up the whole night to finish reading it.","zh":"这本小说太有趣了，以至于我熬了一整夜把它读完了。"},{"en":"The lecture was so boring that most of the audience fell asleep halfway through.","zh":"这场讲座太无聊了，以至于大多数听众听到一半都睡着了。"}]},{"pattern":"... had to ... than they had anticipated, for ...","explanation":"","original":{"en":"The manufacturers had to pay more money than they had anticipated, for they bought the biscuit from the student for $24,000.","zh":"生产商不得不付出比预期多得多的钱，因为他们花了24000美元从那个学生手里买下了这块饼干。"},"examples":[{"en":"We had to spend more time on the project than we had anticipated, for there were many unexpected difficulties in the process.","zh":"我们在这个项目上花的时间比预期要多，因为过程中出现了很多意料之外的困难。"},{"en":"The travel agency had to arrange more accommodation than they had anticipated, for the number of tourists doubled during the holiday.","zh":"旅行社不得不安排比预期更多的住宿，因为假期期间游客数量翻了一倍。"}]},{"pattern":"... discovered years ago that ...","explanation":"","original":{"en":"Advertisers discovered years ago that all of us love to get something for nothing.","zh":"广告商多年前就发现，我们所有人都喜欢免费得到东西。"},"examples":[{"en":"Educators discovered years ago that children learn better in a relaxed and interactive environment.","zh":"教育工作者多年前就发现，孩子在轻松互动的环境里学习效果更好。"},{"en":"Scientists discovered years ago that regular exercise can reduce the risk of many chronic diseases.","zh":"科学家多年前就发现，规律锻炼可以降低很多慢性病的患病风险。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“巨大的；极大的” 对应的单词是？","hint":"adjective · /trəˈmendəs/","options":["amusing","tremendous","graceful","prizefighter"],"answer":1,"explain":"tremendous · /trəˈmendəs/ · adjective · 巨大的；极大的。可用来形容数量、程度、反应等，非正式语境中也可表示“极好的”","source":{"kind":"vocab","word":"tremendous"},"id":"b3-u26-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：施加（影响、压力等）","hint":"/ɪɡˈzɜːt/ · verb","answer":"exert","placeholder":"输入英文单词","explain":"exert · /ɪɡˈzɜːt/ · verb · 施加（影响、压力等）。常与influence, pressure, effort等名词搭配","source":{"kind":"vocab","word":"exert"},"id":"b3-u26-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, he got used to the new school life and made many friends.","hint":"不久之后他就适应了新的学校生活，还交了很多朋友。","answer":"before long","placeholder":"输入缺失的短语","explain":"before long：不久之后，相当于soon，可放在句首或句末（不久之后他就适应了新的学校生活，还交了很多朋友。）","source":{"kind":"phrase","phrase":"before long"},"id":"b3-u26-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：It had been baked by a college _____ who had used over 1,000 pounds of flour, 800 pounds of sugar,","hint":"它是由一名大学生烘烤的，他使用了超过1000磅面粉、800磅糖、","answer":"student","placeholder":"输入缺失的单词","explain":"It had been baked by a college student who had used over 1,000 pounds of flour, 800 pounds of sugar, — 它是由一名大学生烘烤的，他使用了超过1000磅面粉、800磅糖、","source":{"kind":"sentence","en":"It had been baked by a college student who had used over 1,000 pounds of flour, 800 pounds of sugar,"},"id":"b3-u26-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“该结构中it是形式宾语，真正的宾语是后面的不定式短语，形容词作宾语补足语，用来补充说明做某事的性质” 描述的是哪个语法点？","hint":"make + it + 形容词/名词 + (for sb.) + 不定式短语","options":["现在分词作伴随/结果状语","make it + 形容词 + for sb. to do sth.","It引导的强调句","副词的位置和作用"],"answer":1,"explain":"make it + 形容词 + for sb. to do sth.：make + it + 形容词/名词 + (for sb.) + 不定式短语：当不定式作宾语且后面有宾语补足语时，需要用it作形式宾语，将真正的宾语后置，保持句子结构平衡","source":{"kind":"grammar","title":"make it + 形容词 + for sb. to do sth."},"id":"b3-u26-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nbut free cars, free houses, and free trips round the world as well.","hint":"","options":["记者们不停地要求采访，所以不得不雇佣律师在新闻发布会上担任这个家庭的发言人。","还提供免费汽车、免费房屋，以及免费环球旅行。","她从手提包里摸索出父亲写下所有旅行细节的纸条，交给了搬运工。","我们转身沿着主要街道往回走，"],"answer":1,"explain":"but free cars, free houses, and free trips round the world as well. — 还提供免费汽车、免费房屋，以及免费环球旅行。","source":{"kind":"sentence","en":"but free cars, free houses, and free trips round the world as well."},"id":"b3-u26-q06"}]},{"id":"b3-u27","book":3,"unit":27,"key":"27","lessonFrom":27,"lessonTo":27,"title":"Nothing to Sell and Nothing to Buy","titleZh":"无物可卖，无物可买","question":"What is the most important thing for a tramp?","sentences":[{"en":"It has been said that everyone lives by selling something.","zh":"有人说，人人都靠出售某种东西来维持生活。","t":16.99},{"en":"In the light of this statement, teachers live by selling knowledge,","zh":"依此而论，教师靠出售知识为生，","t":21.3},{"en":"philosophers by selling wisdom and priests by selling spiritual comfort.","zh":"哲学家靠出售智慧为生，牧师靠出售精神安慰为生。","t":25.93},{"en":"Though it may be possible to measure the value of material goods in terms of money,","zh":"衡量物质产品的价值或许可以用金钱尺度，","t":31.97},{"en":"it is extremely difficult to estimate the true value of the services which people perform for us.","zh":"但要估量人们为我们提供的服务的真正价值是极其困难的。","t":38.43},{"en":"There are times when we would willingly give everything we possess to save our lives,","zh":"有时，我们甘愿付出我们所拥有的一切来挽救自己的生命，","t":46.57},{"en":"yet we might grudge paying a surgeon a high fee for offering us precisely this service.","zh":"然而我们却可能不愿支付一个外科医生为我们提供了这种服务而索取的高额费用。","t":52.85},{"en":"The conditions of society are such that skills have to be paid for in the same way that goods are paid for at a shop.","zh":"社会现状是，技术和商店里的商品一样，是需要花钱购买的。","t":60.36},{"en":"Everyone has something to sell.","zh":"人人都有东西可卖。","t":68.79},{"en":"Tramps seem to be the only exception to this general rule.","zh":"流浪汉似乎是这条普遍规律的唯一例外。","t":72.01},{"en":"Beggars almost sell themselves as human beings to arouse the pity of passers-by.","zh":"乞丐几乎是出卖他们自身以博得过路人的同情。","t":76.71},{"en":"But real tramps are not beggars.","zh":"但真正的流浪汉不是乞丐。","t":83.13},{"en":"They have nothing to sell and require nothing from others.","zh":"他们无物可卖，也无需别人的任何东西。","t":85.62},{"en":"In seeking independence, they do not sacrifice their human dignity.","zh":"在寻求独立的同时，他们并没有牺牲自己做人的尊严。","t":90.15},{"en":"A tramp may ask you for money, but he will never ask you to feel sorry for him.","zh":"流浪汉可能会向你要钱，但他绝不会让你可怜他。","t":95.55},{"en":"He has deliberately chosen to lead the life he leads and is fully aware of the consequences.","zh":"他是故意选择他所过的这种生活的，并且完全清楚这种选择的后果。","t":101.54},{"en":"He may never be sure where the next meal is coming from,","zh":"他可能从不确定下一顿饭的着落，","t":109.15},{"en":"but he is free from the thousands of anxieties which afflict other people.","zh":"但他却摆脱了困扰其他人的成千上万的忧虑。","t":113.69},{"en":"His few material possessions make it possible for him to move from place to place with ease.","zh":"他那一点点物质财富使他能够轻松自如地从一个地方走到另一个地方。","t":119.99},{"en":"By having to sleep in the open, he gets far closer to the world of nature than most of us ever do.","zh":"由于不得不露宿野外，他比我们大多数人任何时候都更接近大自然。","t":127.89},{"en":"He may hunt, beg, or steal occasionally to keep himself alive;","zh":"他可能偶尔狩猎、乞讨或偷窃以维持生存；","t":136.18},{"en":"he may even, in times of real need, do a little work; but he will never sacrifice his freedom.","zh":"在真正需要的时候，他甚至可以做一点工作；但他绝不会牺牲他的自由。","t":141.89},{"en":"We often speak of tramps with contempt and put them in the same class as beggars,","zh":"我们经常轻蔑地谈起流浪汉，并把他们和乞丐划为一类，","t":150.07},{"en":"but how many of us can honestly say that we have not felt a little envious of their simple way of life and their freedom from care?","zh":"但我们中有多少人能诚实地说，我们没有一点羡慕他们那种简单的生活方式和无忧无虑的生活呢？","t":156.15}],"vocab":[{"word":"philosopher","phonetic":"/fəˈlɒsəfə(r)/","meanings":[{"pos":"noun","meaning":"哲学家","usage":"指研究哲学、构建哲学理论体系的人"}]},{"word":"priest","phonetic":"/priːst/","meanings":[{"pos":"noun","meaning":"牧师；神父","usage":"指基督教会中主持宗教仪式、管理教务的神职人员"}]},{"word":"spiritual","phonetic":"/ˈspɪrɪtʃuəl/","meanings":[{"pos":"adjective","meaning":"精神的；心灵的","usage":"与物质相对，描述和人的精神、信仰、思想相关的事物"}]},{"word":"estimate","phonetic":"/ˈestɪmeɪt/","meanings":[{"pos":"verb","meaning":"估计；估量","usage":"指对事物的价值、数量、程度等进行大致的判断"}]},{"word":"grudge","phonetic":"/ɡrʌdʒ/","meanings":[{"pos":"verb","meaning":"不情愿做；吝惜","usage":"常用结构grudge doing sth/grudge sb sth，表示不愿意给某人某物或不愿意做某事"}]},{"word":"surgeon","phonetic":"/ˈsɜːdʒən/","meanings":[{"pos":"noun","meaning":"外科医生","usage":"指专门从事外科手术的医生，区别于内科医生physician"}]},{"word":"tramp","phonetic":"/træmp/","meanings":[{"pos":"noun","meaning":"流浪汉；游民","usage":"指没有固定住所、四处流浪的人，本文特指不依靠乞讨、追求独立自由的流浪者"}]},{"word":"exception","phonetic":"/ɪkˈsepʃn/","meanings":[{"pos":"noun","meaning":"例外","usage":"常用搭配exception to sth，表示某一规则或情况的例外"}]},{"word":"arouse","phonetic":"/əˈraʊz/","meanings":[{"pos":"verb","meaning":"引起；唤起","usage":"后常接表示情感、反应的名词，如pity, interest, anger等"}]},{"word":"dignity","phonetic":"/ˈdɪɡnəti/","meanings":[{"pos":"noun","meaning":"尊严；自尊","usage":"指人应有的受尊重的地位和身份，不可数名词"}]},{"word":"deliberately","phonetic":"/dɪˈlɪbərətli/","meanings":[{"pos":"adverb","meaning":"故意地；蓄意地","usage":"强调行为是经过深思熟虑后主动选择的，而非偶然发生"}]},{"word":"consequence","phonetic":"/ˈkɒnsɪkwəns/","meanings":[{"pos":"noun","meaning":"后果；结果","usage":"常指某个行为或决定带来的直接结果，可褒可贬"}]},{"word":"afflict","phonetic":"/əˈflɪkt/","meanings":[{"pos":"verb","meaning":"折磨；使痛苦","usage":"常用被动结构sb be afflicted with sth，表示某人受某事物折磨"}]},{"word":"contempt","phonetic":"/kənˈtempt/","meanings":[{"pos":"noun","meaning":"蔑视；轻视","usage":"常用搭配speak of sb with contempt，表示以轻蔑的态度谈论某人"}]},{"word":"envious","phonetic":"/ˈenviəs/","meanings":[{"pos":"adjective","meaning":"羡慕的；嫉妒的","usage":"常用搭配be envious of sb/sth，表示羡慕/嫉妒某人或某物"}]}],"phrases":[{"phrase":"in the light of","usage":"介词短语，意为“根据；鉴于”，用于引出做判断或决定的依据，可置于句首或句中","examples":[{"en":"In the light of recent research, this theory has been proved wrong.","zh":"根据最近的研究，这个理论已经被证明是错误的。"},{"en":"We revised our plan in the light of the new data.","zh":"我们根据新的数据修改了计划。"}]},{"phrase":"in terms of","usage":"介词短语，意为“就…而言；在…方面”，用于限定讨论的角度或范围","examples":[{"en":"The job is great in terms of salary, but it has its disadvantages.","zh":"就薪水而言这份工作很棒，但它也有缺点。"},{"en":"Measured in terms of educational resources, this city is far ahead of others.","zh":"从教育资源方面衡量，这座城市远远领先于其他城市。"}]},{"phrase":"be free from","usage":"形容词短语，意为“不受…影响；没有…的”，用于描述人或事物摆脱了某种不好的状态","examples":[{"en":"She wants to live in a place that is free from noise.","zh":"她想住在一个没有噪音的地方。"},{"en":"Regular exercise helps you stay free from illness.","zh":"经常锻炼能帮你远离疾病。"}]},{"phrase":"move from place to place","usage":"动词短语，意为“四处迁徙；奔波”，描述没有固定住所、经常更换居住地点的状态","examples":[{"en":"As a travel photographer, he has to move from place to place all year round.","zh":"作为一名旅行摄影师，他常年需要四处奔波。"},{"en":"In ancient times, nomadic tribes moved from place to place to find water and grass for their animals.","zh":"在古代，游牧部落为了给牲畜寻找水草四处迁徙。"}]},{"phrase":"in times of","usage":"介词短语，意为“在…的时候；在…的时期”，后接表示困难、需要等的名词，描述特定的情境阶段","examples":[{"en":"Friends always help each other in times of difficulty.","zh":"朋友总会在困难的时候互相帮助。"},{"en":"The company provided enough supplies in times of emergency.","zh":"公司在紧急时期提供了充足的物资。"}]},{"phrase":"speak of sb with contempt","usage":"动词短语，意为“以轻蔑的态度谈论某人”，描述对某人的不尊重态度","examples":[{"en":"It is impolite to speak of those who made mistakes with contempt.","zh":"以轻蔑的态度谈论那些犯过错的人是不礼貌的。"},{"en":"He used to speak of his former boss with contempt, but now he admires him a lot.","zh":"他过去常常轻蔑地谈论他的前老板，但现在他非常敬佩对方。"}]}],"grammar":[{"title":"It作形式主语的主语从句","definition":"当主语是较长的从句时，为了避免句子头重脚轻，通常用it作形式主语放在句首，真正的主语从句放在句末","structure":"It + be + 名词/形容词/过去分词 + that引导的主语从句","usage":"常用于引出观点、事实、传闻等内容，常见搭配有it is said that, it is possible that, it is well known that等","examples":[{"en":"It has been said that everyone lives by selling something.","zh":"有人说，每个人都靠出售某种东西为生。"},{"en":"It is well known that drinking enough water is good for health.","zh":"众所周知，喝足够的水对健康有益。"},{"en":"It is surprising that he finished the task in only two days.","zh":"他仅用两天就完成了任务，这真让人惊讶。"}]},{"title":"There be句型的变形There are times when...","definition":"该结构意为“有些时候…/有时候会…”，用于描述偶尔发生的情况，when引导的定语从句修饰先行词times","structure":"There are times when + 陈述句","usage":"用来引出生活中偶尔出现的某种情境或感受，表达某种情况的偶然性","examples":[{"en":"There are times when we would willingly give everything we possess to save our lives.","zh":"有时候，我们为了挽救生命，愿意付出我们所占有的一切。"},{"en":"There are times when I really want to quit my job and travel around the world.","zh":"有些时候我真的想辞掉工作去环游世界。"},{"en":"There are times when even the most careful person makes mistakes.","zh":"有时候即使是最细心的人也会犯错。"}]}],"patterns":[{"pattern":"Though it may be possible to do sth, it is extremely difficult to do sth else.","explanation":"","original":{"en":"Though it may be possible to measure the value of material goods in terms of money, it is extremely difficult to estimate the true value of the services which people perform for us.","zh":"虽然物质产品的价值可以用金钱来衡量，但要估算别人为我们提供的服务的真实价值却是极其困难的。"},"examples":[{"en":"Though it may be possible to learn the basic rules of a language in a few months, it is extremely difficult to master it fluently.","zh":"虽然可能在几个月内学会一门语言的基本规则，但要流利地掌握它却极其困难。"},{"en":"Though it may be possible to finish the project on time, it is extremely difficult to meet all the requirements perfectly.","zh":"虽然有可能按时完成这个项目，但要完美满足所有要求却极其困难。"}]},{"pattern":"We often speak of sb with... and put them in the same class as..., but how many of us can honestly say that...?","explanation":"","original":{"en":"We often speak of tramps with contempt and put them in the same class as beggars, but how many of us can honestly say that we have not felt a little envious of their simple way of life and their freedom from care?","zh":"我们经常轻蔑地谈论流浪汉，把他们归为乞丐一类，但我们中有多少人能够坦率地说，我们没有对他们简单的生活方式和无忧无虑的自由感到一丝羡慕呢？"},"examples":[{"en":"We often speak of full-time artists with admiration and put them in the same class as geniuses, but how many of us can honestly say that we are willing to give up stable income to pursue such a career?","zh":"我们经常羡慕地谈论全职艺术家，把他们归为天才一类，但我们中有多少人能够坦率地说，我们愿意放弃稳定的收入去追求这样的职业呢？"},{"en":"We often speak of people who quit stable jobs to start businesses with praise and put them in the same class as brave explorers, but how many of us can honestly say that we can bear the risks of failure?","zh":"我们经常称赞那些辞去稳定工作创业的人，把他们归为勇敢的探索者一类，但我们中有多少人能够坦率地说，我们能承担失败的风险呢？"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“故意地；蓄意地” 对应的单词是？","hint":"adverb · /dɪˈlɪbərətli/","options":["grocer","sailing","deliberately","elegant"],"answer":2,"explain":"deliberately · /dɪˈlɪbərətli/ · adverb · 故意地；蓄意地。强调行为是经过深思熟虑后主动选择的，而非偶然发生","source":{"kind":"vocab","word":"deliberately"},"id":"b3-u27-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：哲学家","hint":"/fəˈlɒsəfə(r)/ · noun","answer":"philosopher","placeholder":"输入英文单词","explain":"philosopher · /fəˈlɒsəfə(r)/ · noun · 哲学家。指研究哲学、构建哲学理论体系的人","source":{"kind":"vocab","word":"philosopher"},"id":"b3-u27-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Friends always help each other _____ difficulty.","hint":"朋友总会在困难的时候互相帮助。","answer":"in times of","placeholder":"输入缺失的短语","explain":"in times of：介词短语，意为“在…的时候；在…的时期”，后接表示困难、需要等的名词，描述特定的情境阶段（朋友总会在困难的时候互相帮助。）","source":{"kind":"phrase","phrase":"in times of"},"id":"b3-u27-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：It has been said that everyone lives by selling _____","hint":"有人说，人人都靠出售某种东西来维持生活。","answer":"something","placeholder":"输入缺失的单词","explain":"It has been said that everyone lives by selling something. — 有人说，人人都靠出售某种东西来维持生活。","source":{"kind":"sentence","en":"It has been said that everyone lives by selling something."},"id":"b3-u27-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当主语是较长的从句时，为了避免句子头重脚轻，通常用it作形式主语放在句首，真正的主语从句放在句末” 描述的是哪个语法点？","hint":"It + be + 名词/形容词/过去分词 + that引导的主语从句","options":["for引导的原因状语从句","It作形式主语的主语从句","Though / Although + 从句（让步状语从句）","either...or...并列连词结构"],"answer":1,"explain":"It作形式主语的主语从句：It + be + 名词/形容词/过去分词 + that引导的主语从句：常用于引出观点、事实、传闻等内容，常见搭配有it is said that, it is possible that, it is well known that等","source":{"kind":"grammar","title":"It作形式主语的主语从句"},"id":"b3-u27-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nA tramp may ask you for money, but he will never ask you to feel sorry for him.","hint":"","options":["历史学家已经能够解读这个难懂的密码。","那个官员拧开瓶盖，把瓶子凑到鼻孔前。","流浪汉可能会向你要钱，但他绝不会让你可怜他。","它为闲暇时间提供了放松，因为仅仅看着自己的珍藏就是一种乐趣。"],"answer":2,"explain":"A tramp may ask you for money, but he will never ask you to feel sorry for him. — 流浪汉可能会向你要钱，但他绝不会让你可怜他。","source":{"kind":"sentence","en":"A tramp may ask you for money, but he will never ask you to feel sorry for him."},"id":"b3-u27-q06"}]},{"id":"b3-u28","book":3,"unit":28,"key":"28","lessonFrom":28,"lessonTo":28,"title":"Five Pounds Too Dear","titleZh":"五镑也嫌贵","question":"Why was even five pounds 'too dear' ?","sentences":[{"en":"Small boats loaded with wares sped to the great liner as she was entering the harbour.","zh":"当那艘巨型客轮驶进港口的时候，许多装载着货品的小船疾驶着向它靠拢。","t":16.88},{"en":"Before she had anchored, the men from the boats had climbed on board","zh":"没等船停稳，小船上的人就爬上了客轮。","t":23.63},{"en":"and the decks were soon covered with colourful rugs from Persia,","zh":"甲板上很快就摆满了：来自波斯的五光十色的地毯、","t":28.49},{"en":"silks from India, copper coffee pots, and beautiful handmade silverware.","zh":"印度的丝绸、铜咖啡壶以及制作精美的手工银器。","t":33.3},{"en":"It was difficult not to be tempted.","zh":"谁都很难不为之所动。","t":40.08},{"en":"Many of the tourists on board had begun bargaining with the tradesmen,","zh":"船上许多游客已和小贩们讨价还价起来，","t":43.3},{"en":"but I decided not to buy anything until I had disembarked.","zh":"而我却决定不买任何东西，直到下船为止。","t":47.47},{"en":"I had no sooner got off the ship than I was assailed by a man who wanted to sell me a diamond ring.","zh":"我刚一下船，就受到一个要向我兜售钻石戒指的人的纠缠。","t":53.56},{"en":"I had no intention of buying one,","zh":"我根本不想买钻石戒指，","t":62.16},{"en":"but I could not conceal the fact that I was impressed by the size of the diamonds.","zh":"但我不得不承认我还是给那些钻石的大小留下了深刻的印象。","t":64.87},{"en":"Some of them were as big as marbles.","zh":"有些钻石大得像弹子。","t":71.44},{"en":"The man went to great lengths to prove that the diamonds were real.","zh":"那个人竭力证明他的钻石是真的。","t":74.63},{"en":"As we were walking past a shop, he held a diamond firmly against the window and made a deep impression in the glass.","zh":"当我们走过一家商店的时候，他把一枚钻石使劲地抵在橱窗上，在玻璃上划出了一道深痕。","t":79.9},{"en":"It took me over half an hour to get rid of him.","zh":"我花了半个多小时才摆脱了他。","t":88.9},{"en":"The next man to approach me was selling expensive pens and watches.","zh":"第二个向我走来的人是卖高档钢笔和手表的。","t":92.93},{"en":"I examined one of the pens closely. It certainly looked genuine.","zh":"我仔细地察看了一支钢笔。它看上去确实是真品。","t":98.1},{"en":"At the base of the gold cap, the words 'made in the U.S.A.' had been neatly inscribed.","zh":"在金笔帽的底部，刻有“美国制造”的字样。","t":103.79},{"en":"The man said that the pen was worth ￡50, but as a special favour, he would let me have it for ￡30.","zh":"那人说这支笔值50镑，但作为特别优惠，他愿以30镑卖给我。","t":112.31},{"en":"I shook my head and held up five fingers indicating that I was willing to pay ￡5.","zh":"我摇了摇头，伸出5个手指，表示我愿付5镑。","t":122.21},{"en":"Gesticulating wildly, the man acted as if he found my offer outrageous,","zh":"那人狂乱地打着手势，装出我的出价不可思议的样子，","t":130.51},{"en":"but he eventually reduced the price to 10 pounds.","zh":"但最终还是把价格降到了10镑。","t":137.42},{"en":"Shrugging my shoulders I began to walk away when,","zh":"我耸了耸肩膀，刚要走开，","t":142.62},{"en":"a moment later, he ran after me and thrust the pen into my hands.","zh":"片刻之后，他便追了上来，把钢笔塞到我手里。","t":146.62},{"en":"Though he kept throwing up his arms in despair, he readily accepted the ￡5 I gave him.","zh":"尽管他不停地绝望地挥舞着双臂，但他还是爽快地收下了我给他的5镑钱。","t":153.35},{"en":"I felt especially pleased with my wonderful bargain--until I got back to the ship.","zh":"我对这笔了不起的交易特别满意——直到我回到船上。","t":160.57},{"en":"No matter how hard I tried,","zh":"无论我怎么努力，","t":167.77},{"en":"it was impossible to fill this beautiful pen with ink and to this day it has never written a single word!","zh":"也无法把墨水灌进这支漂亮的钢笔里，而且直到今天，它连一个字也没写出来过！","t":170.58}],"vocab":[{"word":"ware","phonetic":"/weə(r)/","meanings":[{"pos":"noun","meaning":"（通常指小商贩出售的）货物，商品","usage":"常用复数形式wares，多指手工制作或沿街售卖的小商品"}]},{"word":"liner","phonetic":"/ˈlaɪnə(r)/","meanings":[{"pos":"noun","meaning":"大型客轮，邮轮","usage":"指定期航行的大型客运轮船"}]},{"word":"anchor","phonetic":"/ˈæŋkə(r)/","meanings":[{"pos":"verb","meaning":"抛锚，停泊","usage":"指船只放下锚固定在水面"},{"pos":"noun","meaning":"锚","usage":"指船只停泊时使用的金属器具"}]},{"word":"silverware","phonetic":"/ˈsɪlvəweə(r)/","meanings":[{"pos":"noun","meaning":"银器，银制品","usage":"不可数名词，泛指银制的餐具、饰品等"}]},{"word":"tempt","phonetic":"/tempt/","meanings":[{"pos":"verb","meaning":"引诱，诱惑","usage":"常用搭配：tempt sb. to do sth. 诱惑某人做某事；be tempted to do sth. 很想做某事"}]},{"word":"bargain","phonetic":"/ˈbɑːɡən/","meanings":[{"pos":"verb","meaning":"讨价还价，议价","usage":"常用搭配：bargain with sb. about/over sth. 和某人就某物议价"},{"pos":"noun","meaning":"便宜货，减价品；交易","usage":"指价格低于实际价值的商品，或达成的买卖协议"}]},{"word":"disembark","phonetic":"/ˌdɪsɪmˈbɑːk/","meanings":[{"pos":"verb","meaning":"（从船、飞机、火车上）登陆，下车，下机","usage":"正式用词，指离开交通工具，尤其指船只"}]},{"word":"assail","phonetic":"/əˈseɪl/","meanings":[{"pos":"verb","meaning":"纠缠，困扰；攻击","usage":"常用搭配：be assailed by sb./sth. 被某人/某事纠缠/困扰"}]},{"word":"conceal","phonetic":"/kənˈsiːl/","meanings":[{"pos":"verb","meaning":"隐藏，隐瞒","usage":"正式用词，搭配：conceal sth. from sb. 向某人隐瞒某事"}]},{"word":"marble","phonetic":"/ˈmɑːbl/","meanings":[{"pos":"noun","meaning":"大理石；弹珠","usage":"表示“弹珠”时为可数名词，表示“大理石”时为不可数名词"}]},{"word":"inscribe","phonetic":"/ɪnˈskraɪb/","meanings":[{"pos":"verb","meaning":"在…上写（刻）字","usage":"常用被动语态：be inscribed on/in sth. 被刻在某物上"}]},{"word":"favour","phonetic":"/ˈfeɪvə(r)/","meanings":[{"pos":"noun","meaning":"恩惠，好意；偏爱","usage":"常用搭配：do sb. a favour 帮某人一个忙；as a special favour 作为特别优惠"}]},{"word":"gesticulate","phonetic":"/dʒeˈstɪkjuleɪt/","meanings":[{"pos":"verb","meaning":"做手势，用手势表达","usage":"指说话时用手势辅助表达情绪或意思"}]},{"word":"outrageous","phonetic":"/aʊtˈreɪdʒəs/","meanings":[{"pos":"adjective","meaning":"骇人的，离谱的，无法接受的","usage":"可用来形容价格、行为等离谱到令人难以接受"}]},{"word":"thrust","phonetic":"/θrʌst/","meanings":[{"pos":"verb","meaning":"猛推，塞，插","usage":"不规则动词，过去式和过去分词均为thrust，搭配：thrust sth. into sb.'s hands 把某物塞到某人手里"}]}],"phrases":[{"phrase":"go to great lengths to do sth.","usage":"表示“竭尽全力做某事，不遗余力做某事”，含为达成目的不惜花费时间精力的含义","examples":[{"en":"The man went to great lengths to prove that the diamonds were real.","zh":"那个男子竭尽全力证明这些钻石是真的。"},{"en":"Many companies go to great lengths to protect their trade secrets.","zh":"许多公司不遗余力地保护自己的商业机密。"}]},{"phrase":"get rid of","usage":"表示“摆脱，除去，处理掉”，可接人或物作宾语","examples":[{"en":"It took me over half an hour to get rid of him.","zh":"我花了半个多小时才摆脱掉他。"},{"en":"I need to get rid of these old clothes I never wear.","zh":"我需要把这些我从来不穿的旧衣服处理掉。"}]},{"phrase":"as a special favour","usage":"表示“作为特别优惠/优待”，常用于商家说服顾客购买商品的语境","examples":[{"en":"As a special favour, he would let me have it for ￡30.","zh":"作为特别优惠，他愿意收我30英镑就把它卖给我。"},{"en":"The shop owner gave me the discount as a special favour for regular customers.","zh":"作为给老顾客的特别优待，店主给了我这个折扣。"}]},{"phrase":"no sooner...than...","usage":"表示“一…就…”，引导时间状语从句，no sooner位于句首时句子要部分倒装","examples":[{"en":"I had no sooner got off the ship than I was assailed by a man who wanted to sell me a diamond ring.","zh":"我一下船就被一个想要卖给我钻石戒指的男子缠住了。"},{"en":"No sooner had we sat down than the film started.","zh":"我们刚一坐下电影就开始了。"}]},{"phrase":"have no intention of doing sth.","usage":"表示“没有做某事的打算，无意做某事”，强调主观上完全不想做","examples":[{"en":"I had no intention of buying one, but I could not conceal the fact that I was impressed by the size of the diamonds.","zh":"我根本不想买（钻戒），但我无法掩饰的是，那些钻石的大小确实给我留下了深刻的印象。"},{"en":"She has no intention of giving up her career after getting married.","zh":"她完全没有打算在结婚后放弃自己的事业。"}]},{"phrase":"be impressed by","usage":"表示“对…印象深刻，被…打动”，主语是人，宾语是令人印象深刻的事物","examples":[{"en":"I was impressed by the efficiency of the local government.","zh":"当地政府的办事效率给我留下了深刻的印象。"}]},{"phrase":"throw up one's arms in despair","usage":"表示“绝望地举起双手，无可奈何”，用来表达失望、无力的肢体动作和情绪","examples":[{"en":"Though he kept throwing up his arms in despair, he readily accepted the ￡5 I gave him.","zh":"尽管他一直绝望地挥舞着手臂，但还是欣然接受了我付给他的5英镑。"},{"en":"When he found all his efforts had been in vain, he threw up his arms in despair.","zh":"当他发现自己所有的努力都白费了时，他绝望地举起了双手。"}]},{"phrase":"be pleased with","usage":"表示“对…感到满意/高兴”，后接名词或动名词","examples":[{"en":"I felt especially pleased with my wonderful bargain.","zh":"我为自己这笔绝妙的交易感到格外得意。"},{"en":"The manager was very pleased with the performance of the new employee.","zh":"经理对新员工的表现非常满意。"}]}],"grammar":[{"title":"过去完成时（Past Perfect Tense）","definition":"表示过去某个动作或时间之前已经完成的动作，即“过去的过去”，强调动作发生的先后顺序","structure":"主语 + had + 动词过去分词","usage":"常用于描述在过去某个明确动作之前已经发生的事，常和before, until, no sooner...than, hardly...when等结构搭配使用","examples":[{"en":"Before she had anchored, the men from the boats had climbed on board.","zh":"大船还没下锚，小船上的人就已经爬上了船。"},{"en":"I decided not to buy anything until I had disembarked.","zh":"我决定在下船之前什么都不买。"},{"en":"He had finished his homework before his parents came back home.","zh":"在父母回家之前他就已经做完作业了。"}]},{"title":"让步状语从句（Adverbial Clause of Concession）","definition":"用来引导与主句内容相反或相对的信息，表达“虽然，尽管，即使”等让步含义，主句和从句之间存在转折关系","structure":"从属连词（though/although/no matter how等）+ 从句，主句","usage":"though和although表示“虽然”，不与but连用；no matter + 疑问词（how/what/when等）表示“无论/不管…”，引导让步状语从句","examples":[{"en":"Though he kept throwing up his arms in despair, he readily accepted the ￡5 I gave him.","zh":"尽管他一直绝望地挥舞着手臂，但还是欣然接受了我付给他的5英镑。"},{"en":"No matter how hard I tried, it was impossible to fill this beautiful pen with ink.","zh":"不管我怎么努力，都没法把墨水灌进这支漂亮的钢笔里。"},{"en":"Although it was raining heavily, he still went out to meet his friend.","zh":"尽管雨下得很大，他还是出门去见朋友了。"}]},{"title":"并列结构中的省略","definition":"在并列句中，如果前后分句的主语和谓语动词相同，为了避免重复，可省略后一分句中相同的部分","structure":"分句1 + 连词 + （省略相同成分的）分句2","usage":"常见于and, but, or等连词连接的并列句中，省略后句子结构更简洁，语义不受影响","examples":[{"en":"The decks were soon covered with colourful rugs from Persia, silks from India, copper coffee pots, and beautiful handmade silverware.","zh":"甲板上很快就摆满了来自波斯的彩色地毯、印度的丝绸、铜制咖啡壶，还有精美的手工银器。"},{"en":"It was difficult not to be tempted.","zh":"很难不动心。"},{"en":"My friend likes reading novels, and I (like) reading poems.","zh":"我的朋友喜欢读小说，我喜欢读诗歌。"}]}],"patterns":[{"pattern":"It takes/took sb. + 时间 + to do sth.","explanation":"","original":{"en":"It took me over half an hour to get rid of him.","zh":"我花了半个多小时才摆脱掉他。"},"examples":[{"en":"It took me three hours to finish this difficult math problem.","zh":"我花了三个小时才解出这道很难的数学题。"},{"en":"It took the workers two years to build this bridge.","zh":"工人们花了两年时间才建成这座桥。"}]},{"pattern":"主语 + had no sooner done sth. than + 一般过去时从句","explanation":"","original":{"en":"I had no sooner got off the ship than I was assailed by a man who wanted to sell me a diamond ring.","zh":"我一下船就被一个想要卖给我钻石戒指的男子缠住了。"},"examples":[{"en":"We had no sooner arrived at the station than the train left.","zh":"我们刚到车站，火车就开了。"},{"en":"He had no sooner finished his speech than the audience started clapping.","zh":"他刚结束演讲，观众就开始鼓掌了。"}]},{"pattern":"主语 + 动词 + when, a moment later + 另一动作","explanation":"","original":{"en":"Shrugging my shoulders I began to walk away when, a moment later, he ran after me and thrust the pen into my hands.","zh":"我耸了耸肩转身就走，这时，他追了上来，把钢笔塞到了我手里。"},"examples":[{"en":"I was about to close the door when, a moment later, my neighbour knocked and asked for a cup of sugar.","zh":"我正要关门，这时我的邻居敲门来要一杯糖。"},{"en":"We were just leaving the café when, a moment later, it started to pour with rain.","zh":"我们正要离开咖啡馆，这时突然下起了倾盆大雨。"}]},{"pattern":"No matter how + 形容词/副词 + 主语 + 谓语, 主句","explanation":"","original":{"en":"No matter how hard I tried, it was impossible to fill this beautiful pen with ink and to this day it has never written a single word!","zh":"不管我怎么努力，都没法把墨水灌进这支漂亮的钢笔里，直到今天它也没写出过一个字！"},"examples":[{"en":"No matter how difficult the task is, I will try my best to complete it.","zh":"不管这项任务有多难，我都会尽全力完成它。"},{"en":"No matter how many times he failed, he never gave up his dream.","zh":"不管他失败了多少次，他从来没有放弃自己的梦想。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“大理石；弹珠” 对应的单词是？","hint":"noun · /ˈmɑːbl/","options":["prosperity","marble","sunken","dust"],"answer":1,"explain":"marble · /ˈmɑːbl/ · noun · 大理石；弹珠。表示“弹珠”时为可数名词，表示“大理石”时为不可数名词","source":{"kind":"vocab","word":"marble"},"id":"b3-u28-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：引诱，诱惑","hint":"/tempt/ · verb","answer":"tempt","placeholder":"输入英文单词","explain":"tempt · /tempt/ · verb · 引诱，诱惑。常用搭配：tempt sb. to do sth. 诱惑某人做某事；be tempted to do sth. 很想做某事","source":{"kind":"vocab","word":"tempt"},"id":"b3-u28-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It took me over half an hour to _____ him.","hint":"我花了半个多小时才摆脱掉他。","answer":"get rid of","placeholder":"输入缺失的短语","explain":"get rid of：表示“摆脱，除去，处理掉”，可接人或物作宾语（我花了半个多小时才摆脱掉他。）","source":{"kind":"phrase","phrase":"get rid of"},"id":"b3-u28-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：I _____ one of the pens closely. It certainly looked genuine.","hint":"我仔细地察看了一支钢笔。它看上去确实是真品。","answer":"examined","placeholder":"输入缺失的单词","explain":"I examined one of the pens closely. It certainly looked genuine. — 我仔细地察看了一支钢笔。它看上去确实是真品。","source":{"kind":"sentence","en":"I examined one of the pens closely. It certainly looked genuine."},"id":"b3-u28-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示过去某个动作或时间之前已经完成的动作，即“过去的过去”，强调动作发生的先后顺序” 描述的是哪个语法点？","hint":"主语 + had + 动词过去分词","options":["no matter what引导的让步状语从句","过去完成时（Past Perfect Tense）","so...that 结果状语从句","so...that...引导的倒装句"],"answer":1,"explain":"过去完成时（Past Perfect Tense）：主语 + had + 动词过去分词：常用于描述在过去某个明确动作之前已经发生的事，常和before, until, no sooner...than, hardly...when等结构搭配使用","source":{"kind":"grammar","title":"过去完成时（Past Perfect Tense）"},"id":"b3-u28-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nI felt especially pleased with my wonderful bargain--until I got back to the ship.","hint":"","options":["去年夏天，我在花园里花了好几天时间，观察成千上万的蚂蚁爬上我那棵珍贵的桃树树干。","“猫的行为就像训练有素的伞兵，”一位医生说。","我对这笔了不起的交易特别满意——直到我回到船上。","监察官无法采取行动，"],"answer":2,"explain":"I felt especially pleased with my wonderful bargain--until I got back to the ship. — 我对这笔了不起的交易特别满意——直到我回到船上。","source":{"kind":"sentence","en":"I felt especially pleased with my wonderful bargain--until I got back to the ship."},"id":"b3-u28-q06"}]},{"id":"b3-u29","book":3,"unit":29,"key":"29","lessonFrom":29,"lessonTo":29,"title":"Funny or Not","titleZh":"好笑与否？","question":"What is the basis of 'sick' humour?","sentences":[{"en":"Whether we find a joke funny or not largely depends on where we have been brought up.","zh":"我们觉得一个笑话好不好笑，在很大程度上取决于我们是在哪里长大的。","t":14.46},{"en":"The sense of humour is mysteriously bound up with national characteristics.","zh":"幽默感与民族特点有着神秘的联系。","t":21.14},{"en":"A Frenchman, for instance, might find it hard to laugh at a Russian joke.","zh":"例如，法国人可能觉得俄罗斯笑话不好笑。","t":27.58},{"en":"In the same way, a Russian might fail to see anything amusing in a joke","zh":"同样，俄罗斯人可能觉得一个笑话没什么可乐的，","t":33.15},{"en":"which would make an Englishman laugh to tears.","zh":"而这个笑话却能让英国人捧腹大笑。","t":38.74},{"en":"Most funny stories are based on comic situations.","zh":"大多数有趣的故事都基于滑稽的情境。","t":43.08},{"en":"In spite of national differences, certain funny situations have a universal appeal.","zh":"尽管存在民族差异，但某些滑稽情境具有普遍的吸引力。","t":47.99},{"en":"No matter where you live,","zh":"无论你住在哪里，","t":54.56},{"en":"you would find it difficult not to laugh at, say, Charlie Chaplin's early films.","zh":"你都会觉得很难不对，比如说，查理·卓别林的早期电影发笑。","t":56.47},{"en":"However, a new type of humour, which stems largely from U.S., has recently come into fashion.","zh":"然而，一种主要源自美国的幽默新类型，最近流行起来。","t":63.16},{"en":"It is called 'sick humour'. Comedians base their jokes on tragic situations like violent death or serious accidents.","zh":"它被称为“病态幽默”。喜剧演员将他们的笑话建立在悲剧情境上，例如暴力死亡或严重事故。","t":71.51},{"en":"Many people find this sort of joke distasteful.","zh":"许多人觉得这种笑话令人反感。","t":82.68},{"en":"The following example of 'sick humour' will enable you to judge for yourself.","zh":"下面这个“病态幽默”的例子能让你自己评判。","t":87.3},{"en":"A man who had broken his right leg was taken to hospital a few weeks before Christmas.","zh":"一个右腿骨折的男人在圣诞节前几周被送进了医院。","t":93.87},{"en":"From the moment he arrived there,","zh":"从他到达那里那一刻起，","t":100.55},{"en":"he kept on pestering his doctor to tell him when he would be able to go home.","zh":"他就一直缠着医生，问他什么时候能回家。","t":102.86},{"en":"He dreaded having to spend Christmas in hospital.","zh":"他害怕不得不在医院过圣诞节。","t":108.84},{"en":"Though the doctor did his best, the patient's recovery was slow.","zh":"尽管医生尽了力，但病人的康复很慢。","t":112.72},{"en":"On Christmas day, the man still had his right leg in plaster.","zh":"圣诞节那天，这个男人右腿上仍然打着石膏。","t":117.98},{"en":"He spent a miserable day in bed thinking of all the fun he was missing.","zh":"他在床上度过了悲惨的一天，想着自己错过了所有的乐趣。","t":123.68},{"en":"The following day, however, the doctor consoled him by telling him","zh":"然而，第二天，医生安慰他说，","t":129.44},{"en":"that his chances of being able to leave hospital in time for New Year celebrations were good.","zh":"他赶在新年庆祝活动前出院的可能性很大。","t":134.27},{"en":"The man took heart and sure enough, on New Year's Eve he was able to hobble along to a party.","zh":"男人振作起来，果然，在除夕夜他能一瘸一拐地去参加派对。","t":141.56},{"en":"To compensate for his unpleasant experiences in hospital,","zh":"为了弥补他在医院的不愉快经历，","t":149.68},{"en":"the man drank a little more than was good for him.","zh":"他多喝了一点酒，这对他身体不好。","t":154.63},{"en":"In the process, he enjoyed himself thoroughly and kept telling everybody how much he hated hospitals.","zh":"在此过程中，他玩得很开心，并且不停地告诉所有人他有多么讨厌医院。","t":158.28},{"en":"He was still mumbling something about hospitals at the end of the party when he slipped on a piece of ice and broke his left leg.","zh":"派对结束时，他还在嘟囔着关于医院的事情，这时他滑到了一块冰上，摔断了左腿。","t":167.15}],"vocab":[{"word":"amusing","phonetic":"/əˈmjuːzɪŋ/","meanings":[{"pos":"adjective","meaning":"好笑的，有趣的","usage":"用来描述人、事物或情景能引人发笑的，语义中性偏褒义"}]},{"word":"universal","phonetic":"/ˌjuːnɪˈvɜːsl/","meanings":[{"pos":"adjective","meaning":"普遍的，共同的","usage":"指适用于所有情况、所有人或所有地区的，没有例外"}]},{"word":"appeal","phonetic":"/əˈpiːl/","meanings":[{"pos":"noun","meaning":"吸引力，感染力","usage":"表示人或事物具有的吸引他人的特质，常用搭配have appeal to sb."},{"pos":"verb","meaning":"呼吁；吸引","usage":"作动词时常见搭配appeal to sb. for sth.（呼吁）、appeal to sb.（吸引某人）"}]},{"word":"stem","phonetic":"/stem/","meanings":[{"pos":"verb","meaning":"起源于，来自","usage":"不及物动词，固定搭配stem from，用来描述事物的来源或起因"},{"pos":"noun","meaning":"茎，干","usage":"指植物的茎部，也可引申为器物的柄、把"}]},{"word":"comedian","phonetic":"/kəˈmiːdiən/","meanings":[{"pos":"noun","meaning":"喜剧演员，搞笑艺人","usage":"指以表演喜剧、讲笑话为职业的人"}]},{"word":"tragic","phonetic":"/ˈtrædʒɪk/","meanings":[{"pos":"adjective","meaning":"悲惨的，悲剧的","usage":"用来描述令人悲伤、不幸的事件或情况，与comic（喜剧的）是反义词"}]},{"word":"distasteful","phonetic":"/dɪsˈteɪstfl/","meanings":[{"pos":"adjective","meaning":"令人反感的，讨厌的","usage":"指事物不符合人的道德审美、让人觉得不舒服，程度比disgusting轻"}]},{"word":"pester","phonetic":"/ˈpestə(r)/","meanings":[{"pos":"verb","meaning":"纠缠，烦扰","usage":"指反复打扰、纠缠某人以达到自己的目的，常用搭配pester sb. to do sth.或pester sb. for sth."}]},{"word":"dread","phonetic":"/dred/","meanings":[{"pos":"verb","meaning":"惧怕，害怕","usage":"强调对将要发生的不好的事感到极度担忧，常用搭配dread doing sth.或dread that从句"}]},{"word":"plaster","phonetic":"/ˈplɑːstə(r)/","meanings":[{"pos":"noun","meaning":"石膏；灰泥","usage":"表示石膏时常用搭配in plaster（打了石膏），也可指建筑用的灰泥或者创可贴"}]},{"word":"miserable","phonetic":"/ˈmɪzrəbl/","meanings":[{"pos":"adjective","meaning":"痛苦的，悲惨的","usage":"用来描述人感觉非常不愉快、处境糟糕，也可形容事物令人难受"}]},{"word":"console","phonetic":"/kənˈsəʊl/","meanings":[{"pos":"verb","meaning":"安慰，抚慰","usage":"指在某人悲伤、失望的时候给予安慰，常用搭配console sb. with sth."}]},{"word":"hobble","phonetic":"/ˈhɒbl/","meanings":[{"pos":"verb","meaning":"蹒跚，跛行","usage":"指因为腿或脚受伤而走路一瘸一拐的"}]},{"word":"compensate","phonetic":"/ˈkɒmpenseɪt/","meanings":[{"pos":"verb","meaning":"补偿，弥补","usage":"常用搭配compensate sb. for sth.，表示为某人的损失、不好的经历给予补偿"}]},{"word":"mumble","phonetic":"/ˈmʌmbl/","meanings":[{"pos":"verb","meaning":"含糊地说，咕哝","usage":"指说话声音小且不清楚，通常因为不开心、醉酒或害羞"}]}],"phrases":[{"phrase":"be bound up with","usage":"表示事物之间密切相关、密不可分，用来描述两个事物的关联性","examples":[{"en":"The future of the company is bound up with the development of new technology.","zh":"这家公司的未来和新技术的发展密切相关。"},{"en":"Personality is bound up with the environment one grows up in.","zh":"性格和一个人的成长环境密不可分。"}]},{"phrase":"fail to do sth.","usage":"表示没能做到某事、未达成某个动作，比can't do更书面正式","examples":[{"en":"I failed to catch the last bus yesterday, so I had to take a taxi home.","zh":"我昨天没赶上末班车，所以只好打车回家。"},{"en":"The team failed to win the game even after three months of hard training.","zh":"尽管经过了三个月的刻苦训练，这支队伍还是没能赢得比赛。"}]},{"phrase":"be based on","usage":"表示“以…为基础，根据…”，主语通常是故事、理论、判断等事物","examples":[{"en":"The movie is based on a real-life story that happened 20 years ago.","zh":"这部电影是根据20年前发生的真实故事改编的。"},{"en":"Your argument should be based on solid evidence instead of guesses.","zh":"你的论点应该基于可靠的证据，而不是猜测。"}]},{"phrase":"in spite of","usage":"表示“尽管，虽然”，后接名词/名词短语，用来引导让步关系，等同于despite","examples":[{"en":"In spite of the heavy rain, we still arrived at the meeting on time.","zh":"尽管下着大雨，我们还是准时到达了会场。"},{"en":"He kept on running in spite of his injured ankle.","zh":"尽管脚踝受伤了，他还是继续跑步。"}]},{"phrase":"come into fashion","usage":"表示“开始流行，成为时尚”，主语通常是某种风格、事物、风潮","examples":[{"en":"Vintage clothes have come into fashion again among young people these years.","zh":"这些年复古服装又在年轻人中流行起来了。"},{"en":"Short haircuts came into fashion in the 1920s for women in Western countries.","zh":"20世纪20年代，短发在西方国家的女性中开始流行。"}]},{"phrase":"keep on doing sth.","usage":"表示“持续做某事，反复做某事”，强调动作的持续性和重复性","examples":[{"en":"If you keep on practicing English every day, you will make great progress soon.","zh":"如果你坚持每天练习英语，很快就会取得很大进步。"},{"en":"The little boy kept on asking his parents strange questions about the universe.","zh":"这个小男孩不停问他父母关于宇宙的奇怪问题。"}]},{"phrase":"take heart","usage":"表示“鼓起勇气，振作起来”，是不及物短语，用来描述人在受挫后恢复信心","examples":[{"en":"When you face difficulties in study, take heart and you will find solutions finally.","zh":"当你在学习中遇到困难时，振作起来，最终会找到解决办法的。"},{"en":"The team took heart after their first victory and performed better in the following matches.","zh":"这支队伍在首场胜利后振作了起来，在后续的比赛中表现得更好。"}]},{"phrase":"sure enough","usage":"表示“果然，果真”，放在句首或句中，用来证明之前的猜测、预料是正确的","examples":[{"en":"I thought it would rain this afternoon, and sure enough, it started pouring at 3 o'clock.","zh":"我就觉得今天下午会下雨，果然，三点的时候就开始下大雨了。"},{"en":"She said she would bring me a gift when she came back from Japan, and sure enough, she gave me a delicate handcraft.","zh":"她说从日本回来的时候会给我带礼物，果然，她给了我一个精致的手工艺品。"}]},{"phrase":"slip on","usage":"表示“在…上滑倒”，后接表示路面、地面的名词，强调滑倒的地点/原因","examples":[{"en":"Be careful not to slip on the wet floor when you enter the room.","zh":"进房间的时候小心别在湿地板上滑倒。"},{"en":"The old man slipped on the icy road and hurt his arm last winter.","zh":"去年冬天这位老人在结冰的路上滑倒，伤到了胳膊。"}]}],"grammar":[{"title":"让步状语从句（No matter/Whether引导）","definition":"用来表达“尽管、无论”的让步逻辑，说明主句的动作不受从句条件的影响依然成立","structure":"1. Whether + 陈述句, + 主句；2. No matter + 疑问词（where/who/when等）+ 陈述句, + 主句","usage":"whether引导时表示两种情况都不影响主句结果；no matter+疑问词引导时表示在任何该疑问词覆盖的情况下主句都成立，用于加强语气","examples":[{"en":"Whether you like the plan or not, we will carry it out next month.","zh":"无论你喜不喜欢这个计划，我们下个月都会执行它。"},{"en":"No matter how difficult the task is, we will try our best to finish it on time.","zh":"无论这个任务有多难，我们都会尽全力按时完成。"}]},{"title":"定语从句（which/who引导的非限定性定语从句）","definition":"用来对前面的名词或整个句子进行补充说明，去掉从句后主句依然完整，从句和主句之间通常用逗号隔开","structure":"主句 + , + which/who + 从句部分","usage":"which指代事物或前面整句话的内容，who指代人，不能用that引导非限定性定语从句，用来提供额外的补充信息","examples":[{"en":"My favorite season is autumn, when the leaves turn yellow and the weather is cool.","zh":"我最喜欢的季节是秋天，那时树叶变黄，天气凉爽。"},{"en":"He passed the final exam, which made his parents very happy.","zh":"他通过了期末考试，这让他的父母非常开心。"}]}],"patterns":[{"pattern":"Whether sb. find sth. adj. or not largely depends on ...","explanation":"","original":{"en":"Whether we find a joke funny or not largely depends on where we have been brought up.","zh":"我们觉得一个笑话好不好笑，很大程度上取决于我们是在哪里长大的。"},"examples":[{"en":"Whether people find this movie touching or not largely depends on their own life experiences.","zh":"人们觉得这部电影感不感人，很大程度上取决于他们自己的人生经历。"},{"en":"Whether students find a subject interesting or not largely depends on the way the teacher teaches it.","zh":"学生觉得一门课有没有意思，很大程度上取决于老师的授课方式。"}]},{"pattern":"To compensate for ..., sb. do sth. more than is good for sb.","explanation":"","original":{"en":"To compensate for his unpleasant experiences in hospital, the man drank a little more than was good for him.","zh":"为了补偿他在医院的不愉快经历，这个男人喝得有点多，对身体不太好。"},"examples":[{"en":"To compensate for the time he wasted playing games last month, the boy studied much longer than was good for him every day before the exam.","zh":"为了补偿上个月玩游戏浪费的时间，这个男孩在考试前每天学习的时间长得对身体都不好。"},{"en":"To compensate for missing her daughter's birthday, the mother bought many gifts more than were good for the child.","zh":"为了弥补错过了女儿的生日，这位妈妈买了太多对孩子并不好的礼物。"}]},{"pattern":"The following example of ... will enable you to judge for yourself.","explanation":"","original":{"en":"The following example of 'sick humour' will enable you to judge for yourself.","zh":"下面这个“黑色幽默”的例子能让你自己做出判断。"},"examples":[{"en":"The following example of the new policy's effect will enable you to judge for yourself whether it is beneficial.","zh":"下面这个关于新政策效果的例子能让你自己判断它是否有益。"},{"en":"The following example of the product's practical use will enable you to judge for yourself if it is worth buying.","zh":"下面这个关于产品实际使用的例子能让你自己判断它是否值得购买。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“吸引力，感染力” 对应的单词是？","hint":"noun · /əˈpiːl/","options":["odd","depict","diagnose","appeal"],"answer":3,"explain":"appeal · /əˈpiːl/ · noun · 吸引力，感染力。表示人或事物具有的吸引他人的特质，常用搭配have appeal to sb.","source":{"kind":"vocab","word":"appeal"},"id":"b3-u29-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：纠缠，烦扰","hint":"/ˈpestə(r)/ · verb","answer":"pester","placeholder":"输入英文单词","explain":"pester · /ˈpestə(r)/ · verb · 纠缠，烦扰。指反复打扰、纠缠某人以达到自己的目的，常用搭配pester sb. to do sth.或pester sb. for sth.","source":{"kind":"vocab","word":"pester"},"id":"b3-u29-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Be careful not to _____ the wet floor when you enter the room.","hint":"进房间的时候小心别在湿地板上滑倒。","answer":"slip on","placeholder":"输入缺失的短语","explain":"slip on：表示“在…上滑倒”，后接表示路面、地面的名词，强调滑倒的地点/原因（进房间的时候小心别在湿地板上滑倒。）","source":{"kind":"phrase","phrase":"slip on"},"id":"b3-u29-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Many people find this sort of _____ distasteful.","hint":"许多人觉得这种笑话令人反感。","answer":"joke","placeholder":"输入缺失的单词","explain":"Many people find this sort of joke distasteful. — 许多人觉得这种笑话令人反感。","source":{"kind":"sentence","en":"Many people find this sort of joke distasteful."},"id":"b3-u29-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来对前面的名词或整个句子进行补充说明，去掉从句后主句依然完整，从句和主句之间通常用逗号隔开” 描述的是哪个语法点？","hint":"主句 + , + which/who + 从句部分","options":["would rather ... than ... 结构","定语从句（which/who引导的非限定性定语从句）","虚拟语气在条件状语从句中的用法（与过去事实相反）","双重否定疑问句 (Negative Question)"],"answer":1,"explain":"定语从句（which/who引导的非限定性定语从句）：主句 + , + which/who + 从句部分：which指代事物或前面整句话的内容，who指代人，不能用that引导非限定性定语从句，用来提供额外的补充信息","source":{"kind":"grammar","title":"定语从句（which/who引导的非限定性定语从句）"},"id":"b3-u29-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nMany people find this sort of joke distasteful.","hint":"","options":["然而，与此同时，昆虫又有着奇特的魅力。","瑞典已逐步建立起一套完善的制度来保护公民不受专横或渎职的政府官员的侵害。","许多人觉得这种笑话令人反感。","猫总是能吸引人类。"],"answer":2,"explain":"Many people find this sort of joke distasteful. — 许多人觉得这种笑话令人反感。","source":{"kind":"sentence","en":"Many people find this sort of joke distasteful."},"id":"b3-u29-q06"}]},{"id":"b3-u30","book":3,"unit":30,"key":"30","lessonFrom":30,"lessonTo":30,"title":"The Death of a Ghost","titleZh":"幽灵之死","question":"Why did the two brothers keep the secret?","sentences":[{"en":"For years, villagers believed that Endley farm was haunted.","zh":"多年来，村民们一直认为恩德利农场闹鬼。","t":13.75},{"en":"The farm was owned by two brothers, Joe and Bob Cox.","zh":"这个农场归乔和鲍勃·科克斯两兄弟所有。","t":18.87},{"en":"They employed a few farmhands, but no one was willing to work there long.","zh":"他们雇了一些农场工人，但没有人愿意在那里长时间工作。","t":23.74},{"en":"Every time a worker gave up his job, he told the same story.","zh":"每次有工人辞职，他们都会讲同样的故事。","t":29.26},{"en":"Farm labourers said that they always woke up to find that work had been done overnight.","zh":"农场工人说，他们醒来时总是发现工作已经在一夜之间完成了。","t":34.95},{"en":"Hay had been cut and cowsheds had been cleaned.","zh":"干草被割了，牛棚也被清理了。","t":41.59},{"en":"A farm worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight.","zh":"一位彻夜未眠的农场工人声称在月光下看到一个身影在割玉米。","t":46.03},{"en":"In time, it became an accepted fact that the Cox brothers employed a conscientious ghost that did most of their work for them.","zh":"渐渐地，科克斯兄弟雇佣了一个尽职尽责的幽灵为他们做了大部分工作，这成了一个公认的事实。","t":53.64},{"en":"No one suspected that there might be someone else on the farm who had never been seen.","zh":"没有人怀疑农场上可能还有其他人从未被见过。","t":64.02},{"en":"This was indeed the case.","zh":"事实确实如此。","t":70.07},{"en":"A short time ago, villagers were astonished to learn that the ghost of Endley had died.","zh":"不久前，村民们惊讶地得知恩德利的幽灵已经死了。","t":72.81},{"en":"Everyone went to the funeral, for the 'ghost' was none other than Eric Cox,","zh":"所有人都去参加了葬礼，因为那个“幽灵”不是别人，正是埃里克·科克斯，","t":80},{"en":"a third brother who was supposed to have died as a young man.","zh":"据说他年轻时就去世了的第三个兄弟。","t":86.85},{"en":"After the funeral, Joe and Bob revealed a secret which they had kept for over fifty years.","zh":"葬礼结束后，乔和鲍勃揭露了一个他们保守了五十多年的秘密。","t":91.43},{"en":"Eric had been the eldest son of the family, very much older than his two brothers.","zh":"埃里克是家里的长子，比他的两个兄弟大得多。","t":99.48},{"en":"He had been obliged to join the army during the Second World War.","zh":"第二次世界大战期间，他被迫参军。","t":105.49},{"en":"As he hated army life, he decided to desert his regiment.","zh":"由于他厌恶军队生活，他决定开小差。","t":110.25},{"en":"When he learnt that he would be sent abroad,","zh":"当他得知自己将被派往国外时，","t":116.13},{"en":"he returned to the farm and his father hid him until the end of the war.","zh":"他回到了农场，他的父亲把他藏起来直到战争结束。","t":118.99},{"en":"Fearing the authorities, Eric remained in hiding after the war as well.","zh":"由于害怕当局，埃里克在战后也一直躲藏着。","t":124.41},{"en":"His father told everybody that Eric had been killed in action.","zh":"他的父亲告诉所有人埃里克在战斗中牺牲了。","t":130.36},{"en":"The only other people who knew the secret were Joe and Bob.","zh":"唯一知道这个秘密的其他人是乔和鲍勃。","t":135.03},{"en":"They did not even tell their wives.","zh":"他们甚至没有告诉他们的妻子。","t":139.49},{"en":"When their father died they thought it their duty to keep Eric in hiding.","zh":"当他们的父亲去世后，他们认为有责任继续把埃里克藏起来。","t":142.69},{"en":"All these years, Eric had lived as a recluse.","zh":"这么多年来，埃里克一直过着隐居生活。","t":147.7},{"en":"He used to sleep during the day and work at night,","zh":"他白天睡觉，晚上工作，","t":152.66},{"en":"quite unaware of the fact that he had become the ghost of Endley.","zh":"完全没有意识到自己已经成为了恩德利的幽灵。","t":155.66},{"en":"When he died, however, his brothers found it impossible to keep the secret any longer.","zh":"然而，当他去世后，他的兄弟们发现再也无法保守这个秘密了。","t":160.6}],"vocab":[{"word":"haunt","phonetic":"/hɔːnt/","meanings":[{"pos":"verb","meaning":"（鬼魂）出没于（某地）","usage":"常用于被动语态，表示某地被认为有鬼魂出没"},{"pos":"verb","meaning":"萦绕在心头，使困扰","usage":"表示不愉快的回忆或想法一直出现在脑海中"}]},{"word":"farmhand","phonetic":"/ˈfɑːmhænd/","meanings":[{"pos":"noun","meaning":"农场工人，雇农","usage":"指受雇在农场从事体力劳动的人"}]},{"word":"labourer","phonetic":"/ˈleɪbərə(r)/","meanings":[{"pos":"noun","meaning":"体力劳动者，工人","usage":"尤指从事户外重体力工作的人，美式拼写为laborer"}]},{"word":"overnight","phonetic":"/ˌəʊvəˈnaɪt/","meanings":[{"pos":"adverb","meaning":"在夜间，一夜之间","usage":"修饰动词，表示动作发生在夜间"},{"pos":"adjective","meaning":"夜间的，只供一晚的","usage":"修饰名词，描述与夜间相关的事物"}]},{"word":"cowshed","phonetic":"/ˈkaʊʃed/","meanings":[{"pos":"noun","meaning":"牛棚，牛舍","usage":"指农场里饲养奶牛的建筑"}]},{"word":"conscientious","phonetic":"/ˌkɒnʃiˈenʃəs/","meanings":[{"pos":"adjective","meaning":"认真的，尽责的，勤恳的","usage":"用于形容人做事认真负责，追求尽善尽美"}]},{"word":"suspect","phonetic":"/səˈspekt/","meanings":[{"pos":"verb","meaning":"怀疑，猜疑","usage":"后可接that从句，指猜想某事可能存在或属实"}]},{"word":"astonish","phonetic":"/əˈstɒnɪʃ/","meanings":[{"pos":"verb","meaning":"使惊讶，使吃惊","usage":"主语通常为事物，宾语为人，常用结构be astonished to do/that"}]},{"word":"funeral","phonetic":"/ˈfjuːnərəl/","meanings":[{"pos":"noun","meaning":"葬礼，丧礼","usage":"指为死者举行的安葬仪式"}]},{"word":"reveal","phonetic":"/rɪˈviːl/","meanings":[{"pos":"verb","meaning":"揭露，透露，泄露","usage":"指将此前保密的信息公之于众，后可接名词或that从句"}]},{"word":"oblige","phonetic":"/əˈblaɪdʒ/","meanings":[{"pos":"verb","meaning":"迫使，责成","usage":"常用被动结构be obliged to do sth，表示因法律、义务等不得不做某事"}]},{"word":"desert","phonetic":"/dɪˈzɜːt/","meanings":[{"pos":"verb","meaning":"擅离（部队），开小差","usage":"指军人未经允许离开所属部队，是违法行为"}]},{"word":"regiment","phonetic":"/ˈredʒɪmənt/","meanings":[{"pos":"noun","meaning":"（军队的）团","usage":"指军队的一级编制单位"}]},{"word":"authority","phonetic":"/ɔːˈθɒrəti/","meanings":[{"pos":"noun","meaning":"当局，官方","usage":"表示此含义时常用复数形式the authorities"}]},{"word":"recluse","phonetic":"/rɪˈkluːs/","meanings":[{"pos":"noun","meaning":"隐居者，隐士","usage":"指选择独自生活、避免与他人接触的人"}]}],"phrases":[{"phrase":"give up one's job","usage":"表示辞职、放弃工作，可用于主动离职的场景","examples":[{"en":"He gave up his job in the city to move back to his hometown.","zh":"他辞去了城里的工作，搬回了家乡。"}]},{"phrase":"stay up all night","usage":"表示熬夜，一整晚不睡觉，强调夜间保持清醒的状态","examples":[{"en":"I had to stay up all night to finish the report before the deadline.","zh":"我不得不熬一整晚，在截止日期前完成报告。"}]},{"phrase":"claim to have done sth","usage":"声称曾经做过某事，to have done是不定式的完成式，表示动作发生在claim之前","examples":[{"en":"The man claimed to have seen a UFO flying over the park last week.","zh":"这名男子声称上周看到一个不明飞行物飞过公园上空。"}]},{"phrase":"in time","usage":"表示“最终，经过一段时间之后”，强调经过一段时间后某情况发生","examples":[{"en":"In time, everyone forgot about the argument and became friends again.","zh":"最终，所有人都忘记了那次争吵，又成了朋友。"}]},{"phrase":"none other than","usage":"表示“不是别人，正是……”，用于强调某人的身份出人意料","examples":[{"en":"The winner of the competition was none other than my little sister.","zh":"比赛的获胜者不是别人，正是我的小妹妹。"}]},{"phrase":"be supposed to have done sth","usage":"表示“被认为已经做了某事”，暗含该认知可能与事实不符的含义","examples":[{"en":"The ancient temple was supposed to have been destroyed in the war, but it still exists.","zh":"人们本以为这座古庙已经在战争中被毁了，但它依然存在。"}]},{"phrase":"in action","usage":"表示“在战斗中，在行动中”，此处指军事作战场景","examples":[{"en":"Many soldiers were reported missing in action after the battle.","zh":"战斗结束后，许多士兵被报失踪。"}]},{"phrase":"in hiding","usage":"表示“躲藏着，隐藏着”，是固定搭配，描述躲避他人的状态","examples":[{"en":"The witness remained in hiding until the criminal was arrested.","zh":"在罪犯被逮捕之前，证人一直躲着不露面。"}]},{"phrase":"unaware of","usage":"表示“不知道，没意识到”，可作状语或表语，后接名词或名词性从句","examples":[{"en":"He walked straight past his teacher, completely unaware of her presence.","zh":"他径直从老师身边走过，完全没意识到她在那里。"}]}],"grammar":[{"title":"过去完成时","definition":"表示过去某个时间或动作之前已经发生或完成的动作，即“过去的过去”","structure":"had + 动词过去分词","usage":"常用于描述在过去某个已知事件之前发生的背景事件，常和after, before, until等引导的时间状语连用","examples":[{"en":"Eric had been the eldest son of the family, very much older than his two brothers.","zh":"埃里克是家里的长子，比他的两个弟弟大很多。"},{"en":"He had been obliged to join the army during the Second World War.","zh":"第二次世界大战期间，他被迫参军。"}]},{"title":"it作形式主语/形式宾语","definition":"当句子的真正主语或宾语是不定式、动名词或从句时，为了避免句子头重脚轻，用it作形式上的主语或宾语，真正的主语/宾语放在句尾","structure":"作形式主语：It + 谓语 + 名词/形容词 + 真正主语（不定式/that从句）；作形式宾语：主语 + 动词 + it + 宾补 + 真正宾语（不定式/that从句）","usage":"可让句子结构更平衡，符合英语表达习惯","examples":[{"en":"It became an accepted fact that the Cox brothers employed a conscientious ghost.","zh":"考克斯兄弟雇了一个勤恳的鬼魂，这成了人们公认的事实。"},{"en":"His brothers found it impossible to keep the secret any longer.","zh":"他的弟弟们发现再也没法保守这个秘密了。"}]},{"title":"used to do 结构","definition":"表示过去经常性、习惯性的动作或存在的状态，且该动作或状态现在已经不再发生或存在","structure":"主语 + used to + 动词原形","usage":"用于今昔对比，强调过去的情况与现在不同","examples":[{"en":"He used to sleep during the day and work at night.","zh":"他过去常常白天睡觉，晚上干活。"},{"en":"I used to swim in this lake when I was a child.","zh":"我小时候经常在这个湖里游泳。"}]}],"patterns":[{"pattern":"Every time + 从句, 主句","explanation":"","original":{"en":"Every time a worker gave up his job, he told the same story.","zh":"每次有工人辞工，都会讲同样的事。"},"examples":[{"en":"Every time it rains, the old street becomes very muddy.","zh":"每次下雨，这条老街道就会变得非常泥泞。"},{"en":"Every time I visit my grandmother, she prepares a lot of delicious food for me.","zh":"每次我去看望奶奶，她都会给我准备很多好吃的。"}]},{"pattern":"No one suspected that + 从句","explanation":"","original":{"en":"No one suspected that there might be someone else on the farm who had never been seen.","zh":"没有人想到农场里可能还有一个从未露过面的人。"},"examples":[{"en":"No one suspected that the quiet young man was actually a famous painter.","zh":"没有人想到那个安静的年轻人其实是一位著名画家。"},{"en":"No one suspected that the small village hid such a beautiful secret garden.","zh":"没有人想到这个小村庄里藏着这么漂亮的秘密花园。"}]},{"pattern":"When + 时间状语从句, 主语 + think/find + it + 名词/形容词 + to do sth","explanation":"","original":{"en":"When their father died they thought it their duty to keep Eric in hiding.","zh":"父亲去世后，他们认为有责任继续把埃里克藏起来。"},"examples":[{"en":"When he moved to this city, he found it difficult to adapt to the fast-paced life.","zh":"搬到这个城市后，他发现很难适应这里快节奏的生活。"},{"en":"When we participate in group activities, we all think it important to respect others' opinions.","zh":"我们参加集体活动时，都认为尊重他人的意见很重要。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“当局，官方” 对应的单词是？","hint":"noun · /ɔːˈθɒrəti/","options":["forbidding","suspect","overland","authority"],"answer":3,"explain":"authority · /ɔːˈθɒrəti/ · noun · 当局，官方。表示此含义时常用复数形式the authorities","source":{"kind":"vocab","word":"authority"},"id":"b3-u30-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：认真的，尽责的，勤恳的","hint":"/ˌkɒnʃiˈenʃəs/ · adjective","answer":"conscientious","placeholder":"输入英文单词","explain":"conscientious · /ˌkɒnʃiˈenʃəs/ · adjective · 认真的，尽责的，勤恳的。用于形容人做事认真负责，追求尽善尽美","source":{"kind":"vocab","word":"conscientious"},"id":"b3-u30-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, everyone forgot about the argument and became friends again.","hint":"最终，所有人都忘记了那次争吵，又成了朋友。","answer":"in time","placeholder":"输入缺失的短语","explain":"in time：表示“最终，经过一段时间之后”，强调经过一段时间后某情况发生（最终，所有人都忘记了那次争吵，又成了朋友。）","source":{"kind":"phrase","phrase":"in time"},"id":"b3-u30-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：They employed a few farmhands, but no one was willing to _____ there long.","hint":"他们雇了一些农场工人，但没有人愿意在那里长时间工作。","answer":"work","placeholder":"输入缺失的单词","explain":"They employed a few farmhands, but no one was willing to work there long. — 他们雇了一些农场工人，但没有人愿意在那里长时间工作。","source":{"kind":"sentence","en":"They employed a few farmhands, but no one was willing to work there long."},"id":"b3-u30-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当句子的真正主语或宾语是不定式、动名词或从句时，为了避免句子头重脚轻，用it作形式上的主语或宾语，真正的主语/宾语放在句尾” 描述的是哪个语法点？","hint":"作形式主语：It + 谓语 + 名词/形容词 + 真正主语（不定式/that从句）；作形式宾语：主语 + 动词 + it + 宾补 + 真正宾语（不定式/that从句）","options":["间接宾语和直接宾语 (Indirect and Direct Objects)","As引导的时间状语从句","it作形式主语/形式宾语","as if 引导的方式状语从句"],"answer":2,"explain":"it作形式主语/形式宾语：作形式主语：It + 谓语 + 名词/形容词 + 真正主语（不定式/that从句）；作形式宾语：主语 + 动词 + it + 宾补 + 真正宾语（不定式/that从句）：可让句子结构更平衡，符合英语表达习惯","source":{"kind":"grammar","title":"it作形式主语/形式宾语"},"id":"b3-u30-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThey did not even tell their wives.","hint":"","options":["他们甚至没有告诉他们的妻子。","这些孩子不再是五个新的家庭成员，而是立刻变成了商品。","她撞到了家具，嘴里不停地咕哝着关于客人的话。","我们很幸运，只有较低的田地，"],"answer":0,"explain":"They did not even tell their wives. — 他们甚至没有告诉他们的妻子。","source":{"kind":"sentence","en":"They did not even tell their wives."},"id":"b3-u30-q06"}]},{"id":"b3-u31","book":3,"unit":31,"key":"31","lessonFrom":31,"lessonTo":31,"title":"A Lovable Eccentric","titleZh":"可爱的怪人","question":"Why did the shop assistant refuse to serve Dickie?","sentences":[{"en":"True eccentrics never deliberately set out to draw attention to themselves.","zh":"真正的怪人从不刻意引人注目。","t":16.37},{"en":"They disregard social conventions without being conscious that they are doing anything extraordinary.","zh":"他们无视社会习俗，却没意识到自己在做任何非凡的事情。","t":22.11},{"en":"This invariably wins them the love and respect of others, for they add colour to the dull routine of everyday life.","zh":"这总能让他们赢得他人的爱戴和尊重，因为他们为平淡的日常生活增添了色彩。","t":29.72},{"en":"Up to the time of his death, Richard Colson was one of the most notable figures in our town.","zh":"直到去世，理查德·科尔森都是我们镇上最著名的人物之一。","t":40.57},{"en":"He was a shrewd and wealthy businessman,","zh":"他是一位精明富有的商人，","t":47.86},{"en":"but most people in the town hardly knew anything about this side of his life.","zh":"但镇上大多数人对他生活的这一面几乎一无所知。","t":48.62},{"en":"He was known to us all as Dickie and his eccentricity had become legendary long before he died.","zh":"他被我们称为迪基，他的怪癖在他去世前很久就已成为传奇。","t":57.14},{"en":"Dickie disliked snobs intensely.","zh":"迪基非常讨厌势利小人。","t":65.8},{"en":"Though he owned a large car, he hardly ever used it, preferring always to go on foot.","zh":"尽管他有一辆大车，但他几乎从不用它，总是喜欢步行。","t":68.92},{"en":"Even when it was raining heavily, he refused to carry an umbrella.","zh":"即使下大雨，他也不撑伞。","t":75.83},{"en":"One day, he walked into an expensive shop after having been caught in a particularly heavy shower.","zh":"一天，他在一场大雨中淋湿后走进一家昂贵的商店。","t":81.11},{"en":"He wanted to buy a ￡300 watch for his wife,","zh":"他想为妻子买一块300英镑的手表，","t":89.15},{"en":"but he was in such a bedraggled condition that an assistant refused to serve him.","zh":"但他衣衫褴褛，店员拒绝为他服务。","t":93.97},{"en":"Dickie left the shop without a word and returned carrying a large cloth bag.","zh":"迪基一言不发地离开了商店，然后提着一个大布袋回来了。","t":100.84},{"en":"As it was extremely heavy, he dumped it on the counter.","zh":"因为袋子很重，他把它扔在柜台上。","t":107.2},{"en":"The assistant asked him to leave, but Dickie paid no attention to him and requested to see the manager.","zh":"店员让他离开，但迪基没有理会他，要求见经理。","t":111.79},{"en":"Recognizing who the customer was,","zh":"经理认出了这位顾客，","t":120.08},{"en":"the manager was most apologetic and reprimanded the assistant severely.","zh":"非常抱歉，并严厉训斥了店员。","t":122.94},{"en":"When Dickie was given the watch, he presented the assistant with the cloth bag.","zh":"当迪基拿到手表时，他把布袋递给了店员。","t":129.63},{"en":"It contained ￡300 in pennies.","zh":"里面装着300英镑的便士。","t":135.59},{"en":"He insisted on the assistant's counting the money before he left--30, 000 pennies in all!","zh":"他坚持要店员在他离开前数清钱——总共3万枚便士！","t":140.43},{"en":"On another occasion, he invited a number of important critics to see his private collection of modern paintings.","zh":"另一次，他邀请了一些重要的评论家参观他的现代绘画私人收藏。","t":148.76},{"en":"This exhibition received a great deal of attention in the press,","zh":"这次展览受到了媒体的广泛关注，","t":157.2},{"en":"for though the pictures were supposed to be the work of famous artists,","zh":"因为尽管这些画被认为是著名艺术家的作品，","t":161.74},{"en":"they had in fact been painted by Dickie.","zh":"但实际上它们是迪基画的。","t":166.56},{"en":"It took him four years to stage this elaborate joke simply to prove that critics do not always know what they are talking about.","zh":"他花了四年时间策划这个精心设计的玩笑，只是为了证明评论家并不总是知道他们在说什么。","t":170.63}],"vocab":[{"word":"eccentric","phonetic":"/ɪkˈsentrɪk/","meanings":[{"pos":"noun","meaning":"古怪的人；行为怪异的人","usage":"指行为偏离常规、特点鲜明的人，文中带有褒义，指可爱的怪人"},{"pos":"adjective","meaning":"古怪的；异乎寻常的","usage":"用来描述行为、性格等不符合常规的"}]},{"word":"deliberately","phonetic":"/dɪˈlɪbərətli/","meanings":[{"pos":"adverb","meaning":"故意地；蓄意地","usage":"强调行为是有目的、刻意做出的"}]},{"word":"disregard","phonetic":"/ˌdɪsrɪˈɡɑːd/","meanings":[{"pos":"verb","meaning":"不顾；漠视；不理会","usage":"后常接规则、习俗、他人意见等名词，指故意不遵守或不重视"}]},{"word":"convention","phonetic":"/kənˈvenʃn/","meanings":[{"pos":"noun","meaning":"习俗；常规；惯例","usage":"指社会普遍接受的行为准则或传统做法"}]},{"word":"invariably","phonetic":"/ɪnˈveəriəbli/","meanings":[{"pos":"adverb","meaning":"始终如一地；一贯地；总是","usage":"强调情况几乎没有例外，总是发生"}]},{"word":"notable","phonetic":"/ˈnəʊtəbl/","meanings":[{"pos":"adjective","meaning":"显要的；显著的；值得注意的","usage":"用来形容人或事物因特点突出而被大众知晓"}]},{"word":"shrewd","phonetic":"/ʃruːd/","meanings":[{"pos":"adjective","meaning":"精明的；敏锐的；有判断力的","usage":"常用来形容人在商业、判断局势等方面头脑精明"}]},{"word":"legendary","phonetic":"/ˈledʒəndri/","meanings":[{"pos":"adjective","meaning":"传奇的；大名鼎鼎的","usage":"形容人或事因极具特点而被广泛谈论，像传说一样有名"}]},{"word":"snob","phonetic":"/snɒb/","meanings":[{"pos":"noun","meaning":"势利小人；谄上欺下的人","usage":"指以地位、财富取人，看不起普通人的人"}]},{"word":"intensely","phonetic":"/ɪnˈtensli/","meanings":[{"pos":"adverb","meaning":"强烈地；极度地","usage":"用来加强情绪、感受的程度"}]},{"word":"bedraggled","phonetic":"/bɪˈdræɡld/","meanings":[{"pos":"adjective","meaning":"湿脏的；凌乱的","usage":"常形容人被雨淋湿后衣服脏乱、外表邋遢的状态"}]},{"word":"reprimand","phonetic":"/ˈreprɪmɑːnd/","meanings":[{"pos":"verb","meaning":"训斥；斥责","usage":"指上级对下属、长辈对晚辈的正式严厉批评"}]},{"word":"critic","phonetic":"/ˈkrɪtɪk/","meanings":[{"pos":"noun","meaning":"批评家；评论家","usage":"特指对艺术、文学、音乐等进行专业评论的人"}]},{"word":"elaborate","phonetic":"/ɪˈlæbərət/","meanings":[{"pos":"adjective","meaning":"精心制作的；详尽的","usage":"形容计划、事件等经过了周密的安排和设计"}]}],"phrases":[{"phrase":"set out to do sth","usage":"表示“打算、着手做某事”，强调有明确的目的去做某件事","examples":[{"en":"True eccentrics never deliberately set out to draw attention to themselves.","zh":"真正的怪人从不刻意去吸引他人的注意。"},{"en":"She set out to break the world record in the long jump.","zh":"她立志要打破跳远的世界纪录。"}]},{"phrase":"draw attention to sb/sth","usage":"表示“吸引对……的注意”，主语可以是人或事物","examples":[{"en":"The poster is designed to draw attention to the problem of global warming.","zh":"这张海报旨在吸引人们关注全球变暖的问题。"},{"en":"He tried not to draw attention to his mistake in the report.","zh":"他尽量不让别人注意到他报告里的错误。"}]},{"phrase":"add colour to","usage":"表示“给……增添趣味/色彩”，用比喻义表示让原本平淡的事物变得生动","examples":[{"en":"They add colour to the dull routine of everyday life.","zh":"他们给平淡的日常生活增添了趣味。"},{"en":"Her lively stories added colour to the boring meeting.","zh":"她生动的故事给无聊的会议增添了乐趣。"}]},{"phrase":"be caught in","usage":"表示“遭遇、陷入（坏天气、困境等）”，通常用于被动结构","examples":[{"en":"He walked into an expensive shop after having been caught in a particularly heavy shower.","zh":"他遇上了一场特别大的阵雨，之后走进了一家高档商店。"},{"en":"We were caught in a traffic jam on the way to the airport.","zh":"我们在去机场的路上遇上了交通堵塞。"}]},{"phrase":"pay no attention to","usage":"表示“不理会、不注意……”，后面接人或事物","examples":[{"en":"The assistant asked him to leave, but Dickie paid no attention to him and requested to see the manager.","zh":"店员让他离开，但迪基理都不理他，要求见经理。"},{"en":"Pay no attention to what others say about your choice.","zh":"别理会别人对你的选择的议论。"}]},{"phrase":"insist on","usage":"表示“坚持要求、坚决主张”，后接名词或动词的-ing形式","examples":[{"en":"He insisted on the assistant's counting the money before he left.","zh":"他坚持要店员数清楚钱再离开。"},{"en":"My mother insists on walking for an hour after dinner every day.","zh":"我妈妈坚持每天饭后散步一小时。"}]},{"phrase":"a great deal of","usage":"表示“大量的，许多的”，后接不可数名词","examples":[{"en":"This exhibition received a great deal of attention in the press.","zh":"这次展览受到了媒体的大量关注。"},{"en":"The project requires a great deal of time and effort to complete.","zh":"这个项目需要投入大量的时间和精力才能完成。"}]},{"phrase":"be supposed to","usage":"表示“被认为；应该”，可以指人们普遍的看法，也可以指义务、规定","examples":[{"en":"Though the pictures were supposed to be the work of famous artists, they had in fact been painted by Dickie.","zh":"虽然这些画被认为是著名艺术家的作品，但实际上都是迪基画的。"},{"en":"You are supposed to arrive at the office before 9 o'clock every morning.","zh":"你应该每天早上九点之前到办公室。"}]}],"grammar":[{"title":"现在分词的完成被动式","definition":"表示动作发生在主句动作之前，且与逻辑主语之间是被动关系，强调动作的完成和被动属性","structure":"having been + 过去分词，常在句中作时间、原因等状语","usage":"当从句的主语和主句主语一致，且从句动作先于主句动作发生、主语是动作的承受者时使用，可以替换相应的被动语态的状语从句","examples":[{"en":"He walked into an expensive shop after having been caught in a particularly heavy shower.","zh":"他遇上了一场特别大的阵雨，之后走进了一家高档商店。"},{"en":"Having been told many times, he still couldn't understand the rule.","zh":"已经被告知了很多次，他还是不懂这个规则。"}]},{"title":"for引导的原因状语从句","definition":"属于并列连词引导的状语从句，用来补充说明前一句话的原因或提供推断的理由，语气比because弱","structure":"主句 + for + 原因从句","usage":"通常不放在句首，而是放在主句之后，用逗号与主句隔开，是对前面内容的补充解释，而非直接的因果关系","examples":[{"en":"This invariably wins them the love and respect of others, for they add colour to the dull routine of everyday life.","zh":"这总是能为他们赢得别人的喜爱和尊重，因为他们给平淡的日常生活增添了趣味。"},{"en":"The days are short, for it is now December.","zh":"白天很短，因为现在是十二月了。"}]},{"title":"though引导的让步状语从句","definition":"用来表示“虽然、尽管”，引导的从句与主句的内容存在转折关系，突出主句内容的合理性","structure":"Though + 从句，主句 / 主句 + though + 从句","usage":"可以放在句首或句中，不能和but同时出现在同一个句子里，但可以和yet、still等词搭配","examples":[{"en":"Though he owned a large car, he hardly ever used it, preferring always to go on foot.","zh":"虽然他有一辆大轿车，但他几乎从来不用，总喜欢步行。"},{"en":"Though the task was very difficult, they managed to finish it on time.","zh":"尽管任务非常困难，他们还是设法按时完成了。"}]}],"patterns":[{"pattern":"... had become legendary long before ...","explanation":"","original":{"en":"He was known to us all as Dickie and his eccentricity had become legendary long before he died.","zh":"我们都叫他迪基，早在他去世之前，他的怪癖就已经传为美谈了。"},"examples":[{"en":"His songs had become popular long before he released his first album.","zh":"早在他发行第一张专辑之前，他的歌就已经很受欢迎了。"},{"en":"The small town's beautiful scenery had become famous long before it was developed as a tourist spot.","zh":"早在这个小镇被开发成旅游景点之前，它的美景就已经很有名了。"}]},{"pattern":"He was in such a ... condition that ...","explanation":"","original":{"en":"He wanted to buy a ￡300 watch for his wife, but he was in such a bedraggled condition that an assistant refused to serve him.","zh":"他想给妻子买一块价值300英镑的手表，但他当时浑身湿脏邋遢，店员拒绝为他服务。"},"examples":[{"en":"He was in such a tired condition that he fell asleep as soon as he got home.","zh":"他太累了，一到家就睡着了。"},{"en":"The old house was in such a dilapidated condition that no one wanted to rent it.","zh":"这栋老房子破败不堪，没人愿意租。"}]},{"pattern":"It took sb + 时间 + to do sth simply to prove that ...","explanation":"","original":{"en":"It took him four years to stage this elaborate joke simply to prove that critics do not always know what they are talking about.","zh":"他花了四年时间策划这个精心的玩笑，只是为了证明评论家并不总是知道自己在说什么。"},"examples":[{"en":"It took her three months to prepare for the speech contest simply to prove that she could speak English as well as others.","zh":"她花了三个月准备演讲比赛，只是为了证明她的英语能说得和别人一样好。"},{"en":"It took the team half a year to complete the experiment simply to prove that their theory was correct.","zh":"这个团队花了半年时间完成实验，只是为了证明他们的理论是正确的。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“习俗；常规；惯例” 对应的单词是？","hint":"noun · /kənˈvenʃn/","options":["authority","prize","restrict","convention"],"answer":3,"explain":"convention · /kənˈvenʃn/ · noun · 习俗；常规；惯例。指社会普遍接受的行为准则或传统做法","source":{"kind":"vocab","word":"convention"},"id":"b3-u31-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：显要的；显著的；值得注意的","hint":"/ˈnəʊtəbl/ · adjective","answer":"notable","placeholder":"输入英文单词","explain":"notable · /ˈnəʊtəbl/ · adjective · 显要的；显著的；值得注意的。用来形容人或事物因特点突出而被大众知晓","source":{"kind":"vocab","word":"notable"},"id":"b3-u31-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ what others say about your choice.","hint":"别理会别人对你的选择的议论。","answer":"pay no attention to","placeholder":"输入缺失的短语","explain":"pay no attention to：表示“不理会、不注意……”，后面接人或事物（别理会别人对你的选择的议论。）","source":{"kind":"phrase","phrase":"pay no attention to"},"id":"b3-u31-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：When Dickie was given the watch, he presented the assistant with the _____ bag.","hint":"当迪基拿到手表时，他把布袋递给了店员。","answer":"cloth","placeholder":"输入缺失的单词","explain":"When Dickie was given the watch, he presented the assistant with the cloth bag. — 当迪基拿到手表时，他把布袋递给了店员。","source":{"kind":"sentence","en":"When Dickie was given the watch, he presented the assistant with the cloth bag."},"id":"b3-u31-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示动作发生在主句动作之前，且与逻辑主语之间是被动关系，强调动作的完成和被动属性” 描述的是哪个语法点？","hint":"having been + 过去分词，常在句中作时间、原因等状语","options":["But连接的并列句","间接引语（陈述句的转换）","双关语 (Pun)","现在分词的完成被动式"],"answer":3,"explain":"现在分词的完成被动式：having been + 过去分词，常在句中作时间、原因等状语：当从句的主语和主句主语一致，且从句动作先于主句动作发生、主语是动作的承受者时使用，可以替换相应的被动语态的状语从句","source":{"kind":"grammar","title":"现在分词的完成被动式"},"id":"b3-u31-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nRecognizing who the customer was,","hint":"","options":["迪米特里立刻去了阿列科家，愤怒地指责他偷了羊。","那些老掉牙的旧习惯年复一年地以单调的规律重现。","看来狗很喜欢嚼钱！","经理认出了这位顾客，"],"answer":3,"explain":"Recognizing who the customer was, — 经理认出了这位顾客，","source":{"kind":"sentence","en":"Recognizing who the customer was,"},"id":"b3-u31-q06"}]},{"id":"b3-u32","book":3,"unit":32,"key":"32","lessonFrom":32,"lessonTo":32,"title":"A Lost Ship","titleZh":"一艘失踪的船","question":"Did the crew of the Elkor find what they were looking for? Why?","sentences":[{"en":"The salvage operation had been a complete failure.","zh":"打捞行动彻底失败了。","t":15.38},{"en":"The small ship, Elkor, which had been searching the Barents Sea for weeks, was on its way home.","zh":"“埃尔科”号这艘小船在巴伦支海域搜寻了几个星期后，正在返航的途中。","t":19.2},{"en":"A radio message from the mainland had been received by the ship's captain instructing him to give up the search.","zh":"船长收到了一份来自大陆的电报，指示他放弃搜寻。","t":26.72},{"en":"The captain knew that another attempt would be made later,","zh":"船长知道以后还会再进行一次尝试，","t":34.53},{"en":"for the sunken ship he was trying to find had been carrying a precious cargo of gold bullion.","zh":"因为他试图寻找的那艘沉船载有一批珍贵的金条。","t":38.1},{"en":"Despite the message, the captain of the Elkor decided to try once more.","zh":"尽管收到那份电报，“埃尔科”号的船长还是决定再试一次。","t":45.33},{"en":"The sea bed was scoured with powerful nets and there was tremendous excitement on board when a chest was raised from the bottom.","zh":"海底被强力拖网仔细搜寻，当一个箱子从海底被捞上来时，船上的人都非常兴奋。","t":51.89},{"en":"Though the crew were at first under the impression that the lost ship had been found,","zh":"虽然船员们最初以为找到了那艘失踪的船，","t":60.76},{"en":"the contents of the chest proved them wrong.","zh":"但箱子里的东西证明他们错了。","t":65.99},{"en":"What they had in fact found was a ship which had been sunk many years before.","zh":"事实上，他们找到的是一艘多年前就已经沉没的船。","t":69.52},{"en":"The chest contained the personal belongings of a seaman, Alan Fielding.","zh":"箱子里装着一个名叫艾伦·菲尔丁的海员的个人物品。","t":75.62},{"en":"There were books, clothing and photographs, together with letters which the seaman had once received from his wife.","zh":"里面有书、衣服和照片，还有海员以前从他妻子那里收到的信件。","t":80.76},{"en":"The captain of the Elkor ordered his men to salvage as much as possible from the wreck.","zh":"“埃尔科”号的船长命令他的船员尽可能多地从残骸中打捞物品。","t":88.34},{"en":"Nothing of value was found,","zh":"没找到什么有价值的东西，","t":94.32},{"en":"but the numerous items which were brought to the surface proved to be of great interest.","zh":"但打捞上来的许多物品却引起了人们极大的兴趣。","t":96.48},{"en":"From a heavy gun that was raised, the captain realized that the ship must have been a cruiser.","zh":"从打捞上来的一门重型火炮，船长意识到这艘船一定是一艘巡洋舰。","t":101.75},{"en":"In another chest which contained the belongings of a ship's officer,","zh":"在另一个箱子里，装着一名船上军官的物品，","t":108.01},{"en":"there was an unfinished letter which had been written on March 14th, 1943.","zh":"里面有一封写于1943年3月14日、尚未写完的信。","t":112.68},{"en":"The captain learnt from the letter that the name of the lost ship was the Karen.","zh":"船长从信中得知那艘失踪的船名叫“卡伦”号。","t":120.01},{"en":"The most valuable find of all was the ship's log book, parts of which it was still possible to read.","zh":"最有价值的发现是船上的航海日志，其中一部分仍然可以阅读。","t":125.21},{"en":"From this the captain was able to piece together all the information that had come to light.","zh":"从日志中，船长得以把所有已发现的信息拼凑起来。","t":133.41},{"en":"The Karen had been sailing in a convoy to Russia when she was torpedoed by an enemy submarine.","zh":"“卡伦”号当时正在驶往俄罗斯的护航船队中，结果被一艘敌方潜艇鱼雷击中。","t":139.06},{"en":"This was later confirmed by a naval official at the Ministry of Defence after the Elkor had returned home.","zh":"“埃尔科”号返回家园后，国防部的一名海军官员证实了这一点。","t":145.63},{"en":"All the items that were found were sent to the War Museum.","zh":"所有找到的物品都被送往战争博物馆。","t":153.16}],"vocab":[{"word":"salvage","phonetic":"/ˈsælvɪdʒ/","meanings":[{"pos":"verb","meaning":"打捞；抢救","usage":"指从沉船或废墟中救出财物"}]},{"word":"crew","phonetic":"/kruː/","meanings":[{"pos":"noun","meaning":"全体船员","usage":"指船上的所有工作人员"}]},{"word":"mainland","phonetic":"/ˈmeɪnlənd/","meanings":[{"pos":"noun","meaning":"大陆","usage":"指国家的主体部分，不包括岛屿"}]},{"word":"bullion","phonetic":"/ˈbʊliən/","meanings":[{"pos":"noun","meaning":"金条；银条","usage":"指未经加工的贵重金属"}]},{"word":"scour","phonetic":"/ˈskaʊə(r)/","meanings":[{"pos":"verb","meaning":"彻底搜索","usage":"指用工具或方法仔细搜寻某区域"}]},{"word":"tremendous","phonetic":"/trɪˈmendəs/","meanings":[{"pos":"adj","meaning":"巨大的；极大的","usage":"形容规模或程度非常大"}]},{"word":"belonging","phonetic":"/bɪˈlɒŋɪŋ/","meanings":[{"pos":"noun","meaning":"财产；所有物","usage":"常用复数形式，指个人物品"}]},{"word":"cruiser","phonetic":"/ˈkruːzə(r)/","meanings":[{"pos":"noun","meaning":"巡洋舰","usage":"一种军用舰船"}]},{"word":"torpedo","phonetic":"/tɔːˈpiːdəʊ/","meanings":[{"pos":"verb","meaning":"用鱼雷攻击","usage":"指用鱼雷击沉船只"}]},{"word":"convoy","phonetic":"/ˈkɒnvɔɪ/","meanings":[{"pos":"noun","meaning":"护航队；车队","usage":"指一起旅行或被护送的船队或车队"}]},{"word":"log book","phonetic":"/ˈlɒɡ bʊk/","meanings":[{"pos":"noun","meaning":"航海日志","usage":"记录船舶航行情况的日志"}]},{"word":"submarine","phonetic":"/ˌsʌbməˈriːn/","meanings":[{"pos":"noun","meaning":"潜水艇","usage":"指能在水下航行的船只"}]},{"word":"seabed","phonetic":"/ˈsiːbed/","meanings":[{"pos":"noun","meaning":"海底","usage":"指海洋的底部"}]},{"word":"sunken","phonetic":"/ˈsʌŋkən/","meanings":[{"pos":"adj","meaning":"沉没的","usage":"sink的过去分词作形容词用"}]},{"word":"piece together","phonetic":"/piːs təˈɡeðər/","meanings":[{"pos":"verb phrase","meaning":"拼凑；整合","usage":"指将零散的信息拼凑成完整画面"}]}],"phrases":[{"phrase":"give up the search","usage":"放弃搜索","examples":[{"en":"The captain was instructed to give up the search.","zh":"船长被指示放弃搜索。"}]},{"phrase":"on board","usage":"在船上","examples":[{"en":"There was tremendous excitement on board.","zh":"船上有极大的兴奋。"}]},{"phrase":"be under the impression","usage":"认为；以为","examples":[{"en":"The crew were at first under the impression that the lost ship had been found.","zh":"船员们最初以为找到了那艘失踪的船。"}]},{"phrase":"bring to the surface","usage":"打捞上来","examples":[{"en":"The numerous items were brought to the surface.","zh":"许多物品被打捞上来。"}]},{"phrase":"piece together","usage":"拼凑整合","examples":[{"en":"The captain was able to piece together all the information.","zh":"船长能够拼凑出所有的信息。"}]},{"phrase":"come to light","usage":"真相大白；被发现","examples":[{"en":"Information that had come to light was collected.","zh":"被揭露的信息被收集起来。"}]},{"phrase":"order sb to do sth","usage":"命令某人做某事","examples":[{"en":"The captain of the Elkor ordered his men to salvage as much as possible.","zh":"埃尔科号船长命令他的手下尽可能多地打捞。"}]},{"phrase":"search for","usage":"搜寻","examples":[{"en":"Elkor had been searching the Barents Sea for weeks.","zh":"埃尔科号已经在巴伦支海搜索了数周。"}]},{"phrase":"in fact","usage":"事实上","examples":[{"en":"What they had in fact found was a ship which had been sunk many years before.","zh":"他们实际上发现的是一艘很多年前沉没的船。"}]},{"phrase":"later confirmed","usage":"后来证实","examples":[{"en":"This was later confirmed by a naval official.","zh":"这后来被一位海军官员证实。"}]}],"grammar":[{"title":"过去完成进行时 (Past Perfect Continuous)","definition":"表示在过去某一时刻之前已经开始并持续到该时刻的动作，或刚刚结束的动作","structure":"had been + 动词-ing","usage":"用于描述持续进行的动作，常与for/during等时间词连用，强调动作的持续性","examples":[{"en":"Elkor had been searching the Barents Sea for weeks.","zh":"埃尔科号已经在巴伦支海搜索了数周。"}]},{"title":"过去完成时被动态 (Past Perfect Passive)","definition":"过去完成时的被动语态，表示在过去某时刻之前已经完成且承受动作的主语","structure":"had been + 过去分词","usage":"强调动作的完成性和被动性，主语是动作的承受者","examples":[{"en":"The sunken ship he was trying to find had been carrying a precious cargo of gold bullion.","zh":"他试图寻找的沉船一直载有贵重的金条。"}]}],"patterns":[{"pattern":"...had been + V-ing when...","explanation":"","original":{"en":"The sea bed was scoured with powerful nets and there was tremendous excitement on board when a chest was raised from the bottom.","zh":"用强力网搜寻海底，当一个箱子从海底被吊起时，船上非常兴奋。"},"examples":[{"en":"The police had been searching the area for hours when they finally found the missing child.","zh":"警察在该地区搜索了几个小时，终于找到了失踪的孩子。"}]},{"pattern":"Despite + n./v-ing, ...","explanation":"","original":{"en":"Despite the message, the captain of the Elkor decided to try once more.","zh":"尽管收到了消息，埃尔科号的船长决定再试一次。"},"examples":[{"en":"Despite the heavy rain, we continued our journey.","zh":"尽管下着大雨，我们继续赶路。"}]},{"pattern":"The captain/learnt realized that...","explanation":"","original":{"en":"The captain learnt from the letter that the name of the lost ship was the Karen.","zh":"船长从信中得知失踪船只的名字是凯伦号。"},"examples":[{"en":"The detective realized that the suspect had been lying.","zh":"侦探意识到嫌疑人一直在撒谎。"}]},{"pattern":"...had been + V-ing when + past simple","explanation":"","original":{"en":"The Karen had been sailing in a convoy to Russia when she was torpedoed by an enemy submarine.","zh":"凯伦号正在护航队中驶向俄罗斯时被敌方潜艇发射鱼雷击中。"},"examples":[{"en":"He had been driving for three hours when his car broke down.","zh":"他已经开了三个小时的车，这时他的车抛锚了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“巨大的；极大的” 对应的单词是？","hint":"adj · /trɪˈmendəs/","options":["suspect","tremendous","indulge","incompetent"],"answer":1,"explain":"tremendous · /trɪˈmendəs/ · adj · 巨大的；极大的。形容规模或程度非常大","source":{"kind":"vocab","word":"tremendous"},"id":"b3-u32-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：彻底搜索","hint":"/ˈskaʊə(r)/ · verb","answer":"scour","placeholder":"输入英文单词","explain":"scour · /ˈskaʊə(r)/ · verb · 彻底搜索。指用工具或方法仔细搜寻某区域","source":{"kind":"vocab","word":"scour"},"id":"b3-u32-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The captain was able to _____ all the information.","hint":"船长能够拼凑出所有的信息。","answer":"piece together","placeholder":"输入缺失的短语","explain":"piece together：拼凑整合（船长能够拼凑出所有的信息。）","source":{"kind":"phrase","phrase":"piece together"},"id":"b3-u32-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ was an unfinished letter which had been written on March 14th, 1943.","hint":"里面有一封写于1943年3月14日、尚未写完的信。","answer":"there","placeholder":"输入缺失的单词","explain":"there was an unfinished letter which had been written on March 14th, 1943. — 里面有一封写于1943年3月14日、尚未写完的信。","source":{"kind":"sentence","en":"there was an unfinished letter which had been written on March 14th, 1943."},"id":"b3-u32-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在过去某一时刻之前已经开始并持续到该时刻的动作，或刚刚结束的动作” 描述的是哪个语法点？","hint":"had been + 动词-ing","options":["used to do 结构","现在完成时 (Present Perfect Tense)","介词+关系代词引导的定语从句","过去完成进行时 (Past Perfect Continuous)"],"answer":3,"explain":"过去完成进行时 (Past Perfect Continuous)：had been + 动词-ing：用于描述持续进行的动作，常与for/during等时间词连用，强调动作的持续性","source":{"kind":"grammar","title":"过去完成进行时 (Past Perfect Continuous)"},"id":"b3-u32-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe Karen had been sailing in a convoy to Russia when she was torpedoed by an enemy submarine.","hint":"","options":["制造这些标记的游牧民族在最后一次冰河时期（约公元前35,000年开始，约公元前10,000年结束）靠狩猎和捕鱼为生。","“卡伦”号当时正在驶往俄罗斯的护航船队中，结果被一艘敌方潜艇鱼雷击中。","店员让他离开，但迪基没有理会他，要求见经理。","然而，一天晚上，我们的牧师突然惊醒：钟正在报时！"],"answer":1,"explain":"The Karen had been sailing in a convoy to Russia when she was torpedoed by an enemy submarine. — “卡伦”号当时正在驶往俄罗斯的护航船队中，结果被一艘敌方潜艇鱼雷击中。","source":{"kind":"sentence","en":"The Karen had been sailing in a convoy to Russia when she was torpedoed by an enemy submarine."},"id":"b3-u32-q06"}]},{"id":"b3-u33","book":3,"unit":33,"key":"33","lessonFrom":33,"lessonTo":33,"title":"A Day to Remember","titleZh":"值得纪念的一天","question":"What incident began the series of traffic accidents?","sentences":[{"en":"We have all experienced days when everything goes wrong.","zh":"我们都经历过事事不顺的日子。","t":15.47},{"en":"A day may begin well enough, but suddenly everything seems to get out of control.","zh":"一天也许开始得很好，但突然间一切似乎都失去了控制。","t":19.83},{"en":"What invariably happens is that a great number of things choose to go wrong at precisely the same moment.","zh":"事情总是这样，很多事情偏偏选择在同一时刻出错。","t":25.98},{"en":"It is as if a single unimportant event set up a chain of reactions.","zh":"仿佛一个微不足道的事件引发了一连串的连锁反应。","t":33.97},{"en":"Let us suppose that you are preparing a meal and keeping an eye on the baby at the same time.","zh":"假设你正在准备饭菜，同时还要照看婴儿。","t":39.93},{"en":"The telephone rings and this marks the prelude to an unforeseen series of catastrophes.","zh":"电话铃响了，这预示着一系列意想不到的灾难即将发生。","t":47.23},{"en":"While you are on the phone, the baby pulls the tablecloth off the table,","zh":"当你打电话的时候，婴儿把桌布从桌子上扯了下来，","t":55.44},{"en":"smashing half your best crockery and cutting himself in the process.","zh":"打碎了你一半最好的餐具，还把自己划伤了。","t":61.12},{"en":"You hang up hurriedly and attend to baby, crockery, etc.","zh":"你急忙挂断电话，去照看婴儿、餐具等。","t":66.49},{"en":"Meanwhile, the meal gets burnt.","zh":"与此同时，饭菜烧糊了。","t":71.9},{"en":"As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner.","zh":"好像这些还不足以让你落泪，你的丈夫又回来了，出乎意料地带了三位客人来吃晚饭。","t":74.62},{"en":"Things can go wrong on a big scale as a number of people recently discovered in Parramatta, a suburb of Sydney.","zh":"事情也会大规模地出错，正如最近在悉尼郊区帕拉马塔的一些人所发现的那样。","t":84.51},{"en":"During the rush hour one evening two cars collided and both drivers began to argue.","zh":"一天晚上，在交通高峰期，两辆汽车相撞，两位司机开始争吵起来。","t":93.52},{"en":"The woman immediately behind the two cars happened to be a learner.","zh":"紧跟在两辆车后面的一位女士碰巧是位新手司机。","t":101.09},{"en":"She suddenly got into a panic and stopped her car.","zh":"她突然惊慌失措，把车停了下来。","t":106.3},{"en":"This made the driver following her brake hard.","zh":"这使得跟在她后面的司机猛踩刹车。","t":110.97},{"en":"His wife was sitting beside him holding a large cake.","zh":"他的妻子坐在他旁边，手里拿着一个大蛋糕。","t":114.8},{"en":"As she was thrown forward,","zh":"当她向前扑去时，","t":119.08},{"en":"the cake went right through the windscreen and landed on the road.","zh":"蛋糕直接穿过挡风玻璃，落在了路上。","t":121.2},{"en":"Seeing a cake flying through the air,","zh":"看到一个蛋糕飞过空中，","t":126.53},{"en":"a lorry driver who was drawing up alongside the car, pulled up all of a sudden.","zh":"一位正把车开到汽车旁边的货车司机，突然把车停了下来。","t":129.42},{"en":"The lorry was loaded with empty beer bottles and hundreds of them slid off the back of the vehicle and on to the road.","zh":"货车上装满了空啤酒瓶，几百个瓶子从车后部滑落到路上。","t":136.17},{"en":"This led to yet another angry argument.","zh":"这又引发了另一场激烈的争吵。","t":145.47},{"en":"Meanwhile, the traffic piled up behind.","zh":"与此同时，后面的交通堵塞了。","t":149.11},{"en":"It took the police nearly an hour to get the traffic on the move again.","zh":"警察花了将近一个小时才让交通再次恢复通行。","t":153.46},{"en":"In the meantime, the lorry driver had to sweep up hundreds of broken bottles.","zh":"与此同时，货车司机不得不清扫数百个碎瓶子。","t":158.96},{"en":"Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake.","zh":"只有两只流浪狗从这场混乱中受益，因为它们贪婪地吞食了剩下的蛋糕。","t":165.57},{"en":"It was just one of those days!","zh":"真是倒霉的一天！","t":174.22}],"vocab":[{"word":"invariably","phonetic":"/ɪnˈveəriəbli/","meanings":[{"pos":"adverb","meaning":"始终如一地；一贯地；总是","usage":"用来描述几乎每次都会发生的情况，语气比always更正式"}]},{"word":"precisely","phonetic":"/prɪˈsaɪsli/","meanings":[{"pos":"adverb","meaning":"精确地；恰好；准确地","usage":"强调时间、数量等的准确性，可用于加强语气"}]},{"word":"prelude","phonetic":"/ˈpreljuːd/","meanings":[{"pos":"noun","meaning":"前奏；序幕；前兆","usage":"常与介词to搭配，指某个重大事件的开端或预兆"}]},{"word":"unforeseen","phonetic":"/ˌʌnfɔːˈsiːn/","meanings":[{"pos":"adjective","meaning":"未预见的；意外的","usage":"用来描述事先没有预料到的情况，通常修饰事件、问题等名词"}]},{"word":"catastrophe","phonetic":"/kəˈtæstrəfi/","meanings":[{"pos":"noun","meaning":"灾难；灾祸；不幸事件","usage":"可指重大的灾难，也可用于幽默地指代麻烦的小事"}]},{"word":"smash","phonetic":"/smæʃ/","meanings":[{"pos":"verb","meaning":"打碎；粉碎；猛烈撞击","usage":"既可以作及物动词也可以作不及物动词，强调破碎的剧烈程度"}]},{"word":"crockery","phonetic":"/ˈkrɒkəri/","meanings":[{"pos":"noun","meaning":"陶器；瓦器；餐具（杯、盘等的统称）","usage":"不可数名词，通常指陶瓷材质的餐具"}]},{"word":"collide","phonetic":"/kəˈlaɪd/","meanings":[{"pos":"verb","meaning":"碰撞；相撞；冲突","usage":"常与介词with搭配，指交通工具、人或物体相互碰撞"}]},{"word":"panic","phonetic":"/ˈpænɪk/","meanings":[{"pos":"noun","meaning":"恐慌；惊慌","usage":"不可数名词，常用搭配get into a panic表示陷入恐慌"}]},{"word":"brake","phonetic":"/breɪk/","meanings":[{"pos":"verb","meaning":"刹车；用闸减速","usage":"既可以作动词表示刹车的动作，也可作名词指刹车装置"}]},{"word":"windscreen","phonetic":"/ˈwɪndskriːn/","meanings":[{"pos":"noun","meaning":"（汽车的）挡风玻璃","usage":"英式英语表达，美式英语常用windshield"}]},{"word":"greedily","phonetic":"/ˈɡriːdɪli/","meanings":[{"pos":"adverb","meaning":"贪婪地；贪心地","usage":"用来修饰表示吃、拿等动作的动词，强调急切、过量的状态"}]},{"word":"devour","phonetic":"/dɪˈvaʊə(r)/","meanings":[{"pos":"verb","meaning":"狼吞虎咽地吃；吞没；毁灭","usage":"强调吃东西的速度快、量大，也可引申指吞并、耗尽"}]},{"word":"stray","phonetic":"/streɪ/","meanings":[{"pos":"adjective","meaning":"走失的；流浪的；零星的","usage":"常修饰动物，也可指零散的物品或人"}]},{"word":"confusion","phonetic":"/kənˈfjuːʒn/","meanings":[{"pos":"noun","meaning":"混乱；困惑；混淆","usage":"不可数名词，可指场景的混乱，也可指人思想上的困惑"}]}],"phrases":[{"phrase":"get out of control","usage":"表示事态、情绪等失去控制，无法被管理或约束","examples":[{"en":"The protest got out of control and turned into a riot.","zh":"抗议活动失去了控制，演变成了骚乱。"},{"en":"If you don't set rules for the kids, they'll soon get out of control.","zh":"如果你不给孩子们定规矩，他们很快就会无法无天。"}]},{"phrase":"set up a chain of reactions","usage":"指一个事件引发一连串连锁反应，常用来描述因果递进的事件序列","examples":[{"en":"The announcement of the price rise set up a chain of reactions in the market.","zh":"涨价的公告在市场上引发了一连串连锁反应。"},{"en":"A small mistake in the experiment set up a chain of reactions that ruined the whole project.","zh":"实验中的一个小错误引发了连锁反应，毁了整个项目。"}]},{"phrase":"keep an eye on","usage":"口语常用表达，意思是照看、留意、密切关注","examples":[{"en":"Could you keep an eye on my suitcase while I go to the restroom?","zh":"我去洗手间的时候你能帮我照看一下行李箱吗？"},{"en":"We need to keep an eye on the weather forecast in case it rains during the picnic.","zh":"我们得留意天气预报，以防野餐的时候下雨。"}]},{"phrase":"reduce sb to tears","usage":"表示使某人难过/委屈到哭，强调事件对人情绪的强烈影响","examples":[{"en":"The cruel comments on her speech reduced her to tears.","zh":"对她演讲的刻薄评论把她弄哭了。"},{"en":"The pressure of being a new nurse reduced her to tears several times in the first month.","zh":"作为新护士的压力让她第一个月好几次都哭了。"}]},{"phrase":"rush hour","usage":"指城市早晚的交通高峰时段，不可数名词短语","examples":[{"en":"It's better to leave before 7 a.m. to avoid the rush hour traffic.","zh":"最好早上7点前出发，避开高峰时段的车流。"},{"en":"The subway is always crowded during rush hour.","zh":"地铁在高峰时段总是很拥挤。"}]},{"phrase":"get into a panic","usage":"表示陷入恐慌状态，强调突然产生的慌乱情绪","examples":[{"en":"She got into a panic when she found her passport was missing.","zh":"她发现护照不见了的时候陷入了恐慌。"},{"en":"Don't get into a panic when you meet difficulties, take a deep breath and think of solutions.","zh":"遇到困难时别慌，深呼吸想想解决办法。"}]},{"phrase":"draw up alongside","usage":"指车辆等驶到旁边、并排停靠","examples":[{"en":"A police car drew up alongside us and signaled us to pull over.","zh":"一辆警车开到我们旁边，示意我们靠边停车。"},{"en":"The taxi drew up alongside the curb to pick up the passenger.","zh":"出租车开到路边停靠，接乘客上车。"}]},{"phrase":"pull up","usage":"指车辆或司机停车、放慢车速停下","examples":[{"en":"He pulled up in front of the gate and got out of the car quickly.","zh":"他在大门前停下车，快速从车里出来。"},{"en":"The bus pulled up just as I was running to the stop.","zh":"我正跑向公交站的时候，公交车刚好停下了。"}]},{"phrase":"pile up","usage":"表示堆积、积压，可指具体物品的堆叠，也可指事务、问题的累积","examples":[{"en":"Work always piles up at the end of the year.","zh":"年底的时候工作总是堆成山。"},{"en":"Snow piled up against the windows during the blizzard.","zh":"暴风雪期间，雪靠着窗户堆了起来。"}]},{"phrase":"get sth on the move","usage":"表示使某事重新运转、恢复正常运行","examples":[{"en":"The new manager tried his best to get the delayed project on the move.","zh":"新经理尽全力让延误的项目重新运转起来。"},{"en":"We need extra workers to get the production line on the move after the breakdown.","zh":"故障之后我们需要额外的工人让生产线重新运转。"}]}],"grammar":[{"title":"as if引导的虚拟语气","definition":"as if/though引导的从句如果表示与事实相反的情况，需要使用虚拟语气，用来描述假设、想象或者不真实的场景","structure":"主句 + as if + 从句（从句动词用过去式表示与现在事实相反，用过去完成式表示与过去事实相反）","usage":"当说话人认为从句所述内容不真实或者可能性很低时使用虚拟语气，如果所述内容是真实的则用陈述语气","examples":[{"en":"It is as if a single unimportant event set up a chain of reactions.","zh":"就好像一件无关紧要的小事引发了一连串的连锁反应。"},{"en":"He talks as if he knew everything about the plan, but actually he knows nothing.","zh":"他说得好像他对这个计划了如指掌，但实际上他什么都不知道。"},{"en":"She looked as if she had heard some terrible news.","zh":"她看起来好像听到了什么可怕的消息。"}]},{"title":"现在分词作伴随/结果状语","definition":"现在分词（doing形式）可以放在句子末尾，用作状语，表示主句动作发生时伴随的状态，或者主句动作带来的自然结果","structure":"主句 + , + 现在分词短语","usage":"现在分词的逻辑主语必须和主句的主语一致，当表示结果时，通常是主句动作自然而然引发的后果","examples":[{"en":"The baby pulls the tablecloth off the table, smashing half your best crockery and cutting himself in the process.","zh":"婴儿把桌布从桌子上扯了下来，打碎了你一半的上好餐具，还在这个过程中割伤了自己。"},{"en":"He sat by the window, reading a novel attentively.","zh":"他坐在窗边，专心致志地读着一本小说。"},{"en":"The heavy rain lasted for three days, causing serious floods in the area.","zh":"大雨持续了三天，在这个地区造成了严重的洪灾。"}]},{"title":"what引导的名词性从句作主语","definition":"what可以引导主语从句，在从句中充当主语、宾语等成分，整个从句在主句中作主语，通常表示“...的事情/情况”","structure":"What + 从句 + 主句谓语 + 其他成分","usage":"相当于the thing that的含义，用来指代具体的某件事或某种情况，让句子结构更紧凑","examples":[{"en":"What invariably happens is that a great number of things choose to go wrong at precisely the same moment.","zh":"经常发生的情况是，好多事情偏偏都凑在同一时间出问题。"},{"en":"What you need to do right now is to calm down and explain the situation clearly.","zh":"你现在需要做的就是冷静下来，把情况解释清楚。"},{"en":"What he said at the meeting surprised all the participants.","zh":"他在会上说的话让所有参会者都很惊讶。"}]}],"patterns":[{"pattern":"We have all experienced days when everything goes wrong.","explanation":"","original":{"en":"We have all experienced days when everything goes wrong.","zh":"我们都有过事事不顺心的日子。"},"examples":[{"en":"We have all experienced moments when we want to give up but choose to hold on in the end.","zh":"我们都有过想要放弃但最终选择坚持的时刻。"},{"en":"Many people have experienced periods when they feel lost and don't know what to do next.","zh":"很多人都有过感到迷茫、不知道下一步该做什么的阶段。"}]},{"pattern":"It is as if + 从句（虚拟语气）","explanation":"","original":{"en":"It is as if a single unimportant event set up a chain of reactions.","zh":"就好像一件无关紧要的小事引发了一连串的连锁反应。"},"examples":[{"en":"It is as if the whole world had forgotten about this small village hidden in the mountains.","zh":"就好像整个世界都忘记了这个藏在山里的小村庄。"},{"en":"He acted as if nothing had happened, even though he knew he made a big mistake.","zh":"他表现得就好像什么都没发生一样，尽管他知道自己犯了大错。"}]},{"pattern":"As if this were not enough to + 动词短语, + 另一糟糕情况","explanation":"","original":{"en":"As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner.","zh":"好像这一切还不足以让你急哭，你丈夫回来了，出乎意料地带了三位客人来家里吃饭。"},"examples":[{"en":"As if this were not enough to make him anxious, his boss called to say he needed to work extra hours this weekend.","zh":"好像这还不足以让他焦虑，他的老板又打电话来说他这周末需要加班。"},{"en":"As if this were not enough to ruin the trip, it started pouring with rain when we just arrived at the foot of the mountain.","zh":"好像这还不足以毁掉这次旅行，我们刚到山脚下的时候就开始下倾盆大雨了。"}]},{"pattern":"Only + 名词 + benefited from + 负面事件, for + 原因从句","explanation":"","original":{"en":"Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake.","zh":"只有两只流浪狗从这一片混乱中得了好处，因为它们贪婪地吃掉了剩下的蛋糕。"},"examples":[{"en":"Only the second-hand bookstore benefited from the closure of the local library, for a lot of readers came to buy books there.","zh":"只有二手书店从当地图书馆的关闭中得了好处，因为很多读者都去那里买书。"},{"en":"Only the delivery platforms benefited from the sudden lockdown, for people could only order food and daily goods online.","zh":"只有外卖平台从突如其来的封控中得了好处，因为人们只能在网上订购食物和日用品。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“混乱；困惑；混淆” 对应的单词是？","hint":"noun · /kənˈfjuːʒn/","options":["confusion","identity","outlandish","resourceful"],"answer":0,"explain":"confusion · /kənˈfjuːʒn/ · noun · 混乱；困惑；混淆。不可数名词，可指场景的混乱，也可指人思想上的困惑","source":{"kind":"vocab","word":"confusion"},"id":"b3-u33-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：前奏；序幕；前兆","hint":"/ˈpreljuːd/ · noun","answer":"prelude","placeholder":"输入英文单词","explain":"prelude · /ˈpreljuːd/ · noun · 前奏；序幕；前兆。常与介词to搭配，指某个重大事件的开端或预兆","source":{"kind":"vocab","word":"prelude"},"id":"b3-u33-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The subway is always crowded during _____.","hint":"地铁在高峰时段总是很拥挤。","answer":"rush hour","placeholder":"输入缺失的短语","explain":"rush hour：指城市早晚的交通高峰时段，不可数名词短语（地铁在高峰时段总是很拥挤。）","source":{"kind":"phrase","phrase":"rush hour"},"id":"b3-u33-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：While you are on the phone, the baby pulls the _____ off the table,","hint":"当你打电话的时候，婴儿把桌布从桌子上扯了下来，","answer":"tablecloth","placeholder":"输入缺失的单词","explain":"While you are on the phone, the baby pulls the tablecloth off the table, — 当你打电话的时候，婴儿把桌布从桌子上扯了下来，","source":{"kind":"sentence","en":"While you are on the phone, the baby pulls the tablecloth off the table,"},"id":"b3-u33-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“现在分词（doing形式）可以放在句子末尾，用作状语，表示主句动作发生时伴随的状态，或者主句动作带来的自然结果” 描述的是哪个语法点？","hint":"主句 + , + 现在分词短语","options":["现在分词作伴随/结果状语","否定副词开头的倒装句 (Inversion with Negative Adverbs)","so...that...引导的倒装句","定语从句的分隔现象"],"answer":0,"explain":"现在分词作伴随/结果状语：主句 + , + 现在分词短语：现在分词的逻辑主语必须和主句的主语一致，当表示结果时，通常是主句动作自然而然引发的后果","source":{"kind":"grammar","title":"现在分词作伴随/结果状语"},"id":"b3-u33-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\na lorry driver who was drawing up alongside the car, pulled up all of a sudden.","hint":"","options":["比赛开始后，两艘船中最先抵达爪哇的是“特莫皮莱”号，","一位正把车开到汽车旁边的货车司机，突然把车停了下来。","长期以来人们都知道墙壁上描绘的狩猎场景不仅仅是一种艺术表现形式。","手机上的大声对话侵扰我们的思绪，或者打断我们与朋友安静聊天的乐趣。"],"answer":1,"explain":"a lorry driver who was drawing up alongside the car, pulled up all of a sudden. — 一位正把车开到汽车旁边的货车司机，突然把车停了下来。","source":{"kind":"sentence","en":"a lorry driver who was drawing up alongside the car, pulled up all of a sudden."},"id":"b3-u33-q06"}]},{"id":"b3-u34","book":3,"unit":34,"key":"34","lessonFrom":34,"lessonTo":34,"title":"A Happy Discovery","titleZh":"幸福的发现","question":"What was the 'happy discovery' ?","sentences":[{"en":"Antique shops exert a peculiar fascination on a great many people.","zh":"古玩店对许多人来说都有一种特殊的魅力。","t":14.53},{"en":"The more expensive kind of antique shop where rare objects are beautifully displayed in glass cases","zh":"那些高档古玩店，珍品都漂亮地陈列在玻璃柜里","t":21.2},{"en":"to keep them free from dust is usually a forbidding place.","zh":"以免沾染灰尘，通常是令人望而却步的地方。","t":29.11},{"en":"But no one has to muster up courage to enter a less pretentious antique shop.","zh":"但对于不那么做作的古玩店，人们无需鼓起勇气进去。","t":34.65},{"en":"There is always hope that in its labyrinth of musty, dark, disordered rooms a real rarity will be found amongst the piles of assorted junk that litter the floors.","zh":"人们总是希望在那些发霉、阴暗、杂乱的房间构成的迷宫中，能在堆满地板的各式各样的旧货中找到一件真正的珍品。","t":41.64},{"en":"No one discovers a rarity by chance.","zh":"没有人会偶然发现珍品。","t":55.1},{"en":"A truly dedicated bargain hunter must have patience,","zh":"一个真正专注的廉价商品搜寻者必须有耐心，","t":59.29},{"en":"and above all, the ability to recognize the worth of something when he sees it.","zh":"最重要的是，当他看到一件东西时，要有识别其价值的能力。","t":63.19},{"en":"To do this, he must be at least as knowledgeable as the dealer.","zh":"为此，他必须至少和经销商一样知识渊博。","t":69.74},{"en":"Like a scientist bent on making a discovery,","zh":"就像一个决心有所发现的科学家一样，","t":75.71},{"en":"he must cherish the hope that one day he will be amply rewarded.","zh":"他必须怀揣希望，总有一天他会得到丰厚的回报。","t":79.36},{"en":"My old friend, Frank Halliday, is just such a person.","zh":"我的老朋友弗兰克·哈利迪就是这样一个人。","t":85.2},{"en":"He has often described to me how he picked up a masterpiece for a mere ￡50.","zh":"他常常向我描述他是如何以区区50英镑买到一件杰作的。","t":90.9},{"en":"One Saturday morning, Frank visited an antique shop in my neighbourhood.","zh":"一个星期六的上午，弗兰克去了我附近的一家古玩店。","t":97.51},{"en":"As he had never been there before, he found a great deal to interest him.","zh":"因为他以前从未来过这里，所以发现了很多让他感兴趣的东西。","t":104.16},{"en":"The morning passed rapidly and Frank was about to leave when he noticed a large packing case lying on the floor.","zh":"上午很快过去了，弗兰克正准备离开时，他注意到地板上放着一个大包装箱。","t":110.22},{"en":"The dealer told him that it had just come in, but that he could not be bothered to open it.","zh":"经销商告诉他，这东西刚到，但他懒得打开。","t":119.25},{"en":"Frank begged him to do so and the dealer reluctantly prised it open.","zh":"弗兰克恳求他打开，经销商不情愿地撬开了箱子。","t":126.29},{"en":"The contents were disappointing.","zh":"里面的东西令人失望。","t":132.14},{"en":"Apart from an interesting-looking carved dagger, the box was full of crockery, much of it broken.","zh":"除了一个看起来有趣的雕花匕首外，箱子里装满了陶器，其中大部分都碎了。","t":134.85},{"en":"Frank gently lifted the crockery out of the box and suddenly noticed a miniature painting at the bottom of the packing case.","zh":"弗兰克轻轻地把陶器从箱子里拿出来，突然注意到包装箱底部有一幅微型画。","t":143.03},{"en":"As its composition and line reminded him of an Italian painting he knew well, he decided to buy it.","zh":"由于它的构图和线条让他想起了他很熟悉的一幅意大利画作，他决定买下它。","t":153.16},{"en":"Glancing at it briefly the dealer told him that it was worth ￡50.","zh":"经销商匆匆看了一眼，告诉他这幅画值50英镑。","t":162.44},{"en":"Frank could hardly conceal his excitement, for he knew that he had made a real discovery.","zh":"弗兰克几乎无法掩饰他的兴奋，因为他知道他做了一个真正的发现。","t":168.21},{"en":"The tiny painting proved to be an unknown masterpiece by Correggio and was worth hundreds and thousands of pounds.","zh":"这幅小画被证实是科雷吉奥的一幅不为人知的杰作，价值数十万英镑。","t":175.47}],"vocab":[{"word":"antique","phonetic":"/ænˈtiːk/","meanings":[{"pos":"noun","meaning":"古董，古玩","usage":"指具有历史价值的古老物件"},{"pos":"adjective","meaning":"古老的，古董的","usage":"修饰和古董相关的事物"}]},{"word":"peculiar","phonetic":"/pɪˈkjuːliə(r)/","meanings":[{"pos":"adjective","meaning":"特殊的，独特的；奇怪的","usage":"可形容事物独有的特性，也可指反常的、怪异的"}]},{"word":"fascination","phonetic":"/ˌfæsɪˈneɪʃn/","meanings":[{"pos":"noun","meaning":"魅力，吸引力；入迷","usage":"常和介词for/over搭配，表示对…的吸引力"}]},{"word":"rare","phonetic":"/reə(r)/","meanings":[{"pos":"adjective","meaning":"稀有的，罕见的","usage":"形容少见、珍贵的事物，也可形容稀薄的空气"}]},{"word":"forbidding","phonetic":"/fəˈbɪdɪŋ/","meanings":[{"pos":"adjective","meaning":"令人生畏的，望而却步的","usage":"常用来形容地方、外表或者氛围给人严肃、不易接近的感觉"}]},{"word":"muster","phonetic":"/ˈmʌstə(r)/","meanings":[{"pos":"verb","meaning":"鼓起（勇气），集合","usage":"常见搭配muster up courage表示鼓起勇气"}]},{"word":"pretentious","phonetic":"/prɪˈtenʃəs/","meanings":[{"pos":"adjective","meaning":"炫耀的，虚饰的，做作的","usage":"形容人或事物刻意显得贵重、重要，实际名不副实"}]},{"word":"labyrinth","phonetic":"/ˈlæbərɪnθ/","meanings":[{"pos":"noun","meaning":"迷宫，错综复杂的事物","usage":"可指实际的迷宫类建筑，也可比喻复杂难懂的结构"}]},{"word":"musty","phonetic":"/ˈmʌsti/","meanings":[{"pos":"adjective","meaning":"发霉的，有霉味的","usage":"形容长期不通风、潮湿的地方或物品散发的味道"}]},{"word":"rarity","phonetic":"/ˈreərəti/","meanings":[{"pos":"noun","meaning":"珍品，罕见的事物","usage":"指稀有的、有价值的物品，也可指稀有性"}]},{"word":"assorted","phonetic":"/əˈsɔːtɪd/","meanings":[{"pos":"adjective","meaning":"各种各样的，混杂的","usage":"形容不同种类的物品混合在一起"}]},{"word":"dedicated","phonetic":"/ˈdedɪkeɪtɪd/","meanings":[{"pos":"adjective","meaning":"专注的，有奉献精神的","usage":"形容人对某件事投入大量精力、非常专注"}]},{"word":"amply","phonetic":"/ˈæmpli/","meanings":[{"pos":"adverb","meaning":"足够地，丰厚地","usage":"修饰回报、证明等词，表示程度充足"}]},{"word":"reluctantly","phonetic":"/rɪˈlʌktəntli/","meanings":[{"pos":"adverb","meaning":"不情愿地，勉强地","usage":"描述做某事时不情愿的状态"}]},{"word":"miniature","phonetic":"/ˈmɪnətʃə(r)/","meanings":[{"pos":"adjective","meaning":"微型的，小型的","usage":"形容比正常尺寸小很多的事物"}]}],"phrases":[{"phrase":"exert a fascination on","usage":"表示对…产生吸引力，主语通常是具有魅力的事物","examples":[{"en":"Ancient cities exert a peculiar fascination on tourists from all over the world.","zh":"古城对来自世界各地的游客有着独特的吸引力。"}]},{"phrase":"keep sth free from","usage":"表示使某物远离…、免受…的影响","examples":[{"en":"We should keep the laboratory free from dust and noise.","zh":"我们应该让实验室远离灰尘和噪音。"}]},{"phrase":"muster up courage","usage":"固定搭配，意为鼓起勇气做某事，后面常接to do不定式","examples":[{"en":"She mustered up courage to give a speech in front of hundreds of people.","zh":"她鼓起勇气在数百人面前发表演讲。"}]},{"phrase":"by chance","usage":"表示偶然、意外地，相当于accidentally，在句中作状语","examples":[{"en":"I met my former classmate by chance in the supermarket yesterday.","zh":"我昨天在超市偶然碰到了我以前的同学。"}]},{"phrase":"above all","usage":"插入语，意为最重要的是，用于强调后续内容的重要性","examples":[{"en":"To be a good nurse, you need to be careful, patient and above all, kind to patients.","zh":"要成为一名好护士，你需要细心、有耐心，最重要的是要对病人友善。"}]},{"phrase":"be bent on","usage":"表示一心想要、决心要，后面接名词或动名词，常指下定决心做某事","examples":[{"en":"He is bent on winning the first prize in the national English competition.","zh":"他一心想要在全国英语竞赛中获得一等奖。"}]},{"phrase":"pick up","usage":"此处表示轻易买到、便宜买到，还可表示捡起、学会（语言）、接人等含义","examples":[{"en":"She picked up a beautiful vintage dress at the second-hand market for only 100 yuan.","zh":"她在二手市场只花了100元就买到了一件漂亮的复古连衣裙。"}]},{"phrase":"be about to do sth when","usage":"表示正要做某事，这时突然发生另一件事，强调动作的突发性","examples":[{"en":"I was about to go out when the telephone rang.","zh":"我正要出门，这时电话铃响了。"}]},{"phrase":"cannot be bothered to do sth","usage":"表示懒得做某事，不想费心做某事，是口语中常用的表达","examples":[{"en":"After a long day at work, I can't be bothered to cook dinner.","zh":"工作了一整天之后，我懒得做晚饭了。"}]},{"phrase":"apart from","usage":"表示除了…之外，相当于except for或者besides，根据语境可表示排除或者包含关系","examples":[{"en":"Apart from a few spelling mistakes, your composition is very good.","zh":"除了几个拼写错误之外，你的作文写得非常好。"}]}],"grammar":[{"title":"The + 比较级结构作定语","definition":"用\"the + 形容词比较级\"修饰名词，表示两类事物中程度更高的那一类，隐含和另一类的对比关系","structure":"The + 形容词比较级 + 名词 + 定语从句/其他修饰成分","usage":"用于对同一范畴的两个事物进行对比，突出其中程度更高的那个的属性","examples":[{"en":"The more expensive kind of antique shop where rare objects are beautifully displayed in glass cases to keep them free from dust is usually a forbidding place.","zh":"高档一点的古玩店为了防尘，把文物漂亮地陈列在玻璃柜子里，那里往往令人望而却步。"},{"en":"The more convenient way to get to the airport is to take the high-speed rail.","zh":"去机场更便捷的方式是坐高铁。"}]},{"title":"There is hope that 同位语从句","definition":"that引导的从句作名词hope的同位语，用来解释说明hope的具体内容","structure":"There is hope that + 完整的陈述句式从句","usage":"用于表达某种可能性是存在的，人们抱有相关的期望","examples":[{"en":"There is always hope that in its labyrinth of musty, dark, disordered rooms a real rarity will be found amongst the piles of assorted junk that litter the floors.","zh":"人们还常常有希望在发霉、阴暗、杂乱无章、迷宫般的店堂里，从杂乱地摆放在地面上的、一堆堆各式各样的破烂货里找到一件稀世珍品。"},{"en":"There is hope that the team will win the championship this season.","zh":"这支队伍有望在本赛季赢得冠军。"}]}],"patterns":[{"pattern":"A truly dedicated + 名词 + must have..., and above all, the ability to...","explanation":"","original":{"en":"A truly dedicated bargain hunter must have patience, and above all, the ability to recognize the worth of something when he sees it.","zh":"一个一心一意找便宜货的人必须有耐心，最重要的是，要有眼力，看到东西就能认出它的价值。"},"examples":[{"en":"A truly dedicated writer must have rich life experience, and above all, the ability to observe small details in daily life.","zh":"一个真正专注的作家必须有丰富的人生阅历，最重要的是，要有观察生活中微小细节的能力。"},{"en":"A truly dedicated researcher must have rigorous academic attitude, and above all, the ability to think independently.","zh":"一个真正专注的研究者必须有严谨的学术态度，最重要的是，要有独立思考的能力。"}]},{"pattern":"Sb could hardly conceal his/her + 情绪名词, for he/she knew that...","explanation":"","original":{"en":"Frank could hardly conceal his excitement, for he knew that he had made a real discovery.","zh":"弗兰克几乎无法掩饰自己兴奋的心情，因为他知道自己有了一个真正的发现。"},"examples":[{"en":"She could hardly conceal her disappointment, for she knew that she had failed the interview she had prepared for months.","zh":"她几乎无法掩饰自己的失望，因为她知道自己准备了数月的面试没有通过。"},{"en":"The little boy could hardly conceal his joy, for he knew that his parents would take him to the Disneyland this weekend.","zh":"小男孩几乎无法掩饰自己的喜悦，因为他知道父母这周末要带他去迪士尼乐园。"}]},{"pattern":"As + 原因状语从句, sb decided to do sth","explanation":"","original":{"en":"As its composition and line reminded him of an Italian painting he knew well, he decided to buy it.","zh":"由于它的构图和线条让他想起了一幅他熟悉的意大利画作，他决定买下它。"},"examples":[{"en":"As the weather forecast said it would rain heavily in the afternoon, we decided to cancel the outdoor picnic.","zh":"由于天气预报说下午会下大雨，我们决定取消户外野餐。"},{"en":"As the course he wanted to take was very popular, he decided to sign up for it as soon as possible.","zh":"由于他想选的那门课非常热门，他决定尽快报名。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“珍品，罕见的事物” 对应的单词是？","hint":"noun · /ˈreərəti/","options":["lull","astound","rarity","straggling"],"answer":2,"explain":"rarity · /ˈreərəti/ · noun · 珍品，罕见的事物。指稀有的、有价值的物品，也可指稀有性","source":{"kind":"vocab","word":"rarity"},"id":"b3-u34-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：发霉的，有霉味的","hint":"/ˈmʌsti/ · adjective","answer":"musty","placeholder":"输入英文单词","explain":"musty · /ˈmʌsti/ · adjective · 发霉的，有霉味的。形容长期不通风、潮湿的地方或物品散发的味道","source":{"kind":"vocab","word":"musty"},"id":"b3-u34-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：I met my former classmate _____ in the supermarket yesterday.","hint":"我昨天在超市偶然碰到了我以前的同学。","answer":"by chance","placeholder":"输入缺失的短语","explain":"by chance：表示偶然、意外地，相当于accidentally，在句中作状语（我昨天在超市偶然碰到了我以前的同学。）","source":{"kind":"phrase","phrase":"by chance"},"id":"b3-u34-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：As he had never been _____ before, he found a great deal to interest him.","hint":"因为他以前从未来过这里，所以发现了很多让他感兴趣的东西。","answer":"there","placeholder":"输入缺失的单词","explain":"As he had never been there before, he found a great deal to interest him. — 因为他以前从未来过这里，所以发现了很多让他感兴趣的东西。","source":{"kind":"sentence","en":"As he had never been there before, he found a great deal to interest him."},"id":"b3-u34-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用\"the + 形容词比较级\"修饰名词，表示两类事物中程度更高的那一类，隐含和另一类的对比关系” 描述的是哪个语法点？","hint":"The + 形容词比较级 + 名词 + 定语从句/其他修饰成分","options":["so...that...引导的倒装句","more than + n./adj. (不仅仅；超出)","even though/even if引导的让步状语从句","The + 比较级结构作定语"],"answer":3,"explain":"The + 比较级结构作定语：The + 形容词比较级 + 名词 + 定语从句/其他修饰成分：用于对同一范畴的两个事物进行对比，突出其中程度更高的那个的属性","source":{"kind":"grammar","title":"The + 比较级结构作定语"},"id":"b3-u34-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nA truly dedicated bargain hunter must have patience,","hint":"","options":["随着年龄的增长，人们还因为另外两个原因而积累物品：","一个真正专注的廉价商品搜寻者必须有耐心，","在战争快结束时受伤后，","以便我们可以在家中屏幕上阅读，如果需要甚至可以打印出来。"],"answer":1,"explain":"A truly dedicated bargain hunter must have patience, — 一个真正专注的廉价商品搜寻者必须有耐心，","source":{"kind":"sentence","en":"A truly dedicated bargain hunter must have patience,"},"id":"b3-u34-q06"}]},{"id":"b3-u35","book":3,"unit":35,"key":"35","lessonFrom":35,"lessonTo":35,"title":"Justice was Done","titleZh":"正义得以伸张","question":"What is the distinction between them?","sentences":[{"en":"The word justice is usually associated with courts of law.","zh":"“正义”一词通常与法庭联系在一起。","t":19.85},{"en":"We might say that justice has been done when a man's innocence or guilt has been proved beyond doubt.","zh":"当一个人的清白或罪行被无可置疑地证明时，我们可能会说正义得到了伸张。","t":25.49},{"en":"Justice is part of the complex machinery of the law.","zh":"正义是法律复杂机制的一部分。","t":33.15},{"en":"Those who seek it, undertake an arduous journey and can never be sure that they will find it.","zh":"追求正义的人会踏上一段艰难的旅程，而且永远无法确定他们是否会找到它。","t":37.75},{"en":"Judges, however wise or eminent, are human and can make mistakes.","zh":"法官，无论多么明智或杰出，都是人，也可能犯错误。","t":44.88},{"en":"There are rare instances when justice almost ceases to be an abstract concept.","zh":"在极少数情况下，正义几乎不再是一个抽象的概念。","t":51.18},{"en":"Reward or punishment are meted out quite independent of human interference.","zh":"奖励或惩罚在完全没有人类干预的情况下被施加。","t":58.16},{"en":"At such times, justice acts like a living force.","zh":"在这种时候，正义就像一股活生生的力量。","t":64.3},{"en":"When we use a phrase like 'it serves him right',","zh":"当我们使用“活该”这样的短语时，","t":69.44},{"en":"we are, in part, admitting that a certain set of circumstances has enabled justice to act of its own accord.","zh":"我们部分承认了某种情况使正义得以自然而然地发挥作用。","t":73.51},{"en":"When a thief was caught on the premises of a large jewellery store one morning,","zh":"一天早上，当一个小偷在一家大型珠宝店的院子里被抓到时，","t":83.84},{"en":"the shop assistants must have found it impossible to resist the temptation to say 'it serves him right'.","zh":"店员们一定觉得很难抵制住说“活该”的冲动。","t":89.48},{"en":"The shop was an old converted house with many large, disused fireplaces and tall, narrow chimneys.","zh":"这家店是一座由老房子改建而成的，有很多大的废弃壁炉和又高又窄的烟囱。","t":97.67},{"en":"Towards midday, a girl heard a muffled cry coming from behind one of the walls.","zh":"快到中午时，一个女孩听到墙后传来一阵低沉的哭声。","t":106.07},{"en":"As the cry was repeated several times,","zh":"哭声重复了几次之后，","t":112.86},{"en":"she ran to tell the manager who promptly rang up the fire brigade.","zh":"她跑去告诉经理，经理立刻给消防队打了电话。","t":115.79},{"en":"The cry had certainly come from one of the chimneys,","zh":"哭声确实是从一个烟囱里传出来的，","t":121.37},{"en":"but as there were so many of them, the firemen could not be certain which one it was.","zh":"但由于烟囱太多，消防员无法确定是哪一个。","t":124.65},{"en":"They located the right chimney by tapping at the walls and listening for the man's cries.","zh":"他们通过敲击墙壁并聆听那个人的哭声来确定正确的烟囱。","t":132.25},{"en":"After chipping through a wall which was eighteen inches thick,","zh":"在凿穿一堵18英寸厚的墙后，","t":139.67},{"en":"they found that a man had been trapped in the chimney.","zh":"他们发现一个人被困在烟囱里了。","t":144.23},{"en":"As it was extremely narrow, the man was unable to move,","zh":"由于烟囱非常狭窄，那个人无法动弹，","t":148.4},{"en":"but the fire fighters were eventually able to free him by cutting a huge hole in the wall.","zh":"但消防员最终通过在墙上凿开一个大洞，成功地解救了他。","t":153.21},{"en":"The sorry-looking, blackened figure that emerged,","zh":"那个狼狈不堪、浑身漆黑的人影出现后，","t":160.91},{"en":"admitted at once that he had tried to break into the shop during the night but had got stuck in the chimney.","zh":"立刻承认他曾试图在夜间闯入商店，但被卡在了烟囱里。","t":164.98},{"en":"He had been there for nearly ten hours.","zh":"他已经在里面待了将近十个小时。","t":173.22},{"en":"Justice had been done even before the man was handed over to the police.","zh":"甚至在将那个人移交给警方之前，正义就已经得到了伸张。","t":177.25}],"vocab":[{"word":"justice","phonetic":"/ˈdʒʌstɪs/","meanings":[{"pos":"noun","meaning":"正义；公正；司法","usage":"可指法律上的公正审判，也可指抽象的正义概念"}]},{"word":"machinery","phonetic":"/məˈʃiːnəri/","meanings":[{"pos":"noun","meaning":"机械；机构；系统","usage":"指复杂的组织或机构系统"}]},{"word":"arduous","phonetic":"/ˈɑːdjuəs/","meanings":[{"pos":"adjective","meaning":"艰巨的；艰苦的；费力的","usage":"形容需要付出大量努力的困难工作或旅程"}]},{"word":"abstract","phonetic":"/ˈæbstrækt/","meanings":[{"pos":"adjective","meaning":"抽象的；概念上的","usage":"与具体事物相对的，存在于概念中的"}]},{"word":"muffled","phonetic":"/ˈmʌfld/","meanings":[{"pos":"adjective","meaning":"沉闷的；压低的；听不清的","usage":"形容声音被压抑或减弱的"}]},{"word":"temptation","phonetic":"/tempˈteɪʃn/","meanings":[{"pos":"noun","meaning":"诱惑；引诱","usage":"指吸引人做某事的力量或冲动"}]},{"word":"locate","phonetic":"/ləʊˈkeɪt/","meanings":[{"pos":"verb","meaning":"定位；找出位置","usage":"指确定某物的确切位置"}]},{"word":"emerge","phonetic":"/ɪˈmɜːdʒ/","meanings":[{"pos":"verb","meaning":"出现；浮现；出来","usage":"指从某处出来或显露出来"}]},{"word":"hand over","phonetic":"/hænd ˈəʊvə/","meanings":[{"pos":"verb phrase","meaning":"移交；交出","usage":"指把某人或某物交给另一个人或权威机构"}]},{"word":"of one's own accord","phonetic":"/ɒv wʌnz əʊn əˈkɔːd/","meanings":[{"pos":"phrase","meaning":"出于自愿；自动地","usage":"指在没有外部压力的情况下自己去做某事"}]},{"word":"undertake","phonetic":"/ˌʌndəˈteɪk/","meanings":[{"pos":"verb","meaning":"从事；着手做；承担","usage":"指开始进行一项工作或任务"}]},{"word":"chip","phonetic":"/tʃɪp/","meanings":[{"pos":"verb","meaning":"凿；削；凿穿","usage":"指用工具凿开或削去材料"}]},{"word":"converted","phonetic":"/kənˈvɜːtɪd/","meanings":[{"pos":"adjective","meaning":"改建的；改造的","usage":"指从一种用途或形式改变为另一种"}]},{"word":"mete out","phonetic":"/miːt aʊt/","meanings":[{"pos":"verb phrase","meaning":"给予；实施（惩罚等）","usage":"指分配或给予奖惩"}]},{"word":"premises","phonetic":"/ˈpremɪsɪz/","meanings":[{"pos":"noun","meaning":"房屋及土地；营业场所","usage":"指建筑物及其所在的场地，常用复数形式"}]}],"phrases":[{"phrase":"justice has been done","usage":"表示正义已经得到伸张或实现","examples":[{"en":"Justice has been done even before the man was handed over to the police.","zh":"甚至在这个人移交给警察之前，正义就已经得到了伸张。"}]},{"phrase":"it serves him right","usage":"表示某人自食其果、活该倒霉","examples":[{"en":"The shop assistants must have found it impossible to resist the temptation to say 'it serves him right'.","zh":"店员们一定会觉得忍不住想说'他活该'。"}]},{"phrase":"ring up","usage":"打电话给某人","examples":[{"en":"The manager promptly rang up the fire brigade.","zh":"经理立刻给消防队打了电话。"}]},{"phrase":"break into","usage":"闯入；非法进入","examples":[{"en":"He had tried to break into the shop during the night but had got stuck in the chimney.","zh":"他试图在夜间闯入商店，但卡在了烟囱里。"}]},{"phrase":"hand over","usage":"移交（权力、某人等）","examples":[{"en":"Justice had been done even before the man was handed over to the police.","zh":"甚至在这个人移交给警察之前，正义就已经得到了伸张。"}]},{"phrase":"of one's own accord","usage":"出于自愿；自动地","examples":[{"en":"We are, in part, admitting that a certain set of circumstances has enabled justice to act of its own accord.","zh":"我们在某种程度上承认，某些环境因素使得正义能够自行发挥作用。"}]},{"phrase":"beyond doubt","usage":"毫无疑问地；确定无疑地","examples":[{"en":"We might say that justice has been done when a man's innocence or guilt has been proved beyond doubt.","zh":"当一个人的清白或罪行被毫无疑问地证实后，我们可以说正义得到了伸张。"}]},{"phrase":"undertake an arduous journey","usage":"踏上艰难的旅程","examples":[{"en":"Those who seek it, undertake an arduous journey and can never be sure that they will find it.","zh":"那些寻求正义的人，踏上了艰难的旅程，而且永远无法确定他们能否找到它。"}]},{"phrase":"catch on the premises","usage":"在场所内被抓","examples":[{"en":"When a thief was caught on the premises of a large jewellery store one morning.","zh":"一天早上，当一个小偷在一家大型珠宝店的场所内被抓时。"}]},{"phrase":"free someone by doing something","usage":"通过做某事使某人获救","examples":[{"en":"The fire fighters were eventually able to free him by cutting a huge hole in the wall.","zh":"消防队员最终通过在墙上凿开一个大洞将他救了出来。"}]}],"grammar":[{"title":"被动语态 (Passive Voice)","definition":"当句子的主语是动作的承受者时使用被动语态。主动语态中动作的执行者（agent）可以用by引出，但经常被省略。","structure":"be + 过去分词 (be + past participle)","usage":"用于强调动作的承受者，或动作执行者不明确、不重要时。","examples":[{"en":"Justice is done.","zh":"正义得到伸张。"},{"en":"Justice has been done even before the man was handed over to the police.","zh":"甚至在这个人移交给警察之前，正义就已经得到了伸张。"},{"en":"The shop was an old converted house.","zh":"那家商店是一栋改建的老房子。"}]},{"title":"现在完成时 (Present Perfect Tense)","definition":"表示过去发生的动作或状态持续到现在，或对现在有影响。常与already, just, yet, for, since等词连用。","structure":"have/has + 过去分词","usage":"用于表示过去的动作与现在有关联，或动作已发生但强调其结果。","examples":[{"en":"The cry was repeated several times.","zh":"哭喊声重复了好几次。"},{"en":"He had been there for nearly ten hours.","zh":"他在那里已经呆了将近十个小时。"},{"en":"She ran to tell the manager who promptly rang up the fire brigade.","zh":"她跑去告诉经理，经理立刻给消防队打了电话。"}]},{"title":"定语从句 (Relative Clause)","definition":"用于修饰名词或代词的从句，由关系代词（who, whom, which, that）或关系副词（where, when, why）引导。","structure":"名词/代词 + 关系词 + 从句","usage":"用于提供关于某人或某物的额外信息。","examples":[{"en":"The cry had certainly come from one of the chimneys, but as there were so many of them, the firemen could not be certain which one it was.","zh":"哭喊声确实是从某个烟囱里传来的，但由于烟囱太多，消防员无法确定是哪一个。"},{"en":"Those who seek it, undertake an arduous journey.","zh":"那些寻求正义的人，踏上了艰难的旅程。"}]}],"patterns":[{"pattern":"Justice + be + done","explanation":"","original":{"en":"Justice was done.","zh":"正义得到伸张。"},"examples":[{"en":"Justice has been done.","zh":"正义已经得到伸张。"},{"en":"Justice will be done eventually.","zh":"正义最终会得到伸张。"}]},{"pattern":"It serves someone right","explanation":"","original":{"en":"It serves him right.","zh":"他活该。"},"examples":[{"en":"It serves you right for being late.","zh":"你迟到，活该。"},{"en":"It serves her right for not studying.","zh":"她不学习，活该。"}]},{"pattern":"Someone + be + unable to + 动词原形","explanation":"","original":{"en":"As it was extremely narrow, the man was unable to move.","zh":"由于烟囱非常狭窄，这个人无法动弹。"},"examples":[{"en":"She was unable to attend the meeting.","zh":"她无法参加会议。"},{"en":"I was unable to solve the problem.","zh":"我无法解决这个问题。"}]},{"pattern":"When + 时间状语从句, 主句","explanation":"","original":{"en":"When a thief was caught on the premises of a large jewellery store one morning, the shop assistants must have found it impossible to resist the temptation to say 'it serves him right'.","zh":"一天早上，当一个小偷在一家大型珠宝店的场所内被抓时，店员们一定会觉得忍不住想说'他活该'。"},"examples":[{"en":"When I was young, I used to play in the park.","zh":"当我年轻的时候，我常在公园里玩。"},{"en":"When he arrived home, it was already dark.","zh":"当他到家时，天已经黑了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“改建的；改造的” 对应的单词是？","hint":"adjective · /kənˈvɜːtɪd/","options":["philosopher","rashly","converted","abstruse"],"answer":2,"explain":"converted · /kənˈvɜːtɪd/ · adjective · 改建的；改造的。指从一种用途或形式改变为另一种","source":{"kind":"vocab","word":"converted"},"id":"b3-u35-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：移交；交出","hint":"/hænd ˈəʊvə/ · verb phrase","answer":"hand over","placeholder":"输入英文单词","explain":"hand over · /hænd ˈəʊvə/ · verb phrase · 移交；交出。指把某人或某物交给另一个人或权威机构","source":{"kind":"vocab","word":"hand over"},"id":"b3-u35-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：He had tried to _____ the shop during the night but had got stuck in the chimney.","hint":"他试图在夜间闯入商店，但卡在了烟囱里。","answer":"break into","placeholder":"输入缺失的短语","explain":"break into：闯入；非法进入（他试图在夜间闯入商店，但卡在了烟囱里。）","source":{"kind":"phrase","phrase":"break into"},"id":"b3-u35-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：They located the right chimney by tapping at the walls and _____ for the man's cries.","hint":"他们通过敲击墙壁并聆听那个人的哭声来确定正确的烟囱。","answer":"listening","placeholder":"输入缺失的单词","explain":"They located the right chimney by tapping at the walls and listening for the man's cries. — 他们通过敲击墙壁并聆听那个人的哭声来确定正确的烟囱。","source":{"kind":"sentence","en":"They located the right chimney by tapping at the walls and listening for the man's cries."},"id":"b3-u35-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示过去发生的动作或状态持续到现在，或对现在有影响。常与already, just, yet, for, since等词连用。” 描述的是哪个语法点？","hint":"have/has + 过去分词","options":["现在完成时 (Present Perfect Tense)","make it + 形容词 + for sb. to do sth.","过去完成进行时","关系从句（限制性定语从句）"],"answer":0,"explain":"现在完成时 (Present Perfect Tense)：have/has + 过去分词：用于表示过去的动作与现在有关联，或动作已发生但强调其结果。","source":{"kind":"grammar","title":"现在完成时 (Present Perfect Tense)"},"id":"b3-u35-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAfter chipping through a wall which was eighteen inches thick,","hint":"","options":["在凿穿一堵18英寸厚的墙后，","但论速度和舒适度，没有任何交通工具能与它们相比。","在此过程中，他玩得很开心，并且不停地告诉所有人他有多么讨厌医院。","在那些日子里，拳击手们赤手空拳地搏斗以争夺奖金。"],"answer":0,"explain":"After chipping through a wall which was eighteen inches thick, — 在凿穿一堵18英寸厚的墙后，","source":{"kind":"sentence","en":"After chipping through a wall which was eighteen inches thick,"},"id":"b3-u35-q06"}]},{"id":"b3-u36","book":3,"unit":36,"key":"36","lessonFrom":36,"lessonTo":36,"title":"A Chance in a Million","titleZh":"百万分之一的机遇","question":"What was the chance in a million?","sentences":[{"en":"We are less credulous than we used to be.","zh":"我们不像以前那样轻信了。","t":13.45},{"en":"In the nineteenth century, a novelist would bring his story to a conclusion","zh":"在19世纪，小说家在故事的结尾","t":17.13},{"en":"by presenting his readers with a series of coincidences--most of them wildly improbable.","zh":"会给读者安排一连串的巧合——其中大部分都是极不可能发生的。","t":22.6},{"en":"Readers happily accepted the fact that an obscure maidservant was really the hero's mother.","zh":"读者们欣然接受一个默默无闻的女仆竟然是主人公的母亲这一事实。","t":30.29},{"en":"A long-lost brother, who was presumed dead, was really alive all the time","zh":"一个被认为已死去的失散多年的兄弟，实际上一直活着，","t":37.78},{"en":"and wickedly plotting to bring about the hero's downfall. And so on.","zh":"并且阴险地策划着让主人公垮台。诸如此类。","t":44.07},{"en":"Modern readers would find such naive solutions totally unacceptable.","zh":"现代读者会觉得这种天真的结局完全不能接受。","t":50.02},{"en":"Yet, in real life, circumstances do sometimes conspire to bring about coincidences which anyone but a nineteenth century novelist would find incredible.","zh":"然而，在现实生活中，情况有时确实会凑巧地导致巧合的发生，除了19世纪的小说家，其他任何人都觉得不可思议。","t":56.13},{"en":"When I was a boy, my grandfather told me how a German taxi driver, Franz Bussman,","zh":"我小时候，祖父给我讲了一个德国出租车司机弗朗兹·布斯曼的故事，","t":69.39},{"en":"found a brother who was thought to have been killed twenty years before.","zh":"他找到了一个被认为在20年前阵亡的兄弟。","t":76.37},{"en":"While on a walking tour with his wife, he stopped to talk to a workman.","zh":"在和妻子徒步旅行时，他停下来和一名工人交谈。","t":81.39},{"en":"After they had gone on, Mrs. Bussman commented on the workman's close resemblance to her husband","zh":"他们继续前行后，布斯曼夫人评论说那个工人长得很像她丈夫，","t":87.1},{"en":"and even suggested that he might be his brother.","zh":"甚至猜测他可能是她丈夫的兄弟。","t":94.34},{"en":"Franz poured scorn on the idea,","zh":"弗朗兹对这个想法嗤之以鼻，","t":98.71},{"en":"pointing out that his brother had been killed in action during the war.","zh":"指出他兄弟在战争中阵亡了。","t":102.09},{"en":"Though Mrs. Bussman was fully acquainted with this story,","zh":"尽管布斯曼夫人完全了解这个故事，","t":107.35},{"en":"she thought that there was a chance in a million that she might be right.","zh":"她觉得她有可能说对了，尽管几率是百万分之一。","t":111.7},{"en":"A few days later, she sent a boy to the workman to ask him if his name was Hans Bussman.","zh":"几天后，她派了一个男孩去问那个工人，他是否叫汉斯·布斯曼。","t":117.09},{"en":"Needless to say, the man's name was Hans Bussman and he really was Franz's long-lost brother.","zh":"不用说，那个人的名字就是汉斯·布斯曼，他确实是弗朗兹失散多年的兄弟。","t":125.01},{"en":"When the brothers were reunited,","zh":"兄弟俩团聚后，","t":133.94},{"en":"Hans explained how it was that he was still alive.","zh":"汉斯解释了他为什么还活着。","t":136.2},{"en":"After having been wounded towards the end of the war,","zh":"在战争快结束时受伤后，","t":140.36},{"en":"he had been sent to hospital and was separated from his unit.","zh":"他被送往医院，与部队失散了。","t":144.73},{"en":"The hospital had been bombed and Hans had made his way back into Western Germany on foot.","zh":"医院被轰炸了，汉斯徒步回到了西德。","t":149.84},{"en":"Meanwhile, his unit was lost and all records of him had been destroyed.","zh":"同时，他的部队失散了，所有关于他的记录都被销毁了。","t":157.64},{"en":"Hans returned to his family home, but the house had been bombed","zh":"汉斯回到了他的老家，但是房子被炸毁了，","t":163.74},{"en":"and no one in the neighbourhood knew what had become of the inhabitants.","zh":"邻居们也不知道住户们怎么样了。","t":168.37},{"en":"Assuming that his family had been killed during an air raid,","zh":"以为他的家人在空袭中丧生，","t":173.03},{"en":"Hans settled down in a village fifty miles away where he had remained ever since.","zh":"汉斯在一个五十英里外的小村庄安顿下来，自此一直住在那里。","t":177}],"vocab":[{"word":"credulous","phonetic":"/ˈkredjʊləs/","meanings":[{"pos":"adj","meaning":"轻信的，易受骗的","usage":"形容人容易相信不真实的事物"}]},{"word":"coincidence","phonetic":"/kəʊˈɪnsɪdəns/","meanings":[{"pos":"noun","meaning":"巧合，巧事","usage":"指两件或多件事情同时发生但没有明显关联"}]},{"word":"novelist","phonetic":"/ˈnɒvəlɪst/","meanings":[{"pos":"noun","meaning":"小说家","usage":"指创作小说的人"}]},{"word":"improbable","phonetic":"/ɪmˈprɒbəbl/","meanings":[{"pos":"adj","meaning":"不太可能的，未必会的","usage":"形容不太可能发生的事"}]},{"word":"wickedly","phonetic":"/ˈwɪkɪdli/","meanings":[{"pos":"adv","meaning":"恶劣地，邪恶地","usage":"修饰动词，表示以邪恶的方式"}]},{"word":"plot","phonetic":"/plɒt/","meanings":[{"pos":"verb","meaning":"密谋，策划","usage":"指暗中计划做坏事"}]},{"word":"downfall","phonetic":"/ˈdaʊnfɔːl/","meanings":[{"pos":"noun","meaning":"垮台，衰落","usage":"指失去权势或成功"}]},{"word":"reunite","phonetic":"/riːjuːˈnaɪt/","meanings":[{"pos":"verb","meaning":"重聚，使重逢","usage":"指使分离的人或物再次聚在一起"}]},{"word":"resemblance","phonetic":"/rɪˈzembləns/","meanings":[{"pos":"noun","meaning":"相似，相像","usage":"指外貌或特征的相似"}]},{"word":"workman","phonetic":"/ˈwɜːkmən/","meanings":[{"pos":"noun","meaning":"工人，工匠","usage":"指做体力工作的人"}]},{"word":"acquainted","phonetic":"/əˈkweɪntɪd/","meanings":[{"pos":"adj","meaning":"熟悉的，了解的","usage":"与be acquainted with搭配使用"}]},{"word":"inhabit","phonetic":"/ɪnˈhæbɪt/","meanings":[{"pos":"verb","meaning":"居住于，栖居于","usage":"指居住在某个地方"}]},{"word":"assume","phonetic":"/əˈsjuːm/","meanings":[{"pos":"verb","meaning":"假定，假设","usage":"指未证实的情况下认为某事是真实的"}]},{"word":"separate","phonetic":"/ˈsepəreɪt/","meanings":[{"pos":"verb","meaning":"分隔，使分离","usage":"指将原本在一起的东西分开"}]},{"word":"scorn","phonetic":"/skɔːn/","meanings":[{"pos":"noun/verb","meaning":"轻蔑，鄙视","usage":"表达对某人或某事的藐视"}]}],"phrases":[{"phrase":"bring to a conclusion","usage":"使……结束，给……收尾","examples":[{"en":"A novelist would bring his story to a conclusion by presenting coincidences.","zh":"小说家会通过呈现一系列巧合来给故事收尾。"}]},{"phrase":"pour scorn on","usage":"对……嗤之以鼻，嘲笑","examples":[{"en":"Franz poured scorn on the idea.","zh":"弗朗茨对这个想法嗤之以鼻。"}]},{"phrase":"be acquainted with","usage":"熟悉，了解","examples":[{"en":"Mrs. Bussman was fully acquainted with this story.","zh":"布斯曼太太对这件事非常了解。"}]},{"phrase":"a chance in a million","usage":"极小的可能性，万分之一的可能","examples":[{"en":"There was a chance in a million that she might be right.","zh":"她可能是对的，这种可能性微乎其微。"}]},{"phrase":"how it was that","usage":"……是怎么回事","examples":[{"en":"Hans explained how it was that he was still alive.","zh":"汉斯解释了他是如何活下来的。"}]},{"phrase":"make one's way","usage":"前往，走向","examples":[{"en":"Hans had made his way back into Western Germany on foot.","zh":"汉斯步行回到了西德。"}]},{"phrase":"settle down","usage":"定居，安顿下来","examples":[{"en":"Hans settled down in a village fifty miles away.","zh":"汉斯在五十英里外的一个村庄定居下来。"}]},{"phrase":"be thought to have been","usage":"被认为曾是……","examples":[{"en":"He was thought to have been killed twenty years before.","zh":"人们以为他二十年前就已经死了。"}]},{"phrase":"in real life","usage":"在现实生活中","examples":[{"en":"Yet, in real life, circumstances do sometimes conspire to bring about coincidences.","zh":"然而，在现实生活中，情况有时确实会凑巧带来巧合。"}]},{"phrase":"long-lost","usage":"失散已久的","examples":[{"en":"He really was Franz's long-lost brother.","zh":"他确实是弗朗茨失散多年的兄弟。"}]}],"grammar":[{"title":"过去完成时 (Past Perfect Tense)","definition":"表示在过去某一时刻之前已经完成的动作，常用于描述过去的过去发生的事","structure":"had + 过去分词","usage":"用于叙述过去事件时，表示先发生的动作，常与一般过去时连用","examples":[{"en":"He had been wounded towards the end of the war.","zh":"他在战争末期受了伤。"},{"en":"The hospital had been bombed and all records had been destroyed.","zh":"医院被炸毁了，所有记录都被销毁了。"}]},{"title":"过去分词短语作状语","definition":"过去分词可以作状语，表示原因、时间、方式等","structure":"Having + 过去分词 或 过去分词","usage":"用来简化从句，使句子更加简洁","examples":[{"en":"After having been wounded, he had been sent to hospital.","zh":"受伤后，他被送进了医院。"},{"en":"Assuming that his family had been killed, Hans settled down in a village.","zh":"以为家人在空袭中遇难了，汉斯在一个村庄安顿下来。"}]},{"title":"间接引语 (Indirect Speech) - 过去完成时的使用","definition":"在间接引语中，如果引用的动作发生在主句动作之前，且时间已过，需用过去完成时","structure":"主句动词 + that + 主语 + had + 过去分词","usage":"用于转述别人说过的话，且所转述的内容在转述之前就已发生","examples":[{"en":"Hans explained how it was that he was still alive.","zh":"汉斯解释了他是如何活下来的。"},{"en":"She thought there was a chance she might be right.","zh":"她认为她可能是对的。"}]}],"patterns":[{"pattern":"While + doing..., 主语 + 动词...","explanation":"","original":{"en":"While on a walking tour with his wife, he stopped to talk to a workman.","zh":"在和妻子徒步旅行时，他停下来和一个工人聊天。"},"examples":[{"en":"While waiting for the bus, she read a book.","zh":"等公交车时，她读了一本书。"},{"en":"While traveling in Europe, they visited many museums.","zh":"在欧洲旅行时，他们参观了很多博物馆。"}]},{"pattern":"needless to say, ...","explanation":"","original":{"en":"Needless to say, the man's name was Hans Bussman.","zh":"不用说，这个人的名字就是汉斯·布斯曼。"},"examples":[{"en":"Needless to say, he passed the exam easily.","zh":"不用说，他轻松地通过了考试。"},{"en":"Needless to say, she was very happy about the news.","zh":"不用说，她对这个消息非常高兴。"}]},{"pattern":"It is + adj + that ...","explanation":"","original":{"en":"Modern readers would find such naive solutions totally unacceptable.","zh":"现代读者会觉得这种幼稚的解决方法完全不可接受。"},"examples":[{"en":"I find it incredible that such coincidences happen.","zh":"我觉得这样的巧合发生真是令人难以置信。"},{"en":"They consider it possible that he survived the war.","zh":"他们认为他在战争中存活下来是可能的。"}]},{"pattern":"主语 + suggested that + 主语 + might be / might have been","explanation":"","original":{"en":"She even suggested that he might be his brother.","zh":"她甚至猜测他可能是他的兄弟。"},"examples":[{"en":"The doctor suggested that she might be allergic to something.","zh":"医生说她可能对什么东西过敏。"},{"en":"He suggested that the letter might have been lost.","zh":"他猜测那封信可能丢了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“相似，相像” 对应的单词是？","hint":"noun · /rɪˈzembləns/","options":["accompany","capture","resemblance","stray"],"answer":2,"explain":"resemblance · /rɪˈzembləns/ · noun · 相似，相像。指外貌或特征的相似","source":{"kind":"vocab","word":"resemblance"},"id":"b3-u36-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：密谋，策划","hint":"/plɒt/ · verb","answer":"plot","placeholder":"输入英文单词","explain":"plot · /plɒt/ · verb · 密谋，策划。指暗中计划做坏事","source":{"kind":"vocab","word":"plot"},"id":"b3-u36-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：He really was Franz's _____ brother.","hint":"他确实是弗朗茨失散多年的兄弟。","answer":"long-lost","placeholder":"输入缺失的短语","explain":"long-lost：失散已久的（他确实是弗朗茨失散多年的兄弟。）","source":{"kind":"phrase","phrase":"long-lost"},"id":"b3-u36-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ a brother who was thought to have been killed twenty years before.","hint":"他找到了一个被认为在20年前阵亡的兄弟。","answer":"found","placeholder":"输入缺失的单词","explain":"found a brother who was thought to have been killed twenty years before. — 他找到了一个被认为在20年前阵亡的兄弟。","source":{"kind":"sentence","en":"found a brother who was thought to have been killed twenty years before."},"id":"b3-u36-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“过去分词可以作状语，表示原因、时间、方式等” 描述的是哪个语法点？","hint":"Having + 过去分词 或 过去分词","options":["Only + 状语 置于句首的倒装","过去完成时的被动语态","间接引语（陈述句的转换）","过去分词短语作状语"],"answer":3,"explain":"过去分词短语作状语：Having + 过去分词 或 过去分词：用来简化从句，使句子更加简洁","source":{"kind":"grammar","title":"过去分词短语作状语"},"id":"b3-u36-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nHans settled down in a village fifty miles away where he had remained ever since.","hint":"","options":["汉斯在一个五十英里外的小村庄安顿下来，自此一直住在那里。","自己动手游戏的糟糕之处在于，有时连男人也活在自己无所不能的错觉中，","僧侣们更喜欢冬天而不是夏天，因为他们有更多的隐私。","它是由一名大学生烘烤的，他使用了超过1000磅面粉、800磅糖、"],"answer":0,"explain":"Hans settled down in a village fifty miles away where he had remained ever since. — 汉斯在一个五十英里外的小村庄安顿下来，自此一直住在那里。","source":{"kind":"sentence","en":"Hans settled down in a village fifty miles away where he had remained ever since."},"id":"b3-u36-q06"}]},{"id":"b3-u37","book":3,"unit":37,"key":"37","lessonFrom":37,"lessonTo":37,"title":"The Westhaven Express","titleZh":"韦斯特黑文特快","question":"What was the mistake the author made?","sentences":[{"en":"We have learnt to expect that trains will be punctual.","zh":"我们已经习惯了认为火车是准时的。","t":14.04},{"en":"After years of conditioning, most of us have developed an unshakable faith in railway timetables.","zh":"经过多年的条件反射，我们大多数人对火车时刻表都产生了不可动摇的信任。","t":18.46},{"en":"Ships may be delayed by storms;","zh":"船只可能因风暴而延误；","t":26.14},{"en":"flights may be cancelled because of bad weather; but trains must be on time.","zh":"航班可能因恶劣天气而取消；但火车必须准时。","t":28.93},{"en":"Only an exceptionally heavy snow fall might temporarily dislocate railway services.","zh":"只有异常大的降雪才可能暂时打乱铁路服务。","t":35.9},{"en":"It is all too easy to blame the railway authorities when something does go wrong.","zh":"当事情出错时，责备铁路当局实在是太容易了。","t":43.33},{"en":"The truth is that when mistakes occur, they are more likely to be ours than theirs.","zh":"事实是，当错误发生时，它们更有可能是我们的，而不是他们的。","t":49.57},{"en":"After consulting my railway timetable, I noted with satisfaction that there was an express train to Westhaven.","zh":"查阅了我的火车时刻表后，我满意地注意到有一趟开往韦斯特黑文的特快列车。","t":56.76},{"en":"It went direct from my local station and the journey lasted a mere hour and seventeen minutes.","zh":"它直接从我当地的车站出发，行程仅需一小时十七分钟。","t":66},{"en":"When I boarded the train, I could not help noticing that a great many local people got on as well.","zh":"当我登上火车时，我不禁注意到许多当地人也上车了。","t":73.55},{"en":"At the time, this did not strike me as odd.","zh":"当时，这并没有让我觉得奇怪。","t":81.11},{"en":"I reflected that there must be a great many people besides myself who wished to take advantage of this excellent service.","zh":"我想，除了我自己之外，肯定有很多人也希望利用这项优质服务。","t":84.97},{"en":"Neither was I surprised when the train stopped at Widley, a tiny station a few miles along the line.","zh":"当火车在离铁路线几英里外的一个小站威德利停靠时，我也没有感到惊讶。","t":93.31},{"en":"Even a mighty express train can be held up by signals.","zh":"即使是强大的特快列车也可能被信号灯拦住。","t":101.74},{"en":"But when the train dawdled at station after station, I began to wonder.","zh":"但当火车在一个又一个车站磨蹭时，我开始感到疑惑。","t":105.94},{"en":"It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty.","zh":"我突然意识到，这趟特快列车并不是以每小时九十英里的速度呼啸而过，而是以每小时三十英里的速度缓慢行驶。","t":112.11},{"en":"One hour and seventeen minutes passed and we had not even covered half the distance.","zh":"一小时十七分钟过去了，我们甚至还没有走完一半的路程。","t":122.9},{"en":"I asked a passenger if this was the Westhaven Express, but he had not even heard of it.","zh":"我问一位乘客这是否是韦斯特黑文特快，但他甚至没有听说过。","t":129.85},{"en":"I determined to lodge a complaint as soon as we arrived.","zh":"我决定一到站就投诉。","t":136.56},{"en":"Two hours later, I was talking angrily to the station master at Westhaven.","zh":"两个小时后，我正在韦斯特黑文车站愤怒地与站长交谈。","t":141.06},{"en":"When he denied the train's existence, I borrowed his copy of the timetable.","zh":"当他否认这趟火车存在时，我借了他的时刻表。","t":147.3},{"en":"There was a note of triumph in my voice when I told him that it was there in black and white.","zh":"当我告诉他白纸黑字写着时，我的声音带着一丝胜利。","t":153.44},{"en":"Glancing at it briefly, he told me to look again.","zh":"他简短地瞥了一眼，然后告诉我再看一次。","t":160.49},{"en":"A tiny asterisk conducted me to a footnote at the bottom of the page.","zh":"一个小小的星号引导我看到了页面底部的脚注。","t":165.15},{"en":"It said: 'This service has been suspended.'","zh":"它写着：“此项服务已暂停。”","t":170.96}],"vocab":[{"word":"punctual","phonetic":"/ˈpʌŋktʃuəl/","meanings":[{"pos":"adjective","meaning":"准时的，守时的","usage":"用来描述人或交通工具按照约定时间到达或完成的状态"}]},{"word":"conditioning","phonetic":"/kənˈdɪʃənɪŋ/","meanings":[{"pos":"noun","meaning":"训练，条件作用","usage":"指长期的环境影响或反复经历形成的固定思维、行为模式"}]},{"word":"unshakable","phonetic":"/ʌnˈʃeɪkəbl/","meanings":[{"pos":"adjective","meaning":"不可动摇的，坚定不移的","usage":"常用来修饰信念、信仰、决心等抽象名词，表示其非常稳固"}]},{"word":"dislocate","phonetic":"/ˈdɪsləkeɪt/","meanings":[{"pos":"verb","meaning":"扰乱，使混乱；使脱位","usage":"作“扰乱”义时，宾语多为服务、计划、系统等事物"}]},{"word":"temporarily","phonetic":"/ˈtemprərəli/","meanings":[{"pos":"adverb","meaning":"暂时地，临时地","usage":"用来修饰动作或状态，表示其只持续有限的时间"}]},{"word":"express","phonetic":"/ɪkˈspres/","meanings":[{"pos":"noun","meaning":"快车；快递","usage":"作名词时可指特快列车、快递服务；也可作形容词表示“特快的”"}]},{"word":"mere","phonetic":"/mɪə(r)/","meanings":[{"pos":"adjective","meaning":"仅仅的，只不过的","usage":"用来强调数量少、程度轻，放在名词前修饰"}]},{"word":"strike","phonetic":"/straɪk/","meanings":[{"pos":"verb","meaning":"给（某人以……）印象，让（某人）觉得","usage":"常用结构为it strikes sb as + adj. 表示“某人觉得某事怎么样”"}]},{"word":"odd","phonetic":"/ɒd/","meanings":[{"pos":"adjective","meaning":"奇怪的，反常的","usage":"用来描述事物或情况不符合常理、令人疑惑"}]},{"word":"reflect","phonetic":"/rɪˈflekt/","meanings":[{"pos":"verb","meaning":"认真思考，沉思","usage":"后可接that从句或者on/upon sth，表示对某事进行深入思考"}]},{"word":"dawdle","phonetic":"/ˈdɔːdl/","meanings":[{"pos":"verb","meaning":"拖延，磨蹭，缓慢行进","usage":"可作不及物动词，表示动作缓慢、浪费时间"}]},{"word":"dawn","phonetic":"/dɔːn/","meanings":[{"pos":"verb","meaning":"开始明白，开始领悟","usage":"常用结构it dawns on sb that... 表示“某人逐渐明白某事”"}]},{"word":"barely","phonetic":"/ˈbeəli/","meanings":[{"pos":"adverb","meaning":"仅仅，几乎不","usage":"表示刚刚达到某个最低程度，暗含数量少、程度低的含义"}]},{"word":"lodge","phonetic":"/lɒdʒ/","meanings":[{"pos":"verb","meaning":"正式提出（投诉、索赔等）","usage":"常见搭配为lodge a complaint/protest/claim against sb"}]},{"word":"suspend","phonetic":"/səˈspend/","meanings":[{"pos":"verb","meaning":"暂停，中止","usage":"宾语多为服务、活动、航班等，表示其暂时停止运营或开展"}]}],"phrases":[{"phrase":"take advantage of","usage":"表示利用某种有利条件、机会或服务，中性用法","examples":[{"en":"You should take advantage of the free library resources to improve your English.","zh":"你应该利用免费的图书馆资源来提升你的英语水平。"},{"en":"Many tourists take advantage of the low season to travel at a lower cost.","zh":"很多游客利用淡季以更低的成本出行。"}]},{"phrase":"hold up","usage":"被动语态中表示“被耽搁、被延误”，主语通常是交通工具、行程等","examples":[{"en":"We were held up for two hours on the highway because of the car accident.","zh":"因为车祸，我们在高速公路上被耽搁了两个小时。"},{"en":"The project was held up by a lack of funding.","zh":"这个项目因为资金短缺被延误了。"}]},{"phrase":"dawn on sb","usage":"表示某人逐渐明白、突然意识到某个之前没注意到的事实，主语通常是it","examples":[{"en":"It dawned on me that I had left my keys at the office when I got home.","zh":"我到家的时候才突然意识到我把钥匙落在办公室了。"},{"en":"It finally dawned on him that all the suggestions his parents gave were for his own good.","zh":"他终于明白父母给的所有建议都是为了他好。"}]},{"phrase":"in black and white","usage":"表示“以书面形式、白纸黑字”，强调内容有正式的文字记录，不容否认","examples":[{"en":"I want the terms of our agreement in black and white to avoid future disputes.","zh":"我希望我们的协议条款白纸黑字写下来，避免未来产生纠纷。"},{"en":"You can't deny you made the promise—it's here in black and white.","zh":"你不能否认你许下过这个承诺——这里白纸黑字写着呢。"}]},{"phrase":"lodge a complaint","usage":"表示正式向相关方提出投诉，语气比较正式","examples":[{"en":"If the noise from the construction site continues, I will lodge a complaint with the property management.","zh":"如果工地的噪音还继续，我就要向物业投诉了。"},{"en":"Many customers lodged complaints against the restaurant for its poor hygiene conditions.","zh":"很多顾客投诉这家餐厅卫生条件很差。"}]},{"phrase":"strike sb as odd","usage":"表示某人觉得某事很奇怪、反常","examples":[{"en":"It strikes me as odd that he never mentions his family when we talk.","zh":"我们聊天的时候他从来没提过他的家人，我觉得很奇怪。"},{"en":"Her sudden change of attitude struck everyone as odd.","zh":"她突然的态度转变让所有人都觉得反常。"}]},{"phrase":"can't help doing sth","usage":"表示忍不住、情不自禁做某事","examples":[{"en":"I can't help laughing every time I watch that comedy show.","zh":"我每次看那个喜剧节目都忍不住笑。"},{"en":"She couldn't help crying when she heard the bad news.","zh":"她听到这个坏消息的时候忍不住哭了。"}]}],"grammar":[{"title":"部分倒装 (Partial Inversion)","definition":"将谓语的一部分（如助动词、情态动词）放到主语前面的倒装结构，通常用于否定词或半否定词放在句首的情况","structure":"Negative word/phrase + 助动词/情态动词 + 主语 + 谓语动词剩余部分","usage":"当neither, nor, never, hardly, seldom等否定或半否定含义的词/短语放在句首时，句子需要使用部分倒装，来强调否定的含义","examples":[{"en":"Neither was I surprised when the train stopped at Widley, a tiny station a few miles along the line.","zh":"当火车在沿线几英里外的小站威德利停靠时，我也没有感到惊讶。"},{"en":"Never have I seen such a beautiful sunset in my life.","zh":"我这辈子从来没见过这么美的日落。"},{"en":"Seldom does he go to bed before 11 o'clock on weekdays.","zh":"工作日他很少在11点前睡觉。"}]},{"title":"情态动词表推测 (Modal Verbs for Deduction)","definition":"用must, might, may, can't等情态动词对现在或过去的情况进行可能性判断","structure":"情态动词 + 动词原形（对现在的推测）/ have done（对过去的推测）","usage":"must表示非常肯定的推测“一定”，might/may表示可能性较低的推测“可能”，can't表示否定推测“不可能”","examples":[{"en":"I reflected that there must be a great many people besides myself who wished to take advantage of this excellent service.","zh":"我心想，除了我之外，肯定还有很多人想要享受这项优质的服务。"},{"en":"The ground is wet. It must have rained last night.","zh":"地面是湿的，昨晚肯定下雨了。"},{"en":"He might come to the party tonight, but I'm not sure.","zh":"他今晚可能会来派对，但我不确定。"}]}],"patterns":[{"pattern":"We have learnt to expect that...","explanation":"","original":{"en":"We have learnt to expect that trains will be punctual.","zh":"我们已经习惯于期待火车准点。"},"examples":[{"en":"We have learnt to expect that the delivery will arrive within three working days.","zh":"我们已经习惯于期待快递会在三个工作日内送达。"},{"en":"We have learnt to expect that the coffee shop will be open at 7 a.m. every day.","zh":"我们已经习惯于期待这家咖啡店每天早上7点开门。"}]},{"pattern":"It suddenly dawned on me that...","explanation":"","original":{"en":"It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty.","zh":"我突然意识到，这趟快车并没有以90英里的时速在轨道上疾驰，而是只以30英里的时速突突地缓慢前进。"},"examples":[{"en":"It suddenly dawned on me that I had signed up for the speech contest next week.","zh":"我突然想起我报名了下周的演讲比赛。"},{"en":"It suddenly dawned on me that the answer to the problem was much simpler than I thought.","zh":"我突然意识到这个问题的答案比我想的要简单得多。"}]},{"pattern":"There was a note of + 情绪名词 + in one's voice when...","explanation":"","original":{"en":"There was a note of triumph in my voice when I told him that it was there in black and white.","zh":"我告诉他白纸黑字写在那儿的时候，声音里带着一丝得意。"},"examples":[{"en":"There was a note of disappointment in her voice when she said she failed the exam.","zh":"她说自己考试没及格的时候，声音里带着一丝失望。"},{"en":"There was a note of excitement in his voice when he told us he got the offer.","zh":"他告诉我们他拿到录用通知的时候，声音里带着一丝兴奋。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“暂停，中止” 对应的单词是？","hint":"verb · /səˈspend/","options":["confirm","grateful","suspend","grease"],"answer":2,"explain":"suspend · /səˈspend/ · verb · 暂停，中止。宾语多为服务、活动、航班等，表示其暂时停止运营或开展","source":{"kind":"vocab","word":"suspend"},"id":"b3-u37-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：不可动摇的，坚定不移的","hint":"/ʌnˈʃeɪkəbl/ · adjective","answer":"unshakable","placeholder":"输入英文单词","explain":"unshakable · /ʌnˈʃeɪkəbl/ · adjective · 不可动摇的，坚定不移的。常用来修饰信念、信仰、决心等抽象名词，表示其非常稳固","source":{"kind":"vocab","word":"unshakable"},"id":"b3-u37-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：You can't deny you made the promise—it's here _____.","hint":"你不能否认你许下过这个承诺——这里白纸黑字写着呢。","answer":"in black and white","placeholder":"输入缺失的短语","explain":"in black and white：表示“以书面形式、白纸黑字”，强调内容有正式的文字记录，不容否认（你不能否认你许下过这个承诺——这里白纸黑字写着呢。）","source":{"kind":"phrase","phrase":"in black and white"},"id":"b3-u37-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：When I boarded the train, I could not help _____ that a great many local people got on as well.","hint":"当我登上火车时，我不禁注意到许多当地人也上车了。","answer":"noticing","placeholder":"输入缺失的单词","explain":"When I boarded the train, I could not help noticing that a great many local people got on as well. — 当我登上火车时，我不禁注意到许多当地人也上车了。","source":{"kind":"sentence","en":"When I boarded the train, I could not help noticing that a great many local people got on as well."},"id":"b3-u37-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用must, might, may, can't等情态动词对现在或过去的情况进行可能性判断” 描述的是哪个语法点？","hint":"情态动词 + 动词原形（对现在的推测）/ have done（对过去的推测）","options":["even though/even if引导的让步状语从句","情态动词表推测 (Modal Verbs for Deduction)","非限制性定语从句","虚拟语气在suggest后的宾语从句中的用法"],"answer":1,"explain":"情态动词表推测 (Modal Verbs for Deduction)：情态动词 + 动词原形（对现在的推测）/ have done（对过去的推测）：must表示非常肯定的推测“一定”，might/may表示可能性较低的推测“可能”，can't表示否定推测“不可能”","source":{"kind":"grammar","title":"情态动词表推测 (Modal Verbs for Deduction)"},"id":"b3-u37-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAfter consulting my railway timetable, I noted with satisfaction that there was an express train to Westhaven.","hint":"","options":["结果，人类学会了尊重猫的独立性。","如我所料，他没有相信我。","她撞到了家具，嘴里不停地咕哝着关于客人的话。","查阅了我的火车时刻表后，我满意地注意到有一趟开往韦斯特黑文的特快列车。"],"answer":3,"explain":"After consulting my railway timetable, I noted with satisfaction that there was an express train to Westhaven. — 查阅了我的火车时刻表后，我满意地注意到有一趟开往韦斯特黑文的特快列车。","source":{"kind":"sentence","en":"After consulting my railway timetable, I noted with satisfaction that there was an express train to Westhaven."},"id":"b3-u37-q06"}]},{"id":"b3-u38","book":3,"unit":38,"key":"38","lessonFrom":38,"lessonTo":38,"title":"The First Calendar","titleZh":"第一个日历","question":"What is the importance of the dots, lines, and symbols engraved on stone, bones and ivory?","sentences":[{"en":"Future historians will be in a unique position when they come to record the history of our own times.","zh":"未来的历史学家在记录我们这个时代的历史时将处于独特的地位。","t":20.52},{"en":"They will hardly know which facts to select from the great mass of evidence that steadily accumulates.","zh":"他们将很难知道从不断积累的大量证据中选择哪些事实。","t":28.58},{"en":"What is more, they will not have to rely solely on the written word.","zh":"更重要的是，他们不必仅仅依赖书面文字。","t":37.07},{"en":"Films, videos, CDs and CD-ROMs are just some of the bewildering amount of information they will have.","zh":"电影、视频、CD和CD-ROM只是他们将拥有的令人眼花缭乱的信息中的一部分。","t":42.25},{"en":"They will be able, as it were, to see and hear us in action.","zh":"他们将能够，可以说，看到和听到我们的行动。","t":52.41},{"en":"But the historian attempting to reconstruct the distant past is always faced with a difficult task.","zh":"但是，试图重构遥远过去的历史学家总是面临一项艰巨的任务。","t":58.9},{"en":"He has to deduce what he can from the few scanty clues available.","zh":"他必须从仅有的稀少线索中推断出他所能推断的一切。","t":67},{"en":"Even seemingly insignificant remains can shed interesting light on the history of early man.","zh":"即使看似微不足道的遗迹也能为早期人类的历史提供有趣的线索。","t":72.61},{"en":"Up to now, historians have assumed that calendars came into being with the advent of agriculture,","zh":"迄今为止，历史学家一直认为日历是随着农业的出现而产生的，","t":80.69},{"en":"for then man was faced with a real need to understand something about the seasons.","zh":"因为那时人类确实需要了解一些关于季节的知识。","t":88.67},{"en":"Recent scientific evidence seems to indicate that this assumption is incorrect.","zh":"最近的科学证据似乎表明这个假设是错误的。","t":95.55},{"en":"Historians have long been puzzled by dots, lines and symbols which have been engraved on walls, bones, and the ivory tusks of mammoths.","zh":"历史学家长期以来一直对刻在墙壁、骨头和猛犸象牙上的点、线和符号感到困惑。","t":103.01},{"en":"The nomads who made these markings lived by hunting and fishing during the last Ice Age which began about 35,000 B.C. and ended about 10,000 B.C.","zh":"制造这些标记的游牧民族在最后一次冰河时期（约公元前35,000年开始，约公元前10,000年结束）靠狩猎和捕鱼为生。","t":114.98},{"en":"By correlating markings made in various parts of the world,","zh":"通过关联世界各地制作的标记，","t":129.27},{"en":"historians have been able to read this difficult code.","zh":"历史学家已经能够解读这个难懂的密码。","t":133.81},{"en":"They have found that it is connected with the passage of days and the phases of the moon.","zh":"他们发现它与日子的流逝和月亮的盈亏有关。","t":138.11},{"en":"It is, in fact, a primitive type of calendar.","zh":"事实上，这是一种原始的日历。","t":144.49},{"en":"It has long been known that the hunting scenes depicted on walls were not simply a form of artistic expression.","zh":"长期以来人们都知道墙壁上描绘的狩猎场景不仅仅是一种艺术表现形式。","t":149.25},{"en":"They had a definite meaning, for they were as near as early man could get to writing.","zh":"它们具有明确的含义，因为它们是早期人类最接近书写文字的形式。","t":157.4},{"en":"It is possible that there is a definite relation between these paintings and the markings that sometimes accompany them.","zh":"这些绘画与有时伴随它们的标记之间可能存在明确的关系。","t":163.94},{"en":"It seems that man was making a real effort to understand the seasons 20, 000 years earlier than has been supposed.","zh":"看来人类早在比人们猜测的20,000年前就在真正努力理解季节了。","t":173.58}],"vocab":[{"word":"engrave","phonetic":"/ɪnˈɡreɪv/","meanings":[{"pos":"verb","meaning":"雕刻；刻上","usage":"指在硬物上刻字或图案"}]},{"word":"ivory","phonetic":"/ˈaɪvəri/","meanings":[{"pos":"noun","meaning":"象牙；象牙制品","usage":"指大象的长牙，也可指类似质地的物质"}]},{"word":"historian","phonetic":"/hɪˈstɔːriən/","meanings":[{"pos":"noun","meaning":"历史学家","usage":"研究或记录历史的人"}]},{"word":"bewildering","phonetic":"/bɪˈwɪldərɪŋ/","meanings":[{"pos":"adj","meaning":"令人困惑的；使人眼花缭乱的","usage":"形容数量多或复杂让人难以理解"}]},{"word":"deduce","phonetic":"/dɪˈdjuːs/","meanings":[{"pos":"verb","meaning":"推断；演绎","usage":"根据已知信息进行逻辑推理得出结论"}]},{"word":"scanty","phonetic":"/ˈskænti/","meanings":[{"pos":"adj","meaning":"稀少的；不足的","usage":"形容数量少或不充分"}]},{"word":"advent","phonetic":"/ˈædvent/","meanings":[{"pos":"noun","meaning":"出现；到来","usage":"指重要事件或时期的到来"}]},{"word":"correlate","phonetic":"/ˈkɒrəleɪt/","meanings":[{"pos":"verb","meaning":"使相互关联；联系","usage":"找出两个或多个事物之间的相互关系"}]},{"word":"depict","phonetic":"/dɪˈpɪkt/","meanings":[{"pos":"verb","meaning":"描绘；描述","usage":"用图画或文字描述某人或某事"}]},{"word":"accompany","phonetic":"/əˈkʌmpəni/","meanings":[{"pos":"verb","meaning":"伴随；陪伴","usage":"与...一起出现或发生"}]},{"word":"nomad","phonetic":"/ˈnəʊmæd/","meanings":[{"pos":"noun","meaning":"游牧民；流浪者","usage":"没有固定住所、逐水草而居的人"}]},{"word":"phase","phonetic":"/feɪz/","meanings":[{"pos":"noun","meaning":"阶段；月相","usage":"指发展过程中的一个阶段，或月亮的盈亏"}]},{"word":"clue","phonetic":"/kluː/","meanings":[{"pos":"noun","meaning":"线索；提示","usage":"帮助解决问题或找到答案的信息"}]},{"word":"shed light on","phonetic":"/ʃed laɪt ɒn/","meanings":[{"pos":"phrase","meaning":"阐明；使...清楚","usage":"使某事更易理解或解释"}]},{"word":"agriculture","phonetic":"/ˈæɡrɪkʌltʃə/","meanings":[{"pos":"noun","meaning":"农业","usage":"耕种土地、生产农作物的活动"}]}],"phrases":[{"phrase":"come to record","usage":"开始记录；着手记录","examples":[{"en":"Future historians will be in a unique position when they come to record the history of our own times.","zh":"未来的历史学家在着手记录我们这个时代的历史时，将处于独特的地位。"}]},{"phrase":"as it were","usage":"可以说；仿佛","examples":[{"en":"They will be able, as it were, to see and hear us in action.","zh":"可以说，他们将能够看到和听到我们的一举一动。"}]},{"phrase":"shed light on","usage":"阐明；揭示","examples":[{"en":"Even seemingly insignificant remains can shed interesting light on the history of early man.","zh":"即使是看似不重要的遗迹也能揭示早期人类历史的有趣线索。"}]},{"phrase":"up to now","usage":"到目前为止；迄今","examples":[{"en":"Up to now, historians have assumed that calendars came into being with the advent of agriculture.","zh":"到目前为止，历史学家一直认为日历是随着农业的出现而产生的。"}]},{"phrase":"have long been known","usage":"早已为人所知","examples":[{"en":"It has long been known that the hunting scenes depicted on walls were not simply a form of artistic expression.","zh":"人们早已知道，墙上描绘的狩猎场景不仅仅是艺术表现形式。"}]},{"phrase":"be connected with","usage":"与...有关联","examples":[{"en":"They have found that it is connected with the passage of days and the phases of the moon.","zh":"他们发现它与日月的推移和月相有关。"}]},{"phrase":"be faced with","usage":"面对；面临","examples":[{"en":"For then man was faced with a real need to understand something about the seasons.","zh":"因为那时人类确实需要了解季节的变化。"}]},{"phrase":"make an effort","usage":"努力；尽力","examples":[{"en":"It seems that man was making a real effort to understand the seasons 20,000 years earlier than has been supposed.","zh":"看来人类早在人们想象的2万年前就在努力了解季节的变化了。"}]},{"phrase":"what is more","usage":"更重要的是；而且","examples":[{"en":"What is more, they will not have to rely solely on the written word.","zh":"更重要的是，他们不必完全依赖文字记载。"}]},{"phrase":"in fact","usage":"事实上；实际上","examples":[{"en":"It is, in fact, a primitive type of calendar.","zh":"实际上，这是一种原始的日历。"}]}],"grammar":[{"title":"将来完成进行时 (Future Perfect Continuous)","definition":"表示在将来某一时刻之前已经开始并持续进行的动作，强调动作的持续性。","structure":"主语 + will have been + 动词-ing","usage":"用于强调一个从过去开始、持续到将来某时的动作","examples":[{"en":"By the time they finish, they will have been working for ten hours.","zh":"到他们完成时，他们将已经工作了十个小时。"}]},{"title":"现在完成时 (Present Perfect)","definition":"表示过去发生的动作或存在的状态，对现在造成影响或持续到现在。","structure":"主语 + have/has + 过去分词","usage":"用于描述过去的动作或状态与现在的联系，或从过去持续到现在的情况","examples":[{"en":"Historians have long been puzzled by dots, lines and symbols.","zh":"历史学家长期以来对点、线和符号感到困惑。"},{"en":"Recent scientific evidence seems to indicate that this assumption is incorrect.","zh":"最近的科学证据似乎表明这个假设是不正确的。"}]},{"title":"名词性从句 (Noun Clauses)","definition":"由连接词引导的从句，在句中起名词作用，可作主语、宾语、表语等。","structure":"连接词(what/that/whether/if等) + 陈述句","usage":"用于表达复杂的概念或思想，使句子更加正式和学术化","examples":[{"en":"What is more, they will not have to rely solely on the written word.","zh":"更重要的是，他们不必完全依赖文字记载。"},{"en":"What is the importance of the dots, lines, and symbols?","zh":"这些刻在石头、骨骼和象牙上的点、线和符号有什么重要意义？"}]}],"patterns":[{"pattern":"What is more, ...","explanation":"","original":{"en":"What is more, they will not have to rely solely on the written word.","zh":"更重要的是，他们不必完全依赖文字记载。"},"examples":[{"en":"What is more, he is also a talented musician.","zh":"更重要的是，他还是一个有才华的音乐家。"},{"en":"What is more, the price is very reasonable.","zh":"而且，价格也非常合理。"}]},{"pattern":"Even + 形容词/副词比较级 + 主语 + 动词...","explanation":"","original":{"en":"Even seemingly insignificant remains can shed interesting light on the history of early man.","zh":"即使是看似不重要的遗迹也能揭示早期人类历史的有趣线索。"},"examples":[{"en":"Even small mistakes can lead to serious consequences.","zh":"即使是小的错误也可能导致严重的后果。"},{"en":"Even a slight change can make a big difference.","zh":"即使微小的改变也能产生很大的不同。"}]},{"pattern":"It seems that + 主语 + 动词...","explanation":"","original":{"en":"It seems that man was making a real effort to understand the seasons.","zh":"看来人类是在努力了解季节的变化。"},"examples":[{"en":"It seems that the weather is getting worse.","zh":"看起来天气正在变坏。"},{"en":"It seems that she has already finished the work.","zh":"看来她已经完成了工作。"}]},{"pattern":"主语 + have/has long been + 过去分词...","explanation":"","original":{"en":"It has long been known that the hunting scenes depicted on walls were not simply a form of artistic expression.","zh":"人们早已知道，墙上描绘的狩猎场景不仅仅是艺术表现形式。"},"examples":[{"en":"It has long been believed that practice makes perfect.","zh":"人们一直相信熟能生巧。"},{"en":"It has long been recognized that education is important.","zh":"人们早就认识到教育的重要性。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“阶段；月相” 对应的单词是？","hint":"noun · /feɪz/","options":["fertilizer","exceptional","colourful","phase"],"answer":3,"explain":"phase · /feɪz/ · noun · 阶段；月相。指发展过程中的一个阶段，或月亮的盈亏","source":{"kind":"vocab","word":"phase"},"id":"b3-u38-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：推断；演绎","hint":"/dɪˈdjuːs/ · verb","answer":"deduce","placeholder":"输入英文单词","explain":"deduce · /dɪˈdjuːs/ · verb · 推断；演绎。根据已知信息进行逻辑推理得出结论","source":{"kind":"vocab","word":"deduce"},"id":"b3-u38-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：They will be able, _____, to see and hear us in action.","hint":"可以说，他们将能够看到和听到我们的一举一动。","answer":"as it were","placeholder":"输入缺失的短语","explain":"as it were：可以说；仿佛（可以说，他们将能够看到和听到我们的一举一动。）","source":{"kind":"phrase","phrase":"as it were"},"id":"b3-u38-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Films, videos, CDs and _____ are just some of the bewildering amount of information they will have.","hint":"电影、视频、CD和CD-ROM只是他们将拥有的令人眼花缭乱的信息中的一部分。","answer":"CD-ROMs","placeholder":"输入缺失的单词","explain":"Films, videos, CDs and CD-ROMs are just some of the bewildering amount of information they will have. — 电影、视频、CD和CD-ROM只是他们将拥有的令人眼花缭乱的信息中的一部分。","source":{"kind":"sentence","en":"Films, videos, CDs and CD-ROMs are just some of the bewildering amount of information they will have."},"id":"b3-u38-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在将来某一时刻之前已经开始并持续进行的动作，强调动作的持续性。” 描述的是哪个语法点？","hint":"主语 + will have been + 动词-ing","options":["虚拟语气在suggest后的宾语从句中的用法","过去完成时在间接引语中的使用","双关语 (Pun)","将来完成进行时 (Future Perfect Continuous)"],"answer":3,"explain":"将来完成进行时 (Future Perfect Continuous)：主语 + will have been + 动词-ing：用于强调一个从过去开始、持续到将来某时的动作","source":{"kind":"grammar","title":"将来完成进行时 (Future Perfect Continuous)"},"id":"b3-u38-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThey will hardly know which facts to select from the great mass of evidence that steadily accumulates.","hint":"","options":["古玩店对许多人来说都有一种特殊的魅力。","他们将很难知道从不断积累的大量证据中选择哪些事实。","在夏季，修道院非常繁忙，","他是故意选择他所过的这种生活的，并且完全清楚这种选择的后果。"],"answer":1,"explain":"They will hardly know which facts to select from the great mass of evidence that steadily accumulates. — 他们将很难知道从不断积累的大量证据中选择哪些事实。","source":{"kind":"sentence","en":"They will hardly know which facts to select from the great mass of evidence that steadily accumulates."},"id":"b3-u38-q06"}]},{"id":"b3-u39","book":3,"unit":39,"key":"39","lessonFrom":39,"lessonTo":39,"title":"Nothing to Worry About","titleZh":"无忧无虑","question":"What was the difference between Bruce's behaviour and that of other people?","sentences":[{"en":"The rough road across the plain soon became so bad that we tried to get Bruce to drive back to the village we had come from.","zh":"穿过平原的崎岖道路很快变得非常糟糕，以至于我们试图让布鲁斯开车回到我们来时的村庄。","t":18.55},{"en":"Even though the road was littered with boulders and pitted with holes, Bruce was not in the least perturbed.","zh":"尽管路面上布满了巨石和坑洞，布鲁斯却丝毫没有感到不安。","t":28.49},{"en":"Glancing at his map, he informed us that the next village was a mere twenty miles away.","zh":"他扫了一眼地图，告诉我们下一个村庄只有区区二十英里远。","t":37.64},{"en":"It was not that Bruce always underestimated difficulties.","zh":"并不是布鲁斯总是低估困难。","t":45.62},{"en":"He simply had no sense of danger at all.","zh":"他根本就没有危险意识。","t":49.76},{"en":"No matter what the conditions were, he believed that a car should be driven as fast as it could possibly go.","zh":"无论条件如何，他都认为汽车应该尽可能快地行驶。","t":53.87},{"en":"As we bumped over the dusty track, we swerved to avoid large boulders.","zh":"当我们在尘土飞扬的小路上颠簸时，我们猛打方向盘以避开大块巨石。","t":62.58},{"en":"The wheels scooped up stones which hammered ominously under the car.","zh":"车轮卷起石子，在车底下发出不祥的敲击声。","t":68.47},{"en":"We felt sure that sooner or later a stone would rip a hole in our petrol tank or damage the engine.","zh":"我们确信迟早会有石子把我们的油箱撕开一个洞或者损坏发动机。","t":74.9},{"en":"Because of this, we kept looking back, wondering if we were leaving a trail of oil and petrol behind us.","zh":"因此，我们不停地回头看，想知道我们是否在身后留下了一串油迹和汽油。","t":83.6},{"en":"What a relief it was when the boulders suddenly disappeared,","zh":"当巨石突然消失时，我们松了一口气，","t":93.22},{"en":"giving way to a stretch of plain where the only obstacles were clumps of bushes.","zh":"取而代之的是一片平坦的开阔地，那里唯一的障碍物是灌木丛。","t":97.45},{"en":"But there was worse to come. Just ahead of us there was a huge fissure.","zh":"但更糟糕的还在后面。就在我们前方，有一道巨大的裂缝。","t":104.64},{"en":"In response to renewed pleadings, Bruce stopped.","zh":"布鲁斯响应我们再次的恳求，停了下来。","t":111.8},{"en":"Though we all got out to examine the fissure, he remained in the car.","zh":"尽管我们都下车检查裂缝，他却仍然待在车里。","t":116.77},{"en":"We informed him that the fissure extended for fifty yards and was two feet wide and four feet deep.","zh":"我们告诉他，那道裂缝绵延五十码，宽两英尺，深四英尺。","t":122.09},{"en":"Even this had no effect.","zh":"即使这样也毫无作用。","t":131.31},{"en":"Bruce went into a low gear and drove at a terrifying speed,","zh":"布鲁斯挂入低档，以惊人的速度行驶，","t":134.88},{"en":"keeping the front wheels astride the crack as he followed its zigzag course.","zh":"让前轮跨过裂缝，沿着它之字形的路线前进。","t":140.67},{"en":"Before we had time to worry about what might happen, we were back on the plain again.","zh":"还没等我们有时间担心会发生什么，我们又回到了平原上。","t":147.14},{"en":"Bruce consulted the map once more and told us that the village was now only fifteen miles away.","zh":"布鲁斯又一次查阅了地图，告诉我们村庄现在只剩下十五英里远了。","t":154.67},{"en":"Our next obstacle was a shallow pool of water about half a mile across.","zh":"我们的下一个障碍是一个大约半英里宽的浅水池。","t":163.24},{"en":"Bruce charged at it, but in the middle, the car came to a grinding halt.","zh":"布鲁斯冲了过去，但在水池中央，汽车嘎然而止。","t":169.12},{"en":"A yellow light on the dashboard flashed angrily and Bruce cheerfully announced that there was no oil in the engine!","zh":"仪表盘上一个黄灯愤怒地闪烁着，布鲁斯却高兴地宣布发动机里没油了！","t":175.96}],"vocab":[{"word":"perturb","phonetic":"/pəˈtɜːb/","meanings":[{"pos":"verb","meaning":"使不安；使烦恼","usage":"常用被动语态be perturbed，描述人因外界因素感到焦虑、慌乱"}]},{"word":"underestimate","phonetic":"/ˌʌndərˈestɪmeɪt/","meanings":[{"pos":"verb","meaning":"低估；看轻","usage":"后可直接接名词/动名词，反义词为overestimate"}]},{"word":"bump","phonetic":"/bʌmp/","meanings":[{"pos":"verb","meaning":"颠簸而行；碰撞","usage":"表示颠簸时常与over/along搭配，描述车辆在不平路面行驶的状态"}]},{"word":"swerve","phonetic":"/swɜːv/","meanings":[{"pos":"verb","meaning":"突然转向；急转弯","usage":"常与to do搭配，表示转向的目的，也可与off搭配表示偏离路线"}]},{"word":"ominously","phonetic":"/ˈɒmɪnəsli/","meanings":[{"pos":"adverb","meaning":"不祥地；有凶兆地","usage":"修饰动作，暗示即将发生不好的事情"}]},{"word":"rip","phonetic":"/rɪp/","meanings":[{"pos":"verb","meaning":"撕破；划破","usage":"常与in/through搭配，描述外力导致物体出现裂口的状态"}]},{"word":"obstacle","phonetic":"/ˈɒbstəkl/","meanings":[{"pos":"noun","meaning":"障碍；阻碍","usage":"既可以指具体的障碍物，也可以指抽象的困难、阻碍"}]},{"word":"clump","phonetic":"/klʌmp/","meanings":[{"pos":"noun","meaning":"丛；簇；块","usage":"常与of搭配，描述密集生长的植物或聚集的块状物"}]},{"word":"fissure","phonetic":"/ˈfɪʃə(r)/","meanings":[{"pos":"noun","meaning":"裂缝；裂隙","usage":"指岩石、地面等出现的狭长深裂缝"}]},{"word":"pleading","phonetic":"/ˈpliːdɪŋ/","meanings":[{"pos":"noun","meaning":"恳求；乞求","usage":"常用复数形式，表示多次反复的请求"}]},{"word":"astride","phonetic":"/əˈstraɪd/","meanings":[{"pos":"preposition/adverb","meaning":"跨在…上；两腿分开着","usage":"描述物体或人跨越在某个事物两侧的状态"}]},{"word":"zigzag","phonetic":"/ˈzɪɡzæɡ/","meanings":[{"pos":"adjective/noun","meaning":"之字形的；锯齿形的；之字形路线","usage":"描述路线、形状呈连续的Z形转折"}]},{"word":"shallow","phonetic":"/ˈʃæləʊ/","meanings":[{"pos":"adjective","meaning":"浅的；肤浅的","usage":"既可以形容水、坑等深度浅，也可以形容人思想浅薄"}]},{"word":"charge","phonetic":"/tʃɑːdʒ/","meanings":[{"pos":"verb","meaning":"猛冲；猛攻","usage":"常与at搭配，表示向某个方向快速、鲁莽地冲过去"}]},{"word":"grinding","phonetic":"/ˈɡraɪndɪŋ/","meanings":[{"pos":"adjective","meaning":"刺耳的；摩擦的","usage":"常用来形容金属摩擦产生的难听声音，grinding halt表示戛然而止"}]}],"phrases":[{"phrase":"in the least","usage":"用于否定句中，加强否定语气，表示“一点也不，丝毫没有”","examples":[{"en":"Even though the road was littered with boulders and pitted with holes, Bruce was not in the least perturbed.","zh":"尽管路上满是大石头，坑坑洼洼，布鲁斯却一点也不慌。"},{"en":"She was not in the least surprised by the bad news.","zh":"她对这个坏消息一点也不感到惊讶。"}]},{"phrase":"give way to","usage":"表示“被…取代；让位于”，描述一种情况被另一种情况替代","examples":[{"en":"What a relief it was when the boulders suddenly disappeared, giving way to a stretch of plain where the only obstacles were clumps bushes.","zh":"大石头突然消失了，取而代之的是一片平原，唯一的障碍是一簇簇灌木丛，这让我们松了一大口气。"},{"en":"The storm gave way to bright sunshine the next morning.","zh":"第二天早上，暴风雨过后阳光明媚。"}]},{"phrase":"in response to","usage":"表示“作为对…的回应；响应”，引出某个动作的触发原因","examples":[{"en":"In response to renewed pleadings, Bruce stopped.","zh":"在我们再次恳求下，布鲁斯停了车。"},{"en":"The company changed its policy in response to customer complaints.","zh":"公司为了回应客户投诉，修改了政策。"}]},{"phrase":"go into low gear","usage":"原指车辆挂上低速挡，也可引申为“放慢节奏；低速运行”","examples":[{"en":"Bruce went into a low gear and drove at a terrifying speed.","zh":"布鲁斯挂上低速挡，以惊人的速度行驶。"},{"en":"When you climb a steep hill, you need to go into low gear.","zh":"爬陡坡的时候，你需要挂低速挡。"}]},{"phrase":"come to a halt","usage":"表示“停止；停下来”，强调逐渐停止的过程，可加形容词修饰停止的状态","examples":[{"en":"Bruce charged at it, but in the middle, the car came to a grinding halt.","zh":"布鲁斯冲着水潭开过去，可开到中间时，车嘎吱一声停住了。"},{"en":"The project came to a halt due to lack of funding.","zh":"由于缺乏资金，项目停了下来。"}]},{"phrase":"sooner or later","usage":"作时间状语，表示“迟早，总有一天”，强调某事最终必然会发生","examples":[{"en":"We felt sure that sooner or later a stone would rip a hole in our petrol tank or damage the engine.","zh":"我们确信迟早会有石头把油箱砸个洞，或者把发动机弄坏。"},{"en":"If you keep lying, people will find out sooner or later.","zh":"如果你一直撒谎，大家迟早会发现的。"}]},{"phrase":"a trail of","usage":"表示“一串；一溜；痕迹”，描述人或物经过后留下的连续痕迹","examples":[{"en":"We kept looking back, wondering if we were leaving a trail of oil and petrol behind us.","zh":"我们不停地往后看，想知道是不是在身后漏了一路油。"},{"en":"The hurricane left a trail of destruction across the country.","zh":"飓风在全国留下了满目疮痍。"}]},{"phrase":"charge at","usage":"表示“向…猛冲；冲向”，带有动作鲁莽、不顾后果的意味","examples":[{"en":"Bruce charged at it, but in the middle, the car came to a grinding halt.","zh":"布鲁斯冲着水潭开过去，可开到中间时，车嘎吱一声停住了。"},{"en":"The dog charged at the stranger when he walked into the yard.","zh":"陌生人走进院子时，狗朝他冲了过去。"}]}],"grammar":[{"title":"even though/even if引导的让步状语从句","definition":"用来引导让步状语，表示“尽管，即使”，强调主句描述的情况不受从句情况的影响，存在转折关系","structure":"Even though/Even if + 从句，主句","usage":"even though多引导已经发生的事实，even if多引导假设的情况，二者在很多场景下可通用，从句可以放在主句前或主句后","examples":[{"en":"Even though the road was littered with boulders and pitted with holes, Bruce was not in the least perturbed.","zh":"尽管路上满是大石头，坑坑洼洼，布鲁斯却一点也不慌。"},{"en":"Even if it rains tomorrow, we will still hold the sports meeting.","zh":"即使明天下雨，我们还是会举办运动会。"}]},{"title":"no matter what引导的让步状语从句","definition":"表示“无论什么”，引导让步状语，强调不管出现什么情况，主句的动作或状态都不会改变","structure":"No matter what + 从句，主句","usage":"no matter what相当于whatever，在从句中可作主语或宾语，同类结构还有no matter when/where/how等","examples":[{"en":"No matter what the conditions were, he believed that a car should be driven as fast as it could possibly go.","zh":"不管路况如何，他都认为车应该能开多快就开多快。"},{"en":"No matter what difficulties we meet, we will never give up.","zh":"无论遇到什么困难，我们都不会放弃。"}]},{"title":"现在分词作伴随/结果状语","definition":"现在分词（短语）可以在句中作状语，用来表示和主句动作同时发生的伴随动作，或者主句动作带来的自然结果","structure":"主句，现在分词（短语）","usage":"现在分词的逻辑主语必须和主句主语一致，表伴随时动作与主句动作同时发生，表结果时是主句动作产生的意料之中的结果","examples":[{"en":"Glancing at his map, he informed us that the next village was a mere twenty miles away.","zh":"他看了一眼地图，告诉我们下一个村子只有20英里远了。"},{"en":"The fire lasted nearly a month, leaving nothing valuable.","zh":"大火持续了近一个月，没留下什么值钱的东西。"}]}],"patterns":[{"pattern":"It was not that... It was simply that...","explanation":"","original":{"en":"It was not that Bruce always underestimated difficulties. He simply had no sense of danger at all.","zh":"并不是布鲁斯总低估困难，他根本就完全没有危险意识。"},"examples":[{"en":"It was not that she doesn't like the gift. She simply thinks it's too expensive.","zh":"并不是她不喜欢这个礼物，她只是觉得它太贵了。"},{"en":"It was not that the task is too hard. We simply don't have enough time to finish it.","zh":"并不是任务太难，我们只是没有足够的时间完成它。"}]},{"pattern":"What a relief it was when...","explanation":"","original":{"en":"What a relief it was when the boulders suddenly disappeared, giving way to a stretch of plain where the only obstacles were clumps bushes.","zh":"大石头突然消失了，取而代之的是一片平原，唯一的障碍是一簇簇灌木丛，这让我们松了一大口气。"},"examples":[{"en":"What a relief it was when the final exam ended and we could go on vacation.","zh":"期末考试结束了，我们可以去度假了，真是太让人松口气了。"},{"en":"What a relief it was when the missing child was found safe and sound.","zh":"失踪的孩子被安然无恙地找到了，真是让人松了一大口气。"}]},{"pattern":"so...that...引导的结果状语从句","explanation":"","original":{"en":"The rough road across the plain soon became so bad that we tried to get Bruce to drive back to the village we had come from.","zh":"穿越平原的崎岖道路很快变得极差，我们都试图让布鲁斯开回我们来的那个村子。"},"examples":[{"en":"The movie was so touching that almost everyone in the cinema cried.","zh":"这部电影太感人了，电影院里几乎所有人都哭了。"},{"en":"He spoke so fast that I could hardly catch what he was saying.","zh":"他说得太快了，我几乎跟不上他说的内容。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“不祥地；有凶兆地” 对应的单词是？","hint":"adverb · /ˈɒmɪnəsli/","options":["detect","immense","bother","ominously"],"answer":3,"explain":"ominously · /ˈɒmɪnəsli/ · adverb · 不祥地；有凶兆地。修饰动作，暗示即将发生不好的事情","source":{"kind":"vocab","word":"ominously"},"id":"b3-u39-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：恳求；乞求","hint":"/ˈpliːdɪŋ/ · noun","answer":"pleading","placeholder":"输入英文单词","explain":"pleading · /ˈpliːdɪŋ/ · noun · 恳求；乞求。常用复数形式，表示多次反复的请求","source":{"kind":"vocab","word":"pleading"},"id":"b3-u39-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：She was not _____ surprised by the bad news.","hint":"她对这个坏消息一点也不感到惊讶。","answer":"in the least","placeholder":"输入缺失的短语","explain":"in the least：用于否定句中，加强否定语气，表示“一点也不，丝毫没有”（她对这个坏消息一点也不感到惊讶。）","source":{"kind":"phrase","phrase":"in the least"},"id":"b3-u39-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Even this had no _____","hint":"即使这样也毫无作用。","answer":"effect","placeholder":"输入缺失的单词","explain":"Even this had no effect. — 即使这样也毫无作用。","source":{"kind":"sentence","en":"Even this had no effect."},"id":"b3-u39-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示“无论什么”，引导让步状语，强调不管出现什么情况，主句的动作或状态都不会改变” 描述的是哪个语法点？","hint":"No matter what + 从句，主句","options":["no matter what引导的让步状语从句","情态动词 + have + 过去分词 (Modal + Perfect Infinitive)","定语从句 (Relative Clause) - 关系副词where引导","一般现在时表客观事实和普遍规律"],"answer":0,"explain":"no matter what引导的让步状语从句：No matter what + 从句，主句：no matter what相当于whatever，在从句中可作主语或宾语，同类结构还有no matter when/where/how等","source":{"kind":"grammar","title":"no matter what引导的让步状语从句"},"id":"b3-u39-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nBruce charged at it, but in the middle, the car came to a grinding halt.","hint":"","options":["他飞越海峡仅七英里，发动机就失灵了，被迫降落在海面上。","这种事情发生在小说里是完全可以的。","布鲁斯冲了过去，但在水池中央，汽车嘎然而止。","当拉姆齐夫人告诉警察她所做的一切时，警察都惊呆了。"],"answer":2,"explain":"Bruce charged at it, but in the middle, the car came to a grinding halt. — 布鲁斯冲了过去，但在水池中央，汽车嘎然而止。","source":{"kind":"sentence","en":"Bruce charged at it, but in the middle, the car came to a grinding halt."},"id":"b3-u39-q06"}]},{"id":"b3-u40","book":3,"unit":40,"key":"40","lessonFrom":40,"lessonTo":40,"title":"Who's Who","titleZh":"谁是谁","question":"How did the policeman discover that the whole thing was a joke?","sentences":[{"en":"It has never been explained why university students seem to enjoy practical jokes more than anyone else.","zh":"大学学生为什么似乎比其他人更喜欢恶作剧，这一点从未得到解释。","t":14.21},{"en":"Students specialize in a particular type of practical joke: the hoax.","zh":"学生们擅长一种特殊类型的恶作剧：骗局。","t":22.71},{"en":"Inviting the fire brigade to put out a nonexistent fire is a crude form of deception which no self-respecting student would ever indulge in.","zh":"邀请消防队扑灭一场不存在的火灾是一种粗俗的欺骗形式，任何有自尊的学生都不会沉溺其中。","t":28.79},{"en":"Students often create amusing situations which are funny to everyone except the victims.","zh":"学生们经常制造一些有趣的场面，除了受害者，每个人都觉得好笑。","t":39.45},{"en":"When a student recently saw two workmen using a pneumatic drill outside his university,","zh":"最近，当一名学生看到两名工人在他大学外面使用一台气动钻时，","t":46.93},{"en":"he immediately telephoned the police and informed them that two students dressed up as workmen","zh":"他立即打电话报警，并告知警察有两名打扮成工人的学生","t":54.24},{"en":"were tearing up the road with a pneumatic drill.","zh":"正在用气动钻挖路。","t":61.2},{"en":"As soon as he had hung up, he went over to the workmen and told them that if a policeman ordered them to go away,","zh":"他一挂掉电话，就走到工人那里，告诉他们如果一个警察命令他们离开，","t":64.69},{"en":"they were not to take him seriously.","zh":"他们不必把他当真。","t":72.7},{"en":"He added that a student had dressed up as a policeman and was playing all sorts of silly jokes on people.","zh":"他补充说，有个学生打扮成警察，正在对人们开各种愚蠢的玩笑。","t":75.42},{"en":"Both the police and the workmen were grateful to the student for this piece of advance information.","zh":"警察和工人都很感谢这名学生提供的这条提前消息。","t":83.78},{"en":"The student hid in an archway nearby where he could watch and hear everything that went on.","zh":"这名学生藏在附近的一个拱门里，在那里他能看到和听到发生的一切。","t":91.58},{"en":"Sure enough, a policeman arrived on the scene and politely asked the workmen to go away.","zh":"果不其然，一名警察来到了现场，并礼貌地要求工人离开。","t":98.73},{"en":"When he received a very rude reply from one of the workmen, he threatened to remove them by force.","zh":"当他从其中一名工人那里得到非常粗鲁的答复时，他威胁要强行把他们带走。","t":105.75},{"en":"The workmen told him to do as he pleased and the policeman telephoned for help.","zh":"工人们告诉他想怎样就怎样，于是警察打电话请求支援。","t":113.54},{"en":"Shortly afterwards, 4 more policemen arrived and remonstrated with the workmen.","zh":"不久之后，又有4名警察赶到，并与工人们进行交涉。","t":119.16},{"en":"As the men refused to stop working, the police attempted to seize the pneumatic drill.","zh":"由于工人们拒绝停止工作，警察试图没收气动钻。","t":125.79},{"en":"The workmen struggled fiercely and one of them lost his temper.","zh":"工人们激烈反抗，其中一人发了脾气。","t":132.84},{"en":"He threatened to call the police.","zh":"他威胁要报警。","t":138.04},{"en":"At this, the police pointed out ironically that this would hardly be necessary as the men were already under arrest.","zh":"听罢此言，警察讽刺地指出，这几乎没有必要，因为这些人已经被逮捕了。","t":140.87},{"en":"Pretending to speak seriously, one of the workmen asked if he might make a telephone call before being taken to the station.","zh":"其中一名工人假装认真地问道，在被带到警察局之前，他是否可以打个电话。","t":150.34},{"en":"Permission was granted and a policeman accompanied him to a pay phone.","zh":"许可被准予，一名警察陪他去了公用电话亭。","t":159.61},{"en":"Only when he saw that the man was actually telephoning the police did he realize that they had all been the victims of a hoax.","zh":"只有当他看到那个人实际上是在打电话给警察时，他才意识到他们都成了骗局的受害者。","t":165.09}],"vocab":[{"word":"hoax","phonetic":"/həʊks/","meanings":[{"pos":"noun","meaning":"骗局；恶作剧","usage":"指故意制造的欺骗他人取乐的虚假事件"}]},{"word":"pneumatic","phonetic":"/njuːˈmætɪk/","meanings":[{"pos":"adjective","meaning":"气动的；由压缩空气操作的","usage":"常用来描述靠气体压力工作的工具或设备"}]},{"word":"drill","phonetic":"/drɪl/","meanings":[{"pos":"noun","meaning":"钻；钻头","usage":"指用于钻孔的工具，pneumatic drill即风钻、气动钻机"}]},{"word":"deception","phonetic":"/dɪˈsepʃn/","meanings":[{"pos":"noun","meaning":"欺骗；欺诈","usage":"指故意误导他人的行为或手段"}]},{"word":"indulge","phonetic":"/ɪnˈdʌldʒ/","meanings":[{"pos":"verb","meaning":"沉迷于；沉溺于","usage":"常用搭配indulge in sth，表示放任自己做某事"}]},{"word":"victim","phonetic":"/ˈvɪktɪm/","meanings":[{"pos":"noun","meaning":"受害者；受骗者","usage":"指受到伤害、欺骗或不利影响的人"}]},{"word":"grateful","phonetic":"/ˈɡreɪtfl/","meanings":[{"pos":"adjective","meaning":"感激的；感谢的","usage":"常用搭配be grateful to sb for sth，表示因某事感谢某人"}]},{"word":"advance","phonetic":"/ədˈvɑːns/","meanings":[{"pos":"adjective","meaning":"预先的；提前的","usage":"用于描述在事件发生前给出的信息、通知等"}]},{"word":"archway","phonetic":"/ˈɑːtʃweɪ/","meanings":[{"pos":"noun","meaning":"拱廊；拱门通道","usage":"指带有拱形顶的通道或入口"}]},{"word":"threaten","phonetic":"/ˈθretn/","meanings":[{"pos":"verb","meaning":"威胁；恐吓","usage":"常用搭配threaten to do sth，表示扬言要做某事"}]},{"word":"remonstrate","phonetic":"/ˈremənstreɪt/","meanings":[{"pos":"verb","meaning":"抗议；规劝","usage":"常用搭配remonstrate with sb，表示向某人提出异议或规劝"}]},{"word":"fiercely","phonetic":"/ˈfɪəsli/","meanings":[{"pos":"adverb","meaning":"激烈地；凶猛地","usage":"用来描述动作或情绪的强烈程度"}]},{"word":"ironically","phonetic":"/aɪˈrɒnɪkli/","meanings":[{"pos":"adverb","meaning":"讽刺地；说反话地","usage":"用于描述带有讽刺意味的说话或行为方式"}]},{"word":"grant","phonetic":"/ɡrɑːnt/","meanings":[{"pos":"verb","meaning":"同意；准予","usage":"表示正式允许某人做某事，常用被动语态permission was granted"}]},{"word":"accompany","phonetic":"/əˈkʌmpəni/","meanings":[{"pos":"verb","meaning":"陪伴；陪同","usage":"表示和某人一起去某处，常用搭配accompany sb to sp"}]}],"phrases":[{"phrase":"specialize in","usage":"表示专门从事、专攻某一领域或活动","examples":[{"en":"The company specializes in organic skincare products.","zh":"这家公司专门生产有机护肤产品。"}]},{"phrase":"dress up as","usage":"表示装扮成、打扮成特定的样子","examples":[{"en":"The little girl dressed up as a princess for the Halloween party.","zh":"小女孩在万圣节派对上装扮成了公主。"}]},{"phrase":"put out","usage":"此处表示熄灭、扑灭（火）","examples":[{"en":"It took the firefighters three hours to put out the forest fire.","zh":"消防员花了三个小时才扑灭这场森林火灾。"}]},{"phrase":"take sb seriously","usage":"表示认真对待某人、把某人的话当回事","examples":[{"en":"Don't take him seriously - he's always making silly jokes.","zh":"别把他的话当真，他总爱开无聊的玩笑。"}]},{"phrase":"play jokes on sb","usage":"表示开某人的玩笑、捉弄某人","examples":[{"en":"The boys love to play jokes on their classmates on April Fool's Day.","zh":"男孩子们喜欢在愚人节那天捉弄同学。"}]},{"phrase":"on the scene","usage":"表示在现场、到场","examples":[{"en":"The police were on the scene within five minutes of receiving the emergency call.","zh":"警察接到紧急电话后五分钟内就赶到了现场。"}]},{"phrase":"by force","usage":"表示靠武力、用强制手段","examples":[{"en":"The security guards had to remove the troublemaker by force.","zh":"保安不得不强行把闹事者带走。"}]},{"phrase":"lose one's temper","usage":"表示发脾气、发火","examples":[{"en":"He lost his temper when he found his laptop had been damaged.","zh":"当他发现自己的笔记本电脑被弄坏时，他发了脾气。"}]},{"phrase":"under arrest","usage":"表示被逮捕、被拘留","examples":[{"en":"The suspect was under arrest for stealing cars.","zh":"这名嫌疑人因盗窃车辆被逮捕。"}]},{"phrase":"make a telephone call","usage":"表示打电话","examples":[{"en":"I need to make a telephone call to my parents to tell them I'll be home late.","zh":"我得给我父母打个电话，告诉他们我会晚点儿回家。"}]}],"grammar":[{"title":"only引导的部分倒装句","definition":"当\"only+状语（从句）\"位于句首时，句子需要使用部分倒装结构，即将助动词、情态动词或be动词提到主语之前，强调该状语的条件性","structure":"Only + 状语/状语从句 + 助动词/情态动词/be动词 + 主语 + 谓语剩余部分","usage":"用于强调只有在某个条件下才会发生某事，突出条件的重要性","examples":[{"en":"Only when he saw that the man was actually telephoning the police did he realize that they had all been the victims of a hoax.","zh":"当他看到那个人真的在给警察打电话时，他才意识到他们所有人都成了一场恶作剧的受害者。"},{"en":"Only by practicing every day can you improve your spoken English quickly.","zh":"只有每天练习，你才能快速提高英语口语。"}]}],"patterns":[{"pattern":"It has never been explained why...","explanation":"","original":{"en":"It has never been explained why university students seem to enjoy practical jokes more than anyone else.","zh":"为什么大学生似乎比其他人更喜欢搞恶作剧，这一点一直没有得到解释。"},"examples":[{"en":"It has never been explained why this ancient custom disappeared suddenly hundreds of years ago.","zh":"为什么这个古老的习俗在几百年前突然消失，一直没有得到解释。"},{"en":"It has never been explained why he quit his well-paid job without telling anyone.","zh":"为什么他没告诉任何人就辞掉了高薪工作，这一点没人说得清。"}]},{"pattern":"As soon as sb had done sth, sb did sth else","explanation":"","original":{"en":"As soon as he had hung up, he went over to the workmen and told them that if a policeman ordered them to go away, they were not to take him seriously.","zh":"他一挂电话，就走到工人那里，告诉他们如果有警察命令他们离开，不要把他当回事。"},"examples":[{"en":"As soon as she had finished her homework, she went to the park to walk her dog.","zh":"她一做完作业，就去公园遛狗了。"},{"en":"As soon as the guests had left, he started to clean up the messy living room.","zh":"客人一走，他就开始打扫乱糟糟的客厅。"}]},{"pattern":"At this, sb did sth","explanation":"","original":{"en":"At this, the police pointed out ironically that this would hardly be necessary as the men were already under arrest.","zh":"听到这话，警察讽刺地指出，这几乎没有必要，因为这两个人已经被逮捕了。"},"examples":[{"en":"At this, the little girl burst into tears and ran to her mother.","zh":"听到这话，小女孩突然哭了起来，跑向她的妈妈。"},{"en":"At this, the manager smiled and nodded to show his agreement with the proposal.","zh":"听到这里，经理笑了笑，点头表示他同意这个提议。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“威胁；恐吓” 对应的单词是？","hint":"verb · /ˈθretn/","options":["skeleton","glisten","straggling","threaten"],"answer":3,"explain":"threaten · /ˈθretn/ · verb · 威胁；恐吓。常用搭配threaten to do sth，表示扬言要做某事","source":{"kind":"vocab","word":"threaten"},"id":"b3-u40-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：骗局；恶作剧","hint":"/həʊks/ · noun","answer":"hoax","placeholder":"输入英文单词","explain":"hoax · /həʊks/ · noun · 骗局；恶作剧。指故意制造的欺骗他人取乐的虚假事件","source":{"kind":"vocab","word":"hoax"},"id":"b3-u40-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：I need to _____ to my parents to tell them I'll be home late.","hint":"我得给我父母打个电话，告诉他们我会晚点儿回家。","answer":"make a telephone call","placeholder":"输入缺失的短语","explain":"make a telephone call：表示打电话（我得给我父母打个电话，告诉他们我会晚点儿回家。）","source":{"kind":"phrase","phrase":"make a telephone call"},"id":"b3-u40-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：As soon as he had hung up, he went over to the workmen and told them that if a _____ ordered them to go away,","hint":"他一挂掉电话，就走到工人那里，告诉他们如果一个警察命令他们离开，","answer":"policeman","placeholder":"输入缺失的单词","explain":"As soon as he had hung up, he went over to the workmen and told them that if a policeman ordered them to go away, — 他一挂掉电话，就走到工人那里，告诉他们如果一个警察命令他们离开，","source":{"kind":"sentence","en":"As soon as he had hung up, he went over to the workmen and told them that if a policeman ordered them to go away,"},"id":"b3-u40-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当\"only+状语（从句）\"位于句首时，句子需要使用部分倒装结构，即将助动词、情态动词或be动词提到主语之前，强调该状语的条件性” 描述的是哪个语法点？","hint":"Only + 状语/状语从句 + 助动词/情态动词/be动词 + 主语 + 谓语剩余部分","options":["过去完成进行时","only引导的部分倒装句","情态动词 + have + 过去分词 (Modal + Perfect Infinitive)","should have done 结构"],"answer":1,"explain":"only引导的部分倒装句：Only + 状语/状语从句 + 助动词/情态动词/be动词 + 主语 + 谓语剩余部分：用于强调只有在某个条件下才会发生某事，突出条件的重要性","source":{"kind":"grammar","title":"only引导的部分倒装句"},"id":"b3-u40-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nShortly afterwards, 4 more policemen arrived and remonstrated with the workmen.","hint":"","options":["但它们的许多功能已被小型、强大的个人电脑（通常称为PC）所取代。","不久之后，又有4名警察赶到，并与工人们进行交涉。","这使得跟在她后面的司机猛踩刹车。","尽管这位贵族在每次表演中都应该读这封信，但他总是坚持信应该写得清清楚楚。"],"answer":1,"explain":"Shortly afterwards, 4 more policemen arrived and remonstrated with the workmen. — 不久之后，又有4名警察赶到，并与工人们进行交涉。","source":{"kind":"sentence","en":"Shortly afterwards, 4 more policemen arrived and remonstrated with the workmen."},"id":"b3-u40-q06"}]},{"id":"b3-u41","book":3,"unit":41,"key":"41","lessonFrom":41,"lessonTo":41,"title":"Illusions of Pastoral Peace","titleZh":"田园宁静的遐想","question":"What particular anxiety spoils the country dweller's visit to the theatre?","sentences":[{"en":"The quiet life of the country has never appealed to me.","zh":"宁静的乡村生活从来没有吸引过我。","t":17.94},{"en":"City born and city bred,","zh":"我生在城里，长在城里，","t":22.45},{"en":"I have always regarded the country as something you look at through a train window, or something you occasionally visit during the weekend.","zh":"始终认为乡村是透过火车车窗看的东西，或者至多是周末偶尔去逛逛的地方。","t":24.9},{"en":"Most of my friends live in the city, yet they always go into raptures at the mere mention of the country.","zh":"我的大部分朋友都住在城里，然而他们一提到乡村就手舞足蹈。","t":35.61},{"en":"Though they extol the virtues of the peaceful life,","zh":"尽管他们盛赞宁静生活的种种好处，","t":45.18},{"en":"only one of them has ever gone to live in the country and he was back in town within six months.","zh":"但只有一个人去乡下住过，而且不到6个月就回到了城里。","t":49.15},{"en":"Even he still lives under the illusion that country life is somehow superior to town life.","zh":"即使他，至今仍幻想乡村生活不知怎么的要优于城市生活。","t":57.41},{"en":"He is forever talking about the friendly people, the clean atmosphere, the closeness to nature and the gentle pace of living.","zh":"他总是谈论那里的人们多么友好，空气多么清新，多么贴近大自然，生活节奏多么悠闲。","t":66.07},{"en":"Nothing can be compared, he maintains, with the first cockcrow, the twittering of birds at dawn,","zh":"他坚持认为，没有什么能与第一声鸡鸣、黎明时鸟儿的啁啾相比，","t":76.04},{"en":"the sight of the rising sun glinting on the trees and pastures.","zh":"也不能与旭日普照树林和牧场的景象相比。","t":84.79},{"en":"This idyllic pastoral scene is only part of the picture.","zh":"这田园诗般的乡村景色只是部分景象。","t":90.55},{"en":"My friend fails to mention the long and friendless winter evenings in front of the TV--virtually the only form of entertainment.","zh":"我的朋友没有提到在电视机前度过的漫长而孤寂的冬夜——这几乎是唯一的娱乐方式。","t":95.95},{"en":"He says nothing about the poor selection of goods in the shops,","zh":"他没有提及商店里商品的选择少得可怜，","t":106.87},{"en":"or about those unfortunate people who have to travel from the country to the city every day to get to work.","zh":"也没有提及那些每天不得不从乡下到城里上班的可怜人。","t":111.66},{"en":"Why people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country is beyond me.","zh":"为什么人们愿意每天忍受4个小时的车程，只为享受住在乡下这种可疑的优待，这真是超出我的理解。","t":120.73},{"en":"They could be saved so much misery and expense if they chose to live in the city where they rightly belong.","zh":"如果他们选择住在他们本该居住的城市，就可以避免许多痛苦和花费。","t":131.87},{"en":"If you can do without the few pastoral pleasures of the country, you will find the city can provide you with the best that life can offer.","zh":"如果你能放弃乡村那一点点田园乐趣，你就会发现城市能为你提供生活中最美好的东西。","t":141.99},{"en":"You never have to travel miles to see your friends.","zh":"你永远不必跑很远的路去看望朋友。","t":152.11},{"en":"They invariably live nearby and are always available for an informal chat or an evening's entertainment.","zh":"他们总是住在附近，随时都可以进行非正式的聊天或晚间娱乐。","t":156.17},{"en":"Some of my acquaintances in the country come up to town once or twice a year to visit the theatre as a special treat.","zh":"我乡下的一些熟人每年进城一两次，看戏作为一种特殊的享受。","t":165.81},{"en":"For them this is a major operation which involves considerable planning.","zh":"对他们来说，这是一项大工程，需要周密的计划。","t":174.74},{"en":"As the play draws to its close, they wonder whether they will ever catch that last train home.","zh":"随着戏接近尾声，他们会担心是否能赶上最后一班回家的火车。","t":181.5},{"en":"The city dweller never experiences anxieties of this sort.","zh":"城市居民从不会经历这种焦虑。","t":188.77},{"en":"The latest exhibitions, films, or plays are only a short bus ride away.","zh":"最新的展览、电影或戏剧，只需坐一小段公交车就能到达。","t":194.16},{"en":"Shopping, too, is always a pleasure.","zh":"购物也总是一种乐趣。","t":201.46},{"en":"There is so much variety that you never have to make do with second best.","zh":"品种如此繁多，你永远不必将就次等货。","t":205.24},{"en":"Country people run wild when they go shopping in the city and stagger home loaded with as many of the exotic items as they can carry.","zh":"乡下人进城购物时会变得狂热，然后蹒跚着回家，身上背着尽可能多的异国情调的物品。","t":212.3},{"en":"Nor is the city without its moments of beauty.","zh":"城市也并非没有它的美丽时刻。","t":223.18},{"en":"There is something comforting about the warm glow shed by advertisements on cold wet winter nights.","zh":"在寒冷潮湿的冬夜，广告牌散发出的温暖光芒总能给人带来慰藉。","t":227.08},{"en":"Few things could be more impressive than the peace that descends on deserted city streets at weekends","zh":"几乎没有什么能比周末空旷的城市街道上降临的宁静更令人印象深刻，","t":235.15},{"en":"when the thousands that travel to work every day are tucked away in their homes in the country.","zh":"当每天上班的成千上万人都在乡下的家中安睡时。","t":242.61},{"en":"It has always been a mystery to me why city dwellers, who appreciate all these things,","zh":"对我来说，城市居民明明欣赏所有这些优点，","t":250.08},{"en":"obstinately pretend that they would prefer to live in the country.","zh":"却固执地假装他们更喜欢住在乡下，这始终是个谜。","t":257.67}],"vocab":[{"word":"illusion","phonetic":"/ɪˈluːʒn/","meanings":[{"pos":"noun","meaning":"幻觉，错觉，错误的观念","usage":"指看似真实但实际不存在的事物或想法"}]},{"word":"pastoral","phonetic":"/ˈpæstərəl/","meanings":[{"pos":"adj","meaning":"田园的，乡村的","usage":"形容乡村或田园生活方式"}]},{"word":"rapture","phonetic":"/ˈræptʃə(r)/","meanings":[{"pos":"noun","meaning":"狂喜，欣喜若狂","usage":"常用复数形式raptures表示极度欣喜"}]},{"word":"extol","phonetic":"/ɪkˈstəʊl/","meanings":[{"pos":"verb","meaning":"赞美，颂扬","usage":"正式用语，高度赞扬"}]},{"word":"twittering","phonetic":"/ˈtwɪtərɪŋ/","meanings":[{"pos":"noun/verb","meaning":"鸟鸣声，啾啾叫","usage":"鸟发出的短促叫声"}]},{"word":"glinting","phonetic":"/ˈɡlɪntɪŋ/","meanings":[{"pos":"adj/verb","meaning":"闪烁的，闪闪发光的","usage":"形容光线反射的闪烁效果"}]},{"word":"pasture","phonetic":"/ˈpæstʃə(r)/","meanings":[{"pos":"noun","meaning":"牧场，草地","usage":"指供牲畜吃草的地方"}]},{"word":"idyllic","phonetic":"/ɪˈdɪlɪk/","meanings":[{"pos":"adj","meaning":"田园诗般的，完美无缺的","usage":"形容平静美好的乡村生活"}]},{"word":"virtually","phonetic":"/ˈvɜːtʃuəli/","meanings":[{"pos":"adv","meaning":"实际上，几乎","usage":"相当于almost/nearly"}]},{"word":"dubious","phonetic":"/ˈdjuːbiəs/","meanings":[{"pos":"adj","meaning":"可疑的，不确定的","usage":"表示对某事持怀疑态度"}]},{"word":"acquaintance","phonetic":"/əˈkweɪntəns/","meanings":[{"pos":"noun","meaning":"熟人，认识的人","usage":"指认识但不太熟的人，区别于friend"}]},{"word":"deserted","phonetic":"/dɪˈzɜːtɪd/","meanings":[{"pos":"adj","meaning":"荒芜的，无人的","usage":"形容空无一人的地方"}]},{"word":"obstinately","phonetic":"/ˈɒbstɪnətli/","meanings":[{"pos":"adv","meaning":"固执地，倔强地","usage":"形容坚持己见不肯改变的态度"}]},{"word":"stagger","phonetic":"/ˈstæɡə(r)/","meanings":[{"pos":"verb","meaning":"踉跄，摇晃着走","usage":"形容因负重或疲劳而走路不稳"}]},{"word":"descend","phonetic":"/dɪˈsend/","meanings":[{"pos":"verb","meaning":"降临，来临","usage":"指某种状态或氛围突然到来"}]}],"phrases":[{"phrase":"go into raptures","usage":"表示极度兴奋或欣喜若狂","examples":[{"en":"They always go into raptures at the mere mention of the country.","zh":"他们一提到乡村就会欣喜若狂。"}]},{"phrase":"be beyond me","usage":"表示无法理解或超出能力范围","examples":[{"en":"Why people are prepared to tolerate a four-hour journey each day is beyond me.","zh":"我无法理解为什么人们愿意每天忍受四个小时的旅程。"}]},{"phrase":"do without","usage":"表示没有某物也能应付，没有也行","examples":[{"en":"If you can do without the few pastoral pleasures of the country, you will find the city can provide you with the best.","zh":"如果你能不要乡村的那点乐趣，你会发现城市能给你最好的生活。"}]},{"phrase":"make do with","usage":"表示凑合用，将就使用","examples":[{"en":"There is so much variety that you never have to make do with second best.","zh":"品种繁多，你永远不必凑合用次品。"}]},{"phrase":"run wild","usage":"表示疯狂、放纵、胡乱购物","examples":[{"en":"Country people run wild when they go shopping in the city.","zh":"乡下人进城购物时会疯狂采购。"}]},{"phrase":"draw to a close","usage":"表示接近尾声，即将结束","examples":[{"en":"As the play draws to its close, they wonder whether they will ever catch that last train home.","zh":"当戏剧接近尾声时，他们担心能否赶得上最后一班回家的火车。"}]},{"phrase":"be tucked away","usage":"表示被藏起来，安置在某个地方","examples":[{"en":"The thousands that travel to work every day are tucked away in their homes in the country.","zh":"每天成千上万进城工作的人都被藏在乡村的家中。"}]},{"phrase":"It has always been a mystery to me","usage":"表示对某人来说一直是个谜","examples":[{"en":"It has always been a mystery to me why city dwellers pretend they would prefer to live in the country.","zh":"我一直不明白为什么城里人偏要假装喜欢住在乡下。"}]},{"phrase":"under the illusion","usage":"表示误以为，持有错误的观念","examples":[{"en":"Even he still lives under the illusion that country life is somehow superior to town life.","zh":"甚至他仍然误以为乡村生活比城市生活优越。"}]},{"phrase":"for the dubious privilege of","usage":"表示为了某种不值得的特权/好处","examples":[{"en":"Why people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country.","zh":"为什么人们愿意每天忍受四小时的路程，就为了住乡下的那个并不值得的好处。"}]}],"grammar":[{"title":"宾语从句（Object Clause）","definition":"由连接词引导的充当句子宾语的从句，说明说话人对某事物的看法或疑问。","structure":"连接词（that/whether/why/what等）+ 主语 + 谓语 + 其他成分","usage":"用于表达观点、看法、疑问等内容，可位于动词或介词之后。常见动词如：think, believe, know, wonder, understand等后常接宾语从句。","examples":[{"en":"He still lives under the illusion that country life is somehow superior to town life.","zh":"他仍然误以为乡村生活比城市生活优越。"},{"en":"Why people are prepared to tolerate a four-hour journey each day is beyond me.","zh":"我不明白为什么人们愿意每天忍受四小时的路程。"},{"en":"It has always been a mystery to me why city dwellers pretend they would prefer to live in the country.","zh":"我一直不明白为什么城里人偏要假装喜欢住在乡下。"}]},{"title":"否定副词置于句首的倒装句","definition":"含有never, seldom, rarely, little, nowhere, hardly等否定词或半否定词时，如置于句首，句子需要部分倒装。","structure":"否定词/半否定词 + 助动词/be动词/情态动词 + 主语 + 动词原形 + 其他","usage":"强调否定意义，使句子更加正式或文学化。阅读时需注意识别这种倒装结构。","examples":[{"en":"Never have I seen such a beautiful sunset.","zh":"我从未见过如此美丽的日落。"},{"en":"Seldom does he go to the theatre.","zh":"他很少去看戏。"},{"en":"Rarely can you find a place so quiet.","zh":"你很少能找到如此安静的地方。"}]},{"title":"条件状语从句（真实条件句）","definition":"表示在某种条件下可能会发生的情况，使用if引导，描述可能实现的假设。","structure":"If + 主语 + 一般现在时, 主语 + will/can/may + 动词原形","usage":"用于提出真实的假设条件，说明条件与结果之间的关系。这类句子被称为第一类条件句，表示可能发生的情况。","examples":[{"en":"If you can do without the few pastoral pleasures of the country, you will find the city can provide you with the best.","zh":"如果你能不要乡村的那点乐趣，你会发现城市能给你最好的生活。"},{"en":"If you work hard, you will succeed.","zh":"如果你努力工作，你就会成功。"}]}],"patterns":[{"pattern":"Nothing can be compared with...","explanation":"","original":{"en":"Nothing can be compared, he maintains, with the first cockcrow, the twittering of birds at dawn...","zh":"他坚持认为，没有什么能比得上清晨的第一声鸡鸣、鸟儿的啾啾叫声..."},"examples":[{"en":"Nothing can be compared with a mother's love.","zh":"没有什么能比得上母爱。"},{"en":"Nothing can be compared with the taste of fresh fruit.","zh":"没有什么能比得上新鲜水果的味道。"}]},{"pattern":"Why... is beyond me","explanation":"","original":{"en":"Why people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country is beyond me.","zh":"我无法理解为什么人们为了在乡村居住这个可疑的特权而愿意每天忍受四小时的旅程。"},"examples":[{"en":"Why she married him is beyond me.","zh":"我无法理解她为什么要嫁给他。"},{"en":"Why anyone would want to live there is beyond me.","zh":"我无法理解为什么有人想住在那里。"}]},{"pattern":"There is something... about...","explanation":"","original":{"en":"There is something comforting about the warm glow shed by advertisements on cold wet winter nights.","zh":"在寒冷潮湿的冬夜，广告牌发出的温暖光芒有一种令人安慰的感觉。"},"examples":[{"en":"There is something mysterious about the old house.","zh":"那座老房子有一种神秘的感觉。"},{"en":"There is something fascinating about her stories.","zh":"她的故事有一种迷人的魅力。"}]},{"pattern":"If you can do without..., you will find...","explanation":"","original":{"en":"If you can do without the few pastoral pleasures of the country, you will find the city can provide you with the best that life can offer.","zh":"如果你能放弃乡村的那点乐趣，你就会发现城市能给你提供生活中最好的东西。"},"examples":[{"en":"If you can do without luxury, you will find life much simpler.","zh":"如果你能不要奢侈品，你会发现生活简单得多。"},{"en":"If you can do without constant entertainment, you will find time for what matters.","zh":"如果你能不要不断的娱乐，你会发现时间去做重要的事。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“牧场，草地” 对应的单词是？","hint":"noun · /ˈpæstʃə(r)/","options":["prudent","straggling","realm","pasture"],"answer":3,"explain":"pasture · /ˈpæstʃə(r)/ · noun · 牧场，草地。指供牲畜吃草的地方","source":{"kind":"vocab","word":"pasture"},"id":"b3-u41-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：实际上，几乎","hint":"/ˈvɜːtʃuəli/ · adv","answer":"virtually","placeholder":"输入英文单词","explain":"virtually · /ˈvɜːtʃuəli/ · adv · 实际上，几乎。相当于almost/nearly","source":{"kind":"vocab","word":"virtually"},"id":"b3-u41-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：Country people _____ when they go shopping in the city.","hint":"乡下人进城购物时会疯狂采购。","answer":"run wild","placeholder":"输入缺失的短语","explain":"run wild：表示疯狂、放纵、胡乱购物（乡下人进城购物时会疯狂采购。）","source":{"kind":"phrase","phrase":"run wild"},"id":"b3-u41-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：There is something comforting about the _____ glow shed by advertisements on cold wet winter nights.","hint":"在寒冷潮湿的冬夜，广告牌散发出的温暖光芒总能给人带来慰藉。","answer":"warm","placeholder":"输入缺失的单词","explain":"There is something comforting about the warm glow shed by advertisements on cold wet winter nights. — 在寒冷潮湿的冬夜，广告牌散发出的温暖光芒总能给人带来慰藉。","source":{"kind":"sentence","en":"There is something comforting about the warm glow shed by advertisements on cold wet winter nights."},"id":"b3-u41-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在某种条件下可能会发生的情况，使用if引导，描述可能实现的假设。” 描述的是哪个语法点？","hint":"If + 主语 + 一般现在时, 主语 + will/can/may + 动词原形","options":["双重否定疑问句 (Negative Question)","条件状语从句（真实条件句）","It seems that 主语从句结构","百分数表达在描述数据中的应用"],"answer":1,"explain":"条件状语从句（真实条件句）：If + 主语 + 一般现在时, 主语 + will/can/may + 动词原形：用于提出真实的假设条件，说明条件与结果之间的关系。这类句子被称为第一类条件句，表示可能发生的情况。","source":{"kind":"grammar","title":"条件状语从句（真实条件句）"},"id":"b3-u41-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nWhy people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country is beyond me.","hint":"","options":["为什么人们愿意每天忍受4个小时的车程，只为享受住在乡下这种可疑的优待，这真是超出我的理解。","但更糟糕的还在后面。就在我们前方，有一道巨大的裂缝。","他被我们称为迪基，他的怪癖在他去世前很久就已成为传奇。","不用说，我们的房子现在被一片丛林包围着。"],"answer":0,"explain":"Why people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country is beyond me. — 为什么人们愿意每天忍受4个小时的车程，只为享受住在乡下这种可疑的优待，这真是超出我的理解。","source":{"kind":"sentence","en":"Why people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country is beyond me."},"id":"b3-u41-q06"}]},{"id":"b3-u42","book":3,"unit":42,"key":"42","lessonFrom":42,"lessonTo":42,"title":"Modern Cavemen","titleZh":"现代穴居人","question":"With what does the writer compare the Gouffre Berger?","sentences":[{"en":"Cave exploration, or pot-holing, as it has come to be known, is a relatively new sport.","zh":"洞穴探险，即人们所知的“探洞”，是一项比较新的运动。","t":15.31},{"en":"Perhaps it is the desire for solitude or the chance of making an unexpected discovery that lures people down to the depths of the earth.","zh":"也许是出于对孤独的渴望，或是想作一次意想不到的发现，把人们引到地下去的。","t":23.34},{"en":"It is impossible to give a satisfactory explanation for a pot-holer's motives.","zh":"想对探洞者的动机作出满意的解释是不可能的。","t":34.42},{"en":"For him, caves have the same peculiar fascination which high mountains have for the climber.","zh":"对于他来说，洞穴有着与高山对于登山者一样的奇异魅力。","t":40.92},{"en":"They arouse instincts which can only be dimly understood.","zh":"它们唤起人们只能模模糊糊感知到的本能。","t":48.99},{"en":"Exploring really deep caves is not a task for the Sunday afternoon rambler.","zh":"勘探真正深的洞穴并非是周日下午散步者所能胜任的。","t":54.42},{"en":"Such undertakings require the precise planning and foresight of military operations.","zh":"这种活动需要像军事行动一样精确的计划和预见性。","t":60.19},{"en":"It can take as long as eight days to rig up rope ladders and to establish supply bases before a descent can be made into a very deep cave.","zh":"在下到一个很深的洞穴之前，光是架设绳梯和建立补给站就可能需要长达8天的时间。","t":68.04},{"en":"Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties which will confront the pot-holer.","zh":"这种预防是必要的，因为无法预知探洞者将会遇到的困难究竟是什么性质。","t":80.61},{"en":"The deepest known cave in the world is the Gouffre Berger near Grenoble.","zh":"世界上已知最深的洞穴是格勒诺布尔附近的贝杰深洞。","t":92.06},{"en":"It extends to a depth of 3,723 feet.","zh":"它深达3723英尺。","t":98.66},{"en":"This immense chasm has been formed by an underground stream which has tunnelled a course through a flaw in the rocks.","zh":"这个巨大的深渊是由一条地下河形成的，这条河在岩石的裂缝中开凿出一条通道。","t":104.33},{"en":"The entrance to the cave is on a plateau in the Dauphine Alps.","zh":"洞口位于多芬阿尔卑斯山脉的一个高原上。","t":113.65},{"en":"As it is only six feet across, it is barely noticeable.","zh":"由于洞口只有6英尺宽，所以几乎难以察觉。","t":120.13},{"en":"The cave might never have been discovered had not the entrance been spotted by the distinguished French pot-holer, Berger.","zh":"如果不是杰出的法国探洞者贝杰发现了洞口，这个洞穴可能永远也不会被发现。","t":125.39},{"en":"Since its discovery, it has become a sort of pot-holers' Everest.","zh":"自从被发现以来，它已成为探洞者们的一种“珠穆朗玛峰”。","t":135},{"en":"Though a number of descents have been made, much of it still remains to be explored.","zh":"尽管已经进行过多次下降探险，但其中大部分仍有待勘探。","t":140.66},{"en":"A team of pot-holers recently went down the Gouffre Berger.","zh":"一队探洞者最近下到了贝杰深洞。","t":147.85},{"en":"After entering the narrow gap on the plateau,","zh":"他们进入高原上的那个狭窄的缝隙后，","t":153.27},{"en":"they climbed down the steep sides of the cave until they came to a narrow corridor.","zh":"沿着洞穴陡峭的侧壁向下攀爬，直到来到一条狭窄的通道。","t":156.96},{"en":"They had to edge their way along this,","zh":"他们不得不侧身沿着这条通道前行，","t":163.62},{"en":"sometimes wading across shallow streams, or swimming across deep pools.","zh":"有时涉过浅浅的小溪，有时游过深深的水潭。","t":166.29},{"en":"Suddenly they came to a waterfall which dropped into an underground lake at the bottom of the cave.","zh":"突然，他们来到一个瀑布，瀑布落入洞穴底部的一个地下湖中。","t":172.62},{"en":"They plunged into the lake, and after loading their gear on an inflatable rubber dinghy, let the current carry them to the other side.","zh":"他们跳入湖中，把装备装到一艘充气橡皮艇上，然后让水流把他们带到对岸。","t":180.69},{"en":"To protect themselves from the icy water, they had to wear special rubber suits.","zh":"为了保护自己不受冰冷湖水的侵袭，他们不得不穿上特制的橡胶衣。","t":191.67},{"en":"At the far end of the lake, they came to huge piles of rubble which had been washed up by the water.","zh":"在湖的远端，他们遇到了被水冲刷而成的巨大碎石堆。","t":198.58},{"en":"In this part of the cave, they could hear an insistent booming sound","zh":"在洞穴的这部分，他们能听到一种持续不断的轰鸣声，","t":206.87},{"en":"which they found was caused by a small waterspout shooting down into a pool from the roof of the cave.","zh":"他们发现这是由一股小小的水柱从洞顶射入水潭所引起的。","t":212.17},{"en":"Squeezing through a cleft in the rocks, the pot-holers arrived at an enormous cavern, the size of a huge concert hall.","zh":"探洞者们挤过岩石中的一道裂缝，来到一个巨大的洞穴，其大小相当于一个巨大的音乐厅。","t":220.42},{"en":"After switching on powerful arc lights,","zh":"打开强光弧光灯后，","t":229.72},{"en":"they saw great stalagmites--some of them over forty feet high--rising up like tree-trunks to meet the stalactites suspended from the roof.","zh":"他们看到了巨大的石笋——其中一些高达40多英尺——像树干一样向上生长，与悬挂在洞顶的钟乳石相接。","t":233},{"en":"Round about, piles of limestone glistened in all the colours of the rainbow.","zh":"四周，一堆堆的石灰石闪耀着彩虹般的光芒。","t":245.43},{"en":"In the eerie silence of the cavern, the only sound that could be heard was made by water which dripped continuously from the high dome above them.","zh":"在洞穴诡异的寂静中，唯一能听到的声音是头顶高高的拱顶不断滴落的水声。","t":252.14}],"vocab":[{"word":"solitude","phonetic":"/ˈsɒlɪtjuːd/","meanings":[{"pos":"noun","meaning":"孤独；独居","usage":"不可数名词，强调独处的状态，可含褒义（享受独处）或贬义（孤单）"}]},{"word":"lure","phonetic":"/lʊə(r)/","meanings":[{"pos":"verb","meaning":"吸引；引诱","usage":"常用搭配lure sb. to/into sth.，指用具有吸引力的事物引导某人做某事"},{"pos":"noun","meaning":"诱惑力；诱饵","usage":"指吸引他人的事物或钓鱼等用的诱饵"}]},{"word":"instinct","phonetic":"/ˈɪnstɪŋkt/","meanings":[{"pos":"noun","meaning":"本能；直觉","usage":"表示天生的本能时为不可数，表具体的直觉反应时为可数，常用搭配by instinct（出于本能）"}]},{"word":"rambler","phonetic":"/ˈræmblə(r)/","meanings":[{"pos":"noun","meaning":"漫步者；闲逛者","usage":"指休闲散步的人，来自动词ramble（漫步、闲逛）"}]},{"word":"foresight","phonetic":"/ˈfɔːsaɪt/","meanings":[{"pos":"noun","meaning":"远见；先见之明","usage":"不可数名词，强调对未来的预判和规划能力，反义词为hindsight（事后聪明）"}]},{"word":"rig","phonetic":"/rɪɡ/","meanings":[{"pos":"verb","meaning":"装配；搭建","usage":"常用搭配rig up，指快速或临时搭建、装配设备等结构"}]},{"word":"descent","phonetic":"/dɪˈsent/","meanings":[{"pos":"noun","meaning":"下降；下倾","usage":"可指空间上的向下行进，也可指血统、身份的传承，反义词为ascent（上升）"}]},{"word":"precaution","phonetic":"/prɪˈkɔːʃn/","meanings":[{"pos":"noun","meaning":"预防措施；防备","usage":"常用复数形式，搭配take precautions against sth.（采取措施预防某事）"}]},{"word":"foretell","phonetic":"/fɔːˈtel/","meanings":[{"pos":"verb","meaning":"预言；预测","usage":"过去式和过去分词均为foretold，强调提前预告尚未发生的事"}]},{"word":"chasm","phonetic":"/ˈkæzəm/","meanings":[{"pos":"noun","meaning":"深坑；裂隙；分歧","usage":"既可指地理上的巨大裂口，也可引申为观点、群体之间的巨大分歧"}]},{"word":"flaw","phonetic":"/flɔː/","meanings":[{"pos":"noun","meaning":"瑕疵；缺陷；裂缝","usage":"可指物品的瑕疵、人的性格缺点或结构上的裂隙，常用搭配flaw in sth."}]},{"word":"plateau","phonetic":"/ˈplætəʊ/","meanings":[{"pos":"noun","meaning":"高原；稳定期","usage":"地理上指高原，也可引申为发展、增长停滞的平稳阶段，复数形式为plateaus或plateaux"}]},{"word":"wade","phonetic":"/weɪd/","meanings":[{"pos":"verb","meaning":"涉水；费力行进","usage":"常用搭配wade through sth.，既指蹚过水域，也引申为吃力地完成冗长的工作"}]},{"word":"eerie","phonetic":"/ˈɪəri/","meanings":[{"pos":"adjective","meaning":"怪异的；恐怖的","usage":"用来形容气氛、场景等让人感到不安、诡异的，侧重超自然的怪异感"}]},{"word":"glisten","phonetic":"/ˈɡlɪsn/","meanings":[{"pos":"verb","meaning":"闪光；闪亮","usage":"常指湿润或光滑的表面反射光线，多接介词with表示因某物而闪亮"}]}],"phrases":[{"phrase":"come to be known","usage":"表示逐渐被熟知、被称为，强调过程性而非突然成名","examples":[{"en":"Cave exploration, or pot-holing, as it has come to be known, is a relatively new sport.","zh":"洞穴勘探，也就是人们现在常说的洞穴探险，是一项相对较新的运动。"},{"en":"The small town has come to be known for its well-preserved ancient buildings.","zh":"这个小镇现在已经因保存完好的古建筑而广为人知。"}]},{"phrase":"rig up","usage":"指临时或快速搭建、装配设备、结构等","examples":[{"en":"It can take as long as eight days to rig up rope ladders and to establish supply bases before a descent can be made into a very deep cave.","zh":"在进入非常深的洞穴之前，可能需要长达8天的时间来搭建绳梯并建立补给基地。"},{"en":"The hikers rigged up a simple shelter with branches and a plastic sheet when it started to rain.","zh":"开始下雨时，徒步旅行者们用树枝和塑料布临时搭了一个简易庇护所。"}]},{"phrase":"edge one's way along","usage":"指小心翼翼地沿某条路径慢慢移动，强调动作的谨慎","examples":[{"en":"They had to edge their way along this, sometimes wading across shallow streams, or swimming across deep pools.","zh":"他们不得不沿着这条狭窄的通道慢慢挪行，时而蹚过浅溪，时而游过深潭。"},{"en":"We had to edge our way along the crowded platform to get to the train door.","zh":"我们不得不沿着拥挤的站台慢慢挪到列车车门处。"}]},{"phrase":"plunge into","usage":"既可指纵身跳入水中，也可引申为突然投入、开始做某事","examples":[{"en":"They plunged into the lake, and after loading their gear on an inflatable rubber dinghy, let the current carry them to the other side.","zh":"他们跳入湖中，把装备装上充气橡皮艇后，就让水流带着他们漂向对岸。"},{"en":"After graduation, he plunged into his first job with great enthusiasm.","zh":"毕业后，他满怀热情地投入了自己的第一份工作。"}]},{"phrase":"squeeze through","usage":"指用力挤过狭窄的空间，强调空间的狭小和通过的费力","examples":[{"en":"Squeezing through a cleft in the rocks, the pot-holers arrived at an enormous cavern, the size of a huge concert hall.","zh":"探险者们挤过岩石的缝隙，来到了一个足有大型音乐厅那么大的巨大洞穴里。"},{"en":"There was only a small gap in the fence, so we had to squeeze through it.","zh":"围栏上只有一个小缺口，所以我们不得不挤过去。"}]},{"phrase":"arouse instincts","usage":"表示激发、唤起本能，属于常用的动宾搭配","examples":[{"en":"They arouse instincts which can only be dimly understood.","zh":"它们激发了人们的本能，而这种本能只能被模糊地理解。"},{"en":"The smell of cooking aroused the dog's hunting instincts immediately.","zh":"烹饪的气味立刻唤起了这只狗的狩猎本能。"}]},{"phrase":"wash up","usage":"通常指水流将某物冲到岸边或某个地方，也可表示餐后清洗餐具","examples":[{"en":"At the far end of the lake, they came to huge piles of rubble which had been washed up by the water.","zh":"在湖的尽头，他们看到了被水冲上来的大堆碎石。"},{"en":"After the storm, a lot of driftwood was washed up on the beach.","zh":"风暴过后，很多浮木被冲到了海滩上。"}]}],"grammar":[{"title":"It引导的强调句","definition":"用来突出句子中的某个成分（主语、宾语、状语等），强调该成分是动作发生的核心原因或主体，基本含义为“正是……”。","structure":"It is/was + 被强调部分 + that/who + 句子剩余部分","usage":"当被强调部分指人时可以用who，其他情况一律用that；去掉It is/was和that/who后句子结构依然完整。","examples":[{"en":"Perhaps it is the desire for solitude or the chance of making an unexpected discovery that lures people down to the depths of the earth.","zh":"也许正是对独处的渴望，或是获得意外发现的机会，吸引着人们深入地下深处。"},{"en":"It was his dedication to the project that helped the team achieve success finally.","zh":"正是他对这个项目的付出，帮助团队最终取得了成功。"}]},{"title":"虚拟条件句的倒装","definition":"当虚拟条件句的谓语含有were, should, had时，可以省略if，将这些词移到句首形成倒装，用于书面语中，表达与事实相反的假设。","structure":"Were/Should/Had + 主语 + 谓语剩余部分，主句","usage":"多用于正式文体，否定词not不能提前，需放在主语之后。","examples":[{"en":"The cave might never have been discovered had not the entrance been spotted by the distinguished French pot-holer, Berger.","zh":"若不是法国著名洞穴探险家伯杰发现了这个洞口，这个洞穴可能永远不会被人知晓。"},{"en":"Had you followed my advice earlier, you would not have made such a mistake.","zh":"要是你早点听我的建议，你就不会犯这样的错误了。"}]},{"title":"定语从句的分隔现象","definition":"定语从句通常紧跟在先行词之后，但有时为了平衡句子结构，会被其他成分（如状语、谓语等）分隔开，需要根据语义判断先行词。","structure":"先行词 + 其他成分 + 关系词 + 定语从句","usage":"需通过语义和逻辑确定定语从句修饰的对象，避免误判先行词。","examples":[{"en":"In this part of the cave, they could hear an insistent booming sound which they found was caused by a small waterspout shooting down into a pool from the roof of the cave.","zh":"在洞穴的这一部分，他们能听到持续的轰鸣声，后来他们发现这声音是从洞穴顶部倾泻到水池里的小水柱发出的。"},{"en":"A new teacher will come tomorrow who will teach you history.","zh":"明天会来一位新老师，他将教你们历史。"}]}],"patterns":[{"pattern":"It is + 形容词 + to do sth.","explanation":"","original":{"en":"It is impossible to give a satisfactory explanation for a pot-holer's motives.","zh":"要对洞穴探险者的动机给出满意的解释是不可能的。"},"examples":[{"en":"It is necessary to learn basic safety rules before starting the experiment.","zh":"在开始实验之前学习基本的安全规则是很有必要的。"},{"en":"It is exciting to travel to a place you have never visited before.","zh":"去一个你从未去过的地方旅行是很令人兴奋的。"}]},{"pattern":"sth. have the same + 名词 + which/that sth. else have for sb.","explanation":"","original":{"en":"For him, caves have the same peculiar fascination which high mountains have for the climber.","zh":"对他来说，洞穴有着独特的魅力，就像高山对登山者的魅力一样。"},"examples":[{"en":"For children, fairy tales have the same magic attraction which advanced technology has for engineers.","zh":"对孩子们来说，童话故事有着神奇的吸引力，就像先进科技对工程师的吸引力一样。"},{"en":"For painters, natural scenery has the same profound inspiration which classic music has for musicians.","zh":"对画家来说，自然风景有着深厚的启发意义，就像古典音乐对音乐家的启发一样。"}]},{"pattern":"After doing sth., sb. do sth. until + 从句","explanation":"","original":{"en":"After entering the narrow gap on the plateau, they climbed down the steep sides of the cave until they came to a narrow corridor.","zh":"进入高原上的狭窄洞口后，他们沿着洞穴陡峭的岩壁往下爬，直到来到一条狭窄的通道前。"},"examples":[{"en":"After packing all the camping equipment, we walked along the mountain path until we found a flat clearing.","zh":"收拾好所有露营装备后，我们沿着山间小路前行，直到找到了一片平坦的空地。"},{"en":"After finishing his daily homework, the boy read storybooks until his mother asked him to sleep.","zh":"完成日常作业后，这个男孩一直在读故事书，直到妈妈叫他睡觉。"}]},{"pattern":"the only sound that could be heard was made by + 名词","explanation":"","original":{"en":"In the eerie silence of the cavern, the only sound that could be heard was made by water which dripped continuously from the high dome above them.","zh":"在洞穴诡异的寂静中，唯一能听到的声音是从他们头顶高高的穹顶不断滴落的水声。"},"examples":[{"en":"In the quiet library, the only sound that could be heard was made by pages being turned gently.","zh":"在安静的图书馆里，唯一能听到的声音是轻轻翻书的声音。"},{"en":"In the empty street at midnight, the only sound that could be heard was made by the cold wind blowing through the trees.","zh":"午夜空荡荡的街道上，唯一能听到的是寒风吹过树林的声音。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“瑕疵；缺陷；裂缝” 对应的单词是？","hint":"noun · /flɔː/","options":["twittering","flaw","unscrew","ferry"],"answer":1,"explain":"flaw · /flɔː/ · noun · 瑕疵；缺陷；裂缝。可指物品的瑕疵、人的性格缺点或结构上的裂隙，常用搭配flaw in sth.","source":{"kind":"vocab","word":"flaw"},"id":"b3-u42-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：闪光；闪亮","hint":"/ˈɡlɪsn/ · verb","answer":"glisten","placeholder":"输入英文单词","explain":"glisten · /ˈɡlɪsn/ · verb · 闪光；闪亮。常指湿润或光滑的表面反射光线，多接介词with表示因某物而闪亮","source":{"kind":"vocab","word":"glisten"},"id":"b3-u42-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It can take as long as eight days to _____ rope ladders and to establish supply bases before a descent can be made into a very deep cave.","hint":"在进入非常深的洞穴之前，可能需要长达8天的时间来搭建绳梯并建立补给基地。","answer":"rig up","placeholder":"输入缺失的短语","explain":"rig up：指临时或快速搭建、装配设备、结构等（在进入非常深的洞穴之前，可能需要长达8天的时间来搭建绳梯并建立补给基地。）","source":{"kind":"phrase","phrase":"rig up"},"id":"b3-u42-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：They arouse _____ which can only be dimly understood.","hint":"它们唤起人们只能模模糊糊感知到的本能。","answer":"instincts","placeholder":"输入缺失的单词","explain":"They arouse instincts which can only be dimly understood. — 它们唤起人们只能模模糊糊感知到的本能。","source":{"kind":"sentence","en":"They arouse instincts which can only be dimly understood."},"id":"b3-u42-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当虚拟条件句的谓语含有were, should, had时，可以省略if，将这些词移到句首形成倒装，用于书面语中，表达与事实相反的假设。” 描述的是哪个语法点？","hint":"Were/Should/Had + 主语 + 谓语剩余部分，主句","options":["副词的位置和作用","not only位于句首的部分倒装结构","定冠词the的特指用法 (Definite Article 'the' for Specific Reference)","虚拟条件句的倒装"],"answer":3,"explain":"虚拟条件句的倒装：Were/Should/Had + 主语 + 谓语剩余部分，主句：多用于正式文体，否定词not不能提前，需放在主语之后。","source":{"kind":"grammar","title":"虚拟条件句的倒装"},"id":"b3-u42-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe entrance to the cave is on a plateau in the Dauphine Alps.","hint":"","options":["总能在圣伯纳修道院受到热烈的欢迎。","打碎了你一半最好的餐具，还把自己划伤了。","洞口位于多芬阿尔卑斯山脉的一个高原上。","“埃尔科”号返回家园后，国防部的一名海军官员证实了这一点。"],"answer":2,"explain":"The entrance to the cave is on a plateau in the Dauphine Alps. — 洞口位于多芬阿尔卑斯山脉的一个高原上。","source":{"kind":"sentence","en":"The entrance to the cave is on a plateau in the Dauphine Alps."},"id":"b3-u42-q06"}]},{"id":"b3-u43","book":3,"unit":43,"key":"43","lessonFrom":43,"lessonTo":43,"title":"Fully Insured","titleZh":"全额投保","question":"Who owned the pie dish and why?","sentences":[{"en":"Insurance companies are normally willing to insure anything.","zh":"保险公司通常愿意为任何东西投保。","t":15.55},{"en":"Insuring public or private property is a standard practice in most countries in the world.","zh":"在世界上大多数国家，为公共或私人财产投保是一种惯例。","t":20.85},{"en":"If, however, you were holding an open air garden party or a fete it would be equally possible to insure yourself in the event of bad weather.","zh":"然而，如果你要举办一场露天花园派对或游园会，同样可以为自己投保，以防恶劣天气。","t":28.14},{"en":"Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay.","zh":"不言而喻，保险公司承担的风险越大，你将支付的保费就越高。","t":40.27},{"en":"It is not uncommon to hear that a shipping company has made a claim for the cost of salvaging a sunken ship.","zh":"航运公司为打捞沉船的费用提出索赔并非罕见。","t":49.9},{"en":"But the claim made by a local authority to recover the cost of salvaging a sunken pie dish must surely be unique.","zh":"但地方当局为打捞沉没的馅饼盘而提出的索赔，肯定是非同寻常的。","t":58.02},{"en":"Admittedly it was an unusual pie dish, for it was eighteen feet long and six feet wide.","zh":"诚然，这是一个不寻常的馅饼盘，因为它有18英尺长，6英尺宽。","t":68.34},{"en":"It had been purchased by a local authority so that an enormous pie could be baked for an annual fair.","zh":"它是由地方当局购买的，以便为一年一度的集市烤制一个巨大的馅饼。","t":77.4},{"en":"The pie committee decided that the best way to transport the dish would be by canal so they insured it for the trip.","zh":"馅饼委员会决定，运输这个盘子的最好方式是水路，所以他们为这次行程投了保。","t":86.4},{"en":"Shortly after it was launched, the pie committee went to a local inn to celebrate.","zh":"盘子下水后不久，馅饼委员会就去了一家当地的旅店庆祝。","t":96.61},{"en":"At the same time, a number of teenagers climbed on to the dish and held a little party of their own.","zh":"同时，一些青少年爬上盘子，开起了他们自己的小型派对。","t":103.28},{"en":"Dancing proved to be more than the dish could bear,","zh":"跳舞对盘子来说是无法承受的，","t":111.27},{"en":"for during the party it capsized and sank in seven feet of water.","zh":"因为在派对期间，它翻了船，沉入了七英尺深的水中。","t":115.25},{"en":"The pie committee telephoned a local garage owner who arrived in a recovery truck to salvage the pie dish.","zh":"馅饼委员会给当地的一位修车厂老板打电话，他开着一辆救援卡车前来打捞馅饼盘。","t":121.76},{"en":"Shivering in their wet clothes, the teenagers looked on while three men dived repeatedly into the water to locate the dish.","zh":"少年们穿着湿衣服颤抖着，看着三名男子反复潜入水中寻找盘子。","t":130.67},{"en":"They had little difficulty in finding it, but hauling it out of the water proved to be a serious problem.","zh":"他们找到它几乎没什么困难，但把它从水中拖出来却是个大问题。","t":141.41},{"en":"The sides of the dish were so smooth that it was almost impossible to attach hawsers and chains to the rim without damaging it.","zh":"盘子的侧面非常光滑，几乎不可能在不损坏它的情况下将缆绳和链条固定到边缘。","t":150.27},{"en":"Eventually chains were fixed to one end of the dish and a powerful winch was put into operation.","zh":"最终，链条被固定在盘子的一端，一台强大的绞车开始工作。","t":162.12},{"en":"The dish rose to the surface and was gently drawn towards the canal bank.","zh":"盘子浮出水面，被轻轻地拉向运河岸边。","t":170.84},{"en":"For one agonizing moment, the dish was perched precariously on the bank of the canal,","zh":"有一刻，盘子摇摇晃晃地栖息在运河岸边，令人心焦，","t":178.1},{"en":"but it suddenly overbalanced and slid back into the water.","zh":"但它突然失去平衡，滑回了水中。","t":185.67},{"en":"The men were now obliged to try once more.","zh":"男人们现在不得不再次尝试。","t":191.34},{"en":"This time they fixed heavy metal clamps to both sides of the dish so that they could fasten the chains.","zh":"这次他们在盘子的两边固定了沉重的金属夹，以便系上链条。","t":195.82},{"en":"The dish now had to be lifted vertically because one edge was resting against the side of the canal.","zh":"盘子现在必须垂直吊起，因为一侧正抵着运河的侧面。","t":204.77},{"en":"The winch was again put into operation and one of the men started up the truck.","zh":"绞车再次启动，其中一名男子发动了卡车。","t":212.23},{"en":"Several minutes later, the dish was successfully hauled above the surface of the water.","zh":"几分钟后，盘子被成功地吊出水面。","t":218.89},{"en":"Water streamed in torrents over its sides with such force that it set up a huge wave in the canal.","zh":"水从盘子两侧倾泻而下，力量之大，以至于在运河中掀起了巨浪。","t":225.3},{"en":"There was a danger that the wave would rebound off the other side of the bank and send the dish plunging into the water again.","zh":"存在着波浪会从运河对岸反弹回来，再次将盘子冲入水中的危险。","t":233.96},{"en":"By working at tremendous speed, the men managed to get the dish on to dry land before the wave returned.","zh":"男人们以惊人的速度工作，在波浪返回之前设法将盘子弄上了岸。","t":244.44}],"vocab":[{"word":"insure","phonetic":"/ɪnˈʃʊə(r)/","meanings":[{"pos":"verb","meaning":"给...保险；投保","usage":"常用insure sth against...结构，表示为某物投保某种险"}]},{"word":"premium","phonetic":"/ˈpriːmiəm/","meanings":[{"pos":"noun","meaning":"保险费；额外费用","usage":"指投保人定期支付给保险公司的费用"}]},{"word":"claim","phonetic":"/kleɪm/","meanings":[{"pos":"noun/verb","meaning":"索赔；要求（赔偿）","usage":"作名词时指索赔行为；作动词时常用make a claim结构"}]},{"word":"salvage","phonetic":"/ˈsælvɪdʒ/","meanings":[{"pos":"verb","meaning":"打捞；抢救","usage":"指从灾难或水中救出财物"}]},{"word":"capsize","phonetic":"/kæpˈsaɪz/","meanings":[{"pos":"verb","meaning":"（使）倾覆；（使）翻船","usage":"通常指船或类似容器的翻转"}]},{"word":"haul","phonetic":"/hɔːl/","meanings":[{"pos":"verb","meaning":"拖拽；用力拉","usage":"强调用力拖拽重物"}]},{"word":"winch","phonetic":"/wɪntʃ/","meanings":[{"pos":"noun","meaning":"绞车；起货机","usage":"一种用电力或人力驱动的起重设备"}]},{"word":"clamp","phonetic":"/klæmp/","meanings":[{"pos":"noun/verb","meaning":"夹子；夹紧","usage":"作名词指固定用的工具；作动词指用夹子固定"}]},{"word":"rebound","phonetic":"/rɪˈbaʊnd/","meanings":[{"pos":"verb","meaning":"弹回；反弹","usage":"指碰到某物后弹回来"}]},{"word":"perch","phonetic":"/pɜːtʃ/","meanings":[{"pos":"verb","meaning":"（使）处于；位于","usage":"指处于不稳定或高高在上的位置"}]},{"word":"overbalance","phonetic":"/ˌəʊvəˈbæləns/","meanings":[{"pos":"verb","meaning":"（使）失去平衡","usage":"指因不平衡而倒下或翻转"}]},{"word":"vertical","phonetic":"/ˈvɜːtɪkl/","meanings":[{"pos":"adj","meaning":"垂直的；纵向的","usage":"与horizontal（水平的）相对"}]},{"word":"tremendous","phonetic":"/trɪˈmendəs/","meanings":[{"pos":"adj","meaning":"巨大的；极大的","usage":"强调规模或程度非常大"}]},{"word":"sunken","phonetic":"/ˈsʌŋkən/","meanings":[{"pos":"adj","meaning":"沉没的；凹陷的","usage":"sink的过去分词作形容词，描述沉入水中的物体"}]},{"word":"fete","phonetic":"/feɪt/","meanings":[{"pos":"noun","meaning":"露天游乐会；义卖会","usage":"指户外的庆祝活动，通常有各种游戏和义卖"}]}],"phrases":[{"phrase":"be willing to","usage":"愿意做某事，表示乐意或准备做某事","examples":[{"en":"Insurance companies are normally willing to insure anything.","zh":"保险公司通常愿意为任何东西保险。"}]},{"phrase":"in the event of","usage":"如果；万一；倘若，用于引出假设的灾难情况","examples":[{"en":"It would be possible to insure yourself in the event of bad weather.","zh":"如果遇到坏天气，你也可以为自己投保。"}]},{"phrase":"make a claim","usage":"提出索赔，向保险公司要求赔偿","examples":[{"en":"A shipping company has made a claim for the cost of salvaging.","zh":"一家航运公司提出了打捞费用的索赔。"}]},{"phrase":"recover the cost","usage":"收回成本，弥补花费","examples":[{"en":"A local authority to recover the cost of salvaging.","zh":"地方当局为收回打捞费用。"}]},{"phrase":"look on","usage":"旁观，袖手观看","examples":[{"en":"The teenagers looked on while three men dived into the water.","zh":"当三个人反复潜水时，青少年们在一旁观看。"}]},{"phrase":"put into operation","usage":"启动；使运转；使生效","examples":[{"en":"A powerful winch was put into operation.","zh":"一台大功率绞车被启动运转。"}]},{"phrase":"set up","usage":"引起；产生；造成","examples":[{"en":"It set up a huge wave in the canal.","zh":"它在运河里掀起了一股巨浪。"}]},{"phrase":"attach to","usage":"系在...上；附加于","examples":[{"en":"It was almost impossible to attach hawsers to the rim.","zh":"几乎不可能把缆绳系在边缘上。"}]},{"phrase":"at tremendous speed","usage":"以极快的速度","examples":[{"en":"By working at tremendous speed, the men got the dish on to dry land.","zh":"由于以极快的速度工作，这些人把盘子弄到了陆地上。"}]},{"phrase":"be obliged to","usage":"不得不；必须","examples":[{"en":"The men were now obliged to try once more.","zh":"这些人现在不得不再次尝试。"}]}],"grammar":[{"title":"被动语态 (Passive Voice)","definition":"当句子的主语是动作的承受者时，使用被动语态。被动语态由be动词+过去分词构成。","structure":"主语 + be + 过去分词 (+ by + 动作执行者)","usage":"当不知道动作执行者、强调动作承受者或上下文中不需要提及执行者时使用被动语态。","examples":[{"en":"The pie dish was insured for the trip.","zh":"这个馅饼盘被投保了旅途险。"},{"en":"The dish was raised to the surface and was drawn towards the canal bank.","zh":"盘子被升到水面并被拖向运河岸边。"}]},{"title":"It is + not uncommon / not unusual to... (it作形式主语)","definition":"it作形式主语代替不定式短语或从句，真正的主语是后面的不定式to结构。这种结构用于表达某种情况并不罕见。","structure":"It is + not uncommon / not unusual + to + 动词原形","usage":"用来表达某事经常发生或并不稀奇，语气较委婉。","examples":[{"en":"It is not uncommon to hear that a shipping company has made a claim.","zh":"听到航运公司提出索赔是很常见的。"},{"en":"It is not unusual to see tourists here in summer.","zh":"夏天这里有游客并不稀奇。"}]},{"title":"more than + n./adj. (不仅仅；超出)","definition":"more than可以修饰名词、形容词或动词，表示程度'超出'或'不仅仅'的含义。","structure":"主语 + 动词 + more than + 名词/形容词/动词","usage":"用于强调数量、程度或性质超出预期或某个界限。","examples":[{"en":"Dancing proved to be more than the dish could bear.","zh":"跳舞被证明是这只盘子承受不了的。"},{"en":"This is more than I can afford.","zh":"这超出了我的能力范围。"}]}],"patterns":[{"pattern":"主语 + be + 过去分词 + for + 目的","explanation":"","original":{"en":"The pie committee decided that the best way to transport the dish would be by canal so they insured it for the trip.","zh":"馅饼委员会决定运输这只盘子的最好方式是通过运河，所以他们为旅途投了保。"},"examples":[{"en":"The company insured the equipment for the experiment.","zh":"公司为实验设备投了保。"},{"en":"He insured his car for the journey.","zh":"他为旅途中的汽车投保了。"}]},{"pattern":"It is + adj. + to + 动词原形","explanation":"","original":{"en":"It is not uncommon to hear that a shipping company has made a claim.","zh":"听到航运公司提出索赔是很常见的。"},"examples":[{"en":"It is not unusual to see children playing in the park.","zh":"看到孩子们在公园里玩耍并不稀奇。"},{"en":"It is essential to understand the importance of insurance.","zh":"理解保险的重要性是必要的。"}]},{"pattern":"主语 + have/had little difficulty in + doing sth","explanation":"","original":{"en":"They had little difficulty in finding it.","zh":"他们找到它没什么困难。"},"examples":[{"en":"I had little difficulty in solving this problem.","zh":"我解决这个难题没费什么力气。"},{"en":"She had little difficulty in passing the exam.","zh":"她通过考试没费什么力气。"}]},{"pattern":"be + adj. + enough + to + 动词原形","explanation":"","original":{"en":"The dish rose to the surface and was gently drawn towards the canal bank.","zh":"盘子升到水面并被轻轻地拖向运河岸边。"},"examples":[{"en":"The bridge was strong enough to support the weight.","zh":"这座桥足够坚固，能承受这个重量。"},{"en":"He was tall enough to reach the shelf.","zh":"他足够高，能够到那个架子。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“给...保险；投保” 对应的单词是？","hint":"verb · /ɪnˈʃʊə(r)/","options":["immensity","suspension","fancy-dress","insure"],"answer":3,"explain":"insure · /ɪnˈʃʊə(r)/ · verb · 给...保险；投保。常用insure sth against...结构，表示为某物投保某种险","source":{"kind":"vocab","word":"insure"},"id":"b3-u43-q01"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It would be possible to insure yourself _____ bad weather.","hint":"如果遇到坏天气，你也可以为自己投保。","answer":"in the event of","placeholder":"输入缺失的短语","explain":"in the event of：如果；万一；倘若，用于引出假设的灾难情况（如果遇到坏天气，你也可以为自己投保。）","source":{"kind":"phrase","phrase":"in the event of"},"id":"b3-u43-q02"},{"type":"cloze","kind":"text","prompt":"补全句子：The men were now obliged to try once _____","hint":"男人们现在不得不再次尝试。","answer":"more","placeholder":"输入缺失的单词","explain":"The men were now obliged to try once more. — 男人们现在不得不再次尝试。","source":{"kind":"sentence","en":"The men were now obliged to try once more."},"id":"b3-u43-q03"},{"type":"grammar-choice","kind":"choice","prompt":"“it作形式主语代替不定式短语或从句，真正的主语是后面的不定式to结构。这种结构用于表达某种情况并不罕见。” 描述的是哪个语法点？","hint":"It is + not uncommon / not unusual + to + 动词原形","options":["介词+关系代词引导的定语从句","It is + not uncommon / not unusual to... (it作形式主语)","should have done 结构","动词不定式作表语 (Infinitive as Predicative)"],"answer":1,"explain":"It is + not uncommon / not unusual to... (it作形式主语)：It is + not uncommon / not unusual + to + 动词原形：用来表达某事经常发生或并不稀奇，语气较委婉。","source":{"kind":"grammar","title":"It is + not uncommon / not unusual to... (it作形式主语)"},"id":"b3-u43-q04"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe pie committee decided that the best way to transport the dish would be by canal so they insured it for the trip.","hint":"","options":["馅饼委员会决定，运输这个盘子的最好方式是水路，所以他们为这次行程投了保。","她觉得她有可能说对了，尽管几率是百万分之一。","这又引发了另一场激烈的争吵。","尽管如此，意大利人还是把他看作一个英雄。"],"answer":0,"explain":"The pie committee decided that the best way to transport the dish would be by canal so they insured it for the trip. — 馅饼委员会决定，运输这个盘子的最好方式是水路，所以他们为这次行程投了保。","source":{"kind":"sentence","en":"The pie committee decided that the best way to transport the dish would be by canal so they insured it for the trip."},"id":"b3-u43-q05"},{"type":"dictation","kind":"text","prompt":"听写：点击播放，写出你听到的句子。","hint":"共 8 个单词","answer":"Insurance companies are normally willing to insure anything.","placeholder":"输入完整英文句子","explain":"Insurance companies are normally willing to insure anything. — 保险公司通常愿意为任何东西投保。","playText":"Insurance companies are normally willing to insure anything.","source":{"kind":"sentence","en":"Insurance companies are normally willing to insure anything."},"id":"b3-u43-q06"}]},{"id":"b3-u44","book":3,"unit":44,"key":"44","lessonFrom":44,"lessonTo":44,"title":"Speed and Comfort","titleZh":"速度与舒适","question":"Which type of transport does the writer prefer, do you think?","sentences":[{"en":"People travelling long distances frequently have to decide whether they would prefer to go by land, sea, or air.","zh":"长途旅行的人经常不得不决定他们是愿意乘陆路、海路还是空路。","t":15.05},{"en":"Hardly anyone can positively enjoy sitting in a train for more than a few hours.","zh":"几乎没有人会真正喜欢坐几个小时以上的火车。","t":23.94},{"en":"Train compartments soon get cramped and stuffy.","zh":"火车车厢很快就会变得又挤又闷。","t":30.98},{"en":"It is almost impossible to take your mind off the journey.","zh":"几乎不可能不去想旅途。","t":34.86},{"en":"Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lull you to sleep.","zh":"阅读只是一个部分解决方案，因为车轮在铁轨上单调的咔嗒声很快就会让你昏昏欲睡。","t":39.1},{"en":"During the day, sleep comes in snatches.","zh":"白天，睡眠是断断续续的。","t":49.1},{"en":"At night, when you really wish to go to sleep, you rarely manage to do so.","zh":"晚上，当你真正想睡觉时，你却很少能做到。","t":52.9},{"en":"If you are lucky enough to get a sleeper,","zh":"如果你足够幸运能得到一个卧铺，","t":58.6},{"en":"you spend half the night staring at the small blue light in the ceiling, or fumbling to find your ticket for inspection.","zh":"你会花半夜的时间盯着天花板上那盏小蓝灯，或者摸索着找票以备查验。","t":61.43},{"en":"Inevitably you arrive at your destination almost exhausted.","zh":"不可避免地，你到达目的地时几乎精疲力尽。","t":70.91},{"en":"Long car journeys are even less pleasant, for it is quite impossible even to read.","zh":"长途汽车旅行甚至更不愉快，因为连阅读都是完全不可能的。","t":77.13},{"en":"On motorways you can, at least, travel fairly safely at high speeds,","zh":"在高速公路上，你至少可以相当安全地高速行驶，","t":83.68},{"en":"but more often than not, the greater part of the journey is spent on roads with few service stations and too much traffic.","zh":"但通常情况下，旅途的大部分时间是在服务站很少且交通拥堵的道路上度过的。","t":89.31},{"en":"By comparison, ferry trips or cruises offer a great variety of civilized comforts.","zh":"相比之下，渡轮旅行或邮轮旅行提供了各种文明的舒适享受。","t":98.94},{"en":"You can stretch your legs on the spacious decks, play games,","zh":"你可以在宽敞的甲板上伸展双腿，玩游戏，","t":106.94},{"en":"meet interesting people and enjoy good food--always assuming, of course, that the sea is calm.","zh":"结识有趣的人，享受美食——当然，前提是海面风平浪静。","t":111},{"en":"If it is not, and you are likely to get seasick, no form of transport could be worse.","zh":"如果不是，而且你很可能会晕船，那么没有哪种交通方式会更糟了。","t":120.53},{"en":"Even if you travel in ideal weather, sea journeys take a long time.","zh":"即使你在理想的天气中旅行，海路旅行也需要很长时间。","t":128.15},{"en":"Relatively few people are prepared to sacrifice holiday time for the pleasure of travelling by sea.","zh":"相对而言，很少有人愿意为了海上旅行的乐趣而牺牲假期时间。","t":133.69},{"en":"Aeroplanes have the reputation of being dangerous and even hardened travellers are intimidated by them.","zh":"飞机有危险的名声，即使是经验丰富的旅行者也会被它们吓倒。","t":141.98},{"en":"They also have the disadvantage of being an expensive form of transport.","zh":"它们还有另一个缺点，就是价格昂贵的交通方式。","t":149.86},{"en":"But nothing can match them for speed and comfort.","zh":"但论速度和舒适度，没有任何交通工具能与它们相比。","t":155.68},{"en":"Travelling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour is an exhilarating experience.","zh":"在三万英尺高空，远在云层之上，以每小时超过500英里的速度飞行，是一种令人兴奋的体验。","t":160.07},{"en":"You do not have to devise ways of taking your mind off the journey, for an aeroplane gets you to your destination rapidly.","zh":"你不必绞尽脑汁去分散旅途的注意力，因为飞机能迅速将你送达目的地。","t":171.17},{"en":"For a few hours, you settle back in a deep armchair to enjoy the flight.","zh":"几个小时里，你可以靠在舒适的扶手椅上享受飞行。","t":179.72},{"en":"The real escapist can watch a film and sip champagne on some services.","zh":"真正的逃避现实者可以在某些航班上观看电影并品尝香槟。","t":186.26},{"en":"But even when such refinements are not available, there is plenty to keep you occupied.","zh":"但即使没有这些精致的服务，也有很多事情能让你保持忙碌。","t":192.79},{"en":"An aeroplane offers you an unusual and breathtaking view of the world.","zh":"飞机为你提供了独特而令人惊叹的世界景观。","t":198.57},{"en":"You soar effortlessly over high mountains and deep valleys.","zh":"你毫不费力地翱翔于高山深谷之上。","t":204.61},{"en":"You really see the shape of the land.","zh":"你真切地看到了大地的轮廓。","t":209.84},{"en":"If the landscape is hidden from view,","zh":"如果风景被遮挡，","t":212.94},{"en":"you can enjoy the extraordinary sight of unbroken cloud plains that stretch out for miles before you, while the sun shines brilliantly in a clear sky.","zh":"你可以欣赏到绵延数英里的连绵不断的云海奇景，同时阳光在晴朗的天空中灿烂地照耀。","t":215.59},{"en":"The journey is so smooth that there is nothing to prevent you from reading or sleeping.","zh":"旅途如此平稳，没有什么能阻止你阅读或睡觉。","t":228.89},{"en":"However you decide to spend your time, one thing is certain: you will arrive at your destination fresh and uncrumpled.","zh":"无论你决定如何度过时间，有一件事是肯定的：你将精神焕发、衣着整洁地抵达目的地。","t":235.62},{"en":"You will not have to spend the next few days recovering from a long and arduous journey.","zh":"你不必花接下来的几天来从漫长而艰辛的旅程中恢复。","t":245.57}],"vocab":[{"word":"cramped","phonetic":"/kræmpt/","meanings":[{"pos":"adj.","meaning":"狭窄的；拥挤的","usage":"形容空间狭小而拥挤，通常指房间、车厢等地方"}]},{"word":"stuffy","phonetic":"/ˈstʌfi/","meanings":[{"pos":"adj.","meaning":"闷热的；通风不良的","usage":"形容空气不流通、令人感到闷热的环境"}]},{"word":"monotonous","phonetic":"/məˈnɒtənəs/","meanings":[{"pos":"adj.","meaning":"单调的；乏味的","usage":"形容缺乏变化、令人感到无聊的事物"}]},{"word":"lull","phonetic":"/lʌl/","meanings":[{"pos":"verb","meaning":"使平静；使安静","usage":"指通过有节奏的声音或动作使人放松、想要入睡"}]},{"word":"sleeper","phonetic":"/ˈsliːpə/","meanings":[{"pos":"noun","meaning":"卧铺；卧铺车厢","usage":"特指火车上的卧铺座位或卧铺车厢"}]},{"word":"fumble","phonetic":"/ˈfʌmbl/","meanings":[{"pos":"verb","meaning":"摸索；胡乱摸索","usage":"指在黑暗中或不方便的情况下笨拙地寻找东西"}]},{"word":"inevitably","phonetic":"/ɪnˈevɪtəbli/","meanings":[{"pos":"adv.","meaning":"不可避免地；必然地","usage":"修饰动词，表示某事必然会发生"}]},{"word":"motorway","phonetic":"/ˈməʊtəweɪ/","meanings":[{"pos":"noun","meaning":"高速公路","usage":"英国英语，指专供机动车辆高速行驶的公路"}]},{"word":"ferry","phonetic":"/ˈferi/","meanings":[{"pos":"noun","meaning":"渡船；渡轮","usage":"指运送人、车等穿过河流、海峡等水域的船"}]},{"word":"intimidate","phonetic":"/ɪnˈtɪmɪdeɪt/","meanings":[{"pos":"verb","meaning":"恐吓；使害怕","usage":"指通过威胁或气势使人感到害怕或胆怯"}]},{"word":"exhilarating","phonetic":"/ɪɡˈzɪləreɪtɪŋ/","meanings":[{"pos":"adj.","meaning":"令人兴奋的；使人高兴的","usage":"形容令人感到非常兴奋和愉悦的体验"}]},{"word":"soar","phonetic":"/sɔː/","meanings":[{"pos":"verb","meaning":"高飞；翱翔","usage":"指鸟或飞机在高空中飞翔，也可用于抽象意义"}]},{"word":"breathtaking","phonetic":"/ˈbreθteɪkɪŋ/","meanings":[{"pos":"adj.","meaning":"令人惊叹的；惊人的","usage":"形容景色或事物极其壮观、美得令人屏息"}]},{"word":"escapist","phonetic":"/ɪˈskeɪpɪst/","meanings":[{"pos":"noun","meaning":"逃避现实者；追求逃避的人","usage":"指喜欢逃避现实、追求消遣娱乐的人"}]},{"word":"uncrumpled","phonetic":"/ʌnˈkrʌmpəld/","meanings":[{"pos":"adj.","meaning":"未弄皱的；精神饱满的","usage":"指人到达目的地后依然精神焕发、精力充沛"}]}],"phrases":[{"phrase":"take your mind off","usage":"转移注意力；使不再想某事","examples":[{"en":"Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lull you to sleep.","zh":"阅读只是部分解决办法，因为车轮撞击铁轨的单调节奏很快就会让你昏昏欲睡。"},{"en":"He tried to take his mind off the problem by watching TV.","zh":"他试图通过看电视来转移注意力，不再想那个问题。"}]},{"phrase":"come in snatches","usage":"断断续续地；时有时无地","examples":[{"en":"During the day, sleep comes in snatches.","zh":"白天的时候，睡眠断断续续。"},{"en":"We only got the information in snatches.","zh":"我们只是断断续续地得到这些信息。"}]},{"phrase":"by comparison","usage":"相比之下；比较起来","examples":[{"en":"By comparison, ferry trips or cruises offer a great variety of civilized comforts.","zh":"相比之下，渡船旅行或游轮提供了多种多样的文明享受。"},{"en":"By comparison, city life is more exciting.","zh":"相比之下，城市生活更加精彩。"}]},{"phrase":"stretch your legs","usage":"伸展双腿；走动活动","examples":[{"en":"You can stretch your legs on the spacious decks, play games, meet interesting people and enjoy good food.","zh":"你可以在宽敞的甲板上伸展双腿、做游戏、结识有趣的人、享用美食。"},{"en":"We've been driving for hours. Let's stop and stretch our legs.","zh":"我们已经开了几个小时的车了，停下来活动一下吧。"}]},{"phrase":"have the reputation of","usage":"有...的名声/声誉","examples":[{"en":"Aeroplanes have the reputation of being dangerous and even hardened travellers are intimidated by them.","zh":"飞机有危险的名声，甚至老练的旅行者也对其感到畏惧。"},{"en":"She has the reputation of being very reliable.","zh":"她有非常可靠的名声。"}]},{"phrase":"settle back","usage":"放松地坐好；靠回椅背","examples":[{"en":"For a few hours, you settle back in a deep armchair to enjoy the flight.","zh":"在几个小时内，你可以靠在扶手椅上享受飞行。"},{"en":"Settle back and enjoy the show.","zh":"坐好享受演出吧。"}]},{"phrase":"prevent sb. from doing sth.","usage":"阻止某人做某事","examples":[{"en":"The journey is so smooth that there is nothing to prevent you from reading or sleeping.","zh":"旅途如此平稳，没有什么能阻止你阅读或睡觉。"},{"en":"Nothing can prevent me from achieving my goals.","zh":"没有什么能阻止我实现目标。"}]},{"phrase":"more often than not","usage":"经常；多半","examples":[{"en":"but more often than not, the greater part of the journey is spent on roads with few service stations and too much traffic.","zh":"但更多的时候，大部分旅程是在只有很少服务站和交通拥挤的道路上度过的。"},{"en":"More often than not, she arrives late for meetings.","zh":"她开会经常迟到。"}]},{"phrase":"always assuming that","usage":"假设；只要是","examples":[{"en":"enjoy good food--always assuming, of course, that the sea is calm.","zh":"享用美食——当然，前提是海面平静。"},{"en":"I'll help you, always assuming that you need my assistance.","zh":"我会帮你的，只要你需要我的帮助。"}]},{"phrase":"get sb. to somewhere","usage":"把某人送到某地","examples":[{"en":"An aeroplane gets you to your destination rapidly.","zh":"飞机会快速把你送到目的地。"},{"en":"The bus will get you to the station on time.","zh":"公共汽车会把你准时送到车站。"}]}],"grammar":[{"title":"否定副词开头的倒装句 (Inversion with Negative Adverbs)","definition":"当否定副词或否定意义的词组位于句首时，句子需要使用部分倒装语序，即把助动词或be动词提到主语前面。","structure":"否定词 + 助动词/be动词 + 主语 + 动词原形...","usage":"用于强调否定意义，常见的否定词包括：hardly, never, rarely, seldom, not until, no sooner, little等。","examples":[{"en":"Hardly anyone can positively enjoy sitting in a train for more than a few hours.","zh":"几乎没有人能够真正享受连续坐几个小时的火车。"},{"en":"Rarely do we see such a beautiful sunset.","zh":"我们很少见到如此美丽的日落。"},{"en":"Never have I seen such a magnificent building.","zh":"我从未见过如此雄伟的建筑。"}]},{"title":"形式主语it (Formal Subject It)","definition":"用it作形式主语，而把真正的主语（通常是不定式、动名词或从句）放在句子后面，使句子更加平衡。","structure":"It + be + 形容词 + (for/of sb.) + to do sth.","usage":"当主语较长时，为了避免句子头重脚轻，使用形式主语it。","examples":[{"en":"It is almost impossible to take your mind off the journey.","zh":"几乎不可能使自己不想到旅途。"},{"en":"It is difficult to learn a new language.","zh":"学习一门新语言是很难的。"},{"en":"It is necessary for us to practice every day.","zh":"我们每天练习是必要的。"}]},{"title":"条件状语从句 (Conditional Clauses)","definition":"用于表达假设或条件的主从复合句，包括真实条件和虚拟条件。","structure":"If + 主语 + 动词..., 主语 + 动词/情态动词...","usage":"if引导的条件句可以表示真实条件或非真实（假设）的条件。","examples":[{"en":"If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light.","zh":"如果你足够幸运得到了卧铺，你会花半天时间盯着天花板上蓝色的小灯。"},{"en":"If it is not, and you are likely to get seasick, no form of transport could be worse.","zh":"如果海不平静，你可能会晕船，那么没有任何交通工具会比这更糟糕了。"}]}],"patterns":[{"pattern":"Hardly anyone can + 动词原形...","explanation":"","original":{"en":"Hardly anyone can positively enjoy sitting in a train for more than a few hours.","zh":"几乎没有人能够真正享受连续坐几个小时的火车。"},"examples":[{"en":"Hardly anyone can resist the temptation of free food.","zh":"几乎没有人能抵制免费食物的诱惑。"},{"en":"Hardly anyone can understand his complicated theory.","zh":"几乎没有人能理解他那套复杂的理论。"}]},{"pattern":"It is + 形容词 + to do sth.","explanation":"","original":{"en":"It is almost impossible to take your mind off the journey.","zh":"几乎不可能使自己不想到旅途。"},"examples":[{"en":"It is difficult to make a decision without all the facts.","zh":"没有全部事实很难做决定。"},{"en":"It is necessary to arrive early for the interview.","zh":"提前到达面试是必要的。"}]},{"pattern":"By comparison, ...","explanation":"","original":{"en":"By comparison, ferry trips or cruises offer a great variety of civilized comforts.","zh":"相比之下，渡船旅行或游轮提供了多种多样的文明享受。"},"examples":[{"en":"By comparison, living in the countryside is much quieter.","zh":"相比之下，住在乡下要安静得多。"},{"en":"By comparison, this restaurant offers better value for money.","zh":"相比之下，这家餐厅的性价比更高。"}]},{"pattern":"Nothing can + 动词原形 + ...","explanation":"","original":{"en":"But nothing can match them for speed and comfort.","zh":"但就速度和舒适度而言，没有任何交通工具能比得上它们。"},"examples":[{"en":"Nothing can replace the warmth of a mother's love.","zh":"没有什么能取代母爱的温暖。"},{"en":"Nothing can prevent him from reaching his goals.","zh":"没有什么能阻止他实现目标。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“摸索；胡乱摸索” 对应的单词是？","hint":"verb · /ˈfʌmbl/","options":["cottage","surgeon","ashtray","fumble"],"answer":3,"explain":"fumble · /ˈfʌmbl/ · verb · 摸索；胡乱摸索。指在黑暗中或不方便的情况下笨拙地寻找东西","source":{"kind":"vocab","word":"fumble"},"id":"b3-u44-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：未弄皱的；精神饱满的","hint":"/ʌnˈkrʌmpəld/ · adj.","answer":"uncrumpled","placeholder":"输入英文单词","explain":"uncrumpled · /ʌnˈkrʌmpəld/ · adj. · 未弄皱的；精神饱满的。指人到达目的地后依然精神焕发、精力充沛","source":{"kind":"vocab","word":"uncrumpled"},"id":"b3-u44-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：For a few hours, you _____ in a deep armchair to enjoy the flight.","hint":"在几个小时内，你可以靠在扶手椅上享受飞行。","answer":"settle back","placeholder":"输入缺失的短语","explain":"settle back：放松地坐好；靠回椅背（在几个小时内，你可以靠在扶手椅上享受飞行。）","source":{"kind":"phrase","phrase":"settle back"},"id":"b3-u44-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：At night, when you really wish to go to sleep, you _____ manage to do so.","hint":"晚上，当你真正想睡觉时，你却很少能做到。","answer":"rarely","placeholder":"输入缺失的单词","explain":"At night, when you really wish to go to sleep, you rarely manage to do so. — 晚上，当你真正想睡觉时，你却很少能做到。","source":{"kind":"sentence","en":"At night, when you really wish to go to sleep, you rarely manage to do so."},"id":"b3-u44-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于表达假设或条件的主从复合句，包括真实条件和虚拟条件。” 描述的是哪个语法点？","hint":"If + 主语 + 动词..., 主语 + 动词/情态动词...","options":["否定副词置于句首的倒装句","such...that... 结果状语从句","条件状语从句 (Conditional Clauses)","情态动词表推测（对过去的肯定推测）"],"answer":2,"explain":"条件状语从句 (Conditional Clauses)：If + 主语 + 动词..., 主语 + 动词/情态动词...：if引导的条件句可以表示真实条件或非真实（假设）的条件。","source":{"kind":"grammar","title":"条件状语从句 (Conditional Clauses)"},"id":"b3-u44-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nTrain compartments soon get cramped and stuffy.","hint":"","options":["不可避免地，这项修理工作远没有那么简单。","对不喜欢的人和善，小心驾驶，以及每天遛狗。","火车车厢很快就会变得又挤又闷。","就像一个决心有所发现的科学家一样，"],"answer":2,"explain":"Train compartments soon get cramped and stuffy. — 火车车厢很快就会变得又挤又闷。","source":{"kind":"sentence","en":"Train compartments soon get cramped and stuffy."},"id":"b3-u44-q06"}]},{"id":"b3-u45","book":3,"unit":45,"key":"45","lessonFrom":45,"lessonTo":45,"title":"The Power of the Press","titleZh":"新闻界的力量","question":"Does the writer think the parents were lucky or unlucky to gain prosperity in this way? Why?","sentences":[{"en":"In democratic countries any efforts to restrict the freedom of the press are rightly condemned.","zh":"在民主国家，任何限制新闻自由的努力都理应受到谴责。","t":20.22},{"en":"However, this freedom can easily be abused.","zh":"然而，这种自由很容易被滥用。","t":28.59},{"en":"Stories about people often attract far more public attention than political events.","zh":"关于人物的故事常常比政治事件更能吸引公众的注意力。","t":33.74},{"en":"Though we may enjoy reading about the lives of others,","zh":"尽管我们可能喜欢阅读别人的生活故事，","t":40.73},{"en":"it is extremely doubtful whether we would equally enjoy reading about ourselves.","zh":"但我们是否同样喜欢阅读关于我们自己的故事，这一点是极度怀疑的。","t":44.94},{"en":"Acting on the contention that facts are sacred,","zh":"记者们秉持着“事实神圣不可侵犯”的论点，","t":51.76},{"en":"reporters can cause untold suffering to individuals by publishing details about their private lives.","zh":"通过刊登个人私生活的细节，给他们造成了无法言喻的痛苦。","t":56.16},{"en":"Newspapers exert such tremendous influence that they can not only bring about major changes to the lives of ordinary people but can even overthrow a government.","zh":"报纸施加着巨大的影响力，它们不仅能给普通人的生活带来巨大变化，甚至可以推翻一个政府。","t":65.83},{"en":"The story of a poor family that acquired fame and fortune overnight, dramatically illustrates the power of the press.","zh":"一个贫困家庭一夜之间获得名利的故事，戏剧性地说明了新闻界的力量。","t":79.22},{"en":"The family lived in Aberdeen, a small town of 23,000 inhabitants in South Dakota.","zh":"这个家庭住在南达科他州一个拥有23,000居民的小镇阿伯丁。","t":88.3},{"en":"As the parents had five children, life was a perpetual struggle against poverty.","zh":"由于这对父母有五个孩子，生活一直是与贫困的无休止的斗争。","t":96.02},{"en":"They were expecting their sixth child and were faced with even more pressing economic problems.","zh":"他们正期待着第六个孩子，面临着更加紧迫的经济问题。","t":102.12},{"en":"If they had only had one more child, the fact would have passed unnoticed.","zh":"如果他们只多生一个孩子，这件事就会不为人知。","t":109.51},{"en":"They would have continued to struggle against economic odds and would have lived in obscurity.","zh":"他们会继续在经济困境中挣扎，并默默无闻地生活。","t":115.53},{"en":"But they suddenly became the parents of quintuplets, four girls and a boy, an event which radically changed their lives.","zh":"但他们突然成了五胞胎的父母，四个女孩和一个男孩，这一事件彻底改变了他们的生活。","t":122.51},{"en":"The day after the birth of the five children, an aeroplane arrived in Aberdeen bringing sixty reporters and photographers.","zh":"孩子们出生后的第二天，一架飞机抵达阿伯丁，带来了六十名记者和摄影师。","t":132.99},{"en":"The rise to fame was swift.","zh":"成名之路迅速。","t":142.41},{"en":"Television cameras and newspapers carried the news to everyone in the country.","zh":"电视摄像机和报纸将这一消息传遍了全国各地。","t":144.75},{"en":"Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs.","zh":"报纸和杂志为独家刊登这些故事和照片的权利，向这个家庭提供了巨额报酬。","t":150.03},{"en":"Gifts poured in not only from unknown people,","zh":"礼物源源不断地涌来，不仅来自陌生人，","t":158.52},{"en":"but from baby food and soap manufacturers who wished to advertise their products.","zh":"也来自希望宣传产品的婴儿食品和肥皂制造商。","t":162.22},{"en":"The old farmhouse the family lived in was to be replaced by a new $500, 000 home.","zh":"这家人住的老农舍将被一座价值50万美元的新房子取代。","t":168.83},{"en":"Reporters kept pressing for interviews so lawyers had to be employed to act as spokesmen for the family at press conferences.","zh":"记者们不停地要求采访，所以不得不雇佣律师在新闻发布会上担任这个家庭的发言人。","t":176.83},{"en":"While the five babies were still quietly sleeping in oxygen tents in a hospital nursery,","zh":"当五个婴儿还在医院育婴室的氧气帐篷里安静地睡觉时，","t":186.84},{"en":"their parents were paying the price for fame.","zh":"他们的父母却在为名声付出代价。","t":193.58},{"en":"It would never again be possible for them to lead normal lives.","zh":"他们再也无法过上正常的生活了。","t":197.27},{"en":"They had become the victims of commercialization, for their names had acquired a market value.","zh":"他们成了商业化的受害者，因为他们的名字已经有了市场价值。","t":202.2},{"en":"Instead of being five new family members, these children had immediately become a commodity.","zh":"这些孩子不再是五个新的家庭成员，而是立刻变成了商品。","t":210.25}],"vocab":[{"word":"restrict","phonetic":"/rɪˈstrɪkt/","meanings":[{"pos":"verb","meaning":"限制，约束","usage":"及物动词，常接名词作宾语，常见搭配为restrict sb/sth to sth，表示“把某人/某物限制在某范围内”"}]},{"word":"condemn","phonetic":"/kənˈdem/","meanings":[{"pos":"verb","meaning":"谴责，指责","usage":"及物动词，常用于正式语境中表示强烈反对某行为，常见搭配为condemn sb for (doing) sth"}]},{"word":"abuse","phonetic":"/əˈbjuːz/","meanings":[{"pos":"verb","meaning":"滥用；虐待","usage":"作“滥用”解时，宾语多为权力、权利等抽象名词；作“虐待”解时，宾语多为人或动物"}]},{"word":"contention","phonetic":"/kənˈtenʃn/","meanings":[{"pos":"noun","meaning":"观点，主张；争论","usage":"表示“观点”时为可数名词，常用于正式辩论或论述语境；表示“争论”时为不可数名词"}]},{"word":"untold","phonetic":"/ˌʌnˈtəʊld/","meanings":[{"pos":"adjective","meaning":"难以形容的，数不清的","usage":"通常用于修饰抽象名词，强调程度或数量极大、难以衡量"}]},{"word":"exert","phonetic":"/ɪɡˈzɜːt/","meanings":[{"pos":"verb","meaning":"施加（影响、压力等）；运用","usage":"及物动词，常见搭配为exert influence/pressure on sb/sth，表示“对某人/某物施加影响/压力”"}]},{"word":"overthrow","phonetic":"/ˌəʊvəˈθrəʊ/","meanings":[{"pos":"verb","meaning":"推翻，打倒","usage":"及物动词，宾语通常为政府、政权、统治者等，过去式和过去分词为overthrew、overthrown"}]},{"word":"prosperity","phonetic":"/prɒˈsperəti/","meanings":[{"pos":"noun","meaning":"兴旺，繁荣，成功","usage":"不可数名词，可指经济、事业等各方面的富足和成功"}]},{"word":"perpetual","phonetic":"/pəˈpetʃuəl/","meanings":[{"pos":"adjective","meaning":"永久的，不断的，无休止的","usage":"强调动作或状态持续发生、没有间断，常修饰抽象名词，带有一定负面色彩时表示“烦人的，没完没了的”"}]},{"word":"quintuplets","phonetic":"/ˈkwɪntjʊpləts/","meanings":[{"pos":"noun","meaning":"五胞胎","usage":""}]},{"word":"radically","phonetic":"/ˈrædɪkli/","meanings":[{"pos":"adverb","meaning":"根本地，彻底地","usage":"用于修饰动词或形容词，强调变化的程度非常大，完全改变原有状态"}]},{"word":"exclusive","phonetic":"/ɪkˈskluːsɪv/","meanings":[{"pos":"adjective","meaning":"独有的，独家的","usage":"常用于表示权利、内容等仅供某一方使用，常见搭配为exclusive rights（独家权利）"}]},{"word":"obscurity","phonetic":"/əbˈskjʊərəti/","meanings":[{"pos":"noun","meaning":"无名，默默无闻；晦涩","usage":"作“无名”解时为不可数名词，常见搭配为live in obscurity（过着默默无闻的生活）"}]},{"word":"commercialization","phonetic":"/kəˌmɜːʃəlaɪˈzeɪʃn/","meanings":[{"pos":"noun","meaning":"商业化","usage":"不可数名词，指将事物转化为以盈利为目的的商品的过程"}]},{"word":"commodity","phonetic":"/kəˈmɒdəti/","meanings":[{"pos":"noun","meaning":"商品，货物","usage":"可数名词，多指用于贸易的工农业产品，也可引申指被当作商品看待的人或事物"}]}],"phrases":[{"phrase":"act on","usage":"表示“根据……行事，按照……采取行动”，后接建议、观点、信息等名词作宾语","examples":[{"en":"Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals.","zh":"记者们遵从“事实至上”的观点，却可能给个人带来难以估量的痛苦。"},{"en":"You should act on your teacher's advice if you want to improve your grades quickly.","zh":"如果你想快速提高成绩，就应该按照老师的建议去做。"}]},{"phrase":"bring about","usage":"表示“导致，引起，使发生”，为及物短语动词，宾语通常为变化、问题、后果等名词","examples":[{"en":"Newspapers can not only bring about major changes to the lives of ordinary people but can even overthrow a government.","zh":"报纸不仅能给普通人的生活带来重大改变，甚至能推翻一个政府。"},{"en":"Technological advances have brought about great changes to the way we communicate.","zh":"技术进步给我们的沟通方式带来了巨大的变化。"}]},{"phrase":"be faced with","usage":"表示“面临，面对”，主语通常为人或组织，后接困难、问题、挑战等名词作宾语","examples":[{"en":"They were expecting their sixth child and were faced with even more pressing economic problems.","zh":"他们正等着第六个孩子出生，面临着更为严峻的经济问题。"},{"en":"When you are faced with a difficult choice, try to stay calm and weigh all the options.","zh":"当你面临艰难抉择时，尽量保持冷静，权衡所有选择。"}]},{"phrase":"press for","usage":"表示“强烈要求，敦促”，后接要求得到的事物或行动作宾语，也可接press sb for sth表示“向某人索要某物/敦促某人做某事”","examples":[{"en":"Reporters kept pressing for interviews so lawyers had to be employed to act as spokesmen.","zh":"记者们不断要求采访，所以这家人不得不聘请律师在新闻发布会上充当发言人。"},{"en":"Environmental groups are pressing for stricter laws to reduce plastic waste.","zh":"环保组织正在敦促出台更严格的法律来减少塑料垃圾。"}]},{"phrase":"pay the price for","usage":"表示“为……付出代价”，后接行为、事件等名词，强调因某件事而承受不好的后果","examples":[{"en":"While the five babies were still sleeping in oxygen tents, their parents were paying the price for fame.","zh":"当五个婴儿还在医院育婴室的氧气帐里安睡时，他们的父母已经在为出名付出代价了。"},{"en":"Many young people pay the price for staying up late frequently when they get older.","zh":"很多年轻人年纪大了之后，会为经常熬夜付出代价。"}]},{"phrase":"pour in","usage":"表示“大量涌入，蜂拥而至”，主语通常为信件、礼物、信息等名词，强调数量多、速度快","examples":[{"en":"Gifts poured in not only from unknown people, but from baby food manufacturers as well.","zh":"大量礼物涌来，不仅来自素不相识的人，还有婴儿食品制造商。"},{"en":"After the star shared her donation story, messages of support poured in from all over the country.","zh":"这位明星分享了她的捐赠故事后，支持的信息从全国各地蜂拥而至。"}]},{"phrase":"struggle against","usage":"表示“与……作斗争，努力克服”，后接困难、逆境、疾病等名词，强调对抗的过程很艰难","examples":[{"en":"They would have continued to struggle against economic odds and would have lived in obscurity.","zh":"他们本会继续和经济困难作斗争，过着默默无闻的生活。"},{"en":"The local people have been struggling against the flood for three days to protect their homes.","zh":"当地民众已经和洪水抗争了三天，以保护他们的家园。"}]}],"grammar":[{"title":"与过去事实相反的虚拟语气","definition":"用于描述与过去实际发生的情况相反的假设，表达遗憾、假设等含义，主从句都针对过去的时间","structure":"If + 主语 + had + 过去分词, 主语 + would/could/might + have + 过去分词","usage":"从句描述假设的过去情况，主句描述该假设下会产生的过去结果，if可省略，此时将had提前至句首形成倒装","examples":[{"en":"If they had only had one more child, the fact would have passed unnoticed.","zh":"如果他们只是多生了一个孩子，这件事本来根本不会有人注意。"},{"en":"If I had studied harder last semester, I would have got a better score in the final exam.","zh":"如果我上学期更努力学习，我期末考试就会考得更好。"}]},{"title":"such...that... 结果状语从句","definition":"用于表示“如此……以至于……”，引导结果状语从句，强调名词的程度或性质导致了某结果","structure":"such + (a/an) + 形容词 + 可数名词单数/不可数名词/可数名词复数 + that + 结果从句","usage":"such修饰其后的名词，当名词前有many/much/few/little修饰时，需用so代替such","examples":[{"en":"Newspapers exert such tremendous influence that they can not only bring about major changes to the lives of ordinary people but can even overthrow a government.","zh":"报纸的影响力如此巨大，以至于它们不仅能给普通人的生活带来重大改变，甚至能推翻一个政府。"},{"en":"It was such a boring speech that most of the audience fell asleep halfway through.","zh":"这场演讲太无聊了，以至于大部分听众中途都睡着了。"}]}],"patterns":[{"pattern":"It is extremely doubtful whether...","explanation":"","original":{"en":"Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would equally enjoy reading about ourselves.","zh":"尽管我们可能喜欢读别人的生活故事，但我们是否同样喜欢读自己的故事，这一点非常值得怀疑。"},"examples":[{"en":"Though many people dream of being famous, it is extremely doubtful whether they can bear the pressure that comes with it.","zh":"尽管很多人梦想出名，但他们是否能承受出名带来的压力非常值得怀疑。"},{"en":"Though the plan sounds perfect in theory, it is extremely doubtful whether it can be carried out in practice.","zh":"尽管这个计划理论上听起来很完美，但它在实践中是否能执行非常值得怀疑。"}]},{"pattern":"The story of... dramatically illustrates the power of...","explanation":"","original":{"en":"The story of a poor family that acquired fame and fortune overnight, dramatically illustrates the power of the press.","zh":"一个贫苦家庭一夜之间名利双收的故事，生动地说明了新闻界的力量。"},"examples":[{"en":"The story of the small business that grew into a global company in ten years dramatically illustrates the power of innovation.","zh":"这个小企业十年内成长为跨国公司的故事，生动地说明了创新的力量。"},{"en":"The story of the disabled athlete who won the gold medal dramatically illustrates the power of persistence.","zh":"这位残疾运动员赢得金牌的故事，生动地说明了坚持的力量。"}]},{"pattern":"Instead of being..., ... had immediately become...","explanation":"","original":{"en":"Instead of being five new family members, these children had immediately become a commodity.","zh":"这些孩子非但没有成为五名新的家庭成员，反而立刻变成了一种商品。"},"examples":[{"en":"Instead of being a tool to improve learning efficiency, the mobile phone has immediately become a distraction for many students.","zh":"手机非但没有成为提升学习效率的工具，反而立刻变成了很多学生分心的事物。"},{"en":"Instead of being a place for relaxation, the crowded scenic spot had immediately become a source of stress for the tourists.","zh":"这个拥挤的景区非但没有成为放松的地方，反而立刻变成了游客压力的来源。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“无名，默默无闻；晦涩” 对应的单词是？","hint":"noun · /əbˈskjʊərəti/","options":["ferry","obscurity","dismantle","exhibit"],"answer":1,"explain":"obscurity · /əbˈskjʊərəti/ · noun · 无名，默默无闻；晦涩。作“无名”解时为不可数名词，常见搭配为live in obscurity（过着默默无闻的生活）","source":{"kind":"vocab","word":"obscurity"},"id":"b3-u45-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：谴责，指责","hint":"/kənˈdem/ · verb","answer":"condemn","placeholder":"输入英文单词","explain":"condemn · /kənˈdem/ · verb · 谴责，指责。及物动词，常用于正式语境中表示强烈反对某行为，常见搭配为condemn sb for (doing) sth","source":{"kind":"vocab","word":"condemn"},"id":"b3-u45-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：They would have continued to _____ economic odds and would have lived in obscurity.","hint":"他们本会继续和经济困难作斗争，过着默默无闻的生活。","answer":"struggle against","placeholder":"输入缺失的短语","explain":"struggle against：表示“与……作斗争，努力克服”，后接困难、逆境、疾病等名词，强调对抗的过程很艰难（他们本会继续和经济困难作斗争，过着默默无闻的生活。）","source":{"kind":"phrase","phrase":"struggle against"},"id":"b3-u45-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：But they _____ became the parents of quintuplets, four girls and a boy, an event which radically changed their lives.","hint":"但他们突然成了五胞胎的父母，四个女孩和一个男孩，这一事件彻底改变了他们的生活。","answer":"suddenly","placeholder":"输入缺失的单词","explain":"But they suddenly became the parents of quintuplets, four girls and a boy, an event which radically changed their lives. — 但他们突然成了五胞胎的父母，四个女孩和一个男孩，这一事件彻底改变了他们的生活。","source":{"kind":"sentence","en":"But they suddenly became the parents of quintuplets, four girls and a boy, an event which radically changed their lives."},"id":"b3-u45-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于描述与过去实际发生的情况相反的假设，表达遗憾、假设等含义，主从句都针对过去的时间” 描述的是哪个语法点？","hint":"If + 主语 + had + 过去分词, 主语 + would/could/might + have + 过去分词","options":["动名词的被动语态","as if引导的虚拟语气","It is + not uncommon / not unusual to... (it作形式主语)","与过去事实相反的虚拟语气"],"answer":3,"explain":"与过去事实相反的虚拟语气：If + 主语 + had + 过去分词, 主语 + would/could/might + have + 过去分词：从句描述假设的过去情况，主句描述该假设下会产生的过去结果，if可省略，此时将had提前至句首形成倒装","source":{"kind":"grammar","title":"与过去事实相反的虚拟语气"},"id":"b3-u45-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nTelevision cameras and newspapers carried the news to everyone in the country.","hint":"","options":["电视摄像机和报纸将这一消息传遍了全国各地。","乔治脱下他的夹克，","贝茜为哈里特姑妈工作了三年。","这些就是所谓的“大型机”。"],"answer":0,"explain":"Television cameras and newspapers carried the news to everyone in the country. — 电视摄像机和报纸将这一消息传遍了全国各地。","source":{"kind":"sentence","en":"Television cameras and newspapers carried the news to everyone in the country."},"id":"b3-u45-q06"}]},{"id":"b3-u46","book":3,"unit":46,"key":"46","lessonFrom":46,"lessonTo":46,"title":"Do It Yourself","titleZh":"自己动手","question":"Did the writer repair his lawn mower in the end? Why/Why not?","sentences":[{"en":"So great is our passion for doing things for ourselves,","zh":"我们自己动手做事情的热情如此高涨，","t":16.95},{"en":"that we are becoming increasingly less dependent on specialized labour.","zh":"以至于我们对专业劳动的依赖越来越少。","t":21.4},{"en":"No one can plead ignorance of a subject any longer, for there are countless do-it-yourself publications.","zh":"任何人不能再声称对某事一无所知了，因为有无数的自己动手刊物。","t":27.22},{"en":"Armed with the right tools and materials, newlyweds gaily embark on the task of decorating their own homes.","zh":"新婚夫妇带着合适的工具和材料，愉快地着手装饰自己的家园。","t":35.22},{"en":"Men, particularly, spend hours of their leisure time installing their own fireplaces,","zh":"男人们，尤其是，花费数小时的闲暇时间安装自己的壁炉，","t":43.7},{"en":"laying out their own gardens; building garages and making furniture.","zh":"布置自己的花园；建造车库和制作家具。","t":50.59},{"en":"Some really keen enthusiasts go so far as to build their own computers.","zh":"一些真正热心的爱好者甚至自己组装电脑。","t":56.23},{"en":"Shops cater for the do-it-yourself craze not only by running special advisory services for novices,","zh":"商店为了迎合这种自己动手热潮，不仅为新手提供专门的咨询服务，","t":62.48},{"en":"but by offering consumers bits and pieces which they can assemble at home.","zh":"而且还向消费者提供他们可以在家组装的零配件。","t":70.21},{"en":"Such things provide an excellent outlet for pent up creative energy, but unfortunately not all of us are born handymen.","zh":"这样的事情为积压的创造性精力提供了很好的发泄途径，但不幸的是，我们并非所有人都是天生的巧匠。","t":75.74},{"en":"Some wives tend to believe that their husbands are infinitely resourceful and can fix anything.","zh":"一些妻子倾向于认为她们的丈夫足智多谋，什么都能修好。","t":86.47},{"en":"Even men who can hardly drive a nail in straight are supposed to be born electricians, carpenters, plumbers and mechanics.","zh":"即使那些连钉子都钉不直的男人，也被认为是天生的电工、木匠、水管工和机械师。","t":93.94},{"en":"When lights fuse, furniture gets rickety, pipes get clogged, or vacuum cleaners fail to operate,","zh":"当灯泡烧坏、家具摇晃、管道堵塞或吸尘器无法工作时，","t":103.52},{"en":"some women assume that their husbands will somehow put things right.","zh":"一些女人会认为她们的丈夫总会把事情弄好。","t":111.83},{"en":"The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything,","zh":"自己动手游戏的糟糕之处在于，有时连男人也活在自己无所不能的错觉中，","t":116.51},{"en":"even when they have repeatedly been proved wrong.","zh":"即使他们一再被证明是错的。","t":125.2},{"en":"It is a question of pride as much as anything else.","zh":"这更多的是一个面子问题。","t":129.05},{"en":"Last spring my wife suggested that I call in a man to look at our lawn mower.","zh":"去年春天，我妻子建议我请人来修理我们的割草机。","t":133.1},{"en":"It had broken down the previous summer, and though I promised to repair it, I had never got round to it.","zh":"它在前一个夏天坏了，虽然我答应修理，但一直没空动手。","t":139.3},{"en":"I would not hear of the suggestion and said that I would fix it myself.","zh":"我不听她的建议，说我会自己修好它。","t":147.78},{"en":"One Saturday afternoon, I hauled the machine into the garden and had a close look at it.","zh":"一个星期六下午，我把机器拖到花园里仔细查看。","t":153.7},{"en":"As far as I could see, it needed only a minor adjustment:","zh":"据我所见，它只需要做一些小调整：","t":160.45},{"en":"a turn of a screw here, a little tightening up there, a drop of oil and it would be as good as new.","zh":"这里拧一下螺丝，那里紧一紧，再滴一滴油，就会焕然一新。","t":165.27},{"en":"Inevitably the repair job was not quite so simple.","zh":"不可避免地，这项修理工作远没有那么简单。","t":173.88},{"en":"The mower firmly refused to mow, so I decided to dismantle it.","zh":"割草机坚决不肯割草，所以我决定把它拆开。","t":179.04},{"en":"The garden was soon littered with chunks of metal which had once made up a lawn mower.","zh":"花园里很快就散落着曾经组成割草机的金属碎片。","t":185.22},{"en":"But I was extremely pleased with myself. I had traced the cause of the trouble.","zh":"但我对自己非常满意。我找到了故障的原因。","t":192.99},{"en":"One of the links in the chain that drives the wheels had snapped.","zh":"驱动车轮的链条上的一环断裂了。","t":198.61},{"en":"After buying a new chain I was faced with the insurmountable task of putting the confusing jigsaw puzzle together again.","zh":"买了一条新链条后，我面临着一项无法克服的任务：把这个令人困惑的拼图重新组装起来。","t":203.64},{"en":"I was not surprised to find that the machine still refused to work after I had reassembled it,","zh":"我重新组装好机器后，发现它仍然无法工作，对此我并不感到惊讶，","t":214.7},{"en":"for the simple reason that I was left with several curiously shaped bits of metal which did not seem to fit anywhere.","zh":"理由很简单，我剩下了一些形状奇特的金属零件，似乎哪里也安不上。","t":222.35},{"en":"I gave up in despair.","zh":"我绝望地放弃了。","t":232.44},{"en":"The weeks passed and the grass grew.","zh":"几周过去了，草长高了。","t":235.01},{"en":"When my wife nagged me to do something about it,","zh":"当我妻子唠叨我该做些什么时，","t":238.12},{"en":"I told her that either I would have to buy a new mower or let the grass grow.","zh":"我告诉她，要么我买一台新割草机，要么就让草长着。","t":241.52},{"en":"Needless to say our house is now surrounded by a jungle.","zh":"不用说，我们的房子现在被一片丛林包围着。","t":246.91},{"en":"Buried somewhere in deep grass there is a rusting lawn mower which I have promised to repair one day.","zh":"某个地方，在深草丛中埋着一台生锈的割草机，我曾承诺有一天会把它修好。","t":251.75}],"vocab":[{"word":"passion","phonetic":"/ˈpæʃən/","meanings":[{"pos":"noun","meaning":"酷爱，热情","usage":"通常搭配介词for，表示对某事物的强烈喜爱"}]},{"word":"plead","phonetic":"/pliːd/","meanings":[{"pos":"verb","meaning":"以…为借口，抗辩","usage":"后接名词作宾语，常见搭配plead ignorance（声称不知情）"}]},{"word":"gaily","phonetic":"/ˈɡeɪli/","meanings":[{"pos":"adverb","meaning":"快乐地，兴冲冲地","usage":"修饰动词，描述人做某事时愉快的状态"}]},{"word":"embark","phonetic":"/ɪmˈbɑːk/","meanings":[{"pos":"verb","meaning":"开始，从事","usage":"常搭配介词on/upon，指开始一项新的或重要的活动"}]},{"word":"cater","phonetic":"/ˈkeɪtə/","meanings":[{"pos":"verb","meaning":"满足需要，迎合","usage":"搭配介词for，表示满足某人或某群体的需求"}]},{"word":"novice","phonetic":"/ˈnɒvɪs/","meanings":[{"pos":"noun","meaning":"新手，初学者","usage":"指在某一领域没有经验的人"}]},{"word":"outlet","phonetic":"/ˈaʊtlet/","meanings":[{"pos":"noun","meaning":"（情感、精力的）发泄途径，出口","usage":"常搭配介词for，表示释放某种情绪或能量的渠道"}]},{"word":"resourceful","phonetic":"/rɪˈsɔːsfəl/","meanings":[{"pos":"adjective","meaning":"足智多谋的，办法多的","usage":"用来形容人善于应对各种困难"}]},{"word":"delusion","phonetic":"/dɪˈluːʒən/","meanings":[{"pos":"noun","meaning":"错觉，妄想","usage":"常搭配live under the delusion that，表示抱有错误的想法"}]},{"word":"haul","phonetic":"/hɔːl/","meanings":[{"pos":"verb","meaning":"用力拖，拉","usage":"指费力地搬运重物"}]},{"word":"dismantle","phonetic":"/dɪsˈmæntəl/","meanings":[{"pos":"verb","meaning":"拆卸，拆开","usage":"指把机器、结构等拆成多个部件"}]},{"word":"snapped","phonetic":"/snæpt/","meanings":[{"pos":"verb（过去分词）","meaning":"断裂，绷断","usage":"常用来描述细线、链条等硬物突然折断"}]},{"word":"insurmountable","phonetic":"/ˌɪnsəˈmaʊntəbəl/","meanings":[{"pos":"adjective","meaning":"难以克服的，无法解决的","usage":"常修饰问题、困难等，表示难度极大无法应对"}]},{"word":"jigsaw","phonetic":"/ˈdʒɪɡsɔː/","meanings":[{"pos":"noun","meaning":"拼图游戏，错综复杂的事物","usage":"jigsaw puzzle指拼图，也可比喻复杂难理清的情况"}]},{"word":"nag","phonetic":"/næɡ/","meanings":[{"pos":"verb","meaning":"唠叨，催促","usage":"通常指反复抱怨或催促某人做某事"}]}],"phrases":[{"phrase":"get round to","usage":"抽出时间做（一直想做的事）","examples":[{"en":"I've been meaning to fix the shelf, but I never got round to it.","zh":"我一直想修那个架子，但始终抽不出时间做。"}]},{"phrase":"lay out","usage":"布置，设计（花园、场地等）","examples":[{"en":"They spent three months laying out their new garden.","zh":"他们花了三个月布置新花园。"}]},{"phrase":"go so far as to","usage":"甚至做…，竟然到…的地步","examples":[{"en":"Some fans go so far as to wait outside the hotel for hours just to see the star.","zh":"一些粉丝甚至在酒店外等好几个小时，就为了看明星一眼。"}]},{"phrase":"cater for","usage":"满足需求，迎合","examples":[{"en":"This restaurant caters for vegetarians with a special menu.","zh":"这家餐厅有专门的菜单满足素食者的需求。"}]},{"phrase":"live under the delusion that","usage":"抱有…的错觉，误以为","examples":[{"en":"He lives under the delusion that he can win the game without practice.","zh":"他误以为不用练习就能赢得比赛。"}]},{"phrase":"call in","usage":"请来，叫（专业人士）来帮忙","examples":[{"en":"We had to call in a plumber to fix the blocked pipe.","zh":"我们不得不请水管工来修堵塞的管道。"}]},{"phrase":"would not hear of","usage":"不同意，不接受","examples":[{"en":"My mother would not hear of me walking home alone at night.","zh":"我妈妈不同意我晚上独自走路回家。"}]},{"phrase":"be littered with","usage":"散落着，堆满了","examples":[{"en":"The floor was littered with toy bricks after the kids played.","zh":"孩子们玩过之后，地板上散落着积木。"}]},{"phrase":"needless to say","usage":"不用说，显然","examples":[{"en":"Needless to say, the concert was canceled because of the bad weather.","zh":"不用说，演唱会因为恶劣天气取消了。"}]}],"grammar":[{"title":"so...that...引导的倒装句","definition":"当so+形容词/副词位于句首表示强调时，句子需要部分倒装，用来加强语气","structure":"So + adj./adv. + be动词/助动词/情态动词 + 主语 + that + 结果状语从句","usage":"用于强调形容词或副词所描述的程度，引出后面的结果","examples":[{"en":"So great is our passion for doing things for ourselves, that we are becoming increasingly less dependent on specialized labour.","zh":"我们自己动手的热情是如此高涨，以至于我们越来越不依赖专业劳动力。"},{"en":"So fast did he run that no one could catch up with him.","zh":"他跑得太快了，没人能追上他。"}]},{"title":"虚拟语气在suggest后的宾语从句中的用法","definition":"当suggest表示“建议”时，后面的宾语从句需要用虚拟语气，即谓语动词为should+动词原形，should可以省略","structure":"主语 + suggest + that + 主语 + (should) + 动词原形 + 其他","usage":"用于表达建议、要求、命令等含义的动词后的宾语从句中","examples":[{"en":"Last spring my wife suggested that I call in a man to look at our lawn mower.","zh":"去年春天，我妻子建议我请个人来看看我们的割草机。"},{"en":"The teacher suggested that we (should) finish the project before Friday.","zh":"老师建议我们在周五之前完成这个项目。"}]}],"patterns":[{"pattern":"Some...go so far as to...","explanation":"","original":{"en":"Some really keen enthusiasts go so far as to build their own computers.","zh":"一些真正热衷的人甚至自己组装电脑。"},"examples":[{"en":"Some pet owners go so far as to buy expensive clothes for their cats.","zh":"一些宠物主人甚至给他们的猫买昂贵的衣服。"},{"en":"Some students go so far as to stay up all night to prepare for the exam.","zh":"一些学生甚至通宵复习准备考试。"}]},{"pattern":"The worst thing about...is that...","explanation":"","original":{"en":"The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything.","zh":"自己动手最糟糕的一点是，有时候就连男人们也会误以为自己什么都能做。"},"examples":[{"en":"The worst thing about travelling alone is that you have no one to share the beautiful scenery with.","zh":"独自旅行最糟糕的一点是，你没有人可以分享美丽的风景。"},{"en":"The worst thing about forgetting your phone is that you can't contact anyone when you need help.","zh":"忘带手机最糟糕的一点是，你需要帮助的时候联系不上任何人。"}]},{"pattern":"As far as I could see, it needed only...","explanation":"","original":{"en":"As far as I could see, it needed only a minor adjustment: a turn of a screw here, a little tightening up there, a drop of oil and it would be as good as new.","zh":"在我看来，它只需要一点小小的调整：这里拧一下螺丝，那里紧一紧，滴点油，就会跟新的一样了。"},"examples":[{"en":"As far as I could see, the cake needed only a little more cream on top to be perfect.","zh":"在我看来，这个蛋糕只需要在顶部多加一点奶油就完美了。"},{"en":"As far as I could see, the plan needed only a few small changes to be workable.","zh":"在我看来，这个计划只需要几处小改动就可行了。"}]},{"pattern":"When..., I told her that either...or...","explanation":"","original":{"en":"When my wife nagged me to do something about it, I told her that either I would have to buy a new mower or let the grass grow.","zh":"当我妻子催我想想办法的时候，我告诉她要么我买个新的割草机，要么就让草继续长。"},"examples":[{"en":"When my friend asked where to have dinner, I told her that either we can eat at the new restaurant nearby or order takeout.","zh":"当我朋友问去哪里吃晚饭的时候，我告诉她要么我们去附近的新餐厅吃，要么点外卖。"},{"en":"When the teacher asked about our weekend plan, I said that either we would visit the museum or go hiking.","zh":"当老师问起我们的周末计划时，我说我们要么去参观博物馆，要么去远足。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“拆卸，拆开” 对应的单词是？","hint":"verb · /dɪsˈmæntəl/","options":["universal","dismantle","conscientious","precaution"],"answer":1,"explain":"dismantle · /dɪsˈmæntəl/ · verb · 拆卸，拆开。指把机器、结构等拆成多个部件","source":{"kind":"vocab","word":"dismantle"},"id":"b3-u46-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：足智多谋的，办法多的","hint":"/rɪˈsɔːsfəl/ · adjective","answer":"resourceful","placeholder":"输入英文单词","explain":"resourceful · /rɪˈsɔːsfəl/ · adjective · 足智多谋的，办法多的。用来形容人善于应对各种困难","source":{"kind":"vocab","word":"resourceful"},"id":"b3-u46-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：We had to _____ a plumber to fix the blocked pipe.","hint":"我们不得不请水管工来修堵塞的管道。","answer":"call in","placeholder":"输入缺失的短语","explain":"call in：请来，叫（专业人士）来帮忙（我们不得不请水管工来修堵塞的管道。）","source":{"kind":"phrase","phrase":"call in"},"id":"b3-u46-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do _____","hint":"自己动手游戏的糟糕之处在于，有时连男人也活在自己无所不能的错觉中，","answer":"anything","placeholder":"输入缺失的单词","explain":"The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything, — 自己动手游戏的糟糕之处在于，有时连男人也活在自己无所不能的错觉中，","source":{"kind":"sentence","en":"The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything,"},"id":"b3-u46-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“当so+形容词/副词位于句首表示强调时，句子需要部分倒装，用来加强语气” 描述的是哪个语法点？","hint":"So + adj./adv. + be动词/助动词/情态动词 + 主语 + that + 结果状语从句","options":["虚拟语气在suggest后的宾语从句中的用法","so...that...引导的倒装句","It seems that 主语从句结构","非限定性定语从句"],"answer":1,"explain":"so...that...引导的倒装句：So + adj./adv. + be动词/助动词/情态动词 + 主语 + that + 结果状语从句：用于强调形容词或副词所描述的程度，引出后面的结果","source":{"kind":"grammar","title":"so...that...引导的倒装句"},"id":"b3-u46-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\neven when they have repeatedly been proved wrong.","hint":"","options":["我问一位乘客这是否是韦斯特黑文特快，但他甚至没有听说过。","即使他们一再被证明是错的。","在凌晨4点15分进行了一次短程试飞后，布莱里奥在半小时后出发了。","似乎她肯定会是第一艘抵达的船，"],"answer":1,"explain":"even when they have repeatedly been proved wrong. — 即使他们一再被证明是错的。","source":{"kind":"sentence","en":"even when they have repeatedly been proved wrong."},"id":"b3-u46-q06"}]},{"id":"b3-u47","book":3,"unit":47,"key":"47","lessonFrom":47,"lessonTo":47,"title":"Too High a Price","titleZh":"代价太高了吗？","question":"What does the writer describe as an 'amusing old-fashioned source of noise' ?","sentences":[{"en":"Pollution is the price we pay for an overpopulated, overindustrialized planet.","zh":"污染是人口过剩、过度工业化的地球所付出的代价。","t":18.65},{"en":"When you come to think about it, there are only four ways you can deal with rubbish:","zh":"仔细想想，处理垃圾只有四种方法：","t":25.49},{"en":"dump it, burn it, turn it into something you can use again, attempt to produce less of it.","zh":"倾倒、焚烧、回收利用，或者试图减少垃圾产量。","t":30.76},{"en":"We keep trying all four methods, but the sheer volume of rubbish we produce worldwide threatens to overwhelm us.","zh":"我们一直在尝试这四种方法，但全球垃圾的巨大产量正威胁着要将我们淹没。","t":37.73},{"en":"Rubbish, however, is only part of the problem of polluting our planet.","zh":"然而，垃圾只是污染地球问题的一部分。","t":48.1},{"en":"The need to produce ever increasing quantities of cheap food leads to a different kind of pollution.","zh":"生产日益增长的廉价食物的需求导致了另一种污染。","t":53.5},{"en":"Industrialized farming methods produce cheap meat products: beef, pork and chicken.","zh":"工业化农业方法生产廉价肉类产品：牛肉、猪肉和鸡肉。","t":60.99},{"en":"The use of pesticides and fertilizers produces cheap grain and vegetables.","zh":"杀虫剂和化肥的使用生产廉价谷物和蔬菜。","t":68.21},{"en":"The price we pay for cheap food may be already too high:","zh":"我们为廉价食物付出的代价可能已经太高了：","t":74.44},{"en":"Mad Cow Disease (BSE) in cattle, salmonella in chicken and eggs, and listeria in dairy products.","zh":"牛身上的疯牛病（BSE），鸡肉和鸡蛋中的沙门氏菌，以及奶制品中的李斯特菌。","t":79.63},{"en":"And if you think you'll abandon meat and become a vegetarian,","zh":"如果你认为你会放弃肉类成为素食者，","t":89.65},{"en":"you have the choice of very expensive organically-grown vegetables","zh":"你可以选择非常昂贵的有机蔬菜，","t":93.86},{"en":"or a steady diet of pesticides every time you think you're eating fresh salads and vegetables,","zh":"或者每次你以为在吃新鲜沙拉和蔬菜时，都伴随着大量的农药，","t":98.89},{"en":"or just having an innocent glass of water!","zh":"或者仅仅是喝一杯纯净的水！","t":105.59},{"en":"However, there is an even more insidious kind of pollution that particularly affects urban area and invades our daily lives, and that is noise.","zh":"然而，还有一种更阴险的污染，它尤其影响城市地区并侵入我们的日常生活，那就是噪音。","t":109.6},{"en":"Burglar alarms going off at any time of the day or night serve only to annoy passers-by and actually assist burglars to burgle.","zh":"昼夜不停响起的防盗警报只会惹恼路人，并实际上帮助窃贼入室盗窃。","t":122.48},{"en":"Car alarms constantly scream at us in the street and are a source of profound irritation.","zh":"汽车警报在街上不断对我们尖叫，是极度恼人的来源。","t":133.1},{"en":"A recent survey of the effects of noise revealed (surprisingly?)","zh":"最近一项关于噪音影响的调查显示（令人惊讶的是？）","t":140.09},{"en":"that dogs barking incessantly in the night rated the highest form of noise pollution on a scale ranging from 1 to 7.","zh":"狗在夜间不停吠叫被评为1到7级噪音污染中最高的形式。","t":145.37},{"en":"The survey revealed a large number of sources of noise that we really dislike.","zh":"该调查揭示了许多我们真正不喜欢的噪音来源。","t":155.37},{"en":"Lawn mowers whining on a summer's day, late-night parties in apartment blocks,","zh":"夏日里割草机的嗡嗡声，公寓楼里的深夜派对，","t":161.79},{"en":"noisy neighbours, vehicles of all kinds,","zh":"吵闹的邻居，各种车辆，","t":167.97},{"en":"especially large container trucks thundering through quiet villages,","zh":"特别是大型集装箱卡车轰隆隆地穿过宁静的村庄，","t":171.51},{"en":"planes and helicopters flying overhead, large radios carried round in public places and played at maximum volume.","zh":"飞机和直升机从头顶飞过，公共场所里大声播放的收音机。","t":176.23},{"en":"New technology has also made its own contribution to noise.","zh":"新技术也对噪音有所“贡献”。","t":186.3},{"en":"A lot of people object to mobile phones, especially when they are used in public places like restaurants or on public transport.","zh":"很多人反对手机，尤其是在餐馆或公共交通工具等公共场所使用手机。","t":191.44},{"en":"Loud conversations on mobile phones invade our thoughts or interrupt the pleasure of meeting friends for a quiet chat.","zh":"手机上的大声对话侵扰我们的思绪，或者打断我们与朋友安静聊天的乐趣。","t":201.69},{"en":"The noise pollution survey revealed a rather surprising and possibly amusing old-fashioned source of noise.","zh":"噪音污染调查揭示了一个相当令人惊讶且可能有趣的、老式的噪音来源。","t":211.17},{"en":"It turned out to be snoring! Men were found to be the worst offenders.","zh":"结果是打鼾！男性被发现是最大的“罪魁祸首”。","t":219.9},{"en":"It was revealed that 20% of men in their mid-thirties snore.","zh":"调查显示，20%的三十多岁男性会打鼾。","t":226.22},{"en":"This figure rises to a staggering 60% of men in their sixties.","zh":"这个数字在六十多岁男性中飙升至惊人的60%。","t":232.06},{"en":"Against these figures, it was found that only 5% of women snore regularly,","zh":"与这些数字相比，只有5%的女性会规律性打鼾，","t":238.26},{"en":"while the rest are constantly woken or kept awake by their trumpeting partners.","zh":"而其余的女性则不断地被她们打鼾的伴侣吵醒或保持清醒。","t":244.52},{"en":"Whatever the source of noise, one thing is certain: silence, it seems, has become a golden memory.","zh":"无论噪音来源是什么，有一件事是肯定的：宁静，似乎已成为一段美好的回忆。","t":251.34}],"vocab":[{"word":"pollution","phonetic":"/pəˈluːʃən/","meanings":[{"pos":"noun","meaning":"污染，玷污","usage":"指对环境的损害，如空气、水、噪音污染"}]},{"word":"overindustrialized","phonetic":"/ˌəʊvərɪnˈdʌstriəlaɪzd/","meanings":[{"pos":"adjective","meaning":"过度工业化的","usage":"描述工业发展过度的状态"}]},{"word":"overwhelm","phonetic":"/ˌəʊvəˈwelm/","meanings":[{"pos":"verb","meaning":"压倒，使应接不暇","usage":"表示数量或力量大到无法处理"}]},{"word":"pesticide","phonetic":"/ˈpestɪsaɪd/","meanings":[{"pos":"noun","meaning":"杀虫剂，农药","usage":"用于消灭害虫的化学物质"}]},{"word":"fertilizer","phonetic":"/ˈfɜːtɪlaɪzə/","meanings":[{"pos":"noun","meaning":"肥料，化肥","usage":"促进植物生长的物质"}]},{"word":"insidious","phonetic":"/ɪnˈsɪdiəs/","meanings":[{"pos":"adjective","meaning":"阴险的，狡诈的；暗中为害的","usage":"形容危险或问题不易察觉但逐渐扩散"}]},{"word":"urban","phonetic":"/ˈɜːbən/","meanings":[{"pos":"adjective","meaning":"城市的，城镇的","usage":"与城市相关的，反义词为rural（农村的）"}]},{"word":"profound","phonetic":"/prəˈfaʊnd/","meanings":[{"pos":"adjective","meaning":"深刻的，极度的","usage":"程度很深，强烈的"}]},{"word":"irritation","phonetic":"/ˌɪrɪˈteɪʃən/","meanings":[{"pos":"noun","meaning":"恼怒，烦躁","usage":"被某事激怒的感觉"}]},{"word":"incessantly","phonetic":"/ɪnˈsesəntli/","meanings":[{"pos":"adverb","meaning":"不停地，持续不断地","usage":"强调动作或状态的持续性"}]},{"word":"snore","phonetic":"/snɔː/","meanings":[{"pos":"verb/noun","meaning":"打鼾，打呼噜","usage":"睡眠时发出的呼吸声"}]},{"word":"offender","phonetic":"/əˈfendə/","meanings":[{"pos":"noun","meaning":"违规者，冒犯者","usage":"做错事或违反规则的人"}]},{"word":"abandon","phonetic":"/əˈbændən/","meanings":[{"pos":"verb","meaning":"放弃，抛弃","usage":"放弃某种习惯、信仰或地方"}]},{"word":"staggering","phonetic":"/ˈstæɡərɪŋ/","meanings":[{"pos":"adjective","meaning":"令人震惊的，踉跄的","usage":"形容数量或程度令人难以置信"}]},{"word":"overhead","phonetic":"/ˈəʊvəhed/","meanings":[{"pos":"adjective/adverb","meaning":"在头顶上空的","usage":"指位于头顶上方的东西"}]}],"phrases":[{"phrase":"when you come to think about it","usage":"固定表达，意思是'当你仔细想想'，用于引出思考后的结论","examples":[{"en":"When you come to think about it, there are only four ways to deal with rubbish.","zh":"当你仔细想想，垃圾处理只有四种方式。"}]},{"phrase":"lead to","usage":"动词短语，表示'导致'，后接结果或后果","examples":[{"en":"The need to produce cheap food leads to a different kind of pollution.","zh":"生产廉价食品的需求导致了另一种污染。"}]},{"phrase":"at any time of the day or night","usage":"固定短语，意思是'无论白天还是黑夜'，强调随时都可能发生","examples":[{"en":"Burglar alarms going off at any time of the day or night annoy passers-by.","zh":"无论白天还是黑夜响起防盗警报都会惹恼路人。"}]},{"phrase":"make contribution to","usage":"动词短语，表示'对...做出贡献'，to为介词","examples":[{"en":"New technology has made its own contribution to noise.","zh":"新技术也对噪音做出了'贡献'。"}]},{"phrase":"on a scale ranging from...to...","usage":"固定表达，表示'在从...到...的范围内'，用于描述测量范围","examples":[{"en":"Noise pollution was rated on a scale ranging from 1 to 7.","zh":"噪音污染按1到7的等级进行评分。"}]},{"phrase":"a steady diet of","usage":"短语，表示'长期大量的某物'，常指频繁接触某事物","examples":[{"en":"You may have a steady diet of pesticides every time you eat vegetables.","zh":"每次吃蔬菜时你可能都在大量摄入农药。"}]},{"phrase":"keep doing something","usage":"动词短语，表示'继续做某事'，强调动作的持续性","examples":[{"en":"We keep trying all four methods, but the volume threatens to overwhelm us.","zh":"我们不断尝试这四种方法，但垃圾量之大让我们难以应对。"}]},{"phrase":"it seems","usage":"固定表达，表示'似乎，看来'，用于表达推测","examples":[{"en":"Silence, it seems, has become a golden memory.","zh":"看来，静谧已经成为了一段黄金记忆。"}]},{"phrase":"have the choice of","usage":"动词短语，表示'有...的选择'，后面接选择的内容","examples":[{"en":"You have the choice of very expensive organically-grown vegetables.","zh":"你可以选择非常昂贵的有机蔬菜。"}]},{"phrase":"think you'll abandon","usage":"think + that从句的用法，表示'认为你会放弃'","examples":[{"en":"And if you think you'll abandon meat and become a vegetarian...","zh":"如果你认为自己会放弃肉类成为素食者..."}]}],"grammar":[{"title":"定语从句（使用that/which/who）","definition":"定语从句用于修饰名词或代词，由关系代词（that, which, who, whom）或关系副词（where, when, why）引导，置于被修饰词之后。","structure":"主句 + 名词/代词 + 关系词 + 定语从句","usage":"用于提供关于名词的额外信息，使句子更加完整和精确。在本课中，多处使用了that/which引导的定语从句。","examples":[{"en":"The survey that/which revealed these findings was conducted recently.","zh":"揭示这些发现的调查是最近进行的。"},{"en":"Dogs barking incessantly in the night was rated as the highest form of noise pollution.","zh":"夜间不断吠叫的狗被评为最高形式的噪音污染。"},{"en":"New technology that has made its own contribution to noise is a concern.","zh":"对噪音做出'贡献'的新技术令人担忧。"}]},{"title":"副词的位置和作用","definition":"副词在句中可以位于句首、句中或句尾，用来修饰动词、形容词或其他副词，表示时间、方式、程度、频率等。","structure":"副词 + 动词 / 动词 + 副词 / 主语 + 副词 + 动词","usage":"在本课中，insidiously, constantly, incessantly等副词描述了污染的持续性和隐藏性特点，帮助读者理解问题的严重程度。","examples":[{"en":"There is an even more insidious kind of pollution that particularly affects urban areas.","zh":"有一种更为隐蔽的污染，特别影响城市地区。"},{"en":"Car alarms constantly scream at us in the street.","zh":"汽车警报在街上不断对我们尖叫。"},{"en":"Dogs barking incessantly in the night rated the highest form of noise pollution.","zh":"夜间持续吠叫的狗被评为最高形式的噪音污染。"}]},{"title":"百分数表达在描述数据中的应用","definition":"使用百分数（percent/percentage）来描述统计数据，是学术和新闻写作中的常见表达方式。","structure":"数字 + % + of + 名词 + 谓语","usage":"在描述调查结果、人口数据或比例时使用。本课中多处使用百分比来说明打鼾问题的普遍性。","examples":[{"en":"20% of men in their mid-thirties snore.","zh":"处于三十五岁左右的男人中有20%打鼾。"},{"en":"This figure rises to a staggering 60% of men in their sixties.","zh":"这个数字攀升到六十岁男人的惊人60%。"},{"en":"Only 5% of women snore regularly.","zh":"只有5%的女性经常打鼾。"}]}],"patterns":[{"pattern":"...is the price we pay for...","explanation":"","original":{"en":"Pollution is the price we pay for an overpopulated, overindustrialized planet.","zh":"污染是我们为这个人口过剩、工业过度发展的星球所付出的代价。"},"examples":[{"en":"Traffic jams are the price we pay for modernization.","zh":"交通拥堵是我们为现代化付出的代价。"},{"en":"Stress is the price we pay for a competitive society.","zh":"压力是我们为竞争社会付出的代价。"}]},{"pattern":"There are only + 数字 + ways you can...","explanation":"","original":{"en":"There are only four ways you can deal with rubbish.","zh":"处理垃圾只有四种方式。"},"examples":[{"en":"There are only three ways you can solve this problem.","zh":"解决这个问题只有三种方法。"},{"en":"There are only two choices you can make now.","zh":"你现在只有两个选择。"}]},{"pattern":"The price we pay for...may be already too high","explanation":"","original":{"en":"The price we pay for cheap food may be already too high.","zh":"我们为廉价食品付出的代价可能已经太高了。"},"examples":[{"en":"The price we pay for convenience may be already too high.","zh":"我们为便利付出的代价可能已经太高了。"},{"en":"The price we pay for fast delivery may be already too high.","zh":"我们为快递付出的代价可能已经太高了。"}]},{"pattern":"It turned out to be + 名词/动名词","explanation":"","original":{"en":"It turned out to be snoring!","zh":"原来是打鼾！"},"examples":[{"en":"The mysterious noise turned out to be a cat.","zh":"那个神秘的噪音原来是一只猫。"},{"en":"The solution turned out to be much simpler than expected.","zh":"解决办法原来比预期的简单得多。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“深刻的，极度的” 对应的单词是？","hint":"adjective · /prəˈfaʊnd/","options":["tolerant","profound","hand over","sacrifice"],"answer":1,"explain":"profound · /prəˈfaʊnd/ · adjective · 深刻的，极度的。程度很深，强烈的","source":{"kind":"vocab","word":"profound"},"id":"b3-u47-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：城市的，城镇的","hint":"/ˈɜːbən/ · adjective","answer":"urban","placeholder":"输入英文单词","explain":"urban · /ˈɜːbən/ · adjective · 城市的，城镇的。与城市相关的，反义词为rural（农村的）","source":{"kind":"vocab","word":"urban"},"id":"b3-u47-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：You _____ very expensive organically-grown vegetables.","hint":"你可以选择非常昂贵的有机蔬菜。","answer":"have the choice of","placeholder":"输入缺失的短语","explain":"have the choice of：动词短语，表示'有...的选择'，后面接选择的内容（你可以选择非常昂贵的有机蔬菜。）","source":{"kind":"phrase","phrase":"have the choice of"},"id":"b3-u47-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：The noise pollution survey revealed a rather surprising and possibly amusing old-fashioned _____ of noise.","hint":"噪音污染调查揭示了一个相当令人惊讶且可能有趣的、老式的噪音来源。","answer":"source","placeholder":"输入缺失的单词","explain":"The noise pollution survey revealed a rather surprising and possibly amusing old-fashioned source of noise. — 噪音污染调查揭示了一个相当令人惊讶且可能有趣的、老式的噪音来源。","source":{"kind":"sentence","en":"The noise pollution survey revealed a rather surprising and possibly amusing old-fashioned source of noise."},"id":"b3-u47-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“使用百分数（percent/percentage）来描述统计数据，是学术和新闻写作中的常见表达方式。” 描述的是哪个语法点？","hint":"数字 + % + of + 名词 + 谓语","options":["百分数表达在描述数据中的应用","宾语从句（Object Clause）","过去完成时的被动语态","现在分词作原因状语"],"answer":0,"explain":"百分数表达在描述数据中的应用：数字 + % + of + 名词 + 谓语：在描述调查结果、人口数据或比例时使用。本课中多处使用百分比来说明打鼾问题的普遍性。","source":{"kind":"grammar","title":"百分数表达在描述数据中的应用"},"id":"b3-u47-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nplanes and helicopters flying overhead, large radios carried round in public places and played at maximum volume.","hint":"","options":["哈里接着解释说，“美妙来特”是一种硬的、琥珀状物质，可以用来消除雀斑。","果不其然，拉斯特斯那天晚上7点准时回来了。","一位一直对每个人都非常和蔼可亲的老太太，在年轻时毒死了她的五个丈夫时，会毛骨悚然。","飞机和直升机从头顶飞过，公共场所里大声播放的收音机。"],"answer":3,"explain":"planes and helicopters flying overhead, large radios carried round in public places and played at maximum volume. — 飞机和直升机从头顶飞过，公共场所里大声播放的收音机。","source":{"kind":"sentence","en":"planes and helicopters flying overhead, large radios carried round in public places and played at maximum volume."},"id":"b3-u47-q06"}]},{"id":"b3-u48","book":3,"unit":48,"key":"48","lessonFrom":48,"lessonTo":48,"title":"The Silent Village","titleZh":"寂静的村庄","question":"Why was the village silent?","sentences":[{"en":"In this much-travelled world, there are still thousands of places which are inaccessible to tourists.","zh":"在这个人们频繁往来的世界上，仍然有成千上万个旅游者望而却步的地方。","t":14.61},{"en":"We always assume that villagers in remote places are friendly and hospitable.","zh":"我们总是认为，住在偏远地方的村民是友好而殷勤好客的。","t":23.07},{"en":"But people who are cut off not only from foreign tourists, but even from their own countrymen can be hostile to travellers.","zh":"但是，那些不仅与外国旅游者隔绝，甚至与本国同胞也隔绝的人们，却可能对旅游者怀有敌意。","t":29.74},{"en":"Visits to really remote villages are seldom enjoyable--as my wife and I discovered during a tour through the Balkans.","zh":"访问真正偏僻的村庄，很少有什么乐趣可言——我和我妻子在巴尔干半岛旅行时就发现了这一点。","t":40.02},{"en":"We had spent several days in a small town and visited a number of old churches in the vicinity.","zh":"我们在一个小镇上呆了几天，参观了附近的一些古老的教堂。","t":48.81},{"en":"These attracted many visitors, for they were not only of great architectural interest, but contained a large number of beautifully preserved frescoes as well.","zh":"这些教堂吸引了许多旅游者，因为它们不仅有很高的建筑价值，而且还保存了大量的制作精美的壁画。","t":56.13},{"en":"On the day before our departure, several bus loads of tourists descended on the town.","zh":"在我们动身的前一天，好几车游客涌入了小镇。","t":67.95},{"en":"This was more than we could bear, so we decided to spend our last day exploring the countryside.","zh":"这太让我们受不了了，于是我们决定最后一天到乡下去。","t":74.5},{"en":"Taking a path which led out of the town, we crossed a few fields until we came to a dense wood.","zh":"我们沿着一条从小镇延伸出去的小路，穿过几片田地，来到一片茂密的树林。","t":82.86},{"en":"We expected the path to end abruptly, but we found that it traced its way through the trees.","zh":"我们本以为小路会突然中断，不料它却在树林中蜿蜒而行。","t":90.38},{"en":"We tramped through the wood for over two hours until we arrived at a deep stream.","zh":"我们在树林里跋涉了两个多小时，来到一条很深的溪流前。","t":98.22},{"en":"We could see that the path continued on the other side, but we had no idea how we could get across the stream.","zh":"我们看到小路在对岸延伸，但不知道怎样才能穿过溪流。","t":104.54},{"en":"Suddenly my wife spotted a boat moored to the bank.","zh":"突然，我妻子发现了一条系在岸边的船。","t":113.5},{"en":"In it there was a boatman fast asleep.","zh":"船上有一个船夫，睡得很熟。","t":117.76},{"en":"We gently woke him up and asked him to ferry us to the other side.","zh":"我们轻轻地把他叫醒，请他把我们摆渡到对岸。","t":121.38},{"en":"Though he was reluctant to do so at first, we eventually persuaded him to take us.","zh":"虽然他开始不情愿，但我们最终说服他带我们过去了。","t":126.67},{"en":"The path led to a tiny village perched on the steep sides of a mountain.","zh":"小路通向一个坐落在陡峭山腰上的小村庄。","t":133.23},{"en":"The place consisted of a straggling unmade road which was lined on either side by small houses.","zh":"这个地方只有一条弯弯曲曲的土路，两旁是些小房子。","t":139.39},{"en":"Even under a clear blue sky, the village looked forbidding, as all the houses were built of grey mud bricks.","zh":"即使在晴朗的蓝天下，这个村庄看上去也令人望而生畏，因为所有的房子都是用灰色土坯建造的。","t":146.93},{"en":"The village seemed deserted,","zh":"村庄似乎空无一人，","t":156.09},{"en":"the only sign of life being an ugly-looking black goat on a short length of rope tied to a tree in a field nearby.","zh":"唯一的生命迹象是在附近的一块田地里，有一只拴在树上的黑山羊，它被短绳系着，面目丑陋。","t":158.49},{"en":"Sitting down on a dilapidated wooden fence near the field, we opened a couple of tins of sardines and had a picnic lunch.","zh":"我们在田边一处破旧的木栅栏旁坐了下来，打开了两罐沙丁鱼罐头，吃起了野餐。","t":169.12},{"en":"All at once, I noticed that my wife seemed to be filled with alarm.","zh":"突然，我注意到我妻子好像惊恐万状。","t":178.85},{"en":"Looking up I saw that we were surrounded by children in rags who were looking at us silently as we ate.","zh":"我抬起头，看到我们已经被一群衣衫褴褛的孩子围住了，他们一言不发地看着我们吃东西。","t":184.72},{"en":"We offered them food and spoke to them kindly, but they remained motionless.","zh":"我们给他们食物，和善地对他们说话，但他们仍然一动不动。","t":193.3},{"en":"I concluded that they were simply shy of strangers.","zh":"我断定他们只是害羞，不愿见陌生人。","t":199.93},{"en":"When we later walked down the main street of the village, we were followed by a silent procession of children.","zh":"后来我们沿着村里的主要街道走去，一群默默无声的孩子跟在我们后面。","t":204.12},{"en":"The village which had seemed deserted, immediately came to life.","zh":"这个村庄，本来似乎空无一人，立刻变得活跃起来。","t":212.46},{"en":"Faces appeared at windows.","zh":"窗户里出现了脸庞。","t":218.24},{"en":"Men in shirt sleeves stood outside their houses and glared at us.","zh":"穿着衬衫的男人站在屋外，怒视着我们。","t":220.4},{"en":"Old women in black shawls peered at us from doorways.","zh":"披着黑色披肩的老妇人从门道里窥视着我们。","t":225.78},{"en":"The most frightening thing of all was that not a sound could be heard.","zh":"最令人恐惧的是，一点声音都听不到。","t":230.73},{"en":"There was no doubt that we were unwelcome visitors.","zh":"毫无疑问，我们是不受欢迎的客人。","t":236.64},{"en":"We needed no further warning.","zh":"我们不再需要更多的警告了。","t":241.54},{"en":"Turning back down the main street,","zh":"我们转身沿着主要街道往回走，","t":244.25},{"en":"we quickened our pace and made our way rapidly towards the stream where we hoped the boatman was waiting.","zh":"加快了脚步，迅速朝小溪走去，我们希望船夫还在那里等着。","t":246.6}],"vocab":[{"word":"inaccessible","phonetic":"/ˌɪnækˈsesəbl/","meanings":[{"pos":"adjective","meaning":"难到达的，不可及的","usage":"常与介词to搭配，表示“对某人来说难以到达/获取”"}]},{"word":"hospitable","phonetic":"/hɒˈspɪtəbl/","meanings":[{"pos":"adjective","meaning":"好客的，热情友好的","usage":"可用来形容人、地方或风俗，常与介词to搭配"}]},{"word":"hostile","phonetic":"/ˈhɒstaɪl/","meanings":[{"pos":"adjective","meaning":"敌对的，不友善的","usage":"常与介词to/towards搭配，表示“对……怀有敌意”"}]},{"word":"vicinity","phonetic":"/vəˈsɪnəti/","meanings":[{"pos":"noun","meaning":"周围地区，邻近区域","usage":"常用搭配in the vicinity (of) 表示“在（……的）附近”"}]},{"word":"fresco","phonetic":"/ˈfreskəʊ/","meanings":[{"pos":"noun","meaning":"壁画","usage":"复数形式可加s或为frescoes"}]},{"word":"descend","phonetic":"/dɪˈsend/","meanings":[{"pos":"verb","meaning":"突然大批来到，降临","usage":"常与介词on/upon搭配，指大量人突然涌入某个地方"}]},{"word":"tramp","phonetic":"/træmp/","meanings":[{"pos":"verb","meaning":"长途跋涉，徒步走","usage":"指长时间费力地步行，常接表示地点的介词短语"}]},{"word":"ferry","phonetic":"/ˈferi/","meanings":[{"pos":"verb","meaning":"渡运，摆渡","usage":"指用船将人、货物运到河或海峡的对岸，常用搭配ferry sb/sth across sth"}]},{"word":"perch","phonetic":"/pɜːtʃ/","meanings":[{"pos":"verb","meaning":"位于（高处），坐落","usage":"常用被动形式be perched on/upon，指建筑物位于高处或边缘位置"}]},{"word":"straggling","phonetic":"/ˈstræɡlɪŋ/","meanings":[{"pos":"adjective","meaning":"散乱的，蔓延的","usage":"用来形容道路、村落等分布零散、不整齐的状态"}]},{"word":"forbidding","phonetic":"/fəˈbɪdɪŋ/","meanings":[{"pos":"adjective","meaning":"令人生畏的，险恶的","usage":"形容地方、外表等看起来吓人、不友好"}]},{"word":"dilapidated","phonetic":"/dɪˈlæpɪdeɪtɪd/","meanings":[{"pos":"adjective","meaning":"破烂不堪的，年久失修的","usage":"用来形容建筑物、家具等因缺乏维护而破旧的状态"}]},{"word":"procession","phonetic":"/prəˈseʃn/","meanings":[{"pos":"noun","meaning":"（人或车辆的）队列，行列","usage":"指人或物排成的长队，a procession of 表示“一队……”"}]},{"word":"glare","phonetic":"/ɡleə(r)/","meanings":[{"pos":"verb","meaning":"怒目而视，瞪眼","usage":"常与介词at搭配，表示愤怒地盯着某人看"}]},{"word":"peer","phonetic":"/pɪə(r)/","meanings":[{"pos":"verb","meaning":"仔细看，费力地看","usage":"常与介词at/through/into搭配，指因看不清而仔细凝视"}]}],"phrases":[{"phrase":"cut off from","usage":"表示“与……隔绝，切断与……的联系”，被动形式be cut off from更常用","examples":[{"en":"The small village is cut off from the outside world in winter due to heavy snow.","zh":"冬天大雪封山，这个小村庄与外界隔绝了。"}]},{"phrase":"in the vicinity","usage":"表示“在附近，在邻近地区”，后可接of+具体地点说明范围","examples":[{"en":"There are several famous scenic spots in the vicinity of the hotel.","zh":"酒店附近有好几处著名景点。"}]},{"phrase":"descend on","usage":"指“（大量人）突然到访，涌入”，带有出人意料、给当地带来压力的含义","examples":[{"en":"Every summer, crowds of tourists descend on this coastal town.","zh":"每年夏天，大批游客涌入这个海滨小镇。"}]},{"phrase":"have no idea","usage":"口语常用表达，意思是“不知道，不清楚”，后可接疑问词引导的从句","examples":[{"en":"I have no idea when he will come back from his business trip.","zh":"我不知道他什么时候出差回来。"}]},{"phrase":"fast asleep","usage":"表示“睡得很熟，酣睡”，是固定搭配，fast此处为副词，修饰asleep","examples":[{"en":"When I got home last night, my kids were already fast asleep in bed.","zh":"我昨晚到家的时候，孩子们已经在床上睡得很熟了。"}]},{"phrase":"be shy of","usage":"表示“害怕……，对……感到腼腆/迟疑”，后接名词或动名词","examples":[{"en":"Many children are shy of speaking in front of a large audience.","zh":"很多孩子都不好意思在很多人面前讲话。"}]},{"phrase":"come to life","usage":"表示“苏醒过来，恢复生机，变得活跃”，可用于描述人、地方或场景","examples":[{"en":"The quiet park comes to life at dawn when elderly people come to do exercise.","zh":"清晨老人们来锻炼的时候，安静的公园就变得热闹起来。"}]},{"phrase":"There is no doubt that...","usage":"固定句型，意思是“毫无疑问……”，that引导同位语从句说明doubt的内容","examples":[{"en":"There is no doubt that regular exercise is good for physical and mental health.","zh":"毫无疑问，规律锻炼对身心健康都有好处。"}]}],"grammar":[{"title":"独立主格结构","definition":"由名词/代词 + 非谓语动词/形容词/副词/介词短语构成，在句中作状语，说明时间、原因、条件、伴随情况等，其逻辑主语与主句主语不一致","structure":"名词/代词 + 现在分词/过去分词/形容词/副词/介词短语","usage":"多用于书面语，可使句子结构更紧凑，避免重复使用从句","examples":[{"en":"The village seemed deserted, the only sign of life being an ugly-looking black goat on a short length of rope tied to a tree in a field nearby.","zh":"村庄似乎已经废弃了，唯一的生命迹象是一头样子难看的黑山羊，用短绳拴在附近地里的一棵树上。"},{"en":"The meeting over, everyone went home tired but satisfied.","zh":"会议结束了，每个人都疲惫但满足地回家了。"}]},{"title":"as引导的非限制性定语从句","definition":"as可用来引导非限制性定语从句，指代整个主句的内容，可位于主句之前、之后或插入主句中间，常译为“正如……，正像……”","structure":"主句 + as + 定语从句 / As + 定语从句, 主句","usage":"常用于引出已发生的事实、大家已知的情况等，常见搭配有as we all know, as is expected, as is mentioned above等","examples":[{"en":"Visits to really remote villages are seldom enjoyable--as my wife and I discovered during a tour through the Balkans.","zh":"到真正偏僻的村庄去旅游很少是愉快的——我和妻子在巴尔干半岛旅行时就发现了这一点。"},{"en":"As is known to all, the earth moves around the sun.","zh":"众所周知，地球绕着太阳转。"}]}],"patterns":[{"pattern":"not only...but...as well","explanation":"","original":{"en":"These attracted many visitors, for they were not only of great architectural interest, but contained a large number of beautifully preserved frescoes as well.","zh":"这些教堂吸引了很多游客，因为它们不仅具有很高的建筑价值，而且还藏有大量保存完好的壁画。"},"examples":[{"en":"The book is very popular, for it is not only educational, but very interesting as well.","zh":"这本书很受欢迎，因为它不仅有教育意义，而且还非常有趣。"},{"en":"The new shopping mall is convenient, for it not only has a wide range of goods, but offers excellent customer service as well.","zh":"这个新购物中心很方便，因为它不仅商品种类齐全，而且还提供优质的客户服务。"}]},{"pattern":"We expected...but we found that...","explanation":"","original":{"en":"We expected the path to end abruptly, but we found that it traced its way through the trees.","zh":"我们原以为小路会突然到头，却发现它在树林中蜿蜒延伸。"},"examples":[{"en":"We expected the exam to be very difficult, but we found that it was much easier than we had imagined.","zh":"我们原以为考试会很难，却发现它比我们想象的容易得多。"},{"en":"We expected the restaurant to be crowded, but we found that there were still plenty of empty tables.","zh":"我们原以为这家餐厅会很拥挤，却发现还有很多空桌。"}]},{"pattern":"The most frightening/annoying/exciting thing of all was that...","explanation":"","original":{"en":"The most frightening thing of all was that not a sound could be heard.","zh":"最吓人的是，这里听不到一点声音。"},"examples":[{"en":"The most annoying thing of all was that he didn't even apologize for his mistake.","zh":"最气人的是，他甚至都没有为自己的错误道歉。"},{"en":"The most exciting thing of all was that our team won the first prize in the competition.","zh":"最令人激动的是，我们队在比赛中获得了一等奖。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“难到达的，不可及的” 对应的单词是？","hint":"adjective · /ˌɪnækˈsesəbl/","options":["inaccessible","dignity","poison","crockery"],"answer":0,"explain":"inaccessible · /ˌɪnækˈsesəbl/ · adjective · 难到达的，不可及的。常与介词to搭配，表示“对某人来说难以到达/获取”","source":{"kind":"vocab","word":"inaccessible"},"id":"b3-u48-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：长途跋涉，徒步走","hint":"/træmp/ · verb","answer":"tramp","placeholder":"输入英文单词","explain":"tramp · /træmp/ · verb · 长途跋涉，徒步走。指长时间费力地步行，常接表示地点的介词短语","source":{"kind":"vocab","word":"tramp"},"id":"b3-u48-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：There are several famous scenic spots _____ of the hotel.","hint":"酒店附近有好几处著名景点。","answer":"in the vicinity","placeholder":"输入缺失的短语","explain":"in the vicinity：表示“在附近，在邻近地区”，后可接of+具体地点说明范围（酒店附近有好几处著名景点。）","source":{"kind":"phrase","phrase":"in the vicinity"},"id":"b3-u48-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：On the day before our departure, _____ bus loads of tourists descended on the town.","hint":"在我们动身的前一天，好几车游客涌入了小镇。","answer":"several","placeholder":"输入缺失的单词","explain":"On the day before our departure, several bus loads of tourists descended on the town. — 在我们动身的前一天，好几车游客涌入了小镇。","source":{"kind":"sentence","en":"On the day before our departure, several bus loads of tourists descended on the town."},"id":"b3-u48-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“as可用来引导非限制性定语从句，指代整个主句的内容，可位于主句之前、之后或插入主句中间，常译为“正如……，正像……”” 描述的是哪个语法点？","hint":"主句 + as + 定语从句 / As + 定语从句, 主句","options":["as引导的非限制性定语从句","It seems that 主语从句结构","as if引导的虚拟语气","部分倒装 (Partial Inversion)"],"answer":0,"explain":"as引导的非限制性定语从句：主句 + as + 定语从句 / As + 定语从句, 主句：常用于引出已发生的事实、大家已知的情况等，常见搭配有as we all know, as is expected, as is mentioned above等","source":{"kind":"grammar","title":"as引导的非限制性定语从句"},"id":"b3-u48-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nIn it there was a boatman fast asleep.","hint":"","options":["这个人的官方头衔是“司法特派员”，但瑞典人通常称他为“J.O.”或“特派员”。","飞机有危险的名声，即使是经验丰富的旅行者也会被它们吓倒。","船上有一个船夫，睡得很熟。","在最后一幕中，一个狱卒总是会带着一封信上台，然后递给囚犯。"],"answer":2,"explain":"In it there was a boatman fast asleep. — 船上有一个船夫，睡得很熟。","source":{"kind":"sentence","en":"In it there was a boatman fast asleep."},"id":"b3-u48-q06"}]},{"id":"b3-u49","book":3,"unit":49,"key":"49","lessonFrom":49,"lessonTo":49,"title":"The Ideal Servant","titleZh":"理想的仆人","question":"What was Bessie's 'little weakness' ?","sentences":[{"en":"It is a good thing my aunt Harriet died years ago.","zh":"幸好我姑妈哈里特在多年前就去世了。","t":14.96},{"en":"If she were alive today she would not be able to air her views on her favourite topic of conversation: domestic servants.","zh":"如果她今天还活着，她就不能再对她最喜欢的话题——佣人——发表意见了。","t":18.97},{"en":"Aunt Harriet lived in that leisurely age when servants were employed to do housework.","zh":"哈里特姑妈生活在那个悠闲的时代，那时人们雇佣仆人来做家务。","t":29.25},{"en":"She had a huge, rambling country house called 'The Gables'.","zh":"她有一幢名叫“山墙”的巨大而凌乱的乡村别墅。","t":35.42},{"en":"She was sentimentally attached to this house,","zh":"她对这所房子感情深厚，","t":40.36},{"en":"for even though it was far too big for her needs, she persisted in living there long after her husband's death.","zh":"因为尽管它对她来说太大了，但在她丈夫去世后很久，她仍然坚持住在那里。","t":43.82},{"en":"Before she grew old, aunt Harriet used to entertain lavishly.","zh":"在她变老之前，哈里特姑妈经常大摆宴席。","t":52.82},{"en":"I often visited The Gables when I was a boy.","zh":"我小时候经常去“山墙”探望。","t":57.84},{"en":"No matter how many guests were present, the great house was always immaculate.","zh":"无论有多少客人，这幢大房子总是 immaculate（一尘不染的）。","t":61.45},{"en":"The parquet floors shone like mirrors;","zh":"镶木地板擦得像镜子一样亮；","t":67.62},{"en":"highly polished silver was displayed in gleaming glass cabinets;","zh":"擦得锃亮的银器摆放在闪闪发光的玻璃橱柜里；","t":70.94},{"en":"even my uncle's huge collection of books was kept miraculously free from dust.","zh":"甚至我叔叔那一大批藏书也奇迹般地没有沾上一点灰尘。","t":76.31},{"en":"Aunt Harriet presided over an invisible army of servants that continuously scrubbed, cleaned, and polished.","zh":"哈里特姑妈统管着一支无形的仆人队伍，他们不停地擦洗、清洁、打磨。","t":83.38},{"en":"She always referred to them as 'the shifting population',","zh":"她总是称他们为“流动人口”，","t":92.83},{"en":"for they came and went with such frequency that I never even got a chance to learn their names.","zh":"因为他们来去匆匆，我甚至都没机会记住他们的名字。","t":97.88},{"en":"Though my aunt pursued what was, in those days an enlightened policy,","zh":"尽管我姑妈在那时实行着一项开明的政策，","t":105.56},{"en":"in that she never allowed her domestic staff to work more than eight hours a day, she was extremely difficult to please.","zh":"即她从不允许她的家政人员每天工作超过八小时，但她还是非常难以取悦。","t":111.26},{"en":"While she always criticized the fickleness of human nature,","zh":"虽然她总是批评人性的反复无常，","t":120.28},{"en":"she carried on an unrelenting search for the ideal servant to the end of her days,","zh":"但她毕生都在不懈地寻找理想的仆人，","t":124.95},{"en":"even after she had been sadly disillusioned by Bessie.","zh":"即使在她被贝茜伤透了心之后也是如此。","t":132.1},{"en":"Bessie worked for aunt Harriet for three years.","zh":"贝茜为哈里特姑妈工作了三年。","t":137.29},{"en":"During that time she so gained my aunt's confidence, that she was put in charge of the domestic staff.","zh":"在此期间，她深得姑妈的信任，被任命为家政人员的负责人。","t":141.04},{"en":"Aunt Harriet could not find words to praise Bessie's industriousness and efficiency.","zh":"哈里特姑妈对贝茜的勤劳和效率赞不绝口。","t":149.03},{"en":"In addition to all her other qualifications, Bessie was an expert cook.","zh":"除了她所有的其他优点，贝茜还是一位烹饪专家。","t":156.05},{"en":"She acted the role of the perfect servant for three years before Aunt Harriet discovered her 'little weakness'.","zh":"她扮演了三年完美仆人的角色，直到哈里特姑妈发现了她的“小缺点”。","t":162.1},{"en":"After being absent from The Gables for a week,","zh":"在离开“山墙”一周后，","t":170.67},{"en":"my aunt unexpectedly returned one afternoon with a party of guests and instructed Bessie to prepare dinner.","zh":"姑妈在一个下午 unexpectedly（出乎意料地）带着一群客人回来了，并吩咐贝茜准备晚餐。","t":173.84},{"en":"Not only was the meal well below the usual standard, but Bessie seemed unable to walk steadily.","zh":"晚餐不仅远低于平时的水准，而且贝茜似乎无法稳稳地走路。","t":182.21},{"en":"She bumped into the furniture and kept mumbling about the guests.","zh":"她撞到了家具，嘴里不停地咕哝着关于客人的话。","t":189.97},{"en":"When she came in with the last course--a huge pudding--she tripped on the carpet","zh":"当她端着最后一道菜——一个巨大的布丁——进来时，她在地毯上绊了一跤，","t":194.83},{"en":"and the pudding went flying through the air, narrowly missed my aunt, and crashed on the dining table with considerable force.","zh":"布丁飞了起来，险些砸到我姑妈，然后重重地摔在了餐桌上。","t":201.08},{"en":"Though this caused great mirth among the guests, Aunt Harriet was horrified.","zh":"尽管这让客人们大笑，但哈里特姑妈却吓坏了。","t":211.31},{"en":"She reluctantly came to the conclusion that Bessie was drunk.","zh":"她 reluctantly（不情愿地）得出结论：贝茜喝醉了。","t":218.37},{"en":"The guests had, of course, realized this from the moment Bessie opened the door for them and, long before the final catastrophe,","zh":"客人们当然从贝茜为他们开门的那一刻起就意识到了这一点，而且早在最后一场灾难发生之前，","t":223.37},{"en":"had had a difficult time trying to conceal their amusement.","zh":"他们就一直在努力掩饰自己的 amused（好笑）。","t":233.35},{"en":"The poor girl was dismissed instantly.","zh":"这个可怜的女孩被立刻解雇了。","t":238.04},{"en":"After her departure, Aunt Harriet discovered that there were piles of empty wine bottles of all shapes and sizes neatly stacked in what had once been Bessie's wardrobe.","zh":"在她离开后，哈里特姑妈发现，曾是贝茜衣柜的地方，整齐地堆放着各种形状和大小的空酒瓶。","t":241.69},{"en":"They had mysteriously found their way there from the wine cellar!","zh":"它们神秘地从酒窖里“溜”到了那里！","t":254.97}],"vocab":[{"word":"servant","phonetic":"/ˈsɜːvənt/","meanings":[{"pos":"noun","meaning":"仆人，佣人","usage":"指为他人做家务或服务的人"}]},{"word":"leisurely","phonetic":"/ˈleʒəli/","meanings":[{"pos":"adjective","meaning":"悠闲的，从容的","usage":"形容动作或生活节奏缓慢、不紧不慢"}]},{"word":"rambling","phonetic":"/ˈræmblɪŋ/","meanings":[{"pos":"adjective","meaning":"蔓延的，布局凌乱的","usage":"形容房屋或建筑结构不规整，延伸很长"}]},{"word":"immaculate","phonetic":"/ɪˈmækjʊlət/","meanings":[{"pos":"adjective","meaning":"整洁的，一尘不染的","usage":"形容非常干净，没有污点或灰尘"}]},{"word":"preside","phonetic":"/prɪˈzaɪd/","meanings":[{"pos":"verb","meaning":"主持，负责","usage":"常与over连用，表示管理或主持某事"}]},{"word":"fickleness","phonetic":"/ˈfɪkəlnəs/","meanings":[{"pos":"noun","meaning":"善变，变幻无常","usage":"指人的性格或行为不稳定、容易改变"}]},{"word":"industriousness","phonetic":"/ɪnˈdʌstriəsnəs/","meanings":[{"pos":"noun","meaning":"勤奋，勤勉","usage":"指工作努力、勤奋的程度"}]},{"word":"efficiency","phonetic":"/ɪˈfɪʃənsi/","meanings":[{"pos":"noun","meaning":"效率，效能","usage":"指做事的效率或能力"}]},{"word":"unexpectedly","phonetic":"/ˌʌnɪkˈspektɪdli/","meanings":[{"pos":"adverb","meaning":"意外地，出乎意料地","usage":"修饰动词，表示事情发生得让人意外"}]},{"word":"mirth","phonetic":"/mɜːθ/","meanings":[{"pos":"noun","meaning":"欢乐，欢笑","usage":"正式用语，指欢笑和快乐的情绪"}]},{"word":"reluctantly","phonetic":"/rɪˈlʌktəntli/","meanings":[{"pos":"adverb","meaning":"不情愿地，勉强地","usage":"表示虽然做某事但内心不愿意"}]},{"word":"catastrophe","phonetic":"/kəˈtæstrəfi/","meanings":[{"pos":"noun","meaning":"大灾难，惨败","usage":"指严重的事件或失败"}]},{"word":"disillusioned","phonetic":"/ˌdɪsɪˈluːʒənd/","meanings":[{"pos":"adjective","meaning":"醒悟的，幻想破灭的","usage":"指对某人或某事失去幻想"}]},{"word":"lavishly","phonetic":"/ˈlævɪʃli/","meanings":[{"pos":"adverb","meaning":"奢侈地，豪华地","usage":"形容花费大量金钱或物品"}]},{"word":"stacked","phonetic":"/stækt/","meanings":[{"pos":"verb","meaning":"堆放，堆积","usage":"stack的过去式，指整齐地堆起"}]}],"phrases":[{"phrase":"air her views","usage":"发表意见，阐述观点","examples":[{"en":"She would not be able to air her views on her favourite topic.","zh":"她将无法就她最喜欢的话题发表意见。"}]},{"phrase":"be sentimentally attached to","usage":"在感情上依恋，眷恋","examples":[{"en":"She was sentimentally attached to this house.","zh":"她对这座房子怀有深厚的感情。"}]},{"phrase":"refer to...as","usage":"把...称为，把...叫做","examples":[{"en":"She always referred to them as 'the shifting population'.","zh":"她总称他们为'流动的人口'。"}]},{"phrase":"come and went","usage":"来来去去，出入不定","examples":[{"en":"They came and went with such frequency.","zh":"他们来来去去非常频繁。"}]},{"phrase":"to the end of her days","usage":"至死，一辈子","examples":[{"en":"She carried on an unrelenting search to the end of her days.","zh":"她至死都在不懈地寻找理想的仆人。"}]},{"phrase":"put in charge of","usage":"让...负责管理","examples":[{"en":"She was put in charge of the domestic staff.","zh":"她被安排负责管理家务人员。"}]},{"phrase":"not only...but (also)","usage":"不仅...而且...","examples":[{"en":"Not only was the meal well below the usual standard, but Bessie seemed unable to walk steadily.","zh":"不仅饭菜远不如平时，而且贝齐看起来连路都走不稳。"}]},{"phrase":"narrowly miss","usage":"险些击中，差点碰到","examples":[{"en":"The pudding narrowly missed my aunt.","zh":"布丁险些砸到我的姑妈。"}]},{"phrase":"come to the conclusion","usage":"得出结论","examples":[{"en":"Aunt Harriet was reluctantly came to the conclusion that Bessie was drunk.","zh":"姑妈哈丽雅特不得不得出结论：贝齐喝醉了。"}]},{"phrase":"had a difficult time doing","usage":"做...很费劲/困难","examples":[{"en":"The guests had a difficult time trying to conceal their amusement.","zh":"客人们费了好大劲才忍住没笑出来。"}]}],"grammar":[{"title":"虚拟语气 (Subjunctive Mood) - 与现在事实相反","definition":"用于表达与事实相反的假设情况，主句用would+动词原形，从句用一般过去式","structure":"If + 主语 + 过去式(be用were), 主语 + would + 动词原形","usage":"用来表达与现实相反的假设，常用于表达遗憾或不可能实现的愿望","examples":[{"en":"If she were alive today she would not be able to air her views.","zh":"如果她今天还活着，她就不能就她最喜欢的话题发表意见了。"},{"en":"If I were you, I would accept the offer.","zh":"如果我是你，我会接受这个提议。"}]},{"title":"Not only...but (also) 引起的倒装句","definition":"当not only放在句首时，它后面的句子要使用部分倒装语序","structure":"Not only + 助动词/be动词/情态动词 + 主语 + 谓语...but (also) + 句子","usage":"强调两个事实或情况，通常用于正式写作和演讲中增强语气","examples":[{"en":"Not only was the meal well below the usual standard, but Bessie seemed unable to walk steadily.","zh":"不仅饭菜远不如平时，而且贝齐看起来连路都走不稳。"},{"en":"Not only did he finish his work, but he also helped others.","zh":"他不仅完成了自己的工作，还帮助了别人。"}]},{"title":"While 引导的让步状语从句","definition":"while 在此意为\"虽然；尽管\"，引导让步状语从句","structure":"While + 主语 + 谓语..., 主句","usage":"用于引出让步或对比关系，while从句通常放在句首","examples":[{"en":"While she always criticized the fickleness of human nature, she carried on an unrelenting search.","zh":"虽然她总是批评人性的善变，但她仍在不懈地寻找。"},{"en":"While I understand your point, I don't agree with you.","zh":"虽然我理解你的观点，但我不同意。"}]}],"patterns":[{"pattern":"It is a good thing + 主语 + 过去式","explanation":"","original":{"en":"It is a good thing my aunt Harriet died years ago.","zh":"好在哈丽雅特姑妈很多年前就去世了。"},"examples":[{"en":"It is a good thing you came early.","zh":"好在你们来得早。"},{"en":"It is a good thing we brought an umbrella.","zh":"好在我们带了雨伞。"}]},{"pattern":"No matter how + 形容词/副词 + 主语 + 谓语","explanation":"","original":{"en":"No matter how many guests were present, the great house was always immaculate.","zh":"无论有多少客人来访，这座大宅总是干干净净的。"},"examples":[{"en":"No matter how hard he tried, he couldn't open the door.","zh":"无论他怎么努力，都打不开那扇门。"},{"en":"No matter how expensive the dress was, she bought it.","zh":"无论那件裙子多贵，她都买了。"}]},{"pattern":"After + 名词/动名词, 主语 + 谓语","explanation":"","original":{"en":"After her departure, Aunt Harriet discovered that there were piles of empty wine bottles.","zh":"在她离开后，姑妈哈丽雅特发现有一堆空酒瓶。"},"examples":[{"en":"After finishing his homework, he went to play football.","zh":"完成作业后，他去踢足球了。"},{"en":"After the meeting, everyone left the room quietly.","zh":"会议结束后，大家安静地离开了房间。"}]},{"pattern":"主语 + be + so + 形容词/副词 + that + 句子","explanation":"","original":{"en":"The room was so dark that I couldn't see anything.","zh":"房间太暗了，我什么也看不见。"},"examples":[{"en":"She spoke so quickly that I couldn't follow her.","zh":"她说得太快了，我跟不上。"},{"en":"It was so hot that we decided to stay indoors.","zh":"天太热了，我们决定待在室内。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“欢乐，欢笑” 对应的单词是？","hint":"noun · /mɜːθ/","options":["mirth","temperature","editor","multimedia"],"answer":0,"explain":"mirth · /mɜːθ/ · noun · 欢乐，欢笑。正式用语，指欢笑和快乐的情绪","source":{"kind":"vocab","word":"mirth"},"id":"b3-u49-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：效率，效能","hint":"/ɪˈfɪʃənsi/ · noun","answer":"efficiency","placeholder":"输入英文单词","explain":"efficiency · /ɪˈfɪʃənsi/ · noun · 效率，效能。指做事的效率或能力","source":{"kind":"vocab","word":"efficiency"},"id":"b3-u49-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：She carried on an unrelenting search _____.","hint":"她至死都在不懈地寻找理想的仆人。","answer":"to the end of her days","placeholder":"输入缺失的短语","explain":"to the end of her days：至死，一辈子（她至死都在不懈地寻找理想的仆人。）","source":{"kind":"phrase","phrase":"to the end of her days"},"id":"b3-u49-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：my aunt unexpectedly returned one afternoon with a party of guests and instructed Bessie to _____ dinner.","hint":"姑妈在一个下午 unexpectedly（出乎意料地）带着一群客人回来了，并吩咐贝茜准备晚餐。","answer":"prepare","placeholder":"输入缺失的单词","explain":"my aunt unexpectedly returned one afternoon with a party of guests and instructed Bessie to prepare dinner. — 姑妈在一个下午 unexpectedly（出乎意料地）带着一群客人回来了，并吩咐贝茜准备晚餐。","source":{"kind":"sentence","en":"my aunt unexpectedly returned one afternoon with a party of guests and instructed Bessie to prepare dinner."},"id":"b3-u49-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用于表达与事实相反的假设情况，主句用would+动词原形，从句用一般过去式” 描述的是哪个语法点？","hint":"If + 主语 + 过去式(be用were), 主语 + would + 动词原形","options":["间接宾语和直接宾语 (Indirect and Direct Objects)","将来进行时 (Future Continuous Tense)","more than + n./adj. (不仅仅；超出)","虚拟语气 (Subjunctive Mood) - 与现在事实相反"],"answer":3,"explain":"虚拟语气 (Subjunctive Mood) - 与现在事实相反：If + 主语 + 过去式(be用were), 主语 + would + 动词原形：用来表达与现实相反的假设，常用于表达遗憾或不可能实现的愿望","source":{"kind":"grammar","title":"虚拟语气 (Subjunctive Mood) - 与现在事实相反"},"id":"b3-u49-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nShe was sentimentally attached to this house,","hint":"","options":["打开强光弧光灯后，","理查兹夫人不想吓着那个可怜的人，便迅速躲到了楼梯下的小储藏室里。","你不必花接下来的几天来从漫长而艰辛的旅程中恢复。","她对这所房子感情深厚，"],"answer":3,"explain":"She was sentimentally attached to this house, — 她对这所房子感情深厚，","source":{"kind":"sentence","en":"She was sentimentally attached to this house,"},"id":"b3-u49-q06"}]},{"id":"b3-u50","book":3,"unit":50,"key":"50","lessonFrom":50,"lessonTo":50,"title":"New Year Resolutions","titleZh":"新年决心","question":"What marked the end of the writer's New Year resolutions?","sentences":[{"en":"The New Year is a time for resolutions.","zh":"新年是制定决心的时候。","t":16.81},{"en":"Mentally, at least, most of us could compile formidable lists of 'dos' and 'don'ts'.","zh":"至少在心理上，我们大多数人都能列出一长串“该做”和“不该做”的事情。","t":19.91},{"en":"The same old favourites recur year in year out with monotonous regularity.","zh":"那些老掉牙的旧习惯年复一年地以单调的规律重现。","t":27.54},{"en":"We resolve to get up earlier each morning, eat less,","zh":"我们下决心每天早起，少吃，","t":34.27},{"en":"find more time to play with the children, do a thousand and one jobs about the house,","zh":"抽出更多时间陪孩子们玩，做成千上万件家务，","t":38.35},{"en":"be nice to people we don't like, drive carefully, and take the dog for a walk every day.","zh":"对不喜欢的人和善，小心驾驶，以及每天遛狗。","t":44.12},{"en":"Past experience has taught us that certain accomplishments are beyond attainment.","zh":"过去的经验告诉我们，有些成就是无法实现的。","t":51.73},{"en":"If we remain inveterate smokers, it is only because we have so often experienced the frustration that results from failure.","zh":"如果我们仍是老烟枪，那只是因为我们屡次体验了失败带来的挫折感。","t":57.86},{"en":"Most of us fail in our efforts at self-improvement because our schemes are too ambitious and we never have time to carry them out.","zh":"我们大多数人在自我改进方面都失败了，因为我们的计划过于雄心勃勃，我们根本没有时间去实施。","t":67.83},{"en":"We also make the fundamental error of announcing our resolutions to everybody","zh":"我们还犯了一个根本性的错误，那就是向所有人宣布我们的决心，","t":77.37},{"en":"so that we look even more foolish when we slip back into our bad old ways.","zh":"这样当我们故态复萌时，就会显得更加愚蠢。","t":83.01},{"en":"Aware of these pitfalls, this year I attempted to keep my resolutions to myself.","zh":"意识到这些陷阱，今年我试图把我的决心藏在心里。","t":89.2},{"en":"I limited myself to two modest ambitions: to do physical exercises every morning and to read more of an evening.","zh":"我只限制自己两个适度的抱负：每天早上做体育锻炼，晚上多读书。","t":96.21},{"en":"An all-night party on New Year's Eve provided me with a good excuse for not carrying out either of these new resolutions on the first day of the year,","zh":"新年前夜的通宵派对给了我一个很好的借口，让我在新年第一天没有执行这两项新决心，","t":106.61},{"en":"but on the second, I applied myself assiduously to the task.","zh":"但在第二天，我勤奋地投入到这项任务中。","t":117.9},{"en":"The daily exercises lasted only eleven minutes and I proposed to do them early in the morning before anyone had got up.","zh":"每天的锻炼只持续11分钟，我打算在大家起床之前一大早做。","t":123.67},{"en":"The self-discipline required to drag myself out of bed 11 minutes earlier than usual was considerable.","zh":"要比平时早11分钟把自己从床上拽起来，需要的自律性是相当大的。","t":133.4},{"en":"Nevertheless, I managed to creep down into the living room for two days before anyone found me out.","zh":"尽管如此，我还是设法偷偷溜到客厅里去了两天，才被人发现。","t":141.74},{"en":"After jumping about on the carpet and twisting the human frame into uncomfortable positions,","zh":"在地毯上跳来跳去，把身体扭曲成不舒服的姿势之后，","t":151.03},{"en":"I sat down at the breakfast table in an exhausted condition.","zh":"我筋疲力尽地坐到早餐桌旁。","t":157.82},{"en":"It was this that betrayed me.","zh":"就是这个把我出卖了。","t":162.89},{"en":"The next morning the whole family trooped in to watch the performance.","zh":"第二天早上，全家人都跑进来观看表演。","t":165.78},{"en":"That was really unsettling but I fended off the taunts and jibes of the family good-humouredly and soon everybody got used to the idea.","zh":"这确实让人不安，但我还是好脾气地抵挡住了家人的嘲讽和揶揄，很快大家就习惯了。","t":170.51},{"en":"However, my enthusiasm waned.","zh":"然而，我的热情消退了。","t":180.4},{"en":"The time I spent at exercises gradually diminished.","zh":"我花在锻炼上的时间逐渐减少。","t":183.85},{"en":"Little by little the eleven minutes fell to zero.","zh":"渐渐地，那11分钟变成了零。","t":187.67},{"en":"By January 10th, I was back to where I had started from.","zh":"到了1月10日，我又回到了起点。","t":192.29},{"en":"I argued that if I spent less time exhausting myself at exercises in the morning,","zh":"我辩解说，如果早上少花点时间在锻炼上把自己搞得精疲力尽，","t":197.33},{"en":"I would keep my mind fresh for reading when I got home from work.","zh":"那么我下班回家时，头脑会更清醒，可以用来阅读。","t":203.54},{"en":"Resisting the hypnotizing effect of television,","zh":"抵制住电视的催眠作用，","t":208.32},{"en":"I sat in my room for a few evenings with my eyes glued to a book.","zh":"有几个晚上，我坐在房间里，眼睛紧盯着一本书。","t":212.16},{"en":"One night, however, feeling cold and lonely, I went downstairs and sat in front of the television pretending to read.","zh":"然而，有一天晚上，我感到又冷又寂寞，于是下楼坐在电视机前假装看书。","t":217.18},{"en":"That proved to be my undoing, for I soon got back to my old bad habit of dozing off in front of the screen.","zh":"那被证明是我的失败，因为我很快又回到了在屏幕前打瞌睡的旧习惯。","t":227.05},{"en":"I still haven't given up my resolution to do more reading.","zh":"我还没有放弃多读书的决心。","t":237.32},{"en":"In fact, I have just bought a book entitled How to Read a Thousand Words a Minute.","zh":"事实上，我刚买了一本名为《如何一分钟阅读一千字》的书。","t":241.22},{"en":"Perhaps it will solve my problem, but I just haven't had time to read it!","zh":"也许它能解决我的问题，但我就是没时间读它！","t":248.7}],"vocab":[{"word":"resolution","phonetic":"/ˌrezəˈluːʃn/","meanings":[{"pos":"noun","meaning":"决心；决定","usage":"指新年的决心或决定，常用make a resolution"}]},{"word":"mentally","phonetic":"/ˈmentəli/","meanings":[{"pos":"adv","meaning":"精神上；思想上","usage":"由mental加-ly构成，修饰动词或形容词"}]},{"word":"formidable","phonetic":"/ˈfɔːmɪdəbl/","meanings":[{"pos":"adj","meaning":"可怕的；令人敬畏的","usage":"形容令人印象深刻或感到畏惧的事物"}]},{"word":"monotonous","phonetic":"/məˈnɒtənəs/","meanings":[{"pos":"adj","meaning":"单调的；乏味的","usage":"形容缺乏变化、重复的事物"}]},{"word":"attainment","phonetic":"/əˈteɪnmənt/","meanings":[{"pos":"noun","meaning":"达到；成就","usage":"指达到目标或获得成就"}]},{"word":"inveterate","phonetic":"/ɪnˈvetərət/","meanings":[{"pos":"adj","meaning":"根深蒂固的；积习的","usage":"形容长期形成的难以改变的习惯"}]},{"word":"frustration","phonetic":"/frʌˈstreɪʃn/","meanings":[{"pos":"noun","meaning":"挫折；挫败","usage":"指未能实现目标的失望感"}]},{"word":"ambitious","phonetic":"/æmˈbɪʃəs/","meanings":[{"pos":"adj","meaning":"有雄心的；野心勃勃的","usage":"形容有强烈愿望和目标的"}]},{"word":"assiduously","phonetic":"/əˈsɪdjuəsli/","meanings":[{"pos":"adv","meaning":"勤奋地；刻苦地","usage":"形容认真不懈地做某事"}]},{"word":"betray","phonetic":"/bɪˈtreɪ/","meanings":[{"pos":"verb","meaning":"背叛；暴露","usage":"指出卖或泄露秘密，也可指暴露内心感受"}]},{"word":"taunt","phonetic":"/tɔːnt/","meanings":[{"pos":"noun/verb","meaning":"嘲笑；讽刺","usage":"指用言语嘲笑或羞辱他人"}]},{"word":"wane","phonetic":"/weɪn/","meanings":[{"pos":"verb","meaning":"衰落；减弱","usage":"指兴趣、力量等逐渐减少"}]},{"word":"undoing","phonetic":"/ʌnˈduːɪŋ/","meanings":[{"pos":"noun","meaning":"毁灭；失败的原因","usage":"指导致失败或毁灭的事物"}]},{"word":"hypnotize","phonetic":"/ˈhɪpnətaɪz/","meanings":[{"pos":"verb","meaning":"使着迷；催眠","usage":"指使人着迷或被吸引"}]},{"word":"self-discipline","phonetic":"/ˌselfˈdɪsɪplɪn/","meanings":[{"pos":"noun","meaning":"自律；自我约束","usage":"指控制自己行为的能力"}]}],"phrases":[{"phrase":"year in year out","usage":"年复一年地；每年都","examples":[{"en":"The same old favourites recur year in year out with monotonous regularity.","zh":"同样的喜好年复一年地以单调的规律性重复出现。"}]},{"phrase":"a thousand and one","usage":"无数的；许许多多","examples":[{"en":"Do a thousand and one jobs about the house.","zh":"做无数的家务事。"}]},{"phrase":"carry out","usage":"执行；实现；完成","examples":[{"en":"We never have time to carry them out.","zh":"我们从没有时间去实现它们。"}]},{"phrase":"slip back into","usage":"退回到；回到（原状）","examples":[{"en":"When we slip back into our bad old ways.","zh":"当我们重新回到坏习惯时。"}]},{"phrase":"apply oneself to","usage":"专心于；致力于","examples":[{"en":"I applied myself assiduously to the task.","zh":"我勤奋地致力于这项任务。"}]},{"phrase":"creep down","usage":"悄悄溜下；蹑手蹑脚地走下","examples":[{"en":"I managed to creep down into the living room.","zh":"我设法悄悄溜进客厅。"}]},{"phrase":"fend off","usage":"挡开；回避","examples":[{"en":"I fended off the taunts and jibes of the family.","zh":"我挡开了家人的嘲笑和讽刺。"}]},{"phrase":"little by little","usage":"渐渐地；逐渐地","examples":[{"en":"Little by little the eleven minutes fell to zero.","zh":"渐渐地，十一分钟降到了零。"}]},{"phrase":"doze off","usage":"打瞌睡；打盹","examples":[{"en":"I soon got back to my old bad habit of dozing off in front of the screen.","zh":"我很快又回到了在屏幕前打瞌睡的坏习惯。"}]},{"phrase":"keep something to oneself","usage":"对某事保密；不告诉别人","examples":[{"en":"This year I attempted to keep my resolutions to myself.","zh":"今年我试图对自己的决心保密。"}]}],"grammar":[{"title":"动词不定式作表语 (Infinitive as Predicative)","definition":"动词不定式可以在句中作表语，说明主语的内容或目标","structure":"主语 + be + to + 动词原形","usage":"用于说明计划、意图、命运等，或与resolution, aim, goal等名词搭配","examples":[{"en":"My resolution is to read more.","zh":"我的决心是多读书。"},{"en":"Our aim is to finish the project on time.","zh":"我们的目标是按时完成项目。"}]},{"title":"结果状语从句 (Consecutive Clause)","definition":"由so...that或such...that引导，表示某种原因导致的结果","structure":"so + adj/adv + that / such + (a/an) + adj + n + that","usage":"用于描述由于前面情况而产生的自然结果","examples":[{"en":"The daily exercises lasted only eleven minutes so that I could finish them quickly.","zh":"每日锻炼只持续了十一分钟，所以我能很快完成。"},{"en":"It was such cold weather that nobody wanted to go out.","zh":"天气太冷了，没有人想出去。"}]},{"title":"定冠词the的特指用法 (Definite Article 'the' for Specific Reference)","definition":"定冠词the用于特指谈话双方都知道的特定事物","structure":"the + 名词","usage":"当名词被上下文限定、或者谈话双方都知道的事物时使用the","examples":[{"en":"The next morning the whole family trooped in.","zh":"第二天早上，全家人鱼贯而入。"},{"en":"The dog is sleeping under the table.","zh":"那只狗正在桌子下面睡觉。"}]}],"patterns":[{"pattern":"We resolve to + 动词原形","explanation":"","original":{"en":"We resolve to get up earlier each morning.","zh":"我们决心每天早上早起。"},"examples":[{"en":"I resolve to exercise more this year.","zh":"我决心今年多锻炼。"},{"en":"She resolves to learn a new language.","zh":"她决心学习一门新语言。"}]},{"pattern":"It is/was + this/that + that + 动词","explanation":"","original":{"en":"It was this that betrayed me.","zh":"正是这暴露了我。"},"examples":[{"en":"It was the cold weather that kept me indoors.","zh":"正是寒冷的天气让我待在室内。"},{"en":"It was her kindness that saved the day.","zh":"正是她的善良挽救了局面。"}]},{"pattern":"Little by little + 主语 + 动词","explanation":"","original":{"en":"Little by little the eleven minutes fell to zero.","zh":"渐渐地，十一分钟降到了零。"},"examples":[{"en":"Little by little the snow melted away.","zh":"雪渐渐融化了。"},{"en":"Little by little he recovered his confidence.","zh":"他渐渐恢复了信心。"}]},{"pattern":"Past experience has taught us that + 从句","explanation":"","original":{"en":"Past experience has taught us that certain accomplishments are beyond attainment.","zh":"过去的经验告诉我们，某些目标是无法实现的。"},"examples":[{"en":"Life has taught us that patience is a virtue.","zh":"生活教会我们耐心是一种美德。"},{"en":"Experience has taught me that honesty pays off.","zh":"经验告诉我诚实是有回报的。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“达到；成就” 对应的单词是？","hint":"noun · /əˈteɪnmənt/","options":["farmhand","attainment","urban","exert"],"answer":1,"explain":"attainment · /əˈteɪnmənt/ · noun · 达到；成就。指达到目标或获得成就","source":{"kind":"vocab","word":"attainment"},"id":"b3-u50-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：根深蒂固的；积习的","hint":"/ɪnˈvetərət/ · adj","answer":"inveterate","placeholder":"输入英文单词","explain":"inveterate · /ɪnˈvetərət/ · adj · 根深蒂固的；积习的。形容长期形成的难以改变的习惯","source":{"kind":"vocab","word":"inveterate"},"id":"b3-u50-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：I managed to _____ into the living room.","hint":"我设法悄悄溜进客厅。","answer":"creep down","placeholder":"输入缺失的短语","explain":"creep down：悄悄溜下；蹑手蹑脚地走下（我设法悄悄溜进客厅。）","source":{"kind":"phrase","phrase":"creep down"},"id":"b3-u50-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：If we remain inveterate smokers, it is only _____ we have so often experienced the frustration that results from failure.","hint":"如果我们仍是老烟枪，那只是因为我们屡次体验了失败带来的挫折感。","answer":"because","placeholder":"输入缺失的单词","explain":"If we remain inveterate smokers, it is only because we have so often experienced the frustration that results from failure. — 如果我们仍是老烟枪，那只是因为我们屡次体验了失败带来的挫折感。","source":{"kind":"sentence","en":"If we remain inveterate smokers, it is only because we have so often experienced the frustration that results from failure."},"id":"b3-u50-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“定冠词the用于特指谈话双方都知道的特定事物” 描述的是哪个语法点？","hint":"the + 名词","options":["Only + 状语 置于句首的倒装","定语从句","非限制性定语从句","定冠词the的特指用法 (Definite Article 'the' for Specific Reference)"],"answer":3,"explain":"定冠词the的特指用法 (Definite Article 'the' for Specific Reference)：the + 名词：当名词被上下文限定、或者谈话双方都知道的事物时使用the","source":{"kind":"grammar","title":"定冠词the的特指用法 (Definite Article 'the' for Specific Reference)"},"id":"b3-u50-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe daily exercises lasted only eleven minutes and I proposed to do them early in the morning before anyone had got up.","hint":"","options":["我抬起头，看到我们已经被一群衣衫褴褛的孩子围住了，他们一言不发地看着我们吃东西。","每天的锻炼只持续11分钟，我打算在大家起床之前一大早做。","我们很幸运，只有较低的田地，","如果你要赶火车，最好是提前充足时间，而不是哪怕晚一分钟。"],"answer":1,"explain":"The daily exercises lasted only eleven minutes and I proposed to do them early in the morning before anyone had got up. — 每天的锻炼只持续11分钟，我打算在大家起床之前一大早做。","source":{"kind":"sentence","en":"The daily exercises lasted only eleven minutes and I proposed to do them early in the morning before anyone had got up."},"id":"b3-u50-q06"}]},{"id":"b3-u51","book":3,"unit":51,"key":"51","lessonFrom":51,"lessonTo":51,"title":"Predicting the Future","titleZh":"预测未来","question":"What was the 'future' electronic development that Leon Bagrit wasn't able to foresee?","sentences":[{"en":"Predicting the future is notoriously difficult.","zh":"预测未来是出了名的困难。","t":19.4},{"en":"Who could have imagined, in the mid 1970s, for example,","zh":"举例来说，在20世纪70年代中期，谁能想到，","t":23.21},{"en":"that by the end of the 20th century, computers would be as common in people's homes as TV sets?","zh":"到20世纪末，电脑在人们家中会像电视机一样普及？","t":28.33},{"en":"In the 1970s, computers were common enough,","zh":"在20世纪70年代，电脑已经很常见了，","t":36.23},{"en":"but only in big business, government departments and large organizations.","zh":"但只存在于大企业、政府部门和大型机构中。","t":40.83},{"en":"These were the so-called mainframe machines.","zh":"这些就是所谓的“大型机”。","t":47.2},{"en":"Mainframe computers were very large indeed often occupying whole air-conditioned rooms,","zh":"大型机确实非常大，常常占据整个空调房间，","t":52.06},{"en":"employing full-time technicians and run on specially-written software.","zh":"雇用全职技术人员，并运行专门编写的软件。","t":59.08},{"en":"Though these large machines still exist,","zh":"尽管这些大型机器仍然存在，","t":65.11},{"en":"many of their functions have been taken over by small powerful personal computers, commonly known as PCs.","zh":"但它们的许多功能已被小型、强大的个人电脑（通常称为PC）所取代。","t":68.14},{"en":"In 1975, a primitive machine called the Altair, was launched in the USA.","zh":"1975年，一台名为Altair的原始机器在美国问世。","t":78.12},{"en":"It can properly be described as the first 'home computer' and it pointed the way to the future.","zh":"它完全可以被称为第一台“家用电脑”，它指明了未来的方向。","t":86.54},{"en":"This was followed, at the end of the 1970s, by a machine called an Apple.","zh":"随后，在20世纪70年代末，一台名为Apple的机器问世。","t":93.58},{"en":"In the early 1980s, the computer giant, IBM produced the world's first Personal Computer.","zh":"在20世纪80年代初，电脑巨头IBM生产了世界上第一台个人电脑。","t":101.09},{"en":"This ran on an 'operating system' called DOS,","zh":"它运行在一个名为DOS的“操作系统”上，","t":109.76},{"en":"produced by a then small company named Microsoft.","zh":"由当时一家名为微软的小公司开发。","t":114.15},{"en":"The IBM Personal Computer was widely copied.","zh":"IBM个人电脑被广泛复制。","t":119.19},{"en":"From those humble beginnings,","zh":"从这些不起眼的开端，","t":123.75},{"en":"we have seen the development of the user-friendly home computers and multimedia machines which are in common use today.","zh":"我们看到了今天普遍使用的用户友好的家用电脑和多媒体机器的发展。","t":126.11},{"en":"Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s, an Englishman,","zh":"考虑到这些发展是如此之新，更令人称奇的是，早在20世纪60年代，一位名叫","t":136.32},{"en":"Leon Bagrit, was able to predict some of the uses of computers which we know today.","zh":"莱昂·巴格里特的英国人就能预言我们今天所知道的一些电脑用途。","t":147.52},{"en":"Bagrit dismissed the idea that computers would learn to 'think' for themselves and would 'rule the world', which people liked to believe in those days.","zh":"巴格里特驳斥了电脑会学会“独立思考”并“统治世界”的观点，这在当时是人们喜欢相信的。","t":154.98},{"en":"Bagrit foresaw a time when computers would be small enough to hold in the hand,","zh":"巴格里特预见到一个时代，那时电脑会小到可以手持，","t":165.76},{"en":"when they would be capable of providing information about traffic jams and suggesting alternative routes,","zh":"能够提供交通堵塞信息并建议替代路线，","t":171.78},{"en":"when they would be used in hospitals to help doctors to diagnose illnesses,","zh":"在医院里用来帮助医生诊断疾病，","t":179.88},{"en":"when they would relieve office workers and accountants of dull, repetitive clerical work.","zh":"解放办公室职员和会计师们枯燥、重复的文书工作。","t":185.78},{"en":"All these computer uses have become commonplace.","zh":"所有这些电脑用途都已变得司空见惯。","t":193.64},{"en":"Of course, Leon Bagrit couldn't possibly have foreseen the development of the Internet,","zh":"当然，莱昂·巴格里特不可能预见到互联网的发展，","t":197.96},{"en":"the worldwide system that enables us to communicate instantly with anyone in any part of the world by using computers linked to telephone networks.","zh":"这个全球性的系统使我们能够通过连接到电话网络的电脑与世界任何地方的任何人即时交流。","t":204.3},{"en":"Nor could he have foreseen how we could use the Internet to obtain information on every known subject,","zh":"他也无法预见到我们如何利用互联网获取所有已知主题的信息，","t":217.49},{"en":"so we can read it on a screen in our homes and even print it as well if we want to.","zh":"以便我们可以在家中屏幕上阅读，如果需要甚至可以打印出来。","t":224.79},{"en":"Computers have become smaller and smaller, more and more powerful and cheaper and cheaper.","zh":"电脑变得越来越小，越来越强大，也越来越便宜。","t":231.87},{"en":"This is what makes Leon Bagrit's predictions particularly remarkable.","zh":"这就是莱昂·巴格里特的预测显得格外引人注目的原因。","t":239.55},{"en":"If he, or someone like him, were alive today, he might be able to tell us what to expect in the next fifty years.","zh":"如果他，或者像他一样的人，今天还活着，他或许能告诉我们未来五十年会发生什么。","t":244.91}],"vocab":[{"word":"predict","phonetic":"/prɪˈdɪkt/","meanings":[{"pos":"verb","meaning":"预测；预言","usage":"指根据现有信息推断未来事件"}]},{"word":"foresee","phonetic":"/fɔːˈsiː/","meanings":[{"pos":"verb","meaning":"预见；预知","usage":"指提前知道或预见将要发生的事"}]},{"word":"notoriously","phonetic":"/nəʊˈtɔːriəsli/","meanings":[{"pos":"adverb","meaning":"众所周知地；声名狼藉地","usage":"修饰形容词，强调某事出名（通常指坏的方面）"}]},{"word":"mainframe","phonetic":"/ˈmeɪnfreɪm/","meanings":[{"pos":"noun","meaning":"主机；大型机","usage":"指大型计算机系统，通常用于企业或政府机构"}]},{"word":"primitive","phonetic":"/ˈprɪmətɪv/","meanings":[{"pos":"adjective","meaning":"原始的；简陋的","usage":"形容早期、技术不发达的事物"}]},{"word":"user-friendly","phonetic":"/ˌjuːzəˈfrendli/","meanings":[{"pos":"adjective","meaning":"用户友好的；易操作的","usage":"指容易使用和理解的产品或系统"}]},{"word":"multimedia","phonetic":"/ˌmʌltiˈmiːdiə/","meanings":[{"pos":"noun/adjective","meaning":"多媒体","usage":"指结合文字、图像、声音等多种媒介的技术"}]},{"word":"dismiss","phonetic":"/dɪsˈmɪs/","meanings":[{"pos":"verb","meaning":"不予理会；摒弃","usage":"指拒绝接受或不认真考虑某个想法"}]},{"word":"capable","phonetic":"/ˈkeɪpəbl/","meanings":[{"pos":"adjective","meaning":"有能力的；能够...的","usage":"与of连用，表示具备做某事的能力"}]},{"word":"diagnose","phonetic":"/ˈdaɪəɡnəʊz/","meanings":[{"pos":"verb","meaning":"诊断","usage":"主要用于医学领域，指判断疾病"}]},{"word":"commonplace","phonetic":"/ˈkɒmənpleɪs/","meanings":[{"pos":"adjective/noun","meaning":"常见的；平常的事","usage":"指不再稀奇、变得普通的事物"}]},{"word":"instantly","phonetic":"/ˈɪnstəntli/","meanings":[{"pos":"adverb","meaning":"立即；即刻","usage":"表示即时发生，没有延迟"}]},{"word":"remarkable","phonetic":"/rɪˈmɑːkəbl/","meanings":[{"pos":"adjective","meaning":"非凡的；引人注目的","usage":"形容值得注意或不同寻常的事物"}]},{"word":"relieve","phonetic":"/rɪˈliːv/","meanings":[{"pos":"verb","meaning":"减轻；解除","usage":"常与of连用，表示免除某人的负担或工作"}]},{"word":"electronic","phonetic":"/ˌelɪkˈtrɒnɪk/","meanings":[{"pos":"adjective","meaning":"电子的；电子设备的","usage":"指涉及电子技术的设备或系统"}]}],"phrases":[{"phrase":"as long ago as","usage":"早在...（用于强调时间久远）","examples":[{"en":"As long ago as the 1960s, Leon Bagrit predicted these uses.","zh":"早在20世纪60年代，莱昂·巴格瑞特就预测到了这些用途。"}]},{"phrase":"point the way to","usage":"指明...的方向","examples":[{"en":"It pointed the way to the future.","zh":"它指明了未来的方向。"}]},{"phrase":"take over","usage":"接管；取代","examples":[{"en":"Many of their functions have been taken over by small personal computers.","zh":"许多功能已被小型个人电脑所取代。"}]},{"phrase":"be capable of","usage":"能够做...；有能力做...","examples":[{"en":"They would be capable of providing information about traffic jams.","zh":"它们将能够提供有关交通拥堵的信息。"}]},{"phrase":"relieve someone of something","usage":"解除某人的...；使某人从...中解脱","examples":[{"en":"They would relieve office workers of dull, repetitive clerical work.","zh":"它们将把办公室工作人员从枯燥重复的文书工作中解放出来。"}]},{"phrase":"nor could he have foreseen","usage":"他也无法预见（用于否定句后加强语气）","examples":[{"en":"Nor could he have foreseen the development of the Internet.","zh":"他也不可能预见互联网的发展。"}]},{"phrase":"be linked to","usage":"与...连接/联系","examples":[{"en":"Computers linked to telephone networks.","zh":"与电话网络相连的计算机。"}]},{"phrase":"more and more","usage":"越来越...","examples":[{"en":"Computers have become more and more powerful.","zh":"计算机变得越来越强大。"}]},{"phrase":"it is even more remarkable that","usage":"更值得注意的 是...","examples":[{"en":"It is even more remarkable that an Englishman could predict these uses.","zh":"更值得注意的是一个英国人能够预测这些用途。"}]},{"phrase":"think for oneself","usage":"独立思考；自己判断","examples":[{"en":"Bagrit dismissed the idea that computers would learn to 'think' for themselves.","zh":"巴格瑞特摒弃了计算机会学会'独立思考'的观念。"}]}],"grammar":[{"title":"情态动词 + have + 过去分词（表达对过去的推测或可能性）","definition":"情态动词could/might/must + have + 过去分词结构用于表达对过去事件的推测、批评或惊讶","structure":"Subject + could/might/must/would have + past participle","usage":"这个结构用于：1) 对过去的推测（could have been, might have been）；2) 虚拟语气中的假设；3) 表达'本可以'但未实现的可能性","examples":[{"en":"Who could have imagined, in the mid 1970s, that computers would be common in homes?","zh":"在20世纪70年代中期，有谁能够想象计算机会在家庭中普及？"},{"en":"Leon Bagrit couldn't possibly have foreseen the development of the Internet.","zh":"莱昂·巴格瑞特不可能预见互联网的发展。"},{"en":"If he were alive today, he might be able to tell us what to expect.","zh":"如果他今天还活着，他也许能告诉我们该期待什么。"}]},{"title":"nor/neither...nor 的倒装用法","definition":"当nor或neither...nor连接两个否定成分时，可以使用倒装语序","structure":"Nor/Neither + 助动词/be动词/情态动词 + 主语 + ... .","usage":"用于否定句后，连接第二个否定成分，强调两者都不。nor could he have foreseen是'他也无法预见'的意思，强调连...也无法做到","examples":[{"en":"Nor could he have foreseen the development of the Internet.","zh":"他也不可能预见互联网的发展。"},{"en":"Neither does he want to go, nor will he change his mind.","zh":"他既不想去，也不会改变主意。"}]},{"title":"过去完成时在间接引语中的使用","definition":"当主句动词是过去时，间接引语中的动词通常需要使用过去完成时","structure":"主句动词（过去时）+ that + 主语 + had + 过去分词","usage":"用于报道过去某人所说的话或想法，使时间关系更加清晰。Bagrit foresaw a time when computers would be small...中，would表示过去的将来","examples":[{"en":"Bagrit dismissed the idea that computers would learn to 'think' for themselves.","zh":"巴格瑞特摒弃了计算机会学会'独立思考'的观念。"},{"en":"He predicted that computers would be small enough to hold in the hand.","zh":"他预测计算机会小到可以握在手中。"}]}],"patterns":[{"pattern":"Who could have imagined...?","explanation":"","original":{"en":"Who could have imagined, in the mid 1970s, that by the end of the 20th century, computers would be as common in people's homes as TV sets?","zh":"在20世纪70年代中期，有谁能够想象到20世纪末计算机会像电视机一样普及到家庭中？"},"examples":[{"en":"Who could have imagined, in the 1990s, that smartphones would replace cameras?","zh":"在90年代，有谁能够想象智能手机会取代相机？"},{"en":"Who could have predicted that AI would develop so rapidly?","zh":"有谁能够预测人工智能会发展得如此迅速？"}]},{"pattern":"...couldn't possibly have foreseen...","explanation":"","original":{"en":"Of course, Leon Bagrit couldn't possibly have foreseen the development of the Internet.","zh":"当然，莱昂·巴格瑞特不可能预见互联网的发展。"},"examples":[{"en":"The ancient Egyptians couldn't possibly have foreseen modern technology.","zh":"古埃及人不可能预见现代科技。"},{"en":"Early scientists couldn't possibly have imagined the internet.","zh":"早期的科学家不可能想象到互联网。"}]},{"pattern":"It is even more remarkable that...","explanation":"","original":{"en":"Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s, an Englishman was able to predict some of these uses.","zh":"考虑到这些发展是多么新近，尤其值得注意的是，早在20世纪60年代，一个英国人就能预测到其中一些用途。"},"examples":[{"en":"It is even more remarkable that he solved the problem in minutes.","zh":"更值得注意的是他在几分钟内就解决了这个问题。"},{"en":"It is even more remarkable that she learned three languages in a year.","zh":"更值得注意的是她在一年内学会了三种语言。"}]},{"pattern":"...when they would be capable of doing...","explanation":"","original":{"en":"Bagrit foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams.","zh":"巴格瑞特预见了这样一个时代：计算机会小到可以握在手中，能够提供交通拥堵信息。"},"examples":[{"en":"Scientists foresee a time when robots would be capable of doing all housework.","zh":"科学家预见了机器人能够做所有家务的时代。"},{"en":"He imagined a future when people would be capable of traveling to Mars.","zh":"他想象人们能够前往火星的未来。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“有能力的；能够...的” 对应的单词是？","hint":"adjective · /ˈkeɪpəbl/","options":["capable","hospitable","elaborate","gaoler"],"answer":0,"explain":"capable · /ˈkeɪpəbl/ · adjective · 有能力的；能够...的。与of连用，表示具备做某事的能力","source":{"kind":"vocab","word":"capable"},"id":"b3-u51-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：非凡的；引人注目的","hint":"/rɪˈmɑːkəbl/ · adjective","answer":"remarkable","placeholder":"输入英文单词","explain":"remarkable · /rɪˈmɑːkəbl/ · adjective · 非凡的；引人注目的。形容值得注意或不同寻常的事物","source":{"kind":"vocab","word":"remarkable"},"id":"b3-u51-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____ an Englishman could predict these uses.","hint":"更值得注意的是一个英国人能够预测这些用途。","answer":"it is even more remarkable that","placeholder":"输入缺失的短语","explain":"it is even more remarkable that：更值得注意的 是...（更值得注意的是一个英国人能够预测这些用途。）","source":{"kind":"phrase","phrase":"it is even more remarkable that"},"id":"b3-u51-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：_____ they would relieve office workers and accountants of dull, repetitive clerical work.","hint":"解放办公室职员和会计师们枯燥、重复的文书工作。","answer":"when","placeholder":"输入缺失的单词","explain":"when they would relieve office workers and accountants of dull, repetitive clerical work. — 解放办公室职员和会计师们枯燥、重复的文书工作。","source":{"kind":"sentence","en":"when they would relieve office workers and accountants of dull, repetitive clerical work."},"id":"b3-u51-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“情态动词could/might/must + have + 过去分词结构用于表达对过去事件的推测、批评或惊讶” 描述的是哪个语法点？","hint":"Subject + could/might/must/would have + past participle","options":["情态动词 + have + 过去分词（表达对过去的推测或可能性）","It引导的强调句","让步/原因状语从句的省略","Only + 状语 置于句首的倒装"],"answer":0,"explain":"情态动词 + have + 过去分词（表达对过去的推测或可能性）：Subject + could/might/must/would have + past participle：这个结构用于：1) 对过去的推测（could have been, might have been）；2) 虚拟语气中的假设；3) 表达'本可以'但未实现的可能性","source":{"kind":"grammar","title":"情态动词 + have + 过去分词（表达对过去的推测或可能性）"},"id":"b3-u51-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nPredicting the future is notoriously difficult.","hint":"","options":["他们无物可卖，也无需别人的任何东西。","她拿出了各种稀奇古怪的混合物，但没有一样符合哈里的要求。","穿上衣服后，理查兹夫人下了楼。","预测未来是出了名的困难。"],"answer":3,"explain":"Predicting the future is notoriously difficult. — 预测未来是出了名的困难。","source":{"kind":"sentence","en":"Predicting the future is notoriously difficult."},"id":"b3-u51-q06"}]},{"id":"b3-u52","book":3,"unit":52,"key":"52","lessonFrom":52,"lessonTo":52,"title":"Mud is Mud","titleZh":"泥就是泥","question":"Why did Harry decide to give up his little game?","sentences":[{"en":"My cousin, Harry, keeps a large curiously-shaped bottle on permanent display in his study.","zh":"我的表兄哈里在他书房里长期陈列着一个硕大而形状奇特的瓶子。","t":15.35},{"en":"Despite the fact that the bottle is tinted a delicate shade of green,","zh":"尽管瓶子是淡绿色的，","t":23.47},{"en":"an observant visitor would soon notice that it is filled with what looks like a thick, greyish substance.","zh":"细心的来访者很快就会注意到瓶子里盛满了像厚厚的灰白色物质。","t":27.74},{"en":"If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud.","zh":"如果你问哈里瓶子里装的是什么，他会告诉你里面装的是香泥。","t":35.6},{"en":"If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin.","zh":"如果你表示怀疑或惊奇，他会立刻请你闻一闻，然后让你往皮肤上擦一些。","t":42.44},{"en":"The brief experiment would dispel any further doubts you might have.","zh":"这一短暂的试验会打消你可能有的任何疑虑。","t":52.01},{"en":"The bottle really does contain perfumed mud.","zh":"瓶子里确实盛有香泥。","t":56.84},{"en":"How Harry came into the possession of this outlandish stuff makes an interesting story which he is fond of relating.","zh":"哈里是如何得到这种稀奇古怪的东西的，说来话长，他本人也乐于讲述。","t":60.8},{"en":"Furthermore, the acquisition of this bottle cured him of a bad habit he had been developing for years.","zh":"此外，得到这个瓶子还纠正了他多年来养成的一个坏习惯。","t":69.36},{"en":"Harry used to consider it a great joke to go into expensive cosmetic shops and make outrageous requests for goods that do not exist.","zh":"哈里过去认为，到高级化妆品商店去提出一些闻所未闻的要求，寻找一些根本不存在的商品，是一种莫大的乐趣。","t":77.66},{"en":"He would invent fanciful names on the spot.","zh":"他会当场编造一些新奇的名称。","t":88.92},{"en":"On entering a shop,","zh":"一进商店，","t":92.37},{"en":"he would ask for a new perfume called 'Scented Shadow' or for 'insoluble bath cubes'.","zh":"他会要求买一种叫“香影”的新型香水，或“不溶性浴块”。","t":94.06},{"en":"If a shop assistant told him she had not heard of it, he would pretend to be considerably put out.","zh":"如果店员告诉他从未听说过，他便会装出相当不悦的样子。","t":102.32},{"en":"He loved to be told that one of his imaginary products was temporarily out of stock","zh":"他喜欢听人说他臆造的商品暂时缺货，","t":109.63},{"en":"and he would faithfully promise to call again at some future date, but of course he never did.","zh":"他会信誓旦旦地答应改日再来，当然他从来也没有去过。","t":116.35},{"en":"How Harry managed to keep a straight face during these performances is quite beyond me.","zh":"哈里在做这些表演时是如何能不露出笑容的，我简直无法理解。","t":123.27},{"en":"Harry does not need to be prompted to explain how he bought his precious bottle of mud.","zh":"哈里无需别人提醒就会讲他是如何买到那珍贵的泥巴瓶的。","t":130.31},{"en":"One day, he went to an exclusive shop in London and asked for 'Myrolite'.","zh":"有一天，他去了伦敦一家高级商店，要买“美妙来特”。","t":136.1},{"en":"The shop assistant looked puzzled and Harry repeated the word, slowly stressing each syllable.","zh":"店员看上去很迷惑，哈里便重复了一遍这个词，并慢慢地重读每个音节。","t":143.14},{"en":"When the woman shook her head in bewilderment,","zh":"当那个店员困惑地摇了摇头时，","t":151},{"en":"Harry went on to explain that 'myrolite' was a hard, amber-like substance which could be used to remove freckles.","zh":"哈里接着解释说，“美妙来特”是一种硬的、琥珀状物质，可以用来消除雀斑。","t":154.19},{"en":"This explanation evidently conveyed something to the woman who searched shelf after shelf.","zh":"这种解释显然使那个店员明白了一些什么，她便搜寻了一个又一个的货架。","t":164.08},{"en":"She produced all sorts of weird concoctions, but none of them met with Harry's requirements.","zh":"她拿出了各种稀奇古怪的混合物，但没有一样符合哈里的要求。","t":170.69},{"en":"When Harry put on his act of being mildly annoyed, the assistant promised to order some for him.","zh":"当哈里装出有点不高兴的样子时，店员答应为他订购一些。","t":178.09},{"en":"Intoxicated by his success, Harry then asked for perfumed mud.","zh":"哈里成功后有点得意忘形，接着要买香泥。","t":185.09},{"en":"He expected the assistant to look at him in blank astonishment.","zh":"他原以为店员会目瞪口呆地看着他。","t":191.64},{"en":"However, it was his turn to be surprised, for the woman's eyes immediately lit up","zh":"然而，这次轮到他吃惊了，因为店员的眼睛立刻亮了起来，","t":195.81},{"en":"and she fetched several bottles which she placed on the counter for Harry to inspect.","zh":"拿来了好几瓶放在柜台上让哈里检查。","t":203.01},{"en":"For once, Harry had to admit defeat.","zh":"哈里只好承认这次是自己输了。","t":209.03},{"en":"He picked up what seemed to be the smallest bottle and discreetly asked the price.","zh":"他拿起看似最小的一瓶，悄悄地问了问价格。","t":212.65},{"en":"He was glad to get away with a mere twenty pounds and he beat a hasty retreat, clutching the precious bottle under his arm.","zh":"他庆幸只花了区区20英镑就脱身了，他赶忙溜走，把那瓶宝贝紧紧地夹在胳膊下。","t":219.3},{"en":"From then on, Harry decided that this little game he had invented might prove to be expensive.","zh":"从那以后，哈里认为他发明的这个小把戏可能代价太大。","t":228.57},{"en":"The curious bottle which now adorns the bookcase in his study was his first and last purchase of rare cosmetics.","zh":"现在他书房书柜上陈列的那个奇特的瓶子是他最后一次购买这种稀奇化妆品。","t":235.68}],"vocab":[{"word":"curiously","phonetic":"/ˈkjʊəriəsli/","meanings":[{"pos":"adverb","meaning":"奇怪地；稀奇古怪地","usage":"修饰形容词或分词，表示程度"}]},{"word":"tint","phonetic":"/tɪnt/","meanings":[{"pos":"verb","meaning":"给...着色；给...染色","usage":"常用于被动语态，表示颜色深浅"}]},{"word":"delicate","phonetic":"/ˈdelɪkət/","meanings":[{"pos":"adjective","meaning":"精致的；淡的；柔和的","usage":"形容颜色、气味、质地等"}]},{"word":"observant","phonetic":"/əbˈzɜːvənt/","meanings":[{"pos":"adjective","meaning":"观察力敏锐的；善于观察的","usage":"描述人具有敏锐的观察能力"}]},{"word":"perfume","phonetic":"/ˈpɜːfjuːm/","meanings":[{"pos":"noun","meaning":"香水；香味","usage":"指有香味的产品或气味"}]},{"word":"outlandish","phonetic":"/aʊtˈlændɪʃ/","meanings":[{"pos":"adjective","meaning":"稀奇古怪的；古怪的","usage":"描述非常奇特、不寻常的事物"}]},{"word":"outrageous","phonetic":"/aʊtˈreɪdʒəs/","meanings":[{"pos":"adjective","meaning":"离谱的；过分的；惊人的","usage":"形容行为或要求过于极端"}]},{"word":"fanciful","phonetic":"/ˈfænsɪfl/","meanings":[{"pos":"adjective","meaning":"富于幻想的；想象中的","usage":"描述虚构的、不真实的东西"}]},{"word":"bewilderment","phonetic":"/bɪˈwɪldəmənt/","meanings":[{"pos":"noun","meaning":"困惑；迷惑；迷惘","usage":"表示完全迷惑的状态"}]},{"word":"freckle","phonetic":"/ˈfrekl/","meanings":[{"pos":"noun","meaning":"雀斑；斑点","usage":"皮肤上的小褐斑"}]},{"word":"concoction","phonetic":"/kənˈkɒkʃn/","meanings":[{"pos":"noun","meaning":"调制品；混合物；调合物","usage":"指混合多种东西制成的物品"}]},{"word":"intoxicate","phonetic":"/ɪnˈtɒksɪkeɪt/","meanings":[{"pos":"verb","meaning":"使陶醉；使兴奋；使喝醉","usage":"比喻极度兴奋或得意"}]},{"word":"discreetly","phonetic":"/dɪˈskriːtli/","meanings":[{"pos":"adverb","meaning":"谨慎地；慎重地；审慎地","usage":"小心谨慎地做事"}]},{"word":"retreat","phonetic":"/rɪˈtriːt/","meanings":[{"pos":"noun/verb","meaning":"撤退；退后","usage":"指快速离开某地"}]},{"word":"merely","phonetic":"/ˈmɪəli/","meanings":[{"pos":"adverb","meaning":"仅仅；只；只不过","usage":"强调数量或程度之小"}]}],"phrases":[{"phrase":"keep...on display","usage":"把...陈列出来展示","examples":[{"en":"He keeps a large bottle on permanent display in his study.","zh":"他在书房里永久陈列着一个大瓶子。"}]},{"phrase":"despite the fact that","usage":"尽管（事实）...","examples":[{"en":"Despite the fact that the bottle is tinted green, an observant visitor would notice it's filled with greyish substance.","zh":"尽管瓶子被染成绿色，敏锐的来访者会注意到里面装的是灰色物质。"}]},{"phrase":"put on an act","usage":"装腔作势；演戏","examples":[{"en":"When Harry put on his act of being mildly annoyed, the assistant promised to order some for him.","zh":"当哈利装出有点烦恼的样子时，店员答应为他订购一些。"}]},{"phrase":"light up","usage":"（眼睛）亮起来；变得兴奋","examples":[{"en":"The woman's eyes immediately lit up and she fetched several bottles.","zh":"那女人的眼睛立刻亮了起来，拿出了好几个瓶子。"}]},{"phrase":"beat a retreat","usage":"匆忙撤退；赶紧离开","examples":[{"en":"He beat a hasty retreat, clutching the precious bottle under his arm.","zh":"他匆忙撤退，腋下夹着那个珍贵的瓶子。"}]},{"phrase":"get away with","usage":"成功做（某事）；侥幸逃脱","examples":[{"en":"He was glad to get away with a mere twenty pounds.","zh":"他很高兴只花了二十英镑就买到了。"}]},{"phrase":"be fond of doing","usage":"喜欢做某事","examples":[{"en":"He is fond of relating this interesting story.","zh":"他喜欢讲述这个有趣的故事。"}]},{"phrase":"on the spot","usage":"当场；立即","examples":[{"en":"He would invent fanciful names on the spot.","zh":"他会当场编造一些稀奇古怪的名字。"}]},{"phrase":"meet with requirements","usage":"满足要求","examples":[{"en":"None of them met with Harry's requirements.","zh":"没有一个能满足哈利的要求。"}]},{"phrase":"come into the possession of","usage":"获得；占有","examples":[{"en":"How Harry came into the possession of this outlandish stuff makes an interesting story.","zh":"哈利是如何得到这种稀奇古怪的东西的，这本身就是一个有趣的故事。"}]}],"grammar":[{"title":"过去完成进行时 (Past Perfect Continuous Tense)","definition":"表示在过去某一时刻之前一直在进行的动作，强调动作的持续性和未完成性","structure":"had been + 动词-ing","usage":"用于描述持续到过去某一点的习惯性动作","examples":[{"en":"He had been developing a bad habit for years.","zh":"他多年来一直养成一个坏习惯。"}]},{"title":"if虚拟条件句（与现在事实相反）","definition":"表示与现在事实相反或不太可能发生的情况","structure":"If + 主语 + were to + 动词原形...","usage":"用于假设不太可能发生的事情","examples":[{"en":"If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud.","zh":"如果你问哈利瓶子里是什么，他会告诉你里面装的是香水泥。"}]},{"title":"间接引语（陈述句的转换）","definition":"将直接引语转换为间接引语时，人称、时态、时间状语等需要相应变化","structure":"主语 + said (that) + ...","usage":"叙述他人说过的话时使用，that可省略","examples":[{"en":"He said (that) the bottle contained perfumed mud.","zh":"他说瓶子里装的是香水泥。"}]}],"patterns":[{"pattern":"If you were to do..., would/could/might + 动词原形...","explanation":"","original":{"en":"If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud.","zh":"如果你问哈利瓶子里是什么，他会告诉你里面装的是香水泥。"},"examples":[{"en":"If you were to visit China, you would learn a lot about its culture.","zh":"如果你要去中国旅游，你会学到很多关于中国文化的知识。"},{"en":"If you were to practice speaking English every day, you could improve quickly.","zh":"如果你每天练习说英语，你就能快速进步。"}]},{"pattern":"Despite the fact that + 从句...","explanation":"","original":{"en":"Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, greyish substance.","zh":"尽管瓶子被染成淡绿色，敏锐的来访者很快就会注意到里面装的是看起来像浓稠的灰色物质。"},"examples":[{"en":"Despite the fact that he is very young, he speaks English fluently.","zh":"尽管他很年轻，他的英语说得很流利。"},{"en":"Despite the fact that it was raining heavily, we went hiking.","zh":"尽管雨下得很大，我们还是去徒步了。"}]},{"pattern":"主语 + love/like + to be told that...","explanation":"","original":{"en":"He loved to be told that one of his imaginary products was temporarily out of stock.","zh":"他喜欢听别人说他想象中的产品暂时缺货。"},"examples":[{"en":"She loves to be told that her cooking is delicious.","zh":"她喜欢听别人夸她的厨艺好。"},{"en":"Children love to be told that they are clever.","zh":"孩子们喜欢听别人夸他们聪明。"}]},{"pattern":"...is quite beyond me","explanation":"","original":{"en":"How Harry managed to keep a straight face during these performances is quite beyond me.","zh":"哈利在这些表演中是怎样忍住不笑的，我实在想不通。"},"examples":[{"en":"Why she married him is quite beyond me.","zh":"她为什么嫁给他，我实在想不通。"},{"en":"How he passed the exam is quite beyond me.","zh":"他是怎么通过考试的，我实在想不通。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“富于幻想的；想象中的” 对应的单词是？","hint":"adjective · /ˈfænsɪfl/","options":["hoard","stray","fanciful","funeral"],"answer":2,"explain":"fanciful · /ˈfænsɪfl/ · adjective · 富于幻想的；想象中的。描述虚构的、不真实的东西","source":{"kind":"vocab","word":"fanciful"},"id":"b3-u52-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：观察力敏锐的；善于观察的","hint":"/əbˈzɜːvənt/ · adjective","answer":"observant","placeholder":"输入英文单词","explain":"observant · /əbˈzɜːvənt/ · adjective · 观察力敏锐的；善于观察的。描述人具有敏锐的观察能力","source":{"kind":"vocab","word":"observant"},"id":"b3-u52-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：He was glad to _____ a mere twenty pounds.","hint":"他很高兴只花了二十英镑就买到了。","answer":"get away with","placeholder":"输入缺失的短语","explain":"get away with：成功做（某事）；侥幸逃脱（他很高兴只花了二十英镑就买到了。）","source":{"kind":"phrase","phrase":"get away with"},"id":"b3-u52-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Despite the fact that the bottle is tinted a delicate shade of _____","hint":"尽管瓶子是淡绿色的，","answer":"green","placeholder":"输入缺失的单词","explain":"Despite the fact that the bottle is tinted a delicate shade of green, — 尽管瓶子是淡绿色的，","source":{"kind":"sentence","en":"Despite the fact that the bottle is tinted a delicate shade of green,"},"id":"b3-u52-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在过去某一时刻之前一直在进行的动作，强调动作的持续性和未完成性” 描述的是哪个语法点？","hint":"had been + 动词-ing","options":["过去完成进行时 (Past Perfect Continuous Tense)","现在完成时的被动语态","定语从句","As引导的时间状语从句"],"answer":0,"explain":"过去完成进行时 (Past Perfect Continuous Tense)：had been + 动词-ing：用于描述持续到过去某一点的习惯性动作","source":{"kind":"grammar","title":"过去完成进行时 (Past Perfect Continuous Tense)"},"id":"b3-u52-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe brief experiment would dispel any further doubts you might have.","hint":"","options":["他们设计了数百种竞赛，使我们能够赢得巨额奖金。","搜捕美洲狮的行动是从一个小村庄开始的，在那里，一位采摘黑莓的妇女看见“一只大猫”离她只有五码远。","这一短暂的试验会打消你可能有的任何疑虑。","警察和工人都很感谢这名学生提供的这条提前消息。"],"answer":2,"explain":"The brief experiment would dispel any further doubts you might have. — 这一短暂的试验会打消你可能有的任何疑虑。","source":{"kind":"sentence","en":"The brief experiment would dispel any further doubts you might have."},"id":"b3-u52-q06"}]},{"id":"b3-u53","book":3,"unit":53,"key":"53","lessonFrom":53,"lessonTo":53,"title":"In the Public Interest","titleZh":"为了公众利益","question":"What could not be reported in the official files?","sentences":[{"en":"The Scandinavian countries are much admired all over the world for their enlightened social policies.","zh":"斯堪的纳维亚国家以其开明的社会政策而受到全世界的普遍赞扬。","t":15.8},{"en":"Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officers.","zh":"瑞典已逐步建立起一套完善的制度来保护公民不受专横或渎职的政府官员的侵害。","t":23.38},{"en":"The system has worked so well, that it has been adopted in other countries too.","zh":"这套制度非常行之有效，以至于其他国家也采用了它。","t":33.22},{"en":"The Swedes were the first to recognize that public officials like civil servants,","zh":"瑞典人最先认识到，政府官员，如公务员、","t":40.21},{"en":"police officers, health inspectors or tax-collectors can make mistakes or act over-zealously in the belief that they are serving the public.","zh":"警官、卫生检察员或税务官，都可能犯错误，或者相信他们在为公众服务而工作过分热心。","t":46.23},{"en":"As long ago as 1809, the Swedish Parliament introduced a scheme to safeguard the interest of the individual.","zh":"早在1809年，瑞典议会就制定了一项保护个人利益的计划。","t":56.76},{"en":"A parliamentary committee representing all political parties appoints a person who is suitably qualified to investigate private grievances against the State.","zh":"一个由所有政党组成的议会委员会任命一位有资格调查个人对国家不满的投诉的人。","t":66.75},{"en":"The official title of the person is 'Justiteombudsman', but the Swedes commonly refer to him as the 'J.O.' or 'Ombudsman'.","zh":"这个人的官方头衔是“司法特派员”，但瑞典人通常称他为“J.O.”或“特派员”。","t":78.63},{"en":"The Ombudsman is not subject to political pressure.","zh":"监察官不受政治压力。","t":89.51},{"en":"He investigates complaints large and small that come to him from all levels of society.","zh":"他调查来自社会各阶层的大小投诉。","t":93.72},{"en":"As complaints must be made in writing, the Ombudsman receives an average of 1, 200 letters a year.","zh":"由于投诉必须以书面形式提出，监察官平均每年收到1200封信。","t":100.31},{"en":"He has eight lawyer assistants to help him and he examines every single letter in detail.","zh":"他有八名律师助理帮助他，他会详细审查每一封信。","t":108.78},{"en":"There is nothing secretive about the Ombudsman's work, for his correspondence is open to public inspection.","zh":"监察官的工作毫无秘密可言，因为他的信件都公开供公众查阅。","t":116.26},{"en":"If a citizen's complaint is justified the Ombudsman will act on his behalf.","zh":"如果公民的投诉是有根据的，监察官将代表他采取行动。","t":124.5},{"en":"The action he takes varies according to the nature of the complaint.","zh":"他采取的行动因投诉的性质而异。","t":131.26},{"en":"He may gently reprimand an official or even suggest to parliament that a law be altered.","zh":"他可以温和地训斥一名官员，甚至向议会建议修改法律。","t":136},{"en":"The following case is a typical example of the Ombudsman's work.","zh":"下面这个案例是监察官工作的典型例子。","t":143.23},{"en":"A foreigner living in a Swedish village wrote to the Ombudsman complaining that he had been ill-treated by the police,","zh":"一个住在瑞典乡村的外国人写信给监察官，抱怨他受到警察的虐待，","t":149.28},{"en":"simply because he was a foreigner.","zh":"只因为他是个外国人。","t":157.37},{"en":"The Ombudsman immediately wrote to the Chief of Police in the district asking him to send a record of the case.","zh":"监察官立即写信给该地区的警察局长，要求他寄送案件记录。","t":160.42},{"en":"There was nothing in the record to show that the foreigner's complaint was justified","zh":"记录中没有任何内容表明该外国人的投诉是有根据的，","t":169.38},{"en":"and the Chief of Police strongly denied the accusation.","zh":"警察局长也强烈否认了这一指控。","t":175.32},{"en":"It was impossible for the Ombudsman to take action,","zh":"监察官无法采取行动，","t":180.56},{"en":"but when he received a similar complaint from another foreigner in the same village,","zh":"但当他收到同一村庄另一名外国人的类似投诉时，","t":184.52},{"en":"he immediately sent one of his lawyers to investigate the matter.","zh":"他立即派他的一名律师去调查此事。","t":190.2},{"en":"The lawyer ascertained that a policeman had indeed dealt roughly with foreigners on several occasions.","zh":"律师证实，一名警察确实曾多次粗暴对待外国人。","t":195.03},{"en":"The fact that the policeman was prejudiced against foreigners could not be recorded in the official files.","zh":"这名警察对外国人有偏见的事实，无法记录在官方档案中。","t":203.18},{"en":"It was only possible for the Ombudsman to find this out by sending one of his representatives to check the facts.","zh":"监察官只有通过派他的一名代表去核实事实才能发现这一点。","t":210.55},{"en":"The policeman in question was severely reprimanded","zh":"这名警察受到了严厉的训斥，","t":220.24},{"en":"and was informed that if any further complaints were lodged against him, he would be prosecuted.","zh":"并被告知，如果再有针对他的投诉，他将被起诉。","t":224.2},{"en":"The Ombudsman's prompt action at once put an end to an unpleasant practice which might have gone unnoticed.","zh":"监察官的迅速行动立即制止了一种可能被忽视的不愉快的做法。","t":231.78}],"vocab":[{"word":"Scandinavian","phonetic":"/ˌskændɪˈneɪviən/","meanings":[{"pos":"adjective","meaning":"斯堪的纳维亚的；北欧国家的","usage":"用于描述北欧地区的国家或文化"}]},{"word":"enlightened","phonetic":"/ɪnˈlaɪtənd/","meanings":[{"pos":"adjective","meaning":"开明的；进步的；文明的","usage":"形容政策、制度等具有先进性和人性化"}]},{"word":"evolve","phonetic":"/ɪˈvɒlv/","meanings":[{"pos":"verb","meaning":"逐步发展；逐步形成","usage":"强调事物逐渐演变发展的过程"}]},{"word":"high-handed","phonetic":"/ˌhaɪˈhændɪd/","meanings":[{"pos":"adjective","meaning":"高压的；专横的；盛气凌人的","usage":"形容滥用权力、傲慢的行为方式"}]},{"word":"incompetent","phonetic":"/ɪnˈkɒmpɪtənt/","meanings":[{"pos":"adjective","meaning":"不称职的；无能力的","usage":"形容在工作或职责上不能胜任的人"}]},{"word":"safeguard","phonetic":"/ˈseɪfɡɑːd/","meanings":[{"pos":"verb","meaning":"保护；保卫；维护","usage":"表示采取措施保护某人或某物免受伤害"}]},{"word":"grievance","phonetic":"/ˈɡriːvəns/","meanings":[{"pos":"noun","meaning":"委屈；不满；抱怨","usage":"指个人对不公正待遇的申诉或投诉"}]},{"word":"ombudsman","phonetic":"/ˈɒmbʊdzmən/","meanings":[{"pos":"noun","meaning":"巡视官；调查官；申诉专员","usage":"指负责调查公民对政府官员投诉的官员"}]},{"word":"over-zealous","phonetic":"/ˌəʊvəˈzeləs/","meanings":[{"pos":"adjective","meaning":"过于热心的；过分积极的","usage":"形容做事过于热情而可能出错"}]},{"word":"reprimand","phonetic":"/ˈreprɪmɑːnd/","meanings":[{"pos":"verb","meaning":"训斥；谴责；正式警告","usage":"指权威人士对下属的正式责备"}]},{"word":"ascertain","phonetic":"/ˌæsəˈteɪn/","meanings":[{"pos":"verb","meaning":"查明；确定；弄清","usage":"指通过调查或研究来发现事实真相"}]},{"word":"prejudiced","phonetic":"/ˈpredʒʊdɪst/","meanings":[{"pos":"adjective","meaning":"有偏见的；偏袒的","usage":"形容对某事物持有不公平的先入为主的看法"}]},{"word":"prosecute","phonetic":"/ˈprɒsɪkjuːt/","meanings":[{"pos":"verb","meaning":"起诉；检举；控告","usage":"指通过法律程序对某人提起诉讼"}]},{"word":"prompt","phonetic":"/prɒmpt/","meanings":[{"pos":"adjective","meaning":"迅速的；及时的；敏捷的","usage":"形容行动迅速、毫不拖延的"}]},{"word":"lodge","phonetic":"/lɒdʒ/","meanings":[{"pos":"verb","meaning":"提出（投诉、申诉等）","usage":"指正式向有关部门提交投诉或申诉"}]}],"phrases":[{"phrase":"in the public interest","usage":"为了公共利益；符合公众利益","examples":[{"en":"The minister acted in the public interest.","zh":"部长为了公共利益行事。"}]},{"phrase":"evolve an excellent system","usage":"逐步形成一套优秀的体制","examples":[{"en":"Sweden has evolved an excellent system for protecting citizens.","zh":"瑞典逐步形成了一套优秀的保护公民的体制。"}]},{"phrase":"protect the individual citizen","usage":"保护个人公民","examples":[{"en":"The system protects the individual citizen from incompetent officials.","zh":"该体制保护个人公民免受不称职官员的侵害。"}]},{"phrase":"safeguard the interest of","usage":"保护...的利益；维护...的利益","examples":[{"en":"The scheme was introduced to safeguard the interest of the individual.","zh":"该方案的出台是为了保护个人的利益。"}]},{"phrase":"be subject to","usage":"受...支配；受...影响；易遭受","examples":[{"en":"The Ombudsman is not subject to political pressure.","zh":"巡视官不受政治压力的影响。"}]},{"phrase":"act on one's behalf","usage":"代表某人采取行动；代理","examples":[{"en":"If a citizen's complaint is justified, the Ombudsman will act on his behalf.","zh":"如果公民的投诉是合理的，巡视官将代表他采取行动。"}]},{"phrase":"lodge a complaint","usage":"提出投诉；提起申诉","examples":[{"en":"If any further complaints are lodged against him, he will be prosecuted.","zh":"如果再有人对他提出投诉，他将受到起诉。"}]},{"phrase":"put an end to","usage":"结束；终止；消灭","examples":[{"en":"The Ombudsman's prompt action put an end to an unpleasant practice.","zh":"巡视官的迅速行动结束了一种不良做法。"}]},{"phrase":"deal roughly with","usage":"粗暴对待；虐待","examples":[{"en":"A policeman had dealt roughly with foreigners on several occasions.","zh":"一名警察多次粗暴对待外国人。"}]},{"phrase":"be open to public inspection","usage":"公开接受公众检查；可供公众查阅","examples":[{"en":"There is nothing secretive about the Ombudsman's work, for his correspondence is open to public inspection.","zh":"巡视官的工作没有任何秘密，因为他的信函可供公众查阅。"}]}],"grammar":[{"title":"现在完成时的被动语态 (Present Perfect Passive)","definition":"现在完成时被动语态表示过去发生的动作对现在造成的影响，或动作持续到现在，且主语是动作的承受者。","structure":"have/has + been + 过去分词","usage":"用于描述某个动作或过程的结果，强调其对现在的影响。文中描述瑞典的体制被其他国家采用这一结果。","examples":[{"en":"The system has worked so well that it has been adopted in other countries too.","zh":"该体制运行良好，其他国家也采用了这一体制。"},{"en":"The Swedish Parliament introduced a scheme in 1809.","zh":"瑞典议会在1809年推出了一个方案。"}]},{"title":"过去分词作定语 (Past Participle as Attribute)","definition":"过去分词作定语时，放在被修饰的名词之前或之后，表示被动和完成的意义。","structure":"名词 + 过去分词 / 过去分词 + 名词","usage":"用于简化定语从句，使句子更加简洁。常用于正式书面语中。","examples":[{"en":"A parliamentary committee representing all political parties appoints a person.","zh":"一个代表所有政党的议会委员会任命一人。"},{"en":"The official title of the person is 'Justiteombudsman'.","zh":"这个人的官方头衔是'司法特派员'。"}]},{"title":"so...that 结果状语从句","definition":"so后面接形容词或副词，that引导结果状语从句，表示'如此...以至于...'。","structure":"so + 形容词/副词 + that + 结果状语从句","usage":"用于表达某种程度导致的结果。在文中说明瑞典体制运行良好以至于被其他国家采纳。","examples":[{"en":"The system has worked so well that it has been adopted in other countries too.","zh":"该体制运行良好，其他国家也采用了。"},{"en":"He is so busy that he cannot come.","zh":"他太忙了，不能来。"}]}],"patterns":[{"pattern":"The system has worked so well that...","explanation":"","original":{"en":"The system has worked so well that it has been adopted in other countries too.","zh":"该体制运行良好，其他国家也采用了这一体制。"},"examples":[{"en":"The policy has worked so well that it has become a model for other countries.","zh":"这项政策运行良好，已成为其他国家的典范。"},{"en":"The new teaching method has worked so well that it has been推广 in all schools.","zh":"新的教学方法效果良好，已在所有学校推广。"}]},{"pattern":"As long ago as + 年份, ... + 一般过去时","explanation":"","original":{"en":"As long ago as 1809, the Swedish Parliament introduced a scheme to safeguard the interest of the individual.","zh":"早在1809年，瑞典议会就推出了保护个人利益的方案。"},"examples":[{"en":"As long ago as 1990, China began its reform and opening-up policy.","zh":"早在1990年，中国就开始了改革开放政策。"},{"en":"As long ago as 1950, scientists discovered this phenomenon.","zh":"早在1950年，科学家们就发现了这一现象。"}]},{"pattern":"There is nothing secretive about...","explanation":"","original":{"en":"There is nothing secretive about the Ombudsman's work, for his correspondence is open to public inspection.","zh":"巡视官的工作没有任何秘密，因为他的信函可供公众查阅。"},"examples":[{"en":"There is nothing secretive about the government's decision.","zh":"政府的这项决定没有任何秘密。"},{"en":"There is nothing secretive about our company's financial report.","zh":"我们公司的财务报告没有任何隐瞒。"}]},{"pattern":"The action he takes varies according to...","explanation":"","original":{"en":"The action he takes varies according to the nature of the complaint.","zh":"他采取的行动因投诉的性质而异。"},"examples":[{"en":"The punishment varies according to the seriousness of the crime.","zh":"惩罚的轻重取决于犯罪的严重程度。"},{"en":"The salary varies according to qualifications and experience.","zh":"工资根据资历和经验而有所不同。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“逐步发展；逐步形成” 对应的单词是？","hint":"verb · /ɪˈvɒlv/","options":["evolve","glance","exception","guilty"],"answer":0,"explain":"evolve · /ɪˈvɒlv/ · verb · 逐步发展；逐步形成。强调事物逐渐演变发展的过程","source":{"kind":"vocab","word":"evolve"},"id":"b3-u53-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：迅速的；及时的；敏捷的","hint":"/prɒmpt/ · adjective","answer":"prompt","placeholder":"输入英文单词","explain":"prompt · /prɒmpt/ · adjective · 迅速的；及时的；敏捷的。形容行动迅速、毫不拖延的","source":{"kind":"vocab","word":"prompt"},"id":"b3-u53-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The minister acted _____.","hint":"部长为了公共利益行事。","answer":"in the public interest","placeholder":"输入缺失的短语","explain":"in the public interest：为了公共利益；符合公众利益（部长为了公共利益行事。）","source":{"kind":"phrase","phrase":"in the public interest"},"id":"b3-u53-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：He has _____ lawyer assistants to help him and he examines every single letter in detail.","hint":"他有八名律师助理帮助他，他会详细审查每一封信。","answer":"eight","placeholder":"输入缺失的单词","explain":"He has eight lawyer assistants to help him and he examines every single letter in detail. — 他有八名律师助理帮助他，他会详细审查每一封信。","source":{"kind":"sentence","en":"He has eight lawyer assistants to help him and he examines every single letter in detail."},"id":"b3-u53-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“so后面接形容词或副词，that引导结果状语从句，表示'如此...以至于...'。” 描述的是哪个语法点？","hint":"so + 形容词/副词 + that + 结果状语从句","options":["not only位于句首的部分倒装结构","so...that 结果状语从句","过去分词短语作状语","make it + 形容词 + for sb. to do sth."],"answer":1,"explain":"so...that 结果状语从句：so + 形容词/副词 + that + 结果状语从句：用于表达某种程度导致的结果。在文中说明瑞典体制运行良好以至于被其他国家采纳。","source":{"kind":"grammar","title":"so...that 结果状语从句"},"id":"b3-u53-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe following case is a typical example of the Ombudsman's work.","hint":"","options":["不言而喻，保险公司承担的风险越大，你将支付的保费就越高。","报纸杂志的编辑们常常不厌其烦地向读者提供一些无关紧要的事实和统计数字。","下面这个案例是监察官工作的典型例子。","我确信我再也无法把箱子合上了。"],"answer":2,"explain":"The following case is a typical example of the Ombudsman's work. — 下面这个案例是监察官工作的典型例子。","source":{"kind":"sentence","en":"The following case is a typical example of the Ombudsman's work."},"id":"b3-u53-q06"}]},{"id":"b3-u54","book":3,"unit":54,"key":"54","lessonFrom":54,"lessonTo":54,"title":"Instinct or Cleverness","titleZh":"本能还是智慧？","question":"Was the writer successful in protecting his peach tree? Why not?","sentences":[{"en":"We have been brought up to fear insects.","zh":"我们从小就被教导要害怕昆虫。","t":17.67},{"en":"We regard them as unnecessary creatures that do more harm than good.","zh":"我们认为它们是多余的生物，弊大于利。","t":20.65},{"en":"We continually wage war on them, for they contaminate our food, carry diseases, or devour our crops.","zh":"我们不断地与它们作斗争，因为它们会污染我们的食物，传播疾病，或吞噬我们的庄稼。","t":26.54},{"en":"They sting or bite without provocation; they fly uninvited into our rooms on summer nights, or beat against our lighted windows.","zh":"它们无故蜇人或咬人；在夏天的夜晚，它们不请自来地飞进我们的房间，或拍打我们点亮的窗户。","t":35.76},{"en":"We live in dread not only of unpleasant insects like spiders or wasps, but of quite harmless ones like moths.","zh":"我们不仅害怕蜘蛛或黄蜂等令人不快的昆虫，也害怕像飞蛾这样完全无害的昆虫。","t":46.15},{"en":"Reading about them increases our understanding without dispelling our fears.","zh":"阅读有关它们的文章增加了我们的理解，却无法消除我们的恐惧。","t":55.33},{"en":"Knowing that the industrious ant lives in a highly organized society","zh":"即使知道勤劳的蚂蚁生活在一个高度组织化的社会中，","t":61.67},{"en":"does nothing to prevent us from being filled with revulsion when we find hordes of them crawling over a carefully prepared picnic lunch.","zh":"也无法阻止我们在一群蚂蚁爬满精心准备的野餐时感到厌恶。","t":67.57},{"en":"No matter how much we like honey,","zh":"无论我们多么喜欢蜂蜜，","t":78.08},{"en":"or how much we have read about the uncanny sense of direction which bees possess, we have a horror of being stung.","zh":"无论我们读过多少关于蜜蜂拥有不可思议的方向感，我们都害怕被蜇。","t":80.89},{"en":"Most of our fears are unreasonable, but they are impossible to erase.","zh":"我们大部分的恐惧都是不合理的，但它们又难以消除。","t":90.32},{"en":"At the same time, however, insects are strangely fascinating.","zh":"然而，与此同时，昆虫又有着奇特的魅力。","t":96.15},{"en":"We enjoy reading about them, especially when we find that, like the praying mantis, they lead perfectly horrible lives.","zh":"我们喜欢阅读有关它们的文章，特别是当我们发现，像螳螂一样，它们过着极其可怕的生活时。","t":101.48},{"en":"We enjoy staring at them, entranced as they go about their business, unaware (we hope) of our presence.","zh":"我们喜欢凝视它们，着迷地看着它们忙碌，希望它们没有察觉到我们的存在。","t":111.1},{"en":"Who has not stood in awe at the sight of a spider pouncing on a fly,","zh":"谁不曾敬畏地看着蜘蛛扑向苍蝇，","t":119.91},{"en":"or a column of ants triumphantly bearing home an enormous dead beetle?","zh":"或一队蚂蚁凯旋地将一只巨大的死甲虫搬回家呢？","t":124.96},{"en":"Last summer I spent days in the garden watching thousands of ants crawling up the trunk of my prize peach tree.","zh":"去年夏天，我在花园里花了好几天时间，观察成千上万的蚂蚁爬上我那棵珍贵的桃树树干。","t":131.43},{"en":"The tree has grown against a warm wall on a sheltered side of the house.","zh":"这棵树长在房子避风处的一面暖墙边。","t":140.64},{"en":"I am especially proud of it,","zh":"我特别为它感到自豪，","t":146.08},{"en":"not only because it has survived several severe winters, but because it occasionally produces luscious peaches.","zh":"不仅因为它熬过了好几个严酷的冬天，还因为它偶尔会结出甜美的桃子。","t":148.61},{"en":"During the summer, I noticed that the leaves of the tree were beginning to wither.","zh":"夏天的时候，我注意到树叶开始枯萎了。","t":159.08},{"en":"Clusters of tiny insects called aphides were to be found on the underside of the leaves.","zh":"树叶的背面可以发现成群的微小昆虫，叫做蚜虫。","t":165.01},{"en":"They were visited by a large colony of ants which obtained a sort of honey from them.","zh":"一大群蚂蚁来访，从它们那里获取一种蜜露。","t":172.48},{"en":"I immediately embarked on an experiment which even though it failed to get rid of the ants kept me fascinated for twenty-four hours.","zh":"我立即开始了一项实验，尽管它未能除掉蚂蚁，但却让我着迷了二十四个小时。","t":179.12},{"en":"I bound the base of the tree with sticky tape, making it impossible for the ants to reach the aphides.","zh":"我用胶带缠住了树的底部，使蚂蚁无法接触到蚜虫。","t":190},{"en":"The tape was so sticky that they did not dare to cross it.","zh":"胶带非常粘，它们不敢越过。","t":197.71},{"en":"For a long time, I watched them scurrying around the base of the tree in bewilderment.","zh":"我长时间地看着它们困惑地在树底跑来跑去。","t":202.59},{"en":"I even went out at midnight with a torch and noted with satisfaction (and surprise)","zh":"我甚至在午夜带着手电筒出去，满意地（也惊讶地）注意到","t":209.59},{"en":"that the ants were still swarming around the sticky tape without being able to do anything about it.","zh":"蚂蚁仍然在胶带周围聚集，却无计可施。","t":216.88},{"en":"I got up early next morning hoping to find that the ants had given up in despair.","zh":"第二天早上我早早起床，希望能看到蚂蚁已经绝望地放弃了。","t":223.94},{"en":"Instead, I saw that they had discovered a new route.","zh":"结果，我发现它们开辟了一条新路线。","t":229.84},{"en":"They were climbing up the wall of the house and then on to the leaves of the tree.","zh":"它们正在爬上房子的墙壁，然后爬到树叶上。","t":234.31},{"en":"I realized sadly that I had been completely defeated by their ingenuity.","zh":"我伤心地意识到，我完全被它们的足智多谋打败了。","t":239.58},{"en":"The ants had been quick to find an answer to my thoroughly unscientific methods!","zh":"蚂蚁很快就找到了应对我这种完全不科学的方法的办法！","t":245.79}],"vocab":[{"word":"instinct","phonetic":"/ˈɪnstɪŋkt/","meanings":[{"pos":"noun","meaning":"本能","usage":"指人或动物天生的、不需要学习的行为反应"}]},{"word":"contaminate","phonetic":"/kənˈtæmɪneɪt/","meanings":[{"pos":"verb","meaning":"污染，弄脏","usage":"指对食物、环境等造成污染"}]},{"word":"provocation","phonetic":"/ˌprɒvəˈkeɪʃn/","meanings":[{"pos":"noun","meaning":"挑衅，激怒","usage":"指引起愤怒或不满的行为"}]},{"word":"revulsion","phonetic":"/rɪˈvʌlʃn/","meanings":[{"pos":"noun","meaning":"厌恶，反感","usage":"指对令人不快事物的强烈反感"}]},{"word":"industrious","phonetic":"/ɪnˈdʌstriəs/","meanings":[{"pos":"adj","meaning":"勤劳的，勤奋的","usage":"形容人工作努力、不知疲倦"}]},{"word":"horde","phonetic":"/hɔːd/","meanings":[{"pos":"noun","meaning":"群，一大群","usage":"通常指移动中的一大群人或动物，带贬义"}]},{"word":"uncanny","phonetic":"/ʌnˈkæni/","meanings":[{"pos":"adj","meaning":"离奇的，不可思议的","usage":"形容超出寻常、令人惊讶的事物"}]},{"word":"entranced","phonetic":"/ɪnˈtrɑːnst/","meanings":[{"pos":"adj","meaning":"着迷的，入迷的","usage":"形容被某事物吸引、沉迷其中"}]},{"word":"shelter","phonetic":"/ˈʃeltə(r)/","meanings":[{"pos":"noun","meaning":"遮蔽，庇护所","usage":"指可以遮风挡雨的地方或保护"}]},{"word":"wither","phonetic":"/ˈwɪðə(r)/","meanings":[{"pos":"verb","meaning":"枯萎，凋谢","usage":"指植物因缺水或衰老而枯萎"}]},{"word":"aphides","phonetic":"/ˈæfɪdiːz/","meanings":[{"pos":"noun","meaning":"蚜虫（复数）","usage":"一种吸食植物汁液的害虫"}]},{"word":"scurry","phonetic":"/ˈskʌri/","meanings":[{"pos":"verb","meaning":"急促奔跑","usage":"指小步快速移动，常带慌张含义"}]},{"word":"swarm","phonetic":"/swɔːm/","meanings":[{"pos":"verb","meaning":"蜂拥，挤满","usage":"指大量昆虫或人聚集移动"}]},{"word":"ingenuity","phonetic":"/ˌɪndʒɪˈnjuːəti/","meanings":[{"pos":"noun","meaning":"独创力，聪明才智","usage":"指解决问题的巧妙方法和创新能力"}]},{"word":"luscious","phonetic":"/ˈlʌʃəs/","meanings":[{"pos":"adj","meaning":"美味的，甘美的","usage":"形容食物或水果味道甜美诱人"}]}],"phrases":[{"phrase":"do more harm than good","usage":"表示某事弊大于利","examples":[{"en":"We regard them as unnecessary creatures that do more harm than good.","zh":"我们认为它们是无用的生物，弊大于利。"}]},{"phrase":"wage war on","usage":"对...发动战争/发起攻势","examples":[{"en":"We continually wage war on them, for they contaminate our food.","zh":"我们不断地对它们发动战争，因为它们污染我们的食物。"}]},{"phrase":"without provocation","usage":"无缘无故地，无端地","examples":[{"en":"They sting or bite without provocation.","zh":"它们无缘无故地蜇人或咬人。"}]},{"phrase":"be filled with revulsion","usage":"充满厌恶感","examples":[{"en":"Knowing that the industrious ant lives in a highly organized society does nothing to prevent us from being filled with revulsion.","zh":"尽管知道勤劳的蚂蚁生活在高度组织化的社会中，这并不能阻止我们对它们产生厌恶感。"}]},{"phrase":"stand in awe","usage":"敬畏地站着，肃然起敬","examples":[{"en":"Who has not stood in awe at the sight of a spider pouncing on a fly?","zh":"看到蜘蛛扑向苍蝇时，谁没有敬畏地驻足观看？"}]},{"phrase":"pounce on","usage":"猛扑，突然袭击","examples":[{"en":"Who has not stood in awe at the sight of a spider pouncing on a fly?","zh":"看到蜘蛛扑向苍蝇时，谁没有敬畏地驻足观看？"}]},{"phrase":"embark on","usage":"开始从事，着手进行","examples":[{"en":"I immediately embarked on an experiment.","zh":"我立刻着手进行一项实验。"}]},{"phrase":"give up in despair","usage":"绝望地放弃","examples":[{"en":"I got up early next morning hoping to find that the ants had given up in despair.","zh":"第二天一大早我起床，希望发现蚂蚁已经绝望地放弃了。"}]},{"phrase":"discover a new route","usage":"发现新的路线","examples":[{"en":"Instead, I saw that they had discovered a new route.","zh":"然而，我发现它们已经找到了一条新的路线。"}]},{"phrase":"find an answer to","usage":"找到...的答案/解决办法","examples":[{"en":"The ants had been quick to find an answer to my thoroughly unscientific methods!","zh":"蚂蚁很快就找到了对付我完全不科学的方法的答案！"}]}],"grammar":[{"title":"现在完成进行时 (Present Perfect Continuous)","definition":"表示从过去开始一直持续到现在并且可能继续下去的动作，常与all morning/afternoon, for hours, since等时间状语连用","structure":"have/has + been + 动词-ing形式","usage":"强调动作的持续性、反复性或持续产生的结果","examples":[{"en":"We have been brought up to fear insects.","zh":"我们从小就被教育要害怕昆虫。"},{"en":"I have been learning English for five years.","zh":"我已经学英语五年了。"}]},{"title":"让步状语从句 (Concessive Clause)","definition":"表示虽然存在某种情况，但主句的动作或状态仍然成立","structure":"even though / even if / although / though + 从句；no matter how + 从句","usage":"用于表达转折关系，强调尽管存在困难或相反情况","examples":[{"en":"No matter how much we like honey, or how much we have read about the uncanny sense of direction which bees possess, we have a horror of being stung.","zh":"无论我们多么喜欢蜂蜜，或者我们读过多少关于蜜蜂具有不可思议的方向感的文章，我们仍然害怕被蜇。"},{"en":"Even though it failed to get rid of the ants, it kept me fascinated.","zh":"虽然它没能消灭蚂蚁，但它让我着迷了24个小时。"}]},{"title":"双重否定疑问句 (Negative Question)","definition":"用否定形式提问，但期望得到肯定回答，表示强调","structure":"Who/What + has not + 动词...?(谁能不...呢?)","usage":"用于反问，强调说话人认为大家都会有某种感受或行为","examples":[{"en":"Who has not stood in awe at the sight of a spider pouncing on a fly?","zh":"看到蜘蛛扑向苍蝇时，谁没有敬畏地驻足观看？"},{"en":"Who has not experienced this feeling?","zh":"谁没有体验过这种感觉呢？"}]}],"patterns":[{"pattern":"No matter how + much/how/形容词..., + 主句","explanation":"","original":{"en":"No matter how much we like honey, or how much we have read about the uncanny sense of direction which bees possess, we have a horror of being stung.","zh":"无论我们多么喜欢蜂蜜，或者我们读过多少关于蜜蜂不可思议的方向感的文章，我们仍然害怕被蜇。"},"examples":[{"en":"No matter how hard I tried, I couldn't solve the problem.","zh":"无论我多么努力，我都无法解决这个问题。"},{"en":"No matter how expensive the phone is, people will buy it.","zh":"无论手机多贵，人们都会买。"}]},{"pattern":"We have been + 过去分词 + to + 动词原形","explanation":"","original":{"en":"We have been brought up to fear insects.","zh":"我们从小就被教育要害怕昆虫。"},"examples":[{"en":"We have been taught to respect the elderly.","zh":"我们从小就被教导要尊重老人。"},{"en":"Children have been encouraged to read more books.","zh":"孩子们一直被鼓励多读书。"}]},{"pattern":"Who has not + 过去分词 + at the sight of...?","explanation":"","original":{"en":"Who has not stood in awe at the sight of a spider pouncing on a fly?","zh":"看到蜘蛛扑向苍蝇时，谁没有敬畏地驻足观看？"},"examples":[{"en":"Who has not felt surprised at the news?","zh":"听到这个消息时，谁没有感到惊讶？"},{"en":"Who has not experienced loneliness in a foreign country?","zh":"在异国他乡时，谁没有经历过孤独？"}]},{"pattern":"...which/who + 从句, + 主句","explanation":"","original":{"en":"I am especially proud of it, not only because it has survived several severe winters, but because it occasionally produces luscious peaches.","zh":"我特别为它感到骄傲，不仅因为它度过了几个严冬，而且因为它偶尔会结出甘美的桃子。"},"examples":[{"en":"I love this city, not only because it has beautiful scenery, but because the people are friendly.","zh":"我爱这座城市，不仅因为它有美丽的风景，而且因为人们很友好。"},{"en":"She is a good teacher, not only because she is patient, but because she is passionate.","zh":"她是一位好老师，不仅因为她有耐心，而且因为她充满热情。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“独创力，聪明才智” 对应的单词是？","hint":"noun · /ˌɪndʒɪˈnjuːəti/","options":["ingenuity","foresee","fiercely","provocation"],"answer":0,"explain":"ingenuity · /ˌɪndʒɪˈnjuːəti/ · noun · 独创力，聪明才智。指解决问题的巧妙方法和创新能力","source":{"kind":"vocab","word":"ingenuity"},"id":"b3-u54-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：群，一大群","hint":"/hɔːd/ · noun","answer":"horde","placeholder":"输入英文单词","explain":"horde · /hɔːd/ · noun · 群，一大群。通常指移动中的一大群人或动物，带贬义","source":{"kind":"vocab","word":"horde"},"id":"b3-u54-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The ants had been quick to _____ my thoroughly unscientific methods!","hint":"蚂蚁很快就找到了对付我完全不科学的方法的答案！","answer":"find an answer to","placeholder":"输入缺失的短语","explain":"find an answer to：找到...的答案/解决办法（蚂蚁很快就找到了对付我完全不科学的方法的答案！）","source":{"kind":"phrase","phrase":"find an answer to"},"id":"b3-u54-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：I am especially _____ of it,","hint":"我特别为它感到自豪，","answer":"proud","placeholder":"输入缺失的单词","explain":"I am especially proud of it, — 我特别为它感到自豪，","source":{"kind":"sentence","en":"I am especially proud of it,"},"id":"b3-u54-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示虽然存在某种情况，但主句的动作或状态仍然成立” 描述的是哪个语法点？","hint":"even though / even if / although / though + 从句；no matter how + 从句","options":["while引导的时间状语从句（过去进行时搭配）","must have + 过去分词","such...that... 结果状语从句","让步状语从句 (Concessive Clause)"],"answer":3,"explain":"让步状语从句 (Concessive Clause)：even though / even if / although / though + 从句；no matter how + 从句：用于表达转折关系，强调尽管存在困难或相反情况","source":{"kind":"grammar","title":"让步状语从句 (Concessive Clause)"},"id":"b3-u54-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThey sting or bite without provocation; they fly uninvited into our rooms on summer nights, or beat against our lighted windows.","hint":"","options":["它们无故蜇人或咬人；在夏天的夜晚，它们不请自来地飞进我们的房间，或拍打我们点亮的窗户。","在文明社会中，准时是处理一切公共事务的必要习惯。","新年是制定决心的时候。","姑妈在一个下午 unexpectedly（出乎意料地）带着一群客人回来了，并吩咐贝茜准备晚餐。"],"answer":0,"explain":"They sting or bite without provocation; they fly uninvited into our rooms on summer nights, or beat against our lighted windows. — 它们无故蜇人或咬人；在夏天的夜晚，它们不请自来地飞进我们的房间，或拍打我们点亮的窗户。","source":{"kind":"sentence","en":"They sting or bite without provocation; they fly uninvited into our rooms on summer nights, or beat against our lighted windows."},"id":"b3-u54-q06"}]},{"id":"b3-u55","book":3,"unit":55,"key":"55","lessonFrom":55,"lessonTo":55,"title":"From the Earth Greetings","titleZh":"来自地球的问候","question":"Which life forms are most likely to develop on a distant planet?","sentences":[{"en":"Recent developments in astronomy have made it possible to detect planets in our own Milky Way and in other galaxies.","zh":"天文学的最新发展使得在我们自己的银河系和其他星系中探测行星成为可能。","t":17.41},{"en":"This is a major achievement because, in relative terms, planets are very small and do not emit light.","zh":"这是一个重大成就，因为相对而言，行星非常小且不发光。","t":26.55},{"en":"Finding planets is proving hard enough, but finding life on them will prove infinitely more difficult.","zh":"发现行星已经够难了，但在行星上发现生命将是无限困难的。","t":34.99},{"en":"The first question to answer is whether a planet can actually support life.","zh":"首先要回答的问题是，一个行星是否真的能够支持生命。","t":42.52},{"en":"In our own solar system, for example, Venus is far too hot and Mars is far too cold to support life.","zh":"例如，在我们自己的太阳系中，金星太热，火星太冷，都无法支持生命。","t":48.55},{"en":"Only the Earth provides ideal conditions, and even here it has taken more than four billion years for plant and animal life to evolve.","zh":"只有地球提供了理想的条件，即使在这里，植物和动物生命也用了超过40亿年才得以进化。","t":57.03},{"en":"Whether a planet can support life depends on the size and brightness of its star, that is its 'sun'.","zh":"行星是否能支持生命取决于其恒星，也就是它的“太阳”的大小和亮度。","t":68.35},{"en":"Imagine a star up to twenty times larger, brighter and hotter than our own sun.","zh":"想象一颗比我们自己的太阳大20倍、亮20倍、热20倍的恒星。","t":75.68},{"en":"A planet would have to be a very long way from it to be capable of supporting life.","zh":"一个行星必须离它非常遥远才能支持生命。","t":82.25},{"en":"Alternatively, if the star were small,","zh":"另一方面，如果恒星很小，","t":87.92},{"en":"the life-supporting planet would have to have a close orbit round it and also provide the perfect conditions for life forms to develop.","zh":"支持生命的行星就必须围绕它近距离运行，并且提供生命形式发展的完美条件。","t":91.09},{"en":"But how would we find such a planet?","zh":"但是我们如何才能找到这样一个行星呢？","t":101.37},{"en":"At present, there is no telescope in existence that is capable of detecting the presence of life.","zh":"目前，还没有任何望远镜能够探测到生命的存在。","t":104.73},{"en":"The development of such a telescope will be one of the great astronomical projects of the 21st century.","zh":"这种望远镜的开发将是21世纪伟大的天文学项目之一。","t":112.38},{"en":"It is impossible to look for life on another planet using earth-based telescopes.","zh":"使用基于地球的望远镜来寻找其他行星上的生命是不可能的。","t":121.15},{"en":"Our own warm atmosphere and the heat generated by the telescope","zh":"我们温暖的大气层和望远镜产生的热量","t":127.34},{"en":"would make it impossible to detect objects as small as planets.","zh":"将使我们不可能探测到像行星一样小的物体。","t":131.98},{"en":"Even a telescope in orbit round the earth, like the very successful Hubble telescope,","zh":"即使是像非常成功的哈勃望远镜那样围绕地球轨道运行的望远镜，","t":137.1},{"en":"would not be suitable because of the dust particles in our solar system.","zh":"也不会适用，因为我们太阳系中有尘埃颗粒。","t":143.32},{"en":"A telescope would have to be as far away as the planet Jupiter to look for life in outer space,","zh":"望远镜必须远达木星才能在外太空寻找生命，","t":149.03},{"en":"because the dust becomes thinner the further we travel towards the outer edges of our own solar system.","zh":"因为我们越往太阳系外围移动，尘埃就越稀薄。","t":156.55},{"en":"Once we detected a planet, we would have to find a way of blotting out the light from its star,","zh":"一旦我们探测到一颗行星，我们就必须找到一种方法来遮挡其恒星的光线，","t":163.97},{"en":"so that we would be able to 'see' the planet properly and analyse its atmosphere.","zh":"这样我们才能清楚地“看清”这颗行星并分析其大气层。","t":170.47},{"en":"In the first instance, we would be looking for plant life, rather than 'little green men'.","zh":"首先，我们将寻找植物生命，而不是“小绿人”。","t":176.38},{"en":"The life forms most likely to develop on a planet would be bacteria.","zh":"最有可能在行星上发展的生命形式将是细菌。","t":182.99},{"en":"It is bacteria that have generated the oxygen we breathe on earth.","zh":"是细菌产生了我们地球上呼吸的氧气。","t":188.85},{"en":"For most of the earth's history they have been the only form of life on our planet.","zh":"在地球的大部分历史中，它们一直是地球上唯一的生命形式。","t":194.08},{"en":"As Earth-dwellers, we always cherish the hope that we will be visited by little green men and that we will be able to communicate with them.","zh":"作为地球居民，我们总是怀着这样的希望：我们会受到小绿人的拜访，并能与他们交流。","t":199.95},{"en":"But this hope is always in the realms of science fiction.","zh":"但这种希望始终停留在科幻小说的范畴。","t":210.24},{"en":"If we were able to discover lowly forms of life like bacteria on another planet, it would completely change our view of ourselves.","zh":"如果我们能在另一个行星上发现像细菌这样低级的生命形式，它将彻底改变我们对自身的看法。","t":215.38},{"en":"As Daniel Goldin of NASA observed, 'Finding life elsewhere would change everything.","zh":"正如美国宇航局的丹尼尔·戈尔丁所观察到的，“在别处发现生命将改变一切。","t":225.41},{"en":"No human endeavour or thought would be unchanged by it.'","zh":"任何人类的努力或思想都不会因此而保持不变。”","t":232.33}],"vocab":[{"word":"astronomy","phonetic":"/əˈstrɒnəmi/","meanings":[{"pos":"noun","meaning":"天文学","usage":"指研究恒星、星系等天体的科学"}]},{"word":"detect","phonetic":"/dɪˈtekt/","meanings":[{"pos":"verb","meaning":"发现；探测","usage":"表示通过仪器或方法发现或感知某物的存在"}]},{"word":"galaxy","phonetic":"/ˈɡæləksi/","meanings":[{"pos":"noun","meaning":"星系；银河","usage":"指由众多恒星、气体和尘埃组成的巨大天体系统"}]},{"word":"emit","phonetic":"/ɪˈmɪt/","meanings":[{"pos":"verb","meaning":"发出；散发；发射","usage":"指发出光、热、声音等"}]},{"word":"evolve","phonetic":"/ɪˈvɒlv/","meanings":[{"pos":"verb","meaning":"进化；逐步发展","usage":"指生物或事物经过漫长时间逐渐发展变化"}]},{"word":"capable","phonetic":"/ˈkeɪpəbl/","meanings":[{"pos":"adj","meaning":"有能力的；能够...的","usage":"常与of连用，表示有能力做某事"}]},{"word":"orbit","phonetic":"/ˈɔːbɪt/","meanings":[{"pos":"noun/verb","meaning":"轨道；环绕运行","usage":"指天体运行的路径，或绕某天体运行的动作"}]},{"word":"atmosphere","phonetic":"/ˈætməsfɪə/","meanings":[{"pos":"noun","meaning":"大气层；气氛","usage":"指包围地球的气体层，或某地的一般氛围"}]},{"word":"bacteria","phonetic":"/bækˈtɪəriə/","meanings":[{"pos":"noun","meaning":"细菌","usage":"bacterium的复数形式，指微生物"}]},{"word":"generate","phonetic":"/ˈdʒenəreɪt/","meanings":[{"pos":"verb","meaning":"产生；生成","usage":"指产生某种物质、能量或结果"}]},{"word":"realm","phonetic":"/relm/","meanings":[{"pos":"noun","meaning":"领域；范围","usage":"指思想、活动或知识的领域或范围"}]},{"word":"blot","phonetic":"/blɒt/","meanings":[{"pos":"verb","meaning":"遮住；弄脏","usage":"blot out表示遮住、挡住光线"}]},{"word":"dust","phonetic":"/dʌst/","meanings":[{"pos":"noun","meaning":"灰尘；尘埃","usage":"指细小的粉末状物质"}]},{"word":"alternative","phonetic":"/ɔːlˈtɜːnətɪv/","meanings":[{"pos":"noun/adj","meaning":"替代选择；可供选择的","usage":"指另一种选择或方法"}]},{"word":"endeavour","phonetic":"/ɪnˈdevə/","meanings":[{"pos":"noun","meaning":"努力；尝试；事业","usage":"正式用语，指尝试做某事或努力做的事"}]}],"phrases":[{"phrase":"in relative terms","usage":"相对而言；相对地","examples":[{"en":"In relative terms, planets are very small and do not emit light.","zh":"相对而言，行星非常小且不发光。"}]},{"phrase":"be capable of","usage":"能够；有能力的","examples":[{"en":"A planet would have to be a very long way from it to be capable of supporting life.","zh":"行星必须离它很远才能维持生命。"}]},{"phrase":"rather than","usage":"而不是；与其...不如","examples":[{"en":"In the first instance, we would be looking for plant life, rather than 'little green men'.","zh":"首先，我们会寻找植物生命，而不是小绿人。"}]},{"phrase":"in the realms of","usage":"在...领域/范围内","examples":[{"en":"But this hope is always in the realms of science fiction.","zh":"但这种希望总是在科幻小说的领域里。"}]},{"phrase":"blot out","usage":"遮住；遮蔽","examples":[{"en":"We would have to find a way of blotting out the light from its star.","zh":"我们必须找到一种方法遮住它恒星的光。"}]},{"phrase":"in the first instance","usage":"首先；最初；第一阶段","examples":[{"en":"In the first instance, we would be looking for plant life.","zh":"首先，我们会寻找植物生命。"}]},{"phrase":"far too","usage":"太...；过于...","examples":[{"en":"Venus is far too hot and Mars is far too cold to support life.","zh":"金星太热而火星太冷，都无法维持生命。"}]},{"phrase":"take + 时间 + for + 事物 + to do","usage":"花费...时间做某事","examples":[{"en":"It has taken more than four billion years for plant and animal life to evolve.","zh":"动植物生命进化花了四十多亿年。"}]},{"phrase":"look for","usage":"寻找；寻求","examples":[{"en":"It is impossible to look for life on another planet using earth-based telescopes.","zh":"用地面望远镜寻找另一颗行星上的生命是不可能的。"}]},{"phrase":"generate oxygen","usage":"产生氧气","examples":[{"en":"It is bacteria that have generated the oxygen we breathe on earth.","zh":"正是细菌产生了我们呼吸的氧气。"}]}],"grammar":[{"title":"虚拟语气 (Subjunctive Mood) - 与现在事实相反","definition":"虚拟语气用于表达与事实相反的假设情况。使用were来表示与现在事实相反的假设","structure":"If + 主语 + were + 其他, 主语 + would/could/might + 动词原形","usage":"用于表达不太可能实现的假设或与事实相反的情况","examples":[{"en":"If we were able to discover lowly forms of life like bacteria on another planet, it would completely change our view of ourselves.","zh":"如果我們能夠在另一颗行星上发现像细菌这样的低等生命，那将完全改变我们对自己的看法。"}]},{"title":"定语从句 (Relative Clause) - 关系副词where引导","definition":"用where引导的定语从句修饰表示地点的名词，说明事件发生的场所","structure":"名词 + where + 完整句子","usage":"where在从句中作地点状语，修饰其前的名词","examples":[{"en":"A telescope would have to be as far away as the planet Jupiter to look for life in outer space, where the dust becomes thinner.","zh":"望远镜必须远到像木星那样的距离才能在外太空寻找生命，那里的尘埃更稀薄。"}]},{"title":"强调句型 (Emphatic Structure) - It is/was + 被强调部分 + that/who + 其他","definition":"使用It is/was...that/who...结构强调句子的某个成分","structure":"It is/was + 强调部分 + that/who + 句子其他部分","usage":"可用于强调主语、宾语或状语，增强表达效果","examples":[{"en":"It is bacteria that have generated the oxygen we breathe on earth.","zh":"正是细菌产生了我们呼吸的氧气。"}]}],"patterns":[{"pattern":"Whether...depends on...","explanation":"","original":{"en":"Whether a planet can support life depends on the size and brightness of its star.","zh":"行星是否能维持生命取决于其恒星的大小和亮度。"},"examples":[{"en":"Whether we can find water on Mars depends on its geological conditions.","zh":"我们能否在火星上找到水取决于它的地质条件。"},{"en":"Whether the plan will succeed depends on everyone's cooperation.","zh":"这个计划是否成功取决于每个人的配合。"}]},{"pattern":"The first question to answer is whether...","explanation":"","original":{"en":"The first question to answer is whether a planet can actually support life.","zh":"首先要回答的问题是行星是否真的能维持生命。"},"examples":[{"en":"The first problem to solve is whether we have enough funding.","zh":"首先要解决的问题是我们是否有足够的资金。"},{"en":"The first step to take is whether we should accept their offer.","zh":"首先要采取的步骤是我们是否应该接受他们的提议。"}]},{"pattern":"It is + adj + to do something","explanation":"","original":{"en":"It is impossible to look for life on another planet using earth-based telescopes.","zh":"用地面望远镜寻找另一颗行星上的生命是不可能的。"},"examples":[{"en":"It is difficult to detect planets in distant galaxies.","zh":"探测遥远星系中的行星是困难的。"},{"en":"It is necessary to understand the basic principles of astronomy.","zh":"理解天文学的基本原理是必要的。"}]},{"pattern":"A planet would have to be...to be capable of...","explanation":"","original":{"en":"A planet would have to be a very long way from it to be capable of supporting life.","zh":"行星必须离它很远才能维持生命。"},"examples":[{"en":"An organism would have to adapt to extreme conditions to be capable of surviving.","zh":"有机体必须适应极端条件才能存活。"},{"en":"A telescope would have to be placed in space to be capable of detecting small objects.","zh":"望远镜必须放置在太空中才能探测到小物体。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“遮住；弄脏” 对应的单词是？","hint":"verb · /blɒt/","options":["unforeseen","blot","indulge","wretched"],"answer":1,"explain":"blot · /blɒt/ · verb · 遮住；弄脏。blot out表示遮住、挡住光线","source":{"kind":"vocab","word":"blot"},"id":"b3-u55-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：领域；范围","hint":"/relm/ · noun","answer":"realm","placeholder":"输入英文单词","explain":"realm · /relm/ · noun · 领域；范围。指思想、活动或知识的领域或范围","source":{"kind":"vocab","word":"realm"},"id":"b3-u55-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It is impossible to _____ life on another planet using earth-based telescopes.","hint":"用地面望远镜寻找另一颗行星上的生命是不可能的。","answer":"look for","placeholder":"输入缺失的短语","explain":"look for：寻找；寻求（用地面望远镜寻找另一颗行星上的生命是不可能的。）","source":{"kind":"phrase","phrase":"look for"},"id":"b3-u55-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：It is bacteria that have generated the oxygen we _____ on earth.","hint":"是细菌产生了我们地球上呼吸的氧气。","answer":"breathe","placeholder":"输入缺失的单词","explain":"It is bacteria that have generated the oxygen we breathe on earth. — 是细菌产生了我们地球上呼吸的氧气。","source":{"kind":"sentence","en":"It is bacteria that have generated the oxygen we breathe on earth."},"id":"b3-u55-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用where引导的定语从句修饰表示地点的名词，说明事件发生的场所” 描述的是哪个语法点？","hint":"名词 + where + 完整句子","options":["定语从句 (Relative Clause) - 关系副词where引导","It seems that 主语从句结构","It作形式主语的主语从句","非限制性定语从句"],"answer":0,"explain":"定语从句 (Relative Clause) - 关系副词where引导：名词 + where + 完整句子：where在从句中作地点状语，修饰其前的名词","source":{"kind":"grammar","title":"定语从句 (Relative Clause) - 关系副词where引导"},"id":"b3-u55-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nFinding planets is proving hard enough, but finding life on them will prove infinitely more difficult.","hint":"","options":["然而，第二天，医生安慰他说，","我伤心地意识到，我完全被它们的足智多谋打败了。","有人说，人人都靠出售某种东西来维持生活。","发现行星已经够难了，但在行星上发现生命将是无限困难的。"],"answer":3,"explain":"Finding planets is proving hard enough, but finding life on them will prove infinitely more difficult. — 发现行星已经够难了，但在行星上发现生命将是无限困难的。","source":{"kind":"sentence","en":"Finding planets is proving hard enough, but finding life on them will prove infinitely more difficult."},"id":"b3-u55-q06"}]},{"id":"b3-u56","book":3,"unit":56,"key":"56","lessonFrom":56,"lessonTo":56,"title":"Our Neighbour, the River","titleZh":"我们的邻居，河流","question":"Why had the neighbours left their farm?","sentences":[{"en":"The river which forms the eastern boundary of our farm has always played an important part in our lives.","zh":"构成了我们农场东部边界的河流，在我们的生活中一直扮演着重要的角色。","t":13.91},{"en":"Without it we could not make a living.","zh":"没有它，我们就无法谋生。","t":21.26},{"en":"There is only enough spring water to supply the needs of the house so we have to pump from the river for farm use.","zh":"泉水仅够供应房屋使用，所以农场用水必须从河里抽。","t":24.33},{"en":"We tell the river all our secrets.","zh":"我们向河流倾诉我们所有的秘密。","t":32.59},{"en":"We know instinctively, just as beekeepers with their bees,","zh":"我们本能地知道，就像养蜂人对他们的蜜蜂一样，","t":35.36},{"en":"that misfortune might overtake us if the important events of our lives were not related to it.","zh":"如果我们生活中的重要事件不与河流相关，不幸可能会降临到我们身上。","t":39.98},{"en":"We have special river birthday parties in the summer.","zh":"夏天我们会在河边举行特别的生日派对。","t":48.62},{"en":"Sometimes we go upstream to a favourite backwater,","zh":"有时我们逆流而上到我们最喜欢的一个回水湾，","t":52.63},{"en":"sometimes we have our party at the boathouse,","zh":"有时我们会在船屋举行派对，","t":56.49},{"en":"which a predecessor of ours at the farm built in the meadow hard by the deepest pool for swimming and diving.","zh":"那是我们在农场的前任在草地边上，紧邻最深的游泳和跳水池建造的。","t":59.61},{"en":"In a heat wave we choose a midnight birthday party and that is the most exciting of all.","zh":"在热浪来袭时，我们选择举行午夜生日派对，那是所有派对中最令人兴奋的。","t":67.74},{"en":"We welcome the seasons by the riverside, crowning the youngest girl with flowers in the spring,","zh":"我们在河边迎接季节，春天给最小的女孩戴上花冠，","t":74.5},{"en":"holding a summer festival on Midsummer Eve, giving thanks for the harvest in the autumn, and throwing a holly wreath into the current in the winter.","zh":"在仲夏夜举行夏季节庆，秋天感谢丰收，冬天则将冬青花环抛入水流中。","t":81.08},{"en":"After a long period of rain the river may overflow its banks.","zh":"经过长时间的降雨，河流可能会泛滥。","t":92.66},{"en":"This is a rare occurrence as our climate seldom goes to extremes.","zh":"这很少发生，因为我们这里的气候很少出现极端情况。","t":97.93},{"en":"We are lucky in that only the lower fields,","zh":"我们很幸运，只有较低的田地，","t":103.11},{"en":"which make up a very small proportion of our farm, are affected by flooding,","zh":"这只占我们农场很小的一部分，会受到洪水的影响，","t":106.4},{"en":"but other farms are less favourably sited, and flooding can sometimes spell disaster for their owners.","zh":"但其他农场的位置不太好，洪水有时会给他们的主人带来灾难。","t":111.73},{"en":"One bad winter we watched the river creep up the lower meadows.","zh":"一个糟糕的冬天，我们看着河水悄悄漫上了低洼的草地。","t":120.33},{"en":"All the cattle had been moved into stalls and we stood to lose little.","zh":"所有的牛都已移入畜栏，我们几乎没什么损失。","t":126.04},{"en":"We were, however, worried about our nearest neighbours, whose farm was low lying and who were newcomers to the district.","zh":"然而，我们担心我们最近的邻居，他们的农场地势低洼，而且他们是这个地区的新来者。","t":131.01},{"en":"As the floods had put the telephone out of order, we could not find out how they were managing.","zh":"由于洪水导致电话失灵，我们无法了解他们的情况。","t":140.08},{"en":"From an attic window we could get a sweeping view of the river where their land joined ours,","zh":"从阁楼窗户，我们可以俯瞰河流，看到他们的土地与我们农场相接之处，","t":146.3},{"en":"and at the most critical juncture we took turns in watching that point.","zh":"在最关键的时刻，我们轮流守望那个地方。","t":152.65},{"en":"The first sign of disaster was a dead sheep floating down.","zh":"灾难的第一个迹象是一只死羊顺流而下。","t":157.8},{"en":"Next came a horse, swimming bravely,","zh":"接着来了一匹马，勇敢地游着，","t":162.99},{"en":"but we were afraid that the strength of the current would prevent its landing anywhere before it became exhausted.","zh":"但我们担心水流太急，它在筋疲力尽之前无法靠岸。","t":166.07},{"en":"Suddenly a raft appeared, looking rather like Noah's ark, carrying the whole family, a few hens, the dogs, a cat, and a bird in a cage.","zh":"突然，一个木筏出现了，看起来很像诺亚方舟，上面载着全家人、几只母鸡、狗、猫和一只笼子里的鸟。","t":173.85},{"en":"We realized that they must have become unduly frightened by the rising flood,","zh":"我们意识到他们一定是过度被上涨的洪水吓到了，","t":185.9},{"en":"for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged.","zh":"因为他们的房子地基牢固，即使几乎被淹没，也能坚固地屹立不倒。","t":191.63},{"en":"The men of our family waded down through our flooded meadows with boat hooks,","zh":"我们家的男人们带着船钩，趟过被淹没的草地，","t":200.42},{"en":"in the hope of being able to grapple a corner of the raft and pull it out of the current towards our bank.","zh":"希望能钩住木筏的一角，把它从水流中拉到我们这边的岸边。","t":205.34},{"en":"We still think it a miracle that they were able to do so.","zh":"我们仍然认为他们能做到这一点是个奇迹。","t":213.53}],"vocab":[{"word":"boundary","phonetic":"/ˈbaʊndri/","meanings":[{"pos":"noun","meaning":"边界，分界线","usage":"指两个地区或区域之间的界限"}]},{"word":"predecessor","phonetic":"/ˈpriːdɪsesə(r)/","meanings":[{"pos":"noun","meaning":"前任，前辈","usage":"指在同一职位或角色上之前的人"}]},{"word":"backwater","phonetic":"/ˈbækwɔːtə(r)/","meanings":[{"pos":"noun","meaning":"回水湾，死水区","usage":"河流中水流缓慢或静止的区域"}]},{"word":"overflow","phonetic":"/ˌəʊvəˈfləʊ/","meanings":[{"pos":"verb","meaning":"溢出，泛滥","usage":"液体超出容器或河岸的界限"},{"pos":"noun","meaning":"溢出，溢流","usage":"指泛滥的情况"}]},{"word":"occurrence","phonetic":"/əˈkʌrəns/","meanings":[{"pos":"noun","meaning":"发生的事件，偶发的事","usage":"指发生的事情或事件"}]},{"word":"wade","phonetic":"/weɪd/","meanings":[{"pos":"verb","meaning":"涉水，趟水","usage":"在浅水中行走"}]},{"word":"grapple","phonetic":"/ˈɡræpl/","meanings":[{"pos":"verb","meaning":"抓住，抓紧","usage":"用力抓住某物"},{"pos":"verb","meaning":"努力解决（问题）","usage":"grapple with something 表示努力处理棘手问题"}]},{"word":"raft","phonetic":"/rɑːft/","meanings":[{"pos":"noun","meaning":"木筏，竹筏","usage":"由木材绑在一起做成的水上交通工具"}]},{"word":"unduly","phonetic":"/ˌʌnˈdjuːli/","meanings":[{"pos":"adverb","meaning":"过度地，不适当地","usage":"超出正常或合理程度"}]},{"word":"sweeping","phonetic":"/ˈswiːpɪŋ/","meanings":[{"pos":"adjective","meaning":"一览无余的，广阔的","usage":"形容视野开阔，涵盖范围广"}]},{"word":"juncture","phonetic":"/ˈdʒʌŋktʃə(r)/","meanings":[{"pos":"noun","meaning":"时刻，关头","usage":"at this juncture 表示在这个关键时刻"}]},{"word":"exhausted","phonetic":"/ɪɡˈzɔːstɪd/","meanings":[{"pos":"adjective","meaning":"筋疲力尽的，疲惫的","usage":"指极度疲劳的状态"}]},{"word":"proportion","phonetic":"/prəˈpɔːʃn/","meanings":[{"pos":"noun","meaning":"比例，部分","usage":"指整体中的份额或比率"}]},{"word":"crowning","phonetic":"/ˈkraʊnɪŋ/","meanings":[{"pos":"adjective","meaning":"加冕的，顶点的","usage":"表示最崇高或最重要的"}]},{"word":"current","phonetic":"/ˈkʌrənt/","meanings":[{"pos":"noun","meaning":"水流，潮流","usage":"指河流中水的流动"},{"pos":"adjective","meaning":"当前的，现在的","usage":"指当前的、正在发生的"}]}],"phrases":[{"phrase":"play an important part in","usage":"在...中起重要作用","examples":[{"en":"The river has always played an important part in our lives.","zh":"这条河在我们的生活中一直扮演着重要的角色。"}]},{"phrase":"make a living","usage":"谋生，维持生计","examples":[{"en":"Without it we could not make a living.","zh":"没有它，我们无法谋生。"}]},{"phrase":"take turns","usage":"轮流，依次","examples":[{"en":"We took turns in watching that point.","zh":"我们轮流监视那个地点。"}]},{"phrase":"in the hope of","usage":"怀着...的希望","examples":[{"en":"The men waded down with boat hooks in the hope of being able to grapple a corner of the raft.","zh":"男人们涉水走下去，带着船钩，希望能够抓住木筏的一角。"}]},{"phrase":"put out of order","usage":"使出故障，使损坏","examples":[{"en":"The floods had put the telephone out of order.","zh":"洪水使电话出了故障。"}]},{"phrase":"spell disaster","usage":"意味着灾难，预示灾祸","examples":[{"en":"Flooding can sometimes spell disaster for their owners.","zh":"洪水有时会给农场主带来灾难。"}]},{"phrase":"at the most critical juncture","usage":"在最关键的时刻","examples":[{"en":"At the most critical juncture we took turns in watching that point.","zh":"在最关键的时刻，我们轮流监视那个地点。"}]},{"phrase":"look rather like","usage":"看起来有点像","examples":[{"en":"A raft appeared, looking rather like Noah's ark.","zh":"一个木筏出现了，看起来有点像诺亚方舟。"}]},{"phrase":"stand to lose","usage":"可能失去，注定要损失","examples":[{"en":"We stood to lose little.","zh":"我们损失不大。"}]},{"phrase":"a proportion of","usage":"...的一部分","examples":[{"en":"The lower fields make up a very small proportion of our farm.","zh":"地势较低的田地只占我们农场的一小部分。"}]}],"grammar":[{"title":"过去完成时 (Past Perfect Tense)","definition":"表示在过去某一时间点之前已经完成的动作，强调'过去的过去'。常与一般过去时连用，构成时间上的先后关系。","structure":"主语 + had + 过去分词","usage":"用于叙述两个过去的动作，先发生的动作用过去完成时，后发生的动作用一般过去时。也用于after, before, when, as soon as等时间连词引导的复合句中。","examples":[{"en":"After the floods had put the telephone out of order, we could not find out how they were managing.","zh":"洪水使电话出现故障后，我们无法了解他们如何应对。"},{"en":"We realized that they must have become unduly frightened by the rising flood.","zh":"我们意识到他们一定是因上涨的洪水而过度惊慌了。"}]},{"title":"关系从句（限制性定语从句）","definition":"用来修饰名词或代词的从句，为句子提供必要的限定信息，不能省略。由关系代词（who, whom, which, that）或关系副词（where, when, why）引导。","structure":"主句 + 关系代词/副词 + 从句","usage":"当先行词是物时，用which或that；当先行词是人时，用who, whom或that。关系副词where代替介词+which表示地点。","examples":[{"en":"The river which forms the eastern boundary of our farm has always played an important part in our lives.","zh":"形成我们农场东边边界的这条河在我们的生活中一直扮演着重要的角色。"},{"en":"We went upstream to a favourite backwater, where we sometimes had our party.","zh":"我们有时会到上游一个喜欢的回水湾去，在那里举办聚会。"}]},{"title":"情态动词must have done（对过去事实的肯定推测）","definition":"must + have + 过去分词表示对过去发生的事情的肯定推测，意为'一定...'。否定推测用can't have done，意为'不可能...'。","structure":"主语 + must have + 过去分词","usage":"用于对过去发生的事实进行有把握的推测，语气较强。","examples":[{"en":"We realized that they must have become unduly frightened by the rising flood.","zh":"我们意识到他们一定是因上涨的洪水而过度惊慌了。"},{"en":"He must have passed the exam because he studied so hard.","zh":"他一定通过考试了，因为他学习很努力。"}]}],"patterns":[{"pattern":"The river which/that + 动词...has always played an important part in our lives.","explanation":"","original":{"en":"The river which forms the eastern boundary of our farm has always played an important part in our lives.","zh":"形成我们农场东边边界的这条河在我们的生活中一直扮演着重要的角色。"},"examples":[{"en":"The tree that stands in our garden has always provided us with shade in summer.","zh":"长在我们花园里的那棵树在夏天一直为我们提供阴凉。"},{"en":"The tradition which our family keeps has always played an important part in our life.","zh":"我们家族保持的传统在我们的生活中一直扮演着重要的角色。"}]},{"pattern":"Without + 名词, we could not/couldn't + 动词原形.","explanation":"","original":{"en":"Without it we could not make a living.","zh":"没有它，我们无法谋生。"},"examples":[{"en":"Without water, nothing could survive in the desert.","zh":"没有水，沙漠中任何东西都无法生存。"},{"en":"Without your help, I could not have finished this task on time.","zh":"没有你的帮助，我不可能按时完成这项任务。"}]},{"pattern":"We were worried about + 名词/代词, who/which...","explanation":"","original":{"en":"We were, however, worried about our nearest neighbours, whose farm was low lying and who were newcomers to the district.","zh":"然而，我们担心的是我们的近邻，他们的农场地势低洼，而且他们是刚搬到这个地区的。"},"examples":[{"en":"I was worried about my younger brother, who had to travel alone in the storm.","zh":"我担心我的弟弟，他不得不在暴风雨中独自旅行。"},{"en":"She was worried about her son, who was always late for school.","zh":"她担心她的儿子，他总是上学迟到。"}]},{"pattern":"The first sign of + 名词 was + 名词/动名词...","explanation":"","original":{"en":"The first sign of disaster was a dead sheep floating down.","zh":"灾难的第一个迹象是一只死羊漂浮下来。"},"examples":[{"en":"The first sign of spring was the flowers blooming in the garden.","zh":"春天的第一个迹象是花园里花朵绽放。"},{"en":"The first sign of trouble was the dark clouds gathering in the sky.","zh":"麻烦的第一个迹象是天空乌云密布。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“时刻，关头” 对应的单词是？","hint":"noun · /ˈdʒʌŋktʃə(r)/","options":["curiously","narrowly","juncture","dismay"],"answer":2,"explain":"juncture · /ˈdʒʌŋktʃə(r)/ · noun · 时刻，关头。at this juncture 表示在这个关键时刻","source":{"kind":"vocab","word":"juncture"},"id":"b3-u56-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：涉水，趟水","hint":"/weɪd/ · verb","answer":"wade","placeholder":"输入英文单词","explain":"wade · /weɪd/ · verb · 涉水，趟水。在浅水中行走","source":{"kind":"vocab","word":"wade"},"id":"b3-u56-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：The men waded down with boat hooks _____ being able to grapple a corner of the raft.","hint":"男人们涉水走下去，带着船钩，希望能够抓住木筏的一角。","answer":"in the hope of","placeholder":"输入缺失的短语","explain":"in the hope of：怀着...的希望（男人们涉水走下去，带着船钩，希望能够抓住木筏的一角。）","source":{"kind":"phrase","phrase":"in the hope of"},"id":"b3-u56-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Sometimes we go upstream to a _____ backwater,","hint":"有时我们逆流而上到我们最喜欢的一个回水湾，","answer":"favourite","placeholder":"输入缺失的单词","explain":"Sometimes we go upstream to a favourite backwater, — 有时我们逆流而上到我们最喜欢的一个回水湾，","source":{"kind":"sentence","en":"Sometimes we go upstream to a favourite backwater,"},"id":"b3-u56-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“用来修饰名词或代词的从句，为句子提供必要的限定信息，不能省略。由关系代词（who, whom, which, that）或关系副词（where, when, why）引导。” 描述的是哪个语法点？","hint":"主句 + 关系代词/副词 + 从句","options":["定语从句中的“介词+which”结构","as if引导的虚拟语气","虚拟条件句的倒装","关系从句（限制性定语从句）"],"answer":3,"explain":"关系从句（限制性定语从句）：主句 + 关系代词/副词 + 从句：当先行词是物时，用which或that；当先行词是人时，用who, whom或that。关系副词where代替介词+which表示地点。","source":{"kind":"grammar","title":"关系从句（限制性定语从句）"},"id":"b3-u56-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nWe still think it a miracle that they were able to do so.","hint":"","options":["没找到什么有价值的东西，","我们仍然认为他们能做到这一点是个奇迹。","他挣的钱将只有以前的一半，但他觉得地位的提升，很值得损失这点钱。","幸运的是，正当我不知下一步该怎么办的时候，"],"answer":1,"explain":"We still think it a miracle that they were able to do so. — 我们仍然认为他们能做到这一点是个奇迹。","source":{"kind":"sentence","en":"We still think it a miracle that they were able to do so."},"id":"b3-u56-q06"}]},{"id":"b3-u57","book":3,"unit":57,"key":"57","lessonFrom":57,"lessonTo":57,"title":"Back in the Old Country","titleZh":"回到故乡","question":"Did the narrator find his mother's grave?","sentences":[{"en":"I stopped to let the car cool off and to study the map.","zh":"我停车让车冷却下来，并研究地图。","t":13.98},{"en":"I had expected to be near my objective by now, but everything still seemed alien to me.","zh":"我本以为现在应该离目的地很近了，但周围的一切对我来说仍然很陌生。","t":18.28},{"en":"I was only five when my father had taken me abroad, and that was eighteen years ago.","zh":"我父亲带我出国时我才五岁，那已经是十八年前的事了。","t":25.73},{"en":"When my mother had died after a tragic accident, he did not quickly recover from the shock and loneliness.","zh":"母亲在一场悲惨的事故中去世后，他未能很快从震惊和孤独中恢复过来。","t":32.35},{"en":"Everything around him was full of her presence, continually reopening the wound.","zh":"他周围的一切都充满了她的气息，不断地撕开他的伤口。","t":40.37},{"en":"So he decided to emigrate.","zh":"所以他决定移民。","t":46.02},{"en":"In the new country he became absorbed in making a new life for the two of us, so that he gradually ceased to grieve.","zh":"在新的国家，他全心投入为我们俩创造新生活，于是他渐渐停止了悲伤。","t":48.41},{"en":"He did not marry again and I was brought up without a woman's care; but I lacked for nothing, for he was both father and mother to me.","zh":"他没有再婚，我是在没有女性关爱的情况下长大的；但我什么都不缺，因为他既是我的父亲也是我的母亲。","t":57.04},{"en":"He always meant to go back one day, but not to stay.","zh":"他一直打算有一天回去，但不是为了留下。","t":66.9},{"en":"His roots and mine had become too firmly embedded in the new land.","zh":"他和我的根基都已在新土地上扎得太深了。","t":70.65},{"en":"But he wanted to see the old folk again and to visit my mother's grave.","zh":"但他想再见见老乡们，并去我母亲的坟墓看看。","t":75.54},{"en":"He became mortally ill a few months before we had planned to go and, when he knew that he was dying, he made me promise to go on my own.","zh":"在我们计划动身前的几个月，他得了绝症，当他知道自己快要去世时，他让我答应独自前往。","t":80.32},{"en":"I hired a car the day after landing and bought a comprehensive book of maps,","zh":"降落的第二天，我租了一辆车，买了一本详尽的地图册，","t":91.44},{"en":"which I found most helpful on the cross-country journey, but which I did not think I should need on the last stage.","zh":"我发现这本地图册在跨国旅途中非常有用，但我不认为在最后一段路程中我还需要它。","t":96.93},{"en":"It was not that I actually remembered anything at all.","zh":"并不是我真的记得任何东西。","t":104.62},{"en":"But my father had described over and over again what we should see at every milestone after leaving the nearest town,","zh":"但父亲曾一遍又一遍地描述，离开最近的城镇后，每过一个里程碑我们会看到什么，","t":108.56},{"en":"so that I was positive I should recognize it as familiar territory.","zh":"所以我确信我会认出那是熟悉的土地。","t":117.66},{"en":"Well, I had been wrong, for I was now lost.","zh":"嗯，我错了，因为我现在迷路了。","t":122.93},{"en":"I looked at the map and then at the milometer.","zh":"我看了看地图，然后看了看里程表。","t":127.74},{"en":"I had come ten miles since leaving the town and at this point, according to my father,","zh":"我离开城镇已经走了十英里，按照我父亲的说法，在这个地方，","t":131.33},{"en":"I should be looking at farms and cottages in a valley,","zh":"我应该能看到山谷里的农场和小屋，","t":138.39},{"en":"with the spire of the church of our village showing in the far distance.","zh":"远处还能看到我们村教堂的尖顶。","t":142.48},{"en":"I could see no valley, no farms, no cottages and no church spire-only a lake.","zh":"我看不到山谷，看不到农场，看不到小屋，也看不到教堂尖顶——只有一片湖。","t":147.63},{"en":"I decided that I must have taken a wrong turning somewhere.","zh":"我断定我一定是在某个地方拐错了弯。","t":154.88},{"en":"So I drove back to the town and began to retrace the route, taking frequent glances at the map.","zh":"于是我开车回到城镇，开始按原路返回，并不时地看一眼地图。","t":159.19},{"en":"I landed up at the same corner.","zh":"我最终还是回到了同一个路口。","t":166.44},{"en":"The curious thing was that the lake was not marked on the map.","zh":"奇怪的是，地图上并没有标示这片湖。","t":169.18},{"en":"I felt as if I had stumbled into a nightmare country, as you sometimes do in dreams.","zh":"我感觉自己好像偶然闯入了一个噩梦般的国度，就像你在梦中有时会遇到的那样。","t":173.27},{"en":"And, as in a nightmare, there was nobody in sight to help me.","zh":"就像在噩梦中一样，四周没有人能帮助我。","t":179.55},{"en":"Fortunately for me, as I was wondering what to do next,","zh":"幸运的是，正当我不知下一步该怎么办的时候，","t":184.43},{"en":"there appeared on the horizon a man on horseback, riding in my direction.","zh":"地平线上出现了一位骑马的人，正朝我这个方向骑来。","t":188.52},{"en":"I waited till he came near, then I asked him the way to our old village.","zh":"我等到他走近，然后问他去我们那个老村子的路。","t":194.01},{"en":"He said that there was now no village.","zh":"他说现在已经没有那个村子了。","t":199.45},{"en":"I thought he must have misunderstood me, so I repeated its name.","zh":"我以为他一定是误解了我的意思，所以我又重复了一遍村子的名字。","t":202.51},{"en":"This time he pointed to the lake.","zh":"这次他指向了湖面。","t":208.08},{"en":"The village no longer existed because it had been submerged, and all the valley too.","zh":"那个村子已经不复存在了，因为它连同整个山谷都被淹没了。","t":211.15},{"en":"The lake was not a natural one, but a man-made reservoir.","zh":"那片湖不是天然形成的，而是一个人工水库。","t":218.49}],"vocab":[{"word":"alien","phonetic":"/ˈeɪliən/","meanings":[{"pos":"adj.","meaning":"陌生的；异国的","usage":"形容对某人来说不熟悉、格格不入的事物"},{"pos":"n.","meaning":"外国人；外星人","usage":"指来自其他国家的人或生物"}]},{"word":"tragic","phonetic":"/ˈtrædʒɪk/","meanings":[{"pos":"adj.","meaning":"悲剧的；悲惨的","usage":"用于描述非常悲伤、令人痛心的事件或情况"}]},{"word":"emigrate","phonetic":"/ˈemɪɡreɪt/","meanings":[{"pos":"v.","meaning":"移居外国；移民","usage":"指从本国移居到另一个国家，强调离开的动作"}]},{"word":"absorb","phonetic":"/əbˈzɔːb/","meanings":[{"pos":"v.","meaning":"吸收；使全神贯注","usage":"be absorbed in表示专注于某事，沉迷其中"}]},{"word":"grieve","phonetic":"/ɡriːv/","meanings":[{"pos":"v.","meaning":"感到悲伤；哀悼","usage":"指因失去某人或某事而感到悲伤和痛苦"}]},{"word":"mortally","phonetic":"/ˈmɔːtəli/","meanings":[{"pos":"adv.","meaning":"致命地；极其","usage":"修饰形容词或动词，表示达到致死的程度"}]},{"word":"milestone","phonetic":"/ˈmaɪlstəʊn/","meanings":[{"pos":"n.","meaning":"里程碑；重大事件","usage":"字面意思是道路上的里程标记，比喻人生或历史上的重要阶段"}]},{"word":"positive","phonetic":"/ˈpɒzətɪv/","meanings":[{"pos":"adj.","meaning":"确信的；积极的","usage":"表示对某事非常有把握、确定无疑"}]},{"word":"spire","phonetic":"/ˈspaɪə(r)/","meanings":[{"pos":"n.","meaning":"尖顶；尖塔","usage":"通常指教堂或塔楼顶部的尖形结构"}]},{"word":"submerge","phonetic":"/səbˈmɜːdʒ/","meanings":[{"pos":"v.","meaning":"淹没；浸没","usage":"指将某物置于水面以下，或被水覆盖"}]},{"word":"reservoir","phonetic":"/ˈrezəvwɑː(r)/","meanings":[{"pos":"n.","meaning":"水库；蓄水池","usage":"指人工建造的用于储水的水体"}]},{"word":"cottage","phonetic":"/ˈkɒtɪdʒ/","meanings":[{"pos":"n.","meaning":"小屋；村舍","usage":"指乡村的小房子，通常只有一层或两层"}]},{"word":"retract","phonetic":"/rɪˈtrækt/","meanings":[{"pos":"v.","meaning":"收回；撤回","usage":"指收回说过的话或采取的行动，也可指缩回"}]},{"word":"nightmare","phonetic":"/ˈnaɪtmeə(r)/","meanings":[{"pos":"n.","meaning":"噩梦；可怕的事","usage":"指令人恐惧或痛苦的梦，也比喻可怕的经历"}]},{"word":"glance","phonetic":"/ɡlɑːns/","meanings":[{"pos":"n./v.","meaning":"一瞥；扫视","usage":"指快速地看一眼，强调动作的短暂性"}]}],"phrases":[{"phrase":"cool off","usage":"使冷却；冷静下来","examples":[{"en":"I stopped to let the car cool off.","zh":"我停下来让汽车冷却下来。"}]},{"phrase":"be absorbed in","usage":"专心于；全神贯注于","examples":[{"en":"He became absorbed in making a new life for the two of us.","zh":"他全神贯注地为我们俩创造新生活。"}]},{"phrase":"lack for nothing","usage":"什么都不缺","examples":[{"en":"I lacked for nothing, for he was both father and mother to me.","zh":"我什么都不缺，因为他既当父亲又当母亲。"}]},{"phrase":"take a wrong turning","usage":"走错路；拐错弯","examples":[{"en":"I decided that I must have taken a wrong turning somewhere.","zh":"我认定我一定是某个地方拐错弯了。"}]},{"phrase":"in the far distance","usage":"在远处","examples":[{"en":"The spire of the church of our village showing in the far distance.","zh":"我们村庄教堂的尖顶在远处显现出来。"}]},{"phrase":"in sight","usage":"看得见；在视野中","examples":[{"en":"There was nobody in sight to help me.","zh":"看不到有任何人在场能帮我。"}]},{"phrase":"come back","usage":"回来；返回","examples":[{"en":"He always meant to go back one day, but not to stay.","zh":"他一直打算有一天回去，但不是为了留下来。"}]},{"phrase":"make a promise","usage":"许诺；承诺","examples":[{"en":"He made me promise to go on my own.","zh":"他让我答应独自去。"}]},{"phrase":"wonder what to do","usage":"不知道该做什么","examples":[{"en":"As I was wondering what to do next, a man appeared.","zh":"正当我在想下一步该怎么办时，一个人出现了。"}]},{"phrase":"point to","usage":"指向","examples":[{"en":"This time he pointed to the lake.","zh":"这次他指向了那个湖。"}]}],"grammar":[{"title":"过去完成时（Past Perfect Tense）","definition":"表示在过去某一时间之前已经完成的动作或状态，即\"过去的过去\"","structure":"had + 过去分词","usage":"当叙述过去发生的事件时，需要表示更早发生的动作或情况时使用。常与by the time, before, after等连用，或用于宾语从句中表示过去的过去。","examples":[{"en":"I had expected to be near my objective by now.","zh":"我原本以为现在已经接近目的地了。"},{"en":"I was only five when my father had taken me abroad.","zh":"我父亲带我出国时我只有五岁。"}]},{"title":"过去完成进行时（Past Perfect Continuous）","definition":"表示过去某个时间之前一直在进行的动作","structure":"had been + 动词-ing形式","usage":"强调动作的持续性和进行过程，常与for或since连用。","examples":[{"en":"He had been describing over and over again what we should see.","zh":"他曾一遍又一遍地描述我们会看到什么。"}]},{"title":"used to 与 would 的区别","definition":"used to表示过去的习惯性动作或状态，常含有与现在对比的意味；would只表示过去反复发生的动作，不表示状态","structure":"used to + 动词原形 / would + 动词原形","usage":"used to可以表示\"曾经是\"（状态）或\"过去常常\"（动作），而would只用于重复的动作。","examples":[{"en":"He always meant to go back one day, but not to stay.","zh":"他一直打算有一天回去，但不是为了留下来。"},{"en":"My father had described over and over again what we should see.","zh":"我父亲曾一遍又一遍地描述我们会看到什么。"}]}],"patterns":[{"pattern":"I had expected to + 动词原形, but...","explanation":"","original":{"en":"I had expected to be near my objective by now, but everything still seemed alien to me.","zh":"我原本以为现在已经接近目的地了，但一切对我来说仍然很陌生。"},"examples":[{"en":"I had expected to finish the work on time, but I ran out of time.","zh":"我原本以为能按时完成工作，但我时间不够了。"},{"en":"She had expected to meet him at the station, but he never came.","zh":"她原本以为会在车站见到他，但他根本没来。"}]},{"pattern":"It was not that..., but...","explanation":"","original":{"en":"It was not that I actually remembered anything at all. But my father had described over and over again...","zh":"并不是我真的记得什么。而是我父亲曾一遍又一遍地描述……"},"examples":[{"en":"It was not that she didn't want to help, but she really had no time.","zh":"并不是她不想帮忙，而是她真的没有时间。"},{"en":"It was not that he was lazy, but he simply didn't know how to start.","zh":"并不是他懒惰，而是他根本不知道如何开始。"}]},{"pattern":"The curious thing was that...","explanation":"","original":{"en":"The curious thing was that the lake was not marked on the map.","zh":"奇怪的是那个湖在地图上并没有标注。"},"examples":[{"en":"The curious thing was that he knew the answer but refused to tell.","zh":"奇怪的是他知道答案却不肯说。"},{"en":"The curious thing was that the door was open but nobody was inside.","zh":"奇怪的是门开着但里面没有人。"}]},{"pattern":"...no longer + 动词/存在","explanation":"","original":{"en":"The village no longer existed because it had been submerged.","zh":"那个村庄不再存在了，因为它已经被淹没了。"},"examples":[{"en":"He no longer lives in this city.","zh":"他不再住在这个城市了。"},{"en":"This factory no longer produces plastic bags.","zh":"这家工厂不再生产塑料袋了。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“水库；蓄水池” 对应的单词是？","hint":"n. · /ˈrezəvwɑː(r)/","options":["multimedia","reservoir","immortal","temporarily"],"answer":1,"explain":"reservoir · /ˈrezəvwɑː(r)/ · n. · 水库；蓄水池。指人工建造的用于储水的水体","source":{"kind":"vocab","word":"reservoir"},"id":"b3-u57-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：小屋；村舍","hint":"/ˈkɒtɪdʒ/ · n.","answer":"cottage","placeholder":"输入英文单词","explain":"cottage · /ˈkɒtɪdʒ/ · n. · 小屋；村舍。指乡村的小房子，通常只有一层或两层","source":{"kind":"vocab","word":"cottage"},"id":"b3-u57-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：I stopped to let the car _____.","hint":"我停下来让汽车冷却下来。","answer":"cool off","placeholder":"输入缺失的短语","explain":"cool off：使冷却；冷静下来（我停下来让汽车冷却下来。）","source":{"kind":"phrase","phrase":"cool off"},"id":"b3-u57-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：Everything around him was full of her _____ continually reopening the wound.","hint":"他周围的一切都充满了她的气息，不断地撕开他的伤口。","answer":"presence","placeholder":"输入缺失的单词","explain":"Everything around him was full of her presence, continually reopening the wound. — 他周围的一切都充满了她的气息，不断地撕开他的伤口。","source":{"kind":"sentence","en":"Everything around him was full of her presence, continually reopening the wound."},"id":"b3-u57-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“used to表示过去的习惯性动作或状态，常含有与现在对比的意味；would只表示过去反复发生的动作，不表示状态” 描述的是哪个语法点？","hint":"used to + 动词原形 / would + 动词原形","options":["used to 与 would 的区别","more than + n./adj. (不仅仅；超出)","过去完成时被动态 (Past Perfect Passive)","虚拟语气 (Subjunctive Mood) - 与现在事实相反"],"answer":0,"explain":"used to 与 would 的区别：used to + 动词原形 / would + 动词原形：used to可以表示\"曾经是\"（状态）或\"过去常常\"（动作），而would只用于重复的动作。","source":{"kind":"grammar","title":"used to 与 would 的区别"},"id":"b3-u57-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nWell, I had been wrong, for I was now lost.","hint":"","options":["他多喝了一点酒，这对他身体不好。","律师证实，一名警察确实曾多次粗暴对待外国人。","嗯，我错了，因为我现在迷路了。","我重新组装好机器后，发现它仍然无法工作，对此我并不感到惊讶，"],"answer":2,"explain":"Well, I had been wrong, for I was now lost. — 嗯，我错了，因为我现在迷路了。","source":{"kind":"sentence","en":"Well, I had been wrong, for I was now lost."},"id":"b3-u57-q06"}]},{"id":"b3-u58","book":3,"unit":58,"key":"58","lessonFrom":58,"lessonTo":58,"title":"A Spot of Bother","titleZh":"一点麻烦","question":"What did the old lady find when she got home?","sentences":[{"en":"The old lady was glad to be back at the block of flats where she lived.","zh":"老太太很高兴回到她住的公寓楼。","t":14.73},{"en":"Her shopping had tired her and her basket had grown heavier with every step of the way home.","zh":"购物让她感到疲惫，回家的每一步都让她手里的篮子变得更沉。","t":20.86},{"en":"In the lift her thoughts were on lunch and a good rest;","zh":"在电梯里，她想着午餐和好好休息；","t":28.27},{"en":"but when she got out at her own floor, both were forgotten in her sudden discovery that her front door was open.","zh":"但当她走出电梯到达自己的楼层时，她突然发现前门开着，午餐和休息都被抛到了脑后。","t":32.65},{"en":"She was thinking that she must reprimand her home help the next morning for such a monstrous piece of negligence,","zh":"她心想，明天早上一定要训斥她的家政人员，因为她如此严重的疏忽，","t":42.07},{"en":"when she remembered that she had gone shopping after the home help had left and she knew that she had turned both keys in their locks.","zh":"但她随即想起，家政人员离开后她才去购物，而且她确定自己把两把钥匙都锁好了。","t":50.44},{"en":"She walked slowly into the hall and at once noticed that all the room doors were open,","zh":"她慢慢地走进门厅，立刻注意到所有的房门都开着，","t":60.63},{"en":"yet following her regular practice she had shut them before going out.","zh":"然而按照她的习惯，出门前她都会关好门。","t":67.58},{"en":"Looking into the drawing room, she saw a scene of confusion over by her writing desk.","zh":"往客厅里一看，她看到写字台附近一片混乱。","t":72.69},{"en":"It was as clear as daylight then that burglars had forced an entry during her absence.","zh":"这时，她才明白，在她外出期间，窃贼破门而入了，这简直是明摆着的事。","t":79.28},{"en":"Her first impulse was to go round all the rooms looking for the thieves,","zh":"她最初的冲动是把所有房间都找一遍，看看有没有小偷，","t":85.89},{"en":"but then she decided that at her age it might be more prudent to have someone with her,","zh":"但后来她觉得，以她的年纪，找个人陪着会更稳妥，","t":91.23},{"en":"so she went to fetch the porter from his basement.","zh":"于是她下楼去地下室找看门人。","t":97.62},{"en":"By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea, while he telephoned the police.","zh":"这时她的双腿开始颤抖，于是她坐下来，喝了一杯很浓的茶，看门人则打电话报了警。","t":101.71},{"en":"Then, her composure regained, she was ready to set off with the porter's assistance to search for any intruders who might still be lurking in her flat.","zh":"恢复镇定后，她在看门人的协助下准备出发，搜寻可能仍藏在她公寓里的不速之客。","t":112.27},{"en":"They went through the rooms, being careful to touch nothing,","zh":"他们检查了各个房间，小心翼翼地不碰任何东西，","t":124.54},{"en":"as they did not want to hinder the police in their search for fingerprints.","zh":"因为他们不想妨碍警方寻找指纹。","t":128.73},{"en":"The chaos was inconceivable.","zh":"现场一片狼藉，简直难以置信。","t":133.88},{"en":"She had lived in the flat for thirty years and was a veritable magpie at hoarding:","zh":"她在这间公寓住了三十年，是个名副其实的“喜鹊”，喜欢囤积物品：","t":137.27},{"en":"and it seemed as though everything she possessed had been tossed out and turned over and over.","zh":"似乎她所有的东西都被翻了出来，翻了个底朝天。","t":143.59},{"en":"At least sorting out the things she should have discarded years ago was now being made easier for her.","zh":"至少，现在整理那些她几年前就该扔掉的东西变得容易多了。","t":151.08},{"en":"Then a police inspector arrived with a constable and she told them of her discovery of the ransacked flat.","zh":"随后，一名警督带着一名警员赶到，她向他们讲述了她发现公寓被洗劫一空的情况。","t":158.73},{"en":"The inspector began to look for fingerprints, while the constable checked that the front door locks had not been forced,","zh":"警督开始寻找指纹，而警员则检查前门锁是否没有被撬，","t":167.15},{"en":"thereby proving that the burglars had either used skeleton keys or entered over the balcony.","zh":"这证明窃贼要么使用了万能钥匙，要么是从阳台进入的。","t":174.4},{"en":"There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewellery which the old lady said was not hers.","zh":"没有指纹痕迹，但警督发现了一个脏兮兮的红色包裹，里面装着珠宝，老太太说那不是她的。","t":182.03},{"en":"So their entry into this flat was apparently not the burglars' first job that day and they must have been disturbed.","zh":"所以他们闯入这间公寓显然不是窃贼当天做的第一起案子，而且他们一定是在作案时受到了惊扰。","t":193.07},{"en":"The inspector then asked the old lady to try to check what was missing by the next day,","zh":"警督随后要求老太太在第二天之前尽量清点一下丢失的物品，","t":201.84},{"en":"and advised her not to stay alone in the flat for a few nights.","zh":"并建议她几晚不要独自待在公寓里。","t":208.2},{"en":"The old lady thought he was a fussy creature,","zh":"老太太觉得他是个爱挑剔的人，","t":212.81},{"en":"but since the porter agreed with him, she rang up her daughter and asked for her help in what she described as a little spot of bother.","zh":"但看门人也同意他的看法，于是她打电话给女儿，请她帮忙解决她所说的“一点小麻烦”。","t":216.47}],"vocab":[{"word":"bother","phonetic":"/ˈbɒðə(r)/","meanings":[{"pos":"noun","meaning":"麻烦；烦恼","usage":"常用a spot of bother表示小麻烦"},{"pos":"verb","meaning":"打扰；使烦恼","usage":"常用于口语中表示打扰某人"}]},{"word":"flat","phonetic":"/flæt/","meanings":[{"pos":"noun","meaning":"公寓；一套房间","usage":"英式英语中常用，美式英语用apartment"}]},{"word":"reprimand","phonetic":"/ˈreprɪmɑːnd/","meanings":[{"pos":"verb","meaning":"训斥；谴责","usage":"正式用词，指严厉地批评或责备"}]},{"word":"negligence","phonetic":"/ˈneglɪdʒəns/","meanings":[{"pos":"noun","meaning":"疏忽；粗心大意","usage":"指由于不注意而造成的错误或疏忽"}]},{"word":"prudent","phonetic":"/ˈpruːdnt/","meanings":[{"pos":"adjective","meaning":"谨慎的；慎重的","usage":"形容做事深思熟虑、小心谨慎"}]},{"word":"composure","phonetic":"/kəmˈpəʊʒə(r)/","meanings":[{"pos":"noun","meaning":"镇定；沉着的姿态","usage":"指在困难情况下保持冷静的能力"}]},{"word":"lurk","phonetic":"/lɜːk/","meanings":[{"pos":"verb","meaning":"潜伏；暗藏","usage":"指隐藏在暗处等待时机"}]},{"word":"fingerprint","phonetic":"/ˈfɪŋɡəprɪnt/","meanings":[{"pos":"noun","meaning":"指纹","usage":"指手指留下的纹路，用于身份识别"}]},{"word":"inconceivable","phonetic":"/ˌɪnkənˈsiːvəbl/","meanings":[{"pos":"adjective","meaning":"难以置信的；不可思议的","usage":"指某事令人难以想象或相信"}]},{"word":"magpie","phonetic":"/ˈmæɡpaɪ/","meanings":[{"pos":"noun","meaning":"喜鹊；收藏狂","usage":"原指喜鹊，因其收集习惯比喻爱收集东西的人"}]},{"word":"hoard","phonetic":"/hɔːd/","meanings":[{"pos":"verb","meaning":"囤积；贮藏","usage":"指储藏钱或物品以备将来使用"}]},{"word":"ransack","phonetic":"/ˈrænsæk/","meanings":[{"pos":"verb","meaning":"彻底搜查；洗劫","usage":"指为寻找东西而翻遍某处"}]},{"word":"jewellery","phonetic":"/ˈdʒuːəlri/","meanings":[{"pos":"noun","meaning":"珠宝；首饰","usage":"珠宝的总称，不可数名词"}]},{"word":"disturb","phonetic":"/dɪˈstɜːb/","meanings":[{"pos":"verb","meaning":"打扰；打扰","usage":"指打断某人的活动或使某人担忧"}]},{"word":"fussy","phonetic":"/ˈfʌsi/","meanings":[{"pos":"adjective","meaning":"大惊小怪的；挑剔的","usage":"形容人对小事过分担心或挑剔"}]}],"phrases":[{"phrase":"a spot of bother","usage":"表示小麻烦、小纠纷，是英语中常用的委婉表达","examples":[{"en":"She described it as a little spot of bother.","zh":"她把这描述为一点小麻烦。"}]},{"phrase":"force an entry","usage":"指通过武力或强行手段进入某处","examples":[{"en":"Burglars had forced an entry during her absence.","zh":"窃贼趁她不在时强行闯入了。"}]},{"phrase":"at her age","usage":"表示在某人这个年纪，常用于表达某种行为是否适合某人的年龄","examples":[{"en":"At her age, it might be more prudent to have someone with her.","zh":"在她这个年纪，有人陪着可能更明智。"}]},{"phrase":"turn over","usage":"指把东西翻过来或翻遍","examples":[{"en":"Everything she possessed had been tossed out and turned over.","zh":"她的所有东西都被扔了出来，翻了个遍。"}]},{"phrase":"lose one's composure","usage":"指失去镇定，变得慌张","examples":[{"en":"She regained her composure and was ready to search.","zh":"她恢复了镇定，准备开始搜查。"}]},{"phrase":"be not the first job","usage":"表示不是第一次做某事，暗示之前有过类似经历","examples":[{"en":"Their entry into this flat was apparently not the burglars' first job that day.","zh":"他们进入这间公寓显然不是当天第一次作案。"}]},{"phrase":"ring up","usage":"指打电话，是口语中常见的表达","examples":[{"en":"She rang up her daughter and asked for help.","zh":"她给女儿打电话请求帮助。"}]},{"phrase":"be glad to do something","usage":"表示很高兴做某事","examples":[{"en":"The old lady was glad to be back at the block of flats.","zh":"老太太很高兴回到她住的公寓。"}]},{"phrase":"grow + adjective","usage":"表示逐渐变得...","examples":[{"en":"Her basket had grown heavier with every step.","zh":"她的篮子每走一步就重一些。"}]},{"phrase":"as clear as daylight","usage":"比喻某事非常清楚、显而易见","examples":[{"en":"It was as clear as daylight that burglars had forced an entry.","zh":"显而易见，窃贼强行闯入了。"}]}],"grammar":[{"title":"过去完成时 (Past Perfect Tense)","definition":"表示在过去某一时刻之前已经完成的动作，常用于描述过去的背景或先发生的事件","structure":"had + 过去分词","usage":"当需要表达'过去的过去'这一概念时使用，常与when, after, before等连用，或用于宾语从句中","examples":[{"en":"She had gone shopping after the home help had left.","zh":"她在管家离开后才去购物。"},{"en":"She had shut them before going out.","zh":"她在出门前把门都关上了。"},{"en":"The burglars must have been disturbed.","zh":"窃贼一定是被打扰了。"}]},{"title":"过去进行时 (Past Continuous Tense)","definition":"表示在过去某一时刻正在进行的动作，或用来描述过去的背景","structure":"was/were + 动词-ing","usage":"常用于描述故事发生的背景，或与when/while等连用表示两个同时进行的动作","examples":[{"en":"Her thoughts were on lunch and a good rest.","zh":"她满脑子想的都是午餐和好好休息。"},{"en":"She was thinking that she must reprimand her home help.","zh":"她正想着第二天早上一定要责备她的管家。"}]},{"title":"must have + 过去分词","definition":"表示对过去发生的事情的推测，意为'一定/肯定做过某事'","structure":"must have + 过去分词","usage":"用于根据现有证据或情况对过去事件进行肯定性的推测","examples":[{"en":"They must have been disturbed.","zh":"他们一定是被打扰了。"},{"en":"She must reprimand her home help.","zh":"她必须责备她的管家。"}]}],"patterns":[{"pattern":"主语 + be glad to + 动词原形","explanation":"","original":{"en":"The old lady was glad to be back at the block of flats.","zh":"老太太很高兴回到她住的公寓。"},"examples":[{"en":"I was glad to see my old friends again.","zh":"我很高兴再次见到我的老朋友们。"},{"en":"She was glad to finish her work on time.","zh":"她很高兴按时完成了工作。"}]},{"pattern":"主语 + be/feel + 形容词 + to + 动词原形","explanation":"","original":{"en":"At her age it might be more prudent to have someone with her.","zh":"在她这个年纪，有人陪着可能更明智。"},"examples":[{"en":"It might be better to wait for the police.","zh":"等待警察可能更好。"},{"en":"It is wise to check everything carefully.","zh":"仔细检查一切是明智的。"}]},{"pattern":"It is + 形容词 + that...","explanation":"","original":{"en":"It was as clear as daylight that burglars had forced an entry.","zh":"显而易见，窃贼强行闯入了。"},"examples":[{"en":"It is obvious that she has been robbed.","zh":"很明显她被抢劫了。"},{"en":"It is certain that he will come tomorrow.","zh":"他明天一定会来。"}]},{"pattern":"主语 + had + 过去分词 + before + doing something","explanation":"","original":{"en":"She had shut them before going out.","zh":"她在出门前把门都关上了。"},"examples":[{"en":"He had finished his homework before watching TV.","zh":"他在看电视前已经完成了作业。"},{"en":"I had locked the door before leaving.","zh":"我离开前已经锁好了门。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“打扰；打扰” 对应的单词是？","hint":"verb · /dɪˈstɜːb/","options":["resolution","idyllic","stuffy","disturb"],"answer":3,"explain":"disturb · /dɪˈstɜːb/ · verb · 打扰；打扰。指打断某人的活动或使某人担忧","source":{"kind":"vocab","word":"disturb"},"id":"b3-u58-q01"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：_____, it might be more prudent to have someone with her.","hint":"在她这个年纪，有人陪着可能更明智。","answer":"at her age","placeholder":"输入缺失的短语","explain":"at her age：表示在某人这个年纪，常用于表达某种行为是否适合某人的年龄（在她这个年纪，有人陪着可能更明智。）","source":{"kind":"phrase","phrase":"at her age"},"id":"b3-u58-q02"},{"type":"cloze","kind":"text","prompt":"补全句子：Her first impulse was to go round all the rooms looking for the _____","hint":"她最初的冲动是把所有房间都找一遍，看看有没有小偷，","answer":"thieves","placeholder":"输入缺失的单词","explain":"Her first impulse was to go round all the rooms looking for the thieves, — 她最初的冲动是把所有房间都找一遍，看看有没有小偷，","source":{"kind":"sentence","en":"Her first impulse was to go round all the rooms looking for the thieves,"},"id":"b3-u58-q03"},{"type":"grammar-choice","kind":"choice","prompt":"“表示在过去某一时刻之前已经完成的动作，常用于描述过去的背景或先发生的事件” 描述的是哪个语法点？","hint":"had + 过去分词","options":["such...that... 结果状语从句","even though/even if引导的让步状语从句","过去完成时 (Past Perfect Tense)","一般现在时表客观事实和普遍规律"],"answer":2,"explain":"过去完成时 (Past Perfect Tense)：had + 过去分词：当需要表达'过去的过去'这一概念时使用，常与when, after, before等连用，或用于宾语从句中","source":{"kind":"grammar","title":"过去完成时 (Past Perfect Tense)"},"id":"b3-u58-q04"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThen, her composure regained, she was ready to set off with the porter's assistance to search for any intruders who might still be lurking in her flat.","hint":"","options":["一年多过去了，才有人首次尝试。","当拉姆齐夫人告诉警察她所做的一切时，警察都惊呆了。","恢复镇定后，她在看门人的协助下准备出发，搜寻可能仍藏在她公寓里的不速之客。","白天她把它拴在田野里的一棵树上，每天傍晚都去把它牵回来。"],"answer":2,"explain":"Then, her composure regained, she was ready to set off with the porter's assistance to search for any intruders who might still be lurking in her flat. — 恢复镇定后，她在看门人的协助下准备出发，搜寻可能仍藏在她公寓里的不速之客。","source":{"kind":"sentence","en":"Then, her composure regained, she was ready to set off with the porter's assistance to search for any intruders who might still be lurking in her flat."},"id":"b3-u58-q05"},{"type":"dictation","kind":"text","prompt":"听写：点击播放，写出你听到的句子。","hint":"共 9 个单词","answer":"The old lady thought he was a fussy creature,","placeholder":"输入完整英文句子","explain":"The old lady thought he was a fussy creature, — 老太太觉得他是个爱挑剔的人，","playText":"The old lady thought he was a fussy creature,","source":{"kind":"sentence","en":"The old lady thought he was a fussy creature,"},"id":"b3-u58-q06"}]},{"id":"b3-u59","book":3,"unit":59,"key":"59","lessonFrom":59,"lessonTo":59,"title":"Collecting","titleZh":"收藏","question":"What in particular does a person gain when he or she becomes a serious collector?","sentences":[{"en":"People tend to amass possessions, sometimes without being aware of doing so.","zh":"人们倾向于积累财产，有时甚至没有意识到自己在这样做。","t":17.12},{"en":"Indeed they can have a delightful surprise when they find something useful which they did not know they owned.","zh":"事实上，当他们发现一些自己并不知道拥有的有用物品时，他们会感到惊喜。","t":22.96},{"en":"Those who never have to move house become indiscriminate collectors of what can only be described as clutter.","zh":"那些从不搬家的人成了不加选择的收藏者，而他们的收藏只能被称为杂物。","t":30.68},{"en":"They leave unwanted objects in drawers, cupboards and attics for years, in the belief that they may one day need just those very things.","zh":"他们把不用的东西放在抽屉、碗柜和阁楼上好多年，相信总有一天会用上这些东西。","t":38.27},{"en":"As they grow old, people also accumulate belongings for two other reasons,","zh":"随着年龄的增长，人们还因为另外两个原因而积累物品：","t":48.4},{"en":"lack of physical and mental energy, both of which are essential in turning out and throwing away, and sentiment.","zh":"缺少清理和扔掉东西所必需的体力和精力，以及情感因素。","t":54.85},{"en":"Things owned for a long time are full of associations with the past,","zh":"拥有了很久的东西，充满了与过去的联系，","t":63.55},{"en":"perhaps with relatives who are dead, and so they gradually acquire a value beyond their true worth.","zh":"也许与已故的亲人有关，因此它们逐渐获得超出其真实价值的价值。","t":68.41},{"en":"Some things are collected deliberately in the home in an attempt to avoid waste.","zh":"有些东西是人们为了避免浪费而特意在家中收藏的。","t":76.11},{"en":"Among these I would list string and brown paper,","zh":"在这些东西中，我会列举麻线和牛皮纸，","t":81.49},{"en":"kept by thrifty people when a parcel has been opened, to save buying these two requisites.","zh":"节俭的人在包裹拆开后会把它们留下，以节省购买这两种必需品的钱。","t":84.5},{"en":"Collecting small items can easily become a mania.","zh":"收集小物品很容易变成一种癖好。","t":91.45},{"en":"I know someone who always cuts sketches out from newspapers of model clothes that she would like to buy if she had the money.","zh":"我认识一个人，她总是从报纸上剪下她有钱就想买的服装款式图。","t":95.57},{"en":"As she is not rich, the chances that she will ever be able to afford such purchases are remote;","zh":"由于她不富裕，她将来能买得起这些东西的可能性很小；","t":103.88},{"en":"but she is never sufficiently strongminded to be able to stop the practice.","zh":"但她从没有足够的毅力来停止这种做法。","t":111.93},{"en":"It is a harmless habit, but it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction.","zh":"这是一种无害的习惯，但它把她的书桌弄得一团糟，以至于她每次打开书桌，散乱的纸片都会四处掉落。","t":117.24},{"en":"Collecting as a serious hobby is quite different and has many advantages.","zh":"作为一种严肃的爱好，收藏就完全不同了，它有很多优点。","t":129.31},{"en":"It provides relaxation for leisure hours, as just looking at one's treasures is always a joy.","zh":"它为闲暇时间提供了放松，因为仅仅看着自己的珍藏就是一种乐趣。","t":135.15},{"en":"One does not have to go outside for amusement, since the collection is housed at home.","zh":"人不必外出寻找乐趣，因为藏品就放在家里。","t":142.72},{"en":"Whatever it consists of, stamps, records, first editions of books, china, glass,","zh":"无论是邮票、唱片、书籍初版、瓷器、玻璃制品、","t":148.8},{"en":"antique furniture, pictures, model cars, stuffed birds, toy animals, there is always something to do in connection with it,","zh":"古董家具、画作、模型汽车、填充鸟类、玩具动物，总有与它相关的事情可做，","t":157.08},{"en":"from finding the right place for the latest addition, to verifying facts in reference books.","zh":"从为最新藏品找到合适的位置，到在参考书中核实事实。","t":167.44},{"en":"This hobby educates one not only in the chosen subject, but also in general matters which have some bearing on it.","zh":"这种爱好不仅能让人们在所选的领域受到教育，还能在与此相关的一般事务上学到知识。","t":173.67},{"en":"There are also other benefits.","zh":"还有其他好处。","t":182.06},{"en":"One wants to meet like-minded collectors, to get advice, to compare notes, to exchange articles, to show off the latest find.","zh":"人们会想结识志同道合的收藏家，以获取建议、交流心得、交换物品、炫耀最新的发现。","t":184.94},{"en":"So one's circle of friends grows.","zh":"这样一来，朋友圈子就扩大了。","t":194.33},{"en":"Soon the hobby leads to travel, perhaps to a meeting in another town,","zh":"很快，这项爱好就会带来旅行，也许是去另一个城市参加会议，","t":197.07},{"en":"possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country.","zh":"也可能是出国旅行寻找稀有标本，因为收藏家并不局限于某个国家。","t":202.5},{"en":"Over the years, one may well become an authority on one's hobby and will very probably be asked to give informal talks to little gatherings","zh":"多年以后，人们很可能成为自己爱好领域的权威人士，并且很可能会被邀请在小型聚会上做非正式的演讲，","t":210.33},{"en":"and then, if successful, to larger audiences.","zh":"然后，如果成功，还会面向更多的听众。","t":220.08},{"en":"In this way self-confidence grows, first from mastering a subject, then from being able to talk about it.","zh":"这样，自信心就会增长，首先是掌握了一门学科，然后是能够谈论它。","t":224.84},{"en":"Collecting, by occupying spare time so constructively, makes a person contented, with no time for boredom.","zh":"收藏，通过如此建设性地占据了业余时间，使人感到满足，没有时间感到无聊。","t":233.93}],"vocab":[{"word":"amass","phonetic":"/əˈmæs/","meanings":[{"pos":"verb","meaning":"积聚，积累","usage":"指大量收集或积聚财物、信息等"}]},{"word":"possession","phonetic":"/pəˈzeʃən/","meanings":[{"pos":"noun","meaning":"财产，所有物","usage":"指个人拥有的物品，常用复数形式"}]},{"word":"indiscriminate","phonetic":"/ˌɪndɪˈskrɪmɪnət/","meanings":[{"pos":"adj","meaning":"不加选择的，漫不经心的","usage":"形容不加区分地收集或对待事物"}]},{"word":"clutter","phonetic":"/ˈklʌtər/","meanings":[{"pos":"noun","meaning":"杂物，零乱的东西","usage":"指杂乱无章的物品堆放"},{"pos":"verb","meaning":"使凌乱，塞满","usage":"常用clutter up结构"}]},{"word":"sentiment","phonetic":"/ˈsentɪmənt/","meanings":[{"pos":"noun","meaning":"情感，感伤；情绪","usage":"指对事物的感伤情绪或情感因素"}]},{"word":"thrifty","phonetic":"/ˈθrɪfti/","meanings":[{"pos":"adj","meaning":"节俭的，节约的","usage":"形容善于节省金钱或资源的人"}]},{"word":"requisite","phonetic":"/ˈrekwɪzɪt/","meanings":[{"pos":"noun","meaning":"必需品，必要条件","usage":"指做某事所必需的东西"}]},{"word":"mania","phonetic":"/ˈmeɪniə/","meanings":[{"pos":"noun","meaning":"狂热，癖好；狂躁","usage":"指对某事的极度热爱或沉迷"}]},{"word":"sketch","phonetic":"/sketʃ/","meanings":[{"pos":"noun","meaning":"草图，素描；速写","usage":"指简短的绘画或文字描述"},{"pos":"verb","meaning":"绘草图，概述","usage":"cut out sketches表示剪下图片"}]},{"word":"relaxation","phonetic":"/ˌriːlækˈseɪʃən/","meanings":[{"pos":"noun","meaning":"放松，休息；消遣","usage":"指休闲娱乐活动或放松状态"}]},{"word":"treasure","phonetic":"/ˈtreʒər/","meanings":[{"pos":"noun","meaning":"珍宝，财富；珍藏品","usage":"指珍视的收藏品或贵重物品"}]},{"word":"verify","phonetic":"/ˈverɪfaɪ/","meanings":[{"pos":"verb","meaning":"证实，核实；验证","usage":"指通过查证来确认信息的准确性"}]},{"word":"specimen","phonetic":"/ˈspesɪmən/","meanings":[{"pos":"noun","meaning":"标本，样本；范例","usage":"指用于展示或研究的典型例子"}]},{"word":"contented","phonetic":"/kənˈtentɪd/","meanings":[{"pos":"adj","meaning":"满足的，满意的","usage":"指对现状感到满意的状态"}]},{"word":"bore","phonetic":"/bɔːr/","meanings":[{"pos":"verb","meaning":"使厌烦，使无聊","usage":"指让人感到无聊或厌烦"},{"pos":"noun","meaning":"令人厌烦的人或事物","usage":"boredom是名词形式，表示厌烦的状态"}]}],"phrases":[{"phrase":"tend to","usage":"倾向于，易于，往往会","examples":[{"en":"People tend to amass possessions, sometimes without being aware of doing so.","zh":"人们往往会积聚财产，有时甚至没有意识到自己在这样做。"}]},{"phrase":"turn out","usage":"结果是，证明是；关掉","examples":[{"en":"Both physical and mental energy are essential in turning out and throwing away.","zh":"体力和脑力对于清理和扔掉东西都是必不可少的。"}]},{"phrase":"cut out","usage":"剪下，裁剪出；停止","examples":[{"en":"I know someone who always cuts sketches out from newspapers.","zh":"我认识一个人，她总是从报纸上剪下时装图样。"}]},{"phrase":"litter up","usage":"使凌乱，塞满","examples":[{"en":"It is a harmless habit, but it litters up her desk to such an extent.","zh":"这是个无害的习惯，但它把她的桌子弄得乱七八糟。"}]},{"phrase":"in connection with","usage":"关于，与...有关","examples":[{"en":"There is always something to do in connection with it.","zh":"与此相关的总有事情可做。"}]},{"phrase":"have some bearing on","usage":"与...有关联，对...有影响","examples":[{"en":"This hobby educates one not only in the chosen subject, but also in general matters which have some bearing on it.","zh":"这种爱好不仅使人对自己选择的主题有所了解，而且还能使人了解与之相关的一般性知识。"}]},{"phrase":"compare notes","usage":"交换意见，交流心得","examples":[{"en":"One wants to meet like-minded collectors, to get advice, to compare notes.","zh":"人们想遇到志趣相投的收藏家，获取建议，交流心得。"}]},{"phrase":"show off","usage":"炫耀，显示，卖弄","examples":[{"en":"One wants to meet like-minded collectors, to compare notes, to exchange articles, to show off the latest find.","zh":"人们想遇到志趣相投的收藏家，交流心得，交换物品，展示最新发现。"}]},{"phrase":"in search of","usage":"寻找，搜寻","examples":[{"en":"Perhaps a trip abroad in search of a rare specimen.","zh":"或许还会出国寻找珍稀标本。"}]},{"phrase":"over the years","usage":"多年来，随着时间的推移","examples":[{"en":"Over the years, one may well become an authority on one's hobby.","zh":"多年下来，人很可能会成为自己爱好的权威。"}]}],"grammar":[{"title":"What引导的特殊疑问句","definition":"What引导的特殊疑问句用于询问具体的信息，回答不是简单的yes或no","structure":"What + 助动词 + 主语 + 动词...? / What in particular + 助动词 + 主语 + 动词...?","usage":"what in particular用于强调询问具体的方面或细节，相当于specifically或particularly","examples":[{"en":"What in particular does a person gain when he or she becomes a serious collector?","zh":"当一个人成为一个认真的收藏家时，他或她究竟会得到什么？"},{"en":"What do you usually collect?","zh":"你通常收集什么？"}]},{"title":"As引导的时间状语从句","definition":"As引导的时间状语从句，表示'随着'或'当...时候'，主句和从句的动作同时发生","structure":"As + 主语 + 动词..., 主语 + 动词...","usage":"as表示时间的流逝或情况的改变，常与表示变化的动词连用，如grow old, change等","examples":[{"en":"As they grow old, people also accumulate belongings for two other reasons.","zh":"随着人们年龄的增长，他们还因为另外两个原因积攒东西。"},{"en":"As time goes by, his collection grows larger.","zh":"随着时间的推移，他的收藏越来越大。"}]},{"title":"But连接的并列句","definition":"but作为并列连词连接两个意义相反或对照的并列分句","structure":"主句 + , but + 并列句","usage":"but连接的句子强调前后意思的转折或对比，前面不用句号而用逗号","examples":[{"en":"It is a harmless habit, but it litters up her desk to such an extent.","zh":"这是个无害的习惯，但它把她的桌子弄得乱七八糟。"},{"en":"She would like to buy them if she had the money, but she is not rich.","zh":"如果她有钱的话她想买这些衣服，但她不富有。"}]}],"patterns":[{"pattern":"What + 助动词 + 主语 + gain/benefit + when...?","explanation":"","original":{"en":"What in particular does a person gain when he or she becomes a serious collector?","zh":"当一个人成为一个认真的收藏家时，他或她究竟会得到什么？"},"examples":[{"en":"What in particular does one learn when taking up a new hobby?","zh":"当一个人开始一个新的爱好时，他究竟会学到什么？"},{"en":"What in particular do people feel when they retire?","zh":"当人们退休时，他们究竟会有什么感受？"}]},{"pattern":"People/主语 + tend to + 动词原形","explanation":"","original":{"en":"People tend to amass possessions, sometimes without being aware of doing so.","zh":"人们往往会积聚财产，有时甚至没有意识到自己在这样做。"},"examples":[{"en":"Students tend to put off their assignments until the last minute.","zh":"学生们往往会拖延作业直到最后一刻。"},{"en":"Children tend to be more curious about the world around them.","zh":"孩子们往往对周围的世界更加好奇。"}]},{"pattern":"As + 主语 + 动词, 主语 + 动词...","explanation":"","original":{"en":"As they grow old, people also accumulate belongings for two other reasons.","zh":"随着人们年龄的增长，他们还因为另外两个原因积攒东西。"},"examples":[{"en":"As she became more experienced, she started to travel alone.","zh":"随着她变得越来越有经验，她开始独自旅行。"},{"en":"As technology advances, our lives become more convenient.","zh":"随着技术的进步，我们的生活变得更加便利。"}]},{"pattern":"There is always something to + 动词","explanation":"","original":{"en":"There is always something to do in connection with it.","zh":"与此相关的总有事情可做。"},"examples":[{"en":"There is always something to learn from every experience.","zh":"从每一次经历中总有东西可学。"},{"en":"There is always something to improve in our work.","zh":"在我们的工作中总有可以改进的地方。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“标本，样本；范例” 对应的单词是？","hint":"noun · /ˈspesɪmən/","options":["specimen","attempt","smash-and-grab","glance"],"answer":0,"explain":"specimen · /ˈspesɪmən/ · noun · 标本，样本；范例。指用于展示或研究的典型例子","source":{"kind":"vocab","word":"specimen"},"id":"b3-u59-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：使厌烦，使无聊","hint":"/bɔːr/ · verb","answer":"bore","placeholder":"输入英文单词","explain":"bore · /bɔːr/ · verb · 使厌烦，使无聊。指让人感到无聊或厌烦","source":{"kind":"vocab","word":"bore"},"id":"b3-u59-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：This hobby educates one not only in the chosen subject, but also in general matters which _____ it.","hint":"这种爱好不仅使人对自己选择的主题有所了解，而且还能使人了解与之相关的一般性知识。","answer":"have some bearing on","placeholder":"输入缺失的短语","explain":"have some bearing on：与...有关联，对...有影响（这种爱好不仅使人对自己选择的主题有所了解，而且还能使人了解与之相关的一般性知识。）","source":{"kind":"phrase","phrase":"have some bearing on"},"id":"b3-u59-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：possibly a _____ abroad in search of a rare specimen, for collectors are not confined to any one country.","hint":"也可能是出国旅行寻找稀有标本，因为收藏家并不局限于某个国家。","answer":"trip","placeholder":"输入缺失的单词","explain":"possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country. — 也可能是出国旅行寻找稀有标本，因为收藏家并不局限于某个国家。","source":{"kind":"sentence","en":"possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country."},"id":"b3-u59-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“as表示时间的流逝或情况的改变，常与表示变化的动词连用，如grow old, change等” 描述的是哪个语法点？","hint":"As + 主语 + 动词..., 主语 + 动词...","options":["even though/even if引导的让步状语从句","否定副词开头的倒装句 (Inversion with Negative Adverbs)","As引导的时间状语从句","一般过去时 (Simple Past Tense)"],"answer":2,"explain":"As引导的时间状语从句：As + 主语 + 动词..., 主语 + 动词...：as表示时间的流逝或情况的改变，常与表示变化的动词连用，如grow old, change等","source":{"kind":"grammar","title":"As引导的时间状语从句"},"id":"b3-u59-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nAmong these I would list string and brown paper,","hint":"","options":["任何人类的努力或思想都不会因此而保持不变。”","在这些东西中，我会列举麻线和牛皮纸，","但论速度和舒适度，没有任何交通工具能与它们相比。","我们确信迟早会有石子把我们的油箱撕开一个洞或者损坏发动机。"],"answer":1,"explain":"Among these I would list string and brown paper, — 在这些东西中，我会列举麻线和牛皮纸，","source":{"kind":"sentence","en":"Among these I would list string and brown paper,"},"id":"b3-u59-q06"}]},{"id":"b3-u60","book":3,"unit":60,"key":"60","lessonFrom":60,"lessonTo":60,"title":"Too Early and Too Late","titleZh":"为时过早和为时过晚","question":"Why did the young girl miss the train?","sentences":[{"en":"Punctuality is a necessary habit in all public affairs in civilized society.","zh":"在文明社会中，准时是处理一切公共事务的必要习惯。","t":15.76},{"en":"Without it, nothing could ever be brought to a conclusion; everything would be in a state of chaos.","zh":"没有它，任何事情都无法成功；一切都将处于混乱之中。","t":23.31},{"en":"Only in a sparsely-populated rural community is it possible to disregard it.","zh":"只有在人口稀少的乡村社区，才有可能忽视它。","t":31.53},{"en":"In ordinary living, there can be some tolerance of unpunctuality.","zh":"在日常生活中，对不准时可以有一些宽容。","t":38.44},{"en":"The intellectual, who is working on some abstruse problem, has everything coordinated and organized for the matter in hand.","zh":"正在研究某个深奥问题的知识分子，会把手头的一切事物都协调组织好。","t":44.04},{"en":"He is therefore forgiven if late for a dinner party.","zh":"因此，如果他赴晚宴迟到了，是可以被原谅的。","t":53.53},{"en":"But people are often reproached for unpunctuality when their only fault is cutting things fine.","zh":"但人们常常因为不准时而受到指责，尽管他们唯一的过错只是把时间安排得太紧凑。","t":58.07},{"en":"It is hard for energetic, quick-minded people to waste time,","zh":"对于精力充沛、头脑敏捷的人来说，浪费时间是很难的，","t":65.63},{"en":"so they are often tempted to finish a job before setting out to keep an appointment.","zh":"所以他们常常想在赴约之前完成一项工作。","t":70.47},{"en":"If no accidents occur on the way, like punctured tyres, diversions of traffic, sudden descent of fog, they will be on time.","zh":"如果路上没有发生意外，比如爆胎、交通改道、突如其来的大雾，他们就会准时到达。","t":76.25},{"en":"They are often more industrious, useful citizens than those who are never late.","zh":"他们往往比那些从不迟到的人更勤劳、更有用。","t":85.88},{"en":"The over-punctual can be as much a trial to others as the unpunctual.","zh":"过分准时的人和不准时的人一样，都会给别人带来麻烦。","t":92.04},{"en":"The guest who arrives half an hour too soon is the greatest nuisance.","zh":"提前半小时到达的客人是最让人讨厌的。","t":98.12},{"en":"Some friends of my family had this irritating habit.","zh":"我家里有些朋友就有这种令人恼火的习惯。","t":104.56},{"en":"The only thing to do was ask them to come half an hour later than the other guests.","zh":"唯一的办法就是请他们比其他客人晚半小时来。","t":108.32},{"en":"Then they arrived just when we wanted them.","zh":"这样他们就能在我们想要的时候到达。","t":114.09},{"en":"If you are catching a train, it is always better to be comfortably early than even a fraction of a minute too late.","zh":"如果你要赶火车，最好是提前充足时间，而不是哪怕晚一分钟。","t":117.69},{"en":"Although being early may mean wasting a little time,","zh":"尽管提前到达可能会浪费一点时间，","t":125.97},{"en":"this will be less than if you miss the train and have to wait an hour or more for the next one;","zh":"但这比你错过火车，不得不等一个多小时才能搭乘下一班车要好；","t":129.57},{"en":"and you avoid the frustration of arriving at the very moment when the train is drawing out of the station and being unable to get on it.","zh":"而且你还能避免那种火车正驶出车站而你却无法上车的沮丧。","t":135.48},{"en":"An even harder situation is to be on the platform in good time for a train and still to see it go off without you.","zh":"更令人恼火的情况是，你准时到了站台，却眼睁睁看着火车没有你开走。","t":146.35},{"en":"Such an experience befell a certain young girl the first time she was travelling alone.","zh":"这样的经历就发生在一个年轻女孩身上，那是她第一次独自旅行。","t":156.02},{"en":"She entered the station twenty minutes before the train was due,","zh":"她在火车到站前20分钟就进了车站，","t":162.72},{"en":"since her parents had impressed upon her","zh":"因为她的父母曾告诫她","t":167.2},{"en":"that it would be unforgivable to miss it and cause the friends with whom she was going to stay to make two journeys to meet her.","zh":"错过火车是不可原谅的，那会让她要去拜访的朋友来接她两次。","t":169.96},{"en":"She gave her luggage to a porter and showed him her ticket.","zh":"她把行李交给一个搬运工，并给他看了她的车票。","t":179.32},{"en":"To her horror he said that she was two hours too soon.","zh":"让她吃惊的是，他说她早来了两个小时。","t":183.92},{"en":"She felt in her handbag for the piece of paper on which her father had written down all the details of the journey and gave it to the porter.","zh":"她从手提包里摸索出父亲写下所有旅行细节的纸条，交给了搬运工。","t":189.16},{"en":"He agreed that a train did come into the station at the time on the paper and that it did stop, but only to take on mail, not passengers.","zh":"他承认火车确实在纸上写的时间到达车站，也确实停靠了，但那只是为了装载邮件，而不是载客。","t":198.85},{"en":"The girl asked to see a timetable, feeling sure that her father could not have made such a mistake.","zh":"女孩要求看时刻表，她确信她父亲不可能犯这样的错误。","t":210.9},{"en":"The porter went to fetch one and arrived back with the station master,","zh":"搬运工去拿时刻表，回来时带着站长，","t":218.29},{"en":"who produced it with a flourish and pointed out a microscopic 'o' beside the time of the arrival of the train at his station;","zh":"站长得意地拿出时刻表，指出了他们车站火车到站时间旁边的一个微小的“o”；","t":223.19},{"en":"this little 'o' indicated that the train only stopped for mail.","zh":"这个小小的“o”表示火车只停靠装载邮件。","t":233.04},{"en":"Just as that moment the train came into the station.","zh":"就在那时，火车进站了。","t":238.86},{"en":"The girl, tears streaming down her face, begged to be allowed to slip into the guard's van.","zh":"女孩泪流满面，乞求允许她溜进守车。","t":243.59},{"en":"But the station master was adamant: rules could not be broken.","zh":"但站长态度坚决：规则不能打破。","t":250.78},{"en":"And she had to watch that train disappear towards her destination while she was left behind.","zh":"她不得不眼睁睁看着那列火车开往目的地，而她却被留在了原地。","t":257.08}],"vocab":[{"word":"punctuality","phonetic":"/ˌpʌŋktʃuˈæləti/","meanings":[{"pos":"noun","meaning":"准时；守时","usage":"指按时到达或完成某事的习惯"},{"pos":"noun","meaning":"准时性","usage":"强调时间观念的重要性"}]},{"word":"civilized","phonetic":"/ˈsɪvəlaɪzd/","meanings":[{"pos":"adj","meaning":"文明的；有教养的","usage":"形容社会或个人具有良好行为规范"},{"pos":"adj","meaning":"开化的","usage":"指社会发展到较高阶段"}]},{"word":"tolerance","phonetic":"/ˈtɒlərəns/","meanings":[{"pos":"noun","meaning":"宽容；容忍","usage":"指对不同意见或行为的宽恕态度"},{"pos":"noun","meaning":"忍耐力","usage":"指对困难或不适的承受程度"}]},{"word":"abstruse","phonetic":"/æbˈstruːs/","meanings":[{"pos":"adj","meaning":"难懂的；深奥的","usage":"形容复杂难理解的事物，常用于学术或科学问题"}]},{"word":"reproach","phonetic":"/rɪˈprəʊtʃ/","meanings":[{"pos":"verb","meaning":"责备；批评","usage":"指对某人表示不满或指责"},{"pos":"noun","meaning":"责备；羞耻","usage":"指责备的话语或状态"}]},{"word":"industrious","phonetic":"/ɪnˈdʌstriəs/","meanings":[{"pos":"adj","meaning":"勤奋的；勤劳的","usage":"形容工作努力、认真的人"}]},{"word":"nuisance","phonetic":"/ˈnjuːsəns/","meanings":[{"pos":"noun","meaning":"令人讨厌的人/事物","usage":"指造成麻烦或不便的人或事"},{"pos":"noun","meaning":"损害；妨害","usage":"法律用语中指侵害行为"}]},{"word":"fraction","phonetic":"/ˈfrækʃən/","meanings":[{"pos":"noun","meaning":"小部分；少量","usage":"指整体中的一小部分"},{"pos":"noun","meaning":"分数","usage":"数学术语"}]},{"word":"luggage","phonetic":"/ˈlʌɡɪdʒ/","meanings":[{"pos":"noun","meaning":"行李","usage":"指旅行时携带的箱包等物品"}]},{"word":"flourish","phonetic":"/ˈflʌrɪʃ/","meanings":[{"pos":"noun","meaning":"夸张的动作；挥舞","usage":"指引人注意的戏剧性动作"},{"pos":"verb","meaning":"繁荣；兴旺","usage":"指事物发展繁荣"}]},{"word":"microscopic","phonetic":"/ˌmaɪkrəˈskɒpɪk/","meanings":[{"pos":"adj","meaning":"极小的；微小的","usage":"形容非常小以至于难以察觉的事物"}]},{"word":"destination","phonetic":"/ˌdestɪˈneɪʃən/","meanings":[{"pos":"noun","meaning":"目的地；终点","usage":"指旅行或运输的最终目的地"}]},{"word":"impress","phonetic":"/ɪmˈpres/","meanings":[{"pos":"verb","meaning":"使印象深刻；使铭记","usage":"强调某事在某人心中的深刻印象"},{"pos":"verb","meaning":"印；压印","usage":"本意，指在表面上压出图案"}]},{"word":"porter","phonetic":"/ˈpɔːtə/","meanings":[{"pos":"noun","meaning":"搬运工；行李员","usage":"指在车站、机场等帮人搬行李的人"}]},{"word":"adament","phonetic":"/ˈædəmənt/","meanings":[{"pos":"adj","meaning":"坚决的；固执的","usage":"形容态度坚决，不愿改变主意"}]}],"phrases":[{"phrase":"bring to a conclusion","usage":"使结束；得出结论，指完成某事或做出决定","examples":[{"en":"Only in this way can we bring the matter to a conclusion.","zh":"只有这样我们才能结束这件事。"}]},{"phrase":"in a state of chaos","usage":"处于混乱状态，形容无秩序、混乱的局面","examples":[{"en":"Without rules, everything would be in a state of chaos.","zh":"没有规则，一切都会陷入混乱。"}]},{"phrase":"cut things fine","usage":"把时间扣得很紧，指在最后时刻才完成任务或到达","examples":[{"en":"He always cuts things fine when catching trains.","zh":"他赶火车时总是把时间扣得很紧。"}]},{"phrase":"set out","usage":"出发；动身，指开始旅程或着手做某事","examples":[{"en":"They set out for the station early in the morning.","zh":"他们一大早就出发去车站了。"}]},{"phrase":"impress upon","usage":"使深刻印象；叮嘱，强调某事的重要性让某人记住","examples":[{"en":"Her parents impressed upon her that punctuality was important.","zh":"她的父母让她深刻记住准时的重要性。"}]},{"phrase":"point out","usage":"指出；指明，用于提示或解释某事","examples":[{"en":"The station master pointed out the mistake on the timetable.","zh":"站长指出时刻表上的错误。"}]},{"phrase":"slip into","usage":"溜进；悄悄进入，指不引人注意地进入某处","examples":[{"en":"She tried to slip into the train before it left.","zh":"她试图在火车开走前溜进去。"}]},{"phrase":"to her horror","usage":"使她恐惧的是，用于引出令人害怕或震惊的情况","examples":[{"en":"To her horror, the train had already left.","zh":"使她恐惧的是，火车已经开走了。"}]},{"phrase":"as much...as","usage":"和...一样（用于比较），强调两者在某方面程度相同","examples":[{"en":"The over-punctual can be as much a trial as the unpunctual.","zh":"过于准时的人和不准时的人一样让人头疼。"}]},{"phrase":"be unforgivable","usage":"不可原谅的，指错误严重到无法被原谅","examples":[{"en":"It would be unforgivable to miss the train.","zh":"错过这班火车将是不可原谅的。"}]}],"grammar":[{"title":"条件句 (If引导的真实条件句)","definition":"表示真实可能发生的情况，使用if引导的条件状语从句","structure":"If + 一般现在时, 主语 + will/won't + 动词原形","usage":"用于讨论可能发生的真实情况，提出假设或条件","examples":[{"en":"If no accidents occur on the way, they will be on time.","zh":"如果路上没有事故，他们会准时到达。"},{"en":"If you are catching a train, it is better to be early.","zh":"如果你要赶火车，最好早一点。"}]},{"title":"Only + 状语 置于句首的倒装","definition":"当only置于句首修饰状语时，句子需要部分倒装","structure":"Only + 状语 + be/助动词/情态动词 + 主语 + 其他","usage":"强调条件或方式，突出唯一性","examples":[{"en":"Only in a sparsely-populated rural community is it possible to disregard punctuality.","zh":"只有在人口稀少的农村社区才可能忽视守时。"},{"en":"Only then did she realize her mistake.","zh":"直到那时她才意识到自己的错误。"}]},{"title":"too...to... 结构","definition":"表示太...以至于不能...，too后接形容词，to后接动词原形","structure":"too + 形容词/副词 + (for sb.) + to do sth.","usage":"表达程度过高导致不可能实现的情况","examples":[{"en":"She was two hours too early.","zh":"她早了两个小时。"},{"en":"It is too difficult for a child to understand.","zh":"这对一个孩子来说太难理解了。"}]}],"patterns":[{"pattern":"It is + adj. + for sb. + to do sth.","explanation":"","original":{"en":"It is hard for energetic, quick-minded people to waste time.","zh":"对于精力充沛、思维敏捷的人来说，浪费时间是很困难的。"},"examples":[{"en":"It is necessary for us to be punctual.","zh":"对我们来说守时是必要的。"},{"en":"It is important for students to practice English every day.","zh":"对学生来说每天练习英语是重要的。"}]},{"pattern":"Only in + 地点/时间 + is it possible to...","explanation":"","original":{"en":"Only in a sparsely-populated rural community is it possible to disregard it.","zh":"只有在人口稀少的农村社区才可能忽视它。"},"examples":[{"en":"Only in this way can we solve the problem.","zh":"只有用这种方法我们才能解决问题。"},{"en":"Only in Beijing can you see such historical sites.","zh":"只有在北京你才能看到这样的历史遗迹。"}]},{"pattern":"The + adj. + can be as much...as...","explanation":"","original":{"en":"The over-punctual can be as much a trial to others as the unpunctual.","zh":"过于准时的人和不准时的人一样让人头疼。"},"examples":[{"en":"The rich can be as unhappy as the poor.","zh":"富人和穷人一样可能不快乐。"},{"en":"Being early can be as bad as being late.","zh":"来得太早和迟到一样糟糕。"}]},{"pattern":"It would be + 形容词 + to do sth.","explanation":"","original":{"en":"It would be unforgivable to miss it.","zh":"错过它将是不可原谅的。"},"examples":[{"en":"It would be foolish to give up now.","zh":"现在放弃是愚蠢的。"},{"en":"It would be wise to arrive early.","zh":"早点到是明智的。"}]}],"exercises":[{"type":"vocab-choice","kind":"choice","prompt":"“夸张的动作；挥舞” 对应的单词是？","hint":"noun · /ˈflʌrɪʃ/","options":["mete out","abstract","flourish","smash"],"answer":2,"explain":"flourish · /ˈflʌrɪʃ/ · noun · 夸张的动作；挥舞。指引人注意的戏剧性动作","source":{"kind":"vocab","word":"flourish"},"id":"b3-u60-q01"},{"type":"spell","kind":"text","prompt":"根据释义和音标拼写单词：极小的；微小的","hint":"/ˌmaɪkrəˈskɒpɪk/ · adj","answer":"microscopic","placeholder":"输入英文单词","explain":"microscopic · /ˌmaɪkrəˈskɒpɪk/ · adj · 极小的；微小的。形容非常小以至于难以察觉的事物","source":{"kind":"vocab","word":"microscopic"},"id":"b3-u60-q02"},{"type":"phrase-fill","kind":"text","prompt":"补全短语：It would _____ to miss the train.","hint":"错过这班火车将是不可原谅的。","answer":"be unforgivable","placeholder":"输入缺失的短语","explain":"be unforgivable：不可原谅的，指错误严重到无法被原谅（错过这班火车将是不可原谅的。）","source":{"kind":"phrase","phrase":"be unforgivable"},"id":"b3-u60-q03"},{"type":"cloze","kind":"text","prompt":"补全句子：If no accidents occur on the way, like punctured tyres, _____ of traffic, sudden descent of fog, they will be on time.","hint":"如果路上没有发生意外，比如爆胎、交通改道、突如其来的大雾，他们就会准时到达。","answer":"diversions","placeholder":"输入缺失的单词","explain":"If no accidents occur on the way, like punctured tyres, diversions of traffic, sudden descent of fog, they will be on time. — 如果路上没有发生意外，比如爆胎、交通改道、突如其来的大雾，他们就会准时到达。","source":{"kind":"sentence","en":"If no accidents occur on the way, like punctured tyres, diversions of traffic, sudden descent of fog, they will be on time."},"id":"b3-u60-q04"},{"type":"grammar-choice","kind":"choice","prompt":"“表示太...以至于不能...，too后接形容词，to后接动词原形” 描述的是哪个语法点？","hint":"too + 形容词/副词 + (for sb.) + to do sth.","options":["否定副词置于句首的倒装句","too...to... 结构","定语从句的分隔现象","either...or...并列连词结构"],"answer":1,"explain":"too...to... 结构：too + 形容词/副词 + (for sb.) + to do sth.：表达程度过高导致不可能实现的情况","source":{"kind":"grammar","title":"too...to... 结构"},"id":"b3-u60-q05"},{"type":"translation-choice","kind":"choice","prompt":"选出下面句子的正确中文意思：\nThe guest who arrives half an hour too soon is the greatest nuisance.","hint":"","options":["远处还能看到我们村教堂的尖顶。","他飞越海峡仅七英里，发动机就失灵了，被迫降落在海面上。","约翰那天生意很好，就把装有3000英镑的钱包放进了微波炉里，以求安全。","提前半小时到达的客人是最让人讨厌的。"],"answer":3,"explain":"The guest who arrives half an hour too soon is the greatest nuisance. — 提前半小时到达的客人是最让人讨厌的。","source":{"kind":"sentence","en":"The guest who arrives half an hour too soon is the greatest nuisance."},"id":"b3-u60-q06"}]}]};
